window.DECKS = [{"id":"physio-S1-2026","nom":"🫁 Physiologie","src":"Examen N2026","ordre":1,"module":"M113","desc":"40 QCM · respi 8 · cardio 10 · digestif 10 · neuro 12","cards":[{"q":"<b>Physiologie respiratoire</b> — Quelle est la structure principale responsable des échanges gazeux ?","a":"Les <b>alvéoles pulmonaires</b>.<br><br>❌ Pas la trachée, ni les bronches segmentaires, ni les bronchioles terminales, ni la plèvre.<br>→ C'est au niveau de la <b>membrane alvéolo-capillaire</b> que se font les échanges O₂/CO₂.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie respiratoire</b> — Le diaphragme est-il un muscle inspiratoire ou expiratoire ? Quel type de muscle ?","a":"C'est le <b>principal muscle INSPIRATOIRE</b>.<br><br>⚠️ C'est un muscle <b>SQUELETTIQUE (strié)</b>, pas un muscle lisse → il est <b>volontaire</b> (mais le plus souvent automatique).<br>Sa contraction → s'abaisse → ↑ volume thoracique → inspiration.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie respiratoire</b> — Les muscles intercostaux externes : type ? rôle ?","a":"<b>Muscles squelettiques</b> (striés, volontaires).<br>Rôle : <b>inspiration</b> (ils élèvent les côtes).<br><br>⚠️ Piège : ce sont les intercostaux <b>INTERNES</b> qui participent à l'expiration <b>forcée</b>.<br>L'expiration normale est <b>PASSIVE</b> (élasticité pulmonaire).","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie respiratoire</b> — De quoi est constituée la paroi des alvéoles ?","a":"<b>Pneumocyte 1 + pneumocyte 2 + macrophage</b>.<br><br>• <b>Pneumocyte I</b> : cellule pavimenteuse, <b>échanges gazeux</b> (95 % de la surface)<br>• <b>Pneumocyte II</b> : sécrète le <b>surfactant</b><br>• <b>Macrophage alvéolaire</b> (cellule à poussière) : défense<br><br>❌ Pas un épithélium pseudostratifié cilié (ça c'est la trachée/bronches).","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie respiratoire</b> — La ventilation pulmonaire : inspiration et expiration sont-elles actives ou passives ?","a":"<b>Inspiration = ACTIVE</b> (contraction du diaphragme + intercostaux externes)<br><b>Expiration normale = PASSIVE</b> (relâchement + élasticité pulmonaire)<br><br>⚠️ L'expiration <b>forcée</b> devient active (intercostaux internes + abdominaux).","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie respiratoire</b> — Le surfactant pulmonaire : qui le sécrète ? quel est son rôle ?","a":"Sécrété par les <b>PNEUMOCYTES II</b>.<br><br>C'est une substance <b>tensioactive</b> (dipalmitoyl-phosphatidylcholine + protéines SP-A/B/C/D).<br>Rôle : <b>abaisse la tension superficielle</b> alvéolaire →<br>• empêche le <b>collapsus alvéolaire</b> (atélectasie)<br>• ↑ la <b>compliance</b> pulmonaire<br>• ↓ le travail respiratoire<br><br>⚠️ Chez le <b>prématuré</b>, le surfactant est absent → <b>maladie des membranes hyalines</b>.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — Quel est le pacemaker physiologique du cœur ?","a":"Le <b>NŒUD SINUSAL</b> (nœud sino-auriculaire, Keith &amp; Flack).<br><br>Situé dans la paroi de l'<b>oreillette droite</b>, près de l'abouchement de la veine cave supérieure.<br>Fréquence propre : <b>70–80/min</b>.<br><br>Ordre de conduction : <b>nœud sinusal → oreillettes → nœud AV (Aschoff-Tawara) → faisceau de His → fibres de Purkinje → ventricules</b>.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — À quoi est due la phase de dépolarisation rapide du potentiel d'action ventriculaire ?","a":"À une <b>entrée massive de Na⁺</b> (courant sodique entrant rapide, via les canaux Na⁺ voltage-dépendants).<br><br>⚠️ Ne pas confondre :<br>• <b>Phase 0</b> (dépolarisation rapide) = entrée <b>Na⁺</b><br>• <b>Phase 2</b> (plateau) = entrée <b>Ca²⁺</b><br>• <b>Phase 3</b> (repolarisation) = sortie <b>K⁺</b>","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — La phase plateau du potentiel d'action de la fibre contractile est due à… ?","a":"Une <b>entrée de CALCIUM (Ca²⁺)</b> via les canaux calciques de type L.<br><br>C'est ce qui <b>prolonge</b> le PA cardiaque (~300 ms) et empêche la <b>tétanisation</b> du muscle cardiaque (période réfractaire longue).","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — Quel facteur augmente la fréquence cardiaque ?","a":"L'<b>ADRÉNALINE</b> (et la noradrénaline) — stimulation <b>sympathique</b>, via les récepteurs <b>β1</b>.<br><br>❌ L'<b>acétylcholine</b> (parasympathique, nerf vague X) <b>diminue</b> la fréquence cardiaque via les récepteurs <b>M2</b>.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — Quelle valve se trouve entre l'oreillette gauche et le ventricule gauche ?","a":"La valve <b>MITRALE</b> (bicuspide).<br><br>Rappel des 4 valves :<br>• <b>Tricuspide</b> : oreillette D ↔ ventricule D<br>• <b>Mitrale</b> (bicuspide) : oreillette G ↔ ventricule G<br>• <b>Pulmonaire</b> : ventricule D → artère pulmonaire<br>• <b>Aortique</b> : ventricule G → aorte<br><br>Moyen mnémotechnique : les valves <b>droites</b> ont <b>3</b> lettres (Tricuspide, Pulmonaire) sauf Aortique… → retenir surtout <b>Mitrale à gauche</b>.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — La relaxation du ventricule correspond à quelle phase ?","a":"La <b>DIASTOLE VENTRICULAIRE</b>.<br><br>• <b>Systole</b> = contraction (éjection)<br>• <b>Diastole</b> = relaxation (remplissage)<br><br>Cycle cardiaque (~0,8 s à 75/min) : systole auriculaire (0,1 s) → systole ventriculaire (0,3 s) → diastole générale (0,4 s).","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — Décris la petite circulation (pulmonaire) et la grande circulation (systémique).","a":"<b>Petite circulation</b> : <b>ventricule D → artère pulmonaire → poumons → 4 veines pulmonaires → oreillette G</b>.<br>⚠️ L'artère pulmonaire transporte du sang <b>DÉSOXYGÉNÉ</b>, les veines pulmonaires du sang <b>OXYGÉNÉ</b>.<br><br><b>Grande circulation</b> : <b>ventricule G → aorte → corps → veines caves → oreillette D</b>.<br>Transporte du sang <b>oxygéné</b> vers les tissus.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — Quel est le potentiel de repos d'une fibre musculaire cardiaque CONTRACTILE ?","a":"<b>−90 mV</b>.<br><br>⚠️ Ne pas confondre :<br>• Fibre <b>contractile</b> ventriculaire : <b>−90 mV</b><br>• Fibre <b>nerveuse</b> / neurone : <b>−70 mV</b><br>• Cellule <b>autorythmique</b> (nœud sinusal) : pas de potentiel de repos stable → <b>dépolarisation diastolique spontanée</b>","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie cardiovasculaire</b> — La cellule cardiaque contractile est-elle excitable ? mitotique ? autorythmique ?","a":"<b>EXCITABLE</b> ✅ (elle répond à un stimulus par un PA)<br><b>MITOTIQUE</b> ❌ (les cardiomyocytes sont en <b>phase G0</b> définitive → ne se divisent plus → pas de régénération après infarctus)<br><b>AUTORYTHMIQUE</b> ❌ (seules les cellules <b>nodales</b> — nœud sinusal, nœud AV — sont autorythmiques)<br>A UN SEUL NOYAU CENTRAL ❌ (pas plusieurs noyaux périphériques — ça c'est la fibre musculaire squelettique)","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Où commence la digestion des glucides ?","a":"Dans la <b>BOUCHE</b>.<br><br>Par l'<b>amylase salivaire</b> (ptyaline), sécrétée principalement par la <b>glande parotide</b>.<br>⚠️ Elle est <b>inactivée par le pH acide de l'estomac</b> → la digestion des glucides reprend dans le <b>duodénum</b> par l'<b>amylase pancréatique</b>.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Quelles cellules de l'estomac sécrètent l'acide chlorhydrique (HCl) ?","a":"Les <b>CELLULES PARIÉTALES</b> (cellules oxyntiques, bordées en brosse).<br><br>Rappel des cellules gastriques :<br>• <b>Pariétales</b> → <b>HCl</b> + <b>facteur intrinsèque</b><br>• <b>Principales</b> (peptiques) → <b>pepsinogène</b><br>• <b>G</b> (antro-pyloriques) → <b>gastrine</b><br>• <b>À mucus</b> → mucus + bicarbonates (protection)<br>• <b>D</b> → somatostatine","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Où est produite la bile ? Où est-elle stockée ?","a":"Produite par le <b>FOIE</b> (hépatocytes).<br>Stocker et concentrée dans la <b>VÉSICULE BILIAIRE</b>.<br><br>⚠️ Piège classique : la vésicule ne <b>produit pas</b> la bile, elle la <b>stocke</b>.<br>Rôle de la bile : <b>émulsifier les lipides</b> (pas d'enzyme !) → ↑ la surface d'action de la lipase pancréatique.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Quelle est l'enzyme principale de la digestion des lipides ?","a":"La <b>LIPASE PANCRÉATIQUE</b>.<br><br>Elle agit sur les <b>triacylglycérols</b> → 2 acides gras + 1 monoglycéride.<br>Nécessite la <b>colipase</b> (ancrage à l'interface lipidique) et l'<b>émulsification</b> préalable par les sels biliaires.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Où observe-t-on surtout la motilité segmentaire (segmentation) ? Quel est son rôle ?","a":"Dans l'<b>INTESTIN GRÊLE</b>.<br><br>Rôle : <b>MÉLANGER</b> le chyme avec les sucs digestifs et le mettre en contact avec la muqueuse → <b>favorise l'absorption</b>.<br><br>⚠️ Ne pas confondre avec le <b>péristaltisme</b>, qui <b>PROPULSE</b> le contenu dans une seule direction.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Quelle hormone stimule la sécrétion des bicarbonates pancréatiques ?","a":"La <b>SÉCRÉTINE</b>.<br><br>Sécrétée par les <b>cellules S du duodénum</b> en réponse à l'<b>acidité</b> du chyme.<br>Effet : suc pancréatique <b>aqueux, riche en bicarbonates</b> → <b>neutralise</b> le chyme acide.<br><br>Rappel : la <b>CCK</b> (cholécystokinine) stimule les <b>enzymes</b> pancréatiques + la contraction de la vésicule biliaire.","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Quel est le rôle principal de l'onde péristaltique ?","a":"<b>PROPULSER le contenu digestif</b> dans le sens oral → anal.<br><br>Mécanisme : contraction <b>en amont</b> (circulaire) + relâchement <b>en aval</b> (longitudinal).<br>Régulé par le <b>système nerveux entérique</b> (plexus myentérique d'Auerbach).<br><br>❌ Ce n'est pas pour mélanger (ça c'est la segmentation).","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Pourquoi le pH très acide de l'estomac est-il essentiel ?","a":"Pour <b>ACTIVER LA PEPSINE</b>.<br><br>Le HCl transforme le <b>pepsinogène</b> (inactif, sécrété par les cellules principales) en <b>pepsine</b> (active) par <b>auto-catalyse</b> à pH &lt; 5.<br><br>Autres rôles du HCl :<br>• <b>Bactéricide</b> (barrière anti-infectieuse)<br>• Dénature les protéines<br>• Favorise l'absorption du <b>fer</b> et du <b>calcium</b><br>• Stimule la <b>sécrétine</b> duodénale","t":"physio-2026 EXAM-2026"},{"q":"<b>Physiologie digestive</b> — Le facteur intrinsèque est essentiel pour l'absorption de quelle vitamine ?","a":"La <b>VITAMINE B12</b> (cobalamine).<br><br>Le <b>facteur intrinsèque de Castle</b> est une glycoprotéine sécrétée par les <b>cellules pariétales</b> de l'estomac.<br>Le complexe <b>B12-FI</b> est absorbé dans l'<b>iléon terminal</b> (récepteur cubiline).<br><br>⚠️ <b>Gastrectomie</b> ou <b>biermer</b> (gastrite atrophiante auto-immune) → carence en B12 → <b>anémie mégaloblastique</b> + atteinte neurologique.","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Le système nerveux parasympathique : volontaire ? neurotransmetteur ? effets ?","a":"<b>INVOLONTAIRE</b> ✅ (système nerveux autonome)<br>Neurotransmetteur : <b>ACÉTYLCHOLINE</b> (aux récepteurs muscariniques)<br><br>Effets (« <b>rest and digest</b> ») :<br>• <b>↓ fréquence cardiaque</b><br>• <b>Constriction des bronches</b><br>• ↑ motilité et sécrétions digestives<br>• <b>Myosis</b> (constriction pupillaire)<br>• ↑ sécrétion lacrymale/salivaire","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Quelles cellules appartiennent à la névroglie ? Laquelle n'en fait PAS partie ?","a":"<b>Névroglie (cellules gliales)</b> :<br>• <b>Astrocyte</b> (SNC — soutien, barrière hémato-encéphalique)<br>• <b>Oligodendrocyte</b> (SNC — myéline)<br>• <b>Cellule de Schwann</b> (SNP — myéline)<br>• <b>Épendymocyte</b> (SNC — revêtement des ventricules)<br>• <b>Microglie</b> (SNC — macrophages, défense)<br><br>❌ Le <b>NEURONE</b> n'appartient <b>PAS</b> à la névroglie — c'est la cellule <b>noble, excitable</b>.","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Le neurone est-il excitable ? mitotique ?","a":"<b>EXCITABLE</b> ✅ — capable de générer et conduire un potentiel d'action<br><b>MITOTIQUE</b> ❌ — les neurones matures sont en <b>phase G0 définitive</b>, ils ne se divisent plus.<br><br>⚠️ D'où l'importance des <b>cellules souches neurales</b> et de la <b>plasticité synaptique</b> (le neurone ne se renouvelle pas, mais les connexions se remodelent).","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Qu'est-ce qu'un nerf mixte ?","a":"Un nerf qui contient <b>à la fois des fibres SENSITIVES (afférentes) et des fibres MOTRICES (efférentes)</b>.<br><br>→ Il est donc <b>BIDIRECTIONNEL</b>.<br><br>Exemples : les <b>nerfs spinaux (rachidiens)</b> sont tous mixtes.<br>Le nerf <b>triJUMEAU (V)</b> est mixte → très important en odontologie (branches V2 maxillaire et V3 mandibulaire).","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Avec combien de neurones naît-on ?","a":"<b>≈ 100 MILLIARDS</b> de neurones (10¹¹).<br><br>Le nombre est fixé à la naissance — il n'y a pas de <b>neurogenèse</b> significative chez l'adulte (sauf dans l'hippocampe et la zone sous-ventriculaire).<br>→ Ce qui se développe, c'est le nombre de <b>SYNAPSES</b> (jusqu'à 10 000 par neurone) et la <b>myélinisation</b>.","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Quel est le potentiel de repos d'une fibre nerveuse ?","a":"<b>−70 mV</b> (intérieur négatif par rapport à l'extérieur).<br><br>Rappel :<br>• Neurone : <b>−70 mV</b><br>• Cardiomyocyte contractile : <b>−90 mV</b><br>• Fibre musculaire squelettique : <b>−90 mV</b><br><br>Ce potentiel est <b>STABLE</b> (pas instable) tant qu'il n'y a pas de stimulus.","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Quel est le facteur le plus important responsable de l'inégalité des charges membranaires au repos ?","a":"Le <b>CANAL DE FUITE POTASSIQUE (K⁺)</b>.<br><br>Mécanisme : la membrane au repos est <b>beaucoup plus perméable au K⁺ qu'au Na⁺</b> (≈ 50–100×).<br>Le K⁺ sort de la cellule <b>selon son gradient de concentration</b> → laisse des <b>anions</b> (protéines⁻) à l'intérieur → intérieur <b>négatif</b>.<br><br>La <b>pompe Na⁺/K⁺ ATPase</b> (3 Na⁺ out / 2 K⁺ in) <b>entretient</b> les gradients mais ne contribue que pour ~ −5 mV directement.","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Quelles sont les phases du potentiel d'action, dans l'ordre ? Que se passe-t-il ioniquement dans chacune ?","a":"1. <b>REPOS</b> : −70 mV (canaux de fuite K⁺)<br>2. <b>DÉPOLARISATION</b> : <b>entrée massive de Na⁺</b> (canaux Na⁺ voltage-dépendants) → le potentiel monte à <b>+30 mV</b><br>3. <b>REPOLARISATION</b> : <b>sortie de K⁺</b> (canaux K⁺ voltage-dépendants, lents à s'ouvrir) → retour vers −70 mV<br>4. <b>HYPERPOLARISATION</b> (post-potentiel) : les canaux K⁺ restent ouverts trop longtemps → −80 mV<br>5. Retour au <b>REPOS</b> par la pompe Na⁺/K⁺<br><br>⚠️ La phase <b>DÉPOLARISATION</b> est la <b>PREMIÈRE</b> phase du potentiel d'action (après le repos).","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Quelle phase retarde la recréation d'un potentiel d'action ?","a":"L'<b>HYPERPOLARISATION</b> (phase de post-potentiel hyperpolarisant).<br><br>Elle correspond à la <b>période réfractaire relative</b> : la membrane est à −80 mV, donc <b>plus loin du seuil</b> (−55 mV) → il faut un stimulus <b>plus fort</b> pour déclencher un nouveau PA.<br><br>⚠️ Pendant la <b>période réfractaire ABSOLUE</b> (dépolarisation + repolarisation), <b>aucun</b> PA n'est possible, quelle que soit l'intensité.<br>→ C'est ce qui garantit la propagation <b>unidirectionnelle</b> et empêche la <b>tétanisation</b>.","t":"physio-2026 EXAM-2026"},{"q":"<b>Neurophysiologie</b> — Quel est le rôle du calcium présynaptique ?","a":"Le <b>Ca²⁺ présynaptique ACTIVE les vésicules synaptiques</b> → exocytose du neurotransmetteur.<br><br>Séquence :<br>1. Le PA arrive au <b>bouton terminal</b><br>2. Dépolarisation → ouverture des <b>canaux Ca²⁺ voltage-dépendants</b><br>3. <b>Entrée de Ca²⁺</b> (le Ca²⁺ n'est <b>pas stocké</b> dans les vésicules !)<br>4. Ca²⁺ se lie à la <b>synaptotagmine</b> → complexe SNARE<br>5. <b>Fusion</b> des vésicules avec la membrane → exocytose<br>6. Neurotransmetteur dans la fente synaptique","t":"physio-2026 EXAM-2026"},{"q":"<b>Physio — récap</b> : tableau des potentiels de repos à retenir","a":"• <b>Neurone / fibre nerveuse</b> : <b>−70 mV</b><br>• <b>Cardiomyocyte contractile</b> : <b>−90 mV</b><br>• <b>Fibre musculaire squelettique</b> : <b>−90 mV</b><br>• <b>Cellule nodale (nœud sinusal)</b> : <b>−60 mV</b> puis dépolarisation diastolique spontanée<br>• <b>Seuil de déclenchement du PA</b> : <b>−55 mV</b><br>• <b>Pic du PA</b> : <b>+30 mV</b>","t":"physio-2026 EXAM-2026"}]},{"id":"chimie-S1-2026","nom":"⚗️ Chimie","src":"Examen N2026","ordre":2,"module":"M112","desc":"40 QCM · ~45% atomistique + ~55% organique","cards":[{"q":"<b>ATOMISTIQUE</b> — Rappelle la règle de <b>Klechkowski</b> (règle de Madelung). À quoi sert-elle ?","a":"Elle donne l'<b>ordre de remplissage des orbitales</b> selon l'énergie croissante.<br><br>Règle : on classe par <b>n + ℓ</b> croissant ; si <b>n + ℓ</b> est égal, on classe par <b>n</b> croissant.<br><br><b>Ordre à apprendre par cœur :</b><br><b>1s · 2s · 2p · 3s · 3p · 4s · 3d · 4p · 5s · 4d · 5p · 6s · 4f · 5d · 6p · 7s · 5f · 6d</b><br><br>⚠️ Piège : <b>4s se remplit AVANT 3d</b>, mais à l'<b>ionisation</b> ce sont les <b>4s qui partent EN PREMIER</b>.<br>Ex. : Fe = [Ar] 4s² 3d⁶ → Fe²⁺ = [Ar] 3d⁶ (<b>pas</b> 4s² 3d⁴).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Énonce le <b>principe d'exclusion de Pauli</b> et le <b>règle de Hund</b>.","a":"<b>PAULI</b> : deux électrons d'un même atome ne peuvent pas avoir leurs <b>4 nombres quantiques identiques</b> → une orbitale contient au maximum <b>2 électrons</b>, de <b>spins opposés</b> (↑↓).<br><br><b>HUND</b> (règle du multiplicité maximale) : dans des orbitales <b>dégénérées</b> (même énergie, ex. les 3 orbitales 2p), les électrons se placent <b>d'abord seuls, un par orbitale, avec des spins PARALLÈLES</b>, avant de s'apparier.<br><br>Ex. : l'<b>azote</b> (Z=7) → 1s² 2s² 2p³ = ↑ ↑ ↑ (trois électrons célibataires, <b>pas</b> ↑↓ ↑).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Les 4 nombres quantiques : nom, symbole, valeurs possibles, signification.","a":"<b>1. n</b> — nombre quantique <b>PRINCIPAL</b> : <b>n = 1, 2, 3…</b> → <b>couche</b> (niveau d'énergie, taille).<br><b>2. ℓ</b> — nombre quantique <b>SECONDAIRE (azimutal)</b> : <b>ℓ = 0 → n−1</b> → <b>sous-couche / forme</b> de l'orbitale.<br>&nbsp;&nbsp;&nbsp;ℓ=0 → <b>s</b> (sphère) · ℓ=1 → <b>p</b> (haltère) · ℓ=2 → <b>d</b> · ℓ=3 → <b>f</b><br><b>3. mℓ</b> — nombre quantique <b>MAGNÉTIQUE</b> : <b>mℓ = −ℓ … +ℓ</b> → <b>orientation</b> dans l'espace.<br>&nbsp;&nbsp;&nbsp;Nombre d'orbitales par sous-couche = <b>2ℓ + 1</b><br><b>4. ms</b> — nombre quantique de <b>SPIN</b> : <b>+½ ou −½</b><br><br>⚠️ Nombre maximal d'électrons par sous-couche = <b>2(2ℓ+1)</b> → s:<b>2</b>, p:<b>6</b>, d:<b>10</b>, f:<b>14</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Donne le nombre d'électrons et le nombre d'orbitales de chaque sous-couche s, p, d, f.","a":"<b>s</b> (ℓ=0) : <b>1 orbitale</b>, max <b>2 électrons</b><br><b>p</b> (ℓ=1) : <b>3 orbitales</b>, max <b>6 électrons</b><br><b>d</b> (ℓ=2) : <b>5 orbitales</b>, max <b>10 électrons</b><br><b>f</b> (ℓ=3) : <b>7 orbitales</b>, max <b>14 électrons</b><br><br>Formule : orbitales = <b>2ℓ+1</b> ; électrons = <b>2(2ℓ+1)</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Quels sont les cas de configuration électronique « anormale » à connaître ?","a":"<b>Cr (Z=24)</b> : [Ar] <b>3d⁵ 4s¹</b> (et <b>pas</b> 3d⁴ 4s²)<br><b>Cu (Z=29)</b> : [Ar] <b>3d¹⁰ 4s¹</b> (et <b>pas</b> 3d⁹ 4s²)<br><br>Raison : une sous-couche <b>demi-remplie (d⁵)</b> ou <b>totalement remplie (d¹⁰)</b> est <b>plus stable</b> (énergie plus basse).<br><br>⚠️ Dans les QCM, c'est <b>toujours</b> la réponse correcte face à la version « mécanique ».","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Que sont les <b>isotopes</b> ? les <b>isobares</b> ? les <b>isotones</b> ?","a":"<b>ISOTOPES</b> : même <b>Z</b> (même élément), <b>A différent</b> → nombre de <b>NEUTRONS différent</b>.<br>&nbsp;&nbsp;Ex. : ¹²C, ¹³C, ¹⁴C. Même propriétés <b>chimiques</b>, propriétés <b>physiques</b> différentes.<br><b>ISOBARES</b> : même <b>A</b>, <b>Z différent</b>.<br>&nbsp;&nbsp;Ex. : ⁴⁰Ar, ⁴⁰K, ⁴⁰Ca.<br><b>ISOTONES</b> : même nombre de <b>NEUTRONS (N = A − Z)</b>, Z et A différents.<br>&nbsp;&nbsp;Ex. : ¹³C (N=7) et ¹⁴N (N=7).<br><br>Moyen mnémotechnique : iso<b>p</b>es = même <b>p</b>rotons · iso<b>b</b>ares = même masse <b>b</b>rute (A) · iso<b>t</b>ones = même neu<b>t</b>rons.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Comment calcule-t-on la masse atomique moyenne d'un élément à partir de ses isotopes ?","a":"C'est la <b>moyenne pondérée</b> par les abondances naturelles :<br><br><b>M = Σ (masseᵢ × abondanceᵢ) / 100</b><br><br>Ex. : chlore → ³⁵Cl (34,97 u ; 75,77 %) et ³⁷Cl (36,97 u ; 24,23 %)<br>M = (34,97 × 0,7577) + (36,97 × 0,2423) = <b>35,45 u</b><br><br>⚠️ Utilise les abondances en <b>fraction</b> (÷100), pas en pourcentage.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Comment évoluent les propriétés suivantes <b>le long d'une période</b> (de gauche à droite) ?","a":"<b>↑ Rayon atomique</b> → <b>DIMINUE</b> (Z efficace ↑, les électrons sont plus attirés)<br><b>↑ Énergie d'ionisation (EI₁)</b> → <b>AUGMENTE</b> (plus dur d'arracher un e⁻)<br><b>↑ Affinité électronique</b> → <b>AUGMENTE</b> (en valeur absolue)<br><b>↑ Électronégativité</b> → <b>AUGMENTE</b><br><b>↑ Caractère métallique</b> → <b>DIMINUE</b><br><b>↑ Caractère non-métallique</b> → <b>AUGMENTE</b><br><br>Règle globale : tout augmente sauf le rayon et le caractère métallique.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Comment évoluent ces mêmes propriétés <b>le long d'un groupe</b> (de haut en bas) ?","a":"<b>↓ Rayon atomique</b> → <b>AUGMENTE</b> (une couche électronique de plus à chaque période)<br><b>↓ Énergie d'ionisation</b> → <b>DIMINUE</b> (l'e⁻ externe est plus loin du noyau, écran ↑)<br><b>↓ Affinité électronique</b> → <b>DIMINUE</b><br><b>↓ Électronégativité</b> → <b>DIMINUE</b><br><b>↓ Caractère métallique</b> → <b>AUGMENTE</b><br><b>↓ Caractère basique des oxydes</b> → <b>AUGMENTE</b><br><br>⚠️ C'est l'<b>inverse exact</b> de la période, sauf le caractère métallique qui augmente dans les deux sens vers le bas-gauche.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Classe ces éléments par électronégativité croissante : F, O, N, Cl, C, H, Na.","a":"<b>Na (0,93) &lt; H (2,20) &lt; C (2,55) &lt; N (3,04) &lt; Cl (3,16) &lt; O (3,44) &lt; F (3,98)</b><br><br>Échelle de <b>Pauling</b>. À retenir absolument pour la <b>polarité des liaisons</b> et les <b>effets inductifs</b> en organique.<br><br>⚠️ <b>F &gt; O</b> — c'est la seule inversion classique que les étudiants oublient. Et <b>Cl &gt; N</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Quelle est la relation entre ΔEN et le type de liaison ?","a":"<b>ΔEN &lt; 0,4</b> → liaison <b>COVALENTE PURE (APOLAIRE)</b> (ex. : H–H, C–H, Cl–Cl)<br><b>0,4 ≤ ΔEN &lt; 1,7</b> → liaison <b>COVALENTE POLAIRE</b> (ex. : H–Cl, C–O, O–H)<br><b>ΔEN ≥ 1,7</b> → liaison <b>IONIQUE</b> (ex. : NaCl, Na⁺Cl⁻)<br><br>⚠️ Le <b>moment dipolaire μ = q × d</b> (en <b>Debye</b>, 1 D = 3,33 × 10⁻³⁰ C·m). μ = 0 pour une molécule <b>apolaire</b> (ex. : CO₂, symétrique, même si les liaisons C=O sont polaires).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Qu'est-ce que la <b>charge nucléaire efficace (Z_eff)</b> ? Formule de Slater simplifiée.","a":"<b>Z_eff = Z − σ</b> (σ = constante d'écran).<br><br>C'est la charge <b>réellement ressentie</b> par un électron externe, après soustraction de l'<b>effet d'écran</b> des électrons internes.<br><br>• Les électrons de la <b>même couche</b> écrantent peu (σ ≈ 0,35 par e⁻)<br>• Les électrons des <b>couches internes</b> écrantent beaucoup (σ ≈ 0,85 à 1,00)<br><br>→ C'est Z_eff qui explique pourquoi le <b>rayon diminue le long d'une période</b> (Z augmente, σ augmente peu → Z_eff augmente).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Définit l'<b>énergie d'ionisation</b>. Comment évolue EI₁, EI₂, EI₃ d'un même atome ?","a":"<b>EI₁</b> = énergie minimale pour arracher le <b>premier</b> électron d'un atome <b>gazeux neutre isolé</b>.<br><br>Toujours : <b>EI₁ &lt; EI₂ &lt; EI₃ …</b><br><br>Raison : après avoir enlevé un e⁻, l'espèce devient un <b>cation (+)</b> → elle attire plus fortement les e⁻ restants → il faut plus d'énergie.<br><br>⚠️ Un <b>saut brutal</b> entre EIₙ et EIₙ₊₁ indique que l'on vient de vider la <b>couche de valence</b> (ex. : Na → saut entre EI₁ et EI₂ ; Mg → saut entre EI₂ et EI₃).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Les 3 types d'<b>hybridation</b> du carbone : géométrie, angle, orbitales.","a":"<b>sp³</b> : 1 orbitale s + 3 orbitales p → <b>4 orbitales sp³</b><br>&nbsp;&nbsp;Géométrie <b>tétraédrique</b>, angle <b>109,5°</b>, <b>4 liaisons σ</b> (ex. : CH₄, alcanes)<br><b>sp²</b> : 1 s + 2 p → <b>3 orbitales sp²</b> + 1 p pure non hybridée<br>&nbsp;&nbsp;Géométrie <b>trigonale plane</b>, angle <b>120°</b>, <b>3 σ + 1 π</b> (ex. : C₂H₄, alcènes, C=O)<br><b>sp</b> : 1 s + 1 p → <b>2 orbitales sp</b> + 2 p pures non hybridées<br>&nbsp;&nbsp;Géométrie <b>linéaire</b>, angle <b>180°</b>, <b>2 σ + 2 π</b> (ex. : C₂H₂, alcynes, C≡N)<br><br>⚠️ Règle rapide : hybridation = <b>(nombre d'atomes liés + nombre de doublets libres)</b> → 4 = sp³, 3 = sp², 2 = sp.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Différence entre liaison <b>σ (sigma)</b> et liaison <b>π (pi)</b>.","a":"<b>σ</b> : recouvrement <b>AXIAL</b> (tête-à-tête) des orbitales.<br>&nbsp;&nbsp;• Forte, <b>symétrie de révolution</b> autour de l'axe<br>&nbsp;&nbsp;• <b>Rotation LIBRE</b> possible<br>&nbsp;&nbsp;• Toute liaison simple est une σ<br><b>π</b> : recouvrement <b>LATÉRAL</b> (côte-à-côte) des orbitales <b>p non hybridées</b>.<br>&nbsp;&nbsp;• Plus <b>faible</b>, nuage électronique au-dessus et en-dessous du plan<br>&nbsp;&nbsp;• <b>BLOQUE la rotation</b> → cause l'<b>isomérie Z/E</b> !<br>&nbsp;&nbsp;• Double liaison = <b>1 σ + 1 π</b> ; triple = <b>1 σ + 2 π</b><br><br>⚠️ C'est le <b>π</b> qui est attaqué par les <b>électrophiles</b> (E⁺) dans les additions.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Donne les longueurs et énergies relatives des liaisons C–C, C=C, C≡C.","a":"<b>C–C</b> simple : <b>1,54 Å</b> — <b>347 kJ/mol</b> — la plus <b>LONGUE</b>, la plus <b>faible</b><br><b>C=C</b> double : <b>1,34 Å</b> — <b>614 kJ/mol</b><br><b>C≡C</b> triple : <b>1,20 Å</b> — <b>839 kJ/mol</b> — la plus <b>COURTE</b>, la plus <b>forte</b><br><br>⚠️ Mais : la <b>liaison π</b> seule est <b>faible</b> (614 − 347 = 267 kJ/mol) → c'est pourquoi les alcènes sont <b>plus réactifs</b> que les alcanes, même si la liaison totale est plus forte.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Qu'est-ce qu'un <b>complexe</b> (ion complexe / coordination) ? Vocabulaire.","a":"Un <b>complexe</b> = un <b>atome ou ion métallique central</b> entouré de <b>ligands</b>.<br><br>• <b>Atome central</b> : un métal de transition (Fe, Cu, Co, Zn, Pt…), <b>acide de Lewis</b> (accepteur de doublet)<br>• <b>Ligand</b> : espèce possédant au moins un <b>doublet libre</b> → <b>base de Lewis</b> (donneur). Ex. : H₂O, NH₃, Cl⁻, CN⁻, CO<br>• <b>Nombre de coordination</b> = nombre de liaisons métal–ligand → <b>2</b> (linéaire), <b>4</b> (tétraédrique ou plan carré), <b>6</b> (octaédrique)<br>• <b>Ligand monodentate</b> (1 donneur) vs <b>polydentate / chélate</b> (plusieurs, ex. : EDTA = hexadentate)<br>• <b>Sphère de coordination</b> = tout ce qui est entre crochets [ ]<br><br>Ex. : <b>[Cu(NH₃)₄]²⁺</b> — ion tétraamminecuivre(II), coordination 4, tétraédrique/plan carré.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Quels sont les <b>types d'isomérie</b> des complexes ?","a":"<b>ISOMÉRIE GÉOMÉTRIQUE (cis / trans)</b> :<br>• Possible en <b>plan carré</b> (coordination 4) et en <b>octaèdre</b> (coordination 6)<br>• ❌ <b>IMPOSSIBLE en tétraédrique</b> (toutes les positions sont adjacentes)<br>• <b>cis</b> = ligands identiques <b>voisins</b> (90°) ; <b>trans</b> = <b>opposés</b> (180°)<br>• Ex. célèbre : le <b>cisplatine [Pt(NH₃)₂Cl₂]</b> est anticancéreux, le <b>transplatine</b> ne l'est pas !<br><br><b>ISOMÉRIE OPTIQUE (énantiomères)</b> : complexes <b>chiraux</b>, sans plan de symétrie.<br><br><b>ISOMÉRIE DE LIAISON</b> : même ligand ambidentate lié par un atome différent (ex. : SCN⁻ par S = thiocyanato, par N = isothiocyanato).<br><br><b>ISOMÉRIE D'HYDRATATION / D'IONISATION</b> : échange entre la sphère de coordination et le contre-ion (ex. : [Cr(H₂O)₅Cl]Cl₂ vs [Cr(H₂O)₄Cl₂]Cl·H₂O).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ATOMISTIQUE</b> — Définis l'<b>acide</b> et la <b>base</b> de Lewis, et de Brønsted-Lowry.","a":"<b>BRØNSTED-LOWRY</b> :<br>• <b>Acide</b> = donneur de <b>PROTON (H⁺)</b><br>• <b>Base</b> = accepteur de <b>proton</b><br>• Couples conjugués : <b>HA / A⁻</b><br><br><b>LEWIS</b> :<br>• <b>Acide</b> = accepteur de <b>DOUBLET ÉLECTRONIQUE</b> (lacune électronique, ex. : BF₃, AlCl₃, H⁺, métaux de transition)<br>• <b>Base</b> = donneur de <b>doublet</b> (ex. : NH₃, H₂O, OH⁻, halogénures)<br><br>⚠️ Lewis est <b>plus général</b> : tout acide de Brønsted est un acide de Lewis, mais pas l'inverse (BF₃ est acide de Lewis mais pas de Brønsted).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Rappelle les <b>règles IUPAC</b> de nomenclature : comment choisir la chaîne principale ?","a":"1. Chercher la chaîne carbonée la <b>plus LONGUE</b> contenant la <b>fonction principale</b> (et les insaturations C=C / C≡C si présentes).<br>2. La <b>NUMÉROTER</b> en commençant par l'extrémité la plus proche de :<br>&nbsp;&nbsp;a) la <b>fonction principale</b> (priorité la plus haute)<br>&nbsp;&nbsp;b) à défaut, l'<b>insaturation</b> (double ou triple liaison)<br>&nbsp;&nbsp;c) à défaut, le <b>substituant</b><br>3. Nommer les <b>substituants par ordre ALPHABÉTIQUE</b> (di, tri, tétra ne comptent pas dans l'ordre alphabétique).<br>4. Écrire : <b>substituants + chaîne principale + suffixe de fonction</b>.<br><br>⚠️ Terminaisons : alcane <b>-ane</b> · alcène <b>-ène</b> · alcyne <b>-yne</b> · alcool <b>-ol</b> · aldéhyde <b>-al</b> · cétone <b>-one</b> · acide carboxylique <b>-oïque</b> · amine <b>-amine</b> · amide <b>-amide</b> · ester <b>-oate d'alkyle</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Quel est l'ordre de priorité décroissant des fonctions en nomenclature IUPAC ?","a":"<b>Acide carboxylique &gt; ester &gt; amide &gt; nitrile &gt; aldéhyde &gt; cétone &gt; alcool &gt; amine &gt; alcène/alcyne &gt; éther &gt; halogène</b><br><br>En détail :<br>1. <b>–COOH</b> acide carboxylique (suffixe <b>-oïque</b>)<br>2. <b>–COOR</b> ester (<b>-oate</b>)<br>3. <b>–CONH₂</b> amide (<b>-amide</b>)<br>4. <b>–CHO</b> aldéhyde (<b>-al</b>)<br>5. <b>C=O</b> cétone (<b>-one</b>)<br>6. <b>–OH</b> alcool (<b>-ol</b>)<br>7. <b>–NH₂</b> amine (<b>-amine</b>)<br>8. <b>C=C / C≡C</b> (<b>-ène / -yne</b>)<br>9. <b>–OR, –X</b> : toujours nommés comme <b>substituants</b> (méthoxy-, chloro-…)<br><br>⚠️ Les halogènes et les éthers ne sont <b>JAMAIS</b> la fonction principale → toujours préfixes.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Nomme ces chaînes/substituants : CH₃–, CH₃CH₂–, (CH₃)₂CH–, (CH₃)₃C–.","a":"<b>CH₃–</b> : <b>méthyle</b> (1 C)<br><b>CH₃–CH₂–</b> : <b>éthyle</b> (2 C)<br><b>(CH₃)₂CH–</b> : <b>isopropyle</b> (3 C, ramifié)<br><b>(CH₃)₃C–</b> : <b>tert-butyle</b> ou <b>1,1-diméthyléthyle</b> (4 C, ramifié)<br><br>Série normale : <b>méth (1) · éth (2) · prop (3) · but (4) · pent (5) · hex (6) · hept (7) · oct (8) · non (9) · déc (10)</b><br><br>Moyen mnémotechnique : « <b>Me</b>ths <b>Ét</b>udiants <b>Pro</b>fitent <b>But</b>inent <b>Pent</b>es <b>Hex</b>agones ».","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Quelles sont les grandes classes d'<b>isomérie</b> ?","a":"<b>I. ISOMÉRIE PLANE (de constitution)</b> — même formule brute, enchaînements différents :<br>1. <b>Isomérie de CHAÎNE (squelette)</b> : n-butane vs isobutane<br>2. <b>Isomérie de POSITION</b> : propan-1-ol vs propan-2-ol ; ortho/meta/para<br>3. <b>Isomérie de FONCTION</b> : éthanol (C₂H₆O) vs diméthyléther (C₂H₆O)<br>4. <b>Tautomérie</b> : équilibre céto-énolique<br>5. <b>Métamérie</b> : position différente d'un hétéroatome<br><br><b>II. STÉRÉOISOMÉRIE</b> — même constitution, disposition spatiale différente :<br>1. <b>Isomérie de CONFORMATION</b> : interconvertibles par <b>rotation libre</b> autour d'une liaison σ (Newman : éclipsée / décalée). <b>Ne sont PAS séparables</b>.<br>2. <b>Isomérie de CONFIGURATION</b> : <b>NON interconvertibles</b> sans rompre une liaison → <b>séparables</b>.<br>&nbsp;&nbsp;&nbsp;a) <b>Géométrique (cis/trans, Z/E)</b> — diastéréoisomères <b>non chiraux</b><br>&nbsp;&nbsp;&nbsp;b) <b>Optique</b> — molécules <b>chirales</b> (énantiomères, diastéréoisomères)","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Comment déterminer si un carbone est un <b>carbone asymétrique (stéréogène, chiral)</b> ?","a":"Un carbone est <b>ASYMÉTRIQUE (noté C*)</b> s'il est lié à <b>QUATRE SUBSTITUANTS TOUS DIFFÉRENTS</b>.<br><br>Conditions :<br>• Il doit être <b>sp³</b> (tétraédrique) — un carbone sp² ou sp ne peut PAS être chiral<br>• Les 4 groupes doivent être <b>distincts</b><br><br>Ex. :<br>• <b>CHBrClF</b> → chiral ✅<br>• <b>CH₃–CHOH–CH₃</b> (propan-2-ol) → ❌ <b>2 CH₃ identiques</b><br>• <b>Glycine</b> (NH₂–CH₂–COOH) → ❌ 2 H<br>• Tous les autres <b>acides aminés</b> → ✅ Cα chiral (sauf la glycine)<br><br>⚠️ <b>Chiral ≠ C* asymétrique</b> : une molécule peut être chirale sans carbone asymétrique (allènes, biphényles à encombrement). Le critère vrai = <b>absence de plan de symétrie ET de centre d'inversion</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Rappelle la règle <b>CIP (Cahn–Ingold–Prelog)</b> : comment classer les substituants ?","a":"On classe les 4 substituants du C* par <b>priorité</b> :<br><br><b>RÈGLE 1 — Numéro atomique Z</b> : l'atome <b>directement lié</b> au C* ayant le <b>Z le plus grand</b> a la priorité 1.<br>→ I &gt; Br &gt; Cl &gt; S &gt; F &gt; O &gt; N &gt; C &gt; H<br><br><b>RÈGLE 2 — En cas d'égalité</b>, on compare les atomes <b>suivants</b>, <b>un par un, par ordre décroissant</b>.<br>→ <b>–CH₂OH &gt; –CH₃</b> (O,H,H vs H,H,H)<br>→ <b>–CH(CH₃)₂ &gt; –CH₂CH₃</b> (C,C,H vs C,H,H)<br><br><b>RÈGLE 3 — Atomes « fantômes »</b> : une liaison multiple compte l'atome lié <b>autant de fois</b>.<br>→ <b>C=O</b> compte comme C lié à <b>(O, O, H)</b> ; <b>C≡N</b> comme C lié à <b>(N, N, N)</b>.<br>→ Donc <b>–CHO &gt; –CH₂OH</b>.<br><br><b>RÈGLE 4 — Isotopes</b> : à Z égal, la <b>masse la plus grande</b> gagne (D &gt; H).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Comment attribue-t-on la configuration <b>R</b> ou <b>S</b> à un carbone asymétrique ?","a":"1. Classer les 4 substituants selon <b>CIP</b> : 1 &gt; 2 &gt; 3 &gt; 4.<br>2. <b>Placer le substituant de priorité 4 (le plus petit, souvent H) EN ARRIÈRE</b> (trait pointillé, loin de l'œil).<br>3. Suivre le sens <b>1 → 2 → 3</b> :<br>&nbsp;&nbsp;• <b>Sens HORAIRE (droite, ↻)</b> → <b>R</b> (Rectus)<br>&nbsp;&nbsp;• <b>Sens ANTI-HORAIRE (gauche, ↺)</b> → <b>S</b> (Sinister)<br><br>⚠️ <b>ASTUCE SI LE 4 EST EN AVANT (trait plein)</b> : déterminer le sens puis <b>INVERSER</b> le résultat.<br>&nbsp;&nbsp;Ex. : 1→2→3 horaire avec le 4 devant → vraie configuration = <b>S</b>.<br><br>⚠️ <b>R/S n'a AUCUN rapport avec le signe du pouvoir rotatoire (+)/(−)</b>. Un composé <b>R</b> peut être <b>lévogyre (−)</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Dans une <b>projection de Fischer</b>, que signifient les traits horizontaux et verticaux ? Comment passe-t-on de R à S ?","a":"<b>Projection de Fischer :</b><br>• Traits <b>HORIZONTAUX</b> = substituants <b>VERS L'AVANT</b> (en dehors du plan, vers l'observateur) — traits <b>pleins</b>/coins<br>• Trait <b>VERTICAL</b> = substituants <b>VERS L'ARRIÈRE</b> (en dedans du plan)<br>• La chaîne carbonée principale est <b>VERTICALE</b>, le carbone le plus <b>oxydé EN HAUT</b><br><br><b>MANIPULATIONS :</b><br>• Rotation de <b>90°</b> dans le plan → <b>INVERSE</b> la configuration (R↔S) ❌ interdit<br>• Rotation de <b>180°</b> dans le plan → <b>CONSERVE</b> la configuration ✅ autorisé<br>• Échange de <b>2 substituants</b> → <b>INVERSE</b> la configuration<br>• Fixer un substituant et faire <b>tourner les 3 autres</b> → conserve la configuration<br><br>⚠️ En Fischer, si le H (priorité 4) est à l'<b>horizontale</b> (donc vers l'avant), on lit le sens 1→2→3 puis on <b>inverse</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Dans une <b>projection de Cram</b>, que représentent le trait plein, le coin plein (▲) et le trait pointillé ?","a":"<b>Cram (perspective) :</b><br>• <b>Trait plein (—)</b> : liaison <b>DANS LE PLAN</b> du papier<br>• <b>Coin/triangle plein (▲)</b> : liaison <b>VERS L'AVANT</b>, vers l'observateur (au-dessus du plan)<br>• <b>Trait pointillé (····) ou hachuré</b> : liaison <b>VERS L'ARRIÈRE</b>, derrière le plan<br><br>⚠️ C'est la représentation <b>la plus directe</b> pour appliquer la règle R/S.<br>Le carbone chiral est au centre du tétraèdre.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Dans une <b>projection de Newman</b>, quelles sont les conformations remarquables ? Laquelle est la plus stable ?","a":"<b>En regardant le long de la liaison C–C :</b><br><br>• <b>ÉCLIPSÉE (syn-periplanaire, angle dièdre 0°)</b> : les substituants du C avant <b>masquent</b> ceux du C arrière → <b>LA MOINS STABLE</b> (tension stérique maximale + répulsion électronique)<br>• <b>DÉCALÉE (anti-periplanaire, 180°)</b> : les gros groupes sont <b>opposés</b> → <b>LA PLUS STABLE</b> ✅<br>• <b>Décalée gauche (gauche / syn-clinal, 60°)</b> : stabilité intermédiaire, moins bonne que l'anti<br><br>⚠️ Barrière de rotation éthane : <b>~12 kJ/mol</b> — faible, donc rotation <b>libre</b> à température ambiante → les conformères ne sont <b>pas séparables</b>.<br><br>Dans le <b>cyclohexane</b> : la conformation <b>CHAISE</b> est la plus stable, et le substituant est plus stable en position <b>ÉQUATORIALE</b> (évite les interactions 1,3-diaxiales).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Définis : <b>énantiomères</b>, <b>diastéréoisomères</b>, <b>composé méso</b>, <b>racémique</b>.","a":"<b>ÉNANTIOMÈRES</b> : stéréoisomères <b>images l'un de l'autre dans un miroir, NON SUPERPOSABLES</b>.<br>• Toutes les configurations sont <b>inversées</b> (R,S → S,R)<br>• Propriétés physiques <b>IDENTIQUES</b> (F°, E°, solubilité), sauf le <b>pouvoir rotatoire</b> : même valeur absolue, signe <b>opposé</b><br>• Séparables uniquement par un milieu <b>chiral</b> (résolution)<br><br><b>DIASTÉRÉOISOMÈRES</b> : stéréoisomères <b>QUI NE SONT PAS</b> images dans un miroir.<br>• <b>Au moins une</b> configuration conservée, au moins une inversée (ex. : R,R vs R,S)<br>• Propriétés physiques <b>DIFFÉRENTES</b> → séparables par distillation/cristallisation/chromatographie classiques<br>• Inclut les isomères <b>cis/trans (Z/E)</b><br><br><b>COMPOSÉ MÉSO</b> : molécule possédant <b>des carbones asymétriques</b> mais <b>un PLAN DE SYMÉTRIE interne</b> → elle est <b>ACHIRALE</b> et <b>OPTIQUEMENT INACTIVE</b> (α = 0).<br>• Ex. : acide <b>méso</b>-tartrique (2R,3S)<br>⚠️ Un méso est <b>superposable à son image dans le miroir</b>.<br><br><b>RACÉMIQUE (mélange racémique)</b> : mélange <b>50/50</b> des deux énantiomères → <b>optiquement inactif</b> (les rotations s'annulent), noté <b>(±)</b> ou <b>dl</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Combien y a-t-il de stéréoisomères pour une molécule à <b>n</b> carbones asymétriques ?","a":"<b>Nombre maximal de stéréoisomères = 2ⁿ</b><br><br>• <b>n = 1</b> → 2 stéréoisomères (1 paire d'énantiomères)<br>• <b>n = 2</b> → 4 stéréoisomères = <b>2 paires d'énantiomères</b>, soit <b>3</b> s'il existe une forme <b>méso</b> (2 énantiomères + 1 méso)<br>• <b>n = 3</b> → 8 stéréoisomères = 4 paires d'énantiomères<br><br>⚠️ Le nombre est <b>réduit</b> en dessous de 2ⁿ s'il y a un <b>élément de symétrie</b> (forme méso) ou une contrainte cyclique.<br><br>Ex. type QCM : l'<b>acide tartrique</b> (HOOC–CHOH–CHOH–COOH) a 2 C* mais seulement <b>3</b> stéréoisomères : (+), (−) et <b>méso</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Comment attribue-t-on la configuration <b>Z</b> ou <b>E</b> à une double liaison C=C ?","a":"<b>Pré-requis</b> : chaque carbone de la double liaison doit porter <b>2 substituants DIFFÉRENTS</b>.<br><br>Méthode :<br>1. Sur <b>chaque</b> carbone du C=C, classer les 2 substituants par <b>CIP</b> (priorité 1 = Z atomique le plus grand).<br>2. Regarder où sont les deux groupes de <b>priorité 1</b> :<br>&nbsp;&nbsp;• Du <b>MÊME CÔTÉ</b> → <b>Z</b> (allemand <i>zusammen</i> = ensemble)<br>&nbsp;&nbsp;• De côtés <b>OPPOSÉS</b> → <b>E</b> (allemand <i>entgegen</i> = opposé)<br><br>⚠️ <b>Z/E ≠ cis/trans</b>. cis/trans compare des groupes <b>identiques</b> ; Z/E compare des <b>priorités CIP</b>.<br>Ex. : dans <b>CH₃–CH=CH–Br</b>, on doit utiliser Z/E (Br a une priorité supérieure à CH₃).<br><br>⚠️ <b>Un C=C ne peut PAS avoir d'isomérie géométrique</b> si l'un des carbones porte 2 substituants identiques (ex. : CH₂=CH–CH₃).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Définis les configurations <b>érythro</b> et <b>thréo</b>.","a":"<b>ÉRYTHRO</b> : en projection de <b>Fischer</b>, les deux substituants <b>identiques (ou semblables)</b> sont du <b>MÊME CÔTÉ</b> (tous deux à droite, ou tous deux à gauche).<br><br><b>THRÉO</b> : les deux substituants identiques sont de côtés <b>OPPOSÉS</b> (l'un à droite, l'autre à gauche).<br><br>Moyen mnémotechnique :<br>• <b>É</b>rythro = <b>É</b>gal côté = même côté<br>• <b>T</b>hréo = <b>T</b>raversé = opposé<br><br>⚠️ Correspondance avec Z/E (pour des chaînes similaires) :<br>• <b>érythro ≈ syn ≈ Z</b> (souvent)<br>• <b>thréo ≈ anti ≈ E</b> (souvent)<br>Mais ce n'est pas toujours vrai — vérifier cas par cas.<br><br>Ex. biologique : la <b>thr</b>éonine (acide aminé) est <b>thr</b>éo — le nom vient de là !","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Qu'est-ce que le <b>pouvoir rotatoire</b> ? Comment le calcule-t-on ?","a":"Le <b>pouvoir rotatoire [α]</b> est l'angle dont une substance chirale fait <b>tourner le plan de la lumière polarisée</b>.<br><br><b>[α] = α / (l × C)</b><br>• <b>α</b> = angle de rotation observé (en degrés)<br>• <b>l</b> = longueur de la cuve (en <b>dm</b>, décimètres — pas en cm !)<br>• <b>C</b> = concentration (en <b>g/mL</b>)<br>• Conditions standard : <b>T = 20 °C</b>, <b>λ = raie D du sodium (589 nm)</b> → noté [α]ᴅ²⁰<br><br>• <b>(+) ou d</b> = <b>dextrogyre</b> (rotation vers la droite, horaire)<br>• <b>(−) ou l</b> = <b>lévogyre</b> (rotation vers la gauche)<br>• <b>(±) ou dl</b> = <b>racémique</b> (α = 0)<br><br><b>PURETÉ OPTIQUE (excès énantiomérique) :</b><br><b>ee % = ([α]observé / [α]pur) × 100</b> = %(majoritaire) − %(minoritaire)","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Définis l'<b>effet inductif (I)</b>. Quels groupes sont −I et +I ?","a":"<b>EFFET INDUCTIF</b> : déplacement <b>permanent</b> des électrons d'une <b>liaison σ</b> dû à la différence d'<b>électronégativité</b>. Il se transmet par les liaisons σ et <b>s'atténue vite</b> (disparaît après ~3 liaisons).<br><br><b>−I (attracteur, électron-attracteur)</b> : attire les électrons vers soi.<br>Ordre décroissant : <b>–NO₂ &gt; –CN &gt; –F &gt; –Cl &gt; –Br &gt; –I &gt; –OH &gt; –OR &gt; –NH₂ &gt; –C≡CH &gt; –Ph</b><br>→ Tous les <b>halogènes</b> sont −I. <b>F est le plus fort</b> (le plus électronégatif).<br><br><b>+I (donneur, électron-donneur)</b> : pousse les électrons.<br>Ordre croissant : <b>–H &lt; –CH₃ &lt; –CH₂CH₃ &lt; –CH(CH₃)₂ &lt; –C(CH₃)₃</b><br>→ Tous les <b>groupes alkyles</b> sont +I. <b>Le tert-butyle est le plus donneur</b> (le plus ramifié).<br>→ Aussi : les <b>métaux</b> (–Li, –MgX) et les <b>anions</b> (–COO⁻, –O⁻) sont +I.<br><br>⚠️ Conséquences : l'effet −I <b>stabilise les carbanions</b> et <b>augmente l'acidité</b> (ex. : CH₃COOH pKa 4,76 vs ClCH₂COOH pKa 2,86). L'effet +I <b>stabilise les carbocations</b> (tertiaire &gt; secondaire &gt; primaire &gt; CH₃⁺).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Définis l'<b>effet mésomère (M / résonance)</b>. Quels groupes sont −M et +M ?","a":"<b>EFFET MÉSOMÈRE (résonance)</b> : déplacement des électrons <b>π</b> ou des <b>doublets libres</b> le long d'un système <b>conjugué</b> (alternance σ/π).<br><br>Il est <b>beaucoup plus puissant que l'effet inductif</b>.<br><br><b>Condition</b> : il faut une <b>CONJUGAISON</b> — C=C–C=C, C=C–C=O, C=C avec atome à doublet libre (–OH, –NH₂, –Cl), ou C=C avec carbone <b>vide</b> (carbocation) ou à <b>électron célibataire</b> (radical).<br><br><b>+M (donneur par résonance)</b> : possède un <b>DOUBLET LIBRE</b> sur l'atome lié au système.<br>Ordre décroissant : <b>–O⁻ &gt; –NH₂ &gt; –NHR &gt; –NR₂ &gt; –OH &gt; –OR &gt; –NH–CO–CH₃ &gt; –Cl &gt; –Br</b><br>→ Active le cycle benzénique, oriente en <b>ORTHO / PARA</b>.<br><br><b>−M (attracteur par résonance)</b> : possède une <b>liaison multiple avec un atome plus électronégatif</b>.<br>Ordre : <b>–NO₂ &gt; –CN &gt; –CHO &gt; –CO–R &gt; –COOH &gt; –COOR &gt; –CONH₂ &gt; –SO₃H</b><br>→ Désactive le cycle benzénique, oriente en <b>MÉTA</b>.<br><br>⚠️ Les <b>HALOGÈNES</b> sont un cas particulier : <b>−I &gt; +M</b> → globalement <b>désactivants</b> mais orienteurs <b>ORTHO/PARA</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Classe ces carbocations par stabilité décroissante et explique pourquoi.","a":"<b>CH₃–C⁺(CH₃)₂ (tertiaire) &gt; CH₃–C⁺H–CH₃ (secondaire) &gt; CH₃–C⁺H₂ (primaire) &gt; CH₃⁺ (méthylique)</b><br><br><b>Deux raisons :</b><br>1. <b>Effet inductif donneur (+I)</b> des groupes alkyle → ils <b>dispersent la charge positive</b> → stabilisent.<br>2. <b>HYPERCONJUGAISON</b> : recouvrement des orbitales σ C–H <b>vicinales</b> avec l'orbitale p <b>vide</b> du carbocation → délocalisation de la charge. Plus il y a de H en α, plus c'est stable.<br><br><b>Stabilisation par résonance (beaucoup plus forte) :</b><br><b>allylique (CH₂=CH–C⁺H₂) ≈ benzylique (Ph–C⁺H₂) &gt; tertiaire</b><br>→ La charge est délocalisée sur plusieurs atomes.<br><br>⚠️ <b>Réarrangements possibles</b> : un carbocation primaire instable peut se réarranger par <b>transposition d'hydrure (H⁻)</b> ou de <b>méthyle (CH₃⁻)</b> pour donner un carbocation plus stable (ex. : 1,2-shift).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Énonce la règle de <b>Markovnikov</b> et son mécanisme. Qu'est-ce qu'une addition anti-Markovnikov ?","a":"<b>RÈGLE DE MARKOVNIKOV</b> : lors de l'addition d'un réactif <b>H–X</b> sur une double liaison <b>asymétrique</b>, l'<b>H se fixe sur le carbone le PLUS HYDROGÉNÉ</b> (celui qui porte le plus de H), et le <b>X sur le carbone le MOINS HYDROGÉNÉ</b>.<br><br><b>Mécanisme (addition électrophile, AE)</b> :<br>1. Le <b>H⁺ (électrophile)</b> attaque le <b>π</b> → formation du <b>carbocation le PLUS STABLE</b> (étape lente, déterminante)<br>2. Le nucléophile <b>X⁻</b> attaque le carbocation<br><br>Ex. : <b>CH₃–CH=CH₂ + HBr → CH₃–CHBr–CH₃</b> (2-bromopropane, <b>majoritaire</b>)<br>&nbsp;&nbsp;&nbsp;&nbsp;et <b>pas</b> CH₃–CH₂–CH₂Br<br><br><b>ANTI-MARKOVNIKOV (effet Kharasch / effet peroxyde)</b> :<br>Uniquement avec <b>HBr</b> en présence de <b>PEROXYDES (ROOR)</b> → mécanisme <b>RADICALAIRE</b>.<br>Le <b>Br•</b> attaque en premier, formant le <b>radical le plus stable</b> (secondaire) → le Br se fixe sur le carbone <b>le plus hydrogéné</b>.<br>→ <b>CH₃–CH=CH₂ + HBr (ROOR) → CH₃–CH₂–CH₂Br</b><br><br>⚠️ <b>Hydroboration-oxydation</b> (BH₃ puis H₂O₂/OH⁻) = aussi <b>anti-Markovnikov</b>, et <b>syn</b> stéréospécifique → donne l'<b>alcool primaire</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Énonce la règle de <b>Zaïtsev</b> (Saytzeff). Quand s'applique-t-elle ?","a":"<b>RÈGLE DE ZAÏTSEV</b> : lors d'une <b>ÉLIMINATION</b>, l'<b>alcène MAJORITAIRE</b> est celui qui est le <b>PLUS SUBSTITUÉ</b> (le plus grand nombre de groupes alkyle sur les carbones du C=C).<br><br>Raison : un alcène plus substitué est <b>plus stable</b> (hyperconjugaison + effet inductif donneur).<br><br>Stabilité des alcènes : <b>tétrasubstitué &gt; trisubstitué &gt; disubstitué &gt; monosubstitué &gt; éthylène</b>.<br>Et à substitution égale : <b>trans (E) &gt; cis (Z)</b>.<br><br>Ex. : déshydratation du <b>butan-2-ol</b> → <b>but-2-ène (majoritaire, disubstitué)</b> + but-1-ène (minoritaire, monosubstitué).<br><br>⚠️ <b>Exception — produit de Hofmann</b> : avec une <b>base TRÈS ENCOMBRÉE</b> (tert-butoxyde de potassium, <b>t-BuOK</b>) ou un substrat encombré, l'alcène <b>le moins substitué</b> devient majoritaire (attaque sur le H le plus accessible).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Compare les mécanismes <b>E1</b> et <b>E2</b>.","a":"<b>E2 (élimination bimoléculaire, en une étape)</b> :<br>• Cinétique : <b>v = k [substrat][base]</b> (2ᵉ ordre)<br>• <b>Concertée</b> : la base arrache le H en β <b>au même moment</b> que X⁻ part<br>• Stéréochimie : <b>ANTI-PÉRiplanaire obligatoire</b> (H et X à 180°, dans le même plan)<br>• Favorisée par : <b>base forte et encombrée</b> (t-BuOK), substrat <b>tertiaire ou secondaire</b>, solvant <b>apolaire</b>, <b>T° élevée</b><br>• <b>Pas de carbocation</b> → pas de réarrangement<br><br><b>E1 (élimination unimoléculaire, en deux étapes)</b> :<br>• Cinétique : <b>v = k [substrat]</b> (1ᵉʳ ordre)<br>• Étape 1 : départ de X⁻ → <b>carbocation</b> ; étape 2 : une base faible arrache un H en β<br>• <b>Pas de contrainte stéréochimique</b><br>• Favorisée par : <b>base faible</b> (H₂O, ROH), substrat <b>tertiaire</b> (carbocation stable), solvant <b>polaire protique</b><br>• <b>Réarrangements possibles</b> (transposition d'hydrure/méthyle)<br><br>⚠️ <b>E1 est toujours en COMPÉTITION avec SN1</b> ; <b>E2 avec SN2</b>. La chaleur (T° ↑) favorise l'<b>élimination</b> (ΔS &gt; 0).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Compare les mécanismes <b>SN1</b> et <b>SN2</b>.","a":"<b>SN2 (substitution nucléophile bimoléculaire)</b> :<br>• Cinétique : <b>v = k [substrat][Nu⁻]</b> (2ᵉ ordre)<br>• <b>UNE SEULE ÉTAPE concertée</b> — le Nu⁻ attaque par l'<b>arrière</b> pendant que X⁻ part<br>• Stéréochimie : <b>INVERSION DE WALDEN</b> (configuration inversée, R→S)<br>• Favorisée par : substrat <b>MÉTHYLIQUE ou PRIMAIRE</b> (peu encombré), <b>Nu⁻ fort</b> et peu encombré (HO⁻, CN⁻, I⁻), solvant <b>apolaire aprotique</b> (DMSO, DMF, acétone)<br>• Pas de carbocation → pas de réarrangement<br><br><b>SN1 (substitution nucléophile unimoléculaire)</b> :<br>• Cinétique : <b>v = k [substrat]</b> (1ᵉʳ ordre)<br>• <b>DEUX ÉTAPES</b> : 1) départ de X⁻ → <b>carbocation plan sp²</b> ; 2) attaque du Nu⁻<br>• Stéréochimie : <b>RACÉMISATION</b> (attaque des deux faces du carbocation plan) → mélange R + S<br>• Favorisée par : substrat <b>TERTIAIRE, allylique ou benzylique</b> (carbocation stable), <b>Nu⁻ faible</b> (H₂O, ROH), solvant <b>polaire protique</b> (eau, éthanol)<br>• <b>Réarrangements possibles</b><br><br>Moyen mnémotechnique : <b>SN1 = 1 étape lente → carbocation → racémisation · SN2 = 2ᵉ ordre → inversion</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Classe ces halogénures d'alkyle par réactivité décroissante en SN2 et en SN1.","a":"<b>EN SN2</b> (favorise le moins encombré) :<br><b>Méthyle &gt; 1aire &gt; 2aire &gt;&gt; 3aire (quasi nul)</b><br>CH₃–X &gt; CH₃CH₂–X &gt; (CH₃)₂CH–X &gt; (CH₃)₃C–X<br>Raison : l'encombrement stérique <b>bloque l'attaque dorsale</b> du nucléophile.<br><br><b>EN SN1</b> (favorise le carbocation stable) :<br><b>3aire &gt; allylique/benzylique &gt; 2aire &gt;&gt; 1aire &gt; méthyle (quasi nul)</b><br>(CH₃)₃C–X &gt; Ph–CH₂–X ≈ CH₂=CH–CH₂–X &gt; (CH₃)₂CH–X &gt; CH₃CH₂–X &gt; CH₃–X<br>Raison : la stabilité du <b>carbocation intermédiaire</b>.<br><br>⚠️ <b>Les halogénures vinyliques (CH₂=CH–X) et aryles (Ph–X) sont INERTES</b> en SN1 ET en SN2 (liaison C–X renforcée par résonance + carbone sp² inaccessible).","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Classe les halogènes par qualité de groupe partant (leaving group).","a":"<b>I⁻ &gt; Br⁻ &gt; Cl⁻ &gt;&gt; F⁻</b><br><br>Raison : un bon groupe partant est la <b>BASE CONJUGUÉE LA PLUS FAIBLE</b> (= l'acide le plus fort).<br>Acides halogénés : <b>HI &gt; HBr &gt; HCl &gt;&gt; HF</b> (force décroissante)<br>→ Donc leurs bases conjuguées : <b>I⁻ &lt; Br⁻ &lt; Cl⁻ &lt;&lt; F⁻</b> en basicité → <b>I⁻ est le meilleur partant</b>.<br><br>I⁻ est aussi le <b>meilleur nucléophile</b> en solvant polaire protique (le plus polarisable, le moins solvaté).<br><br>⚠️ En solvant <b>apolaire aprotique</b>, l'ordre des nucléophiles s'inverse : <b>F⁻ &gt; Cl⁻ &gt; Br⁻ &gt; I⁻</b> (car F⁻ n'est plus solvaté).<br><br>Autres bons groupes partants : <b>–OTs (tosylate), –OMs (mésylate), –OH₂⁺</b> (après protonation de –OH). ⚠️ <b>–OH et –OR sont de TRÈS MAUVAIS partants</b> — il faut les protonner d'abord.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Quelles sont les réactions de <b>réduction</b> à connaître ? Que réduit chaque réactif ?","a":"<b>LiAlH₄ (hydrure d'aluminium et de lithium)</b> — <b>RÉDUCTEUR FORT</b> :<br>• Acide carboxylique → <b>alcool primaire</b><br>• Ester → <b>2 alcools</b> (primaire issu de l'acide + alcool du groupe alkyle)<br>• Aldéhyde → <b>alcool primaire</b><br>• Cétone → <b>alcool secondaire</b><br>• Amide → <b>amine</b><br>• Nitrile → <b>amine primaire</b><br>• Époxyde → alcool<br>• ❌ <b>Ne réduit PAS les C=C</b> (sauf si conjuguées avec C=O)<br>• ⚠️ Incompatible avec H₂O et les alcools (réaction violente) → solvant = <b>éther anhydre</b><br><br><b>NaBH₄ (borohydrure de sodium)</b> — <b>RÉDUCTEUR DOUX</b> :<br>• Aldéhyde → <b>alcool primaire</b> ✅<br>• Cétone → <b>alcool secondaire</b> ✅<br>• ❌ <b>NE réduit PAS</b> les acides carboxyliques, les esters, les amides, les nitriles<br>• Compatible avec l'eau et les alcools (utilisé dans le méthanol)<br><br><b>H₂ / Pd, Pt ou Ni (hydrogénation catalytique)</b> :<br>• Réduit les <b>C=C, C≡C</b>, les <b>C=O</b> (aldéhyde → alcool 1aire), les <b>NO₂</b> → NH₂, les nitriles → amines<br>• <b>Syn-addition</b> stéréospécifique<br>• ❌ <b>Ne réduit PAS</b> les COOH, esters, amides<br><br><b>DIBAL-H (diisobutylaluminium hydrure)</b> à <b>−78 °C</b> :<br>• Ester / nitrile → <b>aldéhyde</b> (arrêt à l'aldéhyde)<br><br>⚠️ Réactif de choix pour <b>COOH → alcool</b> : <b>LiAlH₄ uniquement</b>.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Quels réactifs <b>oxydent</b> un alcool primaire en aldéhyde sans aller jusqu'à l'acide ?","a":"<b>Un alcool primaire s'oxyde en DEUX étapes :</b><br>alcool 1aire → <b>aldéhyde</b> → <b>acide carboxylique</b><br><br>Pour <b>S'ARRÊTER à l'aldéhyde</b>, il faut un réactif <b>sélectif et doux</b> :<br>• <b>PCC (chlorochromate de pyridinium)</b> dans CH₂Cl₂ → <b>aldéhyde</b> ✅ (réactif de référence en QCM)<br>• <b>PDC (dichromate de pyridinium)</b><br>• <b>Réactif de Collins</b> (CrO₃·2 pyridine)<br>• <b>Oxydation de Swern</b> (DMSO / (COCl)₂ / Et₃N, à −60 °C)<br>• <b>Dess–Martin periodinane (DMP)</b><br><br>⚠️ Pour aller <b>jusqu'à l'acide</b> :<br>• <b>KMnO₄</b> (permanganate) en milieu acide ou basique → acide carboxylique<br>• <b>K₂Cr₂O₇ / H₂SO₄</b> (mélange chromique, réactif de Jones) → acide carboxylique<br>• <b>CrO₃ / H₃O⁺</b> → acide<br><br><b>Alcool SECONDAIRE</b> → <b>cétone</b> (s'arrête là, avec n'importe quel oxydant).<br><b>Alcool TERTIAIRE</b> → <b>PAS D'OXYDATION</b> (pas de H sur le carbone portant le OH).<br><br>Test de distinction : le <b>réactif de Tollens</b> ([Ag(NH₃)₂]⁺) oxyde uniquement les <b>aldéhydes</b> → <b>miroir d'argent</b>. La <b>liqueur de Fehling</b> donne un <b>précipité rouge brique</b> (Cu₂O) avec les aldéhydes.","t":"chimie-2026 EXAM-2026"},{"q":"<b>ORGANIQUE</b> — Quels sont les <b>3 types de carbones</b> en RMN et les déplacements chimiques typiques (rappel de base) ?","a":"⚠️ <b>Ce point n'était PAS dans l'examen 2026</b> — à ne pas prioritiser.<br><br>Pour information :<br>• <b>sp³</b> C–H : δ = 0,9–2 ppm<br>• <b>sp³</b> C lié à un hétéroatome (O, N, X) : δ = 3–4,5 ppm<br>• <b>sp²</b> alcénique C–H : δ = 4,5–6,5 ppm<br>• <b>aromatique</b> C–H : δ = 6,5–8 ppm<br>• <b>aldéhyde</b> C–H : δ = 9–10 ppm<br>• <b>COOH</b> : δ = 10–12 ppm<br><br>Concentre-toi plutôt sur l'<b>atomistique</b> et la <b>stéréochimie</b>, qui représentent <b>100 %</b> du QCM 2026.","t":"chimie-2026 EXAM-2026 A-FAIBLE-PRIORITE"},{"q":"<b>CHIMIE 2026 — MOTIF DE RÉCURRENCE</b> : les QCM se répètent d'une année à l'autre en changeant SEULEMENT l'élément. Donne 2 exemples.","a":"⚠️ <b>FAIT VÉRIFIÉ sur les examens 2023 et 2026</b> : <b>≈80 %</b> des questions de chimie sont des <b>reprises</b> avec seulement l'élément changé.<br><br><b>Exemple 1 — atomistique :</b><br>• 2023 : « Quelle est la configuration électronique du <b>silicium (Si, Z=14)</b> ou du <b>germanium (Ge, Z=32)</b> ? »<br>• 2026 : même question mais sur l'<b>azote (N, Z=7)</b> ou le <b>phosphore (P, Z=15)</b><br>→ Mêmes distracteurs, même structure.<br><br><b>Exemple 2 — isotopes :</b><br>• 2023 : calcul / définition sur le <b>zinc (Zn)</b><br>• 2026 : même question sur le <b>brome (Br)</b><br><br><b>CONSÉQUENCE STRATÉGIQUE :</b><br>1. Récupère <b>TOUTES</b> les annales disponibles (2023, 2024, 2025, 2026).<br>2. <b>Mémorise les ÉNONCÉS</b>, pas juste les réponses — l'énoncé revient, la réponse change avec l'élément.<br>3. Pour chaque élément cité dans les annales, <b>apprends sa configuration électronique, ses isotopes et sa position dans le tableau périodique</b>.<br>4. Entraîne-toi à <b>appliquer la règle</b> plutôt qu'à mémoriser un résultat numérique.","t":"chimie-2026 EXAM-2026 STRATEGIE"},{"q":"<b>CHIMIE 2026 — CE QUI N'EST PAS TOMBÉ</b> : quels chapitres classiques du bac sont absents de l'examen FMDC S1 ?","a":"⚠️ <b>VÉRIFIÉ sur le QCM Chimie N2026 (40 questions) : ZÉRO question</b> sur :<br>• <b>pH, acides/bases, tampons, titrages, courbes de neutralisation</b><br>• <b>Le concept de mole, masse molaire, concentrations, dilutions, calculs stœchiométriques</b><br>• <b>Cinétique chimique, vitesse de réaction, ordre de réaction</b><br>• <b>Thermodynamique, enthalpie, entropie, énergie libre de Gibbs</b><br>• <b>Piles, électrochimie, réactions d'oxydoréduction</b><br>• <b>Solutions, conductivité</b><br><br><b>CE QUI TOMBE À LA PLACE :</b><br>• ~45 % <b>ATOMISTIQUE</b> (configurations électroniques, nombres quantiques, Klechkowski/Pauli/Hund, tableau périodique et tendances, hybridation, types de liaisons, isotopes, complexes)<br>• ~55 % <b>ORGANIQUE + STÉRÉOCHIMIE</b> (nomenclature IUPAC, isomérie, R/S, Cram/Newman/Fischer, énantiomères/diastéréoisomères/méso, Z/E, érythro/thréo, effets I et M, Markovnikov, Zaïtsev, SN1/SN2/E1/E2, réductions)<br><br><b>CONSÉQUENCE :</b> ne gaspille pas tes 15 h/semaine sur le pH et les calculs de mole. Toute l'énergie va sur l'<b>atomistique</b> et la <b>stéréochimie</b>.","t":"chimie-2026 EXAM-2026 STRATEGIE"}]},{"id":"genetique-S1-2026","nom":"🧬 Génétique","src":"Examen N2026","ordre":3,"module":"M111","desc":"Q1–Q40 de l'examen 2026","cards":[{"q":"⚠️ **AVERTISSEMENT** — d9a dyal had l-deck Génétique. 9ra hadchi 9bel.","a":"<b>Ce deck est construit à partir des <b>40 QCM RÉELS de l'épreuve « Biologie Moléculaire et Génétique » de Janvier 2026</b></b> (Pr H. DEHBI et Pr T. ROCHD), que j'ai lus dans `BIOLOGIE N2026.pdf` (chunks 1 et 2).<br><br>⚠️ <b>MAIS :</b><br>• Les PDFs de <b>Chimie N2026</b> et <b>Biochimie N2026</b> portaient des <b>corrections manuscrites</b> → j'ai lu les vraies réponses.<br>• Le PDF de <b>BIOLOGIE N2026</b> : les corrections manuscrites <b>n'apparaissent PAS dans l'extraction de texte</b> (un scan manuscrit ne se convertit pas en texte).<br><br>→ <b>Les réponses de ce deck sont DONC LES MIENNES</b>, dérivées de la génétique standard. Elles sont <b>fiables à ~90 %</b> mais <b>DOIVENT ÊTRE VÉRIFIÉES</b>.<br><br><b>COMMENT VÉRIFIER (5 min) :</b><br>1. Ouvre `BIOLOGIE N2026.pdf` sur ton téléphone<br>2. Regarde les <b>cases noircies / cochées au stylo</b><br>3. Si une carte de ce deck contredit le corrigé, <b>corrige-la dans Anki</b> (bouton « Modifier »)<br><br>⚠️ Les cartes où je suis <b>le moins sûr</b> portent le tag <b>`A-VERIFIER`</b>. Commence par vérifier celles-là.","t":"genetique-2026 EXAM-2026 STRATEGIE"},{"q":"Q1 — Quelle(s) molécule(s) est/sont <b>porteuse(s) de l'information génétique</b> ? (ADN mitochondrial · Topo-isomérase · Hélicase · ARNm · ADN polymérase)","a":"<b>✅ ADN mitochondrial</b> et <b>✅ ARNm</b><br><br><b>Pourquoi :</b><br>• <b>ADN mitochondrial</b> : l'ADNmt est un <b>génome propre</b> (16 569 pb, circulaire, 37 gènes) transmis par <b>voie MATERNELLE</b> → il porte bien de l'information génétique<br>• <b>ARNm</b> : c'est la <b>copie de travail</b> du gène — il porte l'information sous forme de <b>codons</b> qui seront traduits en protéine<br><br><b>❌ Topo-isomérase, Hélicase, ADN polymérase</b> : ce sont des <b>ENZYMES (protéines)</b>. Elles <b>AGISSENT SUR</b> l'information génétique (elles la répliquent, la déroulent, la découpent) mais <b>NE LA PORTENT PAS</b>.<br><br>⚠️ <b>Piège classique :</b> ne pas confondre <b>« support de l'information »</b> (ADN, ARN) et <b>« machinerie qui la manipule »</b> (enzymes).","t":"genetique-2026 EXAM-2026"},{"q":"Q2 — Laquelle/lesquelles de ces molécules <b>NE sont PAS</b> porteuses de l'information génétique ? (fragments d'Okazaki · ADN répétitif · Plasmide · ADN ligase · génome viral)","a":"<b>✅ Fragments d'Okazaki</b> et <b>✅ ADN ligase</b><br><br><b>Pourquoi :</b><br>• <b>Fragments d'Okazaki</b> : ⚠️ <b>PIÈGE</b> — ce sont bien des <b>fragments d'ADN</b>, mais ce sont des <b>INTERMÉDIAIRES TRANSITOIRES de la réplication</b> du brin retardé. Ils ne <b>portent pas d'information génétique autonome</b> — ils sont destinés à être <b>ligaturés</b> pour reconstituer le brin. <i>(Réponse discutée — voir tag)</i><br>• <b>ADN ligase</b> : c'est une <b>ENZYME (protéine)</b> → jamais porteuse d'information ✅ sans ambiguïté<br><br><b>❌ SONT porteurs :</b><br>• <b>ADN répétitif</b> : c'est de l'<b>ADN</b> (séquences satellite, minisatellite, microsatellite, ALU, LINE) → porteur, même s'il est souvent non codant<br>• <b>Plasmide</b> : <b>ADN circulaire extrachromosomique</b> bactérien → porte des gènes (résistance aux antibiotiques) et <b>s'autoréplique</b><br>• <b>Génome viral</b> : <b>ADN ou ARN</b> viral → porte l'information du virus","t":"genetique-2026 EXAM-2026 A-VERIFIER"},{"q":"Q3 — Le <b>fragment d'Okazaki</b> : qu'est-ce que c'est exactement ?","a":"<b>✅ B — C'est un ADN</b> et <b>✅ E — C'est un désoxy-ribonucléotide</b><br><br><b>DÉFINITION :</b> court fragment d'<b>ADN</b> (100–200 nucléotides chez les eucaryotes, 1000–2000 chez E. coli) synthétisé sur le <b>BRIN RETARDÉ (brin discontinu)</b> lors de la réplication.<br><br><b>Pourquoi existent-ils :</b><br>• L'<b>ADN polymérase ne synthétise QUE dans le sens 5' → 3'</b><br>• Les deux brins de l'ADN sont <b>ANTIPARALLÈLES</b><br>• À la fourche de réplication, un seul brin (le <b>brin avancé / leading</b>) peut être synthétisé en <b>continu</b><br>• L'autre (le <b>brin retardé / lagging</b>) doit être synthétisé en <b>morceaux</b>, à rebours de l'ouverture de la fourche → ce sont les <b>fragments d'Okazaki</b><br><br><b>❌ A — « C'est un ARN »</b> : FAUX. ⚠️ Mais attention : chaque fragment d'Okazaki <b>COMMENCE par une AMORCE d'ARN</b> (≈10 nucléotides) synthétisée par la <b>primase (ADN polymérase α-primase)</b>. Cette amorce est ensuite <b>retirée</b> (par la RNase H / FEN1 chez les eucaryotes, ADN pol I chez E. coli) et <b>remplacée par de l'ADN</b>.<br><b>❌ C — « C'est une enzyme »</b> : FAUX, c'est un <b>produit</b>, pas un catalyseur.<br><b>❌ D — « C'est un ribonucléotide »</b> : FAUX — un ribonucléotide contient du <b>ribose</b> (ARN). L'Okazaki est un <b>désoxyribonucléotide</b> (ADN).<br><br><b>Étapes de maturation :</b> amorce ARN → élongation par l'<b>ADN pol δ</b> → retrait de l'amorce → comblement du trou → <b>ligature par l'ADN LIGASE I</b>.","t":"genetique-2026 EXAM-2026"},{"q":"Q4 — Dans la <b>TRANSCRIPTION</b> : (ARN pol n'a pas besoin d'amorce · a besoin d'une amorce ADN · l'ARNm a le même sens que le brin matrice · la transcription a lieu dans le cytoplasme · l'ARN pol synthétise les ARNt)","a":"<b>✅ A — L'ARN polymérase N'A PAS BESOIN D'AMORCE</b><br><b>✅ E — L'ARN polymérase permet la synthèse des ARNt</b><br><br><b>A ✅ — Différence FONDAMENTALE avec la réplication :</b><br>• <b>ADN polymérase</b> : a <b>OBLIGATOIREMENT besoin d'une amorce (primer)</b> — un court ARN fourni par la <b>primase</b> avec un <b>3'-OH libre</b><br>• <b>ARN polymérase</b> : <b>peut démarrer DE NOVO</b> (sans amorce) — elle initie la synthèse directement sur le promoteur<br>→ C'est pourquoi il n'y a <b>pas de fragments d'Okazaki</b> dans la transcription.<br><br><b>E ✅ —</b> Chez les eucaryotes :<br>• <b>ARN polymérase I</b> → <b>ARNr</b> 28S, 18S, 5.8S (dans le <b>nucléole</b>)<br>• <b>ARN polymérase II</b> → <b>ARNm</b> + la plupart des <b>snARN</b> et des <b>miRNA</b> ⚠️ la plus importante, sensible à l'<b>α-amanitine</b><br>• <b>ARN polymérase III</b> → <b>ARNt</b> + <b>ARNr 5S</b> + snARN U6<br><br><b>❌ B —</b> « besoin d'une amorce ADN » : FAUX (voir A).<br><b>❌ C — L'ARNm a le même sens que le brin MATRICE</b> : <b>FAUX, PIÈGE MAJEUR</b> ⚠️<br>• Le <b>brin MATRICE (brin transcrit, template, brin antisens)</b> est lu en <b>3' → 5'</b> ; l'ARNm synthétisé est <b>COMPLÉMENTAIRE et ANTIPARALLÈLE</b> à lui.<br>• Le <b>brin NON-MATRICE (brin codant, brin sens, « coding strand »)</b> a <b>LA MÊME SÉQUENCE que l'ARNm</b> (avec T au lieu de U).<br>→ Donc l'ARNm a le même sens que le <b>brin CODANT</b>, <b>PAS</b> que le brin matrice.<br><b>❌ D —</b> « la transcription a lieu dans le cytoplasme » : FAUX chez les <b>EUCARYOTES</b> → elle a lieu dans le <b>NOYAU</b>. ⚠️ Elle a lieu dans le cytoplasme chez les <b>PROCARYOTES</b> (pas de noyau) — et la transcription/traduction y sont <b>couplées</b>.","t":"genetique-2026 EXAM-2026"},{"q":"Q5 — À propos de l'<b>ARNr</b> et du ribosome : (obtenu par transcription · obtenu par traduction · la traduction de l'ARNr donne les protéines ribosomiques · une sous-unité = ARNr + protéines · un ribosome complet = 2 sous-unités)","a":"<b>✅ A — L'ARNr est obtenu par TRANSCRIPTION</b><br><b>✅ D — Une sous-unité ribosomale est constituée d'un ARNr + des protéines</b><br><b>✅ E — Un ribosome complet est constitué de 2 sous-unités ribosomales</b><br><br><b>A ✅ —</b> L'ARNr est un <b>ARN</b> : comme tous les ARN, il est produit par <b>TRANSCRIPTION</b> de l'ADN par l'<b>ARN polymérase I</b> (pour 28S, 18S, 5.8S) dans le <b>nucléole</b>.<br><br><b>D ✅ / E ✅ — Composition du ribosome eucaryote (80S) :</b><br>• <b>Petite sous-unité 40S</b> : <b>ARNr 18S</b> + <b>33 protéines ribosomiques (RPS)</b><br>• <b>Grande sous-unité 60S</b> : <b>ARNr 28S + 5,8S + 5S</b> + <b>49 protéines ribosomiques (RPL)</b><br>• <b>Ribosome complet 80S</b> = 40S + 60S (S = unité <b>Svedberg</b>, coefficient de sédimentation — <b>NON ADDITIF</b> ⚠️)<br>• <b>Procaryote : 70S</b> = 30S (ARNr 16S + 21 protéines) + 50S (ARNr 23S + 5S + 31 protéines)<br><br>⚠️ Le ribosome est un <b>RIBOZYME</b> : l'activité <b>peptidyl-transférase</b> (formation de la liaison peptidique) est portée par l'<b>ARNr 28S</b>, PAS par une protéine.<br><br><b>❌ B — « obtenu par traduction »</b> : FAUX. La traduction produit des <b>PROTÉINES</b>, jamais des ARN.<br><b>❌ C — « La traduction de l'ARNr donne les protéines ribosomiques »</b> : <b>FAUX, PIÈGE</b> ⚠️<br>• L'<b>ARNr N'EST JAMAIS TRADUIT</b> — il n'a <b>pas de cadre de lecture</b>, il est <b>non codant</b>.<br>• Les <b>protéines ribosomiques</b> sont codées par des <b>gènes NUCLÉAIRES DISTINCTS</b>, transcrites en <b>ARNm</b>, traduites <b>dans le cytoplasme</b>, puis <b>importées dans le nucléole</b> pour s'assembler avec l'ARNr.","t":"genetique-2026 EXAM-2026"},{"q":"Q6 — Une <b>SONDE</b> (moléculaire) : (antiparallèle au fragment recherché · parallèle · capable de s'hybrider au polynucléotide étudié · capable de s'hybrider à la protéine recherchée · une enzyme)","a":"<b>✅ A — Elle est ANTIPARALLÈLE au fragment recherché</b><br><b>✅ C — Elle est capable de rechercher et de s'hybrider au fragment du polynucléotide étudié</b><br><br><b>DÉFINITION :</b> une <b>sonde moléculaire</b> est un <b>court fragment d'acide nucléique (ADN ou ARN), simple brin, de séquence COMPLÉMENTAIRE</b> de la séquence cible que l'on veut détecter. Elle est <b>marquée</b> pour être repérable.<br><br><b>A ✅ — Pourquoi antiparallèle :</b> l'hybridation suit la règle de <b>Watson-Crick</b> : les deux brins s'apparient en <b>antiparallèle</b> (5'→3' contre 3'→5'). Une sonde <b>5'-ATGC-3'</b> s'hybride avec la cible <b>3'-TACG-5'</b> (= <b>5'-GCAT-3'</b>).<br><br><b>Types de marquage :</b><br>• <b>Radioactif</b> : <b>³²P</b> (dATP α-³²P) → détection par autoradiographie. Sensible mais dangereux.<br>• <b>Fluorescent</b> : FITC, Cy3, Cy5, rhodamine → <b>FISH</b><br>• <b>Enzymatique / non isotopique</b> : <b>biotine</b> (détectée par streptavidine-peroxydase) ou <b>digoxigénine (DIG)</b> (détectée par anticorps anti-DIG) → <b>ABC</b> (Avidin-Biotin-Complex)<br><br><b>Techniques utilisant des sondes :</b><br>• <b>Southern blot</b> → détecte l'<b>ADN</b><br>• <b>Northern blot</b> → détecte l'<b>ARN</b><br>• <b>Western blot</b> → détecte les <b>PROTÉINES</b> ⚠️ mais ici la « sonde » est un <b>ANTICORPS</b>, pas un acide nucléique<br>• <b>FISH</b>, <b>PCR en temps réel (TaqMan, SYBR)</b>, <b>puces à ADN (ACPA)</b>, <b>hybridation in situ</b><br><br><b>❌ B — « parallèle »</b> : FAUX (voir A).<br><b>❌ D — « s'hybrider à la protéine recherchée »</b> : FAUX. Une <b>sonde nucléique</b> s'hybride à un <b>acide nucléique</b>. Pour une protéine, on utilise un <b>ANTICORPS</b> (Western blot, immunomarquage, ELISA).<br><b>❌ E — « une enzyme »</b> : FAUX, c'est un <b>acide nucléique</b>.","t":"genetique-2026 EXAM-2026"},{"q":"Q7 — Chez l'<b>HOMME</b> : (chromosomes = ARN · 46 paires · 23 paires · l'un est ADN et l'autre ARN · l'un vient du père, l'autre de la mère)","a":"<b>✅ C — Le génome est constitué de 23 PAIRES de chromosomes</b><br><b>✅ E — Dans chaque paire, l'un vient du père et l'autre de la mère</b><br><br><b>C ✅ —</b> Chez l'Homme :<br>• <b>2n = 46 CHROMOSOMES</b> = <b>23 PAIRES</b><br>• <b>22 paires d'AUTOSOMES</b> (numérotées 1 à 22, par taille décroissante)<br>• <b>1 paire de GONOSOMES (chromosomes sexuels)</b> : <b>XX</b> (femme) ou <b>XY</b> (homme)<br>• <b>n = 23</b> dans les <b>gamètes</b> (haploïde)<br>⚠️ <b>PIÈGE DE L'ÉNONCÉ :</b> « <b>46 paires</b> » (réponse B) est <b>FAUX</b> — il y a <b>46 CHROMOSOMES</b>, soit <b>23 PAIRES</b>. C'est la confusion la plus fréquente.<br><br><b>E ✅ —</b> Chaque paire = <b>1 chromosome d'origine PATERNELLE</b> (via le spermatozoïde) + <b>1 chromosome d'origine MATERNELLE</b> (via l'ovocyte). Ce sont des <b>CHROMOSOMES HOMOLOGUES</b> : même taille, même position du centromère, <b>mêmes loci géniques</b> — mais <b>pas nécessairement les mêmes ALLÈLES</b>.<br><br><b>❌ A — « Les chromosomes humains sont de l'ARN »</b> : FAUX. Les chromosomes sont de l'<b>ADN</b> (double brin, linéaire) associé à des <b>histones</b> = <b>CHROMATINE</b>.<br><b>❌ D — « l'un est ADN, l'autre ARN »</b> : FAUX, les deux homologues sont de l'<b>ADN</b>.<br><br>⚠️ <b>Exception à connaître :</b> les <b>MITOCHONDRIES</b> contiennent leur propre <b>ADN (ADNmt)</b>, circulaire, <b>16 569 pb, 37 gènes</b>, transmis <b>UNIQUEMENT PAR LA MÈRE</b> (hérédité <b>maternelle / cytoplasmique</b>) → ne suit <b>pas</b> les lois de Mendel.","t":"genetique-2026 EXAM-2026"},{"q":"Q8 — « Multiplication <b>in vitro</b> d'un être vivant en grand nombre d'exemplaires <b>identiques</b> » — de quoi s'agit-il ?","a":"<b>✅ D — UN CLONAGE</b><br><br><b>DÉFINITION DU CLONAGE :</b> production, <b>in vitro</b> ou <b>in vivo</b>, d'un <b>grand nombre de copies IDENTIQUES</b> (génétiquement) d'un organisme, d'une cellule, d'un tissu ou d'un fragment d'ADN.<br><br>⚠️ <b>Le mot-clé de l'énoncé est « IDENTIQUES »</b> → ça élimine tout ce qui mélange ou amplifie sans copier à l'identique.<br><br><b>Types de clonage :</b><br>• <b>CLONAGE MOLÉCULAIRE (clonage d'ADN)</b> : insertion d'un fragment d'ADN dans un <b>VECTEUR</b> (plasmide, cosmide, phage, BAC, YAC) → introduction dans une <b>bactérie hôte</b> (E. coli) → multiplication → obtention de millions de copies identiques<br>• <b>CLONAGE CELLULAIRE</b> : à partir d'<b>une seule cellule</b> → colonie de cellules génétiquement identiques (lignées cellulaires, clones d'hybridomes)<br>• <b>CLONAGE REPRODUCTIF</b> : transfert nucléaire (ex. : la brebis <b>Dolly</b>, 1996)<br>• <b>CLONAGE THÉRAPEUTIQUE</b> : production de <b>cellules souches embryonnaires</b> compatibles<br><br><b>❌ POURQUOI PAS LES AUTRES :</b><br>• <b>A — Une RÉPLICATION</b> : c'est la <b>COPIE de l'ADN À L'INTÉRIEUR d'une cellule</b>, <b>IN VIVO</b> (ou in vitro en PCR). Ce n'est <b>pas</b> la « multiplication d'un être vivant ».<br>• <b>B — Un SÉQUENÇAGE</b> : c'est la <b>LECTURE de l'ordre des nucléotides</b> (Sanger, NGS). Ça ne multiplie rien.<br>• <b>C — Une MÉIOSE</b> : c'est la division qui <b>RÉDUIT de moitié</b> le nombre de chromosomes et qui <b>CRÉE de la DIVERSITÉ</b> (crossing-over, ségrégation indépendante) → produit des cellules <b>DIFFÉRENTES</b>, pas identiques. C'est l'<b>OPPOSÉ</b> du clonage.<br>• <b>E — Une PCR</b> : ⚠️ <b>piège</b>. La PCR est bien une <b>amplification IN VITRO</b>, mais elle amplifie un <b>FRAGMENT d'ADN</b>, <b>PAS un « être vivant »</b>. Et l'énoncé dit « être vivant » → <b>clonage</b>.","t":"genetique-2026 EXAM-2026"},{"q":"Q9 — Lesquels de ces codons sont des <b>codons STOP</b> ? (UAA · UAG · AUG · UGG · UGA)","a":"<b>✅ UAA · ✅ UAG · ✅ UGA</b> — les <b>TROIS</b> codons stop.<br><br>⚠️ <b>À APPRENDRE PAR CŒUR.</b> Moyen mnémotechnique :<br>• <b>UAA</b> = « <b>U</b>ne <b>A</b>utre <b>A</b>nnée »<br>• <b>UAG</b> = « <b>U</b>n <b>A</b>utre <b>G</b>ars » (surnom : <b>AMBRE / amber</b>)<br>• <b>UGA</b> = « <b>U</b>n <b>G</b>rand <b>A</b>dieu » (surnom : <b>OPALE / opal</b>)<br>• <b>UAA</b> surnom : <b>OCRE / ochre</b><br><br>Le plus simple : « <b>UAA, UAG, UGA</b> » → <b>U-A / U-A / U-G</b>, les 3 commencent par <b>U</b> et <b>aucun ne contient de C</b>.<br><br><b>❌ AUG</b> : c'est le <b>CODON D'INITIATION (START)</b> ⚠️ — il code la <b>MÉTHIONINE (Met)</b> chez les eucaryotes (et la <b>N-formyl-méthionine, fMet</b> chez les procaryotes). C'est le <b>premier acide aminé</b> de toute chaîne polypeptidique naissante.<br><b>❌ UGG</b> : code le <b>TRYPTOPHANE (Trp / W)</b>. ⚠️ Le Trp est le <b>SEUL acide aminé codé par UN SEUL codon</b> (avec la Met).<br><br><b>❌ Les codons stop NE CODENT AUCUN ACIDE AMINÉ.</b> Ils sont reconnus par des <b>FACTEURS DE TERMINAISON (RF1, RF2, RF3 chez les procaryotes ; eRF1 chez les eucaryotes)</b>, <b>PAS par un ARNt</b>.<br>→ Ils déclenchent l'<b>hydrolyse de la liaison ester entre le polypeptide et l'ARNt du site P</b> → <b>libération de la protéine</b> → <b>dissociation du ribosome</b>.","t":"genetique-2026 EXAM-2026"},{"q":"Q10 — Qu'est-ce qui <b>NE FAIT PAS partie</b> de la RÉPLICATION ? (ARN polymérase · ADN polymérase · Excision-Épissage · Maturation du transcrit · ARNt)","a":"<b>✅ A — ARN polymérase</b><br><b>✅ C — Excision–Épissage</b><br><b>✅ D — Maturation du transcrit</b><br><b>✅ E — ARNt</b><br><br><b>SEUL B (ADN polymérase) FAIT PARTIE de la réplication.</b><br><br><b>Pourquoi les 4 autres N'EN FONT PAS partie :</b><br>• <b>A — ARN polymérase</b> : c'est l'enzyme de la <b>TRANSCRIPTION</b> (ADN → ARN). ⚠️ Ne pas confondre avec la <b>PRIMASE</b> (qui est une <b>ARN polymérase ADN-dépendante</b> spécifique, = <b>ADN pol α-primase</b> chez les eucaryotes) — <b>elle</b>, elle fait bien partie de la réplication (elle synthétise les amorces).<br>• <b>C — Excision–Épissage (splicing)</b> : c'est une étape de la <b>MATURATION de l'ARNm</b> (post-transcriptionnelle) — retrait des <b>INTRONS</b>, jonction des <b>EXONS</b> par le <b>spliceosome</b> (snRNP U1, U2, U4, U5, U6). Ça concerne l'<b>ARN</b>, pas l'ADN.<br>• <b>D — Maturation du transcrit</b> : terme générique = <b>coiffe 5' (m⁷Gppp) + polyadénylation 3' (queue poly-A, ~200 A) + épissage</b>. C'est de la <b>post-TRANSCRIPTION</b>.<br>• <b>E — ARNt</b> : c'est l'<b>ADAPTATEUR de la TRADUCTION</b> (apporte les acides aminés au ribosome). ⚠️ Il intervient bien dans la réplication <b>INDIRECTEMENT</b> (toutes les enzymes de la réplication sont des protéines traduites via des ARNt), mais <b>PAS dans le mécanisme lui-même</b>.<br><br><b>✅ B — ADN polymérase</b> : <b>L'ENZYME CENTRALE DE LA RÉPLICATION</b>.<br>• <b>Eucaryotes</b> : <b>ADN pol α</b> (amorce + début), <b>ADN pol δ</b> (brin retardé, <b>principale</b>), <b>ADN pol ε</b> (brin avancé), <b>ADN pol β</b> (réparation), <b>ADN pol γ</b> (ADN mitochondrial)<br>• <b>Procaryotes</b> : <b>ADN pol III</b> (élongation, principale), <b>ADN pol I</b> (retire les amorces ARN + comble), <b>ADN pol II</b> (réparation)<br>• <b>Propriétés</b> : synthèse <b>5' → 3'</b> uniquement · nécessite une <b>amorce avec 3'-OH libre</b> · activité <b>exonucléasique 3'→5'</b> (<b>relecture / proofreading</b> → fidélité ~10⁻⁹) · ADN pol I a aussi une activité <b>5'→3'</b> (retire les amorces)<br><br>⚠️ <b>PIÈGE :</b> « Excision » existe aussi dans la <b>RÉPARATION de l'ADN</b> (<b>NER</b> = Nucleotide Excision Repair, <b>BER</b> = Base Excision Repair). Mais l'énoncé dit « <b>Excision–Épissage</b> », qui est le terme <b>spécifique de l'épissage de l'ARN</b> → post-transcriptionnel.","t":"genetique-2026 EXAM-2026"},{"q":"Q11 — Les <b>VECTEURS</b> (de clonage) : (molécules d'ADN capables de s'autorépliquer · enzymes de restriction · segments d'ADN/ARN obtenus par synthèse chimique · un cosmide = plasmide + séquence COS d'un bactériophage · un cosmide = plasmide + protéine)","a":"<b>✅ A — Ce sont des molécules d'ADN capables de S'AUTORÉPLIQUER</b><br><b>✅ D — Un cosmide est un mélange entre un plasmide et la séquence COS d'un bactériophage</b><br><br><b>DÉFINITION :</b> un <b>VECTEUR</b> est une molécule d'<b>ADN capable de se RÉPLIQUER DE FAÇON AUTONOME</b> dans une cellule hôte, et dans laquelle on peut <b>INSÉRER un fragment d'ADN étranger</b> pour le <b>cloner</b> (le multiplier) ou l'<b>exprimer</b>.<br><br><b>⚠️ Les 4 CARACTÉRISTIQUES OBLIGATOIRES d'un bon vecteur :</b><br>1. Une <b>ORIGINE DE RÉPLICATION (ori)</b> → permet la <b>réplication autonome</b><br>2. Un ou plusieurs <b>SITES UNIQUES DE RESTRICTION</b> (dans une <b>MCS / polylinker</b>) → pour insérer le fragment<br>3. Un <b>GÈNE DE RÉSISTANCE à un antibiotique</b> (ampᴿ, tetᴿ, kanᴿ) → <b>marqueur de sélection</b><br>4. Une <b>PETITE TAILLE</b> → plus stable, plus facile à manipuler<br><br><b>D ✅ — LES PRINCIPAUX VECTEURS :</b><br>• <b>PLASMIDE</b> : ADN <b>circulaire</b> bactérien extrachromosomique, <b>2–10 kb</b>, <b>10–20 copies</b> (ou plus si plasmide « relaxé »). Ex. : <b>pBR322</b> (4361 pb, ampᴿ + tetᴿ), <b>pUC19</b> (lacZ' → <b>sélection bleu/blanc</b>)<br>• <b>PHAGE λ (lambda)</b> : virus bactérien, ADN linéaire <b>48,5 kb</b>, insert <b>9–23 kb</b>. La région centrale est <b>non essentielle</b> → on la remplace par l'insert.<br>• <b>COSMIDE</b> ⚠️ = <b>PLASMIDE + séquences COS du phage λ</b> (<b>cohesive ends sites</b>). Taille <b>5–7 kb</b>, insert <b>30–45 kb</b>. Les sites <b>COS</b> permettent l'<b>EMPAQUETAGE IN VITRO</b> dans des capsides de phage → infection de E. coli très efficace. Une fois dans la bactérie, il se <b>circularise</b> et se réplique comme un <b>plasmide</b> (il ne contient <b>AUCUN gène de phage</b>).<br>• <b>M13</b> : phage filamenteux → produit de l'<b>ADN simple brin</b> (utilisé pour le séquençage et la mutagenèse dirigée)<br>• <b>BAC</b> (Chromosome Artificiel Bactérien) : basé sur le <b>plasmide F</b>, insert <b>100–300 kb</b> → utilisé pour le <b>Projet Génome Humain</b><br>• <b>YAC</b> (Chromosome Artificiel de Levure) : contient un <b>centromère (CEN)</b>, des <b>télomères (TEL)</b>, une <b>ori (ARS)</b> → insert <b>200–2000 kb</b><br>• <b>Vecteurs d'EXPRESSION</b> : contiennent en plus un <b>promoteur fort</b> (T7, lac, CMV) + un site <b>RBS</b> + souvent une <b>étiquette (His-tag, GST, GFP)</b><br>• <b>Vecteurs VIRAUX pour thérapie génique</b> : <b>rétrovirus / lentivirus</b> (intégration dans le génome → expression durable), <b>adénovirus</b> (pas d'intégration → expression transitoire), <b>AAV</b> (adeno-associated virus, sûr), <b>herpèsvirus</b><br><br><b>❌ B — « enzymes de restriction »</b> : FAUX. Les enzymes de restriction sont des <b>OUTILS (endonucléases)</b> qui <b>COUPENT</b> l'ADN — ce ne sont pas des vecteurs. Elles servent à <b>préparer</b> le vecteur et l'insert.<br><b>❌ C — « segments d'ADN ou d'ARN obtenus par synthèse chimique »</b> : FAUX en général. ⚠️ Un vecteur est <b>naturellement</b> un plasmide ou un virus, <b>puis MODIFIÉ</b> par génie génétique. On peut <b>synthétiser chimiquement</b> des <b>oligonucléotides</b> (amorces, sondes, gènes courts) — mais ce ne sont pas des vecteurs.<br><b>❌ E — « un cosmide est un mélange entre un plasmide et une PROTÉINE »</b> : FAUX. Le cosmide = plasmide + <b>SÉQUENCE COS (de l'ADN)</b> du phage λ.","t":"genetique-2026 EXAM-2026"},{"q":"Q12 — Les <b>MUTATIONS</b> : (spontanées au cours de la réplication · dues aux agents mutagènes · peuvent avoir lieu pendant la traduction · les mutations germinales sont transmises · les mutations somatiques sont transmises)","a":"<b>✅ A — Elles peuvent être SPONTANÉES au cours de la réplication</b><br><b>✅ B — Elles peuvent être dues à l'exposition à des agents mutagènes</b><br><b>✅ D — Les mutations de la lignée GERMINALE sont transmises à la descendance</b><br><br><b>A ✅ — MUTATIONS SPONTANÉES :</b><br>• <b>Erreurs de l'ADN polymérase</b> malgré la relecture (taux résiduel ≈ <b>10⁻⁹ par pb et par réplication</b>)<br>• <b>Désamination spontanée</b> : cytosine → <b>uracile</b> ; 5-méthylcytosine → <b>thymine</b> (point chaud de mutation CpG ⚠️)<br>• <b>Dépurination</b> : perte spontanée d'une purine (A ou G) → <b>site apurinique (AP)</b><br>• <b>Glissements (slippage)</b> de l'ADN pol sur les <b>répétitions</b> → expansion/contraction de microsatellites<br>• <b>Tautomérie</b> : formes rares des bases (énol/imine) → appariements anormaux<br><br><b>B ✅ — MUTATIONS INDUITES (agents mutagènes) :</b><br>• <b>PHYSIQUES</b> : <b>UV</b> (254 nm) → <b>dimères de thymine (pyrimidiques)</b> → réparés par <b>NER</b> ou <b>photolyase</b> ; <b>rayonnements ionisants (X, γ)</b> → <b>cassures double-brin</b> + radicaux libres<br>• <b>CHIMIQUES</b> : <b>agents ALKYLANTS</b> (EMS, MMS, nitrosoguanidine) ; <b>ANALOGUES de BASES</b> (5-bromouracile, 2-aminopurine) ; <b>agents INTERCALANTS</b> (<b>bromure d'éthidium, proflavine, acridine</b>) → décalage du cadre ; <b>benzo(a)pyrène</b> (fumée de cigarette) ; <b>aflatoxine B1</b> (Aspergillus → cancer du foie, mutation du codon 249 de p53)<br>• <b>BIOLOGIQUES</b> : <b>transposons</b>, insertion virale<br><br><b>D ✅ — GERMINALE vs SOMATIQUE ⚠️ NOTION FONDAMENTALE :</b><br>• <b>MUTATION GERMINALE</b> : touche les <b>CELLULES GERMINALES</b> (gamètes, ou leurs précurseurs dans la gonade) → <b>TRANSMISE À LA DESCENDANCE</b> ✅ → présente dans <b>TOUTES les cellules</b> de l'individu issu du gamète muté → c'est la base des <b>MALADIES HÉRÉDITAIRES</b><br>• <b>MUTATION SOMATIQUE</b> : touche une cellule du <b>CORPS</b> → <b>NON TRANSMISE à la descendance</b> ❌ → transmise uniquement aux <b>cellules filles de cette cellule</b> (clone) → base du <b>CANCER</b> (transformation maligne clonale) et du <b>MOSAÏCISME</b><br><br><b>❌ C — « peuvent avoir lieu pendant la TRADUCTION »</b> : FAUX.<br>⚠️ <b>DÉFINITION STRICTE :</b> une <b>MUTATION est une modification de la SÉQUENCE de l'ADN</b>. Elle ne peut donc survenir que lors de la <b>RÉPLICATION</b> (ou par lésion de l'ADN non réparée). La <b>traduction</b> produit des <b>PROTÉINES</b> à partir de l'ARNm — une erreur de traduction donne une <b>protéine anormale</b> mais <b>NE MODIFIE PAS L'ADN</b> → ce n'est <b>PAS une mutation</b>, c'est une <b>erreur traductionnelle</b> (non héréditaire, non clonale).<br><br><b>❌ E — « les mutations somatiques sont transmises à la descendance »</b> : FAUX (voir D).","t":"genetique-2026 EXAM-2026"},{"q":"Q13 — « Le vecteur est introduit <b>DIRECTEMENT dans la cellule cible</b> ». De quel type de transfert s'agit-il ?","a":"<b>✅ A — IN VIVO</b><br><br><b>LES 3 STRATÉGIES DE THÉRAPIE GÉNIQUE ⚠️ À DISTINGUER ABSOLUMENT :</b><br><br><b>1. IN VIVO (direct)</b> ✅<br>• Le <b>vecteur est injecté DIRECTEMENT dans l'organisme</b> du patient, où il atteint les cellules cibles<br>• <b>Voies</b> : intraveineuse, intramusculaire, intratumorale, intrathécale, inhalation, injection locale<br>• <b>Avantages</b> : simple, pas de manipulation cellulaire ex vivo, applicable à un grand nombre de cellules<br>• <b>Inconvénients</b> : <b>ciblage imparfait</b>, risque de réponse immunitaire, difficulté à atteindre le bon tissu<br>• <b>Vecteurs typiques</b> : <b>adénovirus</b>, <b>AAV</b>, <b>liposomes</b>, ADN nu<br>• <b>Exemples</b> : <b>Zolgensma</b> (onasemnogene abeparvovec, AAV9, IV, pour l'amyotrophie spinale SMA) ; thérapie de la <b>mucoviscidose</b> par inhalation<br><br><b>2. EX VIVO (indirect)</b><br>• On <b>PRÉLÈVE les cellules du patient</b> → on les <b>modifie EN LABORATOIRE</b> (transfection par le vecteur) → on les <b>sélectionne</b> → on les <b>RÉINJECTE au patient</b><br>• <b>Avantages</b> : <b>contrôle total</b>, cellules vérifiées avant réinjection, pas de réponse immunitaire contre des cellules étrangères<br>• <b>Inconvénients</b> : complexe, coûteux, ne marche que pour les cellules qu'on peut cultiver<br>• <b>Cellules cibles typiques</b> : <b>cellules souches hématopoïétiques (CSH)</b>, <b>lymphocytes T</b><br>• <b>Exemples</b> : <b>CAR-T cells</b> (Kymriah, Yescarta) · <b>Strimvelis</b> (déficit en ADA-SCID) · thérapie de l'<b>adrénoleucodystrophie</b> · <b>bêta-thalassémie</b> (Zynteglo)<br><br><b>3. IN SITU</b><br>• Injection <b>LOCALE, DIRECTEMENT dans l'organe ou la tumeur</b> visée<br>• Ex. : injection intratumorale d'un adénovirus ; <b>injection intrarétinienne sous-rétinienne</b> pour <b>Luxturna</b> (voretigène néparvovec, RPE65, amaurose congénitale de Leber)<br><br><b>❌ B, C, D</b> : voir ci-dessus — « directement dans la cellule cible » (sans prélèvement ni culture) = <b>IN VIVO</b>.<br><b>❌ E — « intra-veineux »</b> : c'est une <b>VOIE D'ADMINISTRATION</b>, pas un <b>type de transfert</b>. L'injection IV est <b>une des voies possibles du transfert in vivo</b>.","t":"genetique-2026 EXAM-2026 A-VERIFIER"},{"q":"Q14 — Concernant l'<b>ARNm MATURE des eucaryotes</b> : (porte l'anti-codon de l'ARNt · toujours simple brin · plus court que l'ADN · le sucre est un ribose · peut porter des mutations)","a":"<b>✅ B — Il est TOUJOURS SIMPLE BRIN</b><br><b>✅ C — Il est plus court que l'ADN</b><br><b>✅ D — Le sucre est un RIBOSE</b><br><b>✅ E — Il peut porter des mutations</b><br><br><b>B ✅ —</b> Tous les <b>ARN messagers</b> sont <b>simple brin (monocaténaires)</b>. Ils peuvent former des <b>structures secondaires locales</b> (tiges-boucles, épingle à cheveux) par appariement <b>intramoléculaire</b>, mais la molécule reste <b>une seule chaîne polynucléotidique</b>.<br>⚠️ <b>Exception à connaître :</b> certains <b>VIRUS</b> ont un génome à <b>ARN DOUBLE brin</b> (ex. : <b>Rotavirus</b>, famille Reoviridae) — mais ce n'est pas un ARNm eucaryote.<br><br><b>C ✅ — Plus court que l'ADN, POUR 2 RAISONS :</b><br>1. <b>Un ARNm ne code qu'UNE partie du génome</b> (un ou quelques gènes), alors que l'ADN chromosomique contient <b>tout</b> le génome (~3,2 × 10⁹ pb)<br>2. ⚠️ <b>Même par rapport à son propre gène</b>, l'ARNm mature est <b>plus court que l'ADN qui l'a codé</b> : les <b>INTRONS</b> ont été <b>retirés</b> par l'épissage. L'ARNm mature = <b>coiffe 5' + exons enchaînés + queue poly-A 3'</b>.<br><br><b>D ✅ —</b> Le sucre des ARN est le <b>RIBOSE</b> (avec un <b>–OH en 2'</b>). L'ADN utilise le <b>DÉSOXYRIBOSE</b> (un <b>–H</b> en 2'). ⚠️ C'est le <b>OH 2'</b> qui rend l'ARN <b>chimiquement INSTABLE</b> (hydrolyse alcaline) et qui permet l'activité catalytique des ribozymes.<br><br><b>E ✅ —</b> L'ARNm est une copie de l'ADN ; il reflète donc <b>toute mutation présente dans l'ADN matrice</b> (mutations faux-sens, non-sens, décalage du cadre, épissage anormal).<br>⚠️ On peut même les <b>détecter</b> : c'est le principe du <b>séquençage de l'ARN (RNA-seq)</b> et de l'étude des <b>ARNm par RT-PCR</b>.<br><br><b>❌ A — « il porte l'anti-codon de l'ARNt »</b> : <b>FAUX, PIÈGE MAJEUR</b> ⚠️<br>• <b>ARNm</b> : porte les <b>CODONS</b> (triplets <b>lus</b>)<br>• <b>ARNt</b> : porte l'<b>ANTI-CODON</b> (triplet <b>complémentaire</b> du codon) + l'<b>acide aminé correspondant</b> fixé en 3'<br>→ L'anti-codon est sur l'<b>ARNt</b>, <b>JAMAIS</b> sur l'ARNm.<br><br><b>📋 RÉCAP — MATURATION DE L'ARNm EUCARYOTE (3 étapes) :</b><br>1. <b>COIFFE 5' (7-méthylguanosine, m⁷Gppp)</b> — ajoutée <b>co-transcriptionnellement</b>, liaison <b>5'-5' triphosphate</b> → protection contre les exonucléases + reconnaissance par le ribosome (facteur <b>eIF4E</b>)<br>2. <b>ÉPISSAGE (splicing)</b> — retrait des <b>introns</b> (commencent par <b>GT</b>, finissent par <b>AG</b> = règle <b>GT-AG</b>), jonction des <b>exons</b> par le <b>spliceosome</b>. ⚠️ L'<b>épissage ALTERNATIF</b> permet à un seul gène de produire <b>plusieurs protéines</b> (>90 % des gènes humains)<br>3. <b>POLYADÉNYLATION 3'</b> — coupure après le signal <b>AAUAAA</b>, puis ajout de <b>~200 adénosines</b> par la <b>poly(A) polymérase</b> → stabilité + export nucléaire + traduction","t":"genetique-2026 EXAM-2026"},{"q":"Q15 — Un <b>NUCLÉOTIDE</b> = ?","a":"<b>✅ A — Sucre + Base + Groupement phosphate</b><br><b>✅ E — Nucléoside + Groupement phosphate</b><br><br>⚠️ <b>A et E disent LA MÊME CHOSE</b> — les deux sont correctes.<br><br><b>DÉFINITIONS À NE JAMAIS CONFONDRE :</b><br>• <b>BASE AZOTÉE</b> seule : adénine, guanine, cytosine, thymine (ADN) / uracile (ARN)<br>• <b>NUCLÉOSIDE</b> = <b>BASE + SUCRE</b> (liaison <b>β-N-osidique</b> entre l'azote N1 des pyrimidines / N9 des purines et le <b>C1'</b> du sucre)<br>• <b>NUCLÉOTIDE</b> = <b>BASE + SUCRE + PHOSPHATE</b> = <b>NUCLÉOSIDE + PHOSPHATE</b> (liaison <b>ester</b> sur le <b>C5'</b>)<br><br>Moyen mnémotechnique : « <b>un nucléotIDE a un phosphatE en pluS</b> » → <b>nucléoside + P = nucléotide</b>.<br><br><b>NOMS :</b><br>| Base | Nucléoside (ribose) | Nucléotide | Nucléoside (désoxyribose) |<br>|---|---|---|---|<br>| Adénine | <b>Adénosine</b> | AMP | <b>Désoxyadénosine</b> (dAMP) |<br>| Guanine | <b>Guanosine</b> | GMP | <b>Désoxyguanosine</b> (dGMP) |<br>| Cytosine | <b>Cytidine</b> | CMP | <b>Désoxycytidine</b> (dCMP) |<br>| Thymine | — (rare dans l'ARN) | — | <b>Thymidine</b> (dTMP) |<br>| Uracile | <b>Uridine</b> | UMP | — |<br><br>⚠️ <b>La THYMIDINE n'existe que dans l'ADN</b> — on dit toujours « <b>dTTP</b> » et jamais « TTP ».<br><br><b>DI et TRIPHOSPHATES :</b> ATP, GTP, CTP, UTP (énergie + synthèse ARN) ; dATP, dGTP, dCTP, dTTP (synthèse ADN).<br>⚠️ L'<b>ATP</b> est à la fois un <b>nucléotide</b> (constituant de l'ARN) et la <b>« monnaie énergétique »</b> de la cellule.<br><br><b>NUCLÉOTIDES CYCLIQUES (seconds messagers) :</b> <b>AMPc</b> (adénosine monophosphate cyclique, produit par l'<b>adénylate cyclase</b> à partir d'ATP) et <b>GMPc</b>.<br><br><b>❌ B — « sucre + base »</b> : c'est un <b>NUCLÉOSIDE</b>.<br><b>❌ C — « sucre + phosphate »</b> : il manque la base.<br><b>❌ D — « base + phosphate »</b> : il manque le sucre.","t":"genetique-2026 EXAM-2026"},{"q":"Q16 — Les <b>ENZYMES DE RESTRICTION</b> : (coupent au niveau d'un palindrome · ce sont des endonucléases · coupent au niveau d'un site de restriction · interviennent pendant la réplication · coupent un brin d'ADN pour éviter les torsions)","a":"<b>✅ A — Elles coupent au niveau d'un PALINDROME</b><br><b>✅ B — Ce sont des ENDONUCLÉASES</b><br><b>✅ C — Elles coupent au niveau d'un SITE DE RESTRICTION</b><br><br><b>DÉFINITION :</b> les <b>enzymes de restriction (endonucléases de restriction, type II)</b> sont des enzymes <b>bactériennes</b> qui reconnaissent une <b>séquence d'ADN SPÉCIFIQUE et COURTE (4 à 8 pb)</b>, appelée <b>site de restriction</b>, et <b>COUPENT les deux brins</b> de l'ADN à l'intérieur ou à proximité de ce site.<br><br><b>A ✅ — LE PALINDROME :</b><br>Le site de restriction est une séquence à <b>SYMÉTRIE BINAIRE (palindromique)</b> : elle se lit <b>de la même façon en 5'→3' sur les DEUX brins</b>.<br>Ex. : <b>EcoRI</b> reconnaît <b>5'-GAATTC-3'</b> ; le brin complémentaire lu en 5'→3' est aussi <b>5'-GAATTC-3'</b>.<br>⚠️ Ce n'est <b>PAS</b> un palindrome au sens linguistique (comme « Ésope reste ici ») — c'est un palindrome <b>en double brin, antiparallèle</b>.<br><br><b>B ✅ — ENDONUCLÉASE :</b><br>• <b>ENDO</b>nucléase : coupe <b>À L'INTÉRIEUR</b> de la chaîne d'ADN<br>• <b>EXO</b>nucléase : coupe <b>À PARTIR DES EXTRÉMITÉS</b> (5' ou 3')<br>→ Les enzymes de restriction sont des <b>ENDO</b>nucléases.<br><br><b>C ✅ — Le site de restriction :</b><br>• Taille <b>4 pb</b> → coupe en moyenne toutes les <b>4⁴ = 256 pb</b> (ex. : <b>AluI</b> AG↓CT, <b>TaqI</b> T↓CGA)<br>• Taille <b>6 pb</b> → toutes les <b>4⁶ = 4 096 pb</b> (ex. : <b>EcoRI</b>, <b>BamHI</b>, <b>HindIII</b>) — <b>le plus courant</b><br>• Taille <b>8 pb</b> → toutes les <b>4⁸ = 65 536 pb</b> (« <b>rare cutters</b> », ex. : <b>NotI</b> GC↓GGCCGC) → utiles pour la cartographie de grands génomes<br><br><b>LES 2 TYPES DE COUPURE ⚠️ :</b><br>• <b>EXTRÉMITÉS COHÉSIVES (« sticky ends »)</b> : coupe <b>DÉCALÉE</b> → laisse des <b>extrémités simple brin complémentaires</b> qui peuvent <b>s'apparier spontanément</b>. Ex. : <b>EcoRI</b> (G↓AATTC), <b>BamHI</b> (G↓GATCC), <b>HindIII</b>. ⚠️ <b>LES PLUS UTILES POUR LE CLONAGE</b> — l'insert et le vecteur s'assemblent facilement.<br>• <b>EXTRÉMITÉS FRANCHES (« blunt ends »)</b> : coupe <b>DROITE</b> au milieu du palindrome → pas de débord simple brin. Ex. : <b>AluI</b> (AG↓CT), <b>SmaI</b> (CCC↓GGG), <b>HaeIII</b>. Moins efficaces pour le clonage (pas de spécificité d'assemblage), mais universelles (n'importe quel fragment franc peut être ligaturé à n'importe quel autre).<br><br><b>LES EXEMPLES À CONNAÎTRE :</b><br>| Enzyme | Source | Site | Type de coupe |<br>|---|---|---|---|<br>| <b>EcoRI</b> | E. coli RY13 | 5'-G↓AATTC-3' | cohésive |<br>| <b>BamHI</b> | Bacillus amyloliquefaciens H | 5'-G↓GATCC-3' | cohésive |<br>| <b>HindIII</b> | Haemophilus influenzae d | 5'-A↓AGCTT-3' | cohésive |<br>| <b>PstI</b> | Providencia stuartii | 5'-CTGCA↓G-3' | cohésive |<br>| <b>AluI</b> | Arthrobacter luteus | 5'-AG↓CT-3' | franche |<br>| <b>SmaI</b> | Serratia marcescens | 5'-CCC↓GGG-3' | franche |<br><br><b>NOMENCLATURE :</b> <b>1ʳᵉ lettre</b> = genre (E = Escherichia) · <b>2ᵉ–3ᵉ</b> = espèce (co = coli) · <b>4ᵉ</b> = souche (R) · <b>chiffre romain</b> = ordre de découverte (I).<br><br><b>RÔLE BIOLOGIQUE NATUREL :</b> c'est le <b>SYSTÈME IMMUNITAIRE DE LA BACTÉRIE</b> contre les <b>phages</b>. La bactérie protège son propre ADN en le <b>MÉTHYLANT</b> (par des <b>méthylases</b> : <b>Dam</b> méthyle GATC, <b>Dcm</b> méthyle CCWGG) → système <b>RESTRiction-Modification (R-M)</b>.<br><br><b>UTILISATIONS :</b><br>• <b>CLONAGE</b> : couper le vecteur et l'insert avec les <b>MÊMES</b> enzymes → extrémités complémentaires → <b>ADN ligase</b><br>• <b>RFLP</b> (Restriction Fragment Length Polymorphism) → cartographie, empreintes génétiques<br>• <b>Cartographie de restriction</b><br>• ⚠️ Les <b>ISOSCHIZOMÈRES</b> = enzymes différentes reconnaissant le <b>MÊME site</b> (ex. : <b>SphI</b> et <b>BbuI</b> reconnaissent tous deux GCATGC) — mais peuvent couper différemment (on parle alors de <b>néoschizomères</b>).<br><br><b>❌ D — « interviennent pendant la réplication »</b> : FAUX. Les enzymes de restriction ne sont <b>pas impliquées dans la réplication</b>. Les enzymes de la réplication sont : <b>hélicase, primase, ADN polymérase, ligase, topoisomérase, SSB</b>.<br><b>❌ E — « coupent un brin d'ADN pour éviter les torsions »</b> : <b>FAUX — c'est la TOPOISOMÉRASE</b> ⚠️.<br>• <b>TOPOISOMÉRASE I</b> : coupe <b>UN seul brin</b>, laisse tourner, religature → <b>relâche les supertours</b>. Inhibée par la <b>camptothécine / irinotécan / topotécan</b>.<br>• <b>TOPOISOMÉRASE II (ADN gyrase chez les bactéries)</b> : coupe <b>LES DEUX brins</b>, fait passer un autre segment d'ADN à travers, religature → introduit des <b>supertours négatifs</b>. Inhibée par les <b>fluoroquinolones (ciprofloxacine)</b> et l'<b>étoposide / doxorubicine</b>.","t":"genetique-2026 EXAM-2026"},{"q":"Q17 — La stratégie du <b>GÈNE SUICIDE</b> : (confère aux cellules tumorales une sensibilité à un médicament · transformer une prodrogue en métabolite toxique · l'enzyme la plus utilisée est l'ARNpol · l'enzyme transforme le ganciclovir en ganciclovir triphosphate toxique · l'enzyme transforme le ganciclovir triphosphate en ganciclovir)","a":"<b>✅ A — Elle confère aux cellules tumorales une sensibilité à un médicament</b><br><b>✅ B — Elle transforme une prodrogue (médicament) en un métabolite toxique</b><br><b>✅ D — L'enzyme transforme le ganciclovir en ganciclovir TRIPHOSPHATE, qui est TOXIQUE</b><br><br><b>PRINCIPE (thérapie génique « gène suicide » / thérapie par conversion de prodrogue, GDEPT) :</b><br>On introduit dans les <b>cellules tumorales</b> un <b>GÈNE ÉTRANGER</b> qui code une <b>ENZYME absente des cellules humaines</b>. Cette enzyme <b>convertit une PROdrogue INOFFENSIVE en métabolite TOXIQUE</b>. On administre ensuite la prodrogue : <b>seules les cellules tumorales</b> (qui portent le gène) la transforment en poison → elles meurent. Les cellules saines sont épargnées car elles n'ont pas l'enzyme.<br><br><b>LE SYSTÈME DE RÉFÉRENCE — HSV-TK / GANCICLOVIR ✅ :</b><br>1. Le gène <b>TK (thymidine kinase) du VIRUS HERPÈS SIMPLEX (HSV-1)</b> est introduit dans la tumeur par un vecteur<br>2. On administre le <b>GANCICLOVIR (GCV)</b> — un <b>analogue nucléosidique de la guanosine</b>, <b>INOFFENSIF</b> en soi (prodrogue)<br>3. La <b>TK virale</b> <b>MONOPHOSPHORYLE</b> le ganciclovir → <b>GCV-monophosphate</b> ⚠️ (les kinases humaines ne le font <b>pas</b> ou très mal — c'est la clé de la sélectivité)<br>4. Les <b>kinases CELLULAIRES</b> de l'hôte ajoutent 2 phosphates → <b>GANCICLOVIR TRIPHOSPHATE (GCV-TP)</b> ← <b>LA FORME TOXIQUE</b><br>5. Le <b>GCV-TP</b> est un <b>analogue du dGTP</b> → il est <b>incorporé dans l'ADN</b> par l'ADN polymérase → mais comme il lui manque le <b>3'-OH</b>, il <b>BLOQUE l'élongation</b> → <b>arrêt de la réplication</b> → <b>APOPTOSE</b><br><br>⚠️ <b>Effet « BYSTANDER » (effet spectateur)</b> : le GCV-TP passe aux <b>cellules tumorales VOISINES non transduites</b> via les <b>GAP JUNCTIONS</b> (connexine 43) ou par des <b>vésicules apoptotiques</b> → elles meurent aussi. <b>Il n'est donc PAS nécessaire de transduire 100 % des cellules tumorales</b> — c'est ce qui rend la stratégie cliniquement viable.<br><br><b>AUTRES SYSTÈMES GÈNE SUICIDE :</b><br>• <b>Cytosine désaminase (CD)</b> d'E. coli ou de levure → convertit la <b>5-fluorocytosine (5-FC, antifongique inoffensif)</b> en <b>5-fluorouracile (5-FU, chimiothérapie toxique)</b><br>• <b>Nitroreductase (NTR)</b> d'E. coli → convertit le <b>CB1954</b> en agent alkylant toxique<br>• <b>Purine nucléoside phosphorylase (PNP)</b> d'E. coli → convertit la <b>6-méthoxypurine arabinonucléoside (MeP-dR)</b> en MeP toxique<br>• <b>Thymidine phosphorylase</b>, <b>carboxypeptidase G2</b> (CMDA), <b>horseradish peroxidase (HRP)</b> + IAA<br><br><b>B ✅ —</b> C'est exactement la définition de la <b>PROdrogue</b> : une molécule <b>pharmacologiquement INACTIVE</b> administrée telle quelle, qui est <b>convertie IN VIVO en métabolite ACTIF/TOXIQUE</b>.<br><br><b>❌ C — « l'enzyme la plus utilisée est l'ARNpol »</b> : <b>FAUX</b>. L'ARN polymérase est l'enzyme de la <b>transcription</b>, présente dans <b>toutes</b> les cellules → <b>aucune sélectivité</b>, impossible à utiliser. L'enzyme de référence est la <b>THYMIDINE KINASE du HSV (HSV-TK)</b>.<br><b>❌ E — « l'enzyme transforme le ganciclovir TRIPHOSPHATE en ganciclovir »</b> : <b>FAUX, SENS INVERSÉ</b> ⚠️. La réaction va <b>DANS L'AUTRE SENS</b> : ganciclovir → ganciclovir-<b>mono</b>phosphate (par la TK virale) → ganciclovir-<b>tri</b>phosphate (par les kinases cellulaires).","t":"genetique-2026 EXAM-2026"},{"q":"Q18 — L'<b>HYPERCHOLESTÉROLÉMIE FAMILIALE</b> et la thérapie génique : (déficit des récepteurs LDL · déficit des récepteurs HDL · on agit sur les récepteurs hépatiques · thérapie génique ex vivo · thérapie génique in situ)","a":"<b>✅ A — Maladie due à un déficit des récepteurs des lipoprotéines LDL</b><br><b>✅ C — On agit sur les récepteurs HÉPATIQUES</b><br><b>✅ D — La thérapie génique est faite en EX VIVO</b><br><br><b>A ✅ — LA MALADIE :</b><br>L'<b>hypercholestérolémie familiale (HF)</b> est une maladie <b>AUTOSOMIQUE DOMINANTE</b> causée le plus souvent par une mutation du gène <b>LDLR</b> (chromosome <b>19p13.2</b>) codant le <b>RÉCEPTEUR des LDL</b>.<br><br><b>Mécanisme normal :</b> le récepteur LDL (à la surface des <b>hépatocytes</b>, mais aussi de toutes les cellules nucléées) <b>capte les LDL circulants</b> par <b>endocytose médiée par un récepteur</b> (via les <b>puits recouverts de clathrine</b>) → le cholestérol est libéré dans la cellule → la cellule <b>freine</b> sa propre synthèse (inhibition de l'<b>HMG-CoA réductase</b>) et <b>diminue</b> l'expression des récepteurs LDL (rétrocontrôle par <b>SREBP-2</b>).<br><br><b>En cas de déficit en récepteurs LDL :</b> les <b>LDL ne sont PAS captés</b> par le foie → <b>hypercholestérolémie majeure</b> (LDL-C &gt; 1,9 g/L chez l'adulte) → dépôt de cholestérol dans :<br>• <b>Les artères</b> → <b>ATHÉROSCLÉROSE PRÉCOCE</b> → <b>infarctus du myocarde avant 40–50 ans</b> (voire dans l'enfance chez les homozygotes)<br>• <b>Les tendons</b> → <b>XANTHOMES TENDINEUX</b> (tendon d'Achille, extenseurs des doigts) ⚠️ signe pathognomonique<br>• <b>La peau</b> → xanthomes tubéreux, xanthélasmas<br>• <b>La cornée</b> → <b>ARC JUVÉNILE</b> (arc cornéen avant 45 ans)<br><br><b>Formes :</b><br>• <b>HÉTÉROZYGOTE</b> (1/250 — très fréquent) : récepteurs à <b>50 %</b> → LDL ≈ 2–4 g/L → infarctus vers 40–60 ans<br>• <b>HOMOZYGOTE</b> (1/300 000) : récepteurs <b>absents ou non fonctionnels</b> → LDL &gt; 5–10 g/L → infarctus <b>avant 20 ans</b>, souvent mortelle dans l'enfance<br>⚠️ Autre cause plus rare : mutation du gène <b>APOB</b> (ligand du récepteur, <b>HF ligand-déficiente</b>) ou gain de fonction de <b>PCSK9</b> (qui dégrade le récepteur LDL).<br><br><b>C ✅ — Pourquoi le FOIE :</b> le <b>foie est le principal organe de clairance des LDL</b> — il assure ≈ <b>70 %</b> du catabolisme des LDL plasmatiques via les récepteurs LDL <b>hépatiques</b>. Corriger le foie corrige donc la <b>cholestérolémie plasmatique globale</b>.<br><br><b>D ✅ — La stratégie EX VIVO historique (étude de Brown &amp; Goldstein, début des années 1990) :</b><br>1. <b>Hépatectomie partielle</b> — on prélève un fragment de foie du patient<br>2. <b>Mise en culture</b> des <b>hépatocytes</b><br>3. <b>TRANSDUCTION ex vivo</b> par un vecteur <b>rétroviral</b> portant le gène <b>LDLR</b> normal<br>4. <b>Sélection</b> des hépatocytes transduits<br>5. <b>RÉINJECTION</b> des hépatocytes corrigés dans le foie (par le système porte)<br><br>→ C'est un <b>EX VIVO</b> classique : les cellules sont <b>prélevées, modifiées en laboratoire, puis réinjectées</b>.<br><br><b>⚠️ Traitements ACTUELS (2020s) — à connaître :</b><br>• <b>Statines</b> (inhibiteurs de l'HMG-CoA réductase) — base du traitement<br>• <b>Ézétimibe</b> (inhibe l'absorption intestinale du cholestérol via NPC1L1)<br>• <b>Anti-PCSK9</b> (monoclonal : <b>alirocumab, évolocumab</b> ; ou siRNA : <b>inclisiran</b>) → ↑ le nombre de récepteurs LDL → ↓ LDL de 60 %<br>• <b>Lomitapide</b> (inhibiteur de la MTP), <b>mipomersen</b> (oligonucléotide antisens anti-APOB)<br>• <b>Évinacumab</b> (anti-ANGPTL3) pour les formes homozygotes<br>• <b>Aphérèse des LDL</b> hebdomadaire pour les homozygotes<br><br><b>❌ B — « déficit des récepteurs HDL »</b> : FAUX. ⚠️ Les <b>HDL</b> sont le « <b>bon cholestérol</b> » — ils assurent le <b>transport RÉVERSE</b> du cholestérol (des tissus vers le foie, via <b>ABCA1</b>, <b>SR-B1</b>, <b>apoA-I</b>, <b>Lecithin Cholesterol Acyl Transferase / LCAT</b>). La maladie de l'<b>apoA-I</b> ou d'<b>ABCA1</b> donne la <b>maladie de Tangier</b> (HDL très bas) — ce n'est <b>PAS</b> l'hypercholestérolémie familiale.<br><b>❌ E — « in situ »</b> : FAUX pour l'approche historique. ⚠️ Des approches <b>in vivo</b> modernes (AAV8 portant LDLR ou PCSK9-siRNA, <b>inclisiran</b>) sont en développement/utilisation, mais la réponse attendue dans le contexte du cours est <b>EX VIVO</b>.","t":"genetique-2026 EXAM-2026 A-VERIFIER"},{"q":"Q19 — Le <b>MÉLANOME</b> et la thérapie génique : (cancer de la peau dû à la transformation maligne des mélanocytes · cancer du foie · stimuler la réponse immunitaire anti-tumorale · faire proliférer les LT qui détruisent les cellules cancéreuses · faire proliférer les LB)","a":"<b>✅ A — C'est un cancer de la peau dû à une transformation maligne des MÉLANOCYTES</b><br><b>✅ C — La thérapie génique consiste à STIMULER LA RÉPONSE IMMUNITAIRE ANTI-TUMORALE</b><br><br><b>A ✅ — LE MÉLANOME :</b><br>• Tumeur maligne développée aux dépens des <b>MÉLANOCYTES</b> (cellules dérivées de la <b>crête neurale</b>, situées dans la <b>couche basale de l'épiderme</b>, qui produisent la <b>mélanine</b>)<br>• Localisations : <b>peau</b> (85–90 %), mais aussi <b>œil (mélanome uvéal)</b>, <b>muqueuses</b>, <b>méninges</b><br>• ⚠️ <b>Le plus DANGEREUX des cancers cutanés</b> — très <b>métastatique</b> (lymphatique puis hématogène : poumon, foie, cerveau, os), alors que les carcinomes basocellulaire et spinocellulaire sont peu métastatiques<br>• <b>Facteur de risque n°1 : les UV</b> (soleil, cabines de bronzage), surtout les <b>coups de soleil dans l'enfance</b><br>• <b>Mutations fréquentes</b> : <b>BRAF V600E</b> (~50 %), <b>NRAS</b>, <b>CDKN2A/p16</b> (formes familiales), <b>TERT</b> promoteur, <b>KIT</b> (mélanomes des muqueuses/acraux)<br>• <b>Règle ABCDE</b> du dépistage : <b>A</b>symétrie · <b>B</b>ords irréguliers · <b>C</b>ouleur hétérogène · <b>D</b>iamètre &gt; 6 mm · <b>E</b>volutivité<br><br><b>C ✅ — L'IMMUNOTHÉRAPIE / THÉRAPIE GÉNIQUE DU MÉLANOME :</b><br>Le mélanome est <b>la tumeur la plus IMMUNOGÈNE</b> (forte charge mutationnelle induite par les UV → beaucoup de <b>néoantigènes</b>). C'est pourquoi l'immunothérapie y est si efficace.<br><br><b>Stratégies :</b><br>• <b>Transfert de gènes de CYTOKINES</b> dans la tumeur : <b>IL-2</b>, <b>IL-12</b>, <b>GM-CSF</b>, <b>IFN-α/γ</b> → recrutement et activation locale des cellules immunitaires<br>• <b>Transfert des gènes du <span style=\"color:#c00\">CMH</span> (HLA)</b> ou de <b>costimulateurs (B7-1/CD80, CD86)</b> → rendre la tumeur plus « visible » aux lymphocytes T<br>• <b>Vaccins à ADN/ARN</b> codant des <b>antigènes mélanocytaires</b> : <b>MART-1/Melan-A</b>, <b>gp100</b>, <b>tyrosinase</b>, <b>MAGE</b>, <b>NY-ESO-1</b><br>• <b>T-VEC (talimogène laherparepvec / Imlygic)</b> ⚠️ : <b>virus herpès (HSV-1) GÉNÉTIQUEMENT MODIFIÉ</b>, injecté <b>intratumoral</b>. Il est <b>atténué</b> (délétion des gènes ICP34.5 et ICP47) et armé du gène de la <b>GM-CSF humaine</b> → il <b>lyse sélectivement les cellules tumorales</b> et <b>stimule une réponse immunitaire systémique anti-tumorale</b>. <b>Première thérapie génique oncolytique approuvée (FDA 2015) pour le mélanome.</b><br>• <b>CAR-T cells</b> et <b>TCR-transgéniques</b> ciblant MART-1 ou NY-ESO-1<br>• ⚠️ <b>Anti-PD-1 (pembrolizumab, nivolumab)</b> et <b>anti-CTLA-4 (ipilimumab)</b> — immunothérapies par anticorps monoclonaux (pas de la thérapie génique stricto sensu, mais reposent sur le même principe de <b>lever les freins immunitaires</b>)<br>• <b>Anti-BRAF (vémurafénib, dabrafénib)</b> + <b>anti-MEK (tramétinib)</b> — thérapies ciblées, pas géniques<br><br><b>❌ B — « cancer du foie »</b> : FAUX. Le cancer du foie primitif est le <b>carcinome HÉPATOCELLULAIRE (CHC)</b>.<br><b>❌ D — « faire proliférer les LT »</b> : ⚠️ <b>partiellement vrai mais IMPRÉCIS</b> — certaines stratégies visent bien les lymphocytes T (CAR-T, TCR-T, IL-2). Mais la formulation générale du cours est « <b>stimuler la réponse immunitaire anti-tumorale</b> », qui est plus large (inclut les cellules dendritiques, les NK, les cytokines).<br><b>❌ E — « faire proliférer les LB »</b> : FAUX. Les <b>lymphocytes B</b> (immunité humorale, anticorps) ne sont <b>pas</b> la cible de l'immunothérapie anti-tumorale — ce sont les <b>lymphocytes T cytotoxiques (CD8⁺)</b> qui détruisent les cellules cancéreuses.","t":"genetique-2026 EXAM-2026 A-VERIFIER"},{"q":"Q20 — Quelle enzyme <b>coupe UN brin d'ADN lorsque les torsions deviennent fortes</b> ?","a":"<b>✅ B — LA TOPOISOMÉRASE</b> (type I)<br><br><b>MÉCANISME :</b> lors de la réplication, l'ouverture de la double hélice par l'<b>hélicase</b> crée en <b>avant de la fourche</b> des <b>SUPERTOURS POSITIFS</b> (sur-enroulement) → la molécule se <b>tord</b> et devient impossible à dérouler.<br><br><b>LA TOPOISOMÉRASE I</b> :<br>1. Se lie à l'ADN et <b>COUPE UN SEUL BRIN</b> (coupure simple brin)<br>2. Forme une <b>liaison covalente transitoire</b> entre son résidu <b>tyrosine actif</b> et l'extrémité <b>3'-phosphate</b><br>3. <b>LAISSE TOURNER</b> l'ADN librement autour de la liaison phosphodiester intacte de l'autre brin → <b>relâche la tension</b><br>4. <b>RELIGATURE</b> le brin coupé<br>→ Elle est <b>ATP-INDÉPENDANTE</b> ⚠️ (elle utilise l'énergie stockée dans la liaison covalente Tyr-ADN).<br><br><b>LA TOPOISOMÉRASE II (ADN GYRASE chez les bactéries)</b> :<br>• Coupe <b>LES DEUX BRINS</b> (double brin)<br>• Fait <b>PASSER un autre segment d'ADN double brin à travers la coupure</b><br>• Religature<br>• ⚠️ <b>ATP-DÉPENDANTE</b><br>• Chez les bactéries, elle <b>INTRODUIT des supertours NÉGATIFS</b> (compaction de l'ADN)<br><br><b>❌ POURQUOI PAS LES AUTRES :</b><br>• <b>A — Hélicase</b> : elle <b>DÉROULE / SÉPARE les deux brins</b> en rompant les <b>liaisons HYDROGÈNE</b> entre les bases. Elle ne coupe <b>PAS</b> le squelette phosphodiester. ⚠️ <b>C'est elle qui CRÉE le problème de torsion.</b><br>• <b>C — ARN polymérase</b> : synthétise l'<b>ARN</b> à partir d'une matrice ADN (transcription).<br>• <b>D — ADN polymérase</b> : synthétise l'<b>ADN</b> (élongation, 5'→3').<br>• <b>E — Enzyme de restriction</b> : coupe l'ADN sur un <b>site spécifique palindromique</b> — c'est un outil de <b>génie génétique</b>, pas une enzyme de la réplication.<br><br><b>💊 PHARMACOLOGIE ⚠️ À CONNAÎTRE :</b><br>• <b>Inhibiteurs de la TOPOISOMÉRASE I</b> : <b>camptothécine</b> et dérivés — <b>irinotécan</b> (cancer colorectal), <b>topotécan</b> (cancer de l'ovaire, poumon à petites cellules)<br>• <b>Inhibiteurs de la TOPOISOMÉRASE II</b> : <b>étoposide</b>, <b>téniposide</b> (épipodophyllotoxines), <b>anthracyclines</b> (<b>doxorubicine, daunorubicine, épirubicine</b>)<br>• <b>Inhibiteurs de la gyrase bactérienne (topo II)</b> : <b>FLUOROQUINOLONES</b> (ciprofloxacine, lévofloxacine, ofloxacine) → antibiotiques","t":"genetique-2026 EXAM-2026"},{"q":"Q21 — Le <b>CARYOTYPE</b> permet de détecter : (anomalies équilibrées · anomalies déséquilibrées · microdélétions · mosaïques · microduplications)","a":"<b>✅ B — Les anomalies DÉSÉQUILIBRÉES</b><br><b>✅ D — Les mosaïques</b><br><br><b>DÉFINITION DU CARYOTYPE :</b> représentation <b>ordonnée et classée</b> de l'ensemble des chromosomes d'une cellule, en <b>métaphase</b>, après <b>culture cellulaire</b>, <b>coloration</b> et <b>microscopie</b>.<br><br><b>LES 8 ÉTAPES :</b><br>1. <b>PRÉLÈVEMENT</b> : sang périphérique (lymphocytes), liquide amniotique, villosités choriales, moelle osseuse, peau<br>2. <b>CULTURE CELLULAIRE</b> avec un <b>mitogène (PHA)</b> — 48 à 72 h<br>3. <b>BLOCAGE EN MÉTAPHASE</b> par la <b>COLCHICINE / COLCÉMIDE</b><br>4. <b>CHOC HYPO-TONIQUE</b> (<b>KCl 0,075 M</b>) → l'eau entre par <b>osmose</b> → les cellules gonflent → les chromosomes <b>s'éparpillent</b><br>5. <b>FIXATION</b> (<b>méthanol : acide acétique = 3:1</b>)<br>6. <b>ÉTALEMENT</b> sur lame + séchage<br>7. <b>DÉNATURATION + MARQUAGE</b> (bandes G, R, C, ou FISH)<br>8. <b>ANALYSE</b> : <b>au moins 20 métaphases</b> (<b>30–50</b> pour exclure un mosaïcisme)<br><br><b>RÉSOLUTION ⚠️ POINT CLÉ :</b> le caryotype standard (bandes G, 400–550 bandes) a une résolution d'environ <b>5 à 10 MILLIONS de paires de bases (Mb)</b>.<br><br><b>✅ CE QUE LE CARYOTYPE DÉTECTE :</b><br>• <b>ANEUPLOÏDIES</b> : <b>trisomies</b> (21 = Down, 18 = Edwards, 13 = Patau), <b>monosomies</b> (45,X = Turner), <b>triploïdie</b>, gonosomes anormaux (<b>47,XXY = Klinefelter</b>, XYY, XXX)<br>• <b>GRANDES ANOMALIES DE STRUCTURE DÉSÉQUILIBRÉES</b> : délétions &gt; 5–10 Mb (<b>5p− = cri du chat</b>, <b>del(4p) = Wolf-Hirschhorn</b>), grandes duplications, chromosomes en anneau, isochromosomes, chromosomes marqueurs<br>• <b>GRANDES translocations et inversions</b> (même équilibrées, si elles sont assez grandes pour être vues)<br>• <b>MOSAÏCISME</b> ✅<br><br><b>✅ D — LES MOSAÏQUES :</b><br>Un <b>mosaïque</b> = individu issu d'<b>UN SEUL ZYGOTE</b> avec <b>DEUX (ou plus) POPULATIONS CELLULAIRES</b> de contenu génétique différent.<br>• Cause : <b>NON-DISJONCTION MITOTIQUE POST-ZYGOTIQUE</b> pendant les premières divisions de l'embryon<br>• Ex. : <b>mos 46,XX/47,XX,+21</b> (trisomie 21 atténuée) · <b>mos 45,X/46,XX</b> (Turner atténué)<br>• ⚠️ <b>MOSAÏCISME GERMINAL (gonosomal)</b> : la mutation n'est présente que dans une <b>partie des gamètes</b> → les parents sont <b>sains</b> mais peuvent avoir <b>PLUSIEURS enfants atteints</b> d'une maladie réputée « de novo ». Piège classique du conseil génétique (ex. : <b>ostéogenèse imparfaite</b>, <b>myopathie de Duchenne</b>)<br>• ⚠️ <b>Détection</b> : il faut compter <b>beaucoup de métaphases</b> (30–50, voire 100+) car la population anormale peut être minoritaire ou restreinte à un seul tissu<br><br><b>❌ CE QUE LE CARYOTYPE NE DÉTECTE PAS :</b><br>• <b>C — MICRODÉLÉTIONS</b> : trop petites (&lt; 5 Mb) → <b>DiGeorge (22q11.2)</b>, <b>Williams (7q11.23)</b>, <b>Prader-Willi/Angelman (15q11-q13)</b> → détectées par <b>FISH</b>, <b>ACPA</b> ou <b>MLPA</b><br>• <b>E — MICRODUPLICATIONS</b> → <b>ACPA</b><br>• ❌ <b>MUTATIONS PONCTUELLES</b> → <b>SÉQUENÇAGE</b> (Sanger, NGS)<br>• ❌ <b>ANOMALIES D'EMPREINTE / MÉTHYLATION</b> → <b>tests de méthylation (MS-MLPA, bisulfite)</b><br>• ❌ <b>DISOMIE UNIPARENTALE</b> → <b>microsatellites / ACPA-SNP</b><br>• ❌ <b>EXPANSIONS DE TRIPLETS</b> (X fragile, Huntington) → <b>PCR + Southern blot</b><br>• ⚠️ <b>A — anomalies ÉQUILIBRÉES</b> : le caryotype voit les <b>GRANDES</b> translocations/inversions équilibrées, mais <b>PAS les petites</b> ni les réarrangements cryptiques. Dans le contexte du QCM (qui oppose « équilibrées » à « déséquilibrées »), la réponse attendue est <b>❌</b> — car la <b>force</b> du caryotype est de détecter les <b>déséquilibres</b>.<br><br><b>📋 QUELLE TECHNIQUE POUR QUELLE ANOMALIE :</b><br>• Aneuploïdie → <b>caryotype</b> (ou QF-PCR prénatal rapide, NIPT)<br>• Grande translocation/inversion, mosaïcisme → <b>caryotype</b><br>• Microdélétion/microduplication (CNV) → <b>ACPA (puce à ADN)</b> ⭐ ou FISH ciblée, MLPA<br>• Translocation équilibrée fine, remaniement cryptique → <b>FISH</b> ou ACPA-SNP<br>• Empreinte parentale → <b>test de méthylation</b><br>• Disomie uniparentale → <b>microsatellites / ACPA-SNP</b><br>• Mutation ponctuelle → <b>séquençage</b><br>• Expansion de triplets → <b>PCR + Southern blot</b>","t":"genetique-2026 EXAM-2026"},{"q":"Q22 — Le <b>CENTROMÈRE</b> : (constriction secondaire · portion où l'ADN n'est pas encore dupliqué · région d'union des deux chromatides sœurs · contient le centre d'organisation des microtubules · permet l'attachement à l'enveloppe nucléaire)","a":"<b>✅ C — C'est la région d'union des DEUX CHROMATIDES SŒURS</b><br><b>✅ D — Il contient le centre d'organisation des microtubules</b><br><br><b>DÉFINITION :</b> le <b>centromère</b> est la <b>CONSTRICTION PRIMAIRE</b> du chromosome, où les <b>DEUX CHROMATIDES SŒURS</b> restent unies après la réplication, et où s'assemble le <b>KINÉTOCHORE</b> (structure protéique d'attachement des microtubules du fuseau).<br><br><b>C ✅ —</b> Après la réplication (phase S), chaque chromosome = <b>2 chromatides sœurs IDENTIQUES</b> jointes au centromère par la <b>COHÉSINE</b>. Elles ne se séparent qu'en <b>ANAPHASE</b>, quand la <b>séparase</b> clive la cohésine.<br><br><b>D ✅ — LE KINÉTOCHORE :</b><br>• Complexe protéique à <b>3 couches</b> (interne, centrale, externe/fibreuse), &gt; <b>100 protéines</b><br>• Contient la <b>CENP-A</b> ⚠️ — un <b>VARIANT de l'histone H3</b> spécifique du centromère = <b>marqueur ÉPIGÉNÉTIQUE</b> du centromère (la position du centromère n'est pas déterminée par la séquence d'ADN, mais par la CENP-A)<br>• Le kinétochore externe <b>capture 10 à 30 microtubules</b><br>• Contient le <b>POINT DE CONTRÔLE DU FUSEAU (SAC)</b> : <b>MAD1, MAD2, BUB1, BUBR1</b> → bloquent l'<b>APC/C</b> tant que tous les kinétochores ne sont pas <b>BI-ORIENTÉS</b> en métaphase<br>• ⚠️ Le <b>CENTROSOME</b> (2 centrioles) est le <b>MTOC principal</b>, mais le kinétochore est un <b>MTOC local</b><br><br><b>❌ A — « constriction SECONDAIRE » : FAUX — PIÈGE MAJEUR</b> ⚠️<br>• <b>CONSTRICTION PRIMAIRE</b> = le <b>CENTROMÈRE</b> (sur <b>TOUS</b> les chromosomes)<br>• <b>CONSTRICTION SECONDAIRE</b> = le <b>NOR (Nucleolar Organizer Region)</b>, sur les <b>bras courts des ACROCENTRIQUES (13, 14, 15, 21, 22)</b>. Elle contient les gènes des <b>ARNr 45S</b> (~300 copies en tandem) → c'est là que se forme le <b>NUCLÉOLE</b>.<br>→ Les constrictions secondaires sont le site des <b>TRANSLOCATIONS ROBERTSONIENNES</b>.<br><br><b>❌ B — « portion où l'ADN n'est pas encore dupliqué »</b> : FAUX. Le centromère est <b>répliqué</b> comme le reste (mais <b>TARDIVEMENT</b> — c'est de l'hétérochromatine constitutive). Ce qui unit les chromatides, c'est la <b>COHÉSINE</b>.<br><br><b>❌ E — « attachement à l'ENVELOPPE NUCLÉAIRE »</b> : FAUX ⚠️. C'est le <b>TÉLOMÈRE</b> qui s'ancre à la lamina/enveloppe (complexes <b>LINC / SUN-KASH</b>). Le centromère s'attache aux <b>MICROTUBULES DU FUSEAU</b>.<br><br><b>📋 CLASSIFICATION SELON LA POSITION DU CENTROMÈRE :</b><br><b>INDEX CENTROMÉRIQUE (IC) = (longueur du bras p / longueur totale) × 100</b><br>• <b>MÉTACENTRIQUE</b> : centromère au <b>milieu</b>, IC ≈ <b>50 %</b>, p ≈ q → chromosomes <b>1, 3, 16, 19, 20</b><br>• <b>SUBMÉTACENTRIQUE</b> : <b>décalé</b>, IC <b>25–50 %</b>, p &lt; q → chromosomes <b>2, 4, 5, 6–12, X</b><br>• <b>ACROCENTRIQUE</b> : <b>près d'une extrémité</b>, IC <b>&lt; 25 %</b>, p très court avec NOR + satellite → <b>13, 14, 15, 21, 22</b><br>• <b>TÉLOCENTRIQUE</b> : centromère <b>à l'extrémité</b>, IC = <b>0</b>, p absent → ⚠️ <b>N'EXISTE PAS chez l'HOMME</b> (existe chez la souris)<br><br>⚠️ Les 5 paires acrocentriques = <b>10 CHROMOSOMES</b>.","t":"genetique-2026 EXAM-2026"},{"q":"Q23 — Le <b>TÉLOMÈRE</b> : (empêche la fusion des chromosomes · permet le positionnement dans le noyau · est riche en gènes · contient des séquences répétitives · se raccourcit dans les cellules germinales)","a":"<b>✅ A — Il empêche la fusion des chromosomes</b><br><b>✅ B — Il permet le positionnement du chromosome dans le noyau</b><br><b>✅ D — Il contient des séquences d'ADN RÉPÉTITIVES</b><br><br><b>DÉFINITION :</b> structure située à <b>CHAQUE EXTRÉMITÉ</b> d'un chromosome linéaire, faite d'<b>ADN hautement répété NON CODANT</b> associé au complexe protéique <b>SHELTERIN</b>.<br><br><b>D ✅ — SÉQUENCE CHEZ L'HOMME :</b><br>• Motif : <b>5'-TTAGGG-3'</b>, répété <b>500 à 2 000 fois</b> (= <b>3 à 12 kb</b> à la naissance)<br>• <b>Débord 3' simple brin (overhang G-rich)</b> de <b>100–200 nucléotides</b><br>• <b>T-LOOP</b> : le débord 3' <b>s'insère dans la double hélice en amont</b> → grande boucle T + boucle D → l'extrémité est « <b>cachée</b> »<br>• C'est de l'<b>HÉTÉROCHROMATINE</b> : condensée, pauvre en gènes, réplication tardive<br><br><b>LE COMPLEXE SHELTERIN (6 protéines) :</b> <b>TRF1, TRF2, RAP1, TIN2, TPP1, POT1</b><br>• <b>TRF1 et TRF2</b> se lient à l'ADN <b>double brin</b><br>• <b>POT1</b> se lie à l'extrémité <b>simple brin 3'</b><br>• ⚠️ <b>TRF2 est ESSENTIELLE à la T-LOOP</b> — sans elle, l'extrémité est reconnue comme une <b>cassure double brin</b><br><br><b>A ✅ — FONCTION PROTECTRICE :</b><br>Le télomère « <b>cache</b> » l'extrémité pour qu'elle ne soit <b>PAS prise pour une CASSURE DOUBLE BRIN</b>.<br>⚠️ Sans télomères fonctionnels : activation de <b>ATM/ATR et p53</b> → réparation par <b>NHEJ</b> → <b>FUSIONS télomère-télomère</b> → chromosomes <b>DICENTRIQUES</b> → <b>PONTS ANAPHASIQUES</b> en mitose → cassures → <b>INSTABILITÉ GÉNOMIQUE → CANCER</b>.<br><br><b>B ✅ — POSITIONNEMENT DANS LE NOYAU :</b><br>• Les télomères s'ancent à la <b>LAMINA NUCLÉAIRE</b> (lamines A/C, B) et à l'<b>enveloppe nucléaire</b> via les <b>complexes LINC (SUN-KASH)</b><br>• Ils participent à l'organisation des <b>TERRITOIRES CHROMOSOMIQUES</b> (chaque chromosome occupe une zone discrète du noyau)<br>• ⚠️ En <b>MÉIOSE</b> : les télomères s'attachent à l'enveloppe et <b>migrent tous du même côté</b> → <b>STADE « BOUQUET »</b> (leptotène/zygotène) → facilite l'<b>appariement des homologues</b><br><br><b>❌ C — « est riche en gènes » : FAUX</b>. Les télomères sont de l'<b>HÉTÉROCHROMATINE</b> → <b>PAUVRES en gènes</b>, quasi silencieux. (On a découvert des <b>TERRA</b> — TElomeric Repeat-containing RNAs, ARN longs non codants régulant les télomères.)<br><br><b>❌ E — « se raccourcit dans les cellules GERMINALES » : FAUX — C'EST L'INVERSE</b> ⚠️<br>• <b>CELLULES SOMATIQUES</b> : <b>télomérase INACTIVE</b> → le télomère <b>SE RACCOURCIT de 50 à 200 pb par division</b><br>&nbsp;&nbsp;→ Cause : le <b>PROBLÈME DE LA RÉPLICATION TERMINALE</b> — l'ADN polymérase ne peut pas répliquer l'extrémité 3' du <b>brin retardé</b>, car il n'y a plus de place pour poser une <b>amorce</b> après son retrait<br>&nbsp;&nbsp;→ Après <b>50 à 70 divisions</b> : <b>SÉnescence RÉPLICATIVE (LIMITE DE HAYFLICK)</b> → arrêt du cycle ou apoptose<br>• <b>CELLULES GERMINALES</b> : <b>TÉLOMÉRASE ACTIVE</b> → télomères <b>MAINTENUS</b> ✅<br>• <b>CELLULES SOUCHES</b> : télomérase active (niveau plus bas)<br>• ⚠️ <b>CELLULES CANCÉREUSES (~85–90 %)</b> : <b>RÉACTIVENT la TÉLOMÉRASE</b> → <b>IMMORTALISATION</b>. Les autres utilisent le mécanisme <b>ALT</b> (Alternative Lengthening of Telomeres, par recombinaison homologue)<br><br><b>🧬 LA TÉLOMÉRASE :</b><br>• C'est une <b>TRANSCRIPTASE INVERSE</b> (ADN polymérase ARN-dépendante) ⚠️<br>• Holoenzyme = <b>TERT</b> (sous-unité catalytique, gène au 5p15.33) + <b>TERC/hTR</b> (ARN matrice, 3q26) + <b>dyskérine (DKC1)</b>, NOP10, NHP2, GAR1<br>• <b>TERC contient la matrice</b> <b>3'-CAAUCCCAAUC-5'</b> complémentaire de TTAGGG<br>• ⚠️ <b>DYSKÉRATOSE CONGÉNITALE</b> : mutation de TERT, TERC ou DKC1 → télomères courts → triade <b>dysplasie des ongles + leucoplasie buccale + pigmentation réticulée</b> + <b>insuffisance médullaire</b><br><br>⚠️ Le raccourcissement télomérique = « <b>HORLOGE BIOLOGIQUE</b> » corrélée au vieillissement. La longueur télomérique des leucocytes est un <b>biomarqueur de l'âge biologique</b>.","t":"genetique-2026 EXAM-2026"},{"q":"Q24 &amp; Q30 — Les <b>CHROMOSOMES ACROCENTRIQUES</b> : (bras q très petit · contiennent de l'ADN satellite · contiennent une constriction secondaire · sont au nombre de 10 · contiennent une constriction primaire)","a":"<b>✅ Ils CONTIENNENT DE L'ADN SATELLITE</b> (sur leurs bras courts)<br><b>✅ Ils CONTIENNENT UNE CONSTRICTION SECONDAIRE</b><br><b>✅ Ils SONT AU NOMBRE DE 10</b> (5 paires)<br><br><b>LES 5 PAIRES ACROCENTRIQUES CHEZ L'HOMME :</b> <b>13, 14, 15, 21, 22</b> → soit <b>2 × 5 = 10 CHROMOSOMES</b> ✅<br><br><b>STRUCTURE D'UN ACROCENTRIQUE :</b><br>• Centromère <b>très près d'une extrémité</b> → <b>bras court (p) TRÈS PETIT</b>, <b>bras long (q) TRÈS GRAND</b> · <b>IC &lt; 25 %</b><br>• Le <b>bras court (p)</b> porte, de la base vers l'extrémité :<br>&nbsp;&nbsp;1. Une <b>CONSTRICTION SECONDAIRE</b> = le <b>NOR (Nucleolar Organizer Region)</b><br>&nbsp;&nbsp;2. Un <b>PÉDONCULE (stalk)</b> — fin filament<br>&nbsp;&nbsp;3. Un <b>SATELLITE (sat)</b> — petite masse d'hétérochromatine terminale<br>• Le <b>NOR</b> contient les gènes des <b>ARNr 45S</b> (précurseur des ARNr 18S, 5,8S, 28S), répétés <b>en tandem ~300 fois</b> → c'est le site de formation du <b>NUCLÉOLE</b><br>• L'<b>ADN SATELLITE</b> des bras courts = <b>satellites I, II, III</b> → détecté par les <b>bandes C</b> et coloré en argent (<b>Ag-NOR</b>)<br><br><b>⚠️ IMPORTANCE CLINIQUE — LES TRANSLOCATIONS ROBERTSONIENNES :</b><br>• Réarrangement <b>ÉQUILIBRÉ</b> entre <b>DEUX ACROCENTRIQUES</b> : leurs <b>bras longs (q) FUSIONNENT au niveau du centromère</b>, et leurs <b>bras courts (p) sont PERDUS</b><br>• ⚠️ <b>La perte des bras courts est SANS CONSÉQUENCE</b> : ils ne contiennent que des <b>répétitions d'ARNr</b> (10 copies au total — en perdre 2 ne change rien)<br>• Le porteur a donc <b>45 chromosomes</b> mais est <b>PHÉNOTYPIQUEMENT NORMAL</b><br>• <b>Fréquence : 1/1 000 naissances</b> — le réarrangement chromosomique <b>le plus fréquent</b> chez l'Homme<br>• Les plus fréquentes : <b>rob(13;14)</b> (la plus commune), <b>rob(14;21)</b>, <b>rob(21;21)</b><br>• <b>RISQUE POUR LA DESCENDANCE</b> (gamètes déséquilibrés) :<br>&nbsp;&nbsp;– <b>TRISOMIE 21 PAR TRANSLOCATION</b> — ⚠️ <b>~4 % de toutes les trisomies 21</b>. Dans une <b>rob(21;21)</b>, le risque est de <b>100 %</b> (tout gamète porte 2 copies de 21, ou 0)<br>&nbsp;&nbsp;– <b>TRISOMIE 13</b> (si rob(13;14))<br>&nbsp;&nbsp;– <b>MONOSOMIE</b> → fausses couches à répétition<br>• ⚠️ <b>Dépistage</b> : caryotype des parents en cas de trisomie par translocation chez l'enfant, ou de fausses couches à répétition<br>• Nomenclature : <b>45,XX,der(14;21)(q10;q10)</b> ou <b>45,XX,rob(14;21)</b><br><br><b>❌ A — « Ont un bras q très petit » : FAUX — C'EST L'INVERSE</b> ⚠️<br>• Acrocentrique = bras <b>p (petit) TRÈS COURT</b> et bras <b>q (queue) TRÈS LONG</b><br>• <b>q = bras LONG</b> (du français « queue ») ; <b>p = bras COURT</b> (du français « petit »)<br><br><b>❌ B — « Index centromérique = 1 » : FAUX</b> ⚠️<br>• IC = 1 (ou 100 %) → le bras p représenterait toute la longueur → c'est un chromosome <b>TÉLOCENTRIQUE</b> (p absent)<br>• ⚠️ <b>Les TÉLOCENTRIQUES N'EXISTENT PAS chez l'HOMME</b> (ils existent chez la souris)<br>• Les acrocentriques ont un <b>IC &lt; 25 %</b> — petit, mais <b>pas nul</b><br><br><b>❌ E — « Ont une constriction PRIMAIRE » : techniquement VRAI mais NON DISTINGUANT</b> ⚠️<br>• La constriction primaire = le <b>CENTROMÈRE</b>, que <b>TOUS</b> les chromosomes possèdent<br>• Donc ce critère <b>ne distingue pas</b> les acrocentriques<br>• Dans un QCM portant sur leurs <b>caractéristiques PROPRES</b>, la réponse attendue est <b>❌</b> — leur particularité est la constriction <b>SECONDAIRE</b>","t":"genetique-2026 EXAM-2026"},{"q":"Q25 — Au cours du caryotype, le <b>CHOC HYPO-TONIQUE</b> : (première étape après la culture · réalisé par l'ajout d'un milieu hypotonique · se base sur l'osmose · entraîne l'éclatement des noyaux · réalisé par un mélange d'alcool et d'acide acétique)","a":"<b>✅ B — Réalisé par l'ajout d'un milieu HYPO-TONIQUE</b><br><b>✅ C — Se base sur le phénomène d'OSMOSE</b><br><b>✅ D — Entraîne l'éclatement (le gonflement) des noyaux</b><br><br><b>MÉCANISME :</b><br>1. Après la culture et le blocage en métaphase (colchicine), on ajoute une solution <b>HYPO-TONIQUE</b> — classiquement du <b>KCl 0,075 M</b> ou du <b>citrate de sodium 0,8 %</b>, à <b>37 °C pendant 15 à 25 min</b><br>2. La concentration en solutés est <b>PLUS FAIBLE à l'extérieur</b> qu'à l'intérieur de la cellule<br>3. Par <b>OSMOSE</b>, l'<b>EAU ENTRE dans la cellule</b><br>4. La cellule <b>GONFLE</b>, la membrane s'étire, le <b>NOYAU ÉCLATE</b><br>5. ⚠️ <b>RÉSULTAT RECHERCHÉ</b> : les <b>CHROMOSOMES S'ÉPARPILLENT</b> dans le cytoplasme gonflé → à l'étalement, ils seront <b>BIEN SÉPARÉS</b> → on peut les <b>COMPTER et les CLASSER</b><br><br>⚠️ <b>Sans choc hypotonique, les chromosomes resteraient AGGLUTINÉS dans le noyau</b> → caryotype illisible.<br><br><b>⚠️ LE TEMPS DOIT ÊTRE CONTRÔLÉ :</b><br>• <b>Trop court</b> → chromosomes encore agglutinés<br>• <b>Trop long</b> → les cellules éclatent complètement, les chromosomes sont <b>perdus hors de la lame</b> → caryotype inexploitable<br><br><b>❌ A — « C'est la PREMIÈRE étape après la culture cellulaire » : FAUX</b> ⚠️<br>L'ordre réel :<br>1. Prélèvement<br>2. <b>CULTURE CELLULAIRE</b> (mitogène PHA, 48–72 h)<br>3. <b>BLOCAGE EN MÉTAPHASE — COLCHICINE / COLCÉMIDE</b> (30–60 min) ← ⚠️ <b>C'EST CETTE ÉTAPE</b> qui vient juste après la culture<br>4. <b>CHOC HYPO-TONIQUE</b> (KCl, 15–25 min)<br>5. <b>FIXATION</b> (méthanol : acide acétique 3:1, ×2 à ×3)<br>6. <b>ÉTALEMENT</b> sur lame + séchage<br>7. <b>DÉNATURATION + MARQUAGE</b> (bandes G = trypsine + Giemsa ; ou R, C, FISH)<br>8. <b>OBSERVATION et ANALYSE</b> (karyogramme)<br>→ Le choc hypotonique est la <b>4ᵉ étape</b>.<br><br><b>❌ E — « Réalisé par un mélange d'alcool et d'acide acétique » : FAUX — C'EST LE FIXATEUR</b> ⚠️<br>• <b>Méthanol : acide acétique glacial = 3 : 1</b> (« fixateur de Carnoy modifié ») → utilisé pour la <b>FIXATION</b> (étape 5), <b>APRÈS</b> le choc hypotonique<br>• Rôle : <b>tuer et durcir</b> les cellules, <b>précipiter les protéines</b>, <b>conserver la morphologie</b> des chromosomes, éliminer l'eau et les lipides<br>• ⚠️ Doit être <b>PRÉPARÉ EXTTEMPORANÉMENT</b> (frais) et <b>CHANGÉ 2 à 3 fois</b><br>• L'<b>acide acétique</b> est le composant qui <b>durcit les chromosomes</b> et améliore l'étalement","t":"genetique-2026 EXAM-2026"},{"q":"Q26 &amp; Q27 — Les <b>BANDES C</b> et les <b>BANDES G</b> : qu'est-ce que chacune met en évidence ?","a":"<b>BANDES C → ✅ Centromères · ✅ Hétérochromatine constitutive</b><br><b>BANDES G → ✅ Régions pauvres en gènes · ✅ Régions de réplication tardive</b><br><br><b>📋 LES 4 TECHNIQUES DE MARQUAGE CHROMOSOMIQUE — TABLEAU À APPRENDRE :</b><br><br><b>1. BANDES G (G = Giemsa)</b> — ⭐ <b>LA PLUS UTILISÉE EN ROUTINE</b><br>• <b>Protocole</b> : <b>TRYPSINE</b> (digestion partielle des protéines) puis <b>GIEMSA</b><br>• <b>Résultat</b> : alternance de bandes <b>SOMBRES (G-positives)</b> et <b>CLAIRES (G-négatives)</b><br>• <b>BANDES G-POSITIVES (sombres)</b> = <b>riches en A-T</b> · <b>PAUVRES EN GÈNES</b> ✅ · <b>RÉPLICATION TARDIVE</b> (fin de phase S) ✅ · <b>hétérochromatine</b> condensée · transcriptionnellement <b>inactives</b><br>• <b>BANDES G-NÉGATIVES (claires)</b> = <b>riches en G-C</b> · <b>RICHES EN GÈNES</b> (la majorité des gènes humains) · <b>RÉPLICATION PRÉCOCE</b> · <b>euchromatine</b> active · contiennent les <b>îlots CpG</b> et les <b>gènes de ménage (housekeeping)</b><br>• <b>Résolution</b> : <b>400 bandes</b> en routine · <b>550 à 850 bandes</b> en prométaphase<br><br><b>2. BANDES R (R = Reverse)</b><br>• <b>Protocole</b> : <b>CHALEUR</b> (dénaturation thermique en tampon phosphate à 87 °C) puis Giemsa ou acridine-orange<br>• <b>Résultat</b> : <b>INVERSE EXACT des bandes G</b><br>&nbsp;&nbsp;– Bandes <b>R-positives (sombres)</b> = riches en <b>G-C</b>, <b>riches en gènes</b>, réplication <b>PRÉCOCE</b><br>&nbsp;&nbsp;– Bandes <b>R-négatives (claires)</b> = riches en A-T, pauvres en gènes, réplication tardive<br>• ⚠️ <b>Avantage</b> : visualise mieux les <b>EXTRÉMITÉS des chromosomes (télomères)</b> → détecte les <b>petites délétions TERMINALES</b> (que les bandes G masquent)<br><br><b>3. BANDES C (C = Centromère / hétérochromatine Constitutive)</b><br>• <b>Protocole</b> « <b>BSG</b> » : <b>BARYE Ba(OH)₂</b> puis <b>SSC à 60 °C</b> puis Giemsa<br>• <b>Résultat</b> : ne colore <b>QUE l'HÉTÉROCHROMATINE CONSTITUTIVE</b> ✅ (qui reste sombre) — tout le reste est décoloré<br>• ⭐ <b>Met en évidence :</b><br>&nbsp;&nbsp;– Les <b>CENTROMÈRES</b> de tous les chromosomes ✅<br>&nbsp;&nbsp;– Les <b>BRAS COURTS des ACROCENTRIQUES</b> (13, 14, 15, 21, 22) → <b>satellites et pédoncules</b><br>&nbsp;&nbsp;– L'<b>hétérochromatine du bras long du Y (Yq12)</b> — très brillante<br>&nbsp;&nbsp;– L'hétérochromatine constitutive des chromosomes <b>1qh, 9qh, 16qh</b> ⚠️ <b>polymorphismes NORMAUX</b><br>&nbsp;&nbsp;– Le <b>CORPUSCULE DE BARR</b> (chromosome X inactif)<br>• <b>Utilité</b> : identifier les <b>chromosomes marqueurs</b>, les <b>polymorphismes hétérochromatiques</b>, les <b>translocations robertsoniennes</b><br><br><b>4. BANDES T (T = Télomère)</b><br>• Coloration <b>spécifique des TÉLOMÈRES</b> → détecte les <b>réarrangements sub-télomériques cryptiques</b> (cause de ~5–10 % des retards mentaux inexpliqués)<br><br><b>+ Autres marquages :</b> <b>bandes Q</b> (quinacrine, fluorescence UV) · <b>Ag-NOR</b> (argentique, organisateurs nucléolaires)<br><br><b>❌ POUR Q26 (BANDES C) :</b><br>• ❌ « Les télomères » → bandes <b>T</b> (ou R)<br>• ❌ « L'euchromatine » → <b>L'INVERSE</b> : les bandes C colorent l'<b>HÉTÉRO</b>chromatine<br>• ⚠️ « La partie distale du chromosome Y » → <b>PIÈGE SUBTIL</b> : la région <b>Yq12</b> EST bien mise en évidence par les bandes C. Mais dans un QCM à 2 réponses, les 2 attendues sont <b>centromères + hétérochromatine constitutive</b><br><br><b>❌ POUR Q27 (BANDES G) :</b><br>• ❌ « Les télomères » → bandes <b>T</b> ou <b>R</b><br>• ❌ « Les régions riches en CG » → <b>L'INVERSE</b> ⚠️ : les bandes G-POSITIVES (sombres) sont <b>riches en A-T</b>. Les régions <b>riches en G-C</b> apparaissent en bandes <b>G-NÉGATIVES (claires)</b> = bandes <b>R-positives</b><br>• ❌ « L'hétérochromatine constitutive » → bandes <b>C</b><br><br><b>⚠️ MOYEN MNÉMOTÉCHNIQUE :</b><br>• <b>G</b> = « <b>G</b>iemsa » → les bandes <b>G-POSitives (sombres)</b> sont <b>A-T riches, Gène-pauvres, tardives</b><br>• <b>C</b> = « <b>C</b>entromère, <b>C</b>onstitutive »<br>• <b>R</b> = « <b>R</b>everse » → l'inverse de G<br>• <b>T</b> = « <b>T</b>élomère »","t":"genetique-2026 EXAM-2026"},{"q":"Q28 — La <b>FISH</b> (Hybridation Fluorescente In Situ) : (met en évidence une anomalie chromosomique précise · détecte des délétions invisibles au caryotype · peut se faire sur des noyaux en interphase · nécessite des cultures cellulaires · permet d'étudier la méthylation de l'ADN)","a":"<b>✅ A — Met en évidence une anomalie chromosomique PRÉCISE (ciblée)</b><br><b>✅ B — Détecte des délétions invisibles au caryotype</b><br><b>✅ C — Peut se faire sur des NOYAUX EN INTERPHASE (sans métaphase)</b><br><br><b>PRINCIPE :</b><br>1. On utilise une <b>SONDE d'ADN simple brin</b>, marquée par un <b>FLUOROCHROME</b> (FITC vert, rhodamine rouge, Cy3, Cy5, spectrum-orange/green)<br>2. La sonde est <b>COMPLÉMENTAIRE</b> de la séquence chromosomique recherchée<br>3. On <b>DÉNATURE</b> l'ADN de la préparation (chaleur 72–75 °C en formamide) → les chromosomes deviennent simple brin<br>4. On applique la sonde → elle s'<b>HYBRIDE</b> avec sa cible complémentaire<br>5. <b>LAVAGES</b> pour éliminer les sondes non hybridées<br>6. <b>CONTRE-COLORATION</b> au <b>DAPI</b> (bleu, marque tout l'ADN)<br>7. Lecture au <b>MICROSCOPE À FLUORESCENCE</b> avec des filtres spécifiques<br><br>⚠️ <b>RÉSOLUTION : 50 kb à 5 Mb</b> — très supérieure au caryotype (5–10 Mb)<br><br><b>✅ C — LE POINT CLÉ : FISH SUR NOYAUX EN INTERPHASE</b><br>C'est <b>L'AVANTAGE MAJEUR</b> de la FISH :<br>• On <b>n'a PAS besoin de cellules en division</b> → <b>PAS de culture cellulaire</b><br>• ⚠️ <b>On peut donc travailler sur des tissus FIXÉS (paraffine, FFPE)</b>, des <b>frottis</b>, des <b>cellules de liquide amniotique non cultivées</b>, des <b>spermatozoïdes</b>, des <b>tumeurs solides</b><br>• <b>RÉSULTAT EN 24 H</b> contre 7–14 jours pour un caryotype → <b>DIAGNOSTIC PRÉNATAL RAPIDE</b><br>• ⚠️ <b>Mais</b> : sans métaphase, on ne peut pas voir la <b>STRUCTURE</b> des chromosomes (pas de bandes) → on ne voit que le <b>NOMBRE de SIGNAUX</b><br><br><b>LES TYPES DE SONDES :</b><br>• <b>Sonde locus-spécifique (LSI)</b> : cible UN gène / UNE région unique → détecte <b>délétions</b> (1 signal au lieu de 2), <b>amplifications</b> (signaux multiples), <b>translocations</b> (sondes <b>« break apart »</b> qui se séparent)<br>• <b>Sonde centromérique (CEP — Chromosome Enumeration Probe)</b> : cible l'<b>α-satellite</b> du centromère → <b>COMPTE les chromosomes</b> en interphase → aneuploïdies (13, 18, 21, X, Y)<br>• <b>Sonde télesomique / sub-télomérique</b><br>• <b>PEINTURE CHROMOSOMIQUE (WCP — Whole Chromosome Paint)</b> : mélange de sondes couvrant <b>TOUT un chromosome</b> → identifie les <b>chromosomes marqueurs</b> et caractérise les <b>translocations complexes</b><br>• <b>SKY / M-FISH</b> (Spectral Karyotyping / Multiplex-FISH) : <b>24 couleurs différentes</b>, une par chromosome → cartographie tous les réarrangements complexes<br>• <b>CGH-array (ACPA comparative)</b> : voir Q29<br><br><b>✅ B — EXEMPLES DE MALADIES DÉTECTÉES PAR FISH :</b><br>• <b>SYNDROME DE DiGEORGE / VCFS</b> : del <b>22q11.2</b> (sonde TUPLE1/N25) — <b>INVISIBLE au caryotype standard</b> ⚠️<br>• <b>SYNDROME DE WILLIAMS-BEUREN</b> : del <b>7q11.23</b> (gène ELN)<br>• <b>PRADER-WILLI / ANGELMAN</b> : del <b>15q11-q13</b><br>• <b>LEUCÉMIE MYÉLOÏDE CHRONIQUE (LMC)</b> : <b>t(9;22)(q34;q11)</b> → <b>BCR-ABL1</b> — sonde « double fusion »<br>• <b>LYMPHOME DE BURKITT</b> : <b>t(8;14)</b> → <b>MYC-IGH</b><br>• <b>LEUCÉMIE AIGUË PROMYÉLOCYTAIRE (LAM3)</b> : <b>t(15;17)</b> → <b>PML-RARA</b> ⚠️ urgence thérapeutique (ATRA)<br>• <b>CANCER DU SEIN</b> : amplification <b>HER2/ERBB2 (17q12)</b> → détermine le traitement par <b>trastuzumab</b><br>• <b>NEUROBLASTOME</b> : amplification <b>N-MYC (2p24)</b> → facteur pronostique<br>• <b>X FRAGILE</b> : expansion FMR1 (mais diagnostic = PCR/Southern blot)<br><br><b>❌ D — « Nécessite des cultures cellulaires » : FAUX — C'EST L'INVERSE</b> ⚠️<br>• C'est le <b>CARYOTYPE</b> qui nécessite une culture cellulaire (mitogène PHA, 48–72 h)<br>• La <b>FISH</b> fonctionne sur des <b>NOYAUX EN INTERPHASE</b> → <b>PAS de culture</b><br><br><b>❌ E — « Permet d'étudier la MÉTHYLATION de l'ADN » : FAUX</b><br>• La FISH standard ne détecte que la <b>PRÉSENCE / ABSENCE / POSITION</b> d'une séquence — pas son <b>état épigénétique</b><br>• Pour la méthylation : <b>bisulfite sequencing</b>, <b>MS-MLPA</b>, <b>MethyLight</b>, <b>pyroséquençage</b>, <b>ACPA-SNP avec analyse de B-allele frequency</b><br>• ⚠️ Variantes spécialisées : <b>FISH après digestion par une enzyme sensible à la méthylation</b>, ou <b>immuno-FISH (anti-5-méthylcytosine)</b> — mais ce ne sont pas des FISH classiques<br><br><b>📋 FISH vs CARYOTYPE vs ACPA :</b><br>• <b>CARYOTYPE</b> : vue GLOBALE, tous les chromosomes, résolution 5–10 Mb, nécessite culture, détecte mosaïcisme et anomalies équilibrées<br>• <b>FISH</b> : vue CIBLÉE (il faut savoir quoi chercher), résolution 50 kb–5 Mb, pas de culture, rapide<br>• <b>ACPA</b> : vue GÉNOMIQUE (tout le génome d'un coup), résolution 10 kb–100 kb, ⚠️ <b>ne détecte PAS les anomalies ÉQUILIBRÉES</b> ni les mosaïcismes de bas niveau","t":"genetique-2026 EXAM-2026"},{"q":"Q29 — L'<b>ACPA</b> (Analyse Chromosomique sur Puce à ADN) : (détecte les délétions · détecte les duplications · détecte les translocations équilibrées · détecte les mutations ponctuelles · permet de déterminer les CNV)","a":"<b>✅ A — Détecte les DÉLÉTIONS</b><br><b>✅ B — Détecte les DUPLICATIONS</b><br><b>✅ E — Permet de déterminer les CNV (Copy Number Variations)</b><br><br><b>DÉFINITION :</b> l'<b>ACPA</b> (Array-CGH, Comparative Genomic Hybridization) est une technique de <b>cytogénétique moléculaire à HAUTE RÉSOLUTION</b> qui compare le génome du patient à un génome de référence pour détecter les <b>VARiations du NOMBRE DE COPIES (CNV)</b> — gains (duplications) et pertes (délétions).<br><br><b>PRINCIPE DE L'ACPA COMPARATIVE :</b><br>1. <b>ADN du patient</b> marqué en <b>VERT (Cy3)</b> · <b>ADN témoin</b> marqué en <b>ROUGE (Cy5)</b><br>2. Les deux sont <b>mélangés en quantité égale</b> et <b>co-hybridés</b> sur la puce<br>3. La puce contient des <b>milliers/millions de sondes</b> réparties sur tout le génome<br>4. Après hybridation, on mesure le <b>RAPPORT DES FLUORESCENCES (Cy3/Cy5)</b> pour chaque sonde<br>5. Interprétation :<br>&nbsp;&nbsp;• <b>Rapport = 1 (jaune)</b> → <b>NORMAL</b> (2 copies)<br>&nbsp;&nbsp;• <b>Rapport &lt; 1 (rouge)</b> → <b>DÉLÉTION</b> (perte, 1 copie)<br>&nbsp;&nbsp;• <b>Rapport &gt; 1 (vert)</b> → <b>DUPLICATION / GAIN</b> (3+ copies)<br><br><b>LES 2 TYPES DE PUCES :</b><br>• <b>ACPA-CGH (comparative)</b> : patient vs témoin, sondes <b>BAC</b> ou <b>oligonucléotides</b><br>• <b>ACPA-SNP</b> ⚠️ : utilise des sondes <b>SNP</b> → en plus des CNV, donne le <b>GÉNOTYPE</b> et la <b>fréquence allélique B (BAF)</b> → détecte aussi :<br>&nbsp;&nbsp;– Les <b>DISOMIES UNIPARENTALES (DUP)</b> — absence d'hétérozygotie (LOH) sans perte de copies<br>&nbsp;&nbsp;– Les <b>ANEUPLOÏDIES complètes</b> (13, 18, 21, X, Y)<br>&nbsp;&nbsp;– Les <b>MOSAÏCISMES</b> (si &gt; 20–30 %)<br>&nbsp;&nbsp;– La <b>CONSANGUINITÉ</b> (régions d'homozygotie)<br><br><b>RÉSOLUTION :</b> <b>10 kb à 100 kb</b> selon la puce (jusqu'à <b>1 kb</b> avec les puces haute densité) → <b>50 à 500 fois MEILLEURE que le caryotype</b> ⚠️<br><br><b>✅ E — LES CNV :</b><br>• Définition : variation du <b>nombre de copies</b> d'un segment d'ADN (&gt; 1 kb) par rapport au génome de référence<br>• ⚠️ Les CNV couvrent <b>~12 % du génome humain</b> — ils sont <b>FRÉQUENTS et SOUVENT BÉNINS</b><br>• Base de données de référence : <b>DGV</b> (Database of Genomic Variants), <b>DECIPHER</b>, <b>ISCA/ClinGen</b>, <b>gnomAD-SV</b><br>• ⚠️ Le résultat doit être classé selon les critères <b>ACMG/ClinGen (2020)</b> : <b>pathogène · probablement pathogène · de signification incertaine (VUS) · probablement bénin · bénin</b><br><br><b>INDICATIONS ⚠️ (recommandations internationales) :</b><br>• <b>Retard de développement / déficience intellectuelle</b> inexpliqué → ⭐ <b>L'ACPA EST LE TEST DE PREMIÈRE LIGNE</b> (rendement diagnostique <b>15–20 %</b>)<br>• <b>Malformations congénitales multiples</b><br>• <b>Troubles du spectre de l'autisme</b><br>• <b>Fausses couches à répétition</b> (sur produits de conception)<br>• <b>Anomalies prénatales échographiques</b> avec caryotype normal<br>• <b>Hématologie/oncologie</b> : caractérisation des réarrangements tumoraux<br><br><b>❌ C — « Détecte les translocations ÉQUILIBRÉES » : FAUX — LIMITE FONDAMENTALE</b> ⚠️⚠️<br>• Une translocation <b>ÉQUILIBRÉE</b> = échange de matériel <b>SANS PERTE NI GAIN net</b><br>• Le <b>NOMBRE TOTAL DE COPIES ne change pas</b> → l'ACPA ne voit <b>RIEN</b><br>• ⚠️ <b>POUR LES DÉTECTER : CARYOTYPE, FISH, ou SÉQUENÇAGE DU GÉNOME ENTIER (WGS)</b><br>• ⚠️ <b>Exception</b> : l'<b>ACPA-SNP</b> peut <b>SUSPECTER</b> une translocation équilibrée si elle <b>PERTURBE UN GÈNE</b> (rupture intragénique) ou si elle crée une <b>petite délétion au point de cassure</b> — mais ne peut pas la caractériser<br>• ⚠️ <b>Autre limite</b> : les <b>INVERSIONS équilibrées</b> et les <b>insertions équilibrées</b> sont aussi <b>INVISIBLES</b><br><br><b>❌ D — « Détecte les mutations ponctuelles » : FAUX</b><br>• Une mutation ponctuelle (<b>SNV</b>) ne change <b>PAS le nombre de copies</b> → invisible<br>• <b>POUR LES DÉTECTER : SÉQUENÇAGE</b> — <b>Sanger</b> (un gène), <b>panel de gènes NGS</b>, <b>WES (exome)</b>, <b>WGS (génome entier)</b><br><br><b>📋 AUTRES LIMITES DE L'ACPA :</b><br>• Ne détecte pas les <b>mosaïcismes de bas niveau (&lt; 20–30 %)</b><br>• Ne détecte pas les <b>mutations d'équilibre</b> (translocations, inversions, insertions)<br>• Ne détecte pas les <b>EXPANSIONS DE TRIPLETS</b> (X fragile, Huntington, DM1) → PCR/Southern blot<br>• Ne détecte pas les <b>anomalies de MÉTHYLATION / empreinte parentale</b> → tests de méthylation<br>• Ne détecte pas les <b>polyploïdies pures (triploïdie)</b> avec ACPA-CGH (ratio inchangé) → ACPA-SNP ou QF-PCR<br>• ⚠️ <b>Ne donne PAS d'information sur la STRUCTURE des chromosomes</b> (on ne voit pas « où » est le matériel)<br>• ⚠️ Génère beaucoup de <b>VUS (variants de signification incertaine)</b> → difficulté de conseil génétique<br><br><b>📊 HIÉRARCHIE DES TECHNIQUES :</b><br><b>Caryotype</b> (5–10 Mb, vue globale, équilibré + mosaïque) → <b>FISH</b> (50 kb–5 Mb, ciblée) → <b>ACPA</b> (10–100 kb, génomique, CNV uniquement) → <b>MLPA</b> (ciblée, 40–60 régions) → <b>Séquençage NGS</b> (1 pb, SNV + petits indels + CNV selon bio-informatique)","t":"genetique-2026 EXAM-2026"},{"q":"Q31 — La différence entre un <b>MOSAÏQUE</b> et une <b>CHIMÈRE</b> :","a":"<b>📋 MOSAÏQUE vs CHIMÈRE — DIFFÉRENCE FONDAMENTALE :</b><br><br><b>🔵 MOSAÏQUE (mosaïcisme)</b><br>• Définition : individu avec <b>DEUX (ou plus) populations cellulaires GÉNÉTIQUEMENT DIFFÉRENTES</b>, issues d'<b>UN SEUL ZYGOTE</b> ⚠️<br>• <b>Origine</b> : <b>NON-DISJONCTION MITOTIQUE</b> (ou mutation somatique) <b>APRÈS la fécondation</b>, pendant les premières divisions de l'embryon<br>• ⚠️ Les deux lignées <b>PARTAGENT UNE PARTIE DE LEUR GÉNOME</b> (elles descendent de la même cellule-œuf)<br>• <b>Exemples</b> : <b>mos 46,XX/47,XX,+21</b> (trisomie 21 en mosaïque — phénotype atténué) · <b>mos 45,X/46,XX</b> (Turner en mosaïque) · <b>mos 46,XY/47,XXY</b> (Klinefelter en mosaïque)<br>• <b>Mosaïcisme somatique</b> : mutations acquises dans un tissu — ex. <b>syndrome de McCune-Albright</b> (mutation GNAS post-zygotique, taches café-au-lait en « côtes du Maine »), <b>syndrome de Proteus</b> (AKT1), <b>syndrome de Sturge-Weber</b> (GNAQ)<br>• <b>Mosaïcisme germinale (gonosomique)</b> ⚠️ PIÈGE DE CONSEIL GÉNÉTIQUE : la mutation n'est présente que dans <b>UNE PARTIE des gamètes</b> d'un parent <b>PHÉNOTYPIQUEMENT SAIN</b>. Résultat : ce parent peut avoir <b>PLUSIEURS ENFANTS ATTEINTS</b> d'une maladie considérée comme « de novo » (ex. : <b>ostéogenèse imparfaite type II</b>, <b>myopathie de Duchenne</b>, <b>achondroplasie</b>). Le <b>risque de récurrence est de ~1 à 5 %</b>, pas nul.<br>• <b>Détection</b> : compter <b>BEAUCOUP de cellules</b> (30–50 métaphases, voire 100+), car la lignée anormale peut être <b>minoritaire</b> ou <b>restreinte à un seul tissu</b> → parfois besoin d'un <b>second prélèvement (peau, muqueuse buccale)</b><br>• <b>Risque de récurrence pour la descendance</b> : <b>FAIBLE</b> (le mosaïcisme survient de novo)<br><br><b>🔴 CHIMÈRE (chimérisme)</b><br>• Définition : individu avec <b>DEUX (ou plus) populations cellulaires GÉNÉTIQUEMENT DIFFÉRENTES</b>, issues de <b>DEUX ZYGOTES DIFFÉRENTS</b> (donc de <b>deux fécondations séparées</b>) ⚠️<br>• <b>Origine</b> : <b>FUSION de deux embryons / deux blastocystes</b> très précocement, ou <b>ÉCHANGE de cellules entre jumeaux</b> par des <b>anastomoses vasculaires placentaires</b><br>• ⚠️ Les deux lignées sont <b>TOTALEMENT DIFFÉRENTES</b> (elles viennent de gamètes différents → génomes indépendants)<br>• <b>Exemples</b> :<br>&nbsp;&nbsp;– <b>Chimérisme sanguin entre jumeaux dizygotes</b> : les jumeaux bovins de sexes différents → <b>FREEMARTIN</b> (femelle stérilisée par les hormones du mâle via les anastomoses placentaires). Chez l'homme : <b>jumeaux dizygotes avec 2 populations de globules rouges</b><br>&nbsp;&nbsp;– <b>Chimérisme tétragamétique</b> (fusion de 2 embryons) → individus avec <b>2 couleurs d'yeux (hétérochromie)</b>, <b>2 empreintes génétiques selon le tissu</b>, peau en mosaïque<br>&nbsp;&nbsp;– <b>Chimérisme iatrogène</b> : ⭐ <b>APRÈS UNE GREFFE</b> — moelle osseuse (chimérisme hématopoïétique complet), organe solide (micro-chimérisme), <b>transfusion sanguine</b><br>&nbsp;&nbsp;– <b>Micro-chimérisme fœto-maternel</b> : des <b>cellules fœtales passent dans la circulation maternelle</b> pendant la grossesse et persistent des décennies (impliqué dans certaines maladies auto-immunes comme la sclérodermie)<br>• <b>Détection</b> : ⚠️ <b>Le résultat DÉPEND DU TISSU PRÉLEVÉ</b> — le sang peut donner un génotype, la peau ou la bouche un autre. On découvre souvent le chimérisme à l'occasion d'un <b>test de paternité « négatif »</b> alors que l'homme est bien le père biologique (son sperme a un autre génotype que son sang)<br>• ⚠️ En greffe de moelle : on suit le <b>CHIMÉRISME</b> (proportion de cellules du donneur) par <b>STR/PCR</b> pour détecter une rechute ou un rejet<br><br><b>📊 TABLEAU RÉCAPITULATIF :</b><br>• <b>Nombre de zygotes</b> : Mosaïque = <b>1</b> · Chimère = <b>2 ou plus</b><br>• <b>Moment</b> : Mosaïque = <b>POST-zygotique (mitose)</b> · Chimère = <b>fusion de 2 zygotes / échange entre jumeaux</b><br>• <b>Parenté des lignées</b> : Mosaïque = lignées <b>APPARENTÉES</b> (même origine) · Chimère = lignées <b>INDÉPENDANTES</b><br>• <b>Cause</b> : Mosaïque = <b>erreur mitotique</b> · Chimère = <b>fusion embryonnaire / anastomose placentaire / greffe</b><br>• <b>Nomenclature</b> : Mosaïque = préfixe <b>« mos »</b> (ex. <b>mos 45,X/46,XX</b>) · Chimère = préfixe <b>« chi »</b> (ex. <b>chi 46,XX/46,XY</b>)<br><br><b>💡 ASTUCE MNÉMOTÉCHNIQUE :</b><br>• <b>MOSAÏQUE</b> = comme une mosaïque d'art : des <b>tesselles DIFFÉRENTES mais du MÊME tableau</b> (un seul zygote)<br>• <b>CHIMÈRE</b> = la chimère de la mythologie : <b>lion + chèvre + serpent</b> = <b>plusieurs ANIMAUX FUSIONNÉS</b> (plusieurs zygotes)","t":"genetique-2026 EXAM-2026"},{"q":"Q32 &amp; Q33 — La <b>DÉLÉTION</b> chromosomique : (perte de matériel génétique · peut être terminale ou interstitielle · entraîne une monosomie partielle · donne toujours un phénotype anormal · détectée par caryotype, FISH ou ACPA)","a":"<b>✅ Perte de matériel génétique</b><br><b>✅ Peut être TERMINALE ou INTERSTITIELLE</b><br><b>✅ Entraîne une MONOSOMIE PARTIELLE</b><br><br><b>DÉFINITION :</b> la <b>délétion</b> est la <b>PERTE d'un segment de chromosome</b> → le chromosome est <b>plus court</b>. Elle crée une <b>MONOSOMIE PARTIELLE</b> : il ne reste qu'<b>UNE SEULE COPIE</b> des gènes de la région délétée (au lieu de deux).<br><br><b>LES TYPES DE DÉLÉTION :</b><br>• <b>TERMINALE (del)</b> : perte du segment situé <b>à l'extrémité</b> du chromosome (après une <b>cassure unique</b>). Le fragment <b>sans centromère est perdu</b> lors de la division (il ne peut pas migrer).<br>&nbsp;&nbsp;Nomenclature : <b>del(5)(p15.2)</b> = délétion du chromosome 5 à partir de la bande p15.2 jusqu'au télomère<br>• <b>INTERSTITIELLE (del)</b> : perte d'un segment <b>INTERNE</b> (entre <b>DEUX cassures</b>), les extrémités se recolent.<br>&nbsp;&nbsp;Nomenclature : <b>del(15)(q11.2q13)</b> = délétion interstitielle entre q11.2 et q13<br>• <b>MICRODÉLÉTION</b> : trop petite pour être vue au caryotype standard (&lt; 5 Mb) → <b>FISH, ACPA, MLPA</b><br><br><b>⚠️ MÉCANISME DE FORMATION :</b><br>1. <b>CASSURE DOUBLE BRIN</b> de l'ADN (radiations ionisantes, agents chimiques, erreur de réplication)<br>2. Réparation <b>ERRONÉE par NHEJ</b> (Non-Homologous End Joining) → perte du fragment<br>3. Ou <b>RECOMBINAISON NON ALLÉLIQUE (NAHR)</b> entre des <b>répétitions segmentaires (LCR)</b> en position non allélique ⚠️ — c'est le mécanisme des <b>syndromes de microdélétion récurrents</b><br>4. Ou <b>MÉIOSE : crossing-over inégal</b><br><br><b>❌ « Donne TOUJOURS un phénotype anormal » : FAUX ⚠️ PIÈGE</b><br>C'est <b>LE piège classique</b> du QCM. Les exceptions :<br>• <b>CNV BÉNINS</b> : de <b>nombreuses délétions sont des POLYMORPHISMES NORMAUX</b> présents chez des individus sains (les CNV couvrent ~12 % du génome). ⚠️ Ex. : la délétion du gène <b>GSTM1</b> ou <b>GSTT1</b> est présente chez <b>~50 % de la population</b> — sans conséquence majeure.<br>• <b>Délétions dans des régions SANS GÈNE</b> (déserts géniques, hétérochromatine) → <b>aucun effet</b><br>• ⚠️ <b>EXEMPLE EMBLÉMATIQUE : la délétion de la région du gène SMN2 ? Non</b> — le vrai exemple est la <b>délétion CCR5-Δ32</b> : délétion de 32 pb dans le gène du récepteur CCR5 → homozygotes <b>RÉSISTANTS au VIH</b>. C'est une délétion <b>AVANTAGEUSE</b> !<br>• ⚠️ Autre exemple : <b>délétion du gène ACTN3 (R577X)</b> — fréquente, sans pathologie<br>• ⚠️ <b>HAPLOINSUFFISANCE vs REDONDANCE</b> : un gène <b>haplosuffisant</b> fonctionne normalement avec <b>une seule copie</b> → sa délétion hétérozygote n'a <b>pas d'effet</b>. Un gène <b>haploINSUFFISANT</b> a besoin de <b>deux copies</b> → sa perte cause la maladie.<br>• ⚠️ <b>Perte d'un chromosome entier ? Non</b> — mais les <b>délétions de gènes redondants</b> (familles multigéniques comme les ARNr) sont sans effet : c'est exactement pourquoi les <b>TRANSLOCATIONS ROBERTSONIENNES</b> (perte des bras courts des acrocentriques) sont <b>bénignes</b> chez le porteur.<br>→ Donc la réponse est <b>❌</b> : une délétion ne donne <b>PAS TOUJOURS</b> un phénotype anormal.<br><br><b>✅ DÉTECTION :</b><br>• <b>CARYOTYPE</b> (bandes G/R) : si la délétion &gt; <b>5–10 Mb</b><br>• <b>FISH</b> avec une <b>sonde locus-spécifique</b> : si <b>50 kb à 5 Mb</b> ⚠️ méthode de choix pour les microdélétions connues<br>• ⭐ <b>ACPA (puce à ADN)</b> : <b>10 à 100 kb</b>, explorations génomiques non ciblées<br>• <b>MLPA</b> (Multiplex Ligation-dependent Probe Amplification) : ciblée, jusqu'à 40–60 régions, moins chère<br>• <b>SÉQUENÇAGE NGS</b> (exome/génome) avec bio-informatique CNV<br>• <b>QF-PCR</b> en prénatal rapide<br><br><b>📋 CONSÉQUENCES GÉNÉRALES D'UNE DÉLÉTION PATHOGÈNE :</b><br>• <b>HAPLOINSUFFISANCE</b> : la moitié de la quantité de protéine ne suffit pas<br>• <b>EXPRESSION D'UN ALLÈLE RÉCESSIF</b> ⚠️ : si l'allèle restant est muté, le phénotype récessif s'exprime → mécanisme de la <b>RÉTINOBLASTOME</b> (« second hit »)<br>• <b>FUSION DE GÈNES</b> : si la cassure tombe dans deux gènes juxtaposés<br>• <b>PERTURBATION DE LA RÉGULATION</b> : perte d'enhancers/silencers → effet de position<br>• <b>DISRUPTION D'UN GÈNE</b> : cassure intragénique<br><br><b>📋 LES SYNDROMES DE MICRODÉLÉTION À CONNAÎTRE :</b><br>• <b>SYNDROME DE DiGEORGE / VELOCARDIOFACIAL</b> — <b>del 22q11.2</b> — gène <b>TBX1</b> — anomalie des 3ᵉ/4ᵉ poches pharyngées → <b>hypoplasie du thymus (immunodéficience T)</b> + <b>hypoplasie des parathyroïdes (hypocalcémie)</b> + cardiopathie conotroncale (tétralogie de Fallot, interruption de l'arc aortique) + fente palatine + faciès particulier. <b>1/4 000 naissances</b> — la microdélétion la plus fréquente<br>• <b>SYNDROME DE WILLIAMS-BEUREN</b> — <b>del 7q11.23</b> — gène <b>ELN (élastine)</b> — <b>sténose aortique supravalvulaire</b>, faciès d'« elfe », retard mental, <b>HYPERsociabilité</b>, hypercalcémie<br>• <b>PRADER-WILLI</b> — <b>del 15q11-q13 d'origine PATERNELLE</b> — hypotonie néonatale, <b>obésité hyperphagique</b>, hypogonadisme, retard mental<br>• <b>ANGELMAN</b> — <b>del 15q11-q13 d'origine MATERNELLE</b> (gène UBE3A) — retard mental sévère, ataxie, <b>rire inapproprié</b>, épilepsie ⚠️ <b>MÊME délétion, PHÉNOTYPE DIFFÉRENT selon le parent → EMPREINTE PARENTALE</b><br>• <b>SYNDROME DU CRI DU CHAT (5p−)</b> — <b>del 5p15.2</b> — cri de chat (larynx anormal), microcéphalie, retard sévère — visible au caryotype<br>• <b>WOLF-HIRSCHHORN</b> — <b>del 4p16.3</b> — faciès de « casque grec », retard sévère<br>• <b>WAGR</b> — <b>del 11p13</b> — Wilms + Aniridie + anomalies Génito-urinaires + Retard mental<br>• <b>MILLER-DIEKER</b> — <b>del 17p13.3</b> (LIS1) — lissencéphalie<br>• <b>SMITH-MAGENIS</b> — <b>del 17p11.2</b> (RAI1) — troubles du sommeil inversés, auto-mutilation<br>• <b>AZOOSPERMIE (facteur AZF)</b> — microdélétions <b>Yq11</b> — AZFa, AZFb, AZFc → infertilité masculine, transmise à tous les fils par ICSI ⚠️","t":"genetique-2026 EXAM-2026"},{"q":"Q34 — L'<b>INSTABILITÉ CHROMOSOMIQUE</b> (syndromes d'instabilité chromosomique) : cite 3 exemples avec leur mécanisme et leur risque tumoral","a":"<b>L'INSTABILITÉ CHROMOSOMIQUE</b> = tendance d'un génome à accumuler des <b>RÉARRANGEMENTS CHROMOSOMIQUES</b> (cassures, échanges, translocations) à un taux <b>ANORMALEMENT ÉLEVÉ</b>, à cause d'un <b>DÉFAUT des MÉCANISMES DE RÉPARATION DE L'ADN</b>.<br><br>⚠️ Ces maladies sont <b>AUTOSOMIQUES RÉCESSIVES</b> (sauf exceptions), avec un <b>RISQUE MAJEUR DE CANCER</b> dès l'enfance.<br><br><b>📋 LES 5 SYNDROMES À CONNAÎTRE PAR CŒUR :</b><br><br><b>1. ANÉMIE DE FANCONI ⭐ (la plus fréquente)</b><br>• <b>Gènes</b> : <b>22+ gènes FANC</b> (FANCA le plus fréquent ~65 %, FANCC, FANCD1=<b>BRCA2</b>, FANCD2, FANCE, FANCF, FANCG, FANCI, FANCJ=<b>BRIP1</b>, FANCM, FANCN=<b>PALB2</b>, FANCP=<b>SLX4</b>, FANCQ=<b>ERCC4</b>)<br>• <b>Hérédité</b> : <b>AR</b> (sauf <b>FANCB liée à l'X</b>, et <b>FANCR/RAD51 AD</b>)<br>• <b>Mécanisme</b> : défaut de la <b>VOIE FANC</b> qui répare les <b>PONTS INTER-BRINS (ICL — Interstrand Crosslinks)</b> par <b>réparation par recombinaison homologue (HR)</b>. La voie : détection → <b>ubiquitination de FANCD2/FANCI</b> par le complexe central → recrutement de <b>BRCA2/FANCD1, PALB2, BRCA1, RAD51</b> → HR<br>• <b>Test diagnostique ⚠️ SPÉCIFIQUE</b> : culture de lymphocytes avec un <b>AGENT PONTANT</b> — <b>DEB (diepoxybutane)</b> ou <b>MMC (mitomycine C)</b> → <b>AUGMENTATION MARQUÉE des CASSURES et des FIGURES RADIAIRES (quadriradials)</b> ⭐<br>• <b>Clinique</b> : petite taille, <b>taches café-au-lait</b>, anomalies du <b>pouce/radius</b> (aplasie, pouces triphalangés), microcéphalie, anomalies rénales, hypogonadisme, ⚠️ <b>APLASIE MÉDULLAIRE progressive vers 7–8 ans</b> (pancytopénie)<br>• <b>Risque tumoral</b> : <b>LAM</b> et <b>SMD (syndrome myélodysplasique)</b> — risque cumulé ~<b>40 % à 40 ans</b> · ⚠️ <b>CARCINOMES ÉPIDERMOÏDES des voies aéro-digestives supérieures (bouche, pharynx, œsophage) et ano-génitaux</b> — risque <b>×500 à ×700</b>, âge moyen <b>25–30 ans</b> ⭐ · tumeurs cérébrales, hépatoblastome, Wilms<br>• ⚠️ <b>HYPERSENSIBILITÉ à la RADIOTHÉRAPIE et à la CHIMIOTHÉRAPIE</b> (cisplatine, agents pontants) → doses réduites obligatoires<br>• <b>Traitement</b> : androgènes (oxymétholone) · <b>GREFFE DE MOELLE</b> (régime de conditionnement allégé !) · thérapie génique en essai<br><br><b>2. ATAXIE-TÉLANGIECTASIE (syndrome de Louis-Bar)</b><br>• <b>Gène</b> : <b>ATM (11q22.3)</b><br>• <b>Hérédité</b> : <b>AR</b><br>• <b>Mécanisme</b> : <b>ATM = kinase maîtresse de la réponse aux CASSURES DOUBLE BRIN</b>. Elle phosphoryle <b>p53, CHK2, BRCA1, H2AX (γ-H2AX), NBS1, MDC1, SMC1</b> → arrêt du cycle en <b>G1/S et G2/M</b> + activation de la réparation. Sans ATM → pas d'arrêt du cycle → les cellules se divisent avec un ADN cassé<br>• <b>Clinique</b> : <b>ataxie cérébelleuse progressive dès la marche</b> · <b>télangiectasies oculaires (conjonctivales) vers 3–6 ans</b> et cutanées · ⚠️ <b>IMMUNODÉFICIENCE (IgA, IgG2, IgE basses)</b> → infections sinopulmonaires · sensibilité extrême aux <b>radiations ionisantes</b> · ⚠️ <b>AFP ÉLEVÉE</b> (biomarqueur) · vieillissement prématuré<br>• <b>Test</b> : dosage ATM, phosphorylation de H2AX, ⚠️ <b>caryotype avec translocations récurrentes impliquant les LOCUS des RÉCEPTEURS IMMUNITAIRES — t(7;14)(p14;q11) (TCR), t(8;14) (MYC-IGH), t(14;14)</b> → c'est la signature de l'<b>instabilité aux loci V(D)J</b> ⭐<br>• <b>Risque tumoral</b> : <b>LYMPHOMES</b> et <b>LEUCÉMIES</b> (T-ALL, lymphome B) — <b>risque ×100</b> chez l'enfant · après 20 ans : cancers solides (sein, estomac)<br>• ⚠️ <b>Les hétérozygotes ATM (1 % de la population)</b> ont un <b>risque de cancer du SEIN ×2</b> ⭐<br><br><b>3. SYNDROME DE NIJMEGEN (NBS)</b><br>• <b>Gène</b> : <b>NBN/NBS1 (8q21)</b>, protéine <b>nibrine</b><br>• <b>Hérédité</b> : <b>AR</b><br>• <b>Mécanisme</b> : NBN fait partie du <b>COMPLEXE MRN (MRE11-RAD50-NBN)</b> qui <b>DÉTECTE les cassures double brin</b> et <b>RECRUTE ATM</b>. Sans nibrine → pas d'activation d'ATM → même voie que l'ataxie-télangiectasie<br>• <b>Clinique</b> : <b>MICROCÉPHALIE CONGÉNITALE sévère</b> (tête d'oiseau), faciès particulier, retard de croissance, ⚠️ <b>IMMUNODÉFICIENCE (IgA/IgG basses)</b>, taches café-au-lait. ⚠️ <b>Pas d'ataxie ni de télangiectasies</b> (contrairement à AT)<br>• <b>Risque tumoral</b> : <b>LYMPHOMES non hodgkiniens (B) dès l'enfance</b> — risque très élevé<br>• <b>Fréquent chez les populations slaves</b> (effet fondateur, mutation 657del5)<br>• ⚠️ <b>Contre-indication aux radiations ionisantes</b><br><br><b>4. SYNDROME DE BLOOM</b><br>• <b>Gène</b> : <b>BLM/RECQL3 (15q26.1)</b> — une <b>ADN HÉLICASE de la famille RecQ</b><br>• <b>Hérédité</b> : <b>AR</b><br>• <b>Mécanisme</b> : BLM résout les <b>structures d'ADN anormales</b> (jonctions de Holliday, fourches de réplication bloquées, G-quadruplexes) et <b>SUPPRIME la recombinaison homologue illégitime</b>. Sans BLM → <b>ÉCHANGES SŒURS-CHROMATIDES EXCESSIFS (SCE)</b><br>• <b>Test diagnostique ⚠️ SPÉCIFIQUE</b> : <b>TEST DES ÉCHANGES SŒURS-CHROMATIDES (SCE test)</b> — culture avec <b>BrdU</b> pendant 2 cycles + coloration Hoechst/Giemsa → <b>⚠️ SCE TRÈS AUGMENTÉS : &gt; 50 par cellule (norme : ~5 à 10)</b> — soit environ ×10. On voit les chromosomes en « <b>harlequin</b> » ⭐<br>• <b>Clinique</b> : <b>RETARD DE CROISSANCE SÉVÈRE pré- et postnatal</b> (petite taille harmonieuse) · ⚠️ <b>ÉRYTHÈME FACIAL EN « AILES DE PAPILLON »</b> photo-induit (joues, nez) après exposition solaire · microcéphalie, faciès étroit et long, voix aiguë · <b>hypogonadisme</b> (stérilité masculine, ménopause précoce) · ⚠️ <b>DÉFICIT IMMUNITAIRE (IgA/IgM basses)</b> → infections respiratoires · <b>DIABÈTE insulino-résistant</b>, BPCO<br>• <b>Risque tumoral</b> : ⭐ <b>LE PLUS ÉLEVÉ DE TOUS LES SYNDROMES</b> — <b>tout type de cancer, à tout âge, dès l'enfance</b> : leucémies, lymphomes, puis <b>carcinomes</b> (sein, côlon, peau, poumon, estomac). <b>Risque cumulé à vie ~50 % ou plus</b>, âge médian de survenue <b>~25 ans</b><br>• <b>Fréquent chez les juifs ashkénazes</b> (mutation BLMAsh, effet fondateur)<br>• ⚠️ <b>Hypersensibilité aux radiations ET à la chimiothérapie</b> (doses à réduire)<br><br><b>5. XERODERMA PIGMENTOSUM (XP)</b><br>• <b>Gènes</b> : <b>XPA, XPB, XPC, XPD, XPE (DDB2), XPF (ERCC4), XPG (ERCC5), XPV (POLH)</b><br>• <b>Hérédité</b> : <b>AR</b> (XPV aussi AR)<br>• <b>Mécanisme</b> : défaut de la <b>RÉPARATION PAR EXCISION DE NUCLÉOTIDES (NER)</b>, la voie qui répare les <b>DIMÈRES DE PYRIMIDINE (thymine)</b> induits par les <b>UV</b>. <b>XPV</b> est différent : défaut de l'<b>ADN polymérase η (éta)</b> de <b>bypass translésionnel</b> (elle traverse les dimères correctement)<br>• <b>Clinique</b> : ⚠️ <b>PHOTOSENSIBILITÉ EXTRÊME</b> — coup de soleil après quelques minutes d'exposition · <b>Lentigines (taches de rousseur) dès 1–2 ans</b> sur les zones exposées · <b>atrophie cutanée, télangiectasies, poïkilodermie</b> · <b>OPACITÉS CORNÉENNES, kératite, symblépharon, cécité</b> · ⚠️ <b>~20–30 % ont une ATTEINTE NEUROLOGIQUE progressive</b> (forme De Sanctis-Cacchione : microcéphalie, retard mental, surdité, ataxie) — surtout <b>XPA et XPD</b><br>• <b>Test diagnostique ⚠️</b> : mesure de la <b>SYNTHÈSE NON PROGRAMMÉE d'ADN (UDS — Unscheduled DNA Synthesis)</b> après irradiation UV sur fibroblastes en culture → <b>UDS EFFONDRÉE</b> dans XP-A à XP-G · pour XPV : test de <b>synthèse POST-réplicative (PPR)</b> · ⚠️ <b>SÉQUENÇAGE</b> pour le typage moléculaire<br>• <b>Risque tumoral</b> : ⭐ <b>CANCERS CUTANÉS (basocellulaire, spinocellulaire, MÉLANOME)</b> à un âge médian de <b>8 à 10 ANS</b> — risque <b>×1 000 à ×2 000</b> · ⚠️ <b>cancers de la LANGUE et du bout de la langue</b> (très fréquents et agressifs chez l'enfant XP) · tumeurs oculaires<br>• <b>Traitement</b> : ⚠️ <b>PROTECTION SOLAIRE ABSOLUE ET À VIE</b> (vêtements, écrans totaux, vitres anti-UV, lampes UV-safe à la maison et à l'école) · surveillance dermatologique et ophtalmologique tous les 3–6 mois · chirurgie précoce · ⚠️ <b>INTERDICTION des radiations ionisantes si possible</b><br><br><b>📊 TABLEAU SYNTHÈSE :</b><br>• <b>Fanconi</b> — gènes FANC — ponts inter-brins — <b>test DEB/MMC</b> — aplasie médullaire — <b>LAM + CE des VADS</b><br>• <b>Ataxie-télangiectasie</b> — ATM — cassures double brin — <b>t(7;14)</b>, AFP↑ — ataxie + télangiectasies + immunodéficience — <b>lymphomes/leucémies</b><br>• <b>Nijmegen</b> — NBN — complexe MRN — microcéphalie + immunodéficience — <b>lymphomes B</b><br>• <b>Bloom</b> — BLM (RecQ hélicase) — <b>test SCE</b> — petite taille + érythème en papillon — <b>TOUS les cancers</b><br>• <b>Xeroderma</b> — XPA-G, POLH — NER / dimères UV — <b>test UDS</b> — photosensibilité + lentigines — <b>cancers cutanés dès 8 ans</b><br><br><b>🔑 POINT COMMUN :</b> tous sont des <b>défauts de réparation de l'ADN</b> → <b>accumulation de mutations</b> → <b>instabilité génomique</b> → <b>cancer précoce</b> + <b>vieillissement prématuré</b>. ⚠️ Tous sont <b>CONTRE-INDICATION relative aux radiations ionisantes</b> (sauf XP qui craint surtout les UV).<br><br><b>📋 AUTRES SYNDROMES D'INSTABILITÉ (bonus) :</b><br>• <b>SYNDROME DE WERNER</b> — <b>WRN/RECQL2</b> — progeria de l'adulte — sarcomes<br>• <b>SYNDROME DE ROTHMUND-THOMSON</b> — <b>RECQL4</b> — poïkilodermie congénitale — ostéosarcome<br>• <b>SYNDROME DE LIG4</b>, <b>SYNDROME DE CERNUNNOS/XLF</b> — NHEJ — immunodéficience + radiosensibilité<br>• <b>SYNDROME D'ICF</b> — <b>DNMT3B</b> — instabilité des régions centromériques 1, 9, 16 — immunodéficience + anomalies faciales<br>• <b>SYNDROME DE SECKEL</b>, <b>MOPD II</b> — microcéphalie primordiale<br>• <b>ATAXIE-APRAXIE AOA1/AOA2</b> — APRX/SETX<br>• <b>CANCER COLORECTAL HÉRÉDITAIRE SANS POLYPOSE (HNPCC/LYNCH)</b> — <b>MMR (MLH1, MSH2, MSH6, PMS2)</b> — <b>instabilité des microsatellites (MSI)</b> — forme <b>AD</b> ⚠️ (pas AR)","t":"genetique-2026 EXAM-2026"},{"q":"Q35 — L'hérédité <b>DOMINANTE LIÉE À L'X (X-linked dominant)</b> : quelles sont ses caractéristiques ?","a":"<b>📋 HÉRÉDITÉ DOMINANTE LIÉE À L'X — LES 7 RÈGLES À APPRENDRE :</b><br><br><b>1. PAS DE TRANSMISSION PÈRE → FILS</b> ⚠️ <b>LA RÈGLE D'OR</b><br>• Un père atteint transmet son <b>Y à tous ses fils</b> → <b>TOUS ses fils sont SAINS</b> (0 % atteints)<br>• ⚠️ Si tu vois <b>père atteint → fils atteint</b> sur un arbre généalogique, <b>ce N'EST PAS lié à l'X</b> (c'est autosomique ou holandrique)<br><br><b>2. TOUTES LES FILLES D'UN PÈRE ATTEINT SONT ATTEINTES</b> ⚠️<br>• Le père transmet son <b>X muté à 100 % de ses filles</b><br>• → <b>Risque = 100 %</b> pour les filles<br>• C'est le <b>critère le plus caractéristique</b> sur un arbre généalogique<br><br><b>3. UNE MÈRE ATTEINTE (hétérozygote) TRANSMET À 50 % DE TOUS SES ENFANTS</b><br>• <b>50 % des fils atteints</b> (ils reçoivent l'X muté)<br>• <b>50 % des filles atteintes</b> (hétérozygotes)<br>• ⚠️ Contrairement au récessif lié à l'X, <b>LES FILLES SONT AUSSI ATTEINTES</b> (car le gène est DOMINANT — une seule copie suffit)<br><br><b>4. LES FEMMES SONT PLUS SOUVENT ATTEINTES QUE LES HOMMES</b> ⚠️<br>• Rapport ≈ <b>2 : 1</b> (femmes : hommes)<br>• Raison : une femme peut être atteinte en héritant de <b>L'UN OU L'AUTRE parent</b> ; un homme seulement de <b>sa mère</b><br><br><b>5. LES HOMMES SONT PLUS GRAVEMENT ATTEINTS</b> ⚠️<br>• L'homme est <b>HÉMIZYGOTE</b> (un seul X) → <b>aucune copie normale compensatrice</b> → expression complète<br>• Beaucoup de maladies XD sont <b>LÉTALES IN UTERO chez le garçon</b> → on observe alors un <b>EXCÈS DE FILLES</b> et des <b>FAUSSES COUCHES à répétition de garçons</b> ⚠️<br><br><b>6. LES FEMMES HÉTÉROZYGOTES ONT UNE EXPRESSIVITÉ VARIABLE</b> ⚠️<br>• Cause : l'<b>INACTIVATION ALÉATOIRE DU X (LYONISATION)</b><br>• Au début du développement embryonnaire (~<b>jour 12–16</b>, stade blastocyste), chaque cellule inactive <b>au hasard</b> soit l'X paternel, soit l'X maternel → cet état est <b>CLONÉ</b> dans toute la descendance de la cellule<br>• Résultat : une femme hétérozygote est une <b>MOSAÏQUE FONCTIONNELLE</b> de 2 populations cellulaires<br>• Si le hasard donne une proportion élevée de cellules où l'X <b>normal</b> est inactivé → phénotype <b>SÉVÈRE</b><br>• Si l'X <b>muté</b> est préférentiellement inactivé (<b>inactivation biaisée/skewed</b>) → phénotype <b>LÉGER ou absent</b><br>• ⚠️ C'est pourquoi on voit des <b>femmes « conductrices » atteintes</b> et des formes <b>en mosaïque cutanée</b> (stries de Blaschko)<br><br><b>7. PAS DE PORTEURS SAINS</b><br>• Dominant = <b>tout porteur de l'allèle muté est atteint</b> (à des degrés variables)<br>• ⚠️ Différence majeure avec le récessif lié à l'X où les femmes conductrices sont saines<br><br><b>📋 EXEMPLES DE MALADIES XD :</b><br>• <b>RACHITISITE/HYPOPHOSPHATÉMIE VITAMINO-RÉSISTANTE (rachitisme hypophosphatémique lié à l'X)</b> — gène <b>PHEX (Xp22.1)</b> — le plus fréquent. Hypophosphatémie, rachitisme résistant à la vitamine D, jambes arquées, petite taille. Traitement : <b>burosumab</b> (anti-FGF23) ⭐<br>• <b>SYNDROME DE RETT</b> — <b>MECP2 (Xq28)</b> — ⚠️ atteint quasi exclusivement les filles (létal chez le garçon) ; développement normal puis <b>régression après 6–18 mois</b>, perte du langage et des acquisitions manuelles, <b>stéréotypies des mains (lavage/torsion)</b>, microcéphalie acquise, épilepsie<br>• <b>INCONTINENTIA PIGMENTI (syndrome de Bloch-Sulzberger)</b> — <b>IKBKG/NEMO</b> — létal chez le garçon ; <b>4 stades cutanés</b> (vésiculeux → verruqueux → hyperpigmenté en stries de Blaschko → atrophique/hypopigmenté) ; anomalies dentaires (dents coniques, hypodontie) ⚠️ <b>PERTINENT EN DENTAIRE</b><br>• <b>SYNDROME D'ALPORT lié à l'X (forme dominante)</b> — <b>COL4A5</b> — néphropathie + surdité + anomalies oculaires<br>• <b>SCLÉROSE TUBÉREUSE DE BOURNEVILLE</b> (certains cas) — <b>TSC1/TSC2</b> (plutôt AD)<br>• <b>SYNDROME AICARDI</b> — agénésie du corps calleux, spasmes infantiles, chorio-rétinite lacunaire — létal chez le garçon<br>• <b>DYSPLASIE ECTODERMIQUE HYPOHIDROTIQUE</b> — <b>EDA</b> (forme XL, dominante chez certaines femmes) — ⚠️ <b>PERTINENT EN DENTAIRE</b> : hypodontie/anodontie, dents coniques, cheveux fins, absence de transpiration<br><br><b>📊 COMPARAISON AVEC LES AUTRES MODES :</b><br>• <b>Récessif lié à l'X</b> : hommes atteints, femmes conductrices saines, <b>pas de transmission père→fils</b>, transmission par la mère (oncle maternel atteint) — ex. <b>hémophilie A/B, DMD, Daltonisme, G6PD, X fragile</b><br>• <b>Autosomique dominant</b> : hommes et femmes atteints à parts égales, <b>transmission père→fils POSSIBLE</b>, 50 % à chaque génération, atteinte dans toutes les générations<br>• <b>Holandrique</b> : uniquement les hommes, <b>père→TOUS les fils</b>, jamais de femme<br>• ⚠️ <b>Le critère décisif pour distinguer XD de AD</b> : en <b>XD, un père atteint n'a AUCUN fils atteint et TOUTES ses filles sont atteintes</b>. En AD, un père atteint transmet à 50 % des fils et 50 % des filles.","t":"genetique-2026 EXAM-2026"},{"q":"Q36 &amp; Q37 — Un individu <b>HOMOZYGOTE</b> pour une maladie autosomique dominante, et un <b>HÉTÉROZYGOTE COMPOSITE</b> : quelles différences ?","a":"<b>📋 HOMOZYGOTE POUR UNE MALADIE AUTOSOMIQUE DOMINANTE :</b><br><br><b>DÉFINITION :</b> individu qui possède <b>DEUX COPIES de l'allèle MUTÉ DOMINANT</b> (<b>A/A</b> au lieu de <b>A/a</b>).<br><br><b>COMMENT ÇA ARRIVE ?</b> ⚠️ Rare — il faut que <b>LES DEUX PARENTS SOIENT ATTEINTS</b> (tous deux hétérozygotes <b>A/a</b>) :<br>• Croisement <b>A/a × A/a</b> → <b>1/4 A/A (homozygote)</b> · <b>2/4 A/a (hétérozygotes)</b> · <b>1/4 a/a (sain)</b><br>• ⚠️ Donc chez les enfants d'un couple où les deux parents sont atteints d'une maladie AD, le ratio phénotypique attendu est de <b>3 atteints : 1 sain</b> (et non 1:2:1) — car <b>A/A ET A/a SONT TOUS DEUX ATTEINTS</b><br>• Plus fréquent en cas de <b>CONSANGUINITÉ</b> ou dans les <b>populations à effet fondateur</b><br><br><b>CONSÉQUENCES PHÉNOTYPIQUES :</b><br>• ⚠️ <b>FORME BEAUCOUP PLUS SÉVÈRE</b> que l'hétérozygote — souvent <b>LÉTALE</b> (in utero ou dans l'enfance)<br>• <b>Effet de dose génique</b> : 2 copies mutées → quantité anormale de protéine double<br>• <b>Exemples classiques :</b><br>&nbsp;&nbsp;– <b>ACHONDROPLASIE</b> (<b>FGFR3</b>, mutation G380R) : ⭐ <b>L'HOMOZYGOTE EST LÉTAL</b> (nanisme thanatophore-like, cage thoracique étroite → insuffisance respiratoire néonatale). Les hétérozygotes sont atteints de nanisme. <b>Risque = 25 %</b> pour un couple de deux achondroplasiques → ⚠️ <b>conseil génétique OBLIGATOIRE</b> avec diagnostic prénatal<br>&nbsp;&nbsp;– <b>HYPERCHOLESTÉROLÉMIE FAMILIALE</b> (<b>LDLR</b>) : hétérozygote = cholestérol ~3–4 g/L, infarctus vers 40–50 ans ; <b>homozygote = cholestérol &gt; 6–10 g/L, xanthomes dès l'enfance, infarctus AVANT 20 ANS</b><br>&nbsp;&nbsp;– <b>SPHÉROCYTOSE HÉRÉDITAIRE</b>, <b>maladie de Huntington</b> (homozygotes rares, phénotype similaire ou légèrement plus sévère)<br>&nbsp;&nbsp;– <b>NÉCROLYSE ÉPIDERMIQUE</b>, <b>porphyrie</b><br>&nbsp;&nbsp;– ⚠️ <b>MALADIES « PSEUDO-DOMINANTES »</b> : certaines maladies AR deviennent « dominantes » quand l'homozygote et l'hétérozygote sont tous deux atteints (ex. <b>hémochromatose HFE</b>)<br><br><b>📋 HÉTÉROZYGOTE COMPOSITE (compound heterozygote) :</b><br><br><b>DÉFINITION :</b> individu qui possède <b>DEUX ALLÈLES MUTÉS DIFFÉRENTS</b> au <b>MÊME LOCUS</b>, <b>UN SUR CHAQUE CHROMOSOME HOMOLOGUE</b>.<br>• Notation : le locus est <b>a/a</b> en apparence, mais les deux « a » sont en réalité <b>deux mutations DISTINCTES</b> (ex. <b>F508del / G542X</b>)<br>• ⚠️ Ce n'est <b>PAS un homozygote</b> : l'homozygote a la <b>MÊME mutation sur les deux allèles</b><br><br><b>CONTEXTE :</b> ⚠️ C'est le mode habituel des <b>MALADIES AUTOSOMIQUES RÉCESSIVES</b> quand les parents ne sont pas apparentés.<br>• Chaque parent est <b>porteur (hétérozygote) d'une mutation DIFFÉRENTE</b> du même gène<br>• L'enfant hérite de la <b>mutation 1 du père</b> et de la <b>mutation 2 de la mère</b> → <b>HÉTÉROZYGOTE COMPOSITE</b> → <b>ATTEINT</b> (car aucune copie normale)<br>• Exemple : <b>MUCOVISCIDOSE (CFTR)</b> — &gt; <b>2 000 mutations</b> décrites. La plus fréquente : <b>F508del (~70 % des allèles en Europe)</b>. <b>La plupart des patients sont hétérozygotes composites</b> (ex. F508del/G542X, F508del/N1303K)<br>• Autres exemples : <b>phénylcétonurie (PAH)</b>, <b>drépanocytose/HbS-HbC (hétérozygote composé SC)</b>, <b>bêta-thalassémie</b>, <b>maladie de Tay-Sachs</b>, <b>atrophie musculaire spinale</b>, <b>maladie de Gaucher</b>, <b>surdi-mutité GJB2 (35delG/167delT)</b><br><br><b>⚠️ CONSÉQUENCE DIAGNOSTIQUE MAJEURE :</b><br>• Un test qui cherche <b>UNE SEULE mutation</b> (ex. PCR spécifique F508del) peut être <b>FAUSSEMENT NÉGATIF</b> chez un hétérozygote composite → il faut <b>SÉQUENCER tout le gène</b><br>• ⚠️ Le <b>conseil génétique</b> est plus complexe : il faut identifier les <b>2 mutations</b> et les tester chez les apparentés<br><br><b>⚠️ CONSÉQUENCE THÉRAPEUTIQUE (modificateurs CFTR) :</b><br>• Le traitement dépend du <b>GÉNOTYPE exact</b> : <b>ivacaftor</b> (potentiateur) pour les mutations de classe III (G551D) · <b>lumacaftor/ivacaftor, tézacaftor/ivacaftor</b> pour F508del homozygote · ⭐ <b>élexacaftor/tézacaftor/ivacaftor (Trikafta/Kaftrio)</b> pour au moins une copie F508del<br><br><b>📊 TABLEAU COMPARATIF :</b><br>• <b>HOMOZYGOTE</b> : <b>2 copies de la MÊME mutation</b> · parents souvent <b>consanguins</b> ou atteints de la même maladie · souvent <b>plus sévère/létal</b> en AD · en AR = forme classique<br>• <b>HÉTÉROZYGOTE COMPOSITE</b> : <b>2 mutations DIFFÉRENTES du même gène</b>, une sur chaque homologue · parents <b>non apparentés</b>, chacun porteur d'une mutation distincte · mode habituel des <b>maladies AR</b> · sévérité <b>variable selon les 2 mutations</b> (la plus « douce » peut atténuer)<br>• <b>HÉTÉROZYGOTE SIMPLE</b> : <b>1 seule copie mutée</b> → <b>porteur sain</b> en AR, <b>atteint</b> en AD<br><br><b>🔑 PIÈGES À RETENIR :</b><br>• ⚠️ <b>« Homozygote » ≠ « hétérozygote composite »</b> — mais les deux donnent une <b>maladie RÉCESSIVE</b> car il n'y a <b>AUCUNE copie normale</b><br>• ⚠️ En cas de <b>DISOMIE UNIPARENTALE (DUP)</b>, un enfant peut être <b>homozygote pour une mutation récessive</b> alors qu'<b>UN SEUL parent est porteur</b> → piège du conseil génétique (ex. DUP maternelle 15 → Prader-Willi ; DUP11p15 → Beckwith-Wiedemann)<br>• ⚠️ L'<b>hémizygote</b> (homme pour les gènes liés à l'X) n'a qu'<b>UNE SEULE copie</b> — il n'est ni homozygote ni hétérozygote","t":"genetique-2026 EXAM-2026"},{"q":"Q38 — L'hérédité <b>HOLANDRIQUE</b> (liée au chromosome Y) : quelles sont ses caractéristiques ?","a":"<b>📋 HÉRÉDITÉ HOLANDRIQUE = hérédité liée au CHROMOSOME Y</b><br>(du grec <b>holos</b> = entier, <b>andros</b> = homme → « entièrement masculine »)<br><br><b>LES 5 CARACTÉRISTIQUES :</b><br><br><b>1. ⚠️ N'ATTEINT QUE LES HOMMES — JAMAIS LES FEMMES</b><br>• Les femmes sont <b>46,XX</b> → elles <b>N'ONT PAS DE CHROMOSOME Y</b> → elles ne peuvent <b>NI être atteintes, NI être conductrices</b><br>• Il n'y a <b>PAS de porteuses saines</b><br><br><b>2. ⚠️ TRANSMISSION PÈRE → TOUS LES FILS (100 %)</b><br>• Un père atteint donne son <b>Y à 100 % de ses fils</b> → <b>TOUS ses fils sont atteints</b><br>• C'est le <b>critère le plus caractéristique</b> sur un arbre généalogique<br>• ⚠️ <b>Aucun saut de génération</b> : la maladie est présente chez <b>tous les mâles de toutes les générations</b><br>• ⚠️ <b>Différence avec l'AD</b> : en AD, seuls <b>50 %</b> des fils sont atteints<br>• ⚠️ <b>Différence avec l'XD</b> : en XD, <b>0 %</b> des fils sont atteints (le père donne Y aux fils)<br><br><b>3. JAMAIS DE TRANSMISSION PAR LA MÈRE</b><br>• La mère ne peut pas transmettre un Y<br>• Toutes les <b>filles</b> d'un homme atteint sont <b>SAINES et NON CONDUCTRICES</b><br><br><b>4. PSEUDO-AUTOSOMIQUE ? NON ⚠️</b><br>• Le chromosome Y contient une <b>région PSEUDO-AUTOSOMIQUE (PAR1 et PAR2)</b> qui <b>recombine avec l'X</b> → les gènes de cette région (ex. <b>SHOX</b>) ont une hérédité <b>PSEUDO-AUTOSOMALE</b>, pas holandrique<br>• Les gènes <b>HOLANDRIQUES</b> sont dans la <b>région SPÉCIFIQUE DU Y (MSY, male-specific region of Y)</b>, qui <b>NE RECOMBINE PAS</b> → <b>héritage strictement clonal, patrilinéaire</b><br>• ⚠️ C'est pourquoi le <b>Y est utilisé en généalogie génétique et en médecine légale</b> pour tracer les <b>LIGNÉES PATERNELLES</b> (haplogroupes)<br><br><b>5. LE CHROMOSOME Y CONTIENT PEU DE GÈNES</b><br>• ~<b>57 Mb</b>, ~<b>70–200 gènes</b> (le plus pauvre en gènes du génome après le 21)<br>• <b>Régions</b> : bras court (Yp) avec <b>PAR1</b> et le gène <b>SRY</b> · centromère · bras long (Yq) avec <b>hétérochromatine Yq12</b> (très variable, polymorphisme bénin) et <b>PAR2</b> · région <b>AZF (AZFa, AZFb, AZFc)</b> en Yq11<br><br><b>📋 LES GÈNES / MALADIES HOLANDRIQUES :</b><br><br>• ⭐ <b>INFERTILITÉ MASCULINE PAR MICRODÉLÉTIONS DE LA RÉGION AZF (Yq11)</b> — <b>LE SEUL EXEMPLE CLINIQUE VRAIMENT IMPORTANT</b><br>&nbsp;&nbsp;– <b>AZF</b> = <b>AZoospermia Factor</b>, en <b>Yq11</b>, subdivisé en <b>AZFa, AZFb, AZFc</b><br>&nbsp;&nbsp;– <b>AZFa</b> : gènes <b>USP9Y, DBY (DDX3Y)</b> → délétion = <b>SYNDROME SERTOLIEN UNIQUE (SCO)</b>, azoospermie complète, ⚠️ <b>AUCUN spermatozoïde récupérable → ICSI IMPOSSIBLE</b><br>&nbsp;&nbsp;– <b>AZFb</b> : gènes <b>RBMY, PRY</b> → délétion = <b>ARRÊT DE MATURATION (maturation arrest)</b>, azoospermie, ⚠️ <b>ICSI IMPOSSIBLE</b><br>&nbsp;&nbsp;– <b>AZFc</b> : gène <b>DAZ</b> (Deleted in AZoospermia, 4 copies) → <b>la délétion la plus FRÉQUENTE (~60 % des microdélétions AZF)</b> → <b>azoospermie ou oligospermie sévère</b>. ⚠️ <b>ICSI POSSIBLE</b> (spermatozoïdes trouvés dans ~50 % des cas par TESE)<br>&nbsp;&nbsp;– <b>Fréquence</b> : <b>~10–15 % des azoospermies</b> et <b>~5–10 % des oligospermies sévères</b> (&lt; 5 millions/mL)<br>&nbsp;&nbsp;– ⚠️ <b>TRANSMISSION</b> : si une ICSI réussit, <b>TOUS LES FILS hériteront de la délétion → seront infertiles</b>. Toutes les <b>FILLES sont indemnes</b>. → <b>CONSEIL GÉNÉTIQUE OBLIGATOIRE</b> avant ICSI<br>&nbsp;&nbsp;– <b>Diagnostic</b> : <b>caryotype</b> (élimine Klinefelter) + <b>PCR multiplex avec des STS (Sequence-Tagged Sites)</b> sur AZFa/b/c. ⚠️ <b>Invisible au caryotype standard</b> (microdélétion)<br>&nbsp;&nbsp;– <b>Recommandations EAA/ESHRE</b> : rechercher la microdélétion Y + caryotype chez tout homme avec <b>azoospermie non obstructive ou oligospermie &lt; 5 M/mL</b><br><br>• ⭐ <b>SRY — « SEX-DETERMINING REGION Y »</b><br>&nbsp;&nbsp;– Localisation : <b>Yp11.3</b>, près de PAR1<br>&nbsp;&nbsp;– Facteur de transcription <b>HMG-box</b> → <b>DÉTERMINE le SEXE MÂLE</b> en induisant la différenciation des <b>cellules de Sertoli</b> à partir de la gonade bipotente (6ᵉ semaine)<br>&nbsp;&nbsp;– Il active <b>SOX9</b> → production d'<b>AMH (hormone anti-müllérienne)</b> → régression des canaux de Müller ; les cellules de Leydig produisent la <b>testostérone</b> → canaux de Wolff + masculinisation<br>&nbsp;&nbsp;– ⚠️ <b>MUTATION PERTE DE FONCTION de SRY</b> → <b>46,XY avec DÉVELOPPEMENT FÉMININ (DSD 46,XY / dysgenèse gonadique pure)</b><br>&nbsp;&nbsp;– ⚠️ <b>TRANSLOCATION DE SRY SUR L'X</b> (par recombinaison anormale X-Y chez le père) → <b>46,XX MÂLE (syndrome de de la Chapelle)</b> — homme de petite taille, testicules petits, azoospermie, gynécomastie<br>&nbsp;&nbsp;– ⚠️ <b>DUPLICATION de SRY chez un 46,XX</b> → masculinisation<br><br>• <b>GONADOBLASTOME — locus GBY (Gonadoblastoma on Y)</b> ⚠️<br>&nbsp;&nbsp;– Chez les individus avec <b>DSD et un Y présent mais une gonade dysgénésique</b> (ex. 46,XY pur, dysgenèse gonadique mixte, syndrome de Turner avec mosaïque Y) → risque élevé de <b>GONADOBLASTOME</b> puis de <b>DYSGERMINOME</b><br>&nbsp;&nbsp;– ⚠️ <b>INDICATION DE GONADECTOMIE PROPHYLACTIQUE</b><br><br>• <b>H-Y ANTIGÈNE / TSPY</b> (testis-specific protein Y-encoded) — impliqué dans la spermatogenèse, amplifié dans certains gonadoblastomes<br><br>• <b>HYPERTRICHOSE DE L'OREILLE (hairy ears / trichose des pavillons)</b> ⚠️<br>&nbsp;&nbsp;– L'<b>exemple historique « classique »</b> des manuels : poils sur le bord du pavillon de l'oreille, transmis père → tous les fils<br>&nbsp;&nbsp;– ⚠️ <b>En réalité, ce caractère n'est PAS strictement holandrique</b> (il y a des influences autosomales et hormonales) — mais il reste l'exemple pédagogique traditionnel<br><br>• <b>SYNDACTYLIE des 2ᵉ-3ᵉ orteils, ichtyose liée à l'Y, webbed toes</b> — descriptions anciennes, mal confirmées<br><br><b>📊 TABLEAU DES 5 MODES D'HÉRÉDITÉ :</b><br>• <b>AUTOSOMIQUE DOMINANT</b> : H=F · père→fils OUI · toutes les générations · 50 % · ex. Huntington, Marfan, achondroplasie, NF1<br>• <b>AUTOSOMIQUE RÉCESSIF</b> : H=F · saute des générations · 25 % · consanguinité · porteurs sains · ex. mucoviscidose, drépanocytose, PKU<br>• <b>RÉCESSIF LIÉ À L'X</b> : H &gt;&gt; F · père→fils NON · transmission par la mère · conductrices saines · ex. hémophilie, DMD, Daltonisme, G6PD, X fragile<br>• <b>DOMINANT LIÉ À L'X</b> : F &gt; H · père→fils NON · toutes les filles d'un père atteint sont atteintes · ex. rachitisme hypophosphatémique, Rett, incontinentia pigmenti<br>• <b>HOLANDRIQUE (lié au Y)</b> : ⚠️ <b>100 % HOMMES</b> · <b>père→TOUS les fils</b> · jamais de femme · ex. microdélétions AZF, SRY","t":"genetique-2026 EXAM-2026"},{"q":"Q39 — Un couple de <b>porteurs sains</b> d'une maladie <b>autosomique récessive</b> : quels sont les risques pour chaque grossesse ?","a":"<b>📋 RISQUES D'UN COUPLE D'HÉTÉROZYGOTES (A/a × A/a) POUR UNE MALADIE AR :</b><br><br>À <b>CHAQUE GROSSESSE</b> (⚠️ indépendamment des grossesses précédentes) :<br><br>• <b>25 % (1/4) — ENFANT ATTEINT (a/a)</b> homozygote muté<br>• <b>50 % (2/4) — ENFANT PORTEUR SAIN (A/a)</b> hétérozygote<br>• <b>25 % (1/4) — ENFANT SAIN NON PORTEUR (A/A)</b><br><br>⚠️ <b>DEUX PIÈGES FONDAMENTAUX :</b><br><br><b>PIÈGE 1 — Le risque de 25 % s'applique À CHAQUE GROSSESSE, indépendamment</b> ⚠️<br>• Ce n'est <b>PAS</b> « sur 4 enfants, 1 sera atteint »<br>• Avoir déjà un enfant atteint <b>NE DIMINUE PAS</b> le risque pour le suivant : il reste <b>25 %</b><br>• Avoir déjà 3 enfants sains <b>NE DIMINUE PAS</b> le risque pour le 4ᵉ : il reste <b>25 %</b><br>• ⚠️ Probabilité d'avoir <b>n enfants non atteints d'affilée</b> = <b>(3/4)ⁿ</b><br>&nbsp;&nbsp;– 2 enfants sains d'affilée : (3/4)² = <b>56,25 %</b><br>&nbsp;&nbsp;– 3 enfants sains d'affilée : (3/4)³ = <b>42,2 %</b><br>&nbsp;&nbsp;– 4 enfants sains d'affilée : (3/4)⁴ = <b>31,6 %</b><br><br><b>PIÈGE 2 — Les probabilités conditionnelles ⚠️ TRÈS FRÉQUENT À L'EXAMEN</b><br>• « <b>Quel est le risque que leur enfant, s'il est SAIN, soit PORTEUR ?</b> »<br>&nbsp;&nbsp;→ On <b>EXCLUT</b> l'enfant atteint (a/a). Il reste <b>3 génotypes possibles équiprobables</b> : A/A, A/a, A/a<br>&nbsp;&nbsp;→ Réponse : <b>2/3 (66,7 %)</b> ⚠️ <b>PAS 1/2</b><br>• « <b>Quel est le risque que leur FILLE soit conductrice ?</b> » (AR, non lié à l'X)<br>&nbsp;&nbsp;→ <b>50 %</b> (le sexe ne change rien en autosomique) × ... non : la probabilité que cette fille soit A/a = <b>50 %</b> parmi toutes les naissances ; <b>2/3</b> parmi les filles saines<br>• « <b>Quel est le risque d'avoir 2 enfants atteints ?</b> »<br>&nbsp;&nbsp;→ <b>(1/4) × (1/4) = 1/16 = 6,25 %</b><br>• « <b>Quel est le risque d'avoir au moins 1 enfant atteint sur 3 ?</b> »<br>&nbsp;&nbsp;→ <b>1 − (3/4)³ = 1 − 0,4219 = 57,8 %</b><br>• « <b>Quel est le risque qu'un enfant soit atteint ET que ce soit un garçon ?</b> »<br>&nbsp;&nbsp;→ <b>1/4 × 1/2 = 1/8 = 12,5 %</b><br><br><b>📋 AUTRES SITUATIONS DE COUPLES :</b><br>• <b>Atteint (a/a) × Porteur (A/a)</b> → <b>50 % atteints</b>, 50 % porteurs sains<br>• <b>Atteint (a/a) × Sain non porteur (A/A)</b> → <b>100 % porteurs sains</b>, 0 % atteints<br>• <b>Atteint (a/a) × Atteint (a/a)</b> → <b>100 % atteints</b><br>• <b>Porteur (A/a) × Sain non porteur (A/A)</b> → <b>0 % atteints</b>, 50 % porteurs<br><br><b>📋 FRÉQUENCE DES PORTEURS DANS LA POPULATION (LOI DE HARDY-WEINBERG) :</b><br><b>p² + 2pq + q² = 1</b> où <b>p</b> = fréquence de l'allèle normal, <b>q</b> = fréquence de l'allèle muté<br>• <b>q²</b> = fréquence des <b>ATTEINTS</b> (homozygotes)<br>• <b>2pq</b> = fréquence des <b>PORTEURS SAINS</b> (hétérozygotes)<br>• ⚠️ Pour une maladie rare, <b>p ≈ 1</b> → <b>fréquence des porteurs ≈ 2q = 2√(fréquence des atteints)</b><br>• <b>Exemple</b> : maladie au <b>1/10 000</b> → q² = 10⁻⁴ → q = 1/100 → porteurs = <b>2 × 1/100 ≈ 1/50</b> ⭐<br>• <b>Exemple</b> : maladie au <b>1/2 500</b> (mucoviscidose) → q = 1/50 → porteurs ≈ <b>1/25</b> ⭐<br>• <b>Risque pour un couple NON APPARENTÉ</b> = <b>(1/2) × (fréquence des porteurs)²</b> si on connaît le statut d'un seul conjoint (ex. femme porteuse connue × homme inconnu → <b>1/2 × 1/25 = 1/50</b>)<br><br><b>⚠️ CONSANGUINITÉ :</b><br>• La consanguinité <b>AUGMENTE le risque de maladies AR</b> car les conjoints partagent des ancêtres → probabilité élevée d'avoir le <b>MÊME allèle par DESCENDANCE</b><br>• <b>COEFFICIENT DE CONSANGUINITÉ (F)</b> : probabilité que les 2 allèles d'un locus soient <b>IDENTIQUES PAR DESCENDANCE</b><br>&nbsp;&nbsp;– <b>Cousins germains (1er degré de cousinage)</b> : <b>F = 1/16 = 6,25 %</b><br>&nbsp;&nbsp;– <b>Demi-frères/sœurs</b> : <b>F = 1/8 = 12,5 %</b><br>&nbsp;&nbsp;– <b>Oncle-nièce / tante-neveu</b> : <b>F = 1/8</b><br>&nbsp;&nbsp;– <b>Cousins issus de germains (2ᵉ degré)</b> : <b>F = 1/64</b><br>&nbsp;&nbsp;– <b>Frère-sœur / parent-enfant</b> : <b>F = 1/4 = 25 %</b><br>• ⚠️ <b>COEFFICIENT DE PARENTÉ (R)</b> : proportion de gènes partagés — parents/enfants/frères-sœurs = <b>1/2</b> · grands-parents, oncles, demi-frères, neveux = <b>1/4</b> · cousins germains = <b>1/8</b><br>• ⚠️ Le risque global de malformation/maladie génétique chez l'enfant d'un couple de cousins germains passe de <b>~2–3 %</b> (population générale) à <b>~4–6 %</b><br><br><b>📋 EXEMPLES DE MALADIES AR À CONNAÎTRE :</b><br>• <b>MUCOVISCIDOSE</b> — CFTR (7q31) — porteurs 1/25 (Europe) — atteints 1/2 500 — sueur salée (test de la sueur), iléus méconial, insuffisance pancréatique, bronchectasies<br>• <b>DRÉPANOCYTOSE</b> — HBB (11p15), mutation Glu6Val → HbS — porteurs 1/10 en Afrique subsaharienne, 1/50 aux Antilles — ⚠️ avantage contre le paludisme (sélection)<br>• <b>BÊTA-THALASSÉMIE</b> — HBB — Méditerranée, Asie du Sud-Est<br>• <b>PHÉNYLCÉTONURIE (PKU)</b> — PAH (12q23) — dépistage néonatal systématique (test de Guthrie) — régime pauvre en phénylalanine<br>• <b>MALADIE DE TAY-SACHS</b> — HEXA (15q23) — juifs ashkénazes 1/30 porteurs — cherry-red spot, régression, décès à 4 ans<br>• <b>ATROPHIE MUSCULAIRE SPINALE (SMA)</b> — SMN1 (5q13) — 1/40 porteurs — n°1 des causes génétiques de mortalité infantile — nusinersen, onasemnogene abeparvovec (Zolgensma), risdiplam ⭐<br>• <b>MALADIE DE GAUCHER</b> — GBA (1q21) — ashkénazes<br>• <b>HÉMACHROMATOSE HFE C282Y</b> — 6p22 — Bretons/Irlandais — pénétrance incomplète ⚠️<br>• <b>SURDITÉ CONNATALE GJB2 (connexine 26)</b> — 13q12 — 35delG — cause la plus fréquente de surdité génétique AR<br>• <b>ALBINISME OCULOCUTANÉ type 1</b> — TYR (11q14)<br>• <b>XERODERMA PIGMENTOSUM</b> — NER<br>• <b>ANÉMIE DE FANCONI</b>, <b>ATAXIE-TÉLANGIECTASIE</b>, <b>SYNDROME DE BLOOM</b> — instabilité chromosomique","t":"genetique-2026 EXAM-2026"},{"q":"Q40 — Les <b>FEMMES CONDUCTRICES</b> d'une maladie <b>RÉCESSIVE LIÉE À L'X</b> : quelles sont les caractéristiques et les risques ?","a":"<b>📋 FEMME CONDUCTRICE (heterozygote / porteuse) D'UNE MALADIE XL RÉCESSIVE :</b><br><br><b>DÉFINITION :</b> femme <b>X<sup>A</sup>/X<sup>a</sup></b> — porte <b>UN allèle muté récessif</b> sur un de ses deux chromosomes X. Comme l'allèle muté est <b>RÉCESSIF</b>, son X normal (X<sup>A</sup>) suffit normalement → elle est <b>PHÉNOTYPIQUEMENT SAINE</b> dans la majorité des cas.<br><br><b>1. ⚠️ RISQUES POUR SA DESCENDANCE (à chaque grossesse) :</b><br>• <b>25 % — FILS ATTEINT (X<sup>a</sup>/Y)</b> ⭐<br>• <b>25 % — FILLE CONDUCTRICE (X<sup>A</sup>/X<sup>a</sup>)</b><br>• <b>25 % — FILS SAIN (X<sup>A</sup>/Y)</b><br>• <b>25 % — FILLE SAINE NON CONDUCTRICE (X<sup>A</sup>/X<sup>A</sup>)</b><br><br>Exprimé autrement :<br>• <b>Parmi les FILS : 50 % atteints, 50 % sains</b><br>• <b>Parmi les FILLES : 50 % conductrices, 50 % saines</b><br>• ⚠️ <b>RISQUE GLOBAL d'un enfant ATTEINT = 25 %</b> (car seuls les garçons sont atteints, et il y a 50 % de garçons → 0,5 × 0,5 = 0,25)<br><br><b>2. ⚠️ UNE CONDUCTRICE PEUT ÊTRE ATTEINTE (manifestante) ! — PIÈGE MAJEUR</b><br><br>C'est le point le plus important à retenir. Les mécanismes :<br><br>• <b>a) INACTIVATION BIAISÉE / DÉFAVORABLE DU X (skewed X-inactivation)</b> ⭐ LE MÉCANISME LE PLUS FRÉQUENT<br>&nbsp;&nbsp;– L'inactivation du X est <b>aléatoire</b> (lyonisation) au stade blastocyste<br>&nbsp;&nbsp;– Normalement le rapport est ~50:50, mais par hasard il peut être <b>défavorable</b> (ex. 90 % des cellules ont inactivé l'X <b>NORMAL</b>)<br>&nbsp;&nbsp;– → La conductrice devient <b>« hétérozygote manifestante »</b> avec un phénotype <b>atténué ou complet</b><br>&nbsp;&nbsp;– ⚠️ C'est pourquoi <b>~10 % des mères conductrices de myopathie de Duchenne ont une atteinte musculaire</b> et <b>~25 % ont une atteinte cardiaque (cardiomyopathie dilatée)</b> → ⚠️ <b>ECG + échocardiographie OBLIGATOIRES chez toute conductrice de DMD</b><br><br>• <b>b) ANOMALIE CHROMOSOMIQUE — MONOSOMIE X (45,X)</b><br>&nbsp;&nbsp;– Une femme <b>45,X</b> porteuse d'un X muté n'a <b>aucun X normal</b> → elle est <b>ATTEINTE comme un homme</b> (hémizygote fonctionnelle)<br>&nbsp;&nbsp;– Ex. : <b>femme Turner hémophile</b> ou atteinte de <b>DMD</b> — très rare mais décrit<br><br>• <b>c) TRANSLOCATION X-AUTOSOME ÉQUILIBRÉE</b> ⚠️<br>&nbsp;&nbsp;– Si la cassure tombe sur un gène du X → la femme est <b>hémizygote fonctionnelle</b> pour ce gène<br>&nbsp;&nbsp;– ⚠️ <b>De plus</b> : dans les translocations X-autosome, l'inactivation est <b>NON ALÉATOIRE</b> — c'est toujours le <b>X NORMAL qui est inactivé</b> (car inactiver le X transloqué désactiverait aussi l'autosome → létal) → l'X porteur de la translocation reste actif<br>&nbsp;&nbsp;– → Si le gène muté est sur le <b>X transloqué</b>, il sera <b>ACTIF</b> → <b>la femme est ATTEINTE</b><br><br>• <b>d) HOMIZYGOTIE PAR DISOMIE UNIPARENTALE ou DÉLÉTION</b><br>&nbsp;&nbsp;– <b>DUP de l'X normal</b> → la femme n'a qu'un X muté fonctionnel<br><br>• <b>e) HÉRÉDITÉ DU PÈRE ATTEINT</b> ⚠️<br>&nbsp;&nbsp;– Une fille de père atteint est <b>OBLIGATOIREMENT CONDUCTRICE</b> (elle reçoit son seul X, muté)<br><br>• <b>f) PHÉNOTYPES OÙ LES CONDUCTRICES SONT RÉGULIÈREMENT ATTEINTES :</b><br>&nbsp;&nbsp;– <b>SYNDROME DE L'X FRAGILE</b> ⭐ : ~<b>20 % des conductrices ont un QI &lt; 70</b> ; beaucoup ont des troubles d'apprentissage, anxiété. ⚠️ De plus, les conductrices avec une <b>PRÉMUTATION (55–200 répétitions CGG)</b> développent le <b>FXTAS</b> (tremblement/ataxie lié à l'X fragile) après 50 ans — ~<b>16–20 % des conductrices</b> — et une <b>insuffisance ovarienne prématurée (FXPOI)</b> chez ~<b>20 %</b><br>&nbsp;&nbsp;– <b>DÉFICIT EN G6PD</b> : les conductrices peuvent avoir des <b>crises hémolytiques</b> selon le taux d'activité enzymatique (effet mosaïque sur les globules rouges — ⚠️ le test quantitatif peut être <b>FAUSSEMENT NORMAL</b> pendant une crise à cause de la réticulocytose)<br>&nbsp;&nbsp;– <b>DALTONISME (protanopie/déuteranopie)</b> : rare chez les conductrices, mais possible si inactivation biaisée (test d'<b>Ishihara</b>)<br>&nbsp;&nbsp;– <b>HÉMOFILIE A</b> : les conductrices ont un taux de facteur VIII de <b>~50 % en moyenne</b> (avec un intervalle très large de 20 à 120 %) → ⚠️ <b>elles peuvent SAIGNER</b> (ménorragies, hémorragie du post-partum, saignement post-opératoire). <b>Il faut doser le facteur VIII/VON WILLEBRAND chez toute conductrice avant une intervention</b><br>&nbsp;&nbsp;– <b>DMD/BMD</b> : myalgies, faiblesse proximale, cardiomyopathie<br>&nbsp;&nbsp;– <b>HYPOPHOSPHATÉMIE liée à l'X</b>, <b>albinisme oculaire</b>, <b>ichtyose liée à l'X</b>, <b>diabète insipide néphrogénique (AVPR2)</b> — conductrices parfois symptomatiques<br><br><b>3. ⚠️ COMMENT IDENTIFIER UNE CONDUCTRICE :</b><br>• <b>Arbre généalogique</b> : fils atteint + père sain ; ou frère atteint ; ou oncle maternel atteint ; ou grand-père maternel atteint<br>• <b>Dosages biochimiques</b> : facteur VIII/IX (hémophilie), G6PD, CK (DMD — ⚠️ élevée chez ~70 % des conductrices de DMD, mais non spécifique)<br>• ⭐ <b>BIOLOGIE MOLÉCULAIRE — LE SEUL TEST FIABLE</b> : <b>SÉQUENÇAGE</b> (Sanger, NGS) ou <b>MLPA / analyse des CNV</b> pour la mutation familiale connue<br>• <b>Test de liaison (linkage)</b> avec des marqueurs si la mutation n'est pas identifiée<br>• ⚠️ <b>L'étude de l'INACTIVATION DU X (test HUMARA)</b> peut évaluer le risque de phénotype manifestant, mais n'est pas prédictif de façon fiable<br>• ⚠️ <b>Une femme SANS antécédent familial peut être conductrice « de novo »</b> : la mère d'un garçon atteint de DMD a ~<b>2/3 de risque</b> d'être conductrice (1/3 des cas sont des mutations de novo). Si elle a <b>2 fils atteints</b>, elle est quasi certainement conductrice<br>• ⚠️ <b>MOSAÏCISME GERMINAL maternel</b> : une femme peut avoir plusieurs enfants atteints tout en étant <b>négative au test sanguin</b> (la mutation n'est que dans ses ovocytes) — risque de récurrence résiduel <b>~1 à 5 %</b><br><br><b>4. ⚠️ CONSEIL GÉNÉTIQUE ET DIAGNOSTIC PRÉNATAL :</b><br>• Identifier la <b>mutation familiale</b> chez le sujet atteint (cas index) <b>AVANT</b> de tester les femmes à risque<br>• Proposer le test aux <b>femmes apparentées</b> (sœurs, tantes maternelles, nièces, cousines)<br>• ⚠️ <b>Diagnostic prénatal</b> possible : <b>biopsie de trophoblaste (11 SA)</b> ou <b>amniocentèse (15–17 SA)</b> — ⚠️ si le fœtus est une <b>fille</b>, il faut aussi étudier l'inactivation du X pour évaluer le risque (difficile)<br>• <b>DPG (diagnostic préimplantatoire)</b> en FIV<br>• ⚠️ <b>Détermination du sexe fœtal par ADN libre circulant (cfDNA) dans le sang maternel</b> dès <b>7–9 SA</b> → si c'est une fille, <b>aucun geste invasif nécessaire</b> (elle ne sera pas atteinte) ⭐<br><br><b>📋 EXEMPLES DE MALADIES XL RÉCESSIVES :</b><br>• <b>MYOPATHIE DE DUCHENNE (DMD)</b> — <b>DMD (Xp21)</b>, dystrophine — 1/3 500 garçons — la plus fréquente des myopathies de l'enfant — marche en canard, signe de Gowers, mollets pseudo-hypertrophiques, CK ×100, perte de la marche vers 12 ans, décès vers 25–30 ans. Traitement : corticoïdes, <b>éplérenone (Exondys 51)</b>, <b>thérapie génique (delandistrogène moxeparvovec)</b> ⭐<br>• <b>MYOPATHIE DE BECKER</b> — même gène, mutation préservant le cadre de lecture → forme atténuée<br>• <b>HÉMOPHILIE A</b> — <b>F8 (Xq28)</b> — 1/5 000 garçons — facteur VIII déficient — TCA allongé, TP normal<br>• <b>HÉMOPHILIE B</b> — <b>F9 (Xq27)</b> — 1/25 000 garçons — facteur IX<br>• <b>DALTONISME (protanopie, deutéranopie)</b> — <b>OPN1LW/OPN1MW (Xq28)</b> — ⚠️ très fréquent : <b>~8 % des hommes, 0,5 % des femmes</b><br>• <b>DÉFICIT EN G6PD (favisme)</b> — <b>G6PD (Xq28)</b> — ⚠️ <b>LA PLUS FRÉQUENTE DES ENZYMOPATHIES HUMAINES</b> (~400 millions de personnes) — crise hémolytique après fèves, médicaments oxydants, infections<br>• <b>SYNDROME DE L'X FRAGILE</b> — <b>FMR1 (Xq27.3)</b> — expansion de triplets CGG — ⚠️ <b>1ʳᵉ cause de retard mental HÉRÉDITAIRE</b> — macroorchidie, visage long, oreilles décollées, autisme<br>• <b>ICHTYOSE LIÉE À L'X</b> — <b>STS (stéroïde sulfatase)</b><br>• <b>DIABÈTE INSIPIDE NÉPHROGÉNIQUE</b> — <b>AVPR2</b><br>• <b>ALBINISME OCULAIRE type 1</b> — <b>GPR143</b><br>• <b>SYNDROME DE LESCH-NYHAN</b> — <b>HPRT1</b> — hyperuricémie + auto-mutilation<br>• <b>AGAMMAGLOBULINÉMIE DE BRUTON</b> — <b>BTK</b> — absence de lymphocytes B<br>• <b>SYNDROME DE WISKOTT-ALDRICH</b> — <b>WAS</b> — eczéma + thrombopénie + immunodéficience<br>• <b>DYSTROPHIE MUSCULAIRE D'EMERY-DREIFUSS</b>, <b>CMTX (connexine 32)</b>, <b>adrenoleucodystrophie (ABCD1)</b>, <b>syndrome de Menkes (ATP7A)</b>, <b>déficit en OTCS</b>","t":"genetique-2026 EXAM-2026"}]},{"id":"biomol-S1-2026","nom":"🔬 Biologie moléculaire","src":"COURS OFFICIEL Pr ROCHD","ordre":4,"module":"M111","desc":"Les 6 chapitres du poly","cards":[{"q":"📘 <b>COURS OFFICIEL — BIOLOGIE MOLÉCULAIRE &amp; GÉNIE GÉNÉTIQUE</b> (Pr T. ROCHD, FMDC Casablanca, S1). Quel est le plan exact du poly ?","a":"<b>⭐ C'EST LE POLY OFFICIEL DU MODULE M111 — PARTIE BIOLOGIE MOLÉCULAIRE</b><br><br><b>« POLYCOPIE DE BIOLOGIE MOLECULAIRE ET GENIE GENETIQUE » — Pr. T. ROCHD — 1ʳᵉ année S1 — Université Hassan II, Faculté de Médecine Dentaire, Casablanca</b><br><br>⚠️ <b>TOUT CE QUI EST À L'EXAMEN DE BIOMOL EST DANS CES 6 CHAPITRES — RIEN D'AUTRE :</b><br><br><b>I — LES ACIDES NUCLÉIQUES</b><br>• I-1 Définition<br>• I-2 Structure : <b>I-2-1 le nucléotide · I-2-2 l'ADN · I-2-3 l'ARN</b><br><br><b>II — LA RÉPLICATION</b><br>• II-1 Définition · II-2 Caractéristiques · II-3 <b>Les outils de la réplication</b> · II-4 Les étapes (<b>initiation, élongation, terminaison</b>)<br><br><b>III — MUTATIONS ET SYSTÈME DE SAUVEGARDE ET RÉPARATION</b><br>• III-1 Les mutations : définition · types · <b>effets</b> · conséquences · <b>III-1-3 Les mécanismes de réparation de l'ADN</b><br><br><b>IV — MÉCANISMES DE LA TRANSCRIPTION</b><br>• IV-1 Définition · IV-2 Transcription ADN → ARNm (<b>initiation, élongation, terminaison</b>) · <b>IV-3 Maturation de l'ARNm (3 étapes)</b><br><br><b>V — L'EXPRESSION DU GÉNOME (LA TRADUCTION)</b><br>• V-1 Définition · V-2 Étapes (<b>initiation, élongation, terminaison</b>) · V-3 <b>Modifications post-traductionnelles</b><br><br><b>VI — LE GÉNIE GÉNÉTIQUE</b><br>• VI-1 Définition · VI-2 <b>Outils enzymatiques</b> (enzymes de restriction, vecteurs, sondes) · VI-3 <b>Le clonage</b> · VI-4 <b>Applications</b> (diagnostic des maladies, thérapie génique)<br><br><b>📊 LES 5 « GROS MORCEAUX » À MAÎTRISER EN PRIORITÉ (par ordre d'importance à l'examen) :</b><br>1. ⭐⭐⭐ <b>LES OUTILS DE LA RÉPLICATION</b> (hélicase, primase, ADN pol, topo-isomérase, ligase, RNase H) + <b>brin direct / brin indirect / Okazaki</b><br>2. ⭐⭐⭐ <b>LES 4 TYPES D'EFFETS DES MUTATIONS</b> (silencieuse, conservatrice, faux-sens, codon stop) + <b>le code génétique</b><br>3. ⭐⭐⭐ <b>LA MATURATION DE L'ARNm — LES 3 ÉTAPES</b> (queue polyA, coiffe, excision-épissage)<br>4. ⭐⭐ <b>LES OUTILS DU GÉNIE GÉNÉTIQUE</b> (enzymes de restriction, vecteurs, sondes) + <b>clonage</b><br>5. ⭐⭐ <b>LA THÉRAPIE GÉNIQUE</b> (in vivo / ex vivo / in situ + les 4 exemples : mélanome, hypercholestérolémie familiale, maladies cardiovasculaires, gène suicide)<br><br><b>🔗 LIEN AVEC L'AUTRE PARTIE DU MODULE :</b><br>⚠️ Le module M111 = <b>« Biologie cellulaire, moléculaire et génétique »</b> avec <b>DEUX ÉLÉMENTS</b> :<br>• <b>1/ BIOLOGIE CELLULAIRE</b> — <b>Pr F. RHRICH-HADDOUT</b> (voir le deck <b>biocell-methodes-S1-2026.csv</b>)<br>• <b>2/ BIOLOGIE MOLÉCULAIRE ET GÉNÉTIQUE</b> — <b>Pr T. ROCHD</b> (ce deck)<br>⚠️ <b>L'EXAMEN 2026 = 90 QCM au total : 50 QCM BIOCELL + 40 QCM GÉNÉTIQUE</b> (voir <b>genetique-S1-2026.csv</b> et <b>biocell-S1-2026.csv</b>)","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>I-2-1 — LE NUCLÉOTIDE</b> : quelle est sa composition exacte selon le cours du Pr ROCHD ?","a":"<b>⭐ DÉFINITION DU COURS : « Le nucléotide est l'UNITÉ DE CONSTRUCTION DES ACIDES NUCLÉIQUES »</b><br><br><b>⚠️ LA FORMULE À APPRENDRE PAR CŒUR :</b><br><br>🔴 <b>NUCLÉOTIDE = SUCRE + BASE + GROUPEMENT PHOSPHATE</b><br><br><b>LES 3 COMPOSANTS EN DÉTAIL :</b><br><br><b>1. LE SUCRE (un PENTOSE = sucre à 5 carbones)</b><br>• <b>ADN</b> → <b>DÉSOXYRIBOSE</b> ⚠️ (un <b>H</b> en position <b>2'</b>)<br>• <b>ARN</b> → <b>RIBOSE</b> ⚠️ (un <b>OH</b> en position <b>2'</b>)<br>• Numérotation des carbones : <b>1', 2', 3', 4', 5'</b> (avec des <b>'</b> = « prime », pour ne pas confondre avec la numérotation des bases)<br>• ⚠️ La <b>base est fixée sur le carbone 1'</b> · le <b>phosphate sur le carbone 5'</b> · le <b>OH 3'</b> est le point d'élongation<br><br><b>2. LA BASE AZOTÉE</b><br>⚠️ <b>4 bases pour l'ADN</b> : <b>ADÉNINE (A), THYMINE (T), GUANINE (G), CYTOSINE (C)</b><br>⚠️ <b>4 bases pour l'ARN</b> : <b>ADÉNINE (A), URACILE (U), GUANINE (G), CYTOSINE (C)</b><br>• <b>PURIQUES (double cycle)</b> : <b>A et G</b> ⚠️ mnémotechnique : « <b>PAG</b> » = Puriques → Adénine, Guanine<br>• <b>PYRIMIDIQUES (simple cycle)</b> : <b>C, T, U</b> ⚠️ mnémotechnique : « <b>CUT</b> » = Cytosine, Uracile, Thymine<br>• ⚠️ <b>LA THYMINE = 5-MÉTHYL-URACILE</b><br><br><b>3. LE GROUPEMENT PHOSPHATE</b><br>• <b>1 phosphate</b> → <b>NUCLÉOTIDE MONOPHOSPHATE</b> (AMP, GMP, CMP, TMP, UMP)<br>• <b>2 phosphates</b> → <b>DIPHOSPHATE</b> (ADP)<br>• <b>3 phosphates</b> → <b>TRIPHOSPHATE</b> (ATP, GTP, CTP, TTP, UTP)<br>• ⚠️ Ce sont les <b>NUCLÉOSIDES TRIPHOSPHATES (dNTP pour l'ADN, NTP pour l'ARN)</b> qui sont les <b>SUBSTRATS</b> des polymérases<br>• ⚠️ Les liaisons <b>phosphoanhydride</b> entre les phosphates sont <b>riches en énergie</b> (~7,3 kcal/mol pour l'ATP) → l'hydrolyse du pyrophosphate (PPi) par la <b>pyrophosphatase</b> rend la polymérisation <b>IRRÉVERSIBLE</b> ⭐<br><br><b>⚠️ DISTINCTION ESSENTIELLE — NUCLÉOSIDE vs NUCLÉOTIDE :</b><br>• <b>NUCLÉOSIDE</b> = <b>SUCRE + BASE</b> (sans phosphate) → <b>adénosine, guanosine, cytidine, thymidine, uridine</b><br>• <b>NUCLÉOTIDE</b> = <b>SUCRE + BASE + PHOSPHATE</b> → <b>adénylate (AMP), guanylate, cytidylate, thymidylate, uridylate</b><br>• ⚠️ Le cours parle de « <b>nucléoside tri-P</b> » dans son schéma<br><br><b>📋 L'ENCHAÎNEMENT — LA LIAISON PHOSPHODIESTER :</b><br>• Les nucléotides se lient par une <b>LIAISON PHOSPHODIESTER</b> entre le <b>phosphate en 5'</b> d'un nucléotide et le <b>OH en 3'</b> du nucléotide précédent<br>• ⚠️ Cela crée une <b>CHAÎNE ORIENTÉE 5' → 3'</b> avec un <b>squelette sucre-phosphate polaire et chargé négativement</b><br>• ⚠️ C'est pourquoi l'ADN <b>MIGRE VERS L'ANODE (+)</b> en électrophorèse<br>• ⚠️ Et pourquoi l'ADN se lie aux <b>HISTONES</b> (chargées +) et aux colorants <b>BASIQUES</b><br><br><b>⭐ PHRASE DU COURS À RETENIR TEXTUELLEMENT :</b><br>« <b>C'est la succession des bases résultant de l'enchaînement des nucléotides dans l'acide nucléique qui constitue le message génétique.</b> »","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>I-2-2 — L'ADN</b> : définition, structure, fonctions et types selon le cours du Pr ROCHD","a":"<b>⭐ DÉFINITION DU COURS : « L'ADN est la molécule SUPPORT DE L'INFORMATION GÉNÉTIQUE HÉRÉDITAIRE »</b><br><br><b>1. LOCALISATION ⚠️ :</b><br>• <b>NUCLEUS (noyau)</b> chez les eucaryotes — l'ADN y forme des <b>pelotes</b><br>• ⚠️ <b>ET UNE PARTIE AU NIVEAU DES MITOCHONDRIES</b> (ADNmt)<br>• ⚠️ <b>Dans le noyau : ADN LINÉAIRE, scindé en plusieurs ADN formant des CHROMOSOMES</b>, « <b>plus ou moins compacté et associé aux HISTONES</b> »<br>• ⚠️ <b>Dans les MITOCHONDRIES et les CHLOROPLASTES : l'ADN est TOUJOURS CIRCULAIRE, comme chez les BACTÉRIES</b> ⭐ (argument majeur de la <b>THÉORIE ENDOSYMBIOTIQUE</b> de Lynn Margulis)<br><br><b>2. ⭐ STRUCTURE :</b><br>• « <b>La structure originale de l'ADN est formée de 2 BRINS COMPLÉMENTAIRES, ANTIPARALLÈLES enroulés en HÉLICE</b> »<br>• ⚠️ <b>Les bases azotées s'HYBRIDENT entre elles : A avec T et C avec G</b> → « <b>on dit que les bases sont COMPLÉMENTAIRES</b> »<br>• <b>A = T</b> → <b>2 LIAISONS HYDROGÈNE</b><br>• <b>G ≡ C</b> → <b>3 LIAISONS HYDROGÈNE</b> ⚠️ (plus stable → les régions riches en G-C ont une <b>Tm plus élevée</b>)<br>• ⚠️ <b>ANTIPARALLÈLE</b> = un brin est orienté <b>5'→3'</b>, l'autre <b>3'→5'</b><br>• <b>RÈGLES DE CHARGAFF</b> : <b>A = T</b> et <b>G = C</b> ; donc <b>A+G = T+C</b> (purines = pyrimidines) → <b>(A+G)/(T+C) = 1</b> ⚠️ mais <b>(A+T)/(G+C) varie selon les espèces</b><br>• <b>B-DNA</b> (forme physiologique) : hélice <b>droite</b>, <b>10,5 pb par tour</b>, pas de <b>3,4 nm</b>, diamètre <b>2 nm</b>, distance entre bases <b>0,34 nm</b>, <b>grand sillon</b> et <b>petit sillon</b><br>• <b>Niveaux d'organisation (schéma du cours)</b> : <b>cellule → noyau → chromosome (avec télomères et centromère) → chromatides → nucléosomes (ADN + histones) → ADN double brin → paires de bases</b><br><br><b>3. ⭐ FONCTION — LE CHIFFRE À RETENIR :</b><br>« <b>L'ADN humain est une macromolécule contenant 3,3 MILLIARDS DE PAIRES DE BASES. SEULES ENVIRON 10 % CODENT, DONT 1,5 % POUR LA SYNTHÈSE PROTÉIQUE.</b> »<br><br>⚠️ <b>CES 3 CHIFFRES SONT TOMBALES À L'EXAMEN — À APPRENDRE PAR CŒUR :</b><br>• <b>3,3 × 10⁹ paires de bases</b> = taille du génome humain haploïde (~<b>3,2 Gb</b>)<br>• <b>~10 %</b> du génome est <b>CODANT</b> (au sens large : exons + gènes à ARN)<br>• ⚠️ <b>1,5 %</b> seulement code pour la <b>SYNTHÈSE PROTÉIQUE</b> (= les <b>EXONS</b>)<br>• ⚠️ Donc <b>~98,5 % = ADN NON CODANT</b> (« <b>junk DNA</b> » — en réalité très régulateur : introns, promoteurs, enhancers, silencers, L1/Alu, pseudogènes, ARNnc)<br>• <b>~20 000 à 25 000 gènes</b> chez l'homme<br><br><b>📋 LES 3 FONCTIONS DE L'ADN (énumération EXACTE du cours) :</b><br><b>1.</b> ⭐ <b>SA FONCTION PRINCIPALE EST DE STOCKER L'INFORMATION GÉNÉTIQUE</b>. « Cette information est contenue dans <b>l'enchaînement NON ALÉATOIRE des nucléotides</b> »<br><b>2.</b> <b>LA TRANSMISSION DE CETTE INFORMATION DE GÉNÉRATION EN GÉNÉRATION</b>. « Cela permet <b>l'hérédité</b> »<br><b>3.</b> <b>POSSIBILITÉ DE MODIFICATION DE L'INFORMATION PORTÉE PAR L'ADN (= MUTATION)</b>. « Cela aboutit à une <b>DIVERSITÉ des individus</b> et à une <b>ÉVOLUTION POSSIBLE des espèces</b> » ⚠️ <b>la mutation est donc AUSSI une FONCTION, pas seulement une pathologie</b><br><br><b>4. ⭐ LES DIFFÉRENTS TYPES D'ADN (liste EXACTE du cours — 5 types) :</b><br>• <b>ADN POLYMÉRASE</b> : ⚠️ <b>« enzyme catalysant la formation d'ADN à partir des nucléotides »</b> — ⚠️ attention, le cours le liste ici dans « types d'ADN » mais c'est bien une <b>ENZYME</b>, pas un acide nucléique<br>• <b>ADN RÉPÉTITIF</b> : « séquences d'ADN identiques qui se répètent dans le génome. <b>C'est un ADN NON CODANT</b> » → <b>ADN satellite</b> (centromères, télomères), <b>minisatellites (VNTR)</b>, <b>microsatellites (STR)</b>, <b>Alu (SINE), L1 (LINE)</b><br>• <b>ADN CIRCULAIRE</b> : « ADN formant une molécule circulaire » → <b>plasmides bactériens, ADNmt, ADN des chloroplastes</b><br>• <b>ADN RIBOSOMIQUE (ADNr / ADN ribosomal)</b> : « <b>ADN codant pour les ARN RIBOSOMIQUES</b> » → ⚠️ localisé dans les <b>NOR</b> sur les bras courts des <b>acrocentriques 13, 14, 15, 21, 22</b>, ~<b>300 copies en tandem</b><br>• <b>ADN MITOCHONDRIAL (ADNmt)</b> : « ADN constituant le génome des mitochondries » → ⚠️ <b>16 569 pb, circulaire, double brin, 37 gènes</b> (<b>13 protéines</b> de la chaîne respiratoire, <b>2 ARNr</b> — 12S et 16S, <b>22 ARNt</b>) · <b>hérédité MATERNELLE</b> ⭐ (le spermatozoïde n'apporte que son noyau, ses mitochondries sont ubiquitinées et détruites) · <b>taux de mutation ×10</b> par rapport à l'ADN nucléaire (pas d'histones, peu de réparation, proximité des ROS) · <b>code génétique LÉGÈREMENT DIFFÉRENT</b> ⚠️ (AGA/AGG = <b>STOP</b> au lieu d'Arg ; AUA = <b>Met</b> au lieu d'Ile ; UGA = <b>Trp</b> au lieu de STOP) · <b>hétéroplasmie</b> (mélange d'ADNmt normal et muté dans une cellule) → <b>effet de seuil</b><br>• ⚠️ <b>Maladies mitochondriales</b> : <b>MELAS, MERRF, LHON (Leber), NARP, Kearns-Sayre, syndrome de Pearson</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>I-2-3 — L'ARN</b> : ⭐ quelles sont les <b>4 DIFFÉRENCES</b> avec l'ADN selon le cours du Pr ROCHD ? Et quelles sont les <b>5 FAMILLES d'ARN</b> ?","a":"<b>⭐⭐ QUESTION D'EXAMEN DIRECTE — À APPRENDRE MOT POUR MOT :</b><br><br>📖 <b>TEXTE EXACT DU COURS :</b><br>« <b>L'ARN est un polynucléotide similaire à l'ADN, aussi bien en termes structurels qu'en termes fonctionnels (matérialisation et traitement de l'information génétique). L'ARN présente 4 DIFFÉRENCES par rapport à l'ADN :</b> »<br><br><b>⚠️ LES 4 DIFFÉRENCES (nombre exact = 4) :</b><br><br><b>1.</b> « <b>l'ARN est TOUJOURS SIMPLE BRIN</b> sauf chez certains procaryotes »<br>&nbsp;&nbsp;⚠️ (en réalité : sauf chez certains <b>VIRUS</b> — rotavirus, réovirus ont un ARN double brin)<br><br><b>2.</b> « <b>le SUCRE est un RIBOSE et non DÉSOXYRIBOSE</b> (ADN) »<br>&nbsp;&nbsp;⚠️ Le ribose porte un <b>OH en 2'</b> → rend l'ARN <b>INSTABLE</b> (hydrolyse alcaline) mais capable de <b>structures 3D</b> (ribozymes)<br><br><b>3.</b> « <b>la BASE COMPLÉMENTAIRE de l'ADÉNINE est l'URACILE et non la THYMINE</b> (ADN) »<br>&nbsp;&nbsp;⚠️ <b>Uracile = Thymine sans le groupe méthyle en 5</b><br><br><b>4.</b> « <b>l'ARN est COURT (50 à 5 000 NUCLÉOTIDES) et non pas des MILLIONS comme dans l'ADN</b> »<br>&nbsp;&nbsp;⚠️ <b>CES 2 CHIFFRES SONT À RETENIR : 50 à 5 000 nucléotides</b><br><br>⚠️ <b>ATTENTION — PIÈGE :</b> Si l'examen demande « <b>combien de différences</b> », la réponse est <b>4</b> (comme dans le cours). Ne réponds pas 6 ou 7 même si biologiquement il y en a d'autres (stabilité, absence de réparation, fonction catalytique, localisation).<br><br><b>📋 LES 5 FAMILLES D'ARN — ⚠️ LE COURS DIT TEXTUELLEMENT : « Dans la cellule eucaryote, il existe 5 FAMILLES D'ARN assurant chacune une fonction » :</b><br><br><b>1. ARNr = ARN RIBOSOMIQUE</b><br>« <b>Participent, avec les protéines ribosomiques, à la FORMATION DES RIBOSOMES</b> »<br>⚠️ <b>80 à 85 % de l'ARN total</b> — le plus abondant<br>⚠️ Chez l'eucaryote : <b>28S, 18S, 5.8S</b> (pré-ARNr 45S, ARN pol I, nucléole) + <b>5S</b> (ARN pol III, hors nucléole)<br>⭐ <b>Le 28S est un RIBOZYME — centre peptidyl-transférase</b><br><br><b>2. ARNt = ARN DE TRANSFERT</b><br>« <b>Transfère les ACIDES AMINÉS vers le lieu de synthèse des protéines</b> »<br>⚠️ <b>10 à 15 %</b> de l'ARN total — <b>73 à 93 nucléotides</b><br>Structure en <b>TRÈFLE</b> (2D) : <b>bras accepteur CCA-3', bras D (dihydrouridine), bras anticodon, bras TψC, bras variable</b> ; en <b>L</b> (3D)<br>Chargé par les <b>AMINOACYL-ARNt SYNTHÉTASES</b> (20 enzymes, classes I et II) ⚠️ <b>réaction en 2 temps avec un aminoacyl-AMP intermédiaire</b><br>⚠️ <b>Règle du WOBBLE (Crick)</b> à la 3ᵉ position du codon → <b>inosine</b><br><br><b>3. ARNm = ARN MESSAGER</b><br>« <b>Portent l'INFORMATION GÉNÉTIQUE DE L'ADN VERS LE LIEU DE SYNTHÈSE DES PROTÉINES</b> »<br>⚠️ <b>1 à 5 %</b> de l'ARN total<br>Structure mature : <b>coiffe 5' (m7G) + 5'UTR + ORF (codons) + 3'UTR + queue polyA (~200 A)</b><br>⚠️ <b>Durée de vie courte</b> (minutes à heures)<br><br><b>4. ARNsn = ARN « SMALL NUCLEAR »</b><br>« <b>Présent dans le NOYAU uniquement. Participent à la RÉGULATION POST-TRANSCRIPTIONNELLE</b> »<br>⚠️ = les <b>snARN U1, U2, U4, U5, U6</b> qui forment les <b>snRNP</b> de l'<b>ÉPISSOSOME</b> → <b>ÉPISSAGE des introns</b><br>⚠️ Comprend aussi les <b>snoARN</b> (small nucleolar) qui modifient les ARNr<br><br><b>5. ⚠️ ARNpol = ARN POLYMÉRASE</b><br>« <b>Enzyme catalysant la synthèse d'ARN</b> »<br><br>🔴 <b>⚠️⚠️ ATTENTION — PIÈGE MAJEUR DU COURS :</b><br>Le cours de Pr ROCHD liste « <b>ARNpol</b> » comme <b>5ᵉ famille d'ARN</b>. <b>BIOLOGIQUEMENT, L'ARN POLYMÉRASE EST UNE PROTÉINE (une enzyme), PAS UN ARN.</b> ⚠️ <b>MAIS C'EST CE QUE DIT LE COURS OFFICIEL — ET L'EXAMEN PORTE SUR LE COURS.</b><br>→ <b>Si le QCM demande « quelles sont les 5 familles d'ARN du cours ? », la réponse attendue inclut ARNpol.</b><br>→ ⚠️ <b>Retiens la liste DU COURS : ARNr, ARNt, ARNm, ARNsn, ARNpol</b><br>→ <b>Mais sache que la liste biologique complète est</b> : ARNr, ARNt, ARNm, snARN, snoARN, miARN, siARN, piARN, lncARN, eRNA, circARN<br><br><b>📋 LES 3 ARN POLYMÉRASES EUCARYOTES (à connaître en plus) :</b><br>• <b>ARN POL I</b> : <b>NUCLÉOLE</b> → <b>pré-ARNr 45S</b> (28S, 18S, 5.8S) — résistante à l'α-amanitine<br>• <b>ARN POL II</b> : <b>NUCLÉOPLASME</b> → <b>ARNm</b>, snARN, miARN, lncARN — ⚠️ <b>TRÈS SENSIBLE à l'α-AMANITINE</b> (toxine d'<i>Amanita phalloides</i>)<br>• <b>ARN POL III</b> : → <b>ARNt, ARNr 5S, ARN U6, 7SL</b> — modérément sensible<br>• <b>POLRMT</b> : mitochondriale → 13 ARNm, 2 ARNr, 22 ARNt de l'ADNmt<br>• ⚠️ <b>TRANSCRIPTASE INVERSE</b> : ARN → ADN (rétrovirus, télomérase)","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>II — LA RÉPLICATION</b> : ⭐ quels sont <b>LES OUTILS de la réplication</b> selon le cours du Pr ROCHD ? (question quasi certaine à l'examen)","a":"<b>⭐⭐ LA QUESTION LA PLUS PROBABLE DE TOUT L'EXAMEN DE BIOMOL</b><br><br>📖 <b>TEXTE EXACT DU COURS : « La réplication de l'ADN nécessite :</b><br>❖ <b>Une matrice d'ADN</b> (brin parental)<br>❖ <b>Des bases puriques et pyrimidiques (A, C, G, T, U)</b><br>❖ <b>Des enzymes »</b><br><br><b>🔴 LES 7 ENZYMES / OUTILS — LISTE EXACTE DU COURS :</b><br><br><b>1. ⭐ HÉLICASE</b> — « <b>permet la SÉPARATION des 2 BRINS</b> »<br>• ⚠️ Elle <b>ROMPT LES LIAISONS HYDROGÈNE</b> entre les bases (elle ne coupe PAS les liaisons phosphodiester)<br>• Elle utilise l'<b>ATP</b><br>• Elle crée la <b>FOURCHE DE RÉPLICATION</b><br>• <b>Hélicases humaines</b> : <b>MCM2-7</b> (le cœur du complexe, licencié en G1), <b>Cdc45, GINS</b> = <b>complexe CMG</b><br>• ⚠️ <b>Syndrome de Werner (WRN)</b>, <b>Bloom (BLM)</b>, <b>Rothmund-Thomson (RECQL4)</b> = mutations d'hélicases RecQ<br><br><b>2. ⭐ LES PROTÉINES DE LIAISON (SSB / RPA)</b> — « <b>empêchent les 2 brins de se recoller</b> »<br>• ⚠️ Chez les eucaryotes = <b>RPA (Replication Protein A)</b> ; chez les bactéries = <b>SSB (Single-Strand Binding protein)</b><br>• Elles se lient à l'<b>ADN simple brin</b> formé et <b>ÉVITENT LA REFORMATION DE LA DOUBLE HÉLICE</b><br>• Elles protègent aussi l'ADN simple brin de la <b>dégradation par les nucléases</b> et empêchent la formation de <b>structures secondaires (tiges-boucles)</b><br><br><b>3. ⭐ ARN POLYMÉRASE ou PRIMASE</b> — « <b>fournit les AMORCES ARN</b> »<br>• ⚠️ <b>POINT CAPITAL :</b> « <b>L'ADNpol A BESOIN D'UNE AMORCE pour fonctionner, c'est l'ARNpol (primase) qui fournit cette amorce</b> »<br>• ⚠️ Pourquoi ? Parce que l'<b>ADN polymérase ne peut PAS initier une synthèse de novo</b> — elle a besoin d'une <b>extrémité 3'-OH LIBRE</b> pour ajouter le premier nucléotide<br>• L'amorce ARN fait <b>~10 nucléotides</b> chez les eucaryotes (~<b>60 pb</b> ARN+ADN par le complexe <b>Polα-primase</b>)<br>• ⚠️ <b>Cette amorce sera ensuite ÉLIMINÉE</b> — c'est l'origine du <b>PROBLÈME DE LA RÉPLICATION TERMINALE</b> au niveau des télomères<br><br><b>4. ⭐ L'ADN POLYMÉRASE</b> — synthétise l'ADN<br>• ⚠️ « <b>L'élongation de l'ADN progresse TOUJOURS dans le sens 5' VERS 3' pour le brin en création</b> »<br>• « <b>C'est l'ADNpol qui AJOUTE à l'extrémité 3' de la molécule en formation des DÉSOXYRIBONUCLÉOTIDES</b> »<br>• ⚠️ Elle a aussi une <b>FONCTION D'ÉDITION (« PROOFREADING »)</b> : « <b>la correction se fait dans le sens 3' → 5' : l'exonucléase dégrade la nouvelle extrémité 3' si l'appariement n'est pas correct. L'ADNpol reprend son travail et insère le bon nucléotide</b> »<br>• <b>ADN pol eucaryotes :</b><br>&nbsp;&nbsp;– <b>ADN POL α (alpha)</b> : associée à la <b>PRIMASE</b> — initie la synthèse (amorce ARN + ~20 dNTP)<br>&nbsp;&nbsp;– <b>ADN POL δ (delta)</b> ⭐ : élongation du <b>BRIN INDIRECT (retardé)</b> — très <b>processive</b> avec la <b>PCNA</b><br>&nbsp;&nbsp;– <b>ADN POL ε (epsilon)</b> ⭐ : élongation du <b>BRIN DIRECT (continu)</b><br>&nbsp;&nbsp;– <b>ADN POL β (bêta)</b> : <b>RÉPARATION (BER)</b><br>&nbsp;&nbsp;– <b>ADN POL γ (gamma)</b> : <b>RÉPLICATION DE L'ADNmt</b> ⚠️ (mutations → maladies mitochondriales ; cible de toxicité de certains antiviraux)<br>&nbsp;&nbsp;– <b>ADN POL η, ι, κ, ζ</b> : <b>polymérases de BYPASS TRANSLÉSIONNEL</b> (sans relecture → mutagènes). ⚠️ <b>POLH (η)</b> traverse correctement les <b>dimères de thymine UV</b> — sa mutation cause le <b>XERODERMA PIGMENTOSUM VARIANT (XPV)</b><br>• ⚠️ <b>CLAMP = PCNA</b> (Proliferating Cell Nuclear Antigen) — anneau <b>trimérique coulissant</b> chargé par <b>RFC (Replication Factor C)</b> → confère la <b>PROCESSIVITÉ</b> à Pol δ/ε. ⚠️ <b>La PCNA est aussi un MARQUEUR DE PROLIFÉRATION en immunohistochimie</b><br><br><b>5. ⭐⭐ TOPO-ISOMÉRASE</b> — « <b>COUPE UN BRIN, pour déroulement</b> »<br>• ⚠️ Texte exact du cours : « <b>Sur l'ADN double brin PRÉCÉDANT l'hélicase se fixe une TOPO-ISOMÉRASE I qui va permettre d'éviter les TORSIONS entraînées par l'ouverture de la double-chaîne par l'hélicase (comme pour une ficelle dont on écarte les 2 brins), en COUPANT UN DES BRINS, puis le RESSOUDANT après déroulement.</b> »<br>• ⚠️ C'est la <b>TOPOISOMÉRASE I</b> qui agit ici (coupe <b>1 seul brin</b>, <b>ATP-INDÉPENDANTE</b>)<br>• La <b>TOPOISOMÉRASE II (gyrase bactérienne)</b> coupe <b>LES DEUX BRINS</b>, <b>ATP-DÉPENDANTE</b>, fait passer un autre segment d'ADN à travers la coupure<br>• 💊 <b>Pharmacologie :</b> <b>camptothécine/irinotécan/topotécan</b> (topo I) · <b>étoposide/doxorubicine</b> (topo II) · <b>fluoroquinolones</b> (gyrase bactérienne)<br><br><b>6. ⭐ ADN LIGASE</b> — « <b>resoude le brin ADN (rétablit les LIAISONS PHOSPHODIESTERS)</b> »<br>• ⚠️ Elle relie les <b>FRAGMENTS D'OKAZAKI</b> entre eux après l'élimination des amorces ARN<br>• Elle forme une <b>liaison phosphodiester</b> entre le <b>3'-OH</b> et le <b>5'-phosphate</b><br>• ⚠️ <b>ATP-dépendante</b> chez les eucaryotes et les bactériophages ; <b>NAD⁺-dépendante</b> chez la plupart des bactéries<br>• <b>LIG1</b> (réplication), <b>LIG3</b> (BER, mitochondrie), <b>LIG4</b> (NHEJ — ⚠️ mutations = <b>syndrome de LIG4</b> : microcéphalie + immunodéficience + radiosensibilité)<br>• ⚠️ Outil essentiel du <b>GÉNIE GÉNÉTIQUE</b> (clonage) — voir chapitre VI<br><br><b>7. ⭐ RNase H</b> — « <b>enlève les AMORCES</b> »<br>• ⚠️ Texte exact : « <b>Il y aura donc sur le brin retardé (= fragments d'Okazaki) des JONCTIONS ARN-ADN, qui seront par la suite ÉLIMINÉES par une RNase H. D'autres ADN pol vont ensuite COMBLER LES LACUNES laissées par l'ARN.</b> »<br>• ⚠️ La <b>RNase H</b> est une <b>endonucléase qui dégrade SPÉCIFIQUEMENT l'ARN d'un hybride ARN-ADN</b><br>• Chez les eucaryotes, c'est surtout la <b>FEN1 (Flap Endonuclease 1)</b> et l'<b>activité exonucléase 5'→3' de Pol δ</b> qui éliminent les amorces<br>• 💊 <b>Pharmacologie :</b> la <b>RNase H</b> est la cible des <b>ANTISENSE OLIGONUCLEOTIDES</b> et des <b>inhibiteurs de l'intégrase du VIH</b> (l'intégrase appartient à la même famille)<br><br><b>📋 LES CARACTÉRISTIQUES DE LA RÉPLICATION (II-2) — 2 MOTS À RETENIR :</b><br>⭐ « <b>La réplication de l'ADN est SEMI-CONSERVATRICE et BIDIRECTIONNELLE</b> »<br>• <b>SEMI-CONSERVATRICE</b> : « à l'issue de la réplication, chacune des 2 molécules d'ADN nouvellement formée est constituée d'<b>UN BRIN PARENTAL et d'UN BRIN NÉOFORMÉ</b> » — ⚠️ démontré par l'expérience de <b>Meselson et Stahl (1958)</b> avec l'<b>azote lourd ¹⁵N</b> et la centrifugation en gradient de chlorure de césium<br>• <b>BIDIRECTIONNELLE</b> : « débute à partir d'une <b>ORIGINE DE RÉPLICATION</b> et progresse dans les <b>2 SENS</b> à partir de ce point créant ainsi une <b>FOURCHE DE RÉPLICATION</b> » ⚠️ En réalité, <b>2 fourches</b> qui partent en sens opposés = <b>« œil » ou bulle de réplication</b><br>• ⚠️ <b>SEMI-DISCONTINUE</b> : un brin continu, un brin discontinu<br>• ⚠️ <b>Phase S du cycle cellulaire</b> — « la duplication (ou réplication) a lieu pendant la <b>PHASE S</b> »<br><br><b>📋 LES 3 ÉTAPES (II-4) :</b><br><b>1. INITIATION</b> : « a lieu à l'<b>ORIGINE de la réplication</b>. Il existe <b>PLUSIEURS ORIGINES</b> de réplication. Comme il existe aussi des <b>protéines capables de reconnaître ces origines et d'initier la réplication</b>. La <b>FOURCHE DE RÉPLICATION</b> est créée par l'action des <b>HÉLICASES qui BRISENT LES LIAISONS HYDROGÈNES</b> entre les 2 brins de la double hélice. »<br>• ⚠️ <b>Origines eucaryotes = ARS (Autonomously Replicating Sequences)</b> · <b>~30 000 à 50 000 origines</b> dans le génome humain · <b>complexe ORC (Origin Recognition Complex)</b> · <b>Cdc6, Cdt1</b> chargent <b>MCM2-7</b> = <b>« licensing »</b> en G1 ⚠️ garantit qu'une origine ne se réplique <b>qu'UNE SEULE FOIS par cycle</b><br>• ⚠️ <b>Origine bactérienne unique = oriC</b> (chez <i>E. coli</i>), avec <b>DnaA</b><br><br><b>2. ÉLONGATION</b> : ⚠️ voir la question suivante sur le <b>brin direct / brin indirect</b><br><br><b>3. TERMINAISON</b> : « Cette phase correspond à l'<b>ARRÊT de la réplication lorsque 2 FOURCHES DE RÉPLICATION SE RENCONTRENT</b>. »<br>• ⚠️ Chez <i>E. coli</i> : région <b>ter</b> + protéine <b>Tus</b> (terminus utilization substance)<br>• ⚠️ Chez les eucaryotes : rencontre des fourches issues de <b>réplicons adjacents</b>, fusion des bulles, résolution des <b>caténanes par la TOPOISOMÉRASE II</b> (décaténation) → séparation des 2 molécules filles<br>• ⚠️ <b>PROBLÈME DE LA RÉPLICATION TERMINALE</b> aux télomères : l'amorce ARN la plus distale du brin retardé ne peut pas être remplacée → <b>raccourcissement de 50-200 pb par division</b> → résolu par la <b>TÉLOMÉRASE</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>II-4-2 — L'ÉLONGATION</b> : qu'est-ce que le <b>« BRIN DIRECT »</b> et le <b>« BRIN INDIRECT »</b> (fragments d'Okazaki) ?","a":"<b>⭐⭐ DISTINCTION FONDAMENTALE — À CONNAÎTRE PARFAITEMENT :</b><br><br>📖 <b>TEXTE EXACT DU COURS :</b><br>« <b>L'élongation de l'ADN progresse TOUJOURS dans le sens 5' vers 3' pour le brin en création. C'est l'ADNpol qui ajoute à l'extrémité 3' de la molécule en formation des désoxyribonucléotides. Étant donné que les 2 brins de la double hélice d'ADN sont ANTIPARALLÈLES, il existe de ce fait des MÉCANISMES DIFFÉRENTS selon le brin d'ADN répliqué. Il existe ainsi un « BRIN DIRECT » et un « BRIN INDIRECT ».</b> »<br><br><b>🔵 LE BRIN DIRECT (brin continu / brin meneur / leading strand)</b><br>📖 « <b>Le « brin direct » est le brin COMPLÉMENTAIRE du brin parental orienté 3' vers 5'. Il est donc créé de façon CONTINUE, dans le sens 5' vers 3'.</b> »<br>• ⚠️ <b>UNE SEULE AMORCE</b> au départ de l'origine<br>• ⚠️ Synthèse <b>CONTINUE</b>, dans le <b>MÊME SENS</b> que la progression de la fourche<br>• Enzyme : ⭐ <b>ADN POLYMÉRASE ε (epsilon)</b> chez les eucaryotes ; <b>Pol III</b> chez <i>E. coli</i><br><br><b>🔴 LE BRIN INDIRECT (brin retardé / brin différé / lagging strand)</b><br>📖 « <b>Le « brin indirect » est le brin COMPLÉMENTAIRE du brin parental orienté 5' vers 3'. Il est créé de façon DISCONTINUE, sous forme de FRAGMENTS D'OKAZAKI, dans le sens 5' à 3'.</b> »<br>• ⚠️ <b>PLUSIEURS AMORCES</b> — une par fragment d'Okazaki<br>• ⚠️ Synthèse <b>DISCONTINUE</b>, en <b>SENS INVERSE</b> de la progression de la fourche (l'ADN pol doit <b>« rebrousser chemin »</b> à chaque fragment)<br>• ⚠️ Mais <b>CHAQUE FRAGMENT est quand même synthétisé dans le sens 5'→3'</b> ⭐ (la règle est absolue)<br>• Enzyme : ⭐ <b>ADN POLYMÉRASE δ (delta)</b> chez les eucaryotes ; <b>Pol III</b> chez <i>E. coli</i><br>• ⚠️ <b>FRAGMENTS D'OKAZAKI :</b><br>&nbsp;&nbsp;– <b>Longueur : 100 à 200 nucléotides chez les EUCARYOTES</b> ⚠️ (1 000 à 2 000 chez les bactéries)<br>&nbsp;&nbsp;– Découverts par <b>Reiji et Tsuneko OKAZAKI (1968)</b> avec le <b>phage λ et l'ADN marqué au ³H-thymidine</b><br>&nbsp;&nbsp;– ⚠️ Chaque fragment commence par une <b>AMORCE ARN</b> de ~10 nt<br><br><b>📋 LE CYCLE COMPLET D'UN FRAGMENT D'OKAZAKI (6 étapes) ⭐ :</b><br>1. <b>PRIMASE (Pol α-primase)</b> synthétise une <b>amorce ARN</b> de ~10 nt<br>2. <b>POL α</b> ajoute ~20 désoxyribonucléotides (extension de l'amorce)<br>3. ⚠️ <b>« SWITCH » de polymérase</b> : <b>RFC</b> charge la <b>PCNA</b> → <b>POL δ</b> prend le relais et élonge le fragment<br>4. La <b>Pol δ</b> arrive sur l'<b>amorce ARN du fragment précédent</b> → elle la déplace en formant un <b>« FLAP » (volet) 5'</b><br>5. ⚠️ <b>FEN1 (Flap Endonuclease 1)</b> coupe le flap ARN ; la <b>RNase H</b> enlève aussi l'ARN ; la <b>DNA2</b> intervient sur les flaps longs<br>6. ⭐ <b>ADN LIGASE I</b> « resoude » le fragment → <b>brin continu</b><br><br><b>📋 LA BOUCLE TROMBONE (trombone model) ⚠️ :</b><br>• Les 2 polymérases (δ sur le brin retardé, ε sur le brin direct) font partie d'un <b>MÊME COMPLEXE</b> (le <b>RÉPLISOME</b>) qui avance ensemble<br>• Pour que la Pol δ puisse travailler <b>en sens inverse</b> tout en suivant le complexe, le brin retardé forme une <b>BOUCLE en forme de TROMBONE</b> qui grandit puis se relâche à chaque fragment<br>• <b>Le réplisome</b> = <b>CMG (Cdc45-MCM2-7-GINS)</b> + <b>Pol α-primase</b> + <b>Pol δ</b> + <b>Pol ε</b> + <b>PCNA/RFC</b> + <b>RPA</b> + <b>FEN1</b> + <b>Ligase I</b> + <b>Topo I/II</b><br>• Vitesse : <b>~50 nucléotides/seconde</b> chez l'eucaryote ⚠️ (<b>~1 000 nt/s</b> chez <i>E. coli</i>)<br><br><b>⚠️ POURQUOI CE MÉCANISME ? — LA RAISON FONDAMENTALE :</b><br>L'ADN polymérase ne peut <b>JAMAIS</b> synthétiser dans le sens 3'→5'. Pourquoi ?<br>• Elle ajoute un nucléotide sur l'<b>extrémité 3'-OH LIBRE</b>, en attaquant le <b>phosphate α</b> du dNTP entrant<br>• L'<b>énergie</b> vient de l'hydrolyse du dNTP (libération de <b>PPi</b>, hydrolysé par la pyrophosphatase → réaction irréversible)<br>• ⚠️ Si la synthèse se faisait en 3'→5', le nucléotide en croissance porterait le triphosphate, et une erreur d'incorporation suivie d'une <b>relecture (proofreading)</b> laisserait une extrémité <b>5'-monophosphate SANS ÉNERGIE</b> → <b>impossible de continuer</b><br>→ Donc le sens <b>5'→3' est une CONTRAINTE CHIMIQUE ABSOLUE</b>, et le brin retardé en est la conséquence obligée<br><br><b>📋 RAPPEL — LES 5 POINTS À RETENIR :</b><br>1. ⚠️ <b>Les 2 brins parentaux sont ANTIPARALLÈLES</b> → mécanismes différents<br>2. ⭐ <b>BRIN DIRECT = CONTINU</b>, complémentaire du parental <b>3'→5'</b>, <b>1 amorce</b>, <b>Pol ε</b><br>3. ⭐ <b>BRIN INDIRECT = DISCONTINU</b>, complémentaire du parental <b>5'→3'</b>, <b>fragments d'Okazaki (100-200 nt)</b>, <b>plusieurs amorces</b>, <b>Pol δ</b><br>4. ⭐ <b>DANS LES DEUX CAS, LA SYNTHÈSE SE FAIT EN 5'→3'</b><br>5. ⭐ <b>RNase H + FEN1 éliminent les amorces ARN, ADN LIGASE I soude les fragments</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>III — LES MUTATIONS</b> : ⭐ quels sont les <b>4 TYPES D'EFFETS DES MUTATIONS</b> selon le cours du Pr ROCHD ? (question quasi certaine)","a":"<b>⭐⭐ L'EXERCICE CLASSIQUE DE L'EXAMEN : on te donne une séquence, tu dois dire quel type de mutation c'est.</b><br><br>📖 <b>D'ABORD, LES 3 TYPES DE MUTATIONS « STRUCTURELLES » (III-1-2-1) :</b><br>• <b>SUBSTITUTION</b> = « <b>remplacement d'une base par une autre</b> »<br>• <b>DÉLÉTION</b> = « <b>perte d'une base</b> »<br>• <b>INSERTION</b> = « <b>ajout d'une base</b> »<br><br>📖 <b>L'EXEMPLE EXACT DU COURS (à savoir refaire) :</b><br><b>Brin parental</b> ……………… <b>TGG CAT GTT CGA</b><br><b>Brin complémentaire</b> ……… <b>ACC GTA CAA GCT</b><br><b>Substitution</b> ……………… <b>ACC <u>G</u>CA CAA GCT</b> ⚠️ (le T→C sur le brin parental donne A→G sur le complémentaire)<br><b>Délétion</b> …………………… <b>ACC GAC AAG CTN</b> ⚠️ (décalage du cadre de lecture à partir du point de délétion)<br><b>Insertion</b> …………………… <b>ACC GAT ACA AGC</b> ⚠️ (décalage du cadre de lecture)<br><br>⚠️ <b>DÉLÉTION et INSERTION d'1 base = MUTATION DÉCALANTE (frameshift)</b> → TOUS les acides aminés en aval sont changés → presque toujours une <b>protéine non fonctionnelle</b>. ⚠️ <b>Si 3 bases (ou un multiple de 3) sont insérées/déléées = PAS de décalage de cadre</b>.<br><br><b>🔴 LES 4 TYPES D'EFFETS (III-1-2-2) — ⭐⭐ À CONNAÎTRE PAR CŒUR AVEC LES EXEMPLES DU COURS :</b><br><br><b>1. ⭐ MUTATION SILENCIEUSE</b><br>« <b>Changement de base NE MODIFIE PAS L'ACIDE AMINÉ (Aa)</b> »<br>📖 <b>Exemple du cours : UUU → UUC = Phe</b><br>• ⚠️ Les 2 codons codent le <b>MÊME acide aminé</b> (ici la <b>phénylalanine</b>)<br>• ⚠️ Pourquoi ? Parce que le <b>CODE GÉNÉTIQUE EST DÉGÉNÉRÉ</b> (= redondant) : <b>64 codons</b> pour <b>20 acides aminés</b><br>• ⚠️ C'est presque toujours la <b>3ᵉ BASE du codon</b> qui change (<b>wobble</b>) — car la dégénérescence est à la 3ᵉ position<br>• ⭐ <b>AUCUNE CONSÉQUENCE PHÉNOTYPIQUE</b> (protéine identique)<br>• ⚠️ Attention : une mutation silencieuse peut quand même <b>modifier l'ÉPISSAGE</b> (création d'un site d'épissage cryptique) ou la <b>vitesse de traduction</b> (codon rare) → <b>pas toujours totalement neutre</b><br><br><b>2. ⭐ MUTATION CONSERVATRICE</b><br>« <b>Changement de base induit un changement d'Aa, mais AYANT LES MÊMES PROPRIÉTÉS</b> »<br>📖 <b>Exemple du cours : AAA (Lys) → AGA (Arg) : 2 Aa BASIQUES</b><br>• ⚠️ L'acide aminé change, mais il reste dans la <b>MÊME CLASSE CHIMIQUE</b><br>• ⚠️ Donc la protéine reste <b>GÉNÉRALEMENT FONCTIONNELLE</b> (changement mineur)<br>• ⭐ LES CLASSES : <b>basiques</b> (Lys, Arg, His) · <b>acides</b> (Asp, Glu) · <b>polaires</b> (Ser, Thr, Cys, Tyr, Asn, Gln) · <b>apolaires/hydrophobes</b> (Ala, Val, Leu, Ile, Met, Phe, Trp, Pro, Gly)<br><br><b>3. ⭐⭐ MUTATION FAUX-SENS (missense)</b><br>« <b>Changement de base induit un changement d'Aa, N'AYANT PAS LES MÊMES PROPRIÉTÉS donc la PROTÉINE EST NON FONCTIONNELLE</b> »<br>📖 <b>Exemple du cours : AAA (Lys, basique) → GAG (Gly, acide)</b><br>• ⚠️ <b>ATTENTION — IL Y A UNE ERREUR DANS LE COURS :</b> <b>GAG code en réalité pour l'ACIDE GLUTAMIQUE (Glu)</b>, pas pour la glycine (<b>GGN</b> = Gly). Le Pr ROCHD a écrit « Gly » mais <b>GAG = Glu</b>. ⚠️ <b>Si le QCM utilise l'exemple du cours, suis le cours (Gly) ; si c'est un vrai calcul de code génétique, GAG = Glu (acide).</b> Dans les DEUX cas la conclusion est la même : <b>protéine non fonctionnelle</b>.<br>• ⭐ <b>CONSEQUENCE MAJEURE : LA PROTÉINE EST NON FONCTIONNELLE</b><br>• ⚠️ Exemples classiques : <b>drépanocytose</b> (GAG→GTG : Glu→Val ; voir chapitre génie génétique du même cours) · <b>mutation F508del CFTR</b> (délétion de 3 pb = pas de décalage) · <b>syndrome de Marfan</b> (FBN1) · <b>ostéogenèse imparfaite</b> (COL1A1/2, Gly→Ser)<br><br><b>4. ⭐⭐ MUTATION DU CODON STOP</b> — ⚠️ <b>IL Y EN A DEUX SORTES, DANS LES DEUX SENS :</b><br>📖 Texte exact du cours :<br>« <b>Changement d'un codon Aa en codon stop =</b> » → <b>PROTÉINE TRONQUÉE</b> (⚠️ on appelle ça une mutation <b>NON-SENS</b> / nonsense)<br>« <b>Changement d'un codon stop en codon Aa =</b> » → <b>PROTÉINE ALLONGÉE</b> (⚠️ <b>readthrough</b> / mutation de <b>létalité synthétique</b>)<br>• <b>LES 3 CODONS STOP = UAA, UGA, UAG</b> ⭐ (à retenir) — ⚠️ mnémotechnique : <b>U Are Annoying, U Go Away, U Are Gone</b><br>• ⚠️ Une protéine tronquée est <b>QUASI TOUJOURS NON FONCTIONNELLE</b> et souvent <b>DÉGRADÉE</b> par le mécanisme du <b>NMD (Nonsense-Mediated Decay)</b><br>• ⚠️ <b>Le codon-stop prématuré (PTC)</b> → <b>maladies graves</b> : <b>mucoviscidose (G542X, W1282X)</b>, <b>myopathie de Duchenne</b>, <b>β-thalassémie</b> · <b>~11 % de toutes les maladies héréditaires</b><br>• ⚠️ <b>TRAITEMENT ÉMERGENT :</b> les <b>« readthrough drugs »</b> (<b>ataluren/PTC124, gentamicine, amlexanox</b>) font « lire » le codon stop pour produire une protéine complète ⭐<br><br><b>📋 AUTRES NOTIONS DU COURS (III-1) :</b><br>• <b>DÉFINITION :</b> « <b>modification IRRÉVERSIBLE de la SÉQUENCE d'un GÉNOME (ADN ou ARN)</b> »<br>• ⚠️ <b>LA PROBABILITÉ DE MUTATION = 10⁻⁹ à 10⁻¹⁰</b> ⭐ <b>CHIFFRE À RETENIR</b> (par base et par division)<br>• <b>CAUSES :</b> <b>spontanées lors de la réplication</b> · <b>agents mutagènes</b> — <b>radiations (UV, X, γ)</b> · <b>agents chimiques (pesticides)</b> · <b>modification du système de réparation</b> « qui cesse alors de corriger les erreurs »<br>• ⚠️ <b>MUTATION GERMINALE</b> : « peuvent être <b>TRANSMISES À LA DESCENDANCE</b> » — ⭐ <b>MUTATION SOMATIQUE</b> : <b>NON TRANSMISE</b><br>• ⚠️ <b>LA MUTATION PEUT AUSSI TOUCHER L'ARN</b> : « Elle est possible mais <b>MOINS IMPORTANTE car ne concerne qu'une PROTÉINE</b> » ⭐ (l'ARN est transitoire — la mutation disparaît avec lui)<br>• ⚠️ <b>LA MUTATION PEUT TOUCHER LES CHROMOSOMES</b> : « <b>Cas de la TRISOMIE</b> » (anomalie du NOMBRE, pas de la séquence)<br><br><b>📋 CONSÉQUENCES (III-1-2-3) :</b><br>• <b>AVANTAGES</b> : « <b>principe de l'ÉVOLUTION : individus portant la mutation sont MIEUX ADAPTÉS à leur environnement</b> »<br>• <b>MALADIES</b> :<br>&nbsp;&nbsp;– <b>ex 1 : ANÉMIE FALCIFORME</b> = « maladie génétique caractérisée par une <b>HÉMOGLOBINE ANORMALE</b> »<br>&nbsp;&nbsp;– <b>ex 2</b> : « Mutation de certains gènes peut participer à l'apparition de <b>TUMEUR (bénigne ou maligne)</b> »<br>• ⚠️ <b>Le cours dit aussi :</b> « Un défaut dans l'ADN peut engendrer des maladies « héréditaires », comme le <b>DIABÈTE</b>, l'<b>ALZHEIMER</b>, et bien d'autres »<br>• ⚠️ <b>« Beaucoup de CANCERS sont caractérisés par une INSTABILITÉ GÉNÉTIQUE »</b> — phrase d'introduction du chapitre III<br><br><b>📋 LES 20 ACIDES AMINÉS (liste du cours) + LE CODE GÉNÉTIQUE :</b><br>Le cours donne la <b>TABLE COMPLÈTE DU CODE GÉNÉTIQUE</b> ⭐ <b>APPRENDS-LA</b> (au minimum : AUG = Met/START ; UAA-UAG-UGA = STOP ; UUU/UUC = Phe ; GGN = Gly ; AAA/AAG = Lys ; GAG/GAA = Glu).<br><b>Ala, Arg, Leu, Lys, Asp, Asn, Cys, Glu, Gln, Gly, His, Ile, Met, Phe, Pro, Ser, Thr, Trp, Tyr, Val</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>III-1-3 — LES MÉCANISMES DE RÉPARATION DE L'ADN</b> : ⭐ décrire la réparation d'une mutation due aux UV (voie NER) selon le cours du Pr ROCHD","a":"<b>⭐⭐ LE SCHÉMA DU COURS EST À REPRODUIRE — C'EST UNE QUESTION D'EXAMEN PRESQUE CERTAINE</b><br><br>📖 <b>PRINCIPE GÉNÉRAL DU COURS :</b><br>« <b>La PLUPART des mutations sont corrigées par des ENZYMES DE RÉPARATION au cours de la réplication. Ces enzymes RECONNAISSENT LE BRIN NÉOFORMÉ.</b> »<br><br><b>⚠️ COMMENT RECONNAÎTRE LE BRIN NÉOFORMÉ ?</b><br>• ⭐ Chez les bactéries : par la <b>MÉTHYLATION</b> (l'ADN parental est méthylé par <b>Dam méthylase</b> sur les <b>GATC</b>, le brin néoformé ne l'est pas encore) → système <b>MutS/MutL/MutH</b><br>• Chez les eucaryotes : par les <b>coupures (nicks)</b> du brin néoformé (fragments d'Okazaki) et par l'interaction avec la <b>PCNA</b><br><br><b>🔴 LES 3 ÉTAPES GÉNÉRALES (texte du cours) :</b><br>❖ <b>Les ENDONUCLÉASES coupent l'ADN en AMONT et en AVAL de la mutation</b><br>❖ <b>L'ADN POLYMÉRASE comble la BRÈCHE selon le modèle du BRIN PARENTAL</b><br>❖ <b>Enfin, la LIGASE relie les 2 parties du brin néoformé</b><br><br><b>🔴 LE SCHÉMA DU COURS — RÉPARATION D'UNE MUTATION DUE AUX UV (NER) ⭐ :</b><br><br><b>UV → ADN LÉSÉ</b> ⚠️ (formation de <b>DIMÈRES DE THYMINE / CPD</b> — cyclobutane pyrimidine dimers — et de <b>6-4 photoproduits</b>)<br>↓<br><b>1. PROTÉINE DE RECONNAISSANCE</b> → <b>gène xpC sur CHR 3</b> ⭐ (XPC)<br>↓<br><b>2. PROTÉINE DE RECRUTEMENT DES « OUTILS » DE RÉPARATION</b> → <b>gène xpA sur CHR 9</b> ⭐ (XPA)<br>↓<br>« <b>RECONNAISSANCE DE LA ZONE LÉSÉE</b> »<br>↓<br><b>3. HÉLICASE (protéine)</b> → <b>gène xpB sur CHR 2</b> ⭐ (XPB/ERCC3) <b>ET</b> <b>gène xpD sur CHR 19</b> ⭐ (XPD/ERCC2)<br>↓<br>« <b>OUVERTURE DE LA DOUBLE HÉLICE</b> »<br>↓<br><b>4. NUCLÉASE (protéine)</b> → <b>gène xpF sur CHR 16</b> ⭐ (XPF/ERCC4) <b>ET</b> <b>gène xpG sur CHR 13</b> ⭐ (XPG/ERCC5)<br>↓<br>« <b>EXCISION DU DIMÈRE</b> »<br>↓<br><b>5.</b> « <b>MISE EN PLACE DES NUCLÉOTIDES MANQUANTS PAR LA POLYMÉRASE</b> »<br>↓<br><b>6.</b> « <b>RÉTABLISSEMENT DES LIAISONS PAR L'ADN LIGASE</b> »<br><br><b>🔴 LE TABLEAU À APPRENDRE PAR CŒUR — LES GÈNES XP ET LEURS CHROMOSOMES ⭐⭐ :</b><br>• <b>XPC</b> → <b>chr 3</b> → <b>reconnaissance</b><br>• <b>XPA</b> → <b>chr 9</b> → <b>recrutement</b><br>• <b>XPB</b> → <b>chr 2</b> → <b>hélicase</b><br>• <b>XPD</b> → <b>chr 19</b> → <b>hélicase</b><br>• <b>XPF</b> → <b>chr 16</b> → <b>nucléase</b><br>• <b>XPG</b> → <b>chr 13</b> → <b>nucléase</b><br>⚠️ Mnémotechnique : <b>3-9 (C-A) reconnaissance · 2-19 (B-D) hélicases · 16-13 (F-G) nucléases</b><br><br><b>⭐ LA MALADIE CORRESPONDANTE : LE XERODERMA PIGMENTOSUM (XP)</b><br>• Maladie <b>AUTOSOMIQUE RÉCESSIVE</b> · incidence <b>1/250 000</b> en Europe/Amérique, ⚠️ <b>beaucoup plus fréquente au MAGHREB et au JAPON</b> (consanguinité)<br>• ⭐ <b>DÉFICIT DE LA RÉPARATION PAR EXCISION DE NUCLÉOTIDES (NER — Nucleotide Excision Repair)</b><br>• ⚠️ <b>SIGNES CLINIQUES :</b> <b>photosensibilité extrême</b> → <b>coups de soleil après une exposition minimale</b> · <b>lentigines (taches de rousseur)</b> précoces · <b>xérose</b> · <b>kératoses actiniques</b> · ⚠️ <b>RISQUE DE CANCER CUTANÉ MULTIPLIÉ PAR 10 000</b> (carcinomes basocellulaires, spinocellulaires, mélanome malin) <b>AVANT L'ÂGE DE 10 ANS</b> · ⚠️ <b>atteinte OCULAIRE</b> (kératite, conjonctivite, cancers de la conjonctive)<br>• ⚠️ <b>~30 % ont des signes NEUROLOGIQUES</b> (microcéphalie, retard mental, surdité, ataxie, troubles de la déglutition) — <b>syndrome de De Sanctis-Cacchione</b> (la forme la plus grave)<br>• ⭐ <b>Risque estimé : 10 000 fois</b> plus de cancers cutanés · <b>2 000 fois</b> de tumeurs du SNC · <b>1 000 fois</b> de mélanome<br>• ⚠️ <b>TRAITEMENT : AUCUN TRAITEMENT CURATIF</b> → <b>PRÉVENTION TOTALE :</b> vêtements anti-UV, écran total SPF 50+, lunettes, <b>interdiction absolue du soleil</b> (vitres teintées, sorties nocturnes), <b>vitamine D à supplémenter</b> (risque de rachitisme), surveillance dermatologique tous les 3 mois<br>• ⚠️ <b>Variante XPV</b> : déficit en <b>ADN polymérase η</b> (translesion) — <b>NER normale</b> mais <b>hypermutabilité</b><br><br><b>📋 L'AUTRE RÉPARATION DU COURS — LA CORRECTION PENDANT LA RÉPLICATION (PROOFREADING) :</b><br>📖 « <b>L'erreur peut aussi être corrigée PENDANT la réplication.</b> »<br>• « <b>La correction se fait dans le sens 3' → 5' : l'EXONUCLÉASE dégrade la nouvelle extrémité 3' si l'APPARIEMENT n'est pas correct.</b> »<br>• « <b>L'ADNpol reprend son travail et insère le bon nucléotide.</b> »<br>• ⭐ « <b>On parle d'une FONCTION D'ÉDITION (« PROOFREADING »)</b> »<br>• ⚠️ <b>Activité EXONUCLÉASE 3'→5'</b> des ADN pol δ et ε (mais <b>PAS</b> de Pol α ni Pol β !) ⚠️ <b>Pol α n'a PAS de relecture → c'est pourquoi elle est remplacée par Pol δ/ε après l'amorçage</b><br>• ⚠️ <b>Efficacité :</b> erreur de réplication ~<b>10⁻⁵</b> → relecture ~<b>10⁻⁷</b> → système MMR post-réplicatif ~<b>10⁻⁹ à 10⁻¹⁰</b> ⭐ (ça correspond exactement au chiffre du cours !)<br><br><b>📋 LES 5 GRANDES VOIES DE RÉPARATION (à connaître en complément) :</b><br>1. ⭐ <b>NER (Nucleotide Excision Repair)</b> — <b>UV, adduits volumineux</b> — <b>XPA à XPG</b> — ⚠️ déficit = <b>Xeroderma pigmentosum</b>, <b>Cockayne</b> (CSA/CSB), <b>Trichothiodystrophie</b><br>2. ⭐ <b>BER (Base Excision Repair)</b> — <b>bases endommagées par oxydation, alkylation, désamination</b> — <b>ADN glycosylases → AP endonucléase → Pol β → Ligase III/XRCC1</b> ⚠️ déficit = <b>syndrome MUTYH</b> (polypose adénomateuse récessive)<br>3. ⭐ <b>MMR (Mismatch Repair)</b> — <b>mésappariements et boucles de la réplication</b> — <b>MSH2, MSH6, MLH1, PMS2</b> ⚠️ déficit = <b>SYNDROME DE LYNCH (HNPCC)</b> ⭐ → <b>cancer colorectal, endomètre</b> · se manifeste par une <b>INSTABILITÉ DES MICROSATELLITES (MSI)</b><br>4. ⭐ <b>DSB — Homologous Recombination (HR)</b> — <b>BRCA1, BRCA2, RAD51, PALB2</b> sans erreur · ⚠️ déficit = <b>cancers du sein/ovaire héréditaires (BRCA)</b>, <b>anémie de Fanconi</b><br>5. ⭐ <b>DSB — NHEJ (Non-Homologous End Joining)</b> — <b>Ku70/Ku80, DNA-PKcs, LIG4, XRCC4</b>, erreur-prone · ⚠️ déficit = <b>immunodéficience combinée sévère (SCID) radiosensible</b>, syndrome de LIG4<br>• ⚠️ <b>Dommage irréparé → APOPTOSE via p53 → ARRÊT en G1/S par p21</b> ⭐<br>• ⚠️ <b>SYNDROME D'ATAXIE-TÉLANGIECTASIE (ATM)</b> · <b>Syndrome de Bloom (BLM)</b> · <b>Werner (WRN)</b> · <b>Nijmegen (NBS1)</b> = autres déficits avec <b>instabilité chromosomique</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>IV — LA TRANSCRIPTION</b> : ⭐ quels sont les 3 étapes et les notions clés (brin matrice, promoteur, sens 5'→3') selon le Pr ROCHD ?","a":"<b>⭐ DÉFINITION DU COURS :</b><br>« <b>La TRANSCRIPTION est un processus biologique permettant la COPIE des régions dites CODANTES de l'ADN en molécules d'ARN. C'est la 1ʳᵉ ÉTAPE du mécanisme qui permet de passer de l'ADN à la protéine.</b> »<br><br><b>🔴 LES 3 ÉTAPES (IV-2) — texte exact du cours :</b><br>« <b>Le mécanisme général de la transcription pourra donc être divisé en 3 ÉTAPES DISTINCTES :</b><br><b>a. L'INITIATION</b> : reconnaissance du début de l'unité de transcription<br><b>b. L'ÉLONGATION</b> : polymérisation de la chaîne d'ARN<br><b>c. LA TERMINAISON</b> : reconnaissance de la région de terminaison »<br><br><b>1. ⭐ L'UNITÉ DE TRANSCRIPTION :</b><br>📖 « <b>Une unité de transcription (= GÈNE) s'étend TOUJOURS d'un SITE D'INITIATION de la transcription jusqu'à un SITE DE TERMINAISON de la transcription.</b> »<br>Schéma du cours : <b>5' — [site d'initiation] — GÈNE — [site de terminaison] — 3'</b><br><br><b>2. ⭐⭐ LES 2 BRINS — NOTIONS ESSENTIELLES :</b><br>📖 <b>TEXTE EXACT : « ATTENTION : UN SEUL des 2 brins d'ADN est transcrit = BRIN MATRICE = BRIN ANTISENS. Le brin matrice sera transcrit en ARN.</b> »<br>• <b>BRIN MATRICE / BRIN ANTISENS / BRIN TRANSCRIT</b> = celui qui est <b>LU</b> par l'ARN polymérase <br>&nbsp;&nbsp;→ ⚠️ L'ARN est la <b>COPIE COMPLÉMENTAIRE</b> du brin matrice<br>• <b>BRIN CODANT / BRIN SENS / BRIN NON TRANSCRIT</b> = l'autre brin<br>&nbsp;&nbsp;→ ⚠️ L'ARN est la <b>COPIE CONFORME</b> du brin codant, ⚠️ « <b>à l'exception de la THYMINE qui sera de l'URACILE</b> » ⭐<br>• ⚠️ <b>PIÈGE CLASSIQUE :</b> la séquence de l'ARN est <b>IDENTIQUE à celle du brin CODANT</b> (avec T→U), même si c'est l'<b>AUTRE</b> brin qui est lu !<br>• ⚠️ Le brin matrice est lu dans le sens <b>3'→5'</b> par l'ARN pol (donc l'ARN est synthétisé en <b>5'→3'</b>)<br>• ⚠️ Le choix du brin matrice <b>dépend du GÈNE</b> — sur un même chromosome, certains gènes sont transcrits sur un brin, d'autres sur l'autre<br><br><b>3. ⭐ LE SENS DE LA TRANSCRIPTION :</b><br>📖 « <b>La transcription se fait dans le sens 5' VERS 3' ce qui signifie qu'elle s'AGRANDIT en 3'.</b> »<br>• ⚠️ ⭐ <b>PAS de besoin d'AMORCE</b> — contrairement à l'ADN polymérase, l'<b>ARN polymérase peut INITIER une synthèse de novo</b> ⭐ (différence fondamentale avec la réplication)<br><br><b>4. ⭐⭐ IV-2-1 — L'INITIATION :</b><br>📖 « <b>L'ARN POLYMÉRASE est l'enzyme qui assure la transcription, il reconnaît et se fixe sur une région particulière de l'ADN = le SITE PROMOTEUR.</b> »<br>• ⚠️ <b>PROMOTEUR</b> = région régulatrice <b>EN AMONT (5')</b> du gène<br>• ⭐ Chez les eucaryotes : <b>TATA box</b> (séquence consensus <b>TATAAA</b>, située vers <b>−25 à −30 pb</b> du site d'initiation), <b>CAAT box (−75)</b>, <b>GC box</b>, <b>Inr (Initiator)</b>, <b>BRE</b>, <b>DPE</b><br>• ⚠️ L'initiation nécessite les <b>FACTEURS DE TRANSCRIPTION (FT / TF)</b> :<br>&nbsp;&nbsp;– <b>FT GÉNÉRAUX</b> : <b>TFIID</b> (contient la <b>TBP = TATA-Binding Protein</b> ⭐, + les <b>TAF</b>), <b>TFIIB, TFIIF, TFIIE, TFIIH</b> → forment le <b>COMPLEXE DE PRÉ-INITIATION</b> avec l'<b>ARN Pol II</b><br>&nbsp;&nbsp;– ⚠️ <b>TFIIH</b> contient une <b>ACTIVITÉ HÉLICASE (XPB, XPD)</b> ⭐ ⚠️ <b>CE SONT LES MÊMES GÈNES QUE LE XERODERMA PIGMENTOSUM !</b> → explique que les XP ont aussi des défauts de transcription (<b>le TFIIH sert à la NER ET à la transcription</b>) ⭐ c'est pourquoi les patients XP ont aussi des troubles neurologiques<br>&nbsp;&nbsp;– <b>FT SPÉCIFIQUES</b> : <b>enhancers (amplificateurs)</b> en amont/aval, <b>silencers</b>, <b>insulators</b><br>• ⚠️ <b>L'ARN Pol II</b> a un <b>DOMAIN CTD</b> (C-terminal) avec des <b>répétitions YSPTSPS</b> dont la <b>phosphorylation</b> (par <b>TFIIH/CDK7</b> sur Ser5) permet la sortie du promoteur et le recrutement de la machinerie de maturation<br>• ⚠️ L'<b>ARN Pol II</b> est ⭐ <b>TRÈS SENSIBLE À L'α-AMANITINE</b> (toxine de l'<i>Amanita phalloides</i> — <b>amphétamine du champignon</b>) → <b>inhibe la synthèse des ARNm → nécrose hépatique</b><br><br><b>5. ⭐ IV-2-2 — L'ÉLONGATION :</b><br>📖 « <b>Lors de la transcription, les 2 brins d'ADN se SÉPARENT devant l'ARN pol permettant sa progression. Une fois l'ARN pol passé, les 2 brins d'ADN SE REFERMENT par RÉTABLISSEMENT DES LIAISONS HYDROGÈNES.</b> »<br>• ⭐ <b>LES 2 CHIFFRES DU COURS À RETENIR ABSOLUMENT :</b><br>&nbsp;&nbsp;⚠️ « <b>La BOUCLE DE TRANSCRIPTION comporte environ 17 BASES OUVERTES</b> »<br>&nbsp;&nbsp;⚠️ « <b>La VITESSE DE POLYMÉRISATION est d'environ 30 à 80 NUCLÉOTIDES PAR SECONDE</b> »<br>• ⚠️ <b>Comparaison :</b> réplication ~<b>50 nt/s</b> eucaryote · traduction ~<b>2 à 20 aa/s</b><br>• ⚠️ <b>Topologie :</b> surenroulement <b>positif</b> devant la polymérase, <b>négatif</b> derrière → résolu par les <b>topoisomérases I et II</b><br>• ⚠️ <b>La transcription et la traduction sont DÉCOUPLÉES chez les eucaryotes</b> (noyau vs cytoplasme) mais <b>COUPLÉES chez les procaryotes</b> ⭐<br><br><b>6. ⭐ IV-2-3 — LA TERMINAISON :</b><br>📖 « <b>La transcription d'un gène s'achève quand l'ARN pol arrive à la FIN DE L'UNITÉ DE TRANSCRIPTION. L'ARN pol se DÉCROCHE de la matrice et la boucle de transcription se REFERME. Cette terminaison de transcription se produit en une région appelée « SITE DE TERMINAISON ».</b> »<br>• ⚠️ <b>MÉCANISME DÉCRIT DANS LE COURS :</b> « <b>La transcription de la RÉGION DE TERMINAISON conduit à un HYBRIDE ADN/ARN INSTABLE. L'ARN se DÉCROCHE et la boucle de transcription se REFERME.</b> »<br>• ⭐ <b>LE SIGNAL CLÉ :</b> « <b>La terminaison est assurée par des signaux spécifiques dont le SIGNAL DE POLYADÉNYLATION AAUAAA.</b> » ⭐ <b>À RETENIR : la séquence AAUAAA</b><br>• ⚠️ « <b>L'ARN pol CONTINUE sa transcription un peu APRÈS ce motif puis est LIBÉRÉE sous l'action de divers facteurs.</b> »<br>• ⚠️ <b>Deux modèles eucaryotes :</b> le modèle <b>« torpille » (torpedo)</b> — une exonucléase 5'→3' (<b>XRN2</b>) dégrade l'ARN en aval du site de clivage et « rattrape » la polymérase — et le modèle <b>« allostérique »</b><br>• ⚠️ <b>Chez les procaryotes</b>, 2 mécanismes : <b>terminaison Rho-indépendante</b> (tige-boucle riche en G-C suivie d'une série de U) et <b>Rho-dépendante</b> (protéine Rho, une hélicase ARN)<br>• 🔴 <b>PHRASE CAPITALE DU COURS :</b> « <b>La transcription proprement dite est terminée MAIS L'ARN OBTENU N'EST PAS FONCTIONNEL pour autant et doit subir 3 ÉTAPES DE MATURATION.</b> » ⭐<br>• ⚠️ <b>L'ARN avant maturation = TRANSCRIT PRIMAIRE = PRÉ-ARNm = hnARN (hétérogène nucléaire)</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>IV-3 — LA MATURATION DE L'ARNm</b> : ⭐⭐ quelles sont les <b>3 ÉTAPES</b> ? (question certaine à l'examen)","a":"<b>⭐⭐⭐ LA QUESTION LA PLUS CERTAINE DE TOUT L'EXAMEN DE BIOMOL</b><br><br>📖 <b>TEXTE DU COURS :</b><br>« <b>La maturation post-transcriptionnelle a lieu au niveau du NOYAU. En effet, l'ADN chez les EUCARYOTES possède des séquences CODANTES (EXONS) et des séquences NON CODANTES (INTRONS). Seuls les EXONS participent à la synthèse des protéines.</b> »<br>« <b>LA MATURATION SE DÉROULE EN 3 ÉTAPES</b> » ⭐ <b>(le nombre 3 est tombable)</b><br><br><b>🔴 ÉTAPE 1 — ADDITION D'UNE QUEUE POLY-A (en 3')</b><br>📖 « <b>L'ARN est CLIVÉ au niveau du SIGNAL DE POLYADÉNYLATION et une POLYMÉRASE SPÉCIFIQUE (la POLY-A POLYMÉRASE) ajoute de nombreux RÉSIDUS ADÉNINE (200 CHEZ LES EUCARYOTES) : c'est la QUEUE POLY-A, ESSENTIELLE À LA STABILITÉ DE L'ARN.</b> »<br>• ⚠️ <b>CHIFFRES À RETENIR : 200 RÉSIDUS ADÉNYLATES CHEZ LES EUCARYOTES</b><br>• ⭐ <b>ATTENTION — POINT SOULIGNÉ PAR LE COURS :</b> « <b>Il est à noter que cette partie de l'ARN N'EST PAS CODÉE dans l'ADN sous forme de POLY-T.</b> » ⚠️ C'est une <b>ADDITION POST-TRANSCRIPTIONNELLE</b><br>• ⚠️ <b>Signal de clivage</b> : la séquence <b>AAUAAA</b> (en aval du codon stop), + une séquence riche en <b>GU/U</b> en aval, clivage <b>10-30 nt</b> en aval de AAUAAA<br>• ⚠️ <b>RÔLES :</b> <b>STABILITÉ</b> (protection contre les exonucléases 3'→5'), <b>EXPORT NUCLÉAIRE</b>, <b>efficacité de la TRADUCTION</b> (synergie avec la coiffe via <b>eIF4G/PABP</b> → ARNm circularisé)<br>• ⚠️ <b>Plus la queue est courte, plus l'ARNm est INSTABLE</b> → la déadénylation est la 1ʳᵉ étape de la dégradation<br>• ⚠️ <b>POLYADÉNYLATION ALTERNATIVE</b> : plusieurs sites de polyadénylation → ARNm de longueurs différentes<br>• ⚠️ <b>Les ARN d'histones</b> sont une exception : <b>PAS de queue polyA</b>, mais une structure en <b>tige-boucle 3'</b><br><br><b>🔴 ÉTAPE 2 — ADDITION D'UNE COIFFE (en 5')</b><br>📖 <b>TEXTE EXACT :</b> « <b>À l'autre extrémité 5', l'addition d'une COIFFE ou CAP MÉTHYLGUANOSINE est NÉCESSAIRE POUR LA RECONNAISSANCE PAR LES RIBOSOMES lors de l'étape de TRADUCTION.</b> »<br>• ⚠️ <b>Composition chimique :</b> <b>7-MÉTHYLGUANOSINE</b> liée par une liaison <b>5'-5' TRIPHOSPHATE</b> inhabituelle ⭐ (liaison <b>5'→5'</b>, pas 5'→3')<br>• ⚠️ <b>Formule du résumé du cours :</b> <b>CH₃-G-ppp</b> ⭐<br>• ⚠️ Ajoutée <b>TRÈS TÔT</b> — dès que le transcrit atteint <b>~20-25 nucléotides</b>, avant même la fin de la transcription<br>• ⚠️ <b>3 enzymes :</b> <b>RNA triphosphatase</b> → <b>guanylyltransférase</b> → <b>guanine-N7-méthyltransférase</b> (avec la <b>SAM</b> comme donneur de méthyle)<br>• ⚠️ <b>RÔLES :</b> <b>RECONNAISSANCE PAR LE RIBOSOME</b> (fixation d'<b>eIF4E</b>, étape limitante de l'initiation) · <b>protection</b> contre les <b>exonucléases 5'→3'</b> · <b>export nucléaire</b> (complexe <b>CBC</b>) · <b>épissage du 1ᵉʳ intron</b><br>• ⚠️ <b>Application médicale :</b> les <b>ARNm VACCINAUX (anti-COVID Pfizer/Moderna)</b> portent une <b>coiffe modifiée (m¹Ψ, « cap1 »)</b> et une <b>queue polyA optimisée</b> — ⭐ <b>EXACTEMENT les 2 premières étapes de maturation du cours !</b><br><br><b>🔴 ÉTAPE 3 — EXCISION-ÉPISSAGE (splicing)</b><br>📖 <b>TEXTE EXACT :</b> « <b>Il s'agit d'une EXCISION des INTRONS et RÉUNION (= ÉPISSAGE) des EXONS.</b> »<br>• ⭐ <b>PHRASE SUPPLÉMENTAIRE DU COURS :</b> « <b>L'ÉPISSAGE permet en outre d'obtenir DIFFÉRENTES PROTÉINES à partir d'un MÊME GÈNE en SÉLECTIONNANT QUELS EXONS SERONT CONSERVÉS : c'est l'ÉPISSAGE ALTERNATIF.</b> » ⭐⭐<br>• ⚠️ <b>Enzymes citées dans le schéma du cours :</b> <b>ENDONUCLÉASE et LIGASE</b><br>• ⚠️ <b>En réalité</b>, c'est le <b>SPLICEOSOME</b> ⭐ : les <b>snRNP U1, U2, U4, U5, U6</b> (les <b>snARN</b> du chapitre I !) + ~<b>200 protéines</b>. ⚠️ <b>L'U1</b> reconnaît le site <b>5' GU</b>, l'<b>U2AF/U2</b> reconnaît le <b>point de branchement A</b> et le <b>3' AG</b><br>• ⭐ <b>RÈGLE GT-AG (GU-AG sur l'ARN) :</b> <b>presque TOUS les introns commencent par GU et finissent par AG</b> ⭐<br>• ⚠️ <b>Mécanisme :</b> <b>2 réactions de TRANS-ESTÉRIFICATION</b> — (1) l'<b>OH en 2' de l'A du point de branchement</b> attaque le site 5' d'épissage → forme une <b>structure en LARIAT (lasso)</b> ⭐ ; (2) l'<b>OH 3' de l'exon amont</b> attaque le site 3' → les 2 exons sont liés et l'intron est libéré en lariat ⚠️ <b>AUCUNE ATP nécessaire pour la chimie elle-même</b> (l'ATP sert à l'assemblage/remodelage du spliceosome par les <b>RNA hélicases</b>)<br>• ⚠️ <b>ÉPISSAGE ALTERNATIF = LA CLÉ DE LA COMPLEXITÉ HUMAINE</b> : <b>~20 000 gènes</b> mais <b>&gt; 200 000 protéines</b> · ⭐ <b>~95 % des gènes humains à multi-exons subissent un épissage alternatif</b><br>• ⚠️ <b>Types :</b> exon <b>cassette</b> (le plus fréquent), exons mutuellement exclusifs, site 5' ou 3' alternatif, intron retenu, promoteur alternatif, polyadénylation alternative<br>• ⚠️ <b>Régulation :</b> protéines <b>SR</b> (activatrices, se lient aux <b>ESE</b>) et <b>hnRNP</b> (répresseurs, se lient aux <b>ESS</b>)<br><br><b>📋 LE RÉSUMÉ DU COURS (à apprendre tel quel) :</b><br><b>1. QUEUE POLY-A en 3' :</b> AAAAAAAAAAAAAAAAAA<br><b>2. COIFFE en 5' :</b> CH₃-G-ppp<br><b>3. EXCISION-ÉPISSAGE :</b> exon-intron-exon-intron-exon → exon-exon-exon<br><br><b>⚠️ REMARQUE DU COURS :</b> « <b>en fait, la MATURATION DU TRANSCRIT PRIMAIRE A LIEU EN MÊME TEMPS QUE LA TRANSCRIPTION</b> » ⭐ (maturation <b>CO-TRANSCRIPTIONNELLE</b> — l'ARN pol II porte la machinerie de maturation sur son domaine CTD)<br><br><b>📋 PATHOLOGIES DE L'ÉPISSAGE ⚠️ (15 à 50 % des maladies génétiques impliquent une anomalie d'épissage) :</b><br>• <b>β-thalassémie</b> (mutations créant un site d'épissage cryptique) · <b>Atrophie musculaire spinale (SMA)</b> — délétion de <b>SMN1</b>, sauvée par le gène paralogue <b>SMN2</b> dont un épissage alternatif saute l'exon 7 → ⭐ <b>traitement : l'oligonucléotide antisens NUSINERSEN (Spinraza)</b> qui force l'inclusion de l'exon 7 ⭐ <b>EXEMPLE MAGISTRAL D'ÉPISSAGE ALTERNATIF EN THÉRAPIE</b><br>• <b>Dystrophie myotonique de Steinert</b> (expansion CTG sur <b>DMPK</b> → séquestration de <b>MBNL1</b>) · <b>Progéria (Hutchinson-Gilford)</b> (LMNA, épissage cryptique → progérine) · <b>Cancer</b> (isoformes de <b>BCL-X</b> : BCL-XS pro-apoptotique vs BCL-XL anti-apoptotique)<br>• ⭐ <b>MÉDECINE DENTAIRE :</b> <b>Dentinogenèse imparfaite et amélogenèse imparfaite</b> — ⚠️ les gènes <b>AMELX, DSPP, ENAM</b> ont un <b>épissage alternatif important</b> (ex. l'<b>amélogénine</b> a plusieurs isoformes d'épissage) ⭐ <b>PERTINENT POUR LE MODULE</b><br><br><b>📋 ARNm MATURE — LA STRUCTURE FINALE :</b><br><b>5' [COIFFE m⁷G] [5'UTR] [ORF : codon START AUG … codons … codon STOP] [3'UTR] [queue polyA ~200 A] 3'</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>V — LA TRADUCTION</b> : ⭐ quelles sont les 3 étapes, où a-t-elle lieu, et qu'est-ce qui est nécessaire selon le Pr ROCHD ?","a":"<b>⭐ DÉFINITION DU COURS :</b><br>« <b>La TRADUCTION est l'INTERPRÉTATION des CODONS de l'ARNm en ACIDES AMINÉS (Aa). Le CODE GÉNÉTIQUE est le système de CORRESPONDANCE permettant à l'ARN d'être TRADUIT EN PROTÉINE.</b> »<br><br><b>🔴 LE CHIFFRE DE BASE : ⭐ « CODON = GROUPE DE 3 NUCLÉOTIDES »</b><br>• <b>4³ = 64 CODONS</b> · dont <b>61 codons-sens</b> (pour 20 acides aminés) et <b>3 CODONS STOP</b> (<b>UAA, UAG, UGA</b>) ⭐<br>• ⚠️ Le code est <b>DÉGÉNÉRÉ (redondant)</b> : plusieurs codons pour un même Aa · <b>NON AMBIGU</b> : 1 codon = 1 seul Aa · <b>SANS PONCTUATION</b> · <b>QUASI UNIVERSEL</b> ⚠️ (exception : ADN mitochondrial, quelques protozoaires)<br>• ⚠️ <b>Le cadre de lecture (ORF)</b> est fixé par le <b>1ᵉʳ codon AUG</b> (= codon START)<br><br><b>🔴 OÙ ET AVEC QUOI (V-2) :</b><br>📖 <b>TEXTE EXACT :</b> « <b>La traduction s'effectue dans le CYTOPLASME, elle nécessite des Aa qui sont polymérisés selon l'ordre donné par les CODONS de l'ARNm. Elle a besoin d'ÉNERGIE, de RIBOSOMES, d'ARNt, d'ENZYMES et de l'ARNm.</b> »<br><br>⚠️ <b>LES 5 COMPOSANTS NÉCESSAIRES (énumération du cours) :</b><br>1. ⭐ <b>ÉNERGIE</b> — ⚠️ <b>la traduction consomme ~4 équivalents ATP par acide aminé</b> : <b>2 ATP</b> pour charger l'ARNt (aminoacyl-ARNt synthétase → ATP→AMP, donc 2 liaisons riches) + <b>2 GTP</b> (un pour l'aminoacyl-ARNt : <b>eEF1A</b>, un pour la translocation : <b>eEF2</b>) ⭐<br>2. ⭐ <b>RIBOSOMES</b><br>3. <b>ARNt</b><br>4. <b>ENZYMES</b> — ⭐ les <b>AMINOACYL-ARNt SYNTHÉTASES</b> (20 enzymes) et la <b>PEPTIDYL-TRANSFÉRASE</b> (qui est en réalité un <b>RIBOZYME = l'ARN 28S</b> ⭐)<br>5. ⭐ <b>L'ARNm</b><br><br><b>📋 LE RIBOSOME :</b><br>📖 « <b>Le ribosome va se DISLOQUER en ses 2 SOUS-UNITÉS (60S et 40S) et pourra faire une autre synthèse sur un autre ARNm.</b> »<br>• ⚠️ <b>RIBOSOME EUCARYOTE = 80S</b> = <b>60S</b> (28S + 5,8S + 5S + ~50 protéines) + <b>40S</b> (18S + ~33 protéines)<br>• ⚠️ <b>RIBOSOME PROCARYOTE = 70S</b> = <b>50S</b> (23S + 5S) + <b>30S</b> (16S) → ⭐ <b>CIBLE DES ANTIBIOTIQUES</b> : aminosides/ <b>streptomycine, gentamicine</b> (30S), <b>tétracyclines</b> (30S), <b>macrolides/érythromycine</b> (50S), <b>chloramphénicol</b> (50S), <b>clindamycine, linézolide</b> ⚠️ <b>DIFFÉRENCE CLINIQUE MAJEURE : nos ribosomes 80S sont épargnés</b> ⭐ <b>À CONNAÎTRE EN MÉDECINE DENTAIRE (prescriptions !)</b><br>• ⚠️ <b>3 SITES du ribosome :</b> <b>A (aminoacyl)</b> = arrivée de l'ARNt · <b>P (peptidyl)</b> = ARNt portant la chaîne en cours · <b>E (exit)</b> = sortie de l'ARNt déchargé ⭐<br>• ⚠️ <b>Le RER (réticulum endoplasmique rugueux)</b> porte les ribosomes → les protéines <b>sécrétées/membraniaires</b> y sont traduites ; les protéines <b>cytosoliques</b> sont traduites sur des <b>ribosomes libres</b> ou des <b>polysomes</b><br><br><b>🔴 V-2-1 — L'INITIATION :</b><br>📖 « <b>Une fois que le brin d'ARNm a atteint le CYTOPLASME, il se fixe à un RIBOSOME, qui va assembler une séquence d'Aa selon les « INSTRUCTIONS » du code génétique.</b> »<br>• ⭐ <b>LE CODON AUG = CODON-INITIATEUR</b> : « <b>Le codon AUG, appelé CODON-INITIATEUR, va permettre de COMMENCER la traduction, comme son nom l'indique, en formant l'AA MÉTHIONINE, QUI SE DÉTACHERA PLUS TARD de la chaîne polypeptidique.</b> » ⭐ <b>(point souvent tombable : la Met initiale est éliminée après la traduction)</b><br>• ⚠️ Chez les eucaryotes : ARNt initiateur spécial = <b>Met-ARNt<sub>i</sub><sup>Met</sup></b> (distinct de l'ARNt élongateur) · chez les procaryotes : <b>fMet-ARNt<sup>fMet</sup></b> (formylméthionine)<br>• ⚠️ <b>Facteurs d'initiation eucaryotes</b> : <b>eIF4E (coiffe), eIF4G (échafaudage), eIF4A (hélicase) = complexe eIF4F · eIF3 · eIF2-GTP-Met-ARNt<sub>i</sub> (le « complexe ternaire »)</b> · <b>40S → 48S → 80S</b><br>• ⭐ <b>RÉGULATION MAJEURE :</b> la <b>phosphorylation d'eIF2α</b> bloque la traduction (voie du <b>stress intégré ISR</b>) ⭐<br>• ⚠️ <b>Chez l'eucaryote, l'initiation se fait par</b> <b>SCANNING</b> : la 40S se fixe sur la coiffe et « scanne » jusqu'au 1ᵉʳ <b>AUG</b> dans un bon contexte (<b>séquence Kozak : GCCRCCAUGG</b>) ⭐ · ⚠️ chez le procaryote, c'est la séquence <b>Shine-Dalgarno</b> qui positionne le ribosome<br><br><b>🔴 V-2-2 — L'ÉLONGATION :</b><br>📖 « <b>Le ribosome va PARCOURIR le brin d'ARNm CODON PAR CODON (= TRANSLOCATION) et va par l'intermédiaire d'un ARNt ajouter un Aa à la protéine en cours de fabrication selon le CODON LU.</b> »<br>• ⭐ <b>3 TEMPS PAR ACIDE AMINÉ :</b><br>&nbsp;&nbsp;<b>1. RECONNAISSANCE / DÉCODAGE</b> : l'<b>aminoacyl-ARNt</b> (porté par <b>eEF1A-GTP</b>) entre dans le site <b>A</b> et s'apparie à l'<b>ANTICODON</b><br>&nbsp;&nbsp;<b>2. FORMATION DE LA LIAISON PEPTIDIQUE</b> ⭐ : la <b>PEPTIDYL-TRANSFÉRASE</b> transfère la chaîne en cours (sur l'ARNt en <b>P</b>) sur l'Aa de l'ARNt en <b>A</b> → <b>liaison peptidique</b>. ⚠️ <b>C'EST UN RIBOZYME = l'ARN 28S qui catalyse</b> ⭐ (preuve de l'« <b>ARN world</b> »)<br>&nbsp;&nbsp;<b>3. TRANSLOCATION</b> : <b>eEF2-GTP</b> fait avancer le ribosome d'<b>exactement 3 nucléotides = 1 codon</b> → l'ARNt passe A→P→E ⭐<br>• ⚠️ <b>SENS</b> : l'ARNm est lu <b>5'→3'</b> ; la protéine est synthétisée de l'extrémité <b>N-terminale → C-terminale</b> ⭐<br>• ⚠️ <b>Vitesse :</b> ~<b>2 à 20 acides aminés/seconde</b> (plus rapide chez les procaryotes)<br><br><b>🔴 V-2-3 — LA TERMINAISON :</b><br>📖 « <b>Une fois le CODON STOP atteint (UAA, UGA ou UAG), la protéine est COMPLÈTE : le ribosome se DÉTACHE de la protéine et du brin d'ARNm, et la protéine est LIBÉRÉE dans l'organisme.</b> »<br>• ⭐ <b>LES 3 CODONS STOP : UAA, UGA, UAG</b><br>• ⚠️ ⭐ <b>AUCUN ARNt ne reconnaît les codons stop</b> — ce sont des <b>FACTEURS DE TERMINAISON PROTÉIQUES</b> (= <b>eRF1</b> qui reconnaît les 3 codons stop, + <b>eRF3-GTP</b>) qui se lient au site A et <b>hydrolysent</b> la chaîne ⭐<br>• 📖 « <b>Le ribosome va se DISLOQUER en ses 2 sous-unités (60S et 40S)</b> »<br><br><b>⭐ LE POINT « POLYSOME » DU COURS :</b><br>📖 « <b>Le même filament d'ARNm peut servir à la fabrication SIMULTANÉE de plusieurs protéines, lorsque PLUSIEURS RIBOSOMES s'en chargent. Avant d'être détruit, cet ARNm participe, en effet, à la fabrication de 10 à 20 PROTÉINES.</b> »<br>• ⚠️ <b>CHIFFRE À RETENIR : 10 à 20 protéines par ARNm</b> ⭐<br>• <b>POLYSOME / POLYRIBOSOME</b> = 1 ARNm + plusieurs ribosomes (jusqu'à <b>1 ribosome tous les 80 nucléotides</b>)<br>• ⚠️ <b>Chez les eucaryotes</b>, l'ARNm circularisé (coiffe-PABP-eIF4G) permet le <b>« recyclage des ribosomes »</b> → très efficace ⭐<br><br>📖 « <b>La protéine ainsi synthétisée SOIT RESTE À L'INTÉRIEUR DE LA CELLULE, SOIT LA QUITTE pour aller dans le système sanguin.</b> »<br><br><b>📋 LE RÉSUMÉ DU COURS (V-2) — les 3 étapes :</b><br><b>1. L'INITIATION</b> qui correspond à la <b>formation du COMPLEXE D'INITIATION</b><br><b>2. L'ÉLONGATION</b> qui permet d'<b>accrocher de nouveaux Aa</b> à la chaîne peptidique en cours de synthèse<br><b>3. LA TERMINAISON</b> qui conduit à la <b>libération de la chaîne peptidique</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>V-3 — LES MODIFICATIONS POST-TRADUCTIONNELLES</b> : lesquelles selon le cours du Pr ROCHD ?","a":"<b>⭐ DÉFINITION DU COURS :</b><br>« <b>Avant d'être OPÉRATIONNELLE, une protéine subit souvent des MODIFICATIONS POST-TRADUCTIONNELLES.</b> »<br><br><b>🔴 1. LE PLIEMENT (CONFORMATION) — LA 1ʳᵉ ÉTAPE OBLIGATOIRE</b><br>📖 « <b>Elle doit tout d'abord ADOPTER LA CONFORMATION DANS LAQUELLE ELLE EST ACTIVE. Pour cela, elle est aidée par des molécules appelées CHAPERONNES.</b> » ⭐<br>• ⚠️ <b>CHAPERONNES</b> = protéines qui aident au pliage sans faire partie de la protéine finale<br>&nbsp;&nbsp;– <b>Hsp70</b> (et son co-chaperon <b>Hsp40</b>) : se lie aux segments hydrophobes exposés, <b>ATP-dépendant</b><br>&nbsp;&nbsp;– <b>Hsp60 / chaperonines</b> (GroEL/GroES chez les bactéries, <b>TRiC</b> chez les eucaryotes) : <b>cage</b> où la protéine s'isole pour se plier ⭐<br>&nbsp;&nbsp;– <b>Hsp90, Hsp100</b>, les <b>PPIases</b> (peptidyl-prolyl isomérases) et la <b>PDI</b> (protéine disulfure isomérase)<br>• ⚠️ <b>Les chaperonnes sont des</b> <b>HSP = Heat Shock Proteins</b> — leur synthèse augmente lors du <b>stress cellulaire</b> (choc thermique, oxydatif) via le facteur de transcription <b>HSF1</b> ⭐<br>• ⭐ <b>RÈGLE D'ANFINSEN</b> : la conformation native = le minimum d'énergie libre, déterminée par la séquence en acides aminés<br><br><b>🔴 2. LES LIAISONS QUI MAINTIENNENT LA CONFORMATION</b><br>📖 « <b>Il peut y avoir FORMATION DE PONTS DISULFURE et ÉTABLISSEMENT DE LIAISONS HYDROGÈNE pour maintenir cette conformation.</b> »<br>• ⭐ <b>PONTS DISULFURE (-S-S-)</b> : entre les groupements <b>-SH de deux CYSTÉINES</b> ⭐ (oxydation) — ⚠️ ⭐ <b>formés dans le RÉTICULUM ENDOPLASMIQUE</b> (milieu oxydant), <b>PAS dans le cytosol</b> (milieu réducteur) — catalysés par la <b>PDI</b><br>• <b>LIAISONS HYDROGÈNE</b> → structures secondaires <b>α-hélice</b> et <b>feuillet β</b><br>• ⚠️ + <b>interactions hydrophobes</b>, <b>liaisons ioniques (ponts salins)</b>, <b>interactions de Van der Waals</b><br><br><b>🔴 3. L'AJOUT DE MOLÉCULES NON PROTÉIQUES</b><br>📖 « <b>D'autre part, il peut y avoir AJOUT DE MOLÉCULES NON PROTÉIQUES, comme des LIPIDES, des GLUCIDES ou des GROUPEMENTS PHOSPHATE, ainsi que de PETITS PEPTIDES.</b> »<br><br>⚠️ <b>LES 4 AJOUTS CITÉS DANS LE COURS (à retenir) :</b><br><br><b>a) LIPIDES → LIPOPROTÉINES</b><br>• ⚠️ <b>MYRISTOYLATION</b> (acide myristique en C14 sur une <b>Gly N-terminale</b>, liaison amide, irréversible)<br>• ⚠️ <b>PALMITOYLATION</b> (acide palmitique en C16 sur une <b>Cys</b>, liaison thioester, <b>RÉVERSIBLE</b> ⭐ — seul moyen d'aller-retour membranaire, ex. <b>Ras, Src</b>)<br>• ⚠️ <b>PRÉNYLATION</b> (<b>farnésyl</b> C15 ou <b>géranylgéranyl</b> C20 sur une <b>Cys</b> de la séquence <b>CAAX</b> à l'extrémité C-terminale) ⭐ — ⚠️ <b>cible des INHIBITEURS DE LA FARNÉSYL-TRANSFÉRASE (FTI)</b> développés contre <b>Ras</b> (ex. <b>lonafarnib</b>, utilisé dans la <b>progéria</b> !)<br>• ⚠️ <b>Ancrage GPI (glycosylphosphatidylinositol)</b> — ⭐ <b>mutation de PIGA → HÉMOGLOBINURIE PAROXYSTIQUE NOCTURNE (HPN)</b> ⭐<br><br><b>b) GLUCIDES → GLYCOPROTÉINES = GLYCOSYLATION</b> ⭐<br>• ⚠️ <b>N-glycosylation</b> : sur l'<b>ASPARAGINE (Asn)</b> de la séquence <b>Asn-X-Ser/Thr</b> — commence dans le <b>RE</b> (transfert d'un précurseur <b>Glc₃Man₉GlcNAc₂</b> depuis le <b>dolichol</b> par l'<b>oligosaccharyltransférase</b>) et se poursuit dans le <b>GOLGI</b> ⭐<br>• ⚠️ <b>O-glycosylation</b> : sur la <b>SÉRINE (Ser)</b> ou la <b>THRÉONINE (Thr)</b> — ⭐ <b>uniquement dans le GOLGI</b> (ajout successif de sucres par des <b>glycosyltransférases</b>) ⭐<br>• ⚠️ <b>RÔLES :</b> repliement, reconnaissance cellulaire, demi-vie, adressage (ex. <b>mannose-6-phosphate</b> → adressage aux LYSOSOMES ⭐)<br>• ⚠️ <b>MALADIES CONGÉNITALES DE LA GLYCOSYLATION (CDG)</b> — déficit en <b>phosphomannomutase 2 (PMM2)</b> = CDG-Ia, la plus fréquente<br>• ⭐ <b>PERTINENT EN DENTAIRE :</b> les <b>protéines de la matrice de l'émail (amélogénines, énamélines)</b> et la <b>DSPP</b> (sialophosphoprotéine dentinaire) sont <b>fortement GLYCOSYLÉES et PHOSPHORYLÉES</b> → ⚠️ <b>essentielles à la minéralisation</b> ⭐<br><br><b>c) GROUPEMENTS PHOSPHATE → PHOSPHORYLATION</b> ⭐⭐<br>• ⚠️ Sur les résidus <b>SÉRINE (Ser), THRÉONINE (Thr)</b> (→ <b>Ser/Thr kinases</b>) ou <b>TYROSINE (Tyr)</b> (→ <b>Tyr kinases</b>) — ⚠️ <b>~90 % Ser, ~10 % Thr, &lt;1 % Tyr</b><br>• <b>Enzymes</b> : <b>KINASES</b> (ajoutent, avec l'ATP) ⇌ <b>PHOSPHATASES</b> (enlèvent) ⭐ <b>INTERRUPTEUR MOLÉCULAIRE RÉVERSIBLE</b><br>• ⚠️ <b>Exemples</b> : la <b>phosphorylation de l'histone H3</b> (mitose), de la <b>périlipine</b> (lipolyse), de la <b>glycogène phosphorylase</b>, des <b>IRS</b> (signalisation de l'insuline)<br>• ⭐ <b>MÉDECINE DENTAIRE :</b> la <b>DSPP et la DMP1</b> (dentine matrix protein 1) sont <b>hyperphosphorylées</b> → ⚠️ <b>elles se lient au CALCIUM et initient la MINÉRALISATION de la DENTINE</b> ⭐⭐ <b>EXCELLENT EXEMPLE À CITER À L'EXAMEN</b><br><br><b>d) PETITS PEPTIDES</b><br>• ⚠️ <b>Ubiquitination</b> : ajout de l'<b>UBIQUITINE (76 aa)</b> sur une <b>Lys</b> → <b>K48</b> = dégradation par le <b>protéasome 26S</b> ⭐ ; <b>K63</b> = signalisation/réparation de l'ADN ⚠️ <b>Enzymes E1 (activatrice) — E2 (conjuguée) — E3 (ligase, donne la spécificité)</b> · ⭐ <b>découverte = prix Nobel de chimie 2004 (Ciechanover, Hershko, Rose)</b><br>• ⚠️ <b>SUMOylation</b> (SUMO = Small Ubiquitin-like Modifier) — transport nucléaire, transcription<br>• ⚠️ <b>NEDDylation</b> — active les <b>E3 ubiquitine ligases Cullin</b> ⭐ (cible du <b>pevonedistat</b>)<br>• ⚠️ <b>Autres :</b> <b>acétylation</b> (sur Lys — ⚠️ <b>des histones</b> = épigénétique !), <b>méthylation</b>, <b>hydroxylation</b> (de la Pro et Lys dans le <b>COLLAGÈNE</b> — ⭐ <b>VITAMINE C DÉPENDANTE</b> ⭐ ⭐ <b>→ SCORBUT</b> ⭐ <b>ULTRA PERTINENT EN DENTAIRE : défaut de synthèse du collagène → déchaussement dentaire, gingivorragies</b>), <b>carboxylation</b> (du Glu → <b>γ-carboxyglutamate</b>, ⚠️ <b>VITAMINE K DÉPENDANTE</b> — facteurs de coagulation II, VII, IX, X et <b>ostéocalcine</b> ⭐), <b>ADP-ribosylation</b><br><br><b>🔴 4. LE CLIVAGE PROTÉOLYTIQUE — LA 3ᵉ ÉTAPE DU COURS</b><br>📖 « <b>Il y a aussi parfois CLIVAGE d'un PEPTIDE situé à l'extrémité N-TERMINALE, exemple enlever le PEPTIDE SIGNAL qui a dirigé la protéine non mature dans un compartiment particulier de la cellule.</b> » ⭐<br>• ⚠️ <b>PEPTIDE SIGNAL (séquence signal)</b> : séquence <b>N-terminale de 15 à 30 aa, hydrophobe</b> ⭐ — reconnue par la <b>SRP (Signal Recognition Particle)</b> → arrêt de la traduction → adressage au <b>RER</b> → ⭐ <b>traduction co-traductionnelle</b> (modèle de <b>Blobel</b>, prix Nobel 1999) → le peptide signal est <b>CLIVÉ par la PEPTIDASE DU SIGNAL</b> ⭐<br>• ⚠️ <b>AUTRES EXEMPLES DE CLIVAGE ACTIVATEUR (à connaître) :</b><br>&nbsp;&nbsp;– <b>PRÉPRO-INSULINE → PRO-INSULINE → INSULINE</b> ⭐ (clivage du peptide signal dans le RE, puis du <b>peptide C</b> dans les granules de sécrétion par <b>PC1/3 et PC2</b> — ⚠️ <b>le peptide C est un marqueur de la sécrétion endogène d'insuline</b>)<br>&nbsp;&nbsp;– <b>PRO-COLLAGÈNE → COLLAGÈNE</b> (clivage des propeptides N- et C-terminaux par les <b>protéinases ADAMTS2 / BMP1</b>) → ⭐ <b>tropocollagène</b> → fibrilles ⭐ <b>ULTRA PERTINENT EN DENTAIRE (ligament parodontal, cément, os alvéolaire)</b><br>&nbsp;&nbsp;– <b>PROTHROMBINE → THROMBINE</b> (coagulation)<br>&nbsp;&nbsp;– <b>CASPASES</b> : clivage activateur → <b>APOPTOSE</b> ⭐<br>&nbsp;&nbsp;– <b>TRYPSINOGÈNE → TRYPSINE</b> (entéropeptidase) — ⚠️ <b>activation prématurée = PANCRÉATITE AIGUË</b><br>&nbsp;&nbsp;– <b>AMÉLOGÉNINE →</b> ⭐ clivée par la <b>MMP-20 (énalysine)</b> puis la <b>KLK4</b> pendant la maturation de l'émail ⭐⭐ <b>EXEMPLE EN OR POUR UN EXAMEN DE MÉDECINE DENTAIRE</b> — ⚠️ mutations → <b>AMÉLOGENÈSE IMPARFAITE</b><br>&nbsp;&nbsp;– <b>APP → peptide β-amyloïde</b> (β- et γ-sécrétases) → <b>ALZHEIMER</b><br>&nbsp;&nbsp;– <b>La MÉTHIONINE INITIALE</b> est souvent clivée (vue en V-2-1) ⭐<br><br><b>📋 RÉSUMÉ — LES MODIFICATIONS POST-TRADUCTIONNELLES DU COURS :</b><br><b>1.</b> ⭐ <b>PLIEMENT</b> aidé par les <b>CHAPERONNES</b> + <b>ponts disulfure</b> + <b>liaisons hydrogène</b><br><b>2.</b> ⭐ <b>AJOUT de molécules non protéiques</b> : <b>LIPIDES, GLUCIDES, GROUPEMENTS PHOSPHATE, petits PEPTIDES</b><br><b>3.</b> ⭐ <b>CLIVAGE</b> d'un peptide <b>N-terminal</b> (ex. le <b>PEPTIDE SIGNAL</b>)","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>VI — LE GÉNIE GÉNÉTIQUE</b> : ⭐ définition et <b>LES 3 OUTILS ENZYMATIQUES pour étudier l'ADN</b> (enzymes de restriction, vecteurs, sondes)","a":"<b>⭐ DÉFINITION DU COURS :</b><br>« <b>Le GÉNIE GÉNÉTIQUE est l'ensemble des OUTILS et des TECHNIQUES de la biologie moléculaire permettant, de manière CONTRÔLÉE, l'étude et la MODIFICATION DES GÈNES : leur ISOLEMENT, leur CLONAGE, leur SÉQUENÇAGE, leur DÉCOUPAGE... dans un but de RECHERCHE FONDAMENTALE ou APPLIQUÉE.</b> »<br><br>⚠️ <b>LES 7 VERBES DE LA DÉFINITION (tombables) :</b> <b>isolement · clonage · séquençage · découpage</b> (+ étude, modification, recherche)<br><br><b>🔴 OUTIL 1 — LES ENZYMES DE RESTRICTION (VI-2-1) ⭐⭐</b><br><b>📖 DÉFINITION EXACTE :</b><br>« <b>Une enzyme de restriction est une ENDONUCLÉASE = protéine qui peut COUPER un fragment d'ADN au niveau d'une SÉQUENCE DE NUCLÉOTIDES CARACTÉRISTIQUE appelée SITE DE RESTRICTION. Chaque enzyme de restriction reconnaît ainsi un SITE SPÉCIFIQUE.</b> » ⭐<br><br>⚠️ <b>LES 3 PROPRIÉTÉS (énumération exacte du cours) :</b><br>❖ « <b>Elles sont capables de CLIVER LES LIAISONS PHOSPHODIESTERS entre 2 nucléotides.</b> » ⭐<br>❖ « <b>Coupent au niveau de SÉQUENCES PALINDROMIQUES.</b> » ⭐⭐<br>❖ « <b>Certaines enzymes réalisent des coupures à BOUTS COHÉSIFS, d'autres à BOUTS DROITS.</b> » ⭐⭐<br><br><b>DÉTAILS À CONNAÎTRE :</b><br>• ⭐ <b>PALINDROME</b> = séquence <b>identique à l'envers et à l'endroit sur le brin complémentaire lu dans le même sens (5'→3')</b> — ⚠️ ce n'est PAS un palindrome de langage !<br>&nbsp;&nbsp;Exemple : <b>5'-GAATTC-3'</b> / <b>3'-CTTAAG-5'</b> → ⚠️ les 2 brins lus en 5'→3' donnent <b>GAATTC</b> ⭐<br>• ⚠️ <b>NOMENCLATURE :</b> <b>Eco</b>R<b>I</b> = <b>E</b>scherichia <b>co</b>li, souche <b>R</b>, 1ʳᵉ enzyme isolée (<b>I</b>) · <b>Hind</b>III (<i>Haemophilus influenzae</i> Rd) · <b>Bam</b>HI (<i>Bacillus amyloliquefaciens</i>) · <b>Alu</b>I, <b>Hae</b>III, <b>Not</b>I, <b>Sma</b>I<br>• ⚠️ <b>TAILLE DES SITES : 4, 6 ou 8 paires de bases</b> → un site de <b>6 pb</b> apparaît statistiquement tous les <b>4⁶ = 4 096 pb</b> ⭐<br>• ⭐ <b>BOUTS COHÉSIFS (« sticky ends »)</b> = coupure <b>DÉCALÉE</b> sur les 2 brins → extrémités <b>simple brin complémentaires</b> qui peuvent se <b>réhybrider</b> → ⭐ <b>ESSENTIEL POUR LE CLONAGE</b> (permet de recoller 2 ADN d'origines différentes)<br>• ⚠️ <b>BOUTS DROITS / FRANCS (« blunt ends »)</b> = coupure <b>AU MÊME NIVEAU</b> sur les 2 brins → recollement <b>non spécifique</b> et moins efficace ⭐ <b>DIFFÉRENCE TOMBABLE</b><br>&nbsp;&nbsp;Exemples : <b>EcoRI</b> coupe <b>G↓AATTC</b> → bouts cohésifs <b>AATT</b> · <b>HindIII</b> coupe <b>A↓AGCTT</b> · ⚠️ <b>SmaI</b> coupe <b>CCC↓GGG</b> → <b>BOUTS DROITS</b> · <b>AluI</b> (<b>AG↓CT</b>) et <b>HaeIII</b> (<b>GG↓CC</b>) = bouts droits<br>• ⚠️ <b>RÔLE BIOLOGIQUE :</b> « <b>On en retrouve naturellement dans un grand nombre d'ESPÈCES BACTÉRIENNES. Elles s'en servent comme MOYEN DE DÉFENSE CONTRE LES VIRUS.</b> » ⭐ (système <b>restriction-modification</b> : la <b>méthylase</b> protège l'ADN de la bactérie, l'<b>endonucléase</b> coupe l'ADN viral non méthylé ⭐)<br>• ⚠️ <b>Les enzymes de restriction (Werner Arber) + les plasmides = PRIX NOBEL DE MÉDECINE 1978</b> (Arber, Nathans, Smith)<br>• ⭐ <b>APPLICATIONS :</b> <b>carte de restriction, RFLP (polymorphisme de longueur des fragments de restriction), Southern blot, empreinte génétique (ADN fingerprinting d'Alec Jeffreys), clonage</b><br><br><b>🔴 OUTIL 2 — LES VECTEURS (VI-2-2)</b><br><b>📖 DÉFINITION EXACTE :</b><br>« <b>Molécules d'ADN capables de s'AUTORÉPLIQUER dans une cellule hôte. Ils sont utilisés pour TRANSFÉRER DES GÈNES dans des cellules réceptrices. Ces vecteurs ont un SITE DE RÉPLICATION FONCTIONNEL et contiennent des MARQUEURS GÉNÉTIQUES permettant de faciliter leur IDENTIFICATION.</b> » ⭐<br><br>⚠️ <b>LES 3 PROPRIÉTÉS OBLIGATOIRES D'UN VECTEUR :</b><br>1. <b>S'AUTORÉPLIQUER</b> → <b>ORIGINE DE RÉPLICATION (ori)</b><br>2. <b>SITE DE RÉPLICATION FONCTIONNEL</b><br>3. <b>MARQUEURS GÉNÉTIQUES</b> permettant l'identification<br><br><b>📋 LES 4 TYPES DE VECTEURS CITÉS PAR LE COURS :</b><br><b>1. PLASMIDE</b> ⭐<br>📖 « <b>Petite molécule d'ADN CIRCULAIRE DOUBLE BRIN possédant son PROPRE SYSTÈME DE RÉPLICATION. On trouve des plasmides chez les BACTÉRIES et les LEVURES.</b> »<br>• ⚠️ <b>Taille : 1 à 200 kb</b> · <b>ADN circulaire extracromosomique</b><br>• ⭐ <b>Chez les bactéries, les plasmides portent souvent les gènes de</b> <b>RÉSISTANCE AUX ANTIBIOTIQUES (facteur R)</b> → transmis par <b>conjugaison</b> ⭐ <b>ULTRA PERTINENT EN MÉDECINE DENTAIRE (résistance aux antibiotiques, prescriptions)</b><br>• ⚠️ Éléments d'un plasmide vecteur : <b>ori</b>, <b>gène de résistance à un antibiotique (Ampᴿ, Kanᴿ)</b>, <b>polylinker / MCS (Multiple Cloning Site)</b> avec de nombreux sites de restriction uniques, <b>gène rapporteur</b> (<b>lacZα</b> → ⭐ <b>sélection bleu-blanc</b> : les colonies avec insert sont <b>BLANCHES</b>, sans insert <b>BLEUES</b> par complémentation α de la β-galactosidase avec <b>X-gal</b>) ⭐<br>• ⚠️ <b>Capacité d'insertion : jusqu'à ~10 kb</b><br><br><b>2. PHAGES ou BACTÉRIOPHAGES</b><br>📖 « <b>Virus infectant les bactéries.</b> »<br>• ⚠️ Exemples : <b>phage λ (lambda)</b> — ⭐ peut insérer <b>~15-25 kb</b> · <b>M13</b> (ADN simple brin, pour le séquençage Sanger et le phage display) · ⚠️ <b>La stratégie dite « <i>packaging in vitro</i> »</b><br>• ⚠️ <b>Le phage λ</b> fut utilisé par <b>Berg</b> pour les 1ʳˢ ADN recombinants<br><br><b>3. COSMIDES</b><br>📖 « <b>Vecteurs TOTALEMENT ARTIFICIELS construits à partir d'un PLASMIDE auquel on a ajouté les SÉQUENCES COS du PHAGE.</b> » ⭐<br>• ⚠️ <b>Séquences cos</b> = extrémités cohésives du phage λ, nécessaires à l'<b>encapsidation in vitro</b><br>• ⚠️ <b>Capacité : ~35-45 kb</b> (plus qu'un plasmide)<br>• ⚠️ Autres vecteurs (bonus) : <b>BAC (Bacterial Artificial Chromosome, ~300 kb, basé sur le facteur F)</b>, <b>YAC (Yeast Artificial Chromosome, jusqu'à 3 000 kb)</b> — ⭐ <b>utilisés pour le PROJET GÉNOME HUMAIN</b><br><br><b>4. VIRUS</b><br>• ⚠️ <b>Vecteurs viraux :</b> <b>rétrovirus</b> (intégration dans le génome, division cellulaire requise), <b>lentivirus</b> ⭐ (peuvent infecter les cellules <b>non divisantes</b> — neurones) , <b>adénovirus</b> (pas d'intégration, très immunogène), <b>AAV</b> (virus adéno-associé — ⭐ <b>peu immunogène, expression longue</b>), <b>HSV</b><br><br>⚠️ <b>POINT CLÉ DU COURS :</b> « <b>Pour SÉLECTIONNER les cellules hôtes ayant intégré un vecteur, il faut des GÈNES DE SÉLECTION sur ce dernier qui permettront d'IDENTIFIER les cellules hôtes qui ont intégré le vecteur.</b> » ⭐<br>• ⚠️ Types de sélection : <b>résistance aux antibiotiques</b>, <b>auxotrophie complémentée</b>, <b>marqueur fluorescent (GFP)</b>, <b>gènes rapporteurs (luciférase, β-gal, CAT)</b><br><br><b>🔴 OUTIL 3 — LES SONDES (VI-2-3) ⭐⭐</b><br><b>📖 DÉFINITION EXACTE :</b><br>« <b>Ce sont des SÉQUENCES D'ACIDE NUCLÉIQUE (ADN ou ARN) SIMPLE BRIN (d'AU MOINS 15 NUCLÉOTIDES) COMPLÉMENTAIRES de la séquence d'ADN ou d'ARN RECHERCHÉE (= CIBLE).</b> » ⭐<br>• ⚠️ <b>CHIFFRE À RETENIR : AU MOINS 15 NUCLÉOTIDES</b> ⭐ (en dessous, la sonde n'est pas assez spécifique)<br><br><b>📋 LES 3 PROPRIÉTÉS (énumération exacte) :</b><br>• « <b>C'est un segment d'ADN ou d'ARN FLUORESCENT ou RADIOACTIF obtenu par SYNTHÈSE CHIMIQUE.</b> » ⭐<br>• « <b>Elle est MONOBRIN, COMPLÉMENTAIRE et ANTIPARALLÈLE du fragment recherché.</b> » ⭐⭐<br>• « <b>Elle est capable de RECHERCHER et de s'HYBRIDER au fragment d'ADN ou d'ARN étudié.</b> » ⭐<br><br><b>📋 LES 2 APPLICATIONS (énumération exacte) :</b><br>• <b>DIAGNOSTIC DES MALADIES GÉNÉTIQUES</b><br>• <b>DÉTECTER LES BACTÉRIES QUI ONT LE GÈNE D'INTÉRÊT</b><br><br>⚠️ <b>TECHNIQUES UTILISANT DES SONDES (bonus) :</b><br>• <b>SOUTHERN BLOT</b> (ADN) · <b>NORTHERN BLOT</b> (ARN) · <b>WESTERN BLOT</b> (protéines — ⚠️ avec des <b>ANTICORPS</b>, pas une sonde nucléotidique, mais on l'appelle quand même « blot ») ⭐ ⚠️ <b>SOUTHERN = ADN, NORTHERN = ARN, WESTERN = PROTÉINES</b> — <b>QUESTION CLASSIQUE</b><br>• ⭐ <b>FISH</b> (hybridation in situ fluorescente — vue en cytogénétique) ⭐<br>• <b>Microarrays / puces à ADN</b> · <b>PCR quantitative</b> (avec des sondes <b>TaqMan</b>) ⭐<br>• ⚠️ <b>HYBRIDATION</b> = appariement de 2 brins complémentaires ; **<b>DÉNATURATION</b>** (chaleur, pH) = séparation ; ⭐ <b>La Tm (température de fusion) dépend du % G-C et de la longueur</b> ⚠️ ⭐ <b>Tm = 2(A+T) + 4(G+C) °C</b> pour les oligonucléotides courts (formule de Wallace)<br>• ⚠️ <b>STRINGENCE</b> : température et force ionique — ⭐ <b>haute stringence = seules les séquences parfaitement complémentaires s'hybrident</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>VI-3 — LE CLONAGE</b> : définition et ⭐ les étapes du <b>CLONAGE D'UN GÈNE</b> selon le Pr ROCHD","a":"<b>🔴 DÉFINITION (VI-3-1) — TEXTE EXACT :</b><br>« <b>Le clonage est la MULTIPLICATION IN VITRO d'un ORGANISME, d'une CELLULE SOUCHE ou d'un GÈNE, en GRAND NOMBRE D'EXEMPLAIRES IDENTIQUES.</b> » ⭐<br><br>⚠️ <b>LES 2 TYPES DE CLONAGE (distinction du cours) :</b><br>📖 « <b>Autrement dit, le clonage permet d'obtenir un grand nombre de copies ABSOLUMENT IDENTIQUES :</b><br>• <b>soit d'une CELLULE → et l'on parle alors de CLONAGE CELLULAIRE</b><br>• <b>soit d'un FRAGMENT D'ADN → et l'on parle alors de CLONAGE MOLÉCULAIRE</b> » ⭐⭐ <b>DISTINCTION TOMBABLE</b><br><br><b>🔴 CLONAGE D'UN GÈNE (VI-3-2) — TEXTE EXACT :</b><br>« <b>Il s'agit d'INSÉRER UN FRAGMENT D'ADN DANS UN VECTEUR et le faire AMPLIFIER dans une CELLULE HÔTE.</b> » ⭐<br><br><b>📋 LE SCHÉMA DU COURS — LES ÉTAPES À CONNAÎTRE ⭐⭐ :</b><br>Le schéma du poly montre la séquence suivante :<br><b>ENZYMES DE RESTRICTION + PLASMIDES + ADN LIGASE + GÈNE → TRANSFERT DU VECTEUR DANS LA CELLULE-HÔTE → CLONAGE → EXPRESSION DE LA PROTÉINE SOUHAITÉE</b><br><br>⚠️ <b>LES 5 ÉTAPES DÉTAILLÉES :</b><br><br><b>ÉTAPE 1 — DÉCOUPE ( « CUT » )</b><br>• On coupe l'<b>ADN d'intérêt</b> (le gène à cloner) <b>ET</b> le <b>plasmide vecteur</b> avec <b>LA MÊME ENZYME DE RESTRICTION</b> ⭐⭐<br>• ⚠️ <b>POURQUOI LA MÊME ?</b> Pour obtenir les <b>MÊMES EXTRÉMITÉS COHÉSIVES COMPLÉMENTAIRES</b> → les 2 ADN pourront s'hybrider ⭐<br>• ⚠️ On peut aussi utiliser <b>2 enzymes différentes</b> → <b>clonage directionnel</b> ⭐ (le gène ne peut s'insérer que dans un seul sens — évite 50 % de clones inversés)<br><br><b>ÉTAPE 2 — LIAISON ( « PASTE » )</b><br>• Le gène et le plasmide sont mélangés → leurs extrémités cohésives <b>s'HYBRIDENT</b> (appariement des bases)<br>• ⭐ <b>L'ADN LIGASE</b> « <b>RESSOUDE</b> » → rétablit les <b>LIAISONS PHOSPHODIESTERS</b> ⭐ (⚠️ c'est la même enzyme que dans la réplication — vue au chapitre II !)<br>• ⚠️ On obtient un <b>ADN RECOMBINANT</b> = <b>plasmide recombinant / chimérique</b> ⭐<br>• ⚠️ <b>Produits secondaires possibles :</b> plasmide <b>re circulé vide</b> (sans insert), concatémères → d'où la nécessité de la <b>SÉLECTION</b><br><br><b>ÉTAPE 3 — TRANSFERT DANS LA CELLULE HÔTE</b><br>• ⭐ <b>TRANSFORMATION</b> = introduction d'un ADN nu dans une bactérie ⭐<br>• ⚠️ <b>Bactéries « compétentes » :</b> traitement au <b>CaCl₂ + choc thermique (42 °C)</b> ⭐ ou <b>ÉLECTROPORATION</b> (champ électrique)<br>• ⚠️ Autres méthodes : <b>transduction</b> (par un phage) · <b>conjugaison</b> (pili) · <b>transfection</b> (pour les cellules eucaryotes — <b>lipofection, phosphate de calcium, nucléofection, micro-injection, biolistique</b>) ⭐<br>• ⚠️ <b>Cellule hôte classique : E. coli</b> (souche K12, déficiente en restriction : <b>endA⁻, recA⁻, hsdR⁻</b> pour éviter la dégradation de l'ADN étranger et la recombinaison) ⭐<br><br><b>ÉTAPE 4 — SÉLECTION ET IDENTIFICATION</b> ⭐<br>• ⭐ <b>SÉLECTION PAR ANTIBIOTIQUE</b> : le plasmide porte un <b>gène de résistance (Ampᴿ)</b> → on étale sur une gélose contenant l'antibiotique → ⭐ <b>SEULES les bactéries transformées poussent</b><br>• ⭐ <b>SÉLECTION BLEU-BLANC</b> : le gène <b>lacZα</b> est interrompu par l'insert → les colonies <b>AVEC insert = BLANCHES</b>, <b>SANS insert = BLEUES</b> (sur milieu <b>X-gal + IPTG</b>) ⭐⭐ <b>QUESTION CLASSIQUE</b><br>• ⚠️ <b>CRIBLAGE</b> : par <b>hybridation avec une sonde</b> (voir outil 3) — réplique sur membrane, dénaturation, hybridation avec une sonde marquée, autoradiographie/fluorescence<br>• ⚠️ Autres : <b>PCR sur colonies</b>, <b>digestion de restriction des mini-préparations</b>, <b>séquençage</b><br><br><b>ÉTAPE 5 — AMPLIFICATION ET EXPRESSION</b> ⭐<br>• ⭐ <b>AMPLIFICATION / CLONAGE</b> : chaque bactérie se divise toutes les <b>~20 minutes</b> → en une nuit, ⭐ <b>1 bactérie → ~10⁹ copies identiques</b> du plasmide (une <b>BANQUE DE CLONES</b> / « <b>clone library</b> »)<br>• ⚠️ <b>EXPRESSION DE LA PROTÉINE SOUHAITÉE</b> : on utilise un <b>VECTEUR D'EXPRESSION</b> contenant un <b>PROMOTEUR</b> fort + un <b>site de fixation du ribosome</b> + éventuellement une <b>étiquette (Tag)</b> pour la purification (<b>His-Tag, GST-Tag, FLAG, GFP</b>) ⭐<br>• ⚠️ ⭐ <b>EXEMPLE HISTORIQUE : L'INSULINE HUMAINE RECOMBINANTE</b> — <b>1ʳᵉ protéine thérapeutique produite par génie génétique (Genentech, 1978 ; commercialisée sous le nom Humulin en 1982)</b> ⭐⭐ — avant, on utilisait de l'insuline <b>porcine/bovine</b> (risque d'allergie, de résistance) ⭐ <b>EXEMPLE EN OR À CITER</b><br><br><b>📋 LES DOMAINES D'APPLICATION DU CLONAGE :</b><br>• ⭐ <b>PRODUCTION DE PROTÉINES THÉRAPEUTIQUES</b> : <b>insuline, hormone de croissance, érythropoïétine (EPO), interférons, facteurs de coagulation (VIII, IX — hémophilie), anticorps monoclonaux, vaccins (antigène HBs de l'hépatite B !)</b><br>• ⭐ <b>ANIMAUX TRANSGÉNIQUES</b> : <b>souris knock-out</b> (délétion d'un gène — ⭐ <b>prix Nobel 2007 : Capecchi, Evans, Smithies</b>) · <b>knock-in</b> · système <b>Cre-Lox</b> pour l'inactivation conditionnelle ⭐<br>• ⭐ <b>THÉRAPIE GÉNIQUE</b> (chapitre suivant)<br>• ⚠️ <b>OGM</b> (maïs Bt, riz doré, soja Roundup Ready) · <b>banques génomiques</b> · <b>ADNc</b> (à partir d'ARNm par la <b>transcriptase inverse</b> → ⭐ <b>pas d'introns !</b> → indispensable pour exprimer un gène humain dans une bactérie ⭐⭐)<br>• ⚠️ <b>LE CLONAGE REPRODUCTIF</b> : <b>la brebis DOLLY (1996, Institut Roslin, Écosse)</b> — 1ᵉʳ mammifère cloné à partir d'une cellule somatique adulte par <b>transfert nucléaire</b> ⭐ · ⚠️ <b> chez l'Homme : interdit</b><br>• ⚠️ <b>CRISPR-Cas9 (2020, Nobel Doudna &amp; Charpentier)</b> = l'outil moderne d'édition du génome — ⭐ <b>remplace avantageusement les enzymes de restriction pour « découper » l'ADN de façon ciblée</b> ⭐<br><br><b>📋 LES 4 ÉLÉMENTS DU SCHÉMA DU COURS À RETENIR :</b><br>1. ⭐ <b>ENZYMES DE RESTRICTION</b><br>2. ⭐ <b>PLASMIDES</b> (vecteurs)<br>3. ⭐ <b>ADN LIGASE</b><br>4. ⭐ <b>GÈNE</b> (le fragment à insérer)<br>→ puis <b>TRANSFERT DANS LA CELLULE-HÔTE → CLONAGE → EXPRESSION DE LA PROTÉINE SOUHAITÉE</b>","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>VI-4-1 — APPLICATION 1 : LE DIAGNOSTIC DES MALADIES GÉNÉTIQUES</b> — ⭐ l'exemple de la <b>DRÉPANOCYTose</b> (Mst II) selon le Pr ROCHD","a":"<b>⭐⭐ EXERCICE TYPE DE L'EXAMEN — LE COURS DONNE CET EXEMPLE EN DÉTAIL</b><br><br><b>📖 LA MALADIE :</b><br>« <b>C'est une HÉMOGLOBINOPATHIE GÉNÉTIQUE très répandue dans certaines régions du SUD DE L'AFRIQUE.</b> »<br>⚠️ (En réalité : aussi en Afrique subsaharienne, en Inde, dans le bassin méditerranéen, au Moyen-Orient — ⚠️ <b>et au MAROC, surtout dans le Sud</b> ⭐)<br><br><b>📖 LA MUTATION :</b><br>« <b>Elle est secondaire à une MUTATION PONCTUELLE au niveau du 1ᵉʳ EXON du gène qui code pour la CHAÎNE BÊTA de l'HÉMOGLOBINE, portant sur le TRIPLET qui code pour le 6ᵉ ACIDE AMINÉ.</b> » ⭐<br><br>🔴 <b>LES 4 FAITS À RETENIR ABSOLUMENT (tableau) :</b><br>• <b>Chez les SUJETS SAINS :</b> « ce triplet a la séquence <b>GAG</b> et code pour l'<b>ACIDE GLUTAMIQUE</b> » ⭐<br>• <b>Chez les SUJETS DRÉPANOCYTAIRES :</b> « ce triplet est <b>GTG</b> et code pour la <b>VALINE</b> » ⭐<br>• <b>À l'état HOMOZYGOTE :</b> « le sujet est <b>MALADE</b> et présente des <b>HÉMATIES FALCIFORMES</b> » ⭐<br>• <b>À l'état HÉTÉROZYGOTE :</b> « le sujet est <b>PORTEUR SAIN</b> » ⭐<br><br>⚠️ <b>COMMENT LA RETENIR :</b> <b>GAG → GTG</b> = <b>une SUBSTITUTION d'une seule base</b> (<b>A → T</b> en 2ᵉ position). ⭐ <b>C'EST UNE MUTATION FAUX-SENS</b> (Glu <b>acide polaire</b> → Val <b>hydrophobe</b>) — ⚠️ <b>exactement le type « faux-sens » du chapitre III !</b><br>• ⚠️ <b>Conséquence :</b> l'<b>HbS</b> polymérise en conditions désoxygénées → les GR prennent la forme de <b>faucille</b> → <b>vaso-occlusion</b>, <b>hémolyse</b>, <b> crises douloureuses</b>, <b>AVC</b>, <b>splénomégalie puis asplénie fonctionnelle</b> → ⭐ <b>infections à germes encapsulés</b> ⭐ <b>PERTINENT EN DENTAIRE : risque d'ostéomyélite, asplénie → prophylaxie</b><br>• ⚠️ <b>Avantage hétérozygote :</b> le porteur sain est <b>PROTÉGÉ CONTRE LE PALUDISME</b> (Plasmodium falciparum) ⭐ → explique la fréquence élevée de l'allèle en zone d'endémie<br><br><b>📖 LE DIAGNOSTIC :</b><br>« <b>Le dépistage des sujets malades ou porteurs sains se fait grâce à une enzyme de restriction appelée MST II.</b> » ⭐<br>« <b>Le 5ᵉ, 6ᵉ et 7ᵉ TRIPLETS de l'EXON constituent un PALINDROME reconnu par MST II.</b> » ⭐⭐<br><br>⚠️ <b>COMMENT ÇA MARCHE (mécanisme à comprendre) :</b><br>1. <b>L'enzyme de restriction Mst II</b> reconnaît un <b>site palindromique de 6 pb</b> qui <b>inclut le 6ᵉ codon</b> (le codon muté)<br>2. ⭐ <b>Chez le sujet SAIN</b> (GAG) : le site <b>EST RECONNU</b> → Mst II <b>COUPE</b> → ⚠️ <b>fragments COURTS</b><br>3. ⭐ <b>Chez le sujet MALADE</b> (GTG) : la mutation <b>DÉTRUIT le site de restriction</b> → Mst II <b>NE COUPE PAS</b> → ⚠️ <b>fragment LONG</b> ⭐⭐<br>4. ⭐ <b>Chez l'HÉTÉROZYGOTE</b> : <b>les 3 fragments</b> (court + long) ⭐ ⚠️ <b>C'EST LA SIGNATURE DU PORTEUR SAIN</b><br>5. On sépare les fragments par <b>ÉLECTROPHORÈSE sur gel d'agarose</b> (les petits fragments migrent plus loin — ⭐ l'ADN migre vers l'<b>ANODE +</b> car il est chargé négativement)<br>6. ⭐ On révèle par <b>SOUTHERN BLOT</b> avec une <b>SONDE</b> marquée complémentaire du gène β-globine ⭐ (⚠️ <b>l'outil n°3 du chapitre VI-2-3 !</b>)<br><br><b>📋 RÉSUMÉ DU RÉSULTAT PROFESSIONNEL :</b><br>• <b>HOMOZYGOTE SAIN (AA)</b> → <b>1 bande courte</b> (ex. <b>1,15 kb</b>)<br>• <b>HÉTÉROZYGOTE (AS)</b> → <b>2 bandes</b> (courte + longue, ex. <b>1,15 + 1,35 kb</b>) ⭐<br>• <b>HOMOZYGOTE MALADE (SS)</b> → <b>1 bande longue</b> (ex. <b>1,35 kb</b>)<br><br>⚠️ <b>CE TYPE D'ANALYSE S'APPELLE UN RFLP</b> (<b>Restriction Fragment Length Polymorphism = polymorphisme de longueur des fragments de restriction</b>) ⭐⭐ <b>TERME À CONNAÎTRE</b><br><br><b>📋 AUTRES APPLICATIONS DU DIAGNOSTIC MOLÉCULAIRE (bonus) :</b><br>• ⭐ <b>PCR</b> (Réaction de Polymérisation en Chaîne — <b>Kary Mullis, prix Nobel 1993</b>) : <b>amorces (primers) + ADN polymérase THERMOSTABLE (Taq, isolée de <i>Thermus aquaticus</i> dans les sources chaudes du Yellowstone)</b> + <b>dNTP</b> → cycles de <b>dénaturation 94-95 °C · hybridation 50-65 °C · élongation 72 °C</b> → ⭐ <b>amplification EXPONENTIELLE (2ⁿ)</b> ⭐<br>• ⚠️ <b>PCR en temps réel / qPCR</b> (avec <b>SYBR Green</b> ou sonde <b>TaqMan</b>) · <b>RT-PCR</b> (avec <b>transcriptase inverse</b> → ARN) ⭐<br>• ⭐ <b>SÉQUENÇAGE SANGER</b> (didésoxynucléotides <b>ddNTP</b> terminateurs, <b>électrophorèse capillaire</b>) → ⭐ <b>NGS (Next-Generation Sequencing)</b> = séquençage massivement parallèle<br>• ⭐ <b>DIAGNOSTIC PRÉIMPLANTATOIRE (DPI/DPG)</b> · <b>DIAGNOSTIC PRÉNATAL</b> (amniocentèse, choriocentèse) · <b>DPNI/NIPT</b> (ADN libre circulant fœtal dans le sang maternel) ⭐<br>• ⭐ <b>APPLICATIONS EN MÉDECINE DENTAIRE :</b> ⚠️ <b>PCR en ENDODONTIE</b> (détection des bactéries anaérobies dans les canaux nécrosés) · <b>détection des pathogènes parodontaux</b> (<b>Porphyromonas gingivalis, Aggregatibacter actinomycetemcomitans, Tannerella forsythia, Treponema denticola</b> = ⭐ <b>le « complexe rouge » de Socransky</b>) ⭐⭐ <b>EXCELLENT POINT À CITER À L'EXAMEN</b> · <b>détection desHPV</b> dans les lésions buccales · <b>identification médico-légale</b> par empreinte génétique ⭐","t":"biomol-ROCHD EXAM-2026 M111"},{"q":"<b>VI-4-2 — APPLICATION 2 : LA THÉRAPIE GÉNIQUE</b> — ⭐ définition, les <b>3 VOIES d'administration</b> et les <b>4 EXEMPLES</b> du cours","a":"<b>⭐⭐ FIN DU COURS — PARTIE LA PLUS TOMBABLE AVEC LE CLONAGE</b><br><br><b>🔴 DÉFINITION — TEXTE EXACT :</b><br>« <b>La thérapie génique est une méthode thérapeutique visant à TRAITER UNE MALADIE en MODIFIANT LE PROGRAMME GÉNÉTIQUE. Le principe de la thérapie génique est de REMPLACER, à l'intérieur des cellules malades, le GÈNE DÉFECTUEUX responsable de la pathologie par un GÈNE FONCTIONNANT NORMALEMENT (= TRANSGÈNE).</b> » ⭐⭐<br><br>⚠️ <b>LES 3 MOTS CLÉS DE LA DÉFINITION :</b> <b>remplacer</b> · <b>gène défectueux</b> · <b>transgène</b> ⭐<br><br><b>🔴 LA REMARQUE ÉTHIQUE DU COURS ⚠️⭐ :</b><br>« <b>La thérapie génique peut être appliquée aussi bien sur les CELLULES GERMINALES que les CELLULES SOMATIQUES. MAIS CHEZ L'HOMME ET POUR DES RAISONS D'ÉTHIQUES, SEULS LES GÈNES DES CELLULES SOMATIQUES PEUVENT ÊTRE MODIFIÉS, CAR PAS DE TRANSMISSION AUX ENFANTS.</b> » ⭐⭐ <b>QUESTION D'EXAMEN DIRECTE</b><br>• ⚠️ <b>Thérapie germinale = INTERDITE chez l'Homme</b> (modification transmissible à la descendance)<br>• ⚠️ <b>Thérapie somatique = AUTORISÉE</b> (n'affecte que le patient)<br>• ⚠️ ⭐ <b>ACTUALITÉ :</b> en <b>novembre 2018, He Jiankui (Chine)</b> a annoncé la naissance de bébés <b>CCR5-édités par CRISPR</b> → ⭐ <b>condamné à 3 ans de prison</b>, scandale mondial ⭐ <b>EXEMPLE À CITER</b><br><br><b>🔴 LES 3 VOIES DE TRANSFERT ⭐⭐⭐ (À CONNAÎTRE PAR CŒUR — ÉNUMÉRATION EXACTE DU COURS) :</b><br><br><b>1. IN VIVO</b><br>📖 « <b>en injectant le vecteur dans la CIRCULATION SANGUINE</b> »<br>⚠️ <b>INCONVÉNIENT MAJEUR SIGNALÉ PAR LE COURS :</b> « <b>DANGER SI LE VECTEUR SE TROMPE DE CELLULE</b> » ⭐⭐<br>• ⚠️ Risques : <b>absence de ciblage</b>, <b>immunogénicité</b>, <b>toxicité systémique</b>, <b>mutagenèse insertionnelle</b><br>• ⚠️ Exemples : <b>Luxturna</b> (voretigene neparvovec, <b>AAV</b> injecté dans la rétine pour l'<b>amaurose congénitale de Leber</b>, 2017 — 1ʳᵉ thérapie génique approuvée aux USA pour une maladie monogénique) ⭐ · <b>Zolgensma</b> (onasemnogene abeparvovec, AAV9 IV pour l'<b>amyotrophie spinale SMA</b>, 2019) ⭐<br><br><b>2. EX VIVO</b> ⭐<br>📖 « <b>le vecteur est transféré dans la cellule hôte EN DEHORS DE L'ORGANISME puis l'ensemble est RÉINTRODUIT dans le corps</b> » ⭐<br>• ⚠️ <b>Étapes :</b> prélèvement des cellules du patient (ex. <b>moelle osseuse, cellules souches hématopoïétiques CD34+, lymphocytes T</b>) → <b>transduction in vitro</b> → <b>sélection et contrôle</b> → <b>réinjection au patient (autogreffe)</b><br>• ⭐ <b>AVANTAGE MAJEUR :</b> <b>contrôle qualité AVANT réinjection</b> → <b>pas de risque de « se tromper de cellule »</b> ⭐<br>• ⚠️ <b>Inconvénients :</b> lourd, coûteux, nécessite une <b>conditionnement myéloablatif</b> parfois<br>• ⚠️ Exemples : <b>Strimvelis</b> (déficit en <b>ADA-SCID</b>, « enfants bulle », 2016) ⭐ · <b>Kymriah / Yescarta</b> (<b>CAR-T cells</b> ⭐ — lymphocytes T du patient modifiés ex vivo pour exprimer un récepteur chimérique <b>anti-CD19</b> → traitent les <b>leucémies aiguës lymphoblastiques</b> et <b>lymphomes</b> — ⭐ <b>prix Nobel 2024 décerné aux découvreurs des microARN (Ambros &amp; Ruvkun)</b>, mais les CAR-T ont révolutionné l'onco-hématologie) ⭐⭐<br><br><b>3. IN SITU</b><br>📖 « <b>le vecteur est introduit DIRECTEMENT DANS LA CELLULE CIBLE</b> »<br>📖 <b>Exemple du cours :</b> « <b>destruction des cellules cancéreuses par le gène porté par le vecteur</b> » ⭐<br>• ⚠️ <b>DIFFÉRENCE AVEC IN VIVO :</b> <b>in vivo</b> = injection <b>systémique</b> (sang) ; <b>in situ</b> = injection <b>locale, directe dans l'organe/la tumeur cible</b> ⭐⭐ <b>DISTINCTION TOMBABLE</b><br>• ⚠️ Exemples : <b>injection intratumorale</b> d'un vecteur · <b>injection intrathécale</b> · <b>injection intramusculaire</b> · <b>injection sous-rétinienne</b> · <b>injection dans le muscle cardiaque</b> ⭐<br><br><b>🔴 LES 4 EXEMPLES DU COURS ⭐⭐⭐ :</b><br><br><b>a) LE MÉLANOME</b><br>📖 « <b>= cancer de la peau dû à une transformation maligne des MÉLANOCYTES, il est REBELLE AUX TRAITEMENTS CLASSIQUES du cancer.</b> »<br>📖 <b>La stratégie :</b> « <b>La thérapie génique consiste à STIMULER LA RÉPONSE IMMUNITAIRE ANTITUMORALE par transfert d'un GÈNE QUI CODE POUR UNE CYTOKINE qui induit la PROLIFÉRATION DES LYMPHOCYTES T qui DÉTRUISENT LES CELLULES CANCÉREUSES.</b> » ⭐ <b>immunothérapie génique</b><br>• ⚠️ Cytokines utilisées : <b>IL-2, IL-12, IFN-γ, GM-CSF</b> (vaccin <b>GVAX</b>, <b>T-VEC/talimogene laherparepvec</b> = HSV-1 oncolytique exprimant le <b>GM-CSF</b>, approuvé en 2015) ⭐<br><br><b>b) L'HYPERCHOLESTÉROLÉMIE FAMILIALE</b> ⭐<br>📖 « <b>C'est une maladie due à un DÉFICIT DES RÉCEPTEURS DES LIPOPROTÉINES LDL responsable d'une AUGMENTATION DU TAUX DE CHOLESTÉROL dans le sang, ce qui entraîne son DÉPÔT SUR LES PAROIS DES VAISSEAUX SANGUINS et cause la maladie d'ATHÉROSCLÉROSE. Les récepteurs LDL sont UBIQUITAIRES mais ceux HÉPATIQUES permettent l'ÉLIMINATION DE LA MAJORITÉ DES LDL circulants.</b> »<br>📖 <b>Le traitement :</b> « <b>La thérapie génique est faite EN EX VIVO sur des HÉPATOCYTES en introduisant le gène qui code pour le RÉCEPTEUR LDL.</b> » ⭐ ⚠️ <b>À RETENIR : EX VIVO + HÉPATOCYTES + RÉCEPTEUR LDL</b><br>📖 <b>⚠️ LA LIMITE SIGNALÉE PAR LE COURS :</b> « <b>Toutefois l'EFFET THÉRAPEUTIQUE DISPARAÎT APRÈS 6 MOIS car le vecteur N'EST PAS STABLE au cours du RENOUVELLEMENT CELLULAIRE DES HÉPATOCYTES.</b> » ⭐⭐ <b>DÉTAIL TRÈS TOMBABLE</b><br>• ⚠️ <b>Contexte :</b> gène <b>LDLR (chr 19p13)</b>, transmission <b>AUTOSOMIQUE DOMINANTE</b>, <b>1/500 hétérozygotes</b> (la maladie monogénique la plus fréquente) → ⚠️ <b>xanthomes tendineux</b> (tubéreux sur les coudes/genoux, ⭐ <b>tendon d'Achille</b>), <b>xanthélasmas palpébraux</b>, <b>arc cornéen</b>, <b>IDM avant 40-50 ans</b><br><br><b>c) LES MALADIES CARDIOVASCULAIRES</b> ⭐<br>📖 « <b>Les malades souffrant d'OBSTRUCTION DES VAISSEAUX SANGUINS secondaires à la maladie d'ATHÉROSCLÉROSE peuvent bénéficier : d'un transfert IN SITU au niveau de la MEMBRANE INFÉRIEURE DU CŒUR d'un gène appelé VEGF (Vascular Endothelial Growth Factor) porté par un PLASMIDE.</b> »<br>📖 « <b>Le gène code pour la CROISSANCE ET LA MULTIPLICATION DES NOUVEAUX VAISSEAUX SANGUINS, ce qui permet de CONTOURNER LE BLOCAGE.</b> » ⭐<br>• ⚠️ ⭐ <b>À RETENIR : IN SITU + VECTEUR = PLASMIDE + GÈNE = VEGF + BUT = ANGIOGENÈSE / NÉO-VASCULARISATION (contourner le blocage)</b><br>• ⚠️ ⚠️ <b>ATTENTION — LE COURS ÉCRIT « Vascular EPITHELIAL Growth Factor » mais le nom correct est <b>Vascular ENDOTHELIAL Growth Factor</b> (« endothélial », pas « epithelial »).</b> ⚠️ <b>Si le QCM reprend la faute du cours, réponds comme le cours ; sinon, la bonne orthographe est ENDOTHELIAL.</b><br>• ⚠️ <b>Concept :</b> <b>THÉRAPIE ANGIOGÉNIQUE = « by-pass biologique »</b> ⭐ ⚠️ ⭐ <b>PERTINENT EN DENTAIRE : le VEGF est ESSENTIEL dans la CICATRISATION, l'angiogenèse pulpaire et la régénération parodontale</b> ⭐<br><br><b>d) ⭐ LA STRATÉGIE DU GÈNE SUICIDE</b><br>📖 <b>DÉFINITION EXACTE :</b> « <b>C'est une technique qui CONFÈRE AUX CELLULES TUMORALES UNE SENSIBILITÉ À UN MÉDICAMENT.</b> »<br>📖 <b>Mécanisme (2 temps) :</b><br>« <b>On injecte dans la TUMEUR un GÈNE qui code pour une ENZYME capable de transformer une PRODROGUE NON TOXIQUE EN UN MÉTABOLITE TOXIQUE.</b><br><b>Ensuite, on administre au malade la PRODROGUE dont le MÉTABOLITE formé dans les cellules tumorales TUE CES DERNIÈRES.</b> » ⭐⭐<br>📖 <b>L'EXEMPLE DU COURS :</b> « <b>L'enzyme largement utilisée est la THYMINE KINASE DU VIRUS DE L'HERPÈS (HSV-TK), la prodrogue est l'ANTIVIRAL GANCICLOVIR qui sous l'action de la thymine kinase se transforme en GANCICLOVIR TRIPHOSPHATE qui est TOXIQUE.</b> » ⭐⭐⭐<br><br>⚠️ <b>LES 4 ÉLÉMENTS À RETENIR PAR CŒUR :</b><br>• <b>Enzyme :</b> <b>THYMINE KINASE du VIRUS DE L'HERPÈS (HSV-TK)</b><br>• <b>Prodrogue :</b> <b>GANCICLOVIR</b> (antiviral, ⚠️ normalement <b>NON TOXIQUE</b> pour nos cellules car notre TK ne le phosphoryle pas)<br>• <b>Produit toxique :</b> <b>GANCICLOVIR TRIPHOSPHATE</b> ⭐<br>• <b>Mécanisme de la toxicité :</b> le ganciclovir triphosphate est un <b>analogue de nucléoside</b> → ⭐ <b>incorporé dans l'ADN en cours de réplication → ARRÊT DE LA CHAÎNE → APOPTOSE</b> ⭐ <b>donc ⚠️ ⭐ ne tue QUE LES CELLULES QUI SE DIVISENT</b> — c'est pourquoi ça cible les cellules tumorales<br>• ⚠️ ⭐ <b>L'EFFET BYSTANDER (« spectateur »)</b> ⭐ : le métabolite toxique <b>passe dans les cellules voisines</b> via les <b>JONCTIONS GAP (connexine 43)</b> → ⭐ <b>on n'a pas besoin de transduire 100 % des cellules tumorales</b> — ⭐ <b>CONCEPT IMPORTANT, SOUVENT DEMANDÉ</b><br>• ⚠️ Autres systèmes gène suicide : <b>cytosine désaminase (CD) + 5-fluorocytosine → 5-FU</b> ⭐ · <b>nitroreductase + CB1954</b> · <b>caspase inductible (iCasp9)</b><br><br><b>📋 LES LIMITES ET RISQUES DE LA THÉRAPIE GÉNIQUE :</b><br>• ⭐ <b>MUTAGENÈSE INSERTIONNELLE</b> : l'insertion du transgène peut activer un <b>oncogène</b> → ⚠️ <b>LEUCÉMIE</b> (cas des « <b>enfants bulle</b> » X-SCID traités par rétrovirus en 2000 : <b>5 cas de leucémie</b> sur 20 patients, activation de <b>LMO2</b>) ⭐⭐<br>• ⚠️ <b>JESSE GEL SINGER (1999)</b> : décès d'un patient après injection d'un <b>adénovirus</b> à très forte dose → <b>réaction inflammatoire fulminante</b> → ⭐ <b>arrêt temporaire des essais aux USA</b> ⭐<br>• ⚠️ <b>Immunogénicité des vecteurs</b> · <b>expression transitoire</b> · <b>coût faramineux</b> (⚠️ <b>Zolgensma : ~2,1 millions $</b>, <b>Luxturna : ~850 000 $</b>) · <b>difficile pour les maladies polygéniques</b><br>• ⭐ <b>L'AVENIR : CRISPR-Cas9</b> — <b>édition précise</b> au lieu d'une addition aléatoire · ⚠️ <b>1ʳᵉ thérapie CRISPR approuvée : CASGEVY (exa-cel, décembre 2023, UK/USA)</b> pour la <b>drépanocytose</b> et la <b>β-thalassémie</b> — ⭐ <b>édition ex vivo du gène BCL11A dans les cellules souches hématopoïétiques pour réactiver l'HbF (hémoglobine fœtale)</b> ⭐ <b>EN OR : ça boucle avec l'exemple de la drépanocytose du même cours !</b>","t":"biomol-ROCHD EXAM-2026 M111"}]},{"id":"biocell-methodes-S1-2026","nom":"🔍 Méthodes d'étude","src":"COURS OFFICIEL Pr RHRICH-HADDOUT","ordre":5,"module":"M111","desc":"Microscopes · colorations · 12 étapes","cards":[{"q":"📘 <b>COURS OFFICIEL — MÉTHODES D'ÉTUDE DE LA CELLULE</b> (Pr F. RHRICH-HADDOUT, FMDC Casablanca, S1). Quel est le plan exact du cours ?","a":"<b>⭐ C'EST LE COURS OFFICIEL DU MODULE M111 — ÉLÉMENT « BIOLOGIE CELLULAIRE »</b><br><br><b>« PRINCIPALES MÉTHODES D'ÉTUDE DE LA CELLULE » — Pr F. RHRICH-HADDOUT — Université Hassan II de Casablanca, Faculté de Médecine Dentaire — Module : Biologie cellulaire, moléculaire et génétique — S1</b><br><br>⚠️ <b>OBJECTIFS PÉDAGOGIQUES (énumération exacte du cours) — l'étudiant sera en mesure de :</b><br>• Connaître les méthodes d'étude de la <b>STRUCTURE</b> de la cellule<br>• Connaître les méthodes d'étude de la <b>CONSTITUTION CHIMIQUE</b> de la cellule<br>• Connaître les méthodes d'étude du <b>FONCTIONNEMENT</b> de la cellule<br>• Connaître <b>LE BUT ET LE PRINCIPE</b> de chaque méthode ⭐<br><br><b>📋 PLAN DU COURS (3 GRANDES PARTIES) :</b><br><b>I. MÉTHODES D'ÉTUDE DE LA STRUCTURE</b><br>&nbsp;&nbsp;1. Observation au <b>MICROSCOPE OPTIQUE</b> (ou photonique)<br>&nbsp;&nbsp;2. Observation au <b>MICROSCOPE ÉLECTRONIQUE</b><br><b>II. MÉTHODES D'ÉTUDE DE LA CONSTITUTION CHIMIQUE</b><br>&nbsp;&nbsp;1. <b>CYTOCHIMIE</b> · 2. <b>FRACTIONNEMENT CELLULAIRE</b> · 3. <b>ÉLECTROPHORÈSE</b> · 4. <b>CHROMATOGRAPHIE</b><br><b>III. MÉTHODES D'ÉTUDE DU FONCTIONNEMENT</b><br>&nbsp;&nbsp;1. <b>CULTURE DE CELLULES</b> · 2. <b>AUTORADIOGRAPHIE</b><br><br><b>📖 LES 3 DÉFINITIONS DE L'INTRODUCTION ⭐ (tombables) :</b><br>• <b>LA CYTOLOGIE</b> : « permet d'étudier la <b>STRUCTURE</b> microscopique de la cellule <b>EN DEHORS DE TOUTE ORGANISATION TISSULAIRE</b> » ⭐<br>• <b>LA BIOLOGIE MOLÉCULAIRE ET LA BIOCHIMIE</b> : étudient le <b>FONCTIONNEMENT</b> de la cellule ⭐<br>• ⚠️ <b>« FRONTIÈRE ARBITRAIRE car STRUCTURE et FONCTION sont INTIMEMENT LIÉES »</b> ⭐ <b>PHRASE CLÉ DU COURS</b><br>• <b>LA BIOLOGIE CELLULAIRE</b> : « utilise la <b>CYTOLOGIE, la BIOLOGIE MOLÉCULAIRE et la BIOCHIMIE</b> pour étudier la cellule » ⭐<br><br><b>📖 LES DÉFINITIONS HIÉRARCHIQUES :</b><br>• <b>UN TISSU</b> : « un <b>ASSEMBLAGE DE CELLULES</b> remplissant une <b>FONCTION PARTICULIÈRE</b> à l'intérieur d'un organe » ⭐<br>&nbsp;&nbsp;⚠️ <b>LES 4 TISSUS FONDAMENTAUX :</b> <b>épithélial</b> · <b>conjonctif</b> · <b>musculaire</b> · <b>nerveux</b> ⭐ ⚠️ <b>À CONNAÎTRE PAR CŒUR</b><br>• <b>UN ORGANE</b> : « assemblage de <b>PLUSIEURS TISSUS</b> qui remplissent une fonction spécifique dans un organisme » ⭐<br>&nbsp;&nbsp;Exemples du cours : <b>cerveau, foie, pancréas</b><br><br><b>📋 LE PROGRAMME COMPLET DU MODULE « BIOLOGIE CELLULAIRE » (annoncé en page 1 du cours) ⭐ :</b><br>• <b>MEMBRANE PLASMIQUE</b> : Structure · Composition biochimique (<b>les lipides, les protéines, les glucides</b>) · <b>Modèle de la mosaïque fluide</b> · Mécanismes des rôles physiologiques de la MP (<b>échanges membranaires, signalisation cellulaire, interactions cellulaires</b>)<br>• <b>NOYAU</b> : <b>Noyau interphasique · Cycle cellulaire · Chromosomes · Mitose · Méiose</b> ⭐<br>• <b>CONSTITUANTS DU CYTOPLASME ET LEURS RÔLES</b> :<br>&nbsp;&nbsp;– <b>Inclusions inertes</b><br>&nbsp;&nbsp;– <b>Organites cellulaires</b> : ✓ <b>Système endomembranaire</b> (Réticulum endoplasmique, Appareil de Golgi, Lysosomes, Endosomes) ✓ <b>Peroxysome</b> ✓ <b>Mitochondrie</b><br>• <b>CYTOSQUELETTE</b> : Rôles du cytosquelette : <b>Microtubules · Microfilaments · Filaments intermédiaires</b> ⭐<br><br>⚠️ <b>L'EXAMEN 2026 M111 = 90 QCM : 50 BIOCELL + 40 GÉNÉTIQUE</b>. Ce cours « Méthodes » est le <b>CHAPITRE D'INTRODUCTION</b> — ⭐ <b>il est TOMBÉ en 2026</b> et il est <b>FACILE à apprendre</b> (beaucoup de listes et de définitions) → ⭐ <b>PRIORITÉ HAUTE : ce sont des points GRATUITS</b>","t":"biocell-methodes EXAM-2026 M111 COURS-OFFICIEL"},{"q":"<b>I-2 — LE MICROSCOPE OPTIQUE</b> : principe, grossissement et les ⭐ <b>12 ÉTAPES de préparation d'une coupe histologique</b> (question classique)","a":"<b>🔴 LE PRINCIPE (I-2-1) :</b><br>• ⭐ « <b>Utilise des PHOTONS comme source d'énergie</b> → microscope <b>PHOTONIQUE</b> » ⭐ (⚠️ « Le nom photon vient du grec et signifie « <b>LUMIÈRE</b> »)<br>• « <b>Fournit une image AGRANDIE grâce à des COMBINAISONS DE LENTILLES OPTIQUES :</b><br>&nbsp;&nbsp;<b>1/ L'OCULAIRE côté œil (2 à 10X)</b><br>&nbsp;&nbsp;<b>2/ L'OBJECTIF côté objet (2,5 à 100X)</b> » ⭐<br>• ⭐ <b>LA FORMULE DU GROSSISSEMENT :</b> « La multiplication du grossissement de l'<b>OBJECTIF</b> par celui de l'<b>OCULAIRE</b> permet d'obtenir le <b>GROSSESSEMENT</b> du microscope. »<br>&nbsp;&nbsp;⚠️ <b>EXEMPLE DU COURS : oculaire 10X × objectif 40 = GROSSESSEMENT 400</b> ⭐⭐<br>• ⚠️ <b>Grossissement max du MO ≈ 1 000 à 1 500×</b> · ⭐ <b>POUVOIR DE RÉSOLUTION ≈ 0,2 µm (200 nm)</b> ⭐ <b>CHIFFRE À RETENIR</b> (limite physique imposée par la diffraction de la lumière — critère d'<b>Abbe</b>) ⚠️ <b>Au-delà, c'est du « grandissement vide »</b> ⭐<br><br><b>🔴 LES CONTRAINTES DE L'EXAMEN MICROSCOPIQUE (énoncées par le cours) :</b><br>« ⚠️ L'examen au microscope impose cependant certaines <b>CONTRAINTES</b>, il faut que :<br>• <b>les objets soient MINCES</b><br>• <b>leurs constituants présentent un certain CONTRASTE</b> » ⭐⭐ <b>LES 2 CONTRAINTES — TOMBABLES</b><br><br><b>🔴 LES DEUX GRANDS TYPES DE MICROSCOPES (classement par RÉSOLUTION) :</b><br>• <b>LES MICROSCOPES OPTIQUES (MO / MP)</b> — résolution ~<b>0,2 µm</b><br>• <b>LES MICROSCOPES ÉLECTRONIQUES (ME)</b> — <b>MET</b> et <b>MEB</b> — résolution ~<b>0,2 nm</b> ⭐<br><br><b>🔴 ⭐⭐ LES 12 ÉTAPES DE PRÉPARATION D'UN PRÉLÈVEMENT TISSULAIRE POUR COPE AU MICROTOME À PARAFFINE (LISTE EXACTE DU COURS — À APPRENDRE DANS L'ORDRE) :</b><br><b>1. PRÉLÈVEMENT</b><br><b>2. FIXATION</b> du prélèvement<br><b>3. DÉCALCIFICATION</b> (⚠️ <b>pour les tissus DURS</b> — os, dents) : <b>acide nitrique, EDTA</b> (= acide éthylène diamine tétra-acétique) ⭐⭐ <b>ULTRA PERTINENT EN MÉDECINE DENTAIRE !</b><br><b>4. DÉSHYDRATATION</b> du prélèvement<br><b>5. ÉCLAIRCISSEMENT</b> du prélèvement<br><b>6. IMPRÉGNATION</b> du prélèvement dans la paraffine<br><b>7. INCLUSION</b> du prélèvement dans la paraffine<br><b>8. COUPES</b><br><b>9. COLLAGE</b> des coupes sur les lames histologiques (en verre)<br><b>10. DÉPARAFFINAGE</b> des coupes<br><b>11. RÉHYDRATATION</b> des coupes<br><b>12. COLORATION</b> des coupes<br>puis : <b>DÉSHYDRATATION des coupes → MONTAGE des coupes (entre lame et lamelle : Eukitt, Baume de Canada) → OBSERVATION AU MO</b> ⭐<br><br><b>📋 LE DÉTAIL DE CHAQUE ÉTAPE ⭐ :</b><br><br><b>2. FIXATION</b> — « Préserve la structure de la cellule morte »<br>• ⭐ « <b>Fixateurs : tuent la cellule en gardant en place ses constituants. Créent des LIAISONS CHIMIQUES TRÈS STABLES entre les molécules de la cellule.</b> »<br>• ⚠️ <b>Exemples du cours : FORMALDÉHYDE, FORMOL, BOUIN</b> ⭐ (⚠️ le « <b>Bouin</b> » = acide picrique + formol + acide acétique — excellent pour les biopsies testiculaires et digestives)<br>• ⚠️ Le <b>FORMOL (formaldéhyde à 10 %)</b> = le fixateur le plus utilisé → <b>ponts méthylène (-CH₂-) entre les protéines</b> ⭐<br>• ⚠️ Autres : <b>glutaraldéhyde</b> (pour la ME) · <b>alcool, acétone</b> (fixateurs précipitants) · <b>acide osmique</b> (post-fixation ME, fixe les lipides)<br><br><b>3. DÉCALCIFICATION</b> ⭐⭐ — « pour les tissus DURS »<br>• « <b>Tissus imprégnés de SELS DE CALCIUM (os, dents) → ont une RIGIDITÉ qui les rend IMPROPRES À LA COUPE au microtome.</b> »<br>• « <b>La décalcification = procédé utilisé pour ENLEVER de ces tissus les SELS DE CALCIUM.</b> »<br>• ⚠️ <b>AGENTS :</b> <b>ACIDE NITRIQUE</b> (rapide mais ⚠️ <b>altère les colorations nucléaires</b> et endommage l'ADN — ⚠️ <b>à éviter si on veut faire de la biologie moléculaire</b>) · <b>EDTA</b> (acide éthylène diamine tétra-acétique) — ⭐ <b>lent (plusieurs semaines) mais PRÉSERVE les antigènes, les enzymes et les acides nucléiques</b> ⭐⭐ <b>DIFFÉRENCE TRÈS TOMBABLE</b><br>• ⚠️ Autres : acide formique, acide chlorhydrique, agents chélateurs ioniques<br>• ⭐ <b>EN MÉDECINE DENTAIRE :</b> la décalcification est <b>OBLIGATOIRE</b> pour couper une <b>dent</b> ou de l'<b>os alvéolaire</b> ⭐ <b>SUJET D'EXAMEN ÉVIDENT</b><br><br><b>4. DÉSHYDRATATION</b><br>• « <b>Préparer les tissus à l'inclusion car LA PARAFFINE N'EST PAS MISCIBLE À L'EAU</b> » ⭐<br>• ⭐ <b>« Bains d'ALCOOL de plus en plus CONCENTRÉS : 70°, 95°, 100° »</b> ⭐ <b>L'ORDRE EST CROISSANT</b> ⚠️ (ne pas confondre avec la réhydratation qui est DÉCROISSANTE)<br><br><b>5. ÉCLAIRCISSEMENT</b> — « passage dans un <b>SOLVANT ORGANIQUE (TOLUÈNE ou XYLÈNE)</b> » ⭐<br>• ⚠️ Rôle : intermédiaire entre l'alcool et la paraffine (le toluène est miscible aux 2)<br><br><b>6-7. IMPRÉGNATION ET INCLUSION</b><br>• <b>Imprégnation</b> : « par la <b>PARAFFINE PURE LIQUIDE À L'ÉTUVE (56 – 60 °C)</b> » ⭐ ⚠️ <b>« passage dans 3 BAINS »</b> ⭐<br>• <b>Inclusion</b> : « <b>RIGIDIFIE le tissu pour faciliter sa coupe et éviter la déformation des cellules lors de la coupe</b>. Paraffine ou paraplast → <b>56 – 60 °C</b>. Barres en « L », moules en plastique, moules en métal » ⭐<br><br><b>8. COUPES = MICROTOMIE</b> ⭐<br>• ⭐ <b>« MICROTOME (2 à 7 µm) »</b> ⭐ <b>CHIFFRE À RETENIR</b><br>• ⚠️ Pour la <b>ME</b>, les coupes doivent être <b>ULTRAFINES : 40 à 60 nm</b> (avec un <b>ultramicrotome</b>) ⭐<br><br><b>9. COLLAGE DES COUPES SUR LES LAMES</b><br>• « S'effectue sur une <b>PLATINE CHAUFFANTE</b> »<br>• ⭐ <b>Lames sans prétraitement</b> → collage avec de l'<b>EAU GÉLATINEUSE</b> ou de l'<b>EAU ALBUMINEUSE</b> ⭐<br>• ⭐ <b>Lames prétraitées au SILANE</b> → collage avec de l'<b>EAU</b> ⭐ <b>DISTINCTION TOMBABLE</b><br><br><b>10. DÉPARAFFINAGE</b> — « à l'aide d'un <b>SOLVANT de la paraffine : TOLUÈNE, XYLÈNE</b> »<br><b>11. RÉHYDRATATION</b> ⭐<br>• « Étape <b>INDISPENSABLE, PRÉALABLE À LA COLORATION</b> car <b>LA PLUPART DES COLORANTS SONT HYDROPHILES</b> » ⭐⭐<br>• ⭐ <b>« Bains d'alcool à TITRE DÉCROISSANT : 100°, 95°, 70° »</b> ⭐ ⚠️ <b>ORDRE INVERSE de la déshydratation !</b><br>• « Remplacement progressif de la paraffine par l'eau »<br><br><b>12. COLORATION</b> — voir la carte suivante<br><br><b>FINALEMENT :</b><br>• <b>Déshydratation des coupes</b> : « bains d'alcool de plus en plus concentrés (<b>70°, 95°, 100°</b>) »<br>• <b>Montage des coupes</b> : ⭐ « <b>entre LAME et LAMELLE : EUKITT, BAUME DE CANADA</b> » ⭐<br>• <b>Observation au MO</b><br><br>⚠️ <b>MNÉMOTECHNIQUE POUR RETENIR LES ÉTAPES :</b> « <b>P</b>etit <b>F</b>rère <b>D</b>ors, <b>D</b>ors <b>E</b>n <b>I</b>ntelligence, <b>I</b>ntelligemment <b>C</b>oupe, <b>C</b>olle, <b>D</b>éparaffine, <b>R</b>éhydrate, <b>C</b>olore » = <b>P-F-D-D-E-I-I-C-C-D-R-C</b>","t":"biocell-methodes EXAM-2026 M111"},{"q":"<b>LA COLORATION</b> : ⭐ qu'est-ce qu'un colorant, ⭐ la différence <b>ACIDE / BASIQUE</b>, et les colorations <b>TOPOGRAPHIQUES vs SPÉCIALES</b> ?","a":"<b>🔴 1. DÉFINITION D'UN COLORANT :</b><br>📖 « <b>Un colorant = RÉACTIF capable de teindre une substance ou un ensemble de substances de manière DURABLE.</b> » ⭐<br><br>📖 « <b>Il doit présenter 2 PROPRIÉTÉS :</b><br>• <b>Posséder des GROUPEMENTS qui lui confèrent une COULEUR : les CHROMOPHORES</b><br>• <b>Posséder des GROUPEMENTS qui assurent sa FIXATION PERMANENTE sur la structure à teindre : les AUXOCHROMES</b> » ⭐⭐<br><br><b>🔴 ⭐⭐ LA CLASSIFICATION ACIDE / BASIQUE (par la CHARGE des AUXOCHROMES) :</b><br>📖 « <b>La CHARGE des AUXOCHROMES permet de distinguer :</b><br>• <b>Les COLORANTS ACIDES (= COLORANTS CYTOPLASMIQUES)</b><br>• <b>Les COLORANTS BASIQUES (= COLORANTS NUCLÉAIRES)</b> » ⭐⭐⭐ <b>C'EST LA QUESTION LA PLUS CLASSIQUE</b><br><br>⚠️ ⭐ <b>LE PRINCIPE À COMPRENDRE (affinité électrostatique) :</b><br>• <b>COLORANT BASIQUE</b> (chargé <b>+</b>) → se fixe sur les structures <b>ACIDES</b> (chargées <b>−</b>) = <b>BASOPHILES</b><br>&nbsp;&nbsp;→ ⭐ <b>L'ADN et l'ARN</b> sont chargés négativement (groupements <b>phosphate</b>) → ⭐ <b>ils sont BASOPHILES → ils fixent les colorants BASIQUES</b> ⭐⭐<br>&nbsp;&nbsp;→ ⚠️ Donc les structures riches en acides nucléiques = <b>noyau, chromatine, nucléole</b> + les <b>ribosomes</b> (RER) + le <b>cytoplasme riche en ARN</b> sont <b>BASOPHILES</b><br>• <b>COLORANT ACIDE</b> (chargé <b>−</b>) → se fixe sur les structures <b>BASIQUES</b> (chargées <b>+</b>) = <b>ACIDOPHILES / ÉOSINOPHILES</b><br>&nbsp;&nbsp;→ ⭐ <b>Les protéines cytoplasmiques</b> (chargées + au pH histologique) → ⭐ <b>elles sont ACIDOPHILES/ÉOSINOPHILES</b><br>&nbsp;&nbsp;→ ⚠️ Exemples : <b>cytoplasme, fibres de collagène, fibres musculaires, hématies éosinophiles</b><br><br><b>🔴 2. LES 2 GRANDES CATÉGORIES DE COLORATIONS</b><br><br><b>📗 A. LES COLORATIONS TOPOGRAPHIQUES (de base)</b><br>• « <b>Mettre en évidence : NOYAU, CYTOPLASME</b> »<br>• « <b>Donner une idée sur la TOPOGRAPHIE GÉNÉRALE du tissu</b> »<br>• ⭐ <b>EXEMPLE : L'HÉMATOXYLINE-ÉOSINE (H&amp;E)</b> ⭐⭐ <b>LA COLORATION DE RÉFÉRENCE EN HISTOLOGIE</b><br>• ⚠️ « <b>(H&amp;E + SAFRAN → noyau, cytoplasme et FIBRES DE COLLAGÈNE)</b> » ⭐<br><br>⚠️ <b>DÉTAIL DE L'H&amp;E — À CONNAÎTRE PAR CŒUR :</b><br>• ⭐ <b>HÉMATOXYLINE</b> : « <b>L'hématéine est un COLORANT BASIQUE</b> »<br>&nbsp;&nbsp;– ⚠️ « <b>VIOLET À NOIR</b> selon l'épaisseur de la coupe et la concentration du colorant »<br>&nbsp;&nbsp;– ⭐ « <b>Coloration des substances ACIDES des NOYAUX CELLULAIRES</b> »<br>&nbsp;&nbsp;– ⚠️ <b>L'hématoxyline colore le NOYAU en BLEU-VIOLET</b> ⭐<br>&nbsp;&nbsp;– ⚠️ ⭐ <b>ATTENTION PIÈGE :</b> <b>l'hématoxyline N'EST PAS elle-même le colorant actif</b> — elle doit être <b>OXYDÉE en HÉMATÉINE</b> (par maturation naturelle à l'air/lumière, ou par un agent oxydant chimique = « mordançage ») ⭐ · ⚠️ le « <b>MORDANT</b> » (sels d'aluminium, de fer — ex. <b>alun</b>) forme un complexe qui se fixe sur la chromatine ⭐<br>• ⭐ <b>ÉOSINE</b> : « <b>L'éosine est un COLORANT ACIDE</b> »<br>&nbsp;&nbsp;– ⚠️ « <b>ROUGE À ROSE PÂLE</b> selon l'épaisseur de la coupe et la concentration du colorant »<br>&nbsp;&nbsp;– ⭐ « <b>Coloration des composants BASIQUES du CYTOPLASME</b> »<br>&nbsp;&nbsp;– ⚠️ <b>L'éosine colore le CYTOPLASME en ROSE/ROUGE</b> ⭐<br><br><b>📕 B. ⭐⭐ LES COLORATIONS SPÉCIALES (tableau du cours — À APPRENDRE PAR CŒUR) :</b><br><br><b>👉 FIBRES CONJONCTIVES :</b><br>• <b>Méthode de VAN GIESON</b> → <b>collagène en ROUGE</b> ⭐<br>• <b>TRICHROME DE MASSON</b> → <b>fibres de collagène en BLEU ou VERT</b> ⭐⭐<br>• <b>Méthode de GOMORI</b> → <b>fibres de RÉTICULINE en NOIR</b> ⭐ (⚠️ imprégnation argentique)<br><br><b>👉 SUBSTANCES GLUCIDIQUES :</b><br>• <b>PAS</b> (Periodic Acid Schiff) → <b>ROSE à ROUGE POURPRE / ROUGE-VIOLET</b> ⭐⭐ ⚠️ ⭐ <b>LE PLUS UTILISÉ</b> — met en évidence les <b>glycogène, mucus, membrane basale, glycoprotéines</b> ⭐ <b>ex. membrane basale épaissie dans le diabète, maladie de Wegener, les champignons (PAS+)</b><br>• <b>ROUGE CONGO</b> → <b>ROSE à ORANGE</b> ⭐ ⚠️ ⭐ <b>colorant de l'AMYLOSE</b> (avec ⚠️ <b>biréfringence VERT POMME en lumière POLARISÉE</b>) ⭐⭐<br>• <b>BLEU ALCIAN</b> → « <b>substances polysaccaridiques SÉCRÉTÉES par certaines cellules ÉPITHÉLIALES</b> » ⭐ ⚠️ colore les <b>mucines acides</b> en BLEU ⭐ <b>ex. cellules caliciformes</b> ⭐ <b>PERTINENT EN DENTAIRE : glandes salivaires</b><br><br><b>👉 SUBSTANCES LIPIDIQUES :</b><br>• <b>HUILE ROUGE O</b> (Oil Red O) → <b>ROUGE</b> ⭐ ⚠️ ⭐ <b>sur coupe en CONGÉLATION</b> (car les solvants de la paraffine <b>DISSOLVENT les lipides</b>) ⭐⭐<br>• <b>NOIR SOUDAN</b> → <b>NOIR</b> ⭐ (même contrainte)<br><br><b>👉 PROTÉINES :</b><br>• <b>Méthode de GRAM-WEIGERT</b> → <b>BLEU-NOIR</b> ⭐ (coloration de la <b>fibrine</b>) ⚠️ ⭐ <b>ATTENTION : à ne pas confondre avec la coloration de GRAM en bactériologie</b> ⭐<br><br><b>📋 AUTRES COLORATIONS CLASSIQUES (bonus) :</b><br>• <b>MAY-GRÜNWALD-GIEMSA (MGG)</b> → ⭐ <b>FROTTIS SANGUIN</b> (voir carte suivante)<br>• <b>PAPANICOLAOU (Pap)</b> → ⭐ <b>frottis gynécologiques et buccaux</b> ⭐<br>• <b>BLEU DE MÉTHYLÈNE / BLEU DE TOLUIDINE</b> → <b>cellules épithéliales, mastocytes (métachromasie)</b> ⭐<br>• <b>PERLS</b> → <b>FER (hémosidérine) en BLEU</b> · <b>VON KOSSA</b> → <b>CALCIUM en NOIR</b> ⭐⭐ <b>ULTRA PERTINENT EN DENTAIRE (minéralisation, émail, dentine, os)</b><br>• <b>ARGENT (Gomori, Warthin-Starry)</b> → réticuline, champignons, bactéries<br>• <b>ZIEHL-NEELSEN</b> → <b>BK (bacille de Koch)</b> — ⭐ <b>BAAR (Bacille Acido-Alcoolo-Résistant)</b><br>• ⭐ <b>IMMUNOHISTOCHIMIE (IHC)</b> : <b>anticorps</b> + <b>chromogène DAB (brun)</b> → ⚠️ <b>marqueurs : Ki-67 (prolifération), cytokératines, CD3/CD20, p53, HER2, RE/RP</b> ⭐<br>• ⭐ <b>HYBRIDATION IN SITU (ISH/FISH)</b> : sonde nucléotidique (⚠️ <b>lien avec le cours de Pr ROCHD !</b>)<br><br><b>📋 LE RÔLE DE LA COLORATION (énoncé du cours) :</b><br>• « <b>Moyen dont on dispose pour DISTINGUER les diverses structures du tissu.</b> »<br>• « <b>Faire ressortir les DIFFÉRENCES dans la COMPOSITION CHIMIQUE des structures tissulaires → chaque composant tissulaire a un COMPORTEMENT PARTICULIER face aux colorants.</b> » ⭐<br>• « <b>AUGMENTE LE CONTRASTE entre les structures cellulaires.</b> » ⭐","t":"biocell-methodes EXAM-2026 M111"},{"q":"<b>LES PRÉLÈVEMENTS CYTOLOGIQUES</b> : ⭐ le <b>FROTTIS SANGUIN (MGG)</b> et le ⭐ <b>FROTTIS BUCCAL</b> (cytologie exfoliatrice)","a":"<b>🔴 LES 2 TYPES DE PRÉLÈVEMENTS (I-2-2) :</b><br><br><b>📗 A. PRÉLÈVEMENTS TISSULAIRS</b> ⭐ (vus dans la carte précédente)<br>📖 Exemples du cours :<br>• <b>BIOPSIE</b> : « fragment de tissus / être vivant »<br>• <b>BIOPSIE-EXÉRÈSE</b> : « prélèvement de la <b>TOTALITÉ de la LÉSION</b> » ⭐<br>• <b>PONCTION-BIOPSIE</b> : « prélèvement d'une « <b>CAROTTE</b> » tissulaire (<b>aiguille / trocart</b>) » ⭐<br><br><b>📘 B. ⭐ PRÉLÈVEMENTS CYTOLOGIQUES</b> — ⚠️ <b>beaucoup plus simples, pas de coupe</b><br>📖 Exemples du cours : « par <b>GRATTAGE, BROSSAGE, PONCTION À L'AIGUILLE, RECUEIL DE LIQUIDE DE LAVAGE, recueil de produits de SÉCRÉTION / ÉCOULEMENT, APPOSITION sur une lame de microscope d'un prélèvement FRAIS</b> » ⭐<br><br><b>🔴 ⭐⭐ EXEMPLE 1 : LE FROTTIS SANGUIN — COLORATION MAY-GRÜNWALD-GIEMSA (MGG)</b><br><br><b>📖 PRINCIPE :</b> « Le frottis sanguin consiste en la réalisation d'un <b>ÉTALEMENT MONOCELLULAIRE des ÉLÉMENTS SANGUINS</b>. » ⭐<br><br><b>📖 MATÉRIEL :</b> « <b>2 lames</b> + <b>une aiguille stérilisée</b> » ⭐<br><br><b>📖 MODE OPÉRATOIRE (4 temps) :</b><br>1. « À l'aide d'une aiguille stérilisée, <b>PIQUEZ LE BOUT D'UN DOIGT</b>. Placez une <b>GOUTTE DE SANG (3 mm de diamètre)</b> à l'extrémité d'une lame (lame porte-objet) » ⭐<br>2. ⭐ « Avec la deuxième lame tenue <b>À 45 DEGRÉS</b> par rapport à la première, <b>TOUCHER LA GOUTTE</b> de sang puis l'<b>ÉTALER d'un MOUVEMENT BREF</b> sur la première lame pour obtenir un étalement fin. » ⭐ ⚠️ <b>L'ANGLE DE 45° EST TOMBABLE</b><br>3. « <b>SÉCHER AUSSITÔT en AGITANT la lame.</b> » ⭐<br>⚠️ ⭐ « Le sang s'étale par <b>CAPILLARITÉ</b> » — « faire glisser la lame 2 ⇒ entraînement du sang par capillarité » ⭐<br><br><b>📖 LA COLORATION MGG — PROTOCOLE EXACT (5 étapes) ⭐ :</b><br>1. « Placer la lame du frottis sur un <b>SUPPORT HORIZONTAL</b> »<br>2. ⭐ « Verser sur la lame <b>15 GOUTTES de colorant MAY-GRÜNWALD</b> de façon à recouvrir complètement le frottis. <b>Laisser agir 3 MIN</b>. » ⭐<br>3. « <b>REJETER le colorant par un JET D'EAU NEUTRE.</b> »<br>4. ⭐ « Colorer avec la <b>SOLUTION DE GIEMSA pendant 10 MIN</b>. » ⭐<br>5. « <b>RINCER</b> sous un jet d'eau neutre. <b>Laisser SÉCHER la lame à l'AIR, en POSITION INCLINÉE</b>, après avoir essuyé la face inférieure de la lame avec du papier filtre. » ⭐<br>6. ⭐ « <b>ATTENDRE AU MOINS 5 MIN</b> avant l'examen microscopique du frottis. » ⭐<br><br>⚠️ <b>LES CHIFFRES À RETENIR :</b> <b>15 gouttes</b> de May-Grünwald · <b>3 min</b> May-Grünwald · <b>10 min</b> Giemsa · <b>5 min</b> d'attente · <b>45°</b> d'inclinaison · goutte de <b>3 mm</b> ⭐<br><br><b>📖 ⭐⭐ LES 5 TYPES DE CELLULES SANGUINES À SAVOIR IDENTIFIER (décrits dans le cours) :</b><br>• <b>HÉMATIES (= globules rouges)</b> : sans noyau, <b>disque biconcave</b>, ⭐ <b>ÉOSINOPHILES (roses/orangées)</b>, ~<b>7,5 µm</b> ⭐<br>• <b>GRANULOCYTE NEUTROPHILE</b> : ⭐ « <b>NOYAU DIFFORME, comportant des régions larges, les LOBES, réunis par de fines RELATIONS</b> » ⭐ ⚠️ <b>2 à 5 lobes</b> (le « <b>neutrophile à noyau segmenté</b> » — ⚠️ <b>un neutrophile à plus de 5 lobes = carence en B9/B12 = « hypersegmentation »</b> ⭐) · granulations neutrophiles · <b>50-70 % des GB</b> ⭐<br>• <b>GRANULOCYTE ÉOSINOPHILE</b> : ⭐ <b>NOYAU BILOBÉ</b> ⭐ (en « lunettes ») + « cytoplasme avec <b>GRANULATIONS</b> » ⭐ <b>volumineuses, orangées</b> · <b>1-4 %</b> · ⚠️ <b>parasitoses, allergie</b><br>• <b>GRANULOCYTE BASOPHILE</b> : ⭐ « <b>NOYAU MASQUÉ PAR LES GROSSES GRANULATIONS</b> » ⭐ (noyau en « S » masqué par des granulations <b>violet foncé</b>) · <b>&lt;1 %</b><br>• <b>LYMPHOCYTE</b> : ⭐ « <b>cellule RONDE avec un NOYAU ROND, VOLUMINEUX et PEU DE CYTOPLASME</b> » ⭐ · <b>20-40 %</b> ⭐ ⚠️ ⭐ <b>ATTENTION PIÈGE CLASSIQUE :</b> <b>le LYMPHOCYTE a le MÊME DIAMÈTRE qu'une hématie (~7-8 µm)</b> — ne pas le confondre avec un monocyte ⭐<br>• <b>MONOCYTE</b> : ⭐ « <b>cellule RONDE avec un NOYAU EN FORME DE HARICOT</b> » ⭐ (noyau réniforme/encoché, cytoplasme <b>gris bleuté</b> abondant, souvent vacuolisé) · <b>2-8 %</b> · ⚠️ <b>la PLUS GROSSE cellule sanguine : 15-20 µm</b> ⭐<br>• ⚠️ <b>PLAQUETTES (thrombocytes)</b> : <b>2-3 µm</b>, fragments de mégacaryocytes, <b>150-400 ×10⁹/L</b><br><br><b>🔴 ⭐⭐ EXEMPLE 2 : LE FROTTIS BUCCAL (CYTOLOGIE EXFOLIATRICE) ⭐⭐ ULTRA PERTINENT EN MÉDECINE DENTAIRE</b><br><br><b>📖 DÉFINITION :</b> « La <b>CYTOLOGIE EXFOLIATRICE</b> étudie <b>LES CELLULES QUI SE DÉTACHENT NATURELLEMENT D'UN ÉPITHÉLIUM</b> » ⭐<br>⚠️ <b>Exemples du cours :</b> <b>frottis vaginaux, frottis buccaux, cellules de la muqueuse bronchique dans les crachats</b> ⭐<br><br><b>📖 ⭐ LES AVANTAGES (énumération exacte — 4 points) :</b><br>• « <b>Méthode NON AGRESSIVE</b> » ⭐<br>• « <b>FACILE À RÉALISER DANS LA BOUCHE</b> » ⭐<br>• « <b>Donne des RÉSULTATS RAPIDES</b> » ⭐<br>• « Utilisée pour le <b>DIAGNOSTIC de différentes affections BUCCALES</b>, en particulier afin d'identifier certaines <b>affections spécifiques de la MUQUEUSE BUCCALE</b> » ⭐⭐<br><br><b>📖 L'INCONVÉNIENT :</b> « ⚠️ <b>Ne permet pas souvent l'établissement d'un DIAGNOSTIC DÉFINITIF.</b> » ⭐⭐ <b>POINT TOMBABLE</b><br>→ ⚠️ C'est une méthode de <b>DÉPISTAGE / ORIENTATION</b> — un diagnostic définitif nécessite une <b>BIOPSIE</b> avec examen anatomopathologique ⭐<br><br><b>📖 MATÉRIEL :</b> « une <b>LAME HISTOLOGIQUE PROPRE, STÉRILE</b> · une <b>SOLUTION FIXATRICE : ALCOOL/ÉTHER ou ÉTHYLÈNE/GLYCOL</b> ⭐ · un <b>ABAISSE-LANGUE</b> » ⭐<br><br><b>📖 MODE OPÉRATOIRE (5 temps) :</b><br>1. « Passer une <b>COMPRESSE HUMIDE</b> au niveau du site lésé (<b>élimination des MUCOSITÉS</b>) » ⭐<br>2. « <b>GRATTER plusieurs fois la surface de la LÉSION</b> au moyen d'un <b>ABAISSE-LANGUE</b> ou d'une <b>SPATULE EN MÉTAL</b> » ⭐<br>3. « <b>ÉTALER le produit de RACLAGE sur lame</b> »<br>4. « <b>FIXER IMMÉDIATEMENT</b> » ⭐<br>5. ⭐ « <b>COLORATION</b> (<b>H&amp;E, PAPANICOLAOU, BLEU DE MÉTHYLÈNE</b>) » ⭐ ⚠️ <b>LES 3 COLORANTS CITÉS — TOMBABLES</b><br><br>⚠️ <b>APPLICATIONS CLINIQUES EN MÉDECINE DENTAIRE ⭐ :</b> dépistage des <b>lésions potentiellement malignes</b> et des <b>cancers buccaux</b> · diagnostic des <b>infections virales</b> (⚠️ <b>cellules de Tzanck</b> dans l'herpès) · <b>candidose</b> · <b>lichen plan buccal</b> · ⭐ <b>détection du HPV</b> (ADN viral par PCR/hybridisation in situ sur cellules exfoliées) ⭐ <b>LIEN AVEC LE COURS DE GÉNIE GÉNÉTIQUE !</b><br>• ⚠️ ⭐ <b>Les CELLULES ÉPITHÉLIALES BUCCALES</b> (coloration <b>bleu de méthylène</b>) — ⭐ <b>ce sont la SOURCE D'ADN la plus simple pour un test génétique</b> (frottis buccal, « buccal swab ») ⭐⭐","t":"biocell-methodes EXAM-2026 M111"},{"q":"<b>2.3 — LA COUPE EN CONGÉLATION (CRYOTOMIE)</b> : principe, ⭐ les 2 indications et le protocole","a":"<b>🔴 LE PRINCIPE :</b><br>📖 « <b>Principe de la congélation : c'est le DURCISSEMENT DU TISSU grâce à la CONGÉLATION DE L'EAU qu'il contient.</b> » ⭐<br><br><b>🔴 ⭐⭐ LES 2 INDICATIONS DE LA CRYOTOMIE (énumération exacte du cours) :</b><br><b>1.</b> ⭐ « <b>Le CHIRURGIEN a besoin, EN COURS D'OPÉRATION, d'avoir la CONFIRMATION DU DIAGNOSTIC : la RAPIDITÉ de la méthode est alors mise à profit</b> » ⭐⭐<br>&nbsp;&nbsp;→ ⭐ <b>LES EXAMENS EXTEMPORANÉS</b> ⭐ (= « <b>gain de temps</b> ») — ⚠️ <b>on évite ainsi la longue inclusion en paraffine (12-24 h)</b> ⭐<br>&nbsp;&nbsp;→ Exemples : <b>contrôle des limites d'exérèse tumorales</b> (« marges saines ? »), nature d'une masse per-opératoire, recherche de ganglion sentinelle ⭐ ⚠️ <b>EN MÉDECINE DENTAIRE : contrôle des berges d'exérèse d'un carcinome épidermoïde buccal ou d'un kyste</b> ⭐<br><br><b>2.</b> ⭐ « <b>Certaines des étapes préparatoires à l'INCLUSION À LA PARAFFINE sont susceptibles de NUIRE À LA PRÉSERVATION des substances qu'il faut mettre en évidence.</b> » ⭐⭐<br>&nbsp;&nbsp;📖 <b>LES 3 EXEMPLES DU COURS :</b><br>&nbsp;&nbsp;Þ <b>Techniques d'HISTOENZYMOLOGIE</b> (les <b>ENZYMES</b>) ⭐ — ⚠️ car la chaleur de la paraffine (56-60 °C) et les fixateurs <b>DÉNATURENT les enzymes</b> ⭐⭐ <b>LA RAISON LA PLUS IMPORTANTE</b><br>&nbsp;&nbsp;Þ <b>Certaines techniques d'IMMUNOHISTOCHIMIE</b> ⭐ — ⚠️ car les solvants organiques (toluène, xylène) <b>MASQUENT LES ÉPITOPES</b> ⭐<br>&nbsp;&nbsp;Þ <b>Les LIPIDES</b> ⭐ — ⚠️ car les solvants organiques de la déshydratation et de l'éclaircissement <b>DISSOLVENT LES LIPIDES</b> ⭐⭐<br><br><b>🔴 LE PROTOCOLE ⭐ :</b><br>1. ⭐ « La pièce à couper est introduite dans l'<b>ISOPENTANE (= CRYOPROTECTEUR)</b> préalablement <b>REFROIDI (-160 °C)</b> dans l'<b>AZOTE LIQUIDE</b>. » ⭐<br>2. ⭐ « <b>Remarque : l'AZOTE LIQUIDE a une température de l'ordre de (-196 °C)</b> » ⭐ <b>CHIFFRE À RETENIR</b><br>3. ⚠️ Durée : <b>30 s à 1 min</b> ⭐<br><br><b>🔴 LA COUPE :</b><br>• ⭐ « Les coupes sont réalisées à l'aide d'un <b>CRYOSTAT</b> = <b>ENCEINTE RÉFRIGÉRÉE ENTRE (-18 °C ET -20 °C)</b> contenant le <b>MICROTOME</b>. » ⭐⭐ <b>CHIFFRES À RETENIR</b><br>• ⚠️ Épaisseur des coupes : <b>5 à 10 µm</b> (plus épaisses qu'en paraffine)<br>• ⚠️ L'échantillon est dit « <b>frais congelé</b> »<br><br><b>📋 ⭐ LE TABLEAU RÉCAPITULATIF — CONGÉLATION vs PARAFFINE :</b><br>• <b>Durcissement</b> : Congélation = <b>par le FROID</b> (congélation de l'eau) · Paraffine = <b>par IMPRÉGNATION</b> à 56-60 °C<br>• <b>Délai</b> : Congélation = ⭐ <b>~10-20 MINUTES</b> (rapide → extemporané) · Paraffine = <b>12 à 24 HEURES</b> ⭐<br>• <b>Épaisseur</b> : Congélation = <b>5-10 µm</b> · Paraffine = <b>2-7 µm</b> ⭐<br>• <b>Qualité morphologique</b> : Congélation = ⚠️ <b>MÉDIOCRE</b> (artéfacts de congélation : cristaux de glace, déchirures) · Paraffine = ⭐ <b>EXCELLENTE</b> ⭐⭐<br>• <b>Conservation</b> : Congélation = ⚠️ <b>limitée</b> (à -80 °C) · Paraffine = ⭐ <b>des DÉCENNIES</b> à température ambiante (blocs et lames) ⭐<br>• <b>Préservation</b> : Congélation = ⭐ <b>ENZYMES, LIPIDES et ANTIGÈNES PRÉSERVÉS</b> · Paraffine = ⚠️ <b>détruits</b> ⭐⭐<br>• <b>Indications</b> : Congélation = <b>extemporané, histoenzymologie, IHC, lipides</b> · Paraffine = <b>routine, archives, morphologie fine</b><br><br>⚠️ <b>LES CHIFFRES À RETENIR :</b> <b>isopentane</b> (cryoprotecteur) · <b>-160 °C</b> · <b>azote liquide -196 °C</b> · <b>30 s à 1 min</b> · <b>cryostat -18 à -20 °C</b> ⭐<br><br>⚠️ <b>BONUS — LES AUTRES CRYOPROTECTEURS :</b> <b>saccharose (sucrose)</b> en solution, <b>OCT (Optimal Cutting Temperature compound = Tissue-Tek)</b> ⭐ — le milieu d'inclusion le plus utilisé en routine pour la congélation. ⚠️ ⭐ <b>SANS cryoprotecteur, l'eau en gelant forme des CRISTAUX DE GLACE qui LACÈRENT les membranes cellulaires</b> → artéfacts ⭐","t":"biocell-methodes EXAM-2026 M111"},{"q":"⭐⭐ <b>LES DIFFÉRENTS MICROSCOPES OPTIQUES</b> (2.4) : fond clair, contraste de phase, fluorescence, confocale, fond noir, lumière polarisée, réflexion — principe et application de chacun","a":"<b>🔴 ⭐⭐ TABLEAU RÉCAPITULATIF — À APPRENDRE (le cours en cite 7) :</b><br><br><b>1. MICROSCOPE À FOND CLAIR</b> ⭐<br>• « Il s'agit d'un <b>MICROSCOPE NORMAL</b> (= microscope <b>DROIT</b>) utilisé en <b>TRANSMISSION</b>. » ⭐<br>• ⭐ <b>APPLICATIONS (4 citées) :</b> <b>HISTOLOGIE</b> · <b>HÉMATOLOGIE</b> · <b>PARASITOLOGIE</b> · <b>BACTÉRIOLOGIE</b> ⭐<br>• ⚠️ ⭐ <b>C'EST LE MICROSCOPE DE ROUTINE = celui qu'on utilise pour les LAMES D'HISTOLOGIE (H&amp;E)</b> ⭐ — la lumière traverse l'objet, l'objet coloré apparaît <b>foncé sur fond clair</b><br><br><b>2. MICROSCOPE À CONTRASTE DE PHASE</b> ⭐⭐<br>• ⭐ <b>APPLICATION (énoncé exact) :</b> « <b>Permet l'observation des préparations « AYANT UN RELIEF », NON FIXÉES, NON COLORÉES : ÉTALEMENT DE CELLULES, CULTURES DE CELLULES, CELLULES VIVANTES.</b> » ⭐⭐⭐<br>• ⚠️ <b>PRINCIPE</b> (bonus) : convertit les <b>déphasages</b> (différences d'indice de réfraction) en <b>différences d'intensité lumineuse</b> — ⭐ <b>inventé par Frits Zernike (Prix Nobel de physique 1953)</b> ⭐<br>• ⚠️ ⭐ <b>AVANTAGE MAJEUR :</b> <b>on peut observer des CELLULES VIVANTES sans les tuer par la fixation/coloration</b> ⭐ — indispensable en <b>culture cellulaire</b><br>• ⭐ <b>L'EXEMPLE DU COURS : LA DENT (ÉMAIL)</b> ⭐⭐ <b>ULTRA PERTINENT EN MÉDECINE DENTAIRE</b><br>&nbsp;&nbsp;– « Observation au microscope photonique à contraste de phase : <b>COUPE obtenue par PONÇAGE (COUPE PAR USURE), PAS DE COLORATION</b> » ⭐<br>&nbsp;&nbsp;– ⭐ <b>LÉGENDE DU SCHÉMA :</b> <b>E = émail · D = dentine · P = pulpe · O = fragments osseux · C = cément</b> ⭐⭐ <b>À CONNAÎTRE</b><br>&nbsp;&nbsp;– ⚠️ <b>POURQUOI LE PONÇAGE ?</b> Parce que l'<b>ÉMAIL est le tissu le plus DUR de l'organisme</b> → ⚠️ <b>on ne peut PAS le couper au microtome</b> → ⭐ on fait une <b>« coupe par usure »</b> (on ponce la dent jusqu'à obtenir une lame mince translucide) ⭐⭐ <b>CONCEPT CLÉ EN DENTAIRE</b><br>• ⚠️ 2ᵉ exemple du cours : « une <b>cellule d'embryon de souris</b> visualisée en contraste de phase. ⭐ <b>Les contours sont entourés d'une LIGNE BLANCHE</b>. » ⭐ <b>DÉTAIL TOMBABLE</b><br><br><b>3. MICROSCOPE À FLUORESCENCE</b> ⭐⭐<br>• « <b>Permet de VISUALISER des MOLÉCULES FLUORESCENTES ENDOGÈNES ou (SURTOUT) EXOGÈNES.</b> » ⭐<br>• « <b>La source lumineuse est DÉPORTÉE SUR LE CÔTÉ et est constituée par une LAMPE offrant un SPECTRE DE LONGUEUR D'ONDE ÉTENDU VERS LES UV.</b> » ⭐ ⚠️ <b>DÉTAIL TECHNIQUE TOMBABLE</b><br>• « <b>Un FILTRE D'EXCITATION permet de sélectionner une BANDE DE LONGUEUR D'ONDE ADAPTÉE AU FLUOROCHROME à visualiser.</b> » ⭐<br>• ⚠️ <b>PRINCIPE</b> : un fluorochrome absorbe à une λ courte (<b>excitation</b>) et réémet à une λ plus longue (<b>émission</b>) — ⭐ <b>décalage de Stokes</b> ⭐<br>• ⚠️ <b>FLUOROCHROMES CLASSIQUES :</b> <b>FITC</b> (vert, 495/520 nm) · <b>TRITC / rhodamine</b> (rouge) · <b>DAPI</b> ⭐ (bleu, ⚠️ <b>se fixe sur l'ADN</b> → marque les noyaux) · <b>GFP</b> (Green Fluorescent Protein, ⭐ <b>Prix Nobel 2008 : Shimomura, Chalfie, Tsien</b>) · <b>Hoechst</b> (bleu, ADN) · <b>phalloidine</b> (F-actine)<br>• ⭐ <b>APPLICATIONS :</b> <b>IMMUNOFLUORESCENCE</b> (anticorps couplés au fluorochrome → ⭐ <b>IFI directe/indirecte</b> — ex. <b>dépôts d'IgG</b> en IFD dans le <b>pemphigus/pemphigoïde</b> ⭐⭐ <b>ULTRA PERTINENT EN MÉDECINE DENTAIRE ET STOMATOLOGIE</b>) · <b>FISH</b> ⭐ (⚠️ <b>lien avec la cytogénétique et les sondes du cours de Pr ROCHD !</b>) · <b>marquage des protéines</b> (GFP) · <b>histologie à fluorescence</b><br><br><b>4. MICROSCOPE CONFOCAL</b> ⭐⭐<br>• ⭐ <b>L'INTÉRÊT (énoncé exact) :</b><br>&nbsp;&nbsp;Ø « <b>Observer l'image « TRANCHE PAR TRANCHE » ou plutôt PLAN PAR PLAN.</b> » ⭐<br>&nbsp;&nbsp;Ø « <b>On peut ensuite RASSEMBLER LES PLANS SUCCESSIFS et RECONSTITUER UNE IMAGE EN 3D.</b> » ⭐⭐<br>• ⚠️ <b>PRINCIPE</b> : un <b>trou sténopéique (pinhole)</b> élimine la lumière hors-focus → ⭐ <b>« section optique »</b> sans couper physiquement → <b>reconstruction 3D</b> ⭐ <b>invention : Marvin Minsky (brevet 1957)</b><br>• ⚠️ <b>Applications</b> : <b>co-localisation de protéines</b>, imagerie du <b>vivant</b> (time-lapse), <b>spectral imaging</b>, ⭐ <b>en dentaire : organisation 3D des tubules dentinaires et des odontoblastes</b><br>• ⚠️ Variantes : <b>biphotonique</b> (plus profond), <b>spinning disk</b> (plus rapide), <b>STED / PALM / STORM</b> = ⭐ <b>microscopie de SUPER-RÉSOLUTION</b> (<b>Prix Nobel de chimie 2014 : Betzig, Hell, Moerner</b>) — ⚠️ franchit la limite de diffraction d'Abbe ⭐<br><br><b>5. MICROSCOPE À FOND NOIR</b><br>• ⭐ <b>APPLICATION :</b> <b>BACTÉRIOLOGIE</b> ⭐<br>• ⚠️ <b>PRINCIPE</b> : un condensateur spécial empêche la lumière directe d'atteindre l'objectif → ⭐ <b>l'objet apparaît CLAIR/BRILLANT sur FOND NOIR</b> (diffusion de la lumière par l'objet) ⭐<br>• ⚠️ ⭐ <b>APPLICATION CÉLÈBRE :</b> ⭐⭐ <b>l'ULTRAMICROSCOPIE pour observer les SPIROCHÈTES</b> — ⚠️ ⭐ <b>ex. : <i>Treponema pallidum</i> (syphilis) et <i>Treponema denticola</i> du « complexe rouge » parodontal</b> ⭐⭐ <b>EXCELLENT EXEMPLE EN MÉDECINE DENTAIRE</b> — ⚠️ ces bactéries sont <b>trop fines</b> pour être vues au fond clair ⭐<br><br><b>6. MICROSCOPE À LUMIÈRE POLARISÉE</b><br>• ⚠️ « <b>TRÈS PEU UTILISÉ EN BIOLOGIE</b> » ⭐ <b>MENTION EXPLICITE DU COURS — TOMBABLE</b><br>• ⭐ <b>APPLICATIONS :</b> « Permet d'observer : des <b>TRANCHES FINES DE ROCHES</b> · des <b>DENTS ET OS NON DÉCALCIFIÉS</b> » ⭐⭐ ⚠️ <b>ULTRA PERTINENT EN DENTAIRE</b><br>• ⚠️ <b>PRINCIPE</b> : les substances <b>BIRÉFRINGENTES / ANISOTROPES</b> dévient la lumière polarisée → ⭐ <b>l'ÉMAIL, la DENTINE, l'OS et le COLLAGÈNE sont BIRÉFRINGENTS</b> ⭐<br>• ⚠️ ⭐ <b>EXEMPLE CLÉ :</b> la <b>COLORATION AU ROUGE CONGO + LUMIÈRE POLARISÉE</b> → ⭐ <b>BIRÉFRINGENCE VERT POMME</b> = <b>diagnostic de l'AMYLOSE</b> ⭐⭐<br>• ⚠️ En dentaire : étude de la <b>minéralisation</b>, de l'<b>orientation des prismes de l'émail</b> et des <b>fibres de Sharpey</b> (insertion du ligament parodontal) ⭐<br><br><b>7. MICROSCOPE À RÉFLEXION</b><br>• ⭐ « On l'utilise dans le cas d'un <b>ÉCHANTILLON OPAQUE</b> où l'on observe la <b>LUMIÈRE QUI EST RÉFLÉCHIE À LA SURFACE</b>. » ⭐<br>• ⭐ <b>APPLICATION :</b> « <b>MICROSTRUCTURE DES MATÉRIAUX après POLISSAGE de l'échantillon et ATTAQUE CHIMIQUE</b> » ⭐⭐<br>• ⚠️ ⭐ <b>ULTRA PERTINENT EN MÉDECINE DENTAIRE :</b> ⭐⭐ c'est le microscope utilisé en <b>SCIENCE DES MATÉRIAUX DENTAIRES</b> (module <b>M114</b>) → étude des <b>alliages métalliques (amalgame, couronnes coulées, implants en titane)</b>, des <b>céramiques dentaires</b> et des <b>résines composites</b> ⭐⭐ <b>LIEN DIRECT AVEC LE MODULE DE MATÉRIAUX</b><br><br><b>📋 RÉSUMÉ — APPLICATION PAR MICROSCOPE ⭐ :</b><br>• <b>Fond clair</b> → <b>histologie, hématologie, parasitologie, bactériologie</b> (routine)<br>• <b>Contraste de phase</b> → <b>cellules VIVANTES non colorées</b>, <b>dent/émail</b> (coupe par ponçage)<br>• <b>Fluorescence</b> → <b>immunofluorescence, FISH</b><br>• <b>Confocal</b> → <b>plans successifs → image 3D</b><br>• <b>Fond noir</b> → <b>bactériologie, spirochètes</b><br>• <b>Lumière polarisée</b> → <b>roches, dents et os NON décalcifiés</b>, amylose<br>• <b>Réflexion</b> → <b>échantillon OPAQUE, microstructure des matériaux</b>","t":"biocell-methodes EXAM-2026 M111"},{"q":"⭐⭐ <b>LE MICROSCOPE ÉLECTRONIQUE À TRANSMISSION (MET)</b> : principe, chiffres, et les étapes de préparation","a":"<b>🔴 LES 2 TYPES PRINCIPAUX DE ME :</b><br>• <b>À TRANSMISSION (MET / TEM)</b> ⭐ = un faisceau d'électrons <b>TRAVERSE</b> la coupe → ⭐ <b>image 2D, ultrastructure interne</b><br>• <b>À BALAYAGE (MEB / SEM)</b> ⭐ = un faisceau d'électrons <b>BALAIE LA SURFACE</b> → ⭐ <b>image 3D de la surface</b> ⭐ (⚠️ résolution ~<b>5-10 nm</b>, grande profondeur de champ — ⭐ <b>en dentaire : surface de l'ÉMAIL, mordançage acide, jonction émail-composite, surface des IMPLANTS</b> ⭐⭐)<br><br>📖 <b>PRINCIPE COMMUN :</b> « <b>CONCENTRER UN FAISCEAU D'ÉLECTRONS sur le spécimen biologique.</b> » ⭐<br><br><b>🔴 ⭐⭐ LE FONCTIONNEMENT DU MET (détail du cours) :</b><br><b>1. LE FAISCEAU D'ÉLECTRONS</b><br>• « <b>Utilise des ÉLECTRONS qui se déplacent dans un TUBE où règne un VIDE TRÈS POUSSÉ.</b> » ⭐ ⚠️ <b>pourquoi le vide ?</b> pour que les électrons ne soient pas arrêtés par les molécules d'air ⭐<br>• ⭐ « <b>Le flux d'électrons est fourni par une CATHODE = FILAMENT DE TUNGSTÈNE chauffé par un COURANT ÉLECTRIQUE.</b> » ⭐ (⚠️ « <b>PINO 3000</b> » = le modèle de microscope photographié dans le cours) ⭐<br>• ⭐ <b>L'ACCÉLÉRATION :</b> « Les électrons sont ensuite accélérés par une <b>ANODE</b> qui permet d'établir une <b>DIFFÉRENCE DE POTENTIEL de <b>50 000 à 100 000 VOLTS</b> pour un microscope normal, de <b>2 à 3 MILLIONS DE VOLTS</b> pour un microscope à HAUT VOLTAGE.</b> » ⭐⭐ <b>CHIFFRES À RETENIR</b><br><br><b>2. LA FORMATION DE L'IMAGE ⭐⭐ (MÉCANISME TOMBABLE) :</b><br>• « Les électrons sont <b>+ ou – DIFFRACTÉS</b> par les structures cellulaires. »<br>• ⭐ « <b>Les électrons NON DIFFRACTÉS sont dirigés sur un ÉCRAN par des lentilles objectifs et une lentille projecteur → ZONE CLAIRE</b> » ⭐<br>• ⭐ « <b>Les électrons DIFFRACTÉS (qui changent de direction) n'atteignent pas l'écran → ZONE SOMBRE sur l'écran</b> » ⭐⭐ <b>À SAVOIR EXPLIQUER</b><br>• ⚠️ ⭐ <b>CONTRASTE ÉLECTRON-DENSE</b> : les zones <b>denses aux électrons</b> (= <b>électron-denses</b>) apparaissent <b>SOMBRES</b> au MET ⭐ — ⚠️ <b>contrairement au microscope optique où les zones colorées apparaissent foncées</b>, ici c'est la <b>densité électronique</b> qui compte<br>• ⚠️ ⭐ <b>C'est pourquoi on utilise des CONTRASTANTS LOURDS</b> : <b>ACÉTATE D'URANYLE</b> et <b>CITRATE DE PLOMB (Reynolds)</b> ⭐⭐ — ils se fixent sur les structures (membranes, acides nucléiques) → ⭐ <b>les rendent ÉLECTRON-DENSES → SOMBRES</b> ⭐ <b>QUESTION CLASSIQUE</b><br>• ⚠️ Autres contrastants : <b>acide phosphotungstique (PTA)</b>, <b>acide osmique</b>, techniques de <b>cryodécapage (freeze-fracture)</b> et de <b>cryo-MET</b> ⭐<br><br><b>3. ⭐⭐ LES PERFORMANCES — CHIFFRES À RETENIR :</b><br>• ⭐ « <b>POUVOIR SÉPARATEUR : voisin du NANOMÈTRE</b> » ⭐ (~<b>0,1 à 0,2 nm</b>) ⚠️ <b>contre 0,2 µm = 200 nm pour le MO</b> → ⭐ <b>~1 000 à 2 000 fois meilleur</b> ⭐⭐<br>• ⭐ « <b>AGRANDISSEMENT varie entre ×1 500 et ×600 000</b> » ⭐⭐ <b>CHIFFRES EXACTS DU COURS</b><br>• ⭐ « <b>Observation des ULTRASTRUCTURES CELLULAIRES</b> » ⭐ — ⚠️ le terme « <b>ULTRASTRUCTURE</b> » est le mot clé du MET ⭐<br>• ⚠️ ⭐ <b>LA LONGUEUR D'ONDE</b> : la résolution est limitée par la λ des électrons — ⚠️ plus la tension d'accélération est <b>ÉLEVÉE</b>, plus la λ est <b>COURTE</b>, meilleure est la résolution ⭐ (dualité onde-corpuscule de <b>de Broglie</b>) ⭐ <b>PRIX NOBEL DE PHYSIQUE 1937 POUR LE MICROSCOPE ÉLECTRONIQUE (Ruska)</b><br><br><b>🔴 ⭐⭐ LES CONTRAINTES DE PRÉPARATION (énoncées par le cours) :</b><br>📖 « <b>En raison du faible pouvoir de PÉNÉTRATION des électrons, les COUPES doivent être TRÈS FINES de <b>40 à 60 nm</b> d'épaisseur.</b> » ⭐⭐ <b>CHIFFRE À RETENIR</b> (⚠️ <b>100 fois plus fin qu'en microtome à paraffine : 2-7 µm !</b>) ⭐<br>📖 « <b>Cela impose des CONTRAINTES DE PRÉPARATION BEAUCOUP PLUS IMPORTANTES que celles du microscope optique, entre autres, une FIXATION PLUS EXIGEANTE et une INCLUSION EN MILIEU PLUS DUR.</b> » ⭐⭐<br><br><b>📋 LES ÉTAPES DE PRÉPARATION POUR LE MET ⭐ :</b><br><b>1. FIXATION</b> : ⭐ <b>GLUTARALDÉHYDE</b> ⭐ (⚠️ <b>pas le formol !</b> — le glutaraldéhyde préserve mieux les membranes et les protéines) ⭐⭐<br><b>2. POST-FIXATION</b> : ⭐ <b>ACIDE OSMIQUE (tétroxyde d'osmium, OsO₄)</b> ⭐ — ⚠️ <b>fixe les LIPIDES</b> (contrairement au formol) et ⭐ <b>contraste les membranes</b> ⭐⭐ ⚠️ <b>apparaissent NOIRES au MET</b> ⭐<br><b>3. INCLUSION</b> : ⭐ <b>ARALDITE (EPON) = RÉSINES POLYMÉRISABLES</b> ⭐ — ⭐ <b>« à 37 °C PENDANT 24 h PUIS 48 h à 56 °C »</b> ⭐⭐ <b>CHIFFRES EXACTS</b> ⚠️ ⭐ <b>La POLYMÉRISATION</b> = « réaction chimique, fonction du TEMPS et de la TEMPÉRATURE, conduisant la matrice ou la résine à se SOLIDIFIER de manière <b>IRRÉVERSIBLE</b> » ⭐ (⚠️ « valable uniquement pour les <b>THERMODURCISSABLES</b> ») ⭐<br><b>4. COUPES ULTRAFINES</b> : ⭐ avec un <b>ULTRAMICROTOME</b> ⭐ (⚠️ modèle photographié : « <b>LEICA ULTRACT 170</b> ») — ⭐ <b>couteau en DIAMANT ou en VERRE</b> ⭐ — <b>40 à 60 nm</b><br><b>5. RÉCUPÉRATION SUR GRILLES</b> ⭐<br>&nbsp;&nbsp;– ⭐ <b>2 TYPES DE GRILLE (énumération du cours) :</b> <b>1/ SOUS FORME DE GRILLAGE</b> ⭐ · <b>2/ PRÉSENTANT UN TROU AU MILIEU = « MONO-TROU »</b> ⭐⭐ <b>DISTINCTION TOMBABLE</b><br>&nbsp;&nbsp;– ⭐ <b>LES MONO-TROUS doivent être PRÉPARÉS AVANT</b> : « il est nécessaire de préparer la grille de manière à <b>OBTURER LES TROUS</b> par une matière laissant passer les électrons. Pour cela, on utilise une <b>SOLUTION DE COLLODION</b>. » ⭐⭐ ⚠️ <b>le collodion = nitrocellulose, forme un film support transparent aux électrons</b> ⭐<br>&nbsp;&nbsp;– ⭐ <b>Technique de récupération (détail du cours) :</b> « <b>Récupérer les coupes FLOTTANTES soit en POSANT la grille SUR les coupes, soit en GLISSANT la grille SOUS les coupes</b> ⭐ · <b>ÉLIMINER l'excès d'eau à l'aide d'un PAPIER FILTRE</b> · <b>STOCKER les grilles dans un PORTOIR</b> » ⭐<br><b>6. CONTRASTE</b> : acétate d'uranyle + citrate de plomb ⭐<br><br><b>📋 ⭐⭐ COMPARAISON MO vs MET (TABLEAU ESSENTIEL) :</b><br>• <b>Source</b> : MO = <b>PHOTONS</b> (lumière) · MET = <b>ÉLECTRONS</b> ⭐<br>• <b>Lentilles</b> : MO = <b>en VERRE</b> · MET = <b>ÉLECTROMAGNÉTIQUES</b> ⭐<br>• <b>Milieu</b> : MO = <b>air</b> · MET = <b>VIDE</b> ⭐<br>• <b>Résolution</b> : MO = <b>~0,2 µm (200 nm)</b> · MET = <b>~1 nm (0,1-0,2 nm)</b> ⭐<br>• <b>Grossissement</b> : MO = <b>jusqu'à ×1 500</b> · MET = <b>×1 500 à ×600 000</b> ⭐<br>• <b>Épaisseur des coupes</b> : MO = <b>2-7 µm</b> · MET = <b>40-60 nm</b> ⭐<br>• <b>Fixateur</b> : MO = <b>formol, Bouin</b> · MET = <b>glutaraldéhyde + acide osmique</b> ⭐<br>• <b>Inclusion</b> : MO = <b>PARAFFINE (56-60 °C)</b> · MET = <b>ARALDITE/EPON (résine, 37 °C 24h + 56 °C 48h)</b> ⭐<br>• <b>Instrument de coupe</b> : MO = <b>MICROTOME</b> · MET = <b>ULTRAMICROTOME (couteau de diamant/verre)</b> ⭐<br>• <b>Coloration/contraste</b> : MO = <b>H&amp;E, PAS…</b> · MET = <b>acétate d'uranyle, citrate de plomb</b> ⭐<br>• <b>Support</b> : MO = <b>lame de verre</b> · MET = <b>grille métallique (grillage ou mono-trou + collodion)</b> ⭐<br>• <b>Observation</b> : MO = <b>à l'œil / caméra</b> · MET = <b>écran fluorescent / caméra CCD</b><br>• <b>Objet vivant</b> : MO = ⭐ <b>OUI possible</b> · MET = ⚠️ <b>NON (mort, déshydraté, vide)</b> ⭐⭐<br>• <b>Image</b> : MO = <b>2D, en COULEURS</b> · MET = <b>2D, en NOIR ET BLANC</b> ⭐ ⚠️ <b>« les couleurs du MET sont FAUSSES — ajoutées artificiellement »</b> ⭐<br>• <b>Coût / encombrement</b> : MO = <b>faible</b> · MET = <b>très élevé (salle dédiée)</b>","t":"biocell-methodes EXAM-2026 M111"},{"q":"⭐ <b>II &amp; III — LES MÉTHODES D'ÉTUDE DE LA CONSTITUTION CHIMIQUE et DU FONCTIONNEMENT</b> : cytochimie, fractionnement, électrophorèse, chromatographie, culture cellulaire, autoradiographie","a":"<b>⚠️ CES 2 PARTIES SONT DANS LE PLAN DU COURS MAIS LE DOCUMENT FOURNI EST TRONQUÉ APRÈS LE MET.</b> ⚠️ <b>VOICI L'ESSENTIEL À CONNAÎTRE — ce sont les 6 méthodes du plan :</b><br><br><b>📗 II. MÉTHODES D'ÉTUDE DE LA CONSTITUTION CHIMIQUE (4 méthodes)</b><br><br><b>1. ⭐ LA CYTOCHIMIE (et HISTOCHIMIE)</b><br>• <b>PRINCIPE</b> : ⭐ <b>révéler in situ la PRÉSENCE et la LOCALISATION d'une substance chimique</b> dans la cellule/le tissu, par une <b>RÉACTION CHIMIQUE COLORÉE SPÉCIFIQUE</b> ⭐<br>• ⚠️ <b>Exemples (vus dans les colorations) :</b> <b>PAS</b> (glucides) · <b>Noir Soudan / Oil Red O</b> (lipides) · <b>Perls</b> (fer) · <b>Von Kossa</b> (calcium) · ⭐ <b>Réaction de Feulgen</b> (ADN — ⚠️ <b>histochimie quantitative de l'ADN, employée en cytométrie et pour le contenu en ADN des tumeurs</b>) ⭐<br>• ⭐ <b>CYTO-ENZYMOLOGIE / HISTOENZYMOLOGIE</b> : ⭐ <b>mettre en évidence l'ACTIVITÉ d'une ENZYME</b> (ex. <b>phosphatases alcalines, estérases, ATPases, peroxydases</b>) ⭐ ⚠️ ⭐ <b>OBLIGE À LA CONGÉLATION</b> (la paraffine détruit les enzymes) ⭐⭐ <b>LIEN AVEC LA CRYOTOMIE</b><br>• ⭐ <b>IMMUNOCYTOCHIMIE / IMMUNOHISTOCHIMIE (IHC)</b> : ⭐ <b>anticorps spécifiques + chromogène (DAB = brun) ou fluorochrome</b> ⭐ — ⚠️ <b>c'est l'application diagnostique la plus importante</b> (marqueurs tumoraux, Ki-67, HER2, RE/RP, CD) ⭐<br><br><b>2. ⭐ LE FRACTIONNEMENT CELLULAIRE (CENTRIFUGATION DIFFÉRENTIELLE)</b><br>• <b>PRINCIPE</b> : ⭐ <b>BROYER les cellules</b> (homogénéisation) puis ⭐ <b>SÉPARER les ORGANITES</b> par des <b>CENTRIFUGATIONS SUCCESSIVES À VITESSES CROISSANTES</b> ⭐⭐<br>• ⚠️ ⭐ <b>L'ORDRE DE SÉDIMENTATION (par taille décroissante) :</b><br>&nbsp;&nbsp;<b>1. 600 g × 10 min</b> → <b>NOYAUX</b> (+ débris, cytosquelette) ⭐⭐<br>&nbsp;&nbsp;<b>2. 10 000 g × 20 min</b> → <b>MITOCHONDRIES</b> (+ lysosomes, peroxysomes) ⭐⭐<br>&nbsp;&nbsp;<b>3. 100 000 g × 60 min</b> → <b>MICROSOMES</b> (fragments de <b>RE</b> et de <b>Golgi</b>) ⭐⭐<br>&nbsp;&nbsp;<b>4. SURNAGEANT FINAL</b> → <b>CYTOSOL</b> (enzymes solubles, ribosomes libres) ⭐⭐<br>&nbsp;&nbsp;⚠️ à <b>300 000 g</b> → les <b>RIBOSOMES</b> ⭐<br>• ⚠️ <b>Conditions :</b> ⭐ <b>À FROID (0-4 °C)</b> ⭐ et dans un ⭐ <b>milieu ISOTONIQUE (saccharose 0,25 M)</b> ⭐ pour préserver les organites ⭐ <b>DÉTAILS TOMBABLES</b><br>• ⭐ <b>CENTRIFUGATION ISOGRAPHIQUE sur gradient (ex. sucrose ou Percoll)</b> → sépare selon la <b>DENSITÉ</b> (plus précis) → ⭐ <b>permet de purifier les LYSOSOMES, les PEROXYSOMES</b> ⭐<br>• ⚠️ ⭐ <b>LE MARQUEUR ENZYMATIQUE</b> : on identifie chaque fraction par une enzyme spécifique — ⭐ <b>ex. : la CATALASE = marqueur des PEROXYSOMES</b> · <b>la phosphatase acide = lysosomes</b> · <b>la succinate déshydrogénase = mitochondries</b> · <b>la glucose-6-phosphatase = RE</b> ⭐⭐<br><br><b>3. ⭐ L'ÉLECTROPHORÈSE</b><br>• <b>PRINCIPE</b> : ⭐ <b>séparer des MOLÉCULES CHARGÉES (protéines, ADN, ARN) dans un CHAMP ÉLECTRIQUE</b> ⭐ — elles migrent vers l'électrode de charge opposée ⭐<br>• ⚠️ ⭐ <b>L'ADN migre vers l'ANODE (+)</b> car il est chargé <b>NÉGATIVEMENT</b> (groupements phosphate) ⭐⭐ <b>QUESTION CLASSIQUE</b><br>• ⭐ <b>LES SUPPORTS :</b> <b>GEL D'AGAROSE</b> (pour l'<b>ADN</b>) · <b>GEL DE POLYACRYLAMIDE (PAGE)</b> (pour les <b>protéines</b> et les petits acides nucléiques) ⭐<br>• ⭐ <b>SDS-PAGE</b> : le <b>SDS</b> (dodécylsulfate de sodium) dénature les protéines et leur donne une <b>charge uniformément négative</b> proportionnelle à la masse → ⭐ <b>séparation uniquement selon le POIDS MOLÉCULAIRE</b> ⭐⭐<br>• ⚠️ <b>Révélation :</b> <b>Bleu de Coomassie</b>, <b>nitrate d'argent</b>, <b>BET (bromure d'éthidium)</b> ⭐ pour l'ADN (⚠️ <b>fluorescence sous UV</b>) ⭐<br>• ⭐ <b>WESTERN BLOT</b> = électrophorèse des protéines + transfert sur membrane + anticorps ⭐<br>• ⚠️ ⭐ <b>ÉLECTROPHORÈSE DES PROTÉINES SÉRIQUES</b> : ⭐ <b>6 fractions : ALBUMINE · α1 · α2 · β1 · β2 · γ (gammaglobulines = anticorps)</b> ⭐⭐ <b>ULTRA CLASSIQUE — ⚠️ un « PIC MONOCLONAL » dans les γ = MYÉLOME</b> ⭐<br><br><b>4. ⭐ LA CHROMATOGRAPHIE</b><br>• <b>PRINCIPE</b> : ⭐ <b>séparer les molécules par PARTAGE entre DEUX PHASES : une PHASE STATIONNAIRE (fixe) et une PHASE MOBILE (qui circule)</b> ⭐⭐<br>• ⚠️ Les molécules migrent à des vitesses différentes selon leur <b>AFFINITÉ</b> pour chaque phase ⭐<br>• ⭐ <b>LES TYPES :</b><br>&nbsp;&nbsp;– <b>Chromatographie sur PAPIER / sur COUCHE MINCE (CCM, TLC)</b> ⭐<br>&nbsp;&nbsp;– <b>Chromatographie d'EXCLUSION STÉRIQUE (tamissage moléculaire, gel filtration)</b> → selon la <b>TAILLE</b> ⭐<br>&nbsp;&nbsp;– <b>Chromatographie d'ÉCHANGE D'IONS</b> → selon la <b>CHARGE</b> ⭐<br>&nbsp;&nbsp;– <b>Chromatographie d'AFFINITÉ</b> → selon l'<b>AFFINITÉ SPÉCIFIQUE</b> (ex. ⭐ <b>anticorps, His-Tag + nickel</b>) ⭐⭐<br>&nbsp;&nbsp;– <b>HPLC</b> (haute performance) · <b>chromatographie en phase gazeuse (GC)</b> ⭐<br><br><b>📕 III. ⭐⭐ MÉTHODES D'ÉTUDE DU FONCTIONNEMENT (2 méthodes)</b><br><br><b>1. ⭐⭐ LA CULTURE DE CELLULES (cultures cellulaires)</b><br>• <b>PRINCIPE</b> : ⭐ <b>faire VIVRE et MULTIPLIER des cellules HORS DE L'ORGANISME (in vitro)</b>, dans un <b>milieu nutritif stérile</b> ⭐<br>• ⚠️ <b>MILIEU DE CULTURE</b> : <b>MEM, DMEM, RPMI</b> + ⭐ <b>SÉRUM DE VEAU FŒTAL (SVF, 10 %)</b> ⭐ + <b>antibiotiques</b> (pénicilline/streptomycine) + <b>glutamine</b> + ⭐ <b>bicarbonate / tampon HEPES</b> (pH 7,2-7,4) ⭐<br>• ⚠️ <b>CONDITIONS :</b> ⭐ <b>étuve à 37 °C</b>, ⭐ <b>atmosphère humide avec 5 % de CO₂</b> ⭐, milieu stérile (⚠️ <b>PSE (Poste de Sécurité Microbiologique / hotte à flux laminaire)</b>) ⭐<br>• ⭐ <b>LES 3 TYPES :</b><br>&nbsp;&nbsp;1. <b>CULTURE PRIMAIRE</b> : cellules prélevées <b>directement</b> sur le tissu → ⚠️ ⭐ <b>durée de vie LIMITÉE</b> (= <b>limite de Hayflick</b>, ⚠️ <b>~50 divisions</b>, liée au raccourcissement des <b>TÉLOMÈRES</b>) ⭐⭐<br>&nbsp;&nbsp;2. <b>LIGNÉE CELLULAIRE (cellule établie / continue)</b> : ⭐ <b>IMMORTELLE</b>, se divise indéfiniment ⭐ — ⚠️ obtenue par <b>transformation spontanée</b> ou <b>transfection d'oncogènes</b> (ex. ⭐ <b>SV40 grand T, HPV E6/E7</b>) ⭐⭐<br>&nbsp;&nbsp;&nbsp;&nbsp;– ⭐⭐ <b>LA LIGNÉE CÉLÈBRE : <b>HeLa</b></b> ⭐ = cellules de <b>cancer du col de l'utérus</b> prélevées en <b>1951</b> sur <b>Henrietta Lacks</b> <b>SANS SON CONSENTEMENT</b> ⭐⭐ <b>HISTOIRE ÉTHIQUE MAJEURE — À CONNAÎTRE</b><br>&nbsp;&nbsp;3. <b>EXPLANT / culture d'organes / culture 3D (organoïdes)</b> ⭐ — ⭐ <b>« cellules souches » et « organoïdes » = technologie moderne</b> ⭐<br>• ⚠️ <b>Les cultures se font en monocouche</b> (cellules adhérentes qui se <b>« repiquent » = trypsinisation</b>) ou en <b>suspension</b> (cellules sanguines) ⭐<br>• ⭐ <b>APPLICATIONS :</b> <b>étude du cycle cellulaire</b> · <b>caryotype</b> ⭐ (⚠️ <b>lien avec la cytogénétique et le CHOC HYPOTONIQUE !</b>**) ⭐⭐ · <b>tests de cytotoxicité / pharmacologie</b> · <b>production de protéines recombinantes</b> · <b>virologie</b> (culture virale) · <b>FIV</b> · ⭐ <b>thérapie cellulaire, CAR-T</b> ⭐ · ⭐ <b>ingénierie tissulaire parodontale</b> ⭐ <b>PERTINENT EN DENTAIRE</b><br>• ⚠️ <b>CONTAMINATION LA PLUS FRÉQUENTE : les MYCOPLASMES</b> ⭐ · <b>et les levures/bactéries</b> ⭐<br><br><b>2. ⭐⭐ L'AUTORADIOGRAPHIE</b><br>• <b>PRINCIPE</b> : ⭐ <b>utiliser des MOLÉCULES MARQUÉES PAR UN ISOTOPE RADIOACTIF (« traceur »)</b>, les faire <b>INCORPORER par les cellules VIVANTES</b>, puis ⭐ <b>RÉVÉLER leur localisation</b> en mettant la préparation au contact d'une <b>ÉMULSION PHOTOGRAPHIQUE</b> ⭐⭐<br>• ⚠️ ⭐ <b>LES ISOTOPES LES PLUS UTILISÉS :</b><br>&nbsp;&nbsp;– <b>³H (TRITIUM)</b> → ⭐ <b>THYMIDINE TRITIÉE (³H-thymidine)</b> ⭐⭐ ⚠️ <b>marque SPÉCIFIQUEMENT L'ADN → étudie la RÉPLICATION et la PROLIFÉRATION CELLULAIRE</b> ⭐⭐⭐ <b>C'EST L'EXEMPLE N°1</b><br>&nbsp;&nbsp;– <b>³H-URIDINE</b> → ⭐ marque l'<b>ARN</b> (transcription) ⭐<br>&nbsp;&nbsp;– <b>³H-LEUCINE</b> (ou <b>³⁵S-méthionine</b>) → ⭐ marque les <b>PROTÉINES</b> (traduction, sécrétion) ⭐<br>&nbsp;&nbsp;– <b>³²P</b> → <b>acides nucléiques, phosphorylation</b><br>&nbsp;&nbsp;– <b>¹⁴C, ³⁵S, ¹²⁵I, ⁴⁵Ca</b> ⭐<br>• ⚠️ <b>AVANTAGE MAJEUR :</b> ⭐ <b>étudie une cellule VIVANTE et son FONCTIONNEMENT DYNAMIQUE dans le TEMPS</b> ⭐ — contrairement aux colorations qui donnent une image statique d'une cellule morte ⭐⭐<br>• ⭐ <b>EXEMPLE CÉLÈBRE :</b> l'expérience de <b>PALADE</b> sur la <b>VOIE DE SÉCRÉTION</b> — ⭐ <b>pulse-chase</b> avec de la <b>³H-leucine</b> : ⭐ <b>RE → GOLGI → VÉSICULES DE SÉCRÉTION → EXOCYTOSE</b> ⭐⭐ <b>PRIX NOBEL 1974 (Palade, Claude, de Duve)</b> ⭐⭐ <b>À CONNAÎTRE</b><br>• ⚠️ <b>Autre application :</b> ⭐ <b>l'AUTORADIOGRAPHIE a permis la découverte de la réplication SEMI-CONSERVATRICE</b> — ⚠️ ⭐ <b>par TAYLOR, WOODS et HUGHES en 1957</b> <b>sur les chromosomes de <i>Vicia faba</i> (fève) avec la ³H-thymidine</b> ⭐⭐ <b>LIEN DIRECT AVEC LE COURS DE PR ROCHD !</b> ⭐<br>• ⚠️ <b>ÉVOLUTION MODERNE :</b> l'autoradiographie est aujourd'hui ⭐ <b>largement remplacée par des méthodes NON RADIOACTIVES</b> : <b>BrdU/EdU</b> (analogues de la thymidine révélés par ⭐ <b>anticorps anti-BrdU</b>), <b>immunofluorescence, GFP, sondes fluorescentes</b> ⭐","t":"biocell-methodes EXAM-2026 M111"},{"q":"QCM — <b>LA CYTOLOGIE</b> selon Pr RHRICH-HADDOUT : chno kat-dir b d-dabt ?","a":"<b>⭐ RÉPONSE EXACTE DU COURS :</b><br>« <b>La CYTOLOGIE permet d'étudier la <b>STRUCTURE</b> microscopique de la cellule <b>EN DEHORS DE TOUTE ORGANISATION TISSULAIRE</b>.</b> » ⭐⭐<br><br>🔴 <b>LES 2 MOTS CLÉS À RETENIR :</b> <b>STRUCTURE</b> + <b>EN DEHORS DE TOUTE ORGANISATION TISSULAIRE</b> ⭐<br><br><b>📋 LES 3 DÉFINITIONS À NE PAS CONFONDRE :</b><br>• <b>CYTOLOGIE</b> → ⭐ <b>STRUCTURE</b> (microscopique, cellule isolée)<br>• <b>BIOLOGIE MOLÉCULAIRE + BIOCHIMIE</b> → ⭐ <b>FONCTIONNEMENT</b><br>• <b>BIOLOGIE CELLULAIRE</b> → ⭐ <b>utilise les 3</b> (cytologie + biologie moléculaire + biochimie)<br><br>⚠️ <b>PHRASE CLÉ DU COURS :</b> « <b>FRONTIÈRE ARBITRAIRE car <b>STRUCTURE et FONCTION sont INTIMEMENT LIÉES</b></b> » ⭐⭐ <b>TOMBABLE</b><br><br><b>⚠️ PIÈGE DU QCM :</b><br>❌ « La cytologie étudie la cellule <b>dans le tissu</b> » → <b>FAUX</b> (c'est l'<b>HISTOLOGIE</b>)<br>❌ « La cytologie étudie le <b>fonctionnement</b> » → <b>FAUX</b> (c'est la <b>biochimie</b>)<br>✅ « La cytologie étudie la <b>structure</b> de la cellule <b>isolée</b> » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — <b>UN TISSU w UN ORGANE</b> : ⭐ chno l-far9 ? (w les 4 tissus fondamentaux)","a":"<b>🔴 LES 2 DÉFINITIONS DU COURS :</b><br>• ⭐ <b>UN TISSU</b> : « un <b>ASSEMBLAGE DE CELLULES</b> remplissant une <b>FONCTION PARTICULIÈRE</b> à l'intérieur d'un organe » ⭐<br>• ⭐ <b>UN ORGANE</b> : « assemblage de <b>PLUSIEURS TISSUS</b> qui remplissent une fonction spécifique dans un organisme » ⭐<br><br><b>⚠️ LA DIFFÉRENCE EN UN MOT :</b><br>• <b>TISSU</b> = <b>des CELLULES</b> ⭐<br>• <b>ORGANE</b> = <b>des TISSUS</b> ⭐<br><br><b>🔴 ⭐⭐ LES 4 TISSUS FONDAMENTAUX (liste EXACTE du cours) :</b><br>1. <b>Tissu ÉPITHÉLIAL</b> ⭐<br>2. <b>Tissu CONJONCTIF</b> ⭐<br>3. <b>Tissu MUSCULAIRE</b> ⭐<br>4. <b>Tissu NERVEUX</b> ⭐<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>É</b>pit <b>C</b>onjonctif <b>M</b>uscle <b>N</b>erf » = <b>É-C-M-N</b> ⭐<br><br><b>📋 LES EXEMPLES D'ORGANES DU COURS :</b> <b>cerveau</b>, <b>foie</b>, <b>pancréas</b> ⭐<br><br><b>⚠️ PIÈGE DU QCM :</b><br>❌ « Un tissu est un assemblage d'<b>organes</b> » → <b>FAUX</b> (c'est l'inverse)<br>✅ « Un organe = <b>plusieurs tissus</b> » → <b>VRAI</b> ⭐<br><br><b>💡 BONUS — PERTINENT EN DENTAIRE :</b><br>La <b>DENT</b> est un <b>ORGANE</b> ⭐ — elle contient <b>4 tissus</b> :<br>• <b>ÉMAIL</b> (épithélial d'origine ectodermique — ⚠️ <b>le + dur du corps</b>)<br>• <b>DENTINE</b> (conjonctif minéralisé)<br>• <b>CÉMENT</b> (conjonctif minéralisé)<br>• <b>PULPE</b> (conjonctif lâche + <b>tissu nerveux</b> + vaisseaux) ⭐⭐<br>➡️ <b>EXCELLENT EXEMPLE À CITER À L'EXAMEN</b>","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — <b>L'ÉCLAIRCISSEMENT</b> : chno howa, b chno, w 3lach ?","a":"<b>⭐ RÉPONSE EXACTE DU COURS :</b><br>« <b>ÉCLAIRCISSEMENT : passage dans un SOLVANT ORGANIQUE (<b>TOLUÈNE</b> ou <b>XYLÈNE</b>)</b> » ⭐⭐<br><br><b>📍 OÙ IL SE PLACE (étape n° 5 des 12) :</b><br>1. Prélèvement → 2. Fixation → 3. Décalcification → 4. **Déshydratation** → ⭐ **5. ÉCLAIRCISSEMENT** → 6. Imprégnation → 7. Inclusion → 8. Coupes...<br><br><b>🔴 ⭐ 3LACH (le pourquoi — le plus important) :</b><br>• <b>Étape 4 (déshydratation)</b> a enlevé l'eau → le tissu est dans l'<b>ALCOOL</b><br>• <b>Étape 6 (imprégnation)</b> doit mettre le tissu dans la <b>PARAFFINE</b><br>• ⚠️ ⭐ <b>L'ALCOOL ET LA PARAFFINE NE SONT PAS MISCIBLES</b> ⭐⭐<br>• ➡️ Il faut un <b>INTERMÉDIAIRE</b> miscible aux deux = ⭐ <b>LE TOLUÈNE / XYLÈNE</b> ⭐⭐<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « Eau → <b>Alcool</b> → ⭐ <b>Toluène</b> → <b>Paraffine</b> » — chaque solvant doit être <b>miscible avec le suivant</b> ⭐<br><br><b>🔴 LE MÊME PRODUIT SERT AU DÉPARAFFINAGE (étape 10) :</b><br>« <b>DÉPARAFFINAGE des coupes : à l'aide d'un SOLVANT de la paraffine : <b>TOLUÈNE, XYLÈNE</b></b> » ⭐<br>➡️ ⭐ <b>Le toluène/xylène sert 2 fois : à l'ALLER (éclaircissement) et au RETOUR (déparaffinage)</b> ⭐⭐ <b>DÉTAIL TOMBABLE</b><br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « Éclaircissement = bain d'<b>alcool</b> » → <b>FAUX</b> (c'est la <b>déshydratation</b>)<br>❌ « Le xylène rend le tissu <b>transparent</b> » → ⚠️ c'est <b>VRAI</b> en apparence (le tissu devient translucide = « éclairci ») <b>mais ce n'est PAS le but</b> — ⭐ <b>le but est d'être miscible avec la paraffine</b> ⭐<br>✅ « Solvant organique : toluène ou xylène » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐ <b>DÉSHYDRATATION vs RÉHYDRATATION</b> : l'ordre des bains d'alcool (piège classique)","a":"<b>🔴 ⭐⭐ C'EST LE PIÈGE N°1 DU CHAPITRE — L'ORDRE EST INVERSÉ</b><br><br><b>📗 ⭐ LA DÉSHYDRATATION (étape 4 — AVANT l'inclusion)</b><br>📖 « Bains d'<b>ALCOOL de plus en plus CONCENTRÉS</b> : <b>70°, 95°, 100°</b> » ⭐⭐<br>• <b>BUT :</b> ⭐ « Préparer les tissus à l'inclusion car <b>LA PARAFFINE N'EST PAS MISCIBLE À L'EAU</b> » ⭐⭐<br>• ⚠️ <b>ORDRE = CROISSANT : 70 → 95 → 100</b> ⭐<br><br><b>📘 ⭐ LA RÉHYDRATATION (étape 11 — AVANT la coloration)</b><br>📖 « Bains d'alcool à <b>TITRE DÉCROISSANT</b> : <b>100°, 95°, 70°</b> » ⭐⭐<br>• <b>BUT :</b> ⭐ « Étape <b>INDISPENSABLE, PRÉALABLE À LA COLORATION</b> car <b>LA PLUPART DES COLORANTS SONT HYDROPHILES</b> » ⭐⭐⭐<br>• ⚠️ <b>ORDRE = DÉCROISSANT : 100 → 95 → 70</b> ⭐<br><br><b>🔴 ⭐⭐ LE TABLEAU À APPRENDRE :</b><br>• <b>DÉSHYDRATATION</b> → <b>70 → 95 → 100</b> → <b>CROISSANT</b> ⬆️ → but : <b>enlever l'eau pour la paraffine</b> ⭐<br>• <b>RÉHYDRATATION</b> → <b>100 → 95 → 70</b> → <b>DÉCROISSANT</b> ⬇️ → but : <b>remettre l'eau pour les colorants hydrophiles</b> ⭐<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b><br>• <b>DÉSHY</b>dratation → on <b>MONTE</b> vers le 100 (il faut que ce soit <b>sec</b>) ⬆️<br>• <b>RÉHY</b>dratation → on <b>DESCEND</b> vers l'eau ⬇️<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « Réhydratation : 70°, 95°, 100° » → <b>FAUX</b> (c'est la déshydratation !)<br>❌ « La réhydratation se fait <b>après</b> la coloration » → <b>FAUX</b> (elle est <b>AVANT</b>, étape 11 vs 12) ⭐<br>✅ « La réhydratation est indispensable car la plupart des colorants sont <b>hydrophiles</b> » → <b>VRAI</b> ⭐⭐<br><br><b>📋 RAPPEL — L'ORDRE COMPLET (12 étapes) :</b><br>Prélèvement → Fixation → Décalcification → **Déshydratation (70-95-100)** → Éclaircissement (toluène) → Imprégnation → Inclusion → Coupes (microtome 2-7 µm) → Collage → Déparaffinage (toluène) → **Réhydratation (100-95-70)** → **Coloration** → Déshydratation (70-95-100) → Montage (Eukitt) → Observation ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐ <b>FIXATEURS</b> : chno howa l-but dyal l-fixation, w chno les agents ? (avec la DIFFÉRENCE clé)","a":"<b>🔴 ⭐ LE BUT (définition exacte du cours) :</b><br>« <b>La fixation <b>PRÉSERVE LA STRUCTURE DE LA CELLULE MORTE</b></b>. » ⭐<br><br><b>📋 LES 3 ACTIONS (textuel) :</b><br>1. ⭐ « <b>Fixateurs : <b>TUENT la cellule en GARDANT EN PLACE ses constituants</b></b> » ⭐⭐<br>2. ⭐ « <b>Créent des <b>LIAISONS CHIMIQUES TRÈS STABLES</b> entre les molécules de la cellule</b> » ⭐⭐<br>3. ⭐ « Préserve la structure » ⭐<br><br><b>🔴 ⭐ LES AGENTS (liste du cours) :</b><br>• <b>FORMALDÉHYDE</b> ⭐<br>• <b>FORMOL</b> ⭐⭐ (⚠️ = solution aqueuse de formaldéhyde à <b>~37 %</b>, utilisée diluée à <b>10 %</b>) — ⭐ <b>LE PLUS UTILISÉ EN ROUTINE</b><br>• <b>BOUIN</b> ⭐⭐ ⚠️ (⚠️ = <b>acide picrique + formol + acide acétique</b>) — ⭐ <b>excellent pour les biopsies testiculaires et digestives</b><br><br><b>🔴 ⭐⭐ LE TABLEAU COMPARATIF (à connaître) :</b><br>• <b>FORMOL / FORMALDÉHYDE</b> → ⭐ <b>ROUTINE</b> (MO) → <b>ponts méthylène (-CH₂-) entre protéines</b> → ⚠️ lent (24h), bonne morphologie<br>• <b>BOUIN</b> → ⭐ <b>biopsies testiculaires, digestives</b> → ⚠️ l'<b>acide picrique</b> colore le tissu en jaune<br>• <b>GLUTARALDÉHYDE</b> → ⭐ <b>MICROSCOPIE ÉLECTRONIQUE</b> ⭐⭐ → ⚠️ <b>préserve mieux les MEMBRANES</b> (le formol ne les conserve pas bien)<br>• <b>ACIDE OSMIQUE (OsO₄)</b> → ⭐ <b>POST-fixation en ME</b> → ⚠️ <b>fixe les LIPIDES</b> + ⭐ <b>contraste les membranes (noires)</b> ⭐⭐<br>• <b>ALCOOL / ACÉTONE</b> → fixateurs <b>précipitants</b> (dénaturent les protéines) ⭐<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « La fixation <b>garde la cellule vivante</b> » → <b>FAUX</b> — ⭐ « <b>TUENT la cellule</b> » ⭐<br>❌ « Le glutaraldéhyde sert en <b>microscopie optique</b> » → <b>FAUX</b> (c'est le <b>formol</b>) ⭐<br>✅ « Le formol crée des <b>liaisons chimiques très stables</b> » → <b>VRAI</b> ⭐<br>✅ « L'acide osmique <b>fixe les lipides</b> » → <b>VRAI</b> ⭐⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>DÉCALCIFICATION</b> : <b>ACIDE NITRIQUE vs EDTA</b> — chno l-far9 ? (ultra pertinent en dentaire)","a":"<b>🔴 ⭐ POURQUOI (énoncé du cours) :</b><br>« <b>Tissus imprégnés de <b>SELS DE CALCIUM</b> (<b>OS, DENTS</b>) → ont une <b>RIGIDITÉ</b> qui les rend <b>IMPROPRES À LA COUPE au microtome</b>.</b> » ⭐⭐<br>« <b>La décalcification = procédé utilisé pour <b>ENLEVER de ces tissus les SELS DE CALCIUM</b>.</b> » ⭐<br><br><b>🔴 ⭐⭐ LE TABLEAU COMPARATIF (LE PLUS TOMBABLE) :</b><br>• <b>ACIDE NITRIQUE</b> : ⭐ <b>RAPIDE</b> (quelques heures) · ⚠️ <b>ALTÈRE LES COLORATIONS NUCLÉAIRES</b> · ⚠️ <b>ENDOMMAGE L'ADN</b> → ⭐ <b>À ÉVITER si on veut faire de la BIOLOGIE MOLÉCULAIRE (PCR, FISH)</b> ⭐⭐<br>• <b>EDTA</b> (= <b>acide éthylène diamine tétra-acétique</b>) ⭐⭐ : ⭐ <b>LENT</b> (plusieurs <b>SEMAINES</b>) · ⭐ <b>PRÉSERVE les antigènes, les enzymes et les ACIDES NUCLÉIQUES</b> ⭐⭐ · ⚠️ c'est un <b>CHÉLATEUR</b> du calcium<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>N</b>itrique = <b>N</b>ocif mais <b>R</b>apide · <b>E</b>DTA = <b>E</b>xcellent mais <b>L</b>ent » ⭐<br>• ⚠️ Autres agents : <b>acide formique</b>, <b>acide chlorhydrique</b>, agents chélateurs<br><br><b>🔴 ⭐⭐ POURQUOI C'EST ULTRA PERTINENT EN MÉDECINE DENTAIRE :</b><br>• ⭐ La <b>DENT</b> et l'<b>OS ALVÉOLAIRE</b> sont des <b>TISSUS DURS</b> → ⭐ <b>la décalcification est OBLIGATOIRE</b> pour pouvoir les couper ⭐⭐<br>• ⭐ <b>L'ÉMAIL</b> = <b>96 % de matière minérale</b> (hydroxyapatite) → ⭐ <b>le tissu le PLUS DUR du corps humain</b> → ⚠️ <b>ne peut PAS être coupé au microtome</b> ⭐⭐<br>• ⭐ <b>CONSEQUENCE :</b> pour étudier l'<b>émail</b>, on utilise une ⭐ <b>« COUPE PAR USURE » (PONÇAGE)</b> ⭐ — on ponce la dent jusqu'à obtenir une lame mince translucide<br>• ⭐ <b>LIEN DIRECT AVEC LE COURS :</b> le microscope à <b>CONTRASTE DE PHASE</b> du cours montre « <b>DENT (ÉMAIL)</b> — <b>coupe obtenue par PONÇAGE (coupe par usure), PAS DE COLORATION</b> » ⭐⭐ <b>LÉGENDE : E = émail · D = dentine · P = pulpe · O = fragments osseux · C = cément</b> ⭐⭐<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « La décalcification se fait pour <b>tous</b> les tissus » → <b>FAUX</b> (uniquement les tissus <b>DURS</b>) ⭐<br>❌ « L'EDTA est <b>rapide</b> » → <b>FAUX</b> (lent)<br>✅ « L'EDTA préserve les <b>acides nucléiques</b> » → <b>VRAI</b> ⭐⭐<br>✅ « L'acide nitrique <b>altère les colorations</b> » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐ <b>LE MICROTOME</b> : ch7al l-épaisseur dyal l-coupe ? (MO vs MET vs cryostat)","a":"<b>🔴 ⭐⭐ LES 3 CHIFFRES À RETENIR ABSOLUMENT :</b><br><br><b>1. ⭐ MICROTOME (paraffine, MO) = <b>2 à 7 µm</b></b> ⭐⭐<br>📖 Texte exact : « <b>Coupes : MICROTOMIE — microtome (<b>2-7 µm</b>)</b> » ⭐<br><br><b>2. ⭐⭐ ULTRAMICROTOME (MET) = <b>40 à 60 nm</b></b> ⭐⭐<br>📖 Texte exact : « <b>En raison du faible pouvoir de PÉNÉTRATION des électrons, les COUPES doivent être TRÈS FINES de <b>40 à 60 nm</b> d'épaisseur.</b> » ⭐<br>• ⚠️ ⭐ <b>C'est ~100 FOIS PLUS FIN qu'en paraffine !</b> (2-7 µm = 2 000-7 000 nm) ⭐⭐<br><br><b>3. ⭐ CRYOSTAT (congélation) = <b>5 à 10 µm</b></b> ⭐<br>• ⚠️ Le cours donne la température (<b>-18 à -20 °C</b>) mais pas l'épaisseur — ⭐ <b>5-10 µm est la valeur standard</b> (plus épais qu'en paraffine) ⭐<br><br><b>🔴 ⭐ LE TABLEAU :</b><br>• <b>MO (paraffine)</b> → <b>MICROTOME</b> → ⭐ <b>2-7 µm</b> → couteau en <b>acier/verre</b><br>• <b>ME (résine)</b> → <b>ULTRAMICROTOME</b> → ⭐ <b>40-60 nm</b> → couteau en <b>DIAMANT ou VERRE</b> ⭐<br>• <b>Congélation</b> → <b>CRYOSTAT</b> (enceinte <b>-18 à -20 °C</b>) → <b>5-10 µm</b><br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « Les coupes pour le MET font <b>2-7 µm</b> » → <b>FAUX</b> (c'est le MO)<br>❌ « Les coupes pour le MET font <b>40-60 µm</b> » → <b>FAUX</b> ⭐ — ⚠️ <b>c'est des NANOMÈTRES (nm), pas des micromètres</b> ⭐⭐ <b>PIÈGE LE PLUS FRÉQUENT</b><br>✅ « 40 à 60 <b>nm</b> » → <b>VRAI</b> ⭐<br><br><b>📋 RAPPEL DES UNITÉS :</b><br>• <b>1 mm</b> = 1 000 <b>µm</b> = 1 000 000 <b>nm</b><br>• <b>1 µm</b> = 1 000 <b>nm</b> ⭐<br>• ⚠️ <b>Ordre de grandeur utile :</b> cellule ~<b>10-20 µm</b> · noyau ~<b>6 µm</b> · mitochondrie ~<b>1 µm</b> · membrane ~<b>7-10 nm</b> · ribosome ~<b>20 nm</b> ⭐<br>➡️ ⭐ <b>C'est pour ça qu'il faut le MET (résolution ~1 nm) pour voir une MEMBRANE</b> ⭐⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>LES 12 ÉTAPES</b> — exercice : raddhom f l-ordre","a":"<b>🔴 EXERCICE TYPE DE L'EXAMEN — ⭐ APPRENDS LA LISTE DANS L'ORDRE</b><br><br><b>📋 L'ORDRE EXACT DU COURS :</b><br><b>1. PRÉLÈVEMENT</b><br><b>2. FIXATION</b> (formol, Bouin)<br><b>3. DÉCALCIFICATION</b> ⚠️ <b>tissus DURS uniquement</b> (acide nitrique, EDTA)<br><b>4. DÉSHYDRATATION</b> → alcool <b>70 → 95 → 100</b> ⬆️<br><b>5. ÉCLAIRCISSEMENT</b> → <b>toluène / xylène</b><br><b>6. IMPRÉGNATION</b> → paraffine liquide à <b>56-60 °C</b>, <b>3 bains</b><br><b>7. INCLUSION</b> → paraffine/paraplast <b>56-60 °C</b>, moules, barres en L<br><b>8. COUPES = MICROTOMIE</b> → <b>2-7 µm</b><br><b>9. COLLAGE</b> → platine chauffante · lames simples = <b>eau gélatineuse/albumineuse</b> · lames au <b>silane</b> = <b>eau</b><br><b>10. DÉPARAFFINAGE</b> → <b>toluène / xylène</b><br><b>11. RÉHYDRATATION</b> → alcool <b>100 → 95 → 70</b> ⬇️ (indispensable : colorants <b>hydrophiles</b>)<br><b>12. COLORATION</b> → H&amp;E, PAS, etc.<br><br><b>PUIS (fin) :</b><br><b>13. DÉSHYDRATATION des coupes</b> → <b>70 → 95 → 100</b> ⬆️<br><b>14. MONTAGE</b> → entre lame et lamelle · <b>EUKITT</b> ou <b>BAUME DE CANADA</b> ⭐<br><b>15. OBSERVATION AU MO</b><br><br><b>🔴 ⭐⭐ MNÉMOTECHNIQUE (les initiales) :</b><br><b>P</b>rélèvement · <b>F</b>ixation · <b>D</b>écalcification · <b>D</b>éshydratation · <b>É</b>claircissement · <b>I</b>mprégnation · <b>I</b>nclusion · <b>C</b>oupes · <b>C</b>ollage · <b>D</b>éparaffinage · <b>R</b>éhydratation · <b>C</b>oloration<br>= <b>P – F – D – D – É – I – I – C – C – D – R – C</b> ⭐<br><br>⚠️ <b>PHRASE MNÉMOTECHNIQUE :</b> « <b>P</b>etit <b>F</b>rère <b>D</b>ors <b>D</b>oucement, <b>É</b>coute <b>I</b>ntelligemment, <b>I</b>nsiste <b>C</b>ourageusement, <b>C</b>ompte, <b>D</b>étaille, <b>R</b>egarde, <b>C</b>olore » ⭐<br><br><b>🔴 ⭐ LES 5 ÉTAPES LES PLUS TOMBABLES :</b><br>1. ⭐ <b>DÉCALCIFICATION</b> (acide nitrique vs EDTA) — ⭐⭐ <b>DENTAIRE</b><br>2. ⭐ <b>ÉCLAIRCISSEMENT</b> (toluène/xylène — miscible alcool↔paraffine)<br>3. ⭐ <b>RÉHYDRATATION</b> (100→95→70, <b>colorants hydrophiles</b>) ⭐⭐ <b>LE PIÈGE</b><br>4. ⭐ <b>COUPES</b> (<b>2-7 µm</b> au microtome)<br>5. ⭐ <b>MONTAGE</b> (<b>Eukitt</b> / <b>baume de Canada</b>) ⭐<br><br><b>⚠️ PIÈGE DU QCM :</b><br>❌ « La coloration vient <b>avant</b> la réhydratation » → <b>FAUX</b> (réhydratation = étape 11, coloration = 12) ⭐⭐<br>❌ « L'inclusion vient <b>avant</b> l'imprégnation » → <b>FAUX</b> (imprégnation = 6, inclusion = 7)<br>✅ « Le déparaffinage et l'éclaircissement utilisent le <b>même solvant</b> » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐ <b>COLORANTS ACIDES vs BASIQUES</b> : chno kay-lounnou, w 3lach ?","a":"<b>🔴 ⭐⭐ LA RÈGLE D'OR (affinité électrostatique) :</b><br>⚠️ <b>LES CHARGES OPPOSÉES S'ATTIRENT</b> ⭐⭐<br><br><b>🔵 COLORANT BASIQUE</b> (chargé <b>+</b>) → se fixe sur les structures <b>ACIDES</b> (chargées <b>−</b>) = <b>BASOPHILES</b><br>• ⭐ <b>L'ADN et l'ARN</b> sont chargés <b>NÉGATIVEMENT</b> (groupements <b>phosphate</b>) ⭐⭐<br>• ➡️ ⭐ <b>ils sont BASOPHILES → ils fixent les COLORANTS BASIQUES</b><br>• ⚠️ <b>Structures colorées :</b> <b>NOYAU</b>, <b>chromatine</b>, <b>nucléole</b>, <b>ribosomes</b> (RER), cytoplasme riche en ARN ⭐<br><br><b>🔴 COLORANT ACIDE</b> (chargé <b>−</b>) → se fixe sur les structures <b>BASIQUES</b> (chargées <b>+</b>) = <b>ACIDOPHILES / ÉOSINOPHILES</b><br>• ⭐ <b>Les protéines cytoplasmiques</b> sont chargées <b>+</b> au pH histologique ⭐<br>• ➡️ ⭐ <b>elles sont ACIDOPHILES / ÉOSINOPHILES</b><br>• ⚠️ <b>Structures colorées :</b> <b>CYTOPLASME</b>, <b>fibres de collagène</b>, <b>fibres musculaires</b>, <b>hématies</b> ⭐<br><br><b>🔴 ⭐⭐ LE TABLEAU DU COURS :</b><br>• <b>COLORANTS ACIDES</b> = ⭐ <b>COLORANTS CYTOPLASMIQUES</b> ⭐⭐<br>• <b>COLORANTS BASIQUES</b> = ⭐ <b>COLORANTS NUCLÉAIRES</b> ⭐⭐<br><br><b>🔴 ⭐⭐ L'HÉMATOXYLINE-ÉOSINE (H&amp;E) :</b><br>• ⭐ <b>HÉMATOXYLINE</b> → ⭐ <b>COLORANT BASIQUE</b> → « coloration des substances <b>ACIDES</b> des <b>NOYAUX</b> cellulaires » → ⭐ <b>VIOLET À NOIR</b> ⭐<br>• ⭐ <b>ÉOSINE</b> → ⭐ <b>COLORANT ACIDE</b> → « coloration des composants <b>BASIQUES</b> du <b>CYTOPLASME</b> » → ⭐ <b>ROUGE À ROSE PÂLE</b> ⭐<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>H</b>ématoxyline → <b>N</b>oyau (<b>H</b> comme <b>H</b>NO = le noyau) · <b>É</b>osine → <b>C</b>ytoplasme » ⭐<br><br><b>🔴 LES 2 PROPRIÉTÉS D'UN COLORANT (définition du cours) :</b><br>• ⭐ <b>CHROMOPHORES</b> → « groupements qui lui confèrent une <b>COULEUR</b> » ⭐<br>• ⭐ <b>AUXOCHROMES</b> → « groupements qui assurent sa <b>FIXATION PERMANENTE</b> » ⭐<br>• ⚠️ ⭐ « <b>La CHARGE des AUXOCHROMES</b> permet de distinguer acide/basique » ⭐⭐<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « L'hématoxyline est un colorant <b>acide</b> » → <b>FAUX</b> (elle est <b>BASIQUE</b>) ⭐<br>❌ « L'éosine colore le <b>noyau</b> » → <b>FAUX</b> (le <b>cytoplasme</b>) ⭐<br>✅ « Les colorants basiques colorent les <b>acides nucléiques</b> » → <b>VRAI</b> ⭐⭐<br>✅ « L'ADN est <b>basophile</b> car chargé négativement » → <b>VRAI</b> ⭐⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>LES COLORATIONS SPÉCIALES</b> : « chno kay-lounn had l-7aja ? » (tableau complet)","a":"<b>🔴 ⭐⭐ TABLEAU À APPRENDRE PAR CŒUR — LE COURS DONNE CES 9 COLORATIONS</b><br><br><b>👉 FIBRES CONJONCTIVES :</b><br>• <b>VAN GIESON</b> → ⭐ <b>collagène en ROUGE</b> ⭐<br>• <b>TRICHROME DE MASSON</b> → ⭐ <b>collagène en BLEU ou VERT</b> ⭐⭐<br>• <b>GOMORI</b> → ⭐ <b>fibres de RÉTICULINE en NOIR</b> ⭐ (imprégnation argentique)<br><br><b>👉 SUBSTANCES GLUCIDIQUES :</b><br>• <b>PAS</b> (Periodic Acid Schiff) → ⭐ <b>ROSE à ROUGE POURPRE / ROUGE-VIOLET</b> ⭐⭐ • ⚠️ <b>LE PLUS UTILISÉ</b> • glycogène, mucus, <b>membranes basales</b>, champignons ⭐<br>• <b>ROUGE CONGO</b> → ⭐ <b>ROSE à ORANGE</b> ⭐ • ⭐ <b>AMYLOSE</b> — ⚠️ <b>biréfringence VERT POMME en lumière POLARISÉE</b> ⭐⭐<br>• <b>BLEU ALCIAN</b> → ⭐ « substances polysaccaridiques sécrétées par certaines cellules <b>ÉPITHÉLIALES</b> » = ⭐ <b>mucines ACIDES en BLEU</b> ⭐ • ⚠️ ex. <b>cellules caliciformes</b> ⭐ <b>DENTAIRE : glandes salivaires</b><br><br><b>👉 SUBSTANCES LIPIDIQUES :</b><br>• <b>HUILE ROUGE O</b> (Oil Red O) → ⭐ <b>ROUGE</b> ⭐<br>• <b>NOIR SOUDAN</b> → ⭐ <b>NOIR</b> ⭐<br>• ⚠️ ⭐⭐ <b>PIÈGE MAJEUR :</b> les 2 nécessitent une ⭐ <b>COUPE EN CONGÉLATION</b> — 7it les solvants (toluène, xylène, alcool) <b>DISSOLVENT LES LIPIDES</b> ⭐⭐ <b>QUESTION TRÈS TOMBABLE</b><br><br><b>👉 PROTÉINES :</b><br>• <b>GRAM-WEIGERT</b> → ⭐ <b>BLEU-NOIR</b> ⭐ • ⚠️ coloration de la <b>FIBRINE</b> · ⚠️ <b>NE PAS CONFONDRE avec la coloration de GRAM en bactériologie</b> ⭐<br><br><b>🔴 ⭐⭐ AUTRES COLORATIONS CLASSIQUES (bonus — souvent tombables) :</b><br>• <b>MGG (May-Grünwald-Giemsa)</b> → ⭐ <b>FROTTIS SANGUIN</b> ⭐<br>• <b>PAPANICOLAOU</b> → ⭐ <b>frottis gynécologiques et BUCCAUX</b> ⭐<br>• <b>BLEU DE MÉTHYLÈNE / TOLUIDINE</b> → ⭐ cellules épithéliales, <b>mastocytes</b> (métachromasie) ⭐<br>• <b>PERLS</b> → ⭐ <b>FER (hémosidérine) en BLEU</b> ⭐<br>• <b>VON KOSSA</b> → ⭐ <b>CALCIUM en NOIR</b> ⭐⭐ ⚠️ <b>ULTRA PERTINENT EN DENTAIRE</b> (minéralisation, émail, dentine, os)<br>• <b>ZIEHL-NEELSEN</b> → ⭐ <b>BK / BAAR</b> ⭐<br>• <b>IMMUNOHISTOCHIMIE (IHC)</b> → ⭐ anticorps + <b>DAB (brun)</b> ⭐<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « Le PAS colore les <b>lipides</b> » → <b>FAUX</b> (les <b>glucides</b>) ⭐<br>❌ « Le Noir Soudan se fait sur coupe en <b>paraffine</b> » → <b>FAUX</b> (<b>congélation</b>) ⭐⭐<br>✅ « Le Rouge Congo + lumière polarisée = <b>vert pomme</b> = amylose » → <b>VRAI</b> ⭐⭐<br>✅ « Le PAS met en évidence les <b>membranes basales</b> » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>LE FROTTIS SANGUIN (MGG)</b> : les chiffres w les 6 cellules","a":"<b>🔴 ⭐⭐ LES 6 CHIFFRES DU PROTOCOLE (tombables) :</b><br>• ⭐ goutte de sang = <b>3 mm de diamètre</b> ⭐<br>• ⭐ lame 2 inclinée à <b>45 DEGRÉS</b> ⭐<br>• ⭐ <b>15 GOUTTES</b> de May-Grünwald ⭐<br>• ⭐ May-Grünwald : <b>3 MIN</b> ⭐<br>• ⭐ Giemsa : <b>10 MIN</b> ⭐<br>• ⭐ attendre <b>AU MOINS 5 MIN</b> avant l'examen ⭐<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>3</b> mm · <b>45</b>° · <b>15</b> gouttes · <b>3</b> min · <b>10</b> min · <b>5</b> min » ⭐<br><br><b>🔴 ⭐ AUTRES DÉTAILS TECHNIQUES :</b><br>• Le sang s'étale par ⭐ <b>CAPILLARITÉ</b> ⭐<br>• ⭐ <b>SÉCHER AUSSITÔT EN AGITANT la lame</b> ⭐<br>• Lame sur <b>support HORIZONTAL</b> pendant la coloration ⭐<br>• Rincer au <b>jet d'eau NEUTRE</b> ⭐<br>• Sécher à l'air en <b>position INCLINÉE</b>, essuyer la face inférieure <b>au papier filtre</b> ⭐<br>• ⭐ <b>Étalement MONOCELLULAIRE</b> ⭐ (une seule couche de cellules)<br><br><b>🔴 ⭐⭐ LES 6 TYPES CELLULAIRES (description EXACTE du cours) :</b><br>• <b>HÉMATIES (GR)</b> → sans noyau, ⭐ <b>ÉOSINOPHILES</b> (roses/orangées), disque biconcave, ~<b>7,5 µm</b> ⭐<br>• <b>NEUTROPHILE</b> → ⭐ « <b>NOYAU DIFFORME</b>, comportant des régions larges, les <b>LOBES</b>, réunis par de fines <b>RELATIONS</b> » ⭐ · <b>2-5 lobes</b> · <b>50-70 %</b> ⭐⭐<br>• <b>ÉOSINOPHILE</b> → ⭐ <b>NOYAU BILOBÉ</b> ⭐ (en « lunettes ») + grosses granulations orangées · <b>1-4 %</b><br>• <b>BASOPHILE</b> → ⭐ « <b>NOYAU MASQUÉ PAR LES GROSSES GRANULATIONS</b> » ⭐ · <b>&lt;1 %</b><br>• <b>LYMPHOCYTE</b> → ⭐ « cellule <b>RONDE</b> avec un <b>NOYAU ROND, VOLUMINEUX</b> et <b>PEU DE CYTOPLASME</b> » ⭐ · <b>20-40 %</b><br>• <b>MONOCYTE</b> → ⭐ « cellule <b>RONDE</b> avec un <b>NOYAU EN FORME DE HARICOT</b> » ⭐ · <b>2-8 %</b> · ⚠️ <b>la + GROSSE : 15-20 µm</b> ⭐<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « Le lymphocyte est <b>gros</b> » → <b>FAUX</b> — ⭐ <b>il a le MÊME diamètre qu'une hématie (~7-8 µm)</b> ⭐⭐ <b>PIÈGE CLASSIQUE</b><br>❌ « Le monocyte a un noyau <b>rond</b> » → <b>FAUX</b> (<b>haricot</b> — c'est le lymphocyte qui est rond)<br>✅ « Le neutrophile à plus de <b>5 lobes</b> = carence en <b>B9/B12</b> » → <b>VRAI</b> ⭐ (hypersegmentation)<br>✅ « Le monocyte est la <b>plus grosse</b> cellule sanguine » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>LE FROTTIS BUCCAL</b> (cytologie exfoliatrice) : avantages, inconvénient, protocole","a":"<b>🔴 ⭐ DÉFINITION :</b><br>« La <b>CYTOLOGIE EXFOLIATRICE</b> étudie <b>LES CELLULES QUI SE DÉTACHENT NATURELLEMENT D'UN ÉPITHÉLIUM</b> » ⭐⭐<br>⚠️ <b>Exemples du cours :</b> frottis <b>vaginaux</b>, frottis <b>buccaux</b>, cellules de la <b>muqueuse bronchique</b> dans les <b>crachats</b> ⭐<br><br><b>🔴 ⭐⭐ LES 4 AVANTAGES (liste EXACTE) :</b><br>1. ⭐ « Méthode <b>NON AGRESSIVE</b> » ⭐<br>2. ⭐ « <b>FACILE À RÉALISER DANS LA BOUCHE</b> » ⭐<br>3. ⭐ « Donne des <b>RÉSULTATS RAPIDES</b> » ⭐<br>4. ⭐ « Utilisée pour le <b>DIAGNOSTIC de différentes affections BUCCALES</b>, en particulier afin d'identifier certaines <b>affections spécifiques de la MUQUEUSE BUCCALE</b> » ⭐⭐<br><br><b>🔴 ⭐⭐ L'INCONVÉNIENT (TRÈS TOMBABLE) :</b><br>« ⚠️ <b>Ne permet pas souvent l'établissement d'un DIAGNOSTIC DÉFINITIF.</b> » ⭐⭐<br>• ➡️ ⭐ C'est une méthode de <b>DÉPISTAGE / ORIENTATION</b> — un diagnostic définitif exige une ⭐ <b>BIOPSIE</b> avec examen anatomopathologique ⭐⭐<br>• ⚠️ <b>Les 2 sont complémentaires :</b> frottis = rapide et indolore · biopsie = définitif ⭐<br><br><b>🔴 ⭐ LE MATÉRIEL :</b><br>• une ⭐ <b>LAME HISTOLOGIQUE PROPRE, STÉRILE</b> ⭐<br>• une ⭐ <b>SOLUTION FIXATRICE : ALCOOL/ÉTHER</b> ou <b>ÉTHYLÈNE/GLYCOL</b> ⭐⭐ <b>DÉTAIL TOMBABLE</b><br>• un ⭐ <b>ABAISSE-LANGUE</b> ⭐<br><br><b>🔴 ⭐ LE MODE OPÉRATOIRE (5 temps) :</b><br>1. ⭐ « Passer une <b>COMPRESSE HUMIDE</b> au niveau du site lésé (<b>élimination des MUCOSITÉS</b>) » ⭐<br>2. ⭐ « <b>GRATTER</b> plusieurs fois la surface de la <b>LÉSION</b> au moyen d'un <b>ABAISSE-LANGUE</b> ou d'une <b>SPATULE EN MÉTAL</b> » ⭐<br>3. ⭐ « <b>ÉTALER</b> le produit de <b>RACLAGE</b> sur lame » ⭐<br>4. ⭐ « <b>FIXER IMMÉDIATEMENT</b> » ⭐<br>5. ⭐ « <b>COLORATION</b> : <b>H&amp;E</b>, <b>PAPANICOLAOU</b>, <b>BLEU DE MÉTHYLÈNE</b> » ⭐⭐ <b>LES 3 — TOMBABLES</b><br><br><b>🔴 ⭐⭐ APPLICATIONS EN MÉDECINE DENTAIRE :</b><br>• Dépistage des <b>lésions potentiellement malignes</b> et des <b>cancers buccaux</b> ⭐<br>• ⭐ <b>Cellules de TZANCK</b> (herpès) ⭐ · <b>candidose</b> · <b>lichen plan buccal</b><br>• ⭐ <b>Détection du HPV</b> par PCR/hybridisation <b>in situ</b> sur cellules exfoliées ⭐⭐ <b>LIEN AVEC LE COURS DE PR ROCHD (sondes/génie génétique)</b><br>• ⭐⭐ <b>Les cellules épithéliales buccales = la SOURCE D'ADN la plus simple pour un test génétique</b> (« buccal swab ») ⭐⭐ <b>EXCELLENT À CITER</b><br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « Le frottis buccal donne un <b>diagnostic définitif</b> » → <b>FAUX</b> ⭐⭐ <b>LE PIÈGE N°1</b><br>❌ « Le fixateur est le <b>formol</b> » → <b>FAUX</b> (<b>alcool/éther</b> ou <b>éthylène/glycol</b>) ⭐<br>✅ « Méthode non agressive, rapide, facile » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>MET vs MEB</b> : chno l-far9 ? (w 3lach l-MEB mouhim f dentaire)","a":"<b>🔴 ⭐ L-FAR9 F KELMA WA7DA :</b><br>• <b>MET</b> (transmission) : les électrons ⭐ <b>TRAVERSENT</b> la coupe → t-chouf ⭐ <b>L-DAKHEL</b> → image <b>2D</b><br>• <b>MEB</b> (balayage) : les électrons ⭐ <b>BALAYENT LA SURFACE</b> → t-chouf ⭐ <b>L-BARRA</b> → image <b>3D</b> ⭐⭐<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>MET = D</b>akhel (2D) · <b>MEB = B</b>arra (3D) » → <b>D / B</b> ⭐<br><br><b>🔴 ⭐⭐ LE TABLEAU COMPARATIF :</b><br>• <b>Résolution</b> : MET = ⭐ <b>~0,1-0,2 nm</b> (la meilleure) · MEB = <b>~5-10 nm</b><br>• <b>Grossissement</b> : MET = <b>×1 500 → ×600 000</b> · MEB = <b>×10 → ×500 000</b><br>• <b>Image</b> : MET = <b>2D</b> · MEB = ⭐ <b>3D</b> (grande profondeur de champ) ⭐<br>• <b>Ce qu'on voit</b> : MET = ⭐ <b>ULTRASTRUCTURE</b> · MEB = ⭐ <b>SURFACE / TOPOGRAPHIE</b><br>• <b>Préparation</b> : MET = coupe <b>40-60 nm</b> · MEB = ⭐ <b>échantillon ENTIER</b> (pas de coupe) + ⭐ <b>MÉTALLISATION</b><br><br><b>🔴 ⭐⭐ LA MÉTALLISATION (POINT CLÉ) :</b><br>• ⚠️ L'échantillon doit être <b>CONDUCTEUR</b> — sinon les électrons s'accumulent = ⭐ <b>« effet de charge »</b><br>• ⭐ Les échantillons <b>BIOLOGIQUES ne sont PAS conducteurs</b> → on les recouvre d'une couche mince de ⭐ <b>MÉTAL</b> (<b>or</b> ou <b>carbone</b>)<br>• ⭐ <b>C'est ça la « MÉTALLISATION »</b> ⭐⭐ <b>MOT À CONNAÎTRE</b><br><br><b>🔴 ⭐⭐⭐ POURQUOI LE MEB EST ULTRA PERTINENT EN MÉDECINE DENTAIRE :</b><br>1. ⭐ <b>L'ÉMAIL</b> — les <b>prismes de l'émail</b>, les cristaux d'<b>hydroxyapatite</b><br>2. ⭐⭐ <b>LE MORDANÇAGE ACIDE</b> — ⭐ <b>L'ASAS DYAL L-ADHÉSION</b> : l'acide ortho-phosphorique <b>37 %</b> crée des <b>MICROPOROSITÉS</b> dans l'émail → la résine y entre → forme ⭐ <b>les « TAGS » DE RÉSINE</b> ⭐⭐ <b>PRINCIPE DU COMPOSITE — TOMBABLE EN MATÉRIAUX</b><br>3. ⭐ <b>LA JONCTION ÉMAIL-COMPOSITE</b> (gaps, infiltration)<br>4. ⭐ <b>LES IMPLANTS</b> — la <b>rugosité</b> de la surface du <b>titane</b> → ⭐ <b>l'ostéointégration</b><br>5. ⭐ <b>L'INSTRUMENTATION CANALAIRE</b> — déformation/fracture des limes<br>6. ⭐ <b>LA PLAQUE BACTÉRIENNE / LE BIOFILM</b> — le MEB est <b>idéal</b> pour voir les bactéries ⭐⭐<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « Le MEB nécessite des coupes de <b>40-60 nm</b> » → <b>FAUX</b> (<b>c'est le MET</b>) ⭐<br>❌ « Le MEB a une <b>meilleure</b> résolution que le MET » → <b>FAUX</b> (le <b>MET</b> est meilleur) ⭐<br>✅ « Le MEB donne une image en <b>3D</b> de la <b>surface</b> » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>LE FRACTIONNEMENT CELLULAIRE</b> : l'ordre de sédimentation w les 2 conditions","a":"<b>🔴 ⭐⭐ LES ÉTAPES (À APPRENDRE PAR CŒUR — TOMBABLE) :</b><br><br><b>1.</b> ⭐ <b>600 g × 10 min</b> → ⭐ <b>LES NOYAUX</b> (les plus gros) + débris + cytosquelette<br><b>2.</b> ⭐ <b>10 000 g × 20 min</b> → ⭐ <b>LES MITOCHONDRIES</b> + lysosomes + peroxysomes<br><b>3.</b> ⭐ <b>100 000 g × 60 min</b> → ⭐ <b>LES MICROSOMES</b> (fragments de <b>RE</b> et de <b>Golgi</b>)<br><b>4.</b> ⭐ <b>300 000 g</b> → ⭐ <b>LES RIBOSOMES</b><br><b>5.</b> ⭐ <b>LE SURNAGEANT FINAL</b> → ⭐ <b>LE CYTOSOL</b> (enzymes solubles)<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>N</b>oyau → <b>M</b>itochondrie → <b>M</b>icrosome → <b>R</b>ibosome → <b>C</b>ytosol » = <b>N-M-M-R-C</b> ⭐<br>⚠️ ⭐ <b>LA LOGIQUE :</b> le poids <b>DIMINUE</b>, la vitesse <b>AUGMENTE</b> ⭐⭐<br><br><b>🔴 ⭐⭐ LES 2 CONDITIONS (TRÈS TOMBABLES) :</b><br>1. ⭐ <b>À FROID — 0 à 4 °C</b> ⭐ → pour que les enzymes ne <b>détruisent pas</b> les organites<br>2. ⭐ <b>Milieu ISOTONIQUE — SACCHAROSE 0,25 M</b> ⭐ → pour éviter l'<b>éclatement</b> des organites (osmose)<br><br>⚠️ <b>PIÈGE MAJEUR :</b><br>❌ « On utilise de l'<b>eau distillée</b> » → ⭐⭐ <b>FAUX</b> — l'eau distillée est <b>HYPOTONIQUE</b> → les organites ⭐ <b>ÉCLATENT</b> ⭐⭐<br><br><b>🔴 ⭐ L'IDENTIFICATION — LES MARQUEURS ENZYMATIQUES :</b><br>• ⭐ <b>PEROXYSOMES</b> → <b>CATALASE</b> ⭐⭐ <b>LE PLUS CLASSIQUE</b><br>• <b>LYSOSOMES</b> → <b>phosphatase acide</b><br>• <b>MITOCHONDRIES</b> → <b>succinate déshydrogénase</b><br>• <b>RE</b> → <b>glucose-6-phosphatase</b><br>• <b>GOLGI</b> → <b>galactosyltransférase</b><br><br><b>🔴 LA CENTRIFUGATION ISOGRAPHIQUE (bonus) :</b><br>• ⭐ Sépare selon la <b>DENSITÉ</b> (sur gradient de <b>saccharose</b> ou <b>Percoll</b>)<br>• ⭐ Plus <b>précise</b> → permet de purifier les <b>LYSOSOMES</b> et les <b>PEROXYSOMES</b><br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « Les noyaux sédimentent à <b>10 000 g</b> » → <b>FAUX</b> (<b>600 g</b> — ils sont les plus gros) ⭐<br>❌ « Le cytosol sédimente en <b>premier</b> » → <b>FAUX</b> — ⭐ <b>c'est le SURNGEANT FINAL</b> (il ne sédimente jamais) ⭐⭐<br>✅ « La catalase est le marqueur des <b>peroxysomes</b> » → <b>VRAI</b> ⭐⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>ÉLECTROPHORÈSE vs CHROMATOGRAPHIE</b> : chno l-far9 ? (w de quel côté migre l'ADN ?)","a":"<b>🔴 ⭐⭐ LA QUESTION LA PLUS CLASSIQUE : DE QUEL CÔTÉ MIGRE L'ADN ?</b><br>⭐⭐ <b>L'ADN migre vers l'<b>ANODE (+)</b></b> ⭐⭐<br>• ⚠️ <b>POURQUOI ?</b> L'ADN porte des groupements ⭐ <b>PHOSPHATE</b> chargés ⭐ <b>NÉGATIVEMENT</b><br>• ⚠️ « Les charges <b>opposées s'attirent</b> » → l'ADN (−) va vers l'anode (+) ⭐⭐⭐<br><br><b>🔴 ⭐ L'ÉLECTROPHORÈSE :</b><br>• <b>PRINCIPE :</b> un <b>CHAMP ÉLECTRIQUE</b> sépare les molécules ⭐ <b>CHARGÉES</b><br>• <b>T-chbiha :</b> comme une course — ⭐ <b>les petits vont LOIN, les gros restent PRÈS</b> ⭐<br>• <b>SUPPORTS :</b><br>&nbsp;&nbsp;– ⭐ <b>GEL D'AGAROSE</b> → pour l'<b>ADN</b><br>&nbsp;&nbsp;– ⭐ <b>GEL DE POLYACRYLAMIDE (PAGE)</b> → pour les <b>PROTÉINES</b><br>• ⭐ <b>SDS-PAGE</b> : le <b>SDS</b> donne une <b>charge négative uniforme</b> → ⭐ <b>séparation UNIQUEMENT selon le POIDS MOLÉCULAIRE</b> ⭐⭐<br>• <b>RÉVÉLATION :</b> <b>Bleu de Coomassie</b>, <b>nitrate d'argent</b>, ⭐ <b>BET (bromure d'éthidium)</b> — ⚠️ <b>fluorescent sous UV</b> ⭐<br>• ⭐ <b>WESTERN BLOT</b> = électrophorèse + transfert sur membrane + <b>anticorps</b><br>• ⭐⭐ <b>ÉLECTROPHORÈSE DES PROTÉINES SÉRIQUES — 6 FRACTIONS :</b> <b>ALBUMINE · α1 · α2 · β1 · β2 · γ</b> — ⚠️⭐ <b>un « PIC MONOCLONAL » dans les γ = MYÉLOME</b> ⭐⭐<br><br><b>🔴 ⭐ LA CHROMATOGRAPHIE :</b><br>• <b>PRINCIPE :</b> séparation par <b>PARTAGE entre DEUX PHASES</b><br>&nbsp;&nbsp;– ⭐ <b>PHASE STATIONNAIRE</b> (fixe)<br>&nbsp;&nbsp;– ⭐ <b>PHASE MOBILE</b> (qui circule)<br>• <b>T-chbiha :</b> comme l'<b>encre sur un buvard</b> — ⭐ <b>chaque couleur monte à une vitesse différente</b> ⭐<br>• <b>LES 4 TYPES :</b><br>&nbsp;&nbsp;1. ⭐ <b>EXCLUSION STÉRIQUE</b> (gel filtration) → selon la ⭐ <b>TAILLE</b> (les gros sortent en premier)<br>&nbsp;&nbsp;2. ⭐ <b>ÉCHANGE D'IONS</b> → selon la ⭐ <b>CHARGE</b><br>&nbsp;&nbsp;3. ⭐ <b>AFFINITÉ</b> → selon l'<b>affinité spécifique</b> (anticorps, <b>His-Tag + nickel</b>)<br>&nbsp;&nbsp;4. <b>PARTAGE / CCM / HPLC</b> → selon la <b>polarité</b><br>• ⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>T</b>aille · <b>C</b>harge · <b>A</b>ffinité · <b>S</b>olubilité » = <b>T-C-A-S</b> ⭐<br><br><b>🔴 ⭐⭐ LA DIFFÉRENCE CLÉ :</b><br>• <b>ÉLECTROPHORÈSE</b> → ⭐ <b>champ ÉLECTRIQUE</b> → seulement les molécules ⭐ <b>CHARGÉES</b><br>• <b>CHROMATOGRAPHIE</b> → ⭐ <b>2 phases</b> → ⭐ <b>n'importe quelle</b> molécule<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « L'ADN migre vers la <b> cathode </b>(−) » → ⭐⭐ <b>FAUX</b> — il va vers l'<b>ANODE (+)</b> ⭐⭐ <b>LE PIÈGE N°1</b><br>❌ « L'agarose sert pour les <b>protéines</b> » → <b>FAUX</b> (c'est le <b>polyacrylamide</b>) ⭐<br>✅ « En SDS-PAGE, la séparation se fait selon le <b>poids moléculaire</b> » → <b>VRAI</b> ⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>L'AUTORADIOGRAPHIE</b> : l-fikra, les isotopes, w l-expérience dyal PALADE","a":"<b>🔴 ⭐ L-FIKRA :</b><br>⭐ <b>Marquer une molécule avec un ISOTOPE RADIOACTIF → la cellule l'accepte (elle la croit normale) → on suit OÙ elle va</b> ⭐<br>• <b>T-chbiha :</b> comme un ⭐ <b>GPS caché</b> dans un téléphone — on suit la personne ⭐ <b>sans qu'elle le sache</b> ⭐<br><br><b>🔴 ⭐⭐ LES ISOTOPES (À CONNAÎTRE) :</b><br>• ⭐⭐ <b>³H-THYMIDINE</b> (thymidine tritiée) → ⭐⭐ marque <b>L'ADN</b> → étudie la <b>RÉPLICATION / PROLIFÉRATION</b> ⭐⭐ <b>LE PLUS IMPORTANT</b><br>• ⭐ <b>³H-URIDINE</b> → marque <b>L'ARN</b> → la <b>TRANSCRIPTION</b><br>• ⭐ <b>³H-LEUCINE</b> (ou <b>³⁵S-méthionine</b>) → marque <b>LES PROTÉINES</b> → la <b>TRADUCTION / SÉCRÉTION</b><br>• <b>³²P</b> → acides nucléiques, <b>phosphorylation</b><br>• <b>¹⁴C, ¹²⁵I, ⁴⁵Ca</b><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>T</b>hymidine → <b>A</b>DN · <b>U</b>ridine → <b>A</b>RN · <b>L</b>eucine → <b>P</b>rotéine » = <b>T-U-L</b> ⭐<br><br><b>🔴 ⭐⭐⭐ L'EXPÉRIENCE DE PALADE — LE « PULSE-CHASE » (PRIX NOBEL 1974) :</b><br><b>1. PULSE</b> : on donne de la <b>³H-leucine</b> radioactive pendant <b>3 minutes</b> seulement<br><b>2. CHASE</b> : on donne ensuite de la leucine <b>NON radioactive</b> (normale)<br><b>3.</b> ⭐ On suit <b>où se trouve la radioactivité</b> comme une vague :<br><br>⭐ <b>3 min</b> → ⭐ <b>LE RÉTICULUM ENDOPLASMIQUE (RE)</b><br>⭐ <b>7 min</b> → ⭐ <b>L'APPAREIL DE GOLGI</b><br>⭐ <b>37 min</b> → ⭐ <b>LES VÉSICULES DE SÉCRÉTION</b><br>⭐ <b>117 min</b> → ⭐ <b>L'EXOCYTOSE</b> (sortie de la cellule)<br><br>⭐⭐ <b>HADI HIYA LA VOIE DE SÉCRÉTION — TOMBABLE DANS TOUS LES EXAMENS DE BIOLOGIE CELLULAIRE</b><br>⚠️ <b>PRIX NOBEL 1974 : Palade, Claude, de Duve</b> ⭐<br><br><b>🔴 ⭐⭐ 2ᵉ EXPÉRIENCE CÉLÈBRE — TAYLOR, WOODS &amp; HUGHES (1957) :</b><br>• Avec la <b>³H-thymidine</b> sur les chromosomes de la ⭐ <b>FÈVE (<i>Vicia faba</i>)</b><br>• ⭐⭐ Ils ont DÉMONTRÉ que la réplication est ⭐⭐ <b>SEMI-CONSERVATRICE</b><br>• ⚠️⭐ <b>LIEN DIRECT AVEC LE COURS DE PR ROCHD</b> (chap. II : « La réplication est semi-conservatrice et bidirectionnelle ») ⭐⭐ <b>EXCELLENT À CITER</b><br><br><b>🔴 ⭐ L'AVANTAGE MAJEUR (vs les colorations) :</b><br>• ⭐ L'autoradiographie étudie une ⭐ <b>CELLULE VIVANTE</b> et son ⭐ <b>FONCTIONNEMENT DYNAMIQUE DANS LE TEMPS</b><br>• ⚠️ Les colorations ne donnent qu'une image <b>STATIQUE</b> d'une cellule <b>MORTE</b> ⭐⭐<br><br><b>🔴 ⭐ AUJOURD'HUI :</b><br>• ⚠️ L'autoradiographie est <b>moins utilisée</b> (sécurité, déchets radioactifs)<br>• ⭐ Remplacée par : <b>BrdU / EdU</b> (analogues de la thymidine révélés par ⭐ <b>anticorps anti-BrdU</b>), l'<b>immunofluorescence</b>, la <b>GFP</b> ⭐<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « La ³H-thymidine marque les <b>protéines</b> » → <b>FAUX</b> (c'est l'<b>ADN</b>) ⭐⭐<br>❌ « L'autoradiographie étudie une cellule <b>morte</b> » → <b>FAUX</b> (<b>VIVANTE</b>) ⭐<br>✅ « L'expérience de Palade a élucidé la <b>voie de sécrétion</b> : RE → Golgi → vésicules → exocytose » → <b>VRAI</b> ⭐⭐","t":"biocell-methodes EXAM-2026 M111 QCM"},{"q":"QCM — ⭐⭐ <b>LA CULTURE CELLULAIRE</b> : l-milieu, les conditions, w <b>HeLa</b>","a":"<b>🔴 ⭐⭐ LE MILIEU DE CULTURE (TOMBABLE) :</b><br>• ⭐ <b>MEM / DMEM / RPMI</b> → les <b>nutriments</b> (acides aminés, vitamines, glucose)<br>• ⭐⭐ <b>SÉRUM DE VEAU FŒTAL (SVF) — 10 %</b> → ⭐ les <b>FACTEURS DE CROISSANCE</b> ⭐⭐ <b>LE PLUS TOMBABLE</b><br>• <b>ANTIBIOTIQUES</b> (pénicilline + streptomycine) → empêcher les bactéries<br>• <b>GLUTAMINE</b> → acide aminé essentiel en culture<br>• ⭐ <b>BICARBONATE / tampon HEPES</b> → ⭐ maintenir le <b>pH 7,2 - 7,4</b><br><br><b>🔴 ⭐ LES CONDITIONS :</b><br>• ⭐ <b>Étuve à 37 °C</b> (température du corps)<br>• ⭐⭐ <b>Atmosphère humide avec 5 % de CO₂</b> ⭐⭐ → pour stabiliser le pH<br>• ⭐ <b>STÉRILITÉ</b> — ⭐ <b>PSM</b> = Poste de Sécurité Microbiologique (hotte à flux laminaire)<br><br><b>🔴 ⭐⭐ LES 2 TYPES (TOMBABLE) :</b><br>• ⭐ <b>CULTURE PRIMAIRE</b> → ⭐ durée de vie <b>LIMITÉE</b> — ⭐ <b>~50 divisions</b> = <b>limite de Hayflick</b> ⭐ (liée au raccourcissement des <b>TÉLOMÈRES</b>)<br>• ⭐ <b>LIGNÉE CELLULAIRE (continue)</b> → ⭐ <b>IMMORTELLE</b> — obtenue par transformation spontanée ou par <b>oncogènes</b> (<b>SV40 grand T</b>, <b>HPV E6/E7</b>)<br>• <b>EXPLANT / organoïdes / culture 3D</b><br><br><b>🔴 ⭐⭐⭐ L'HISTOIRE DE HeLa (À CONNAÎTRE — question d'éthique) :</b><br>• <b>1951</b> · cellules d'un ⭐ <b>CANCER DU COL DE L'UTÉRUS</b><br>• Prélevées sur ⭐⭐ <b>Henrietta Lacks</b><br>• ⚠️⭐ <b>SANS SON CONSENTEMENT</b> — elle et sa famille ne l'ont jamais su<br>• ⭐ Ces cellules sont <b>encore utilisées partout dans le monde</b> (vaccins, cancer, COVID...)<br>• ⚠️ <b>C'est LE grand cas d'école d'ÉTHIQUE en biologie</b> ⭐⭐ <b>TOMBABLE</b><br><br><b>🔴 ⭐ LES APPLICATIONS :</b><br>• ⭐⭐ <b>LE CARYOTYPE</b> — ⚠️ <b>LIEN AVEC LA CYTOGÉNÉTIQUE : c'est pour ça qu'on utilise le CHOC HYPOTONIQUE !</b> ⭐⭐ <b>LIEN DIRECT AVEC LE COURS DE BIOCELL</b><br>• Tests de <b>cytotoxicité / pharmacologie</b> · <b>production de protéines recombinantes</b> (insuline !) · <b>virologie</b> · <b>FIV</b> · ⭐ <b>thérapie cellulaire (CAR-T)</b> · 🦷 <b>ingénierie tissulaire parodontale</b><br><br><b>🔴 ⭐ LA CONTAMINATION LA PLUS FRÉQUENTE :</b><br>⭐⭐ <b>LES MYCOPLASMES</b> ⭐⭐ — ⚠️ bactéries <b>SANS PAROI</b> → ⭐ invisibles au microscope + ⭐ <b>résistantes</b> aux antibiotiques courants<br><br><b>⚠️ PIÈGES DU QCM :</b><br>❌ « La culture primaire est <b>immortelle</b> » → <b>FAUX</b> (limitée à ~50 divisions) ⭐<br>❌ « On cultive à <b>25 °C</b> » → <b>FAUX</b> (<b>37 °C</b>)<br>✅ « Le SVF apporte les <b>facteurs de croissance</b> » → <b>VRAI</b> ⭐⭐<br>✅ « HeLa vient d'un cancer du col sans consentement » → <b>VRAI</b> ⭐⭐","t":"biocell-methodes EXAM-2026 M111 QCM"}]},{"id":"biocell-S1-2026","nom":"🧫 Biologie cellulaire","src":"Examen N2026","ordre":6,"module":"M111","desc":"Q41–Q50 de l'examen 2026","cards":[{"q":"Q41 — L'<b>ENVELOPPE NUCLÉAIRE</b> : quelles sont ses caractéristiques ?","a":"<b>📋 L'ENVELOPPE NUCLÉAIRE — STRUCTURE EN 5 COUCHES :</b><br><br>Vue du nucléoplasme vers le cytoplasme :<br><br><b>1. MEMBRANE INTERNE</b><br>• Contient des <b>protéines TRANSMEMBRANAIRES SPÉCIFIQUES</b> ⚠️ qui <b>N'EXISTENT PAS dans la membrane externe</b> :<br>&nbsp;&nbsp;– <b>LAMINE B RÉCEPTEUR (LBR — Lamin B Receptor)</b> : ancre la <b>lamina</b> et l'<b>hétérochromatine</b> ; possède une activité <b>stérol réductase</b> ⚠️ (mutations → <b>syndrome de GREENBERG / dysplasie de Pelger-Huët</b>)<br>&nbsp;&nbsp;– <b>ÉMERINE</b> ⚠️ (mutations → <b>DYSTROPHIE MUSCULAIRE D'EMERY-DREIFUSS liée à l'X</b>)<br>&nbsp;&nbsp;– <b>LAMINES A/C réceptrices, MAN1, LEM-domain proteins, SUN1/SUN2</b><br>• Sa face nucléoplasmique est tapissée par la <b>LAMINA</b><br><br><b>2. LA LAMINA (lamina fibreuse / lame fibreuse) ⭐</b><br>• Réseau de <b>FILAMENTS INTERMÉDIAIRES DE TYPE V</b> = les <b>LAMINES</b>, épais de <b>10 à 100 nm</b>, tapissant la face interne de la membrane interne<br>• <b>LAMINES DE TYPE A</b> : <b>lamine A, lamine C</b> (gène <b>LMNA, 1q22</b>, épissage alternatif) — ⚠️ exprimées seulement <b>APRÈS la différenciation</b> (absentes des cellules souches et embryonnaires précoces)<br>• <b>LAMINES DE TYPE B</b> : <b>lamine B1 (LMNB1, 5q31)</b>, <b>lamine B2 (LMNB2, 19p13)</b> — ⚠️ exprimées dans <b>TOUTES</b> les cellules ; elles sont <b>PRÉNYLÉES</b> (farnésylation de la <b>cysteine de la boîte CaaX</b>) → ancrage membranaire permanent<br>• <b>Structure des lamines</b> : domaine central <b>α-hélicoïdal (rod domain)</b> + extrémités <b>N- et C-terminales globulaires</b> → <b>dimères enroulés (coiled-coil)</b> → <b>tétramères antiparallèles</b> → <b>protofilaments</b> → réseau <b>orthogonal 2D</b><br>• ⭐ <b>FONCTIONS DE LA LAMINA :</b><br>&nbsp;&nbsp;a) <b>SUPPORT STRUCTURAL</b> du noyau — lui donne sa forme et sa rigidité mécanique<br>&nbsp;&nbsp;b) ⚠️ <b>POINT D'ANCRAGE DE L'HÉTÉROCHROMATINE</b> — la lamine se lie à l'<b>ADN par l'intermédiaire de l'hétérochromatine</b> et des <b>protéines HP1/LBR/BAF</b> → organise les <b>domaines associés à la lamina (LADs — Lamina-Associated Domains)</b>, qui sont des régions <b>réprimées transcriptionnellement</b> (⚠️ <b>la lamina ne se lie PAS directement à l'ADN</b> — elle passe par l'hétérochromatine)<br>&nbsp;&nbsp;c) <b>ANCRAGE DES PORES NUCLÉAIRES</b><br>&nbsp;&nbsp;d) <b>RÉGULATION DE LA MITOSE</b> : en prophase, la lamina est <b>PHOSPHORYLÉE</b> par <b>CDK1/MPF</b> sur des résidus sérine spécifiques → <b>DÉSASSEMBLAGE</b> → désintégration de l'enveloppe ; en télophase, elle est <b>DÉPHOSPHORYLÉE</b> → <b>RÉASSEMBLAGE</b><br>&nbsp;&nbsp;e) <b>ÉCHEFAUDAGE pour la réplication et la transcription</b><br>&nbsp;&nbsp;f) ⚠️ <b>SIGNALISATION MÉCANOTRANSDUCTION</b> via les complexes <b>LINC</b> (SUN-KASH) reliant le cytosquelette au noyau<br>&nbsp;&nbsp;g) <b>RÔLE DANS LE VIEILLISSEMENT</b> : ⚠️ la <b>PROGÉRINE</b> (lamine A mutée, délétion de 50 aa due à une mutation silencieuse <b>c.1824C&gt;T, G608G</b> activant un site cryptique d'épissage) reste <b>farnésylée en permanence</b> → s'accumule → noyaux déformés → <b>PROGERIA DE HUTCHINSON-GILFORD</b>. Traitement : <b>lonafarnib</b> (inhibiteur de la farnésyltransférase) ⭐<br>• ⚠️ <b>LAMINOPATHIES</b> : > 15 maladies dues aux mutations de LMNA — <b>dystrophie musculaire d'Emery-Dreifuss AD</b>, <b>cardiomyopathie dilatée avec troubles de conduction</b>, <b>lipodystrophie partielle familiale (Dunnigan)</b>, <b>progeria</b>, <b>neuropathie axonale de Charcot-Marie-Tooth type 2B1</b>, <b>syndrome de Dunnigan</b>, <b>mandibuloacral dysplasia</b><br><br><b>3. ESPACE PÉRINUCLÉAIRE (citerne péri-nucléaire)</b><br>• Large de <b>20 à 40 nm</b> (jusqu'à 70 nm)<br>• ⚠️ Il est <b>EN CONTINUITÉ avec la CITERNE DU RÉTICULUM ENDOPLASMIQUE RUGUEUX</b> ⭐<br>• Contient un <b>milieu dense aux électrons</b>, similaire à la lumière du RE<br>• ⚠️ Les <b>protéines membranaires</b> peuvent diffuser librement entre la membrane externe et celle du RE<br><br><b>4. MEMBRANE EXTERNE</b><br>• ⚠️ <b>EN CONTINUITÉ DIRECTE avec le RÉTICULUM ENDOPLASMIQUE RUGUEUX</b> ⭐⭐ C'EST LA CARACTÉRISTIQUE FONDAMENTALE<br>• Sa face <b>CYTOPLASMIQUE est couverte de RIBOSOMES</b> → elle est donc <b>morphologiquement et fonctionnellement IDENTIQUE au RER</b><br>• Ces ribosomes <b>synthétisent des protéines directement dans l'espace périnucléaire</b> (= lumière du RE)<br>• ⚠️ La membrane externe contient les mêmes protéines que le RE (ex. <b>cytochrome P450, protéines de la translocation</b>)<br>• Elle contient les protéines <b>KASH</b> (nesprines) du complexe LINC<br><br><b>5. LES PORES NUCLÉAIRES</b> (voir Q42) — traversent les deux membranes<br><br><b>📋 FONCTIONS GLOBALES DE L'ENVELOPPE NUCLÉAIRE :</b><br>1. <b>COMPARTIMENTATION</b> : sépare le <b>matériel génétique</b> du cytoplasme → ⚠️ permet le <b>DÉCOUPLAGE SPATIO-TEMPOREL entre TRANSCRIPTION (noyau) et TRADUCTION (cytoplasme)</b> — c'est la caractéristique définissant l'<b>EUCARYOTE</b>. Chez les procaryotes, la traduction commence <b>avant</b> la fin de la transcription → permet l'épissage, le contrôle qualité, l'export sélectif<br>2. <b>PROTECTION de l'ADN</b> contre les agressions mécaniques et enzymatiques du cytoplasme<br>3. <b>RÉGULATION DES ÉCHANGES</b> nucléocytoplasmiques via les pores<br>4. <b>ORGANISATION DE LA CHROMATINE</b> (hétérochromatine péri-nucléolaire)<br>5. <b>ANCRAGE DU CYTOSQUELETTE</b> via LINC → migration cellulaire, positionnement du noyau<br>6. <b>SIGNALISATION</b> (lamines = plateformes de signalisation, séquestration de facteurs de transcription comme SREBP1, Rb, MOK2)<br><br><b>📋 CYCLE DE L'ENVELOPPE NUCLÉAIRE PENDANT LA MITOSE ⚠️ :</b><br>• <b>PROMÉTAPHASE</b> : <b>PHOSPHORYLATION des lamines par CDK1</b> → désassemblage ; phosphorylation des <b>nucléoporines</b> → désassemblage des pores ; ⚠️ <b>l'enveloppe se FRAGMENTE en VÉSICULES</b> qui sont <b>ABSORBÉES dans le RE</b> (elle ne disparaît pas — elle fusionne avec le RE). Deux modèles : « <b>vesiculation</b> » (classique, animaux) et « <b>absorption dans le RE</b> » (le plus admis)<br>• <b>MÉTAPHASE</b> : pas d'enveloppe — les chromosomes sont libres dans le cytoplasme → ⚠️ c'est le stade utilisé pour le <b>CARYOTYPE</b><br>• <b>TELOPHASE</b> : ⚠️ <b>DÉPHOSPHORYLATION</b> par les phosphatases PP1 → <b>RÉASSEMBLAGE autour des chromatides</b>. Les vésicules membranaires se lient à la chromatine via l'<b>émerine, LBR, BAF (Barrier-to-Autointegration Factor)</b>, les <b>Histones</b>. La lamina se reforme. <b>FUSION des membranes</b> (dépendante de l'<b>ATPase p97/VCP</b>) → pores réassemblés<br>• ⚠️ <b>MITOSE OUVERTE</b> (animaux supérieurs) = désintégration complète · <b>MITOSE FERMÉE</b> (levures) = l'enveloppe reste intacte, le fuseau se forme à l'intérieur<br><br><b>📋 AUTRES POINTS :</b><br>• ⚠️ L'enveloppe nucléaire <b>SE DOUBLE de surface</b> pendant l'interphase (croissance du noyau)<br>• Le <b>noyau</b> occupe ~<b>10 % du volume cellulaire</b>, diamètre <b>5–10 µm</b><br>• <b>Nombre d'enveloppes</b> : <b>DEUX membranes</b> (double membrane) ⚠️ comme la mitochondrie et le chloroplaste<br>• ⚠️ <b>La membrane externe est CONTINUE avec le RE, mais l'enveloppe elle-même n'est PAS en continuité ouverte avec le cytosol</b>","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q42 — Les <b>PORES NUCLÉAIRES</b> : structure, composition et fonction","a":"<b>📋 LE PORE NUCLÉAIRE (NPC — Nuclear Pore Complex) :</b><br><br><b>1. STRUCTURE GLOBALE :</b><br>• C'est un <b>complexe protéique ÉNORME</b> qui traverse <b>LES DEUX membranes</b> de l'enveloppe nucléaire<br>• <b>Masse : ~60 à 125 MDa</b> chez les vertébrés ⚠️ (soit <b>~30 fois plus gros qu'un ribosome</b> 80S, qui fait ~4 MDa)<br>• <b>Diamètre externe : ~120 nm</b> · <b>Épaisseur : ~50 nm</b><br>• ⚠️ <b>DIAMÈTRE DU CANAL CENTRAL (ouvert) : ~40 à 50 nm</b>, mais <b>DIAMÈTRE FONCTIONNEL DE DIFFUSION LIBRE : ~9 à 10 nm</b> (le reste est occupé par le bouchon de FG-répétitions)<br>• <b>DENSITÉ : 3 000 à 5 000 pores par noyau</b> de mammifère ⚠️ (soit <b>~10 à 20 % de la surface totale</b> de l'enveloppe). Peut atteindre <b>10⁷</b> dans les ovocytes d'amphibiens (utilisés pour la purification des NPC)<br>• ⚠️ Le nombre de pores est <b>proportionnel à l'activité de transcription</b> de la cellule<br><br><b>2. SYMÉTRIE :</b><br>⚠️ <b>SYMÉTRIE OCTOGONALE (symétrie 8)</b> autour d'un axe perpendiculaire à l'enveloppe — c'est la caractéristique architecturale fondamentale<br>• <b>ANNEAU CYTOPLASMIQUE</b> (anneau externe)<br>• <b>ANNEAU NUCLÉOPLASMIQUE</b> (anneau interne) — ⚠️ ces deux anneaux sont <b>SYMÉTRIQUES</b><br>• <b>ANNEAU CENTRAL / ÉCHEFAUDAGE INTERNE</b> (scaffold) — fait de <b>« Y-complexes » (Nup107-160)</b> en double copie<br>• ⚠️ Mais les <b>FILAMENTS CYTOPLASMIQUES</b> et le <b>PANIER NUCLÉAIRE (basket)</b> sont <b>ASYMÉTRIQUES</b> → le pore est donc <b>GLOBALEMENT ASYMÉTRIQUE</b> dans ses extensions, même si son cœur est symétrique<br><br><b>3. COMPOSITION — LES NUCLÉOPORINES (Nups) :</b><br>• ⚠️ <b>~30 NUCLÉOPORINES DIFFÉRENTES</b>, en <b>~500 à 1 000 copies par pore</b> (la plupart en 8, 16 ou 32 copies selon la symétrie)<br>• <b>TROIS CLASSES de Nups :</b><br>&nbsp;&nbsp;<b>a) Nups TRANSMEMBRANAIRES (d'ancrage)</b> — ⚠️ seules protéines <b>intégrées dans la membrane</b> : <b>GP210 (NUP210), POM121, NDC1</b> → ancrent le NPC dans la membrane et la <b>courbent</b> au niveau de la région de fusion des 2 membranes (le « pore membraneux »)<br>&nbsp;&nbsp;<b>b) Nups d'ÉCHEFAUDAGE (scaffold)</b> — structure en <b>répétitions β-propeller + α-solenoid</b> ⚠️ (motif architectural caractéristique, pas de transmembranaire) : le <b>COMPLEXE Y (Nup107-160)</b> = <b>Nup160, Nup133, Nup107, Nup96, Nup85, Nup43, Nup37, Seh1, Sec13</b> ; et le complexe <b>Nup93-205 (Nup205, Nup188, Nup155, Nup93, Nup62, Nup58, Nup54)</b><br>&nbsp;&nbsp;<b>c) ⚠️ Nups « FG » (barrière de perméabilité)</b> — les plus importantes fonctionnellement : <b>riches en répétitions PHÉNYLALANINE-GLYCINE (motif FG)</b>, dans des régions <b>INTRINSÈQUEMENT DÉSORDONNÉES (IDR)</b>, non structurées, flexibles. Elles forment un <b>GEL HYDROPHOBE / MAillage sélectif</b> au centre du pore. Ex. : <b>Nup62, Nup214, Nup358/RanBP2, Nup153, Nup98, Nup42</b><br>&nbsp;&nbsp;&nbsp;&nbsp;⚠️ <b>MÉCANISME DE SÉLECTIVITÉ :</b> les <b>RÉCEPTEURS DE TRANSPORT (importines/exportines = karyophérines)</b> possèdent des <b>domaines HEAT</b> qui <b>interagissent avec les motifs FG</b> par des interactions <b>hydrophobes faibles et transitoires</b> → ils <b>« fondent » / traversent le gel</b> comme dans un solvant organique (modèle de « <b>selective phase / réduction de dimensionnalité</b> »). Les macromolécules <b>SANS récepteur sont EXCLUES</b><br>&nbsp;&nbsp;&nbsp;&nbsp;⚠️ <b>Nup98</b> est aussi impliquée dans les <b>leucémies</b> (translocations NUP98-HOXA9, NUP98-NSD1)<br><br><b>4. EXTENSIONS :</b><br>• <b>FILAMENTS CYTOPLASMIQUES</b> (8) : <b>Nup358/RanBP2</b> (⚠️ possède un domaine <b>SUMO E3 ligase</b>, site d'ancrage du <b>complexe RAN-GAP1</b> et des microtubules), <b>Nup214, Nup88, RanBP1</b><br>• <b>PANIER NUCLÉAIRE (nuclear basket)</b> : filaments de <b>Nup153</b> et <b>Nup50</b> reliés par <b>Tpr/Megator</b> — ⚠️ site de <b>rétention des ARNm mal épissés</b> et de <b>contrôle qualité</b> · <b>Tpr</b> est surexprimé dans plusieurs cancers<br><br><b>5. ⭐ FONCTION : TRANSPORT NUCLÉOCYTOPLASMIQUE SÉLECTIF :</b><br><br><b>a) DIFFUSION LIBRE (passive)</b><br>• Molécules <b>&lt; 40 à 60 kDa</b> ou <b>&lt; 5 nm de diamètre</b> : ions, métabolites, petites protéines, ARNt, nucléotides → passent <b>librement</b> en quelques millisecondes<br>• ⚠️ Au-delà, la diffusion chute <b>exponentiellement</b> (une protéine de 60 kDa diffuse encore lentement ; au-delà de ~100 kDa c'est quasi nul)<br><br><b>b) TRANSPORT ACTIF / FACILITÉ — DÉPENDANT DE L'ÉNERGIE ⚠️</b><br>• <b>Import</b> : protéines nucléaires (ADN/ARN polymérases, histones, facteurs de transcription, ribonucléoprotéines) — signal = <b>NLS (Nuclear Localization Signal)</b><br>&nbsp;&nbsp;– <b>NLS CLASSIQUE (monopartite)</b> : séquence basique riche en <b>Lys/Arg</b> — ⚠️ exemple canonique : <b>PKKKRKV</b> de l'<b>ANTIGÈNE T du virus SV40</b><br>&nbsp;&nbsp;– <b>NLS BIPARTITE</b> : deux groupes basiques séparés par ~10 aa — ex. <b>nucléoplasmine</b> (KRPAATKKAGQAKKKK)<br>&nbsp;&nbsp;– <b>NLS non classique</b> : ex. <b>M9</b> (hétérogène, hnRNP A1) → reconnu par <b>transportine</b><br>&nbsp;&nbsp;• <b>MÉCANISME :</b> NLS → reconnu par l'<b>IMPORTINE α (adaptateur, karyophérine α)</b> → recrutement de l'<b>IMPORTINE β1</b> → le <b>complexe cargo-importineα-importineβ</b> traverse le pore en interagissant avec les FG-Nups → côté <b>NUCLÉOPLASMIQUE</b>, <b>RAN-GTP</b> se lie à l'importine β → <b>DISSOCIATION</b> du complexe → le cargo est libéré → importine β-RanGTP et importine α (avec CAS/RanGTP) retournent au cytoplasme<br>• <b>Export</b> : ARNm, ARNr, ARNt, protéines — signal = <b>NES (Nuclear Export Signal)</b>, séquence <b>riche en LEUCINE</b> (ex. <b>LQLPPLERLTL</b> de PKI, ou du VIH Rev) → reconnu par l'<b>EXPORTINE 1 / CRM1</b> en présence de <b>RAN-GTP</b> → traversée → côté cytoplasmique, <b>RAN-GAP1 + RANBP1</b> hydrolysent RanGTP en RanGDP → dissociation<br>• <b>Export des ARNm</b> : <b>NXFP1/TAP-p15 (NXF1-NXT1)</b>, pas de RanGTP requis de la même façon ; l'ARNm est « marqué » par le <b>complexe TREX</b> et les <b>protéines de jonction d'exon (EJC)</b> après l'épissage<br>• <b>Export des ARNt</b> : <b>exportine-t (Xpo-t)</b> ; <b>pré-ARNr 60S/40S</b> : <b>CRM1, exportine-5</b><br>• <b>Transport des microARN</b> : <b>exportine-5 (XPO5)</b> pour les pré-miRNA<br><br><b>c) ⭐ LE MOTEUR ÉNERGÉTIQUE : LE GRADIENT DE RAN</b><br>• ⚠️ <b>Le transport nucléaire n'utilise PAS directement l'ATP au niveau du pore</b> — il utilise le <b>GRADIENT DE RAN-GTP/RAN-GDP</b>, qui est lui-même maintenu par l'<b>HYDROLYSE DE GTP</b><br>• <b>Dans le NOYAU</b> : <b>RCC1 (Regulator of Chromosome Condensation 1)</b> = <b>FACTEUR D'ÉCHANGE DE GUANINE (GEF)</b>, ancré à la <b>CHROMATINE (histones H2A/H2B)</b> → convertit RanGDP en <b>RanGTP</b> → ⚠️ <b>RAN-GTP ÉLEVÉ dans le NOYAU</b><br>• <b>Dans le CYTOPLASME</b> : <b>RAN-GAP1</b> (cytosolique et sur les filaments cytoplasmiques de Nup358) = <b>GTPase-ACTIVATING PROTEIN (GAP)</b>, associée à <b>RANBP1</b> → stimule l'hydrolyse du GTP → <b>RanGDP</b> → ⚠️ <b>RAN-GDP ÉLEVÉ dans le CYTOPLASME</b><br>• <b>NTF2 (Nuclear Transport Factor 2)</b> : ramène <b>RanGDP</b> dans le noyau<br>• <b>MOG1/RanBP</b> : régulateurs<br>• ⚠️ <b>Ce gradient asymétrique est la SOURCE D'ÉNERGIE et de DIRECTIONNALITÉ</b> du transport<br>• <b>RAN</b> est aussi essentielle à l'<b>assemblage du FUSEAU MITOTIQUE</b> et à la <b>formation de l'enveloppe en télophase</b><br>• ⚠️ <b>Pharmacologie</b> : la <b>LEPTOMYCINE B</b> et le <b>SÉLINEXOR</b> (anti-myélome) inhibent CRM1<br><br><b>6. ⚠️ AUTRES FONCTIONS DU PORE (au-delà du transport) :</b><br>• <b>RÉGULATION DE L'EXPRESSION GÉNIQUE</b> : ⚠️ <b>« gene gating hypothesis »</b> — les gènes actifs sont <b>recrutés au pore</b> ; certaines Nups (<b>Nup98, Nup2, Mlp1/2</b>) participent à l'activation transcriptionnelle<br>• <b>CONTRÔLE QUALITÉ DES ARNm</b> : les <b>transcrits mal épissés sont RETENUS au panier nucléaire</b> et dégradés<br>• <b>ORGANISATION DE LA CHROMATINE</b> : les Nups créent des <b>domaines d'hétérochromatine</b> aux bords du noyau<br>• <b>ASSEMBLAGE DU FUSEAU</b> : en mitose ouverte, certaines Nups (<b>Nup107-160</b>) se localisent aux <b>KINÉTOCHORES</b> ⚠️<br>• <b>SIGNALISATION</b> : le pore contrôle l'accès nucléaire des facteurs de transcription (NF-κB, p53, β-caténine, STAT) → régulation dynamique<br>• ⚠️ <b>PATHOLOGIE — LES « NUCLEOPORINOPATHIES » :</b><br>&nbsp;&nbsp;– <b>DÉFICIT IMMUNITAIRE avec ACHATESIE / hypothyroïdie / dysplasie</b> : mutations de <b>NUP62</b><br>&nbsp;&nbsp;– <b>SYNDROME NÉPHROTIQUE de la petite enfance (Galloway-Mowat)</b> : mutations de <b>WDR73</b> et de Nups du complexe KEOPS<br>&nbsp;&nbsp;– <b>SCLÉROSE LATÉRALE AMYOTROPHIQUE (SLA) et DÉMENCE FRONTOTEMPORALE</b> : agrégats de <b>Nup62</b>, altération de <b>TDP-43</b> et <b>FUS</b> (qui portent un NLS) → défaut d'import nucléaire ⭐<br>&nbsp;&nbsp;– <b>LEUCÉMIES</b> : translocations impliquant <b>NUP98</b> (NUP98-HOXA9, NUP98-NSD1) → leucémies aiguës agressives<br>&nbsp;&nbsp;– <b>CANCERS</b> : surexpression de <b>Nup88, Nup358, Tpr, CRM1</b> dans de nombreuses tumeurs (mauvais pronostic)<br>&nbsp;&nbsp;– <b>AUTO-ANTICORPS ANTI-GP210 et ANTI-p62/SP100</b> ⚠️ : marqueurs sérologiques de la <b>CHOLANGITE BILIAIRE PRIMITIVE (CBP)</b> — les anti-gp210 sont très spécifiques<br>&nbsp;&nbsp;– <b>VIRUS</b> : le <b>VIH</b> (via Vpr et le complexe d'intégration), les <b>herpèsvirus</b>, la <b>grippe</b> (NS1) détournent ou dégradent les Nups","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q43 — L'<b>EUCHROMATINE</b> : quelles sont ses caractéristiques ? (et comparaison avec l'hétérochromatine)","a":"<b>📋 EUCHROMATINE — DÉFINITION :</b> forme de chromatine <b>DÉCONDENSÉE, CLAIRE au microscope électronique</b>, <b>TRANSCRIPTIONNELLEMENT ACTIVE</b> (ou compétente pour l'être). Elle représente la <b>MAJORITÉ du génome actif</b>.<br><br><b>1. ✅ CARACTÉRISTIQUES STRUCTURALES :</b><br>• <b>DÉCONDENSÉE / RELÂCHÉE</b> : apparence de <b>« collier de perles »</b> (nucléosomes espacés), diamètre ~<b>10 nm</b> (fibre nucléosomique), sans compaction en 30 nm<br>• ⚠️ <b>CLAIRE AUX ÉLECTRONS</b> en MET (elle ne fixe pas les colorants denses)<br>• ⚠️ <b>COLORE PEU en coloration de Feulgen / Giemsa</b> → correspond aux <b>BANDES CLAIRES (bandes R-positives, G-négatives)</b> du caryotype<br>• Localisée <b>AU CENTRE du noyau</b> (loin de l'enveloppe), en <b>grappes/îlots</b><br>• <b>REPRÉSENTE ~90 % du génome humain</b> en termes de masse d'ADN ⚠️ (mais la grande majorité est inactive à un moment donné — seule une petite fraction est transcrite dans un type cellulaire donné)<br>• ⚠️ <b>N'est PAS riche en ADN satellite</b> — l'ADN satellite est dans l'hétérochromatine<br>• ⚠️ <b>RICHE EN GÈNES</b> (la plupart des gènes codants s'y trouvent)<br><br><b>2. ✅ CARACTÉRISTIQUES FONCTIONNELLES :</b><br>• ⭐ <b>TRANSCRIPTIONNELLEMENT ACTIVE</b> — c'est le critère fondamental<br>• <b>RÉPLICATION PRÉCOCE</b> ⚠️ — se réplique au <b>DÉBUT de la phase S</b> (l'hétérochromatine se réplique <b>TARD</b>, en fin de phase S)<br>• <b>RICHE EN G-C</b> (60 % GC vs 40 % pour l'hétérochromatine) → ⚠️ c'est pourquoi ces régions ont des <b>îlots CpG</b> et des <b>températures de fusion (Tm) plus élevées</b><br>• <b>Contient les ÎLOTS CpG</b> : régions de <b>0,5 à 2 kb</b> avec un <b>ratio CpG observé/attendu &gt; 0,6</b> et un <b>taux de GC &gt; 55 %</b> — présentes au niveau des <b>promoteurs de ~70 % des gènes humains</b>. ⚠️ Quand elles sont <b>NON MÉTHYLÉES</b> → gène <b>ACTIF/compétent</b> ; quand elles sont <b>MÉTHYLÉES</b> → gène <b>SILENCIEUX</b> (mécanisme majeur de régulation et d'<b>empreinte parentale</b>)<br>• <b>Accessibilité aux facteurs de transcription, à l'ARN polymérase II et aux machineries de réparation</b><br>• ⚠️ <b>Peut se CONDENSER en hétérochromatine et inversement</b> = <b>PLASTICITÉ ÉPIGÉNÉTIQUE</b> (transitions euchromatine ↔ hétérochromatine au cours de la différenciation)<br><br><b>3. ⭐ MARQUEURS ÉPIGÉNÉTIQUES DE L'EUCHROMATINE ACTIVE :</b><br>• <b>HISTONES</b> : riches en <b>H3 et H4</b>, présence des <b>VARIANTS H3.3, H2A.Z</b> (au niveau des promoteurs actifs)<br>• <b>MODIFICATIONS ACTIVATRICES des histones :</b><br>&nbsp;&nbsp;– <b>ACÉTYLATION des lysines</b> (H3K9ac, H3K14ac, H3K27ac, H4K5/K8/K12/K16ac) ⭐ — neutralise la charge positive → <b>réduit l'affinité ADN-histone</b> → ouverture ; effectuée par les <b>HAT (Histone AcétylTransférases : p300/CBP, GCN5)</b><br>&nbsp;&nbsp;– <b>MÉTHYLATION H3K4me3</b> → ⭐ marqueur des <b>PROMOTEURS ACTIFS</b><br>&nbsp;&nbsp;– <b>H3K4me1</b> → marqueur des <b>ENHANCERS</b><br>&nbsp;&nbsp;– <b>H3K36me3</b> → ⭐ marqueur du <b>CORPS DES GÈNES EN COURS DE TRANSCRIPTION (élongation)</b><br>&nbsp;&nbsp;– <b>H3K79me2</b> → gènes actifs<br>&nbsp;&nbsp;– <b>PHOSPHORYLATION H3S10</b> → mitose et activation immédiate<br>&nbsp;&nbsp;– <b>UBIQUITINATION H2BK120ub</b><br>• <b>ADN</b> : <b>HYPOMÉTHYLÉ</b> ⚠️ (faible taux de 5-méthylcytosine aux îlots CpG des promoteurs actifs)<br>• <b>SENSIBLE À LA DNase I</b> ⭐ — les <b>« sites hypersensibles à la DNase I » (DHS)</b> marquent les <b>promoteurs, enhancers et régions régulatrices actives</b> — c'est le test expérimental classique pour cartographier l'euchromatine<br>• <b>Protéines associées</b> : <b>facteurs de transcription, ARN polymérase II, complexe de remodelage (SWI/SNF), chaperonnes d'histones</b><br><br><b>📋 HÉTÉROCHROMATINE — POUR COMPARER :</b><br><br><b>a) HÉTÉROCHROMATINE CONSTITUTIVE</b> ⚠️<br>• <b>Toujours condensée, dans TOUTES les cellules, à tous les stades</b><br>• Localisation : <b>centromères, télomères, bras courts des acrocentriques (NOR), bras long du Y (Yq12), régions 1qh/9qh/16qh</b><br>• <b>ADN SATELLITE</b> : <b>α-satellite</b> (centromère, monomère de <b>171 pb</b> en tandem, site de fixation de la <b>CENP-A</b>), <b>satellite 1, 2, 3</b>, <b>ADNr en tandem</b><br>• <b>Très pauvre en gènes</b> — quasi « <b>désert génique</b> »<br>• <b>Réplication TRÈS TARDIVE</b> (fin de phase S)<br>• <b>Marqueurs :</b> ⭐ <b>H3K9me3</b> + <b>HP1</b> (Heterochromatin Protein 1, via son <b>chromodomaine</b>) ; <b>H4K20me3</b> ; <b>H3K27me3</b> pour certaines ; <b>DNA MÉTHYLÉE (5mC)</b> · enzyme clé : <b>SUV39H1/H2</b> (H3K9 méthyltransférase)<br>• <b>BANDES C au caryotype</b> ✅<br><br><b>b) HÉTÉROCHROMATINE FACULTATIVE</b> ⚠️<br>• <b>Condensée dans CERTAINES cellules ou à CERTAINS stades, mais pas dans d'autres</b> → potentiellement réversible<br>• Exemples :<br>&nbsp;&nbsp;– ⭐ <b>LE CHROMOSOME X INACTIF (CORPUSCULE DE BARR)</b> : chez la femme, <b>1 des 2 X est inactivé au hasard</b> vers le <b>jour 12–16</b> (stade blastocyste), de façon <b>STABLE et CLONALE</b>. Mécanisme : transcription du <b>lncRNA XIST</b> (X-Inactive Specific Transcript, locus <b>XIC — X-Inactivation Center, Xq13</b>) → il <b>recouvre l'X en cis</b> → recrutement de <b>PRC2</b> (EZH2 → <b>H3K27me3</b>) et de <b>macroH2A</b> → condensation. ⚠️ <b>Le X inactif reste actif pour ~15 % des gènes</b> (surtout dans la région pseudo-autosomale PAR1) → c'est pourquoi les aneuploïdies X ne sont pas létales. ⚠️ Les gènes qui échappent à l'inactivation expliquent le phénotype des <b>syndromes XXY, XXX</b><br>&nbsp;&nbsp;– <b>EMPREINTE PARENTALE (imprinting)</b> : l'allèle maternel ou paternel est condensé de façon stable selon son origine<br>&nbsp;&nbsp;– <b>Genes silencieux tissu-spécifiques</b> (hétérochromatine de différenciation)<br>• <b>Marqueurs :</b> <b>H3K27me3</b> (PRC2), <b>H3K9me2/3</b>, <b>HP1</b>, <b>DNA méthylation</b>, <b>macroH2A</b><br><br><b>📊 TABLEAU COMPARATIF À APPRENDRE PAR CŒUR :</b><br>• <b>Condensation</b> : Eu = <b>décondensée</b> · Hét = <b>condensée</b><br>• <b>Apparence MET</b> : Eu = <b>CLAIRE</b> · Hét = <b>SOMBRE/dense aux électrons</b><br>• <b>Caryotype</b> : Eu = <b>bandes R+, G−</b> · Hét = <b>bandes G+, C+</b><br>• <b>Localisation dans le noyau</b> : Eu = <b>centrale</b> · Hét = <b>PÉRIPHÉRIQUE (sous l'enveloppe)</b> + <b>autour des nucléoles</b> + centromères<br>• <b>Activité transcriptionnelle</b> : Eu = <b>ACTIVE</b> · Hét = <b>SILENCIEUSE</b><br>• <b>Réplication</b> : Eu = <b>PRÉCOCE (début de S)</b> · Hét = <b>TARDIVE (fin de S)</b><br>• <b>Contenu en GC</b> : Eu = <b>RICHE en G-C</b> · Hét = <b>RICHE en A-T</b><br>• <b>Densité en gènes</b> : Eu = <b>ÉLEVÉE</b> · Hét = <b>FAIBLE (déserts géniques)</b><br>• <b>Îlots CpG</b> : Eu = <b>PRÉSENTS, non méthylés</b> · Hét = <b>absents ou hyperméthylés</b><br>• <b>Méthylation de l'ADN</b> : Eu = <b>FAIBLE</b> · Hét = <b>ÉLEVÉE</b><br>• <b>Histones</b> : Eu = <b>acétylées, H3K4me3, H3K36me3, H3.3, H2A.Z</b> · Hét = <b>désacétylées, H3K9me3, H3K27me3, HP1, macroH2A</b><br>• <b>Sensibilité DNase I</b> : Eu = <b>SENSIBLE (hypersensible)</b> · Hét = <b>RÉSISTANTE</b><br>• <b>Proportion du génome</b> : Eu = <b>~90 %</b> · Hét = <b>~10 %</b><br>• <b>Réversibilité</b> : Eu ↔ Hét = <b>OUI, dynamique</b> (sauf hétérochromatine constitutive qui est permanente)<br><br><b>🧪 APPLICATIONS CLINIQUES :</b><br>• ⭐ <b>CORPUSCULE DE BARR (test de Barr)</b> : frottis de <b>muqueuse buccale</b> coloré → recherche de la <b>masse de chromatine sexuelle</b> accolée à l'enveloppe → présent chez <b>46,XX</b> (1 corpuscule), absent chez <b>46,XY</b>. ⚠️ <b>Formule : nombre de corpuscules de Barr = nombre d'X − 1</b> → 47,XXY = <b>1</b> ; 47,XXX = <b>2</b> ; 45,X = <b>0</b>. Utilisé historiquement pour le <b>contrôle de féminité</b> aux JO (abandonné, remplacé par PCR SRY)<br>• <b>CODE DES HISTONES</b> : le profil combiné des modifications détermine l'état de la chromatine → cible thérapeutique : <b>inhibiteurs des HDAC (vorinostat, romidepsine)</b>, <b>inhibiteurs des méthyltransférases (azacitidine, décitabine — inhibiteurs de DNMT ; tazemetostat — inhibiteur d'EZH2)</b>, <b>inhibiteurs de BET/BRD4</b><br>• ⚠️ <b>CANCER</b> : l'<b>hyperméthylation des îlots CpG des gènes suppresseurs de tumeurs</b> (MLH1, p16, BRCA1, GSTP1) est un événement précoce et universel — utilisé comme biomarqueur (ADN circulant, test de méthylation SEPT9 pour le cancer colorectal)","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q44 — Le <b>NUCLÉOSOME</b> : composition de l'octamère d'histones, longueur d'ADN, structure","a":"<b>📋 LE NUCLÉOSOME — L'UNITÉ FONDAMENTALE DE LA CHROMATINE :</b><br><br><b>1. DÉFINITION :</b> structure élémentaire de compaction de l'ADN, formée d'un <b>OCTAMÈRE D'HISTONES</b> autour duquel s'enroule l'<b>ADN</b>.<br><br><b>2. ⭐ L'OCTAMÈRE (cœur du nucléosome) — À APPRENDRE PAR CŒUR :</b><br>Il est composé de <b>8 sous-unités</b> = <b>4 types d'histones × 2 copies</b> :<br>• <b>2 × H2A</b><br>• <b>2 × H2B</b><br>• <b>2 × H3</b><br>• <b>2 × H4</b><br><br>⚠️ <b>ASSEMBLAGE HIÉRARCHIQUE :</b><br>1. <b>TÉTRAMÈRE (H3-H4)₂</b> : 2 dimères H3-H4 s'associent → <b>cœur central</b>, c'est le <b>premier</b> à se lier à l'ADN ⚠️<br>2. <b>2 DIMÈRES H2A-H2B</b> viennent se fixer de part et d'autre du tétramère → <b>OCTAMÈRE</b> complet<br>3. ⚠️ <b>L'ADN s'enroule d'abord autour du tétramère (H3-H4)₂</b> (~<b>60 pb</b>), puis les dimères H2A-H2B complètent le tour (~<b>86 pb</b> supplémentaires)<br><br>⚠️ <b>L'HISTONE H1 N'EST PAS DANS L'OCTAMÈRE</b> — c'est la <b>PIÈGE CLASSIQUE</b> ⭐. Elle est <b>externe</b>, elle se lie à l'<b>ADN de liaison (linker)</b> et au nucléosome → elle n'est donc <b>PAS comptée dans l'octamère de 8</b>.<br><br><b>3. L'ADN AUTOUR DU NUCLÉOSOME :</b><br>• ⚠️ <b>146 à 147 PAIRES DE BASES</b> d'ADN enroulées autour de l'octamère (le « <b>core particle</b> ») — valeur canonique : <b>147 pb</b> par cristallographie (Luger et al., 1997)<br>• <b>1,65 TOURS</b> (≈ <b>1,7 tour</b>) d'hélice en <b>SUPERHÉLICE GAUCHE (solénoïde négatif)</b> ⚠️<br>• ⚠️ Avec l'histone H1 et l'ADN de liaison : <b>~166 à 200 pb</b> par nucléosome (valeur moyenne classiquement retenue : <b>~200 pb</b>)<br>• <b>ADN DE LIAISON (linker DNA)</b> : <b>20 à 80 pb</b> entre deux nucléosomes (variable selon l'espèce et le type cellulaire ; <b>~50 pb</b> chez l'homme en moyenne)<br>• ⚠️ <b>Cela compresse l'ADN d'un facteur ~7</b> : les 2 m d'ADN humain → <b>11 nm × nombre de nucléosomes</b>... En fait la <b>fibre de 10 nm</b> mesure déjà <b>~1/7</b> de la longueur d'ADN nu<br>• <b>Nombre de nucléosomes dans une cellule humaine</b> : ~<b>30 millions</b> (3 × 10⁹ pb / 200 pb)<br><br><b>4. STRUCTURE DU NUCLÉOSOME :</b><br>• Forme de <b>« disque » / cylindre aplati</b> : <b>11 nm de diamètre × 6 nm de hauteur</b><br>• ⚠️ C'est ce qui donne l'aspect de <b>« COLLIER DE PERLES »</b> (beads on a string) en microscopie électronique après choc hypotonique = la <b>FIBRE DE 10 nm</b> (ou 11 nm)<br>• ⚠️ <b>L'ADN entre en contact avec l'octamère par 14 points</b>, via des <b>liaisons ioniques</b> entre les <b>phosphates (charge −)</b> de l'ADN et les <b>résidus LYSINE et ARGININE (charge +)</b> des histones<br>• ⚠️ <b>Les queues N-terminales des histones SORTENT du nucléosome</b> → elles sont <b>ACCESSIBLES aux modifications covalentes</b> (acétylation, méthylation, phosphorylation, ubiquitination, SUMOylation, ADP-ribosylation) = <b>CODE DES HISTONES</b><br><br><b>5. ⭐ LES HISTONES — CARACTÉRISTIQUES :</b><br>• <b>PROTÉINES TRÈS BASIQUES</b> ⚠️ — riches en <b>LYSINE (K) et ARGININE (R)</b> → <b>charge nette POSITIVE à pH physiologique</b> → interaction <b>électrostatique</b> avec l'ADN (chargé négativement)<br>• <b>PETITES</b> (11 à 21 kDa, ~<b>102 à 135 acides aminés</b>)<br>• <b>Domaine central « HISTONE FOLD »</b> : <b>3 hélices α</b> reliées par 2 boucles (motif <b>helix-turn-helix-turn-helix</b>) → permet la <b>dimérisation</b> par interaction <b>coiled-coil/handshake</b><br>• <b>Queues N-terminales flexibles et non structurées</b> (et queue C-terminale pour H2A) → sites de modification<br>• ⚠️ <b>CE SONT LES PROTÉINES LES PLUS CONSERVÉES DE L'ÉVOLUTION</b> ⭐ : H4 ne diffère que de <b>2 acides aminés</b> entre le pois et la vache ! H3 diffère d'<b>1 seul résidu</b> entre l'oursin et le veau. Cette conservation témoigne de leur rôle structural critique<br>• ⚠️ <b>Les gènes des histones sont en CLUSTERS MULTICOPIES</b> sans introns, avec une <b>boucle tige (stem-loop)</b> en 3' au lieu d'une queue polyA → expression couplée à la <b>phase S</b><br>• <b>CLASSIFICATION selon la composition en lysine :</b><br>&nbsp;&nbsp;– <b>TRÈS RICHES EN LYSINE</b> : <b>H1, H2A</b><br>&nbsp;&nbsp;– <b>MODÉRÉMENT RICHES EN LYSINE</b> : <b>H2B</b><br>&nbsp;&nbsp;– <b>RICHES EN ARGININE</b> : <b>H3, H4</b> ⭐<br>• ⭐ <b>L'HISTONE H1 (histone de liaison / linker histone)</b> :<br>&nbsp;&nbsp;– <b>La plus GRANDE et la plus BASIQUE</b> (~<b>21 kDa, 220 aa</b>)<br>&nbsp;&nbsp;– Structure en <b>3 domaines</b> : N-terminal court et basique, <b>domaine globulaire central (winged-helix)</b>, C-terminal long et très basique<br>&nbsp;&nbsp;– ⚠️ <b>Se lie à l'ADN de LIAISON et à l'ADN du nucléosome</b> (au site d'entrée/sortie) → <b>« scelle » les 2 tours d'ADN</b><br>&nbsp;&nbsp;– ⚠️ <b>FONCTION CLÉ : elle est RESPONSABLE DE LA COMPACTION de la fibre 10 nm en FIBRE 30 nm (solénoïde)</b><br>&nbsp;&nbsp;– <b>5 SOUS-TYPES chez les mammifères</b> (H1.1 à H1.5) + variants (H1°, H1.0, H1X, H1t/H1FOO testiculaire)<br>&nbsp;&nbsp;– ⚠️ <b>Ratio H1 : nucléosome ≈ 1 : 1</b> (mais il peut y en avoir moins)<br>&nbsp;&nbsp;– Sa <b>phosphorylation</b> par <b>CDK</b> en mitose réduit son affinité → décondensation<br><br><b>6. ⭐ LES VARIANTS D'HISTONES (non canoniques) :</b><br>• <b>CENP-A (CENH3)</b> — variant de <b>H3</b> ⚠️ SPÉCIFIQUE DU <b>CENTROMÈRE</b> → <b>marqueur ÉPIGÉNÉTIQUE</b> de la position du centromère, site d'assemblage du <b>KINÉTOCHORE</b>. Mutations/surexpression → aneuploïdie, cancer<br>• <b>H3.3</b> — variant de H3 déposé <b>indépendamment de la réplication</b> sur les <b>gènes actifs, enhancers et télomères</b> → associé à la transcription. ⚠️ Mutations <b>H3.3 K27M</b> dans les <b>gliomes pédiatriques de la ligne médiane</b> (gliome diffus intrinsèque du tronc cérébral, DIPG) — inhibiteur dominant de PRC2<br>• <b>H2A.Z</b> — variant de H2A au niveau des <b>PROMOTEURS ACTIFS et des ENHANCERS</b>, et aussi de l'hétérochromatine (double rôle)<br>• <b>macroH2A</b> — très grand variant de H2A ⚠️ ENRICHI SUR LE <b>CHROMOSOME X INACTIF</b> (corpuscule de Barr) ; suppresseur de tumeur<br>• <b>H2A.X (γ-H2AX)</b> — ⚠️ <b>PHOSPHORYLÉ sur Ser139 par ATM/ATR/DNA-PK</b> en réponse aux <b>CASSURES DOUBLE BRIN</b> → forme des <b>FOCI</b> détectables par immunofluorescence → ⭐ <b>marqueur standard des dommages à l'ADN</b> (utilisé en radiobiologie et pour mesurer la radiosensibilité)<br>• <b>H1°/H1.0</b> — lié aux cellules différenciées/quiescentes<br>• <b>Protamines</b> ⚠️ — <b>NE SONT PAS des histones</b> : protéines <b>encore plus basiques (riches en arginine)</b> qui <b>REMPLACENT les histones</b> dans les <b>SPERMATOZOÏDES</b> → compaction extrême (×6 plus dense que la chromatine somatique) ; essentiel pour la fertilité masculine. Anomalies → infertilité, fragmentation de l'ADN spermatique<br><br><b>7. ⭐ MODIFICATIONS POST-TRADUCTIONNELLES — LE « CODE DES HISTONES » :</b><br>• <b>ACÉTYLATION (HAT/HDAC)</b> : sur les <b>lysines</b> des queues → <b>neutralise la charge +</b> → <b>réduit l'affinité pour l'ADN</b> → <b>OUVERTURE de la chromatine → TRANSCRIPTION ACTIVÉE</b> ⭐<br>&nbsp;&nbsp;– <b>HAT</b> : p300/CBP, GCN5, PCAF, Tip60, MOF, HBO1<br>&nbsp;&nbsp;– <b>HDAC</b> : classes I, II, III (sirtuines), IV → <b>désacétylation → condensation → répression</b><br>&nbsp;&nbsp;– ⚠️ Médicaments : <b>vorinostat (SAHA), romidepsine, belinostat, panobinostat</b> — inhibiteurs de HDAC (lymphome T cutané, myélome)<br>• <b>MÉTHYLATION (HMT/KDM)</b> : sur <b>lysine (mono/di/tri)</b> ou <b>arginine</b> — ⚠️ <b>ne change PAS la charge</b>, donc effet <b>INDIRECT</b> via le recrutement de <b>protéines lectrices (readers)</b> — peut être <b>ACTIVATRICE ou RÉPRESSIVE</b> selon le résidu :<br>&nbsp;&nbsp;– <b>ACTIVATRICES</b> : <b>H3K4me3</b> (promoteur), <b>H3K4me1</b> (enhancer), <b>H3K36me3</b> (corps du gène), <b>H3K79me2</b><br>&nbsp;&nbsp;– <b>RÉPRESSIVES</b> : <b>H3K9me3</b> (hétérochromatine constitutive, lu par <b>HP1</b>), <b>H3K27me3</b> (hétérochromatine facultative, déposé par <b>PRC2/EZH2</b>, lu par <b>PRC1</b>), <b>H4K20me3</b><br>&nbsp;&nbsp;– ⚠️ <b>« BIVALENT DOMAINS »</b> : <b>H3K4me3 + H3K27me3</b> sur les mêmes promoteurs dans les <b>CELLULES SOUCHES EMBRYONNAIRES</b> → gènes « <b>prêts mais silencieux</b> », résolus lors de la différenciation ⭐<br>• <b>PHOSPHORYLATION</b> : <b>H3S10ph</b> (mitose, activation immédiate précoce), <b>H2AX S139ph (γ-H2AX)</b> (cassures double brin), <b>H1ph</b> (mitose, par CDK1)<br>• <b>UBIQUITINATION</b> : <b>H2BK120ub</b> (transcription, nécessaire pour H3K4me3/H3K79me2), <b>H2AK119ub</b> (par PRC1 → répression)<br>• <b>SUMOylation, ADP-ribosylation, crotonylation, butyrylation, propionylation, citrullination (PADI4 sur H3R)</b><br>• ⚠️ Les <b>« writers, readers, erasers »</b> : enzymes qui écrivent, lisent et effacent ces marques. Les <b>readers</b> ont des domaines spécialisés : <b>bromodomaine</b> (lit l'acétyl-lysine), <b>chromodomaine</b> (lit la méthyl-lysine, ex. HP1), <b>PHD finger</b>, <b>tudor</b>, <b>MBT</b>, <b>PWWP</b><br><br><b>8. NIVEAUX SUPÉRIEURS DE COMPACTION ⭐ :</b><br>1. <b>ADN nu</b> — diamètre <b>2 nm</b><br>2. <b>NUCLÉOSOME (fibre de 10–11 nm, « collier de perles »)</b> — compaction <b>×7</b><br>3. <b>FIBRE DE 30 nm (solénoïde ou zigzag / two-start helix)</b> ⚠️ — dépendante de l'<b>HISTONE H1</b>, <b>6 nucléosomes par tour</b>, pas de <b>11 nm</b> — compaction <b>×40</b> au total. ⚠️ <b>SON EXISTENCE IN VIVO EST CONTESTÉE</b> : la cristallographie et la cryo-EM récente suggèrent que la chromatine in vivo est plutôt une <b>masse irrégulière, hétérogène et fluide</b> (modèle « <b>melted/polymer</b> ») que des solénoïdes réguliers<br>4. <b>BOUCLES / DOMAINES (loops) de 300 nm</b> — ancrées sur la <b>MATRICE NUCLÉAIRE (scaffold)</b> via les <b>SAR/MAR (Scaffold/Matrix Attachment Regions)</b>, organisées par <b>CTCF + COHÉSINE</b> → <b>DOMAINES TOPOLOGIQUEMENT ASSOCIÉS (TADs — Topologically Associating Domains)</b> ⭐, taille moyenne <b>~1 Mb</b>, compaction <b>×250</b><br>5. <b>ROSETTES / COILS — fibre de 700 nm</b> (chromatide en métaphase), compaction <b>×1 000</b><br>6. ⭐ <b>CHROMOSOME MÉTAPHASIQUE — 1 400 nm</b>, compaction totale <b>×10 000</b> (certains auteurs disent <b>×8 000 à ×10 000</b>)<br><br>⚠️ <b>MÉMO :</b> 2 nm → 10 nm → 30 nm → 300 nm → 700 nm → 1 400 nm<br>⚠️ <b>Tailles</b> : ADN total déplié = <b>~2 m</b> par cellule diploïde ; chromosome métaphasique = <b>~2 à 10 µm</b><br><br><b>9. ASSEMBLAGE ET DÉSASSEMBLAGE :</b><br>• <b>DÉPOSITION</b> pendant la <b>réplication (phase S)</b> : les <b>CHAPERONNES D'HISTONES</b> déposent les octamères sur l'ADN néosynthétisé :<br>&nbsp;&nbsp;– <b>CAF-1 (Chromatin Assembly Factor 1)</b> — dépose <b>(H3-H4)₂</b> couplé à la replication, reconnaît <b>PCNA</b><br>&nbsp;&nbsp;– <b>HIRA</b> — dépose <b>H3.3</b> indépendamment de la réplication<br>&nbsp;&nbsp;– <b>NAP1 (Nucleosome Assembly Protein 1)</b> — dépose <b>H2A-H2B</b><br>&nbsp;&nbsp;– <b>ASF1</b> — chaperonne H3-H4, travaille avec CAF-1 et HIRA<br>&nbsp;&nbsp;– <b>FACT (Facilitates Chromatin Transcription)</b> — <b>SSRP1 + SPT16</b> ⚠️ démonte/remonte les nucléosomes <b>devant l'ARN polymérase II</b> pendant la transcription<br>• <b>REMODELAGE</b> : complexes <b>ATP-dépendants</b> qui glissent, éjectent ou échangent les nucléosomes : <b>SWI/SNF (BAF, PBAF)</b>, <b>ISWI</b>, <b>CHD/Mi-2</b>, <b>INO80</b>. ⚠️ <b>SMARCB1 (INI1)</b> muté dans les <b>tumeurs rhabdoïdes</b> ; <b>ARID1A</b> muté dans > 20 % des cancers de l'ovaire/endomètre<br>• <b>POSITIONNEMENT</b> : ⚠️ les <b>promoteurs actifs ont un NDR (Nucleosome-Depleted Region)</b> — une zone sans nucléosome permettant l'accès des facteurs de transcription, encadrée par des nucléosomes bien positionnés (+1, −1)","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q45 — Différences entre l'<b>ARN</b> et l'<b>ADN</b> : quelles sont-elles ?","a":"<b>📋 ARN vs ADN — LES 6 DIFFÉRENCES FONDAMENTALES :</b><br><br><b>1. ⭐ LE SUCRE : RIBOSE vs DÉSOXYRIBOSE</b><br>• <b>ADN</b> : <b>2'-DÉSOXYRIBOSE</b> — il y a un <b>H</b> en position <b>2'</b> du cycle pentose<br>• <b>ARN</b> : <b>RIBOSE</b> — il y a un <b>OH (hydroxyle)</b> en position <b>2'</b><br>• ⚠️ <b>CONSÉQUENCE MAJEURE :</b> le <b>OH 2'</b> de l'ARN le rend <b>BEAUCOUP PLUS RÉACTIF et INSTABLE</b> :<br>&nbsp;&nbsp;– Il peut attaquer le <b>phosphore adjacent</b> → formation d'un <b>intermédiaire cyclique 2'-3' phosphate</b> → <b>HYDROLYSE SPONTANÉE du squelette</b> (hydrolyse alcaline)<br>&nbsp;&nbsp;– ⚠️ <b>L'ARN est HYDROLYSÉ en milieu ALCALIN (pH &gt; 9), l'ADN NON</b> — c'est un critère expérimental classique<br>&nbsp;&nbsp;– <b>Demi-vie de l'ARN</b> : quelques <b>minutes à quelques heures</b> (médiane ~<b>3 à 8 h</b> pour les ARNm humains) · <b>ADN</b> : <b>stable des années</b> (on extrait de l'ADN de fossiles de plusieurs dizaines de milliers d'années)<br>&nbsp;&nbsp;– ⚠️ C'est <b>LA RAISON pour laquelle l'ADN est le support de l'information génétique</b> et l'ARN n'est qu'un intermédiaire<br>• ⚠️ Le OH 2' permet aussi à l'ARN de former des <b>structures 3D complexes</b> (ribozymes, épissosome) que l'ADN ne peut pas former<br><br><b>2. ⭐ LES BASES AZOTÉES : THYMINE vs URACILE</b><br>• <b>Bases communes</b> : <b>ADÉNINE (A), GUANINE (G), CYTOSINE (C)</b><br>• <b>ADN</b> : contient de la <b>THYMINE (T)</b> = <b>5-MÉTHYL-URACILE</b><br>• <b>ARN</b> : contient de l'<b>URACILE (U)</b> — sans le groupe méthyle<br>• <b>Appariements</b> : <b>A=T (2 liaisons H)</b>, <b>G≡C (3 liaisons H)</b> dans l'ADN ; <b>A=U (2 liaisons H)</b>, <b>G≡C (3 liaisons H)</b> dans l'ARN<br>• ⚠️ <b>POURQUOI LA THYMINE ?</b> La <b>CYTOSINE se DÉAMINE spontanément en URACILE</b> (fréquence : ~<b>100 à 500 événements par cellule et par jour</b>). Si l'ADN utilisait l'uracile comme base normale, la cellule ne pourrait <b>PAS distinguer</b> un U légitime d'un U issu d'une désamination de C → mutations C→T. En utilisant la <b>THYMINE (U méthylé)</b>, tout <b>U dans l'ADN est RECONNU COMME ANORMAL</b> et <b>ÉLIMINÉ par l'URACILE-ADN GLYCOSYLASE (UNG)</b> dans la voie de <b>réparation par excision de base (BER)</b> ⭐<br>• ⚠️ <b>La 5-MÉTHYL-CYTOSINE (5mC)</b> existe aussi dans l'ADN (épigénétique) ; sa désamination donne la <b>THYMINE</b> → c'est pourquoi les <b>CpG sont des points chauds de mutation</b> (C→T) ⭐<br>• <b>Bases modifiées/minores :</b><br>&nbsp;&nbsp;– <b>ARN</b> : <b>+100 nucléosides modifiés</b> — <b>pseudouridine (Ψ)</b>, <b>dihydrouridine (D)</b>, <b>inosine (I)</b> ⚠️ (wobble, édition A→I par ADAR), <b>méthyladénosine (m6A)</b> ⭐ (la modification interne la plus abondante des ARNm, lue par YTHDF1/2/3, effacée par FTO/ALKBH5 — rôle dans la stabilité, la traduction, et maladies), <b>ribothymidine (T)</b>, <b>2'-O-méthylribose</b>, <b>queuosine</b>, <b>wybutosine</b><br>&nbsp;&nbsp;– <b>ADN</b> : <b>5-méthylcytosine (5mC)</b>, <b>5-hydroxyméthylcytosine (5hmC)</b> (abondante dans le cerveau, produit de TET1-3), <b>N6-méthyladénine</b> (bactéries), <b>glucosyl-hydroxyméthylcytosine</b> (bactériophages T-pairs)<br><br><b>3. ⭐ LA STRUCTURE : DOUBLE BRIN vs SIMPLE BRIN</b><br>• <b>ADN</b> : ⚠️ <b>DOUBLE BRIN (bicaténaire)</b> — les deux brins sont <b>ANTIPARALLÈLES</b> (un 5'→3', l'autre 3'→5'), <b>COMPLÉMENTAIRES</b>, enroulés en <b>DOUBLE HÉLICE</b><br>&nbsp;&nbsp;– <b>B-DNA</b> : la forme <b>physiologique dominante</b> — hélice <b>DROITE (droitier)</b>, <b>10,5 paires de bases par tour</b> ⚠️, pas de <b>3,4 nm</b>, diamètre <b>2 nm</b>, distance entre bases <b>0,34 nm</b>, <b>grand sillon</b> et <b>petit sillon</b> distincts, bases <b>perpendiculaires</b> à l'axe<br>&nbsp;&nbsp;– <b>A-DNA</b> : forme <b>déshydratée</b>, hélice droite, <b>11 pb/tour</b>, plus large (2,6 nm), bases <b>inclinées à 20°</b> — ressemble à l'<b>ARN double brin</b> et aux hybrides <b>ADN-ARN</b><br>&nbsp;&nbsp;– <b>Z-DNA</b> : hélice <b>GAUCHE (gaucher)</b> ⚠️, <b>12 pb/tour</b>, squelette en <b>zigzag</b>, alternance <b>purine-pyrimidine (CGCGCG)</b>, <b>pas de grand sillon</b> — formé en amont des gènes en cours de transcription (tension de sur-enroulement négatif), lié aux protéines <b>ADAR1, ZBP1</b><br>&nbsp;&nbsp;– Autres formes : <b>G-quadruplexes</b> (séquences riches en G, aux télomères et promoteurs — cible thérapeutique), <b>i-motifs</b> (C riches), <b>triplexes (H-DNA)</b>, <b>cruciformes</b>, <b>bulles</b><br>• <b>ARN</b> : ⚠️ <b>SIMPLE BRIN (monocaténaire)</b> en général<br>&nbsp;&nbsp;– <b>Mais</b> il forme des <b>structures secondaires INTRAMOLÉCULAIRES</b> : <b>tiges-boucles (hairpins/stem-loop)</b>, <b>boucles internes</b>, <b>renflements (bulges)</b>, <b>jonctions</b>, <b>pseudonœuds (pseudoknots)</b><br>&nbsp;&nbsp;– Appariements <b>non canoniques</b> permis : <b>G-U (wobble)</b> ⚠️ très fréquent, A-G, etc.<br>&nbsp;&nbsp;– <b>L'ARN peut donc avoir une structure 3D (tertiaire) avec une FONCTION CATALYTIQUE</b> → les <b>RIBOZYMES</b> ⭐<br>&nbsp;&nbsp;– ⚠️ <b>Exceptions :</b> certains <b>virus à ARN ont un génome DOUBLE BRIN</b> (Rotavirus, Réovirus, virus de la mosaïque) — dsRNA est un signal d'alerte reconnu par <b>RIG-I, MDA5, TLR3, PKR</b> → réponse interféron<br><br><b>4. LA LONGUEUR ET LA LOCALISATION :</b><br>• <b>ADN</b> : ⚠️ <b>TRÈS LONG</b> — le génome humain = <b>~3,2 Gb (3,2 × 10⁹ pb)</b>, soit <b>~2 m</b> d'ADN par cellule diploïde. <b>LOCALISATION : NOYAU</b> (chromosomes) + <b>MITOCHONDRIE</b> (ADNmt, <b>16 569 pb, circulaire, 37 gènes</b>) + <b>chloroplaste</b> (végétaux)<br>• <b>ARN</b> : <b>COURT</b> — de <b>20 nt (microARN)</b> à <b>~100 kb</b> (les plus grands ARNm, ex. <b>dystrophine ~14 kb</b>, <b>titine ~100 kb</b>). <b>LOCALISATION : NOYAU (synthèse et traitement) → CYTOPLASME (fonction)</b>, ribosomes, RER, mitochondrie<br>• ⚠️ <b>L'ARN n'est JAMAIS le génome principal des cellules</b> (seulement de certains virus)<br><br><b>5. ⭐ LA FONCTION :</b><br>• <b>ADN</b> : <b>STOCKAGE et TRANSMISSION de l'INFORMATION GÉNÉTIQUE</b> — molécule <b>STABLE, RÉPLIQUÉE fidèlement</b> (erreur : ~<b>1 par 10⁹ à 10¹⁰ nucléotides</b> grâce à la relecture), <b>archivée</b> dans des copies de secours (2 allèles)<br>• <b>ARN</b> : <b>EXPRESSSION de l'information + fonctions CATALYTIQUES et RÉGULATRICES</b> — molécule <b>TRANSITOIRE, DYNAMIQUE</b><br><br><b>6. ⭐ LA STABILITÉ ET LA RÉPARATION :</b><br>• <b>ADN</b> : <b>STABLE</b>, avec <b>DES SYSTÈMES DE RÉPARATION COMPLETS</b> (BER, NER, MMR, HR, NHEJ, direct reversal) et un système de <b>RELECTURE (proofreading) 3'→5' exonucléase</b> de l'ADN polymérase<br>• <b>ARN</b> : ⚠️ <b>INSTABLE</b>, et <b>PAS DE SYSTÈME DE RÉPARATION</b> — un ARN endommagé est simplement <b>DÉGRADÉ et REMPLACÉ</b>. L'ARN polymérase n'a <b>PAS d'activité de relecture</b> → taux d'erreur <b>~10⁻⁴ à 10⁻⁵</b> ⚠️<br><br><b>📋 LES TYPES D'ARN — À CONNAÎTRE :</b><br>• <b>ARNm (messager)</b> : <b>1 à 5 %</b> de l'ARN total — intermédiaire entre le gène et la protéine — <b>coiffe 5' (m7Gppp)</b>, <b>5'UTR</b>, <b>ORF/cadre de lecture</b>, <b>3'UTR</b>, <b>queue polyA (~200-250 A)</b><br>• ⭐ <b>ARNr (ribosomal)</b> : <b>80 à 85 %</b> de l'ARN total ⚠️ le plus abondant — <b>28S, 18S, 5.8S</b> (transcrits en <b>pré-ARNr 45S/47S</b> par l'<b>ARN pol I</b> dans le nucléole) + <b>5S</b> (par l'<b>ARN pol III</b>, hors nucléole) — composant structural et <b>CATALYTIQUE</b> du ribosome (le <b>28S est un RIBOZYME = peptidyl-transférase</b>)<br>• ⭐ <b>ARNt (transfert)</b> : <b>10 à 15 %</b> — <b>73 à 93 nt</b> — structure en <b>TRÈFLE</b> (2D) et en <b>L</b> (3D) — bras <b>accepteur (CCA-3')</b>, <b>bras D (dihydrouridine)</b>, <b>bras anticodon</b>, <b>bras TψC</b>, <b>bras variable</b> — apporte les acides aminés ; chargé par les <b>aminoacyl-ARNt synthétases</b> (20 enzymes, classe I et II) — ⚠️ <b>règle du wobble (Crick)</b> à la 3ᵉ position du codon<br>• <b>snARN (small nuclear)</b> : <b>U1, U2, U4, U5, U6</b> → composants des <b>snRNP</b> de l'<b>ÉPISSOSOME</b> (transcrits par l'ARN pol II ou III) — épissage des introns. ⚠️ Mutations de <b>SF3B1, U2AF1, SRSF2</b> dans les <b>SMD et LLC</b><br>• <b>snoARN (small nucleolar)</b> : <b>C/D box</b> (2'-O-méthylation) et <b>H/ACA box</b> (pseudouridylation) — modifient les ARNr dans le nucléole<br>• <b>microARN (miARN)</b> : <b>~22 nt</b> — régulation post-transcriptionnelle — biogenèse : <b>pri-miARN → Drosha/DGCR8 → pré-miARN → Exportine-5 → Dicer/TRBP → duplex → RISC (AGO2)</b> → <b>répression de la traduction ou dégradation de l'ARNm</b>. ⚠️ Ex. : <b>miR-21</b> (oncomiR), <b>let-7</b> (suppresseur), <b>miR-155</b>. Utilisés comme biomarqueurs<br>• <b>siARN (small interfering)</b> : <b>21-23 nt</b> double brin, parfaitement complémentaires → clivage de l'ARNm cible. ⚠️ Médicament : <b>patisiran</b> (Onpattro) pour l'<b>amylose héréditaire à transthyrétine</b> — le 1ᵉʳ siRNA approuvé<br>• <b>piARN (piwi-interacting)</b> : <b>26-31 nt</b> — silencent les <b>transposons</b> dans la <b>ligne germinale</b> (protéines PIWI : MIWI, MILI) — essentiels à la fertilité masculine<br>• <b>lncARN (long non-coding)</b> : <b>&gt; 200 nt</b> — <b>XIST</b> (inactivation du X), <b>HOTAIR</b> (recrute PRC2, métastases), <b>MALAT1</b>, <b>NEAT1</b> (corps paraspléiques), <b>TERRA</b> (télomères), <b>H19</b> (empreinte), <b>ANRIL</b><br>• <b>ARN circulaires (circARN)</b> — covalents, stables, éponges à miARN<br>• <b>eRNA (enhancer RNA)</b>, <b>ARN guide (gRNA)</b> des kinétoplastides, <b>ARN de la télomérase (TERC)</b>, <b>7SK</b>, <b>Y RNA</b>, <b>ARN 7SL (SRP)</b><br>• ⚠️ <b>ARN viral</b> : génome simple brin + (coronavirus, VHC, poliovirus), simple brin − (grippe, rage, Ebola), double brin (rotavirus), ou rétrovirus (+ avec transcriptase inverse : VIH, HTLV)<br><br><b>📋 LES ARN POLYMÉRASES (EUCARYOTES) ⚠️ :</b><br>• <b>ARN POLYMÉRASE I</b> : dans le <b>NUCLÉOLE</b> — transcrit le <b>pré-ARNr 45S/47S</b> (→ 18S, 5.8S, 28S) — ⚠️ <b>pas de coiffe ni de polyA</b> — inhibée par de faibles doses d'<b>α-amanitine</b>? NON (elle y est résistante)<br>• <b>ARN POLYMÉRASE II</b> : dans le <b>NUCLÉOPLASME</b> — transcrit les <b>ARNm, la plupart des snARN, des miARN, des lncARN</b> — ⚠️ <b>TRÈS SENSIBLE à l'α-AMANITINE</b> (toxine de l'<b>Amanita phalloides</b>, la « calice de la mort ») → blocage de la synthèse des ARNm → nécrose hépatique · possède un <b>domaine CTD</b> avec <b>52 répétitions heptapeptidiques YSPTSPS</b> (chez l'homme) dont la <b>phosphorylation</b> orchestre coiffe/épissage/polyadénylation<br>• <b>ARN POLYMÉRASE III</b> : transcrit les <b>ARNt, l'ARNr 5S, l'ARN U6, le 7SL, les Alu</b> — modérément sensible à l'α-amanitine<br>• <b>ARN POLYMÉRASE mitochondriale (POLRMT)</b> : transcrit les <b>13 ARNm, 2 ARNr, 22 ARNt</b> de l'ADNmt<br>• <b>ADN POLYMÉRASE ARN-DÉPENDANTE (transcriptase inverse)</b> : chez les <b>rétrovirus</b> (VIH) et la <b>TÉLOMÉRASE</b><br><br><b>📊 TABLEAU SYNTHÈSE RAPIDE :</b><br>• <b>Sucre</b> : ADN = <b>désoxyribose</b> · ARN = <b>ribose (OH 2')</b><br>• <b>Bases</b> : ADN = <b>A, G, C, T</b> · ARN = <b>A, G, C, U</b><br>• <b>Brins</b> : ADN = <b>double (bicaténaire)</b> · ARN = <b>simple (monocaténaire)</b> avec structures secondaires<br>• <b>Hélice</b> : ADN = <b>B droite, 10,5 pb/tour</b> · ARN db = <b>type A, 11 pb/tour</b><br>• <b>Longueur</b> : ADN = <b>très long (Gb)</b> · ARN = <b>court (20 nt à 100 kb)</b><br>• <b>Stabilité</b> : ADN = <b>stable</b> · ARN = <b>instable (min à h)</b><br>• <b>Localisation</b> : ADN = <b>noyau + mitochondrie</b> · ARN = <b>noyau → cytoplasme</b><br>• <b>Fonction</b> : ADN = <b>stockage</b> · ARN = <b>expression + catalyse + régulation</b><br>• <b>Hydrolyse alcaline</b> : ADN = <b>résistant</b> · ARN = <b>sensible</b><br>• <b>Réparation</b> : ADN = <b>OUI</b> · ARN = <b>NON</b><br>• <b>Activité catalytique</b> : ADN = <b>non</b> · ARN = <b>OUI (ribozymes)</b><br><br><b>💡 HYPOthèse DU « MONDE À ARN » ⭐</b> (Gilbert, 1986) : l'ARN, capable à la fois de <b>stocker l'information</b> ET de <b>catalyser des réactions</b>, aurait été la <b>première molécule de la vie</b> ; l'ADN (plus stable) et les protéines (plus catalytiques) seraient apparus ensuite. Preuves : <b>ribozymes</b> (ARNr 28S = peptidyl-transférase, RNase P, introns auto-épissables du groupe I et II), <b>ATP/GTP/NAD/FAD/CoA</b> = nucléotides, <b>télomérase</b> = transcriptase inverse à ARN, <b>ARNt</b> comme adaptateur.","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q46 — Les <b>ARNr (ARN ribosomiques)</b> : quelles sont leurs caractéristiques ?","a":"<b>📋 LES ARNr — CARACTÉRISTIQUES ESSENTIELLES :</b><br><br><b>1. ⭐ PROPORTION : LES PLUS ABONDANTS</b><br>• ⚠️ Les ARNr représentent <b>80 à 85 % de l'ARN TOTAL de la cellule</b> (le reste : ARNt 10–15 %, ARNm 1–5 %)<br>• Ils constituent <b>~60 % de la MASSE du ribosome</b> (les protéines ribosomiques font ~40 %)<br>• <b>C'est le constituant STRUCTURAL ET FONCTIONNEL MAJEUR du ribosome</b><br><br><b>2. ⭐ LES 4 ARNr EUCARYOTES (cytoplasmiques) :</b><br><br><b>SOUS-UNITÉ 60S (grande) :</b><br>• <b>28S</b> (~<b>5 070 nt</b> chez l'homme) ⚠️ — <b>le plus grand</b> — contient le <b>SITE CATALYTIQUE PEPTIDYL-TRANSFÉRASE (PTC)</b> ⭐<br>• <b>5.8S</b> (~<b>157 nt</b>) — lié au 28S par appariement de bases (équivalent au 5' du 23S bactérien)<br>• <b>5S</b> (~<b>121 nt</b>) ⚠️ — <b>le SEUL qui N'EST PAS transcrit dans le NUCLÉOLE</b><br><br><b>SOUS-UNITÉ 40S (petite) :</b><br>• <b>18S</b> (~<b>1 869 nt</b>) — contient le <b>site de décodage</b>, participe à la reconnaissance de la coiffe et au contrôle de fidélité<br><br><b>⚠️ COEFFICIENTS DE SÉDIMENTATION — À RETENIR :</b><br>• <b>RIBOSOME EUCARYOTE = 80S</b> = <b>60S (28S + 5.8S + 5S + ~49 protéines)</b> + <b>40S (18S + ~33 protéines)</b><br>• <b>RIBOSOME PROCARYOTE / MITOCHONDRIAL = 70S</b> = <b>50S (23S + 5S)</b> + <b>30S (16S)</b><br>• ⚠️ Le ribosome <b>mitochondrial humain = 55S</b> (<b>39S</b> grande + <b>28S</b> petite) avec des ARNr <b>16S (MT-RNR2)</b> et <b>12S (MT-RNR1)</b> — ⚠️ la mutation <b>m.1555A&gt;G dans le MT-RNR1</b> cause une <b>surdité induite par les AMINOSIDES</b> ⭐<br>• ⚠️ <b>S = Svedberg = coefficient de sédimentation</b> — <b>NON ADDITIF</b> (car il dépend de la forme, pas seulement de la masse) : 60S + 40S = 80S, pas 100S<br><br><b>3. ⭐ SYNTHÈSE — DEUX VOIES DIFFÉRENTES :</b><br><br><b>a) 28S, 18S et 5.8S — LE PRÉCURSEUR 45S (ou 47S)</b><br>• Transcrits <b>EN UN SEUL TRANSCRIT PRIMAIRE</b> : le <b>PRÉ-ARNr 45S/47S</b> (~<b>13 kb</b>)<br>• ⚠️ Par l'<b>ARN POLYMÉRASE I</b> ⭐ — <b>localisée dans le NUCLÉOLE</b><br>• Organisation du pré-ARNr : <b>5'ETS – 18S – ITS1 – 5.8S – ITS2 – 28S – 3'ETS</b><br>&nbsp;&nbsp;(<b>ETS</b> = External Transcribed Spacer · <b>ITS</b> = Internal Transcribed Spacer)<br>• ⚠️ <b>MATURATION = CLIVAGES SUCCESSIFS + MODIFICATIONS</b>, couplés à l'<b>assemblage des protéines ribosomiques</b> :<br>&nbsp;&nbsp;1. Le pré-45S est <b>clivé</b> par un <b>complexe de ~200 facteurs d'assemblage</b> (UTP, SSU processome) → <b>pré-ARNr 41S</b> puis <b>32S + 30S</b><br>&nbsp;&nbsp;2. → <b>21S (pré-18S) + 12S</b><br>&nbsp;&nbsp;3. → <b>18S</b> (sous-unité 40S) + <b>5.8S + 28S</b> (sous-unité 60S)<br>&nbsp;&nbsp;4. ⚠️ Le clivage final de la <b>21S en 18S</b> se fait dans le <b>CYTOPLASME</b> par <b>NOB1</b><br>• ⚠️ <b>MODIFICATIONS</b> (plus de <b>200</b> par ARNr, guidées par les <b>snoARN</b>) :<br>&nbsp;&nbsp;– <b>2'-O-MÉTHYLATION du ribose</b> (~<b>105 sites</b>) — guidée par les <b>snoARN à boîte C/D</b> (complexe : <b>fibrillarine</b> (méthyltransférase) + <b>NOP56, NOP58, 15.5K/SNU13</b>)<br>&nbsp;&nbsp;– <b>PSEUDO-URIDYLATION (Ψ)</b> (~<b>95 sites</b>) — guidée par les <b>snoARN à boîte H/ACA</b> (complexe : <b>dyskérine (DKC1)</b> + <b>NOP10, NHP2, GAR1</b>) ⚠️ Mutations de <b>DKC1 → DYSKÉRATOSE CONGÉNITALE liée à l'X</b> ⭐<br>• ⚠️ Ces modifications sont <b>ESSENTIELLES à la fonction</b> : elles stabilisent la structure, assurent la <b>fidélité du décodage</b> et l'<b>activité peptidyl-transférase</b><br><br><b>b) 5S — SÉPARÉ ⚠️</b><br>• Transcrit par l'<b>ARN POLYMÉRASE III</b> ⭐<br>• ⚠️ <b>HORS DU NUCLÉOLE</b> (dans le nucléoplasme) — c'est une <b>exception classique à connaître</b><br>• Gène : <b>cluster sur le chromosome 1q42</b> (~<b>200 à 300 copies</b> en tandem)<br>• Transporté ensuite <b>dans le nucléole</b> sous forme de complexe avec <b>TFIIIA (7S RNP)</b> pour être incorporé dans la sous-unité 60S<br><br><b>4. ⭐ ORGANISATION GÉNOMIQUE — LES GÈNES D'ARNr :</b><br>• ⚠️ <b>EN TANDEM RÉPÉTÉS</b>, regroupés en <b>CLUSTERS</b><br>• <b>Chez l'homme : ~300 à 400 COPIES</b> du gène 45S, réparties sur les <b>ORGANISATEURS NUCLÉOLAIRES (NOR)</b> situés sur les <b>BRAS COURTS des 5 CHROMOSOMES ACROCENTRIQUES : 13, 14, 15, 21, 22</b> ⭐ (région <b>12p12, 13p12, 14p12, 15p12, 21p12, 22p12</b>)<br>• ⚠️ C'est pour cela que la <b>constriction secondaire</b> des acrocentriques = le <b>NOR</b>, et qu'ils forment le <b>NUCLÉOLE</b> en interphase<br>• ⚠️ <b>Seules ~50 % des copies sont ACTIVES</b> à un moment donné — les autres sont <b>silencieuses/hétérochromatiques</b> → <b>réservoir de sécurité</b><br>• Structure d'une unité de transcription : <b>gène 45S (~13 kb) + espaceur intergénique (IGS, ~30 kb)</b> → répétition totale <b>~43 kb</b><br>• ⚠️ <b>Transcription MASSIVE</b> : chaque copie active peut produire <b>1 ARNr par seconde</b> → une cellule en croissance rapide peut en fabriquer <b>plusieurs milliers par minute</b>. En microscopie électronique, on voit les gènes d'ARNr en « <b>ARBRES DE NOËL</b> » (Christmas trees) avec des dizaines de polymérases en parallèle ⭐<br>• ⚠️ <b>Perte de copies d'ARNr</b> avec l'âge → <b>théorie du vieillissement nucléolaire</b><br>• <b>Gènes 5S</b> : cluster au <b>1q42</b>, ~<b>200-300 copies</b><br><br><b>5. ⭐ LE NUCLÉOLE — USINE À ARNr :</b><br>• <b>Pas de membrane</b> — c'est un <b>CONDENSAT BIOMOLÉCULAIRE / granule sans membrane</b>, formé par <b>SÉPARATION DE PHASE LIQUIDE-LIQUIDE (LLPS — Liquid-Liquid Phase Separation)</b> ⭐<br>• <b>Diamètre : 1 à 5 µm</b> — ⚠️ <b>LA STRUCTURE LA PLUS VISIBLE du noyau en microscopie optique</b> (après coloration argentique ou au bleu de crésyl)<br>• <b>Nombre : 1 à 5 par noyau</b> (souvent plusieurs NOR fusionnent)<br>• ⚠️ <b>TAILLE PROPORTIONNELLE à l'ACTIVITÉ DE SYNTHÈSE PROTÉIQUE</b> de la cellule → ⭐ <b>les cellules cancéreuses et les cellules très sécrétrices ont des NUCLÉOLES TRÈS GROS ET NOMBREUX</b> → critère diagnostique en anatomopathologie<br>• <b>3 ZONES (en MET) :</b><br>&nbsp;&nbsp;a) <b>CENTRE FIBRILLAIRE (FC — Fibrillar Center)</b> : <b>clair</b> — contient les <b>gènes d'ARNr actifs (ADN des NOR)</b> + l'<b>ARN pol I</b> + <b>UBF</b><br>&nbsp;&nbsp;b) <b>COMPOSANT FIBRILLAIRE DENSE (DFC — Dense Fibrillar Component)</b> : <b>sombre</b>, autour du FC — site du <b>traitement précoce</b> (clivages initiaux, 2'-O-méthylation) — contient la <b>FIBRILLINE</b>, <b>NOP56/58</b>, <b>snoRNP</b><br>&nbsp;&nbsp;c) <b>COMPOSANT GRANULAIRE (GC — Granular Component)</b> : <b>périphérique, granuleux</b> — site de l'<b>ASSEMBLAGE des sous-unités ribosomiques</b> avec les protéines — contient la <b>NUCLÉOPHOSMINE (B23/NPM1)</b> ⚠️ (translocation <b>NPM1</b> dans <b>~30 % des LAM</b>, marqueur pronostique favorable ; ⚠️ <b>mutée dans ~30 % des LAM (bon pronostic)</b>)<br>• <b>AUTRES FONCTIONS DU NUCLÉOLE (au-delà des ribosomes) ⚠️ :</b><br>&nbsp;&nbsp;– <b>ASSEMBLAGE de la SRP (Signal Recognition Particle)</b><br>&nbsp;&nbsp;– <b>Maturation des ARNt et des snARN</b><br>&nbsp;&nbsp;– <b>RÉGULATION DU CYCLE CELLULAIRE</b> : ⭐ séquestre des protéines comme <b>p53, MDM2, ARF, PTEN, Rb</b>. En cas de <b>« stress nucléolaire »</b> (inhibition de l'ARN pol I, dommages à l'ADN des NOR), les protéines ribosomiques <b>RPL5 et RPL11</b> sont libérées, se lient à <b>MDM2</b> et l'<b>inhibent</b> → <b>STABILISATION DE p53</b> → arrêt du cycle/apoptose<br>&nbsp;&nbsp;– <b>RÉPONSE AU STRESS</b>, <b>contrôle de la sénescence</b>, <b>vieillissement</b><br>&nbsp;&nbsp;– ⚠️ <b>Le nucléole DISPARAÎT en PROPHASE</b> (arrêt de la transcription par l'ARN pol I, phosphorylation des facteurs) et <b>SE REFORME en TELOPHASE</b> autour des NOR<br>• ⚠️ <b>PATHOLOGIES — « RIBOSOMOPATHIES » :</b><br>&nbsp;&nbsp;– <b>ANÉMIE DE BLACKFAN-DIAMOND</b> : mutations des <b>protéines ribosomiques RPS19 (la plus fréquente), RPL5, RPL11, RPS26</b> → érythroblastopénie congénitale, malformations<br>&nbsp;&nbsp;– <b>SYNDROME DE SHWACHMAN-DIAMOND</b> : <b>SBDS</b> (maturation du 60S) → neutropénie + insuffisance pancréatique + risque de LAM<br>&nbsp;&nbsp;– <b>DYSKÉRATOSE CONGÉNITALE</b> : <b>DKC1</b> (pseudouridine synthase, boîte H/ACA) → télomères courts + atteinte des ARNr<br>&nbsp;&nbsp;– <b>SYNDROME DE TREACHER COLLINS</b> : <b>TCOF1 (tréacle)</b>, <b>POLR1C, POLR1D</b> → hypoplasie cranio-faciale, déficit de transcription des ARNr dans les cellules de la crête neurale ⚠️ <b>PERTINENT EN DENTAIRE/MAXILLO-FACIAL</b><br>&nbsp;&nbsp;– <b>SYNDROME 5q− (SMD)</b> : haploinsuffisance de <b>RPS14</b><br>&nbsp;&nbsp;– <b>Syndromes de Diamond-Blackfan-like</b><br>• <b>Coloration argentique (Ag-NOR)</b> ⚠️ : met en évidence les <b>NOR actifs</b> → marqueur de prolifération tumorale<br><br><b>6. ⭐ FONCTION CATALYTIQUE — L'ARNr EST UN RIBOZYME :</b><br>• ⚠️ <b>LA RÉACTION PEPTIDYL-TRANSFÉRASE (formation de la liaison peptidique) EST CATALYSÉE PAR l'ARNr 28S, PAS par une protéine</b> ⭐⭐ — démontré par <b>Noller et al.</b> et confirmé par la <b>cristallographie du ribosome 50S (Steitz, Ramakrishnan, Yonath — PRIX NOBEL DE CHIMIE 2009)</b><br>• Les protéines ribosomiques sont <b>périphériques</b> — elles <b>stabilisent</b> la structure mais ne participent <b>PAS au site actif</b><br>• ⚠️ C'est une des <b>PREUVES LES PLUS FORTES du « MONDE À ARN »</b><br>• <b>RÔLES des ARNr :</b><br>&nbsp;&nbsp;– <b>18S</b> : décodage de l'ARNm, reconnaissance de la coiffe (via eIF3/eIF4E), contrôle de fidélité (interaction avec le codon-anticodon)<br>&nbsp;&nbsp;– <b>28S</b> : <b>centre peptidyl-transférase</b> + tunnel de sortie du polypeptide<br>&nbsp;&nbsp;– <b>5.8S et 5S</b> : architecture, interaction avec les facteurs d'élongation<br>&nbsp;&nbsp;– ⚠️ <b>Le TUNNEL de sortie du peptide</b> (long de <b>~10 nm</b>, diamètre <b>1–2 nm</b>) est formé par le <b>28S</b> et les protéines <b>uL4, uL22</b><br><br><b>7. ⚠️ CIBLES ANTIBIOTIQUES (différenciation 70S vs 80S) :</b><br>• <b>Sous-unité 30S (16S)</b> : <b>aminosides</b> (streptomycine, gentamicine, amikacine — erreurs de lecture), <b>tétracyclines</b> (blocage de l'ARNt), <b>spectinomycine</b><br>• <b>Sous-unité 50S (23S)</b> : <b>macrolides</b> (érythromycine, azithromycine, clarithromycine — blocage du tunnel), <b>chloramphénicol</b> (peptidyl-transférase), <b>clindamycine, linézolide</b>, <b>streptogramines</b>, <b>acide fusidique</b> (EF-G)<br>• ⚠️ <b>La toxicité mitochondriale</b> de ces antibiotiques vient de la ressemblance du ribosome mitochondrial (55S) avec le ribosome bactérien → effets secondaires (chloramphénicol → aplasie médullaire ; aminosides → ototoxicité/néphrotoxicité ; linézolide → neuropathie optique)<br>• ⚠️ <b>Cycloheximide</b> : inhibe le ribosome <b>80S eucaryote</b> (outil de laboratoire)<br>• <b>α-Amanitine</b> : inhibe l'<b>ARN pol II</b> (pas le ribosome)<br>• <b>Actinomycine D</b> : intercale dans l'ADN → inhibe la transcription (à faible dose : <b>ARN pol I</b>)<br><br><b>8. APPLICATIONS :</b><br>• ⭐ <b>ARNr 16S bactérien</b> : gène <b>horloge moléculaire</b> universel (régions conservées + variables) → <b>identification et phylogénie des bactéries</b>, <b>métagénomique</b>, définition des espèces (seuil <b>98,7 %</b> d'identité). Cible des <b>PCR universelles</b><br>• <b>ARNr 18S, ITS</b> : phylogénie des eucaryotes, des champignons (ITS = standard pour l'identification fongique)<br>• <b>ARNr 28S</b> : identification des insectes/vecteurs<br>• ⚠️ <b>Élimination des ARNr</b> dans le <b>RNA-seq</b> : les ARNr représentent 80-90 % de l'ARN total → il faut les <b>éliminer par déplétion (Ribo-Zero)</b> ou sélectionner les ARNm par <b>oligo-dT</b> avant le séquençage","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q47 — Le <b>NUCLÉOLE</b> : structure, composition et fonctions","a":"<b>📋 LE NUCLÉOLE — FICHE COMPLÈTE :</b><br><br><b>1. DÉFINITION :</b> le nucléole est la <b>plus grande structure du noyau interphasique</b>, un <b>« organite SANS MEMBRANE »</b> formé par <b>SÉPARATION DE PHASE LIQUIDE-LIQUIDE (LLPS)</b>. C'est l'<b>USINE DE PRODUCTION DES SOUS-UNITÉS RIBOSOMIQUES</b>.<br><br><b>2. CARACTÉRISTIQUES GÉNÉRALES :</b><br>• <b>Diamètre : 1 à 5 µm</b> ⚠️ — occupe jusqu'à <b>25 % du volume nucléaire</b><br>• ⚠️ <b>PAS DE MEMBRANE</b> — c'est un <b>condensat biomoléculaire</b>, délimité uniquement par des interactions faibles multivalentes (phénomène de LLPS, comme les granules de stress, les corps de Cajal, les corps P)<br>• <b>Nombre : 1 à 5 par noyau</b> (souvent plusieurs NOR fusionnent en un seul nucléole)<br>• ⚠️ <b>Visible en MICROSCOPIE OPTIQUE</b> après coloration (hématoxyline, bleu de crésyl, argentique) — c'est le point de repère le plus facile du noyau<br>• ⚠️ <b>DENSE AUX ÉLECTRONS en MET</b> — car riche en ARN<br>• ⚠️ <b>TAILLE ET NOMBRE PROPORTIONNELS À L'ACTIVITÉ DE SYNTHÈSE PROTÉIQUE</b> → les <b>cellules en croissance rapide, les cellules sécrétrices (plasmocytes, hépatocytes) et les CELLULES CANCÉREUSES</b> ont des <b>NUCLÉOLES HYPERTRÓPHIQUES</b> ⭐ → critère de malignité en anatomopathologie (« <b>nucléoles proéminents</b> » dans le score de Fuhrman/ISUP du cancer de la prostate, mélanome, carcinome rénal)<br>• <b>Le nucléole DISPARAÎT EN PROPHASE</b> et <b>SE REFORME EN TELOPHASE</b> ⚠️<br><br><b>3. ⭐ LOCALISATION — LES NOR (Nucleolar Organizer Regions) :</b><br>• Le nucléole se forme autour des <b>NOR</b> = régions chromosomiques portant les <b>gènes d'ARNr en tandem</b><br>• ⚠️ Chez l'<b>HOMME : sur les BRAS COURTS des 5 CHROMOSOMES ACROCENTRIQUES = 13, 14, 15, 21, 22</b> ⭐ (régions p12/p13)<br>• Soit <b>10 chromosomes</b> au total, mais seulement <b>~50 % des copies</b> de gènes sont actives simultanément<br>• ⚠️ Les NOR correspondent aux <b>CONSTRICTIONS SECONDAIRES</b> du caryotype, et leur activité est révélée par la <b>COLORATION ARGENTIQUE (Ag-NOR)</b> — qui ne colore que les NOR <b>TRANSCRIPTIONNELLEMENT ACTIFS</b> (l'argent se fixe sur les protéines acides non-histones : <b>nucléophosmine B23, UBF, NCL</b>)<br>• ⚠️ <b>APPLICATION :</b> les NOR sont le site des <b>TRANSLOCATIONS ROBERTSONIENNES</b> et des <b>associations satellites</b> (les acrocentriques s'agglutinent au nucléole en interphase)<br><br><b>4. ⭐ STRUCTURE — LES 3 ZONES (en MET) :</b><br><br><b>a) CENTRE FIBRILLAIRE (FC — Fibrillar Center)</b><br>• Apparence : <b>CLAIRE / peu dense</b><br>• Contenu : <b>ADN des NOR (gènes d'ARNr)</b> en cours de transcription + <b>ARN POLYMÉRASE I</b> + <b>UBF (Upstream Binding Factor)</b> + <b>SL1/TIF-IB</b> + <b>topoisomérase I</b><br>• ⚠️ Fonction : <b>TRANSCRIPTION du pré-ARNr 47S</b><br>• ⚠️ En microscopie optique à haute résolution, on voit les « <b>ARBRES DE NOËL</b> » (Christmas trees) — des gènes d'ARNr couverts de dizaines d'ARN pol I en parallèle avec leurs transcrits naissants en brosse<br><br><b>b) COMPOSANT FIBRILLAIRE DENSE (DFC — Dense Fibrillar Component)</b><br>• Apparence : <b>SOMBRE / très dense aux électrons</b>, forme un anneau autour du FC<br>• Contenu : <b>pré-ARNr 47S/45S naissant</b> + <b>FIBRILLINE (FBL)</b> ⭐ (marqueur spécifique du DFC) + <b>NOP56, NOP58, SNU13/15.5K</b> + <b>snoRNP à boîte C/D</b> + <b>NOP1</b><br>• ⚠️ Fonction : <b>TRAITEMENT PRÉCOCE du pré-ARNr</b> — clivages initiaux (dans l'ETS 5'), <b>2'-O-MÉTHYLATION</b> (par la fibrillarine), repliement précoce<br><br><b>c) COMPOSANT GRANULAIRE (GC — Granular Component)</b><br>• Apparence : <b>GRANULEUSE</b>, périphérique, la plus volumineuse<br>• Contenu : <b>pré-sous-unités ribosomiques 90S/60S/40S en cours d'assemblage</b> + <b>NUCLÉOPHOSMINE (NPM1/B23)</b> ⭐ + <b>NUCLÉOLINE (NCL/C23)</b> + <b>protéines ribosomiques importées du cytoplasme</b> + <b>facteurs d'assemblage</b> + <b>snoRNP à boîte H/ACA</b> + <b>dyskérine</b><br>• ⚠️ Fonction : <b>ASSEMBLAGE FINAL et MATURATION TARDIVE</b> des sous-unités 60S et 40S, <b>pseudouridylation</b>, <b>export</b> vers le cytoplasme<br><br>⚠️ <b>RÉSUMÉ DU FLUX :</b> FC (transcription) → DFC (traitement précoce) → GC (assemblage) → export cytoplasmique<br><br><b>⚠️ AUTRES SOUS-STRUCTURES NUCLÉOLAIRES :</b><br>• <b>CORPS DE CAJAL (Coiled bodies)</b> — contiennent la <b>COILINE</b>, maturation des <b>snRNP</b> et des <b>snoRNP</b>, télomérase — adjacents au nucléole, reliés par les <b>« GC bodies / histone locus bodies »</b><br>• <b>NUCLÉOLE DETACHED / NUCLEAR BODY</b><br>• <b>PARASPECKLES</b> — autour du lncARN <b>NEAT1</b>, séquestrent les ARNm avec des doubles brins A→I<br>• <b>CORPS PML</b> — domaines nucléaires, suppresseurs de tumeur<br>• <b>GRANULES PÉRI-NUCLÉOLAIRES (PNC)</b> — riches en <b>PTBP1</b>, surexprimés dans les cancers<br><br><b>5. ⭐ FONCTIONS DU NUCLÉOLE :</b><br><br><b>a) FONCTION PRINCIPALE — BIOGENÈSE DES RIBOSOMES</b> ⭐<br>• <b>TRANSCRIPTION</b> du pré-ARNr 47S/45S par l'<b>ARN POLYMÉRASE I</b> (contrôlée par <b>UBF, SL1, TIF-IA/RRN3</b>) — jusqu'à <b>60 % de la transcription totale</b> d'une cellule en croissance<br>• <b>TRAITEMENT/MATURATION</b> : ~<b>200 facteurs d'assemblage</b>, clivages multiples → <b>18S, 5.8S, 28S</b><br>• <b>MODIFICATIONS</b> : <b>~105 2'-O-méthylations</b> (snoARN C/D + fibrillarine) et <b>~95 pseudouridylations</b> (snoARN H/ACA + dyskérine)<br>• <b>ASSEMBLAGE</b> avec les <b>80 protéines ribosomiques</b> (synthétisées dans le <b>CYTOPLASME</b> puis <b>IMPORTÉES</b> dans le noyau via les pores) → <b>pré-sous-unités 90S (SSU processome)</b> → séparation en <b>pré-40S</b> et <b>pré-60S</b><br>• ⚠️ Le <b>5S</b> (transcrit par l'<b>ARN pol III</b> hors nucléole, au <b>1q42</b>) est <b>RECRUTÉ</b> dans le nucléole en complexe <b>5S RNP (5S + RPL5/uL18 + RPL11/uL5 + TFIIIA)</b> → incorporé dans la pré-60S<br>• <b>EXPORT</b> vers le cytoplasme par les pores (via <b>CRM1/XPO1</b> pour la 60S, <b>exportine-t/LOS1</b> et <b>CRM1</b> pour la 40S). ⚠️ La <b>maturation finale du 18S</b> se termine dans le <b>CYTOPLASME</b> (clivage de la 21S par <b>NOB1</b>)<br>• ⚠️ <b>Rendement :</b> une cellule de mammifère en croissance produit <b>~10 millions de ribosomes</b> par cycle cellulaire<br><br><b>b) ⭐ RÉGULATION DU CYCLE CELLULAIRE ET DU STRESS — « STRESS NUCLÉOLAIRE »</b><br>C'est la fonction la plus importante après la ribogenèse :<br>• ⚠️ Le nucléole est un <b>CAPTEUR de STRESS</b> : toute perturbation (inhibition de l'ARN pol I, carence nutritionnelle, dommages à l'ADN, stress oxydatif, chaleur, inhibiteurs de mTOR, hypoxie) bloque la ribogenèse<br>• <b>CONSÉQUENCE ⭐ :</b> les <b>PROTÉINES RIBOSOMIQUES LIBRES</b> — surtout <b>RPL5 (uL18) et RPL11 (uL5)</b>, avec le <b>5S ARNr</b> — quittent le nucléole, se lient à <b>MDM2</b> (l'ubiquitine ligase E3 qui dégrade p53) et <b>L'INHIBENT</b> → <b>STABILISATION et ACCUMULATION de p53</b> → <b>ARRÊT DU CYCLE (p21)</b> ou <b>APOPTOSE (PUMA, NOXA, BAX)</b><br>• ⚠️ C'est le mécanisme par lequel les <b>inhibiteurs de la ribogenèse</b> (actinomycine D à faible dose, <b>CX-5461</b> — inhibiteur de l'ARN pol I en essai clinique) <b>ACTIVENT p53</b> indépendamment des dommages à l'ADN → piste thérapeutique anticancéreuse ⭐<br>• Le nucléole séquestre aussi <b>PTEN, ARF, RB, MDM2, hTERT, VHL</b> → régulation de leur disponibilité<br><br><b>c) AUTRES FONCTIONS :</b><br>• <b>ASSEMBLAGE DE LA SRP</b> (Signal Recognition Particle) — le noyau 7SL ARN y est assemblé<br>• <b>MATURATION DES ARNt et des snARN</b><br>• <b>TRAITEMENT DES RNP de la TÉLOMÉRASE</b> (TERC y est assemblé)<br>• <b>FORMATION DES CORPS DE CAJAL</b> et régulation des snoRNP<br>• ⚠️ <b>RÉGULATION DU VIEILLISSEMENT</b> : le nucléole contrôle la longévité — chez <b>C. elegans</b>, la réduction de la taille du nucléole allonge la durée de vie ; la <b>voie mTOR/IGF-1</b> module la taille du nucléole ⭐. Hypothèse de la « <b>ribogenèse et vieillissement</b> » (Johnson, 2009)<br>• <b>SÉQUESTRATION de FACTEURS DE TRANSCRIPTION</b> et de protéines régulatrices<br>• <b>RÉPONSE IMMUNITAIRE INNÉE</b> (détection du stress, libération de DAMPs)<br>• <b>MAINTIEN DE L'INTÉGRITÉ DU GÉNOME</b> (les NOR sont des zones fragiles ; la topoisomérase I y est abondante)<br>• ⚠️ <b>SÉGRÉGATION CELLULAIRE ASYMÉTRIQUE</b> : dans les <b>cellules souches de Drosophile</b>, le nucléole (via la protéine <b>fibrillarine</b>) est ségrégé de façon asymétrique → détermine le destin cellulaire ⭐<br><br><b>6. ⚠️ PATHOLOGIES — LES « NUCLÉOLOPATHIES » / « RIBOSOMOPATHIES » :</b><br>• ⭐ <b>ANÉMIE DE BLACKFAN-DIAMOND</b> : mutations de <b>RPS19</b> (~25 %), <b>RPL5, RPL11, RPS26, RPL35A, RPS7, RPS24</b> → <b>érythroblastopénie congénitale</b> macrocytaire, malformations (pouces triphalangés, cardiopathie), prédisposition aux tumeurs (ostéosarcome, LAM). Traitement : corticoïdes, transfusions, greffe de moelle<br>• ⭐ <b>SYNDROME DE SHWACHMAN-DIAMOND</b> : <b>SBDS</b> (défaut de maturation du 60S, libération d'eIF6) → <b>insuffisance pancréatique exocrine</b> + <b>neutropénie</b> + anomalies squelettiques + risque élevé de <b>SMD/LAM</b><br>• ⭐ <b>DYSKÉRATOSE CONGÉNITALE</b> : <b>DKC1</b> (dyskérine, pseudouridine synthase de la boîte H/ACA) → triade <b>dysplasie unguéale + leucoplasie buccale + pigmentation réticulée</b> + insuffisance médullaire + télomères courts ⚠️ <b>PERTINENT EN DENTAIRE (leucoplasie)</b><br>• ⭐ <b>SYNDROME DE TREACHER COLLINS (dysostose mandibulofaciale)</b> : <b>TCOF1 (tréacle)</b> dans 80-90 %, <b>POLR1C, POLR1D, POLR1B</b> → déficit de transcription des ARNr dans les <b>cellules de la crête neurale</b> → apoptose → <b>hypoplasie des os zygomatiques et de la mandibule</b>, microtie, colobome, fentes, ⚠️ <b>détresse respiratoire néonatale</b>. <b>TRAITEMENT CHIRURGICAL MAXILLO-FACIAL — PERTINENT EN DENTAIRE</b> ⭐<br>• <b>SYNDROME 5q− (SMD)</b> : haploinsuffisance de <b>RPS14</b> → macrocytose, anomalies mégacaryocytaires<br>• <b>NEUROPATHIE HÉRÉDITAIRE SENSORIELLE ET AUTONOME (HSAN)</b> avec mutations de <b>WDR87</b><br>• ⚠️ <b>CANCER</b> : <b>hypertranscription nucléolaire</b> dans la plupart des cancers (activation de <b>MYC</b> qui stimule l'ARN pol I, perte de <b>p53/RB/PTEN</b>, activation de <b>mTOR</b>). <b>NPM1</b> muté dans <b>~30 % des LAM</b> (relocalisation cytoplasmique, bon pronostic). <b>Fibrillarine</b> surexprimée dans les cancers du sein et de la prostate. <b>Nucléoline</b> = cible des aptamères AS1411<br>• <b>MALADIES NEURODÉGÉNÉRATIVES</b> : fragmentation du nucléole dans la <b>maladie d'Alzheimer</b>, la <b>maladie de Parkinson</b>, la <b>SLA</b> (agrégats de <b>TDP-43, FUS</b> séquestrés), la <b>maladie de Huntington</b>. Dans la <b>maladie de Parkinson</b>, l'<b>α-synucléine</b> interagit avec <b>NPM1</b> et altère la ribogenèse<br>• ⚠️ <b>VIRUS</b> : beaucoup de virus <b>détournent le nucléole</b> pour se répliquer — <b>VIH (Rev, Tat, Gag se localisent au nucléole)</b>, <b>HPV, HSV, influenza (NP), coronavirus (protéine N)</b>, <b>HTLV-1</b>. Le nucléole sert à l'assemblage des particules virales et à l'évasion immunitaire<br>• ⚠️ <b>MALADIES AUTO-IMMUNES</b> : <b>anticorps ANTI-NUCLÉOLAIRES</b> dans la <b>SCLÉRODERMIE</b> — anti-<b>fibrillarine (U3-RNP)</b> = anti-PM-Scl, anti-<b>Th/To</b>, anti-<b>RNase MRP</b>, anti-<b>NOR-90/hUBF</b>. ⚠️ Les anti-fibrillarine (anti-U3 RNP) sont associés à la <b>sclérodermie diffuse des Afro-Américains</b> avec atteinte multi-viscérale<br>• <b>SYNDROME DE PRADER-WILLI / ANGELMAN</b>, <b>syndrome de Rothmund-Thomson</b><br><br><b>7. ⭐ POINTS CLÉS POUR L'EXAMEN :</b><br>1. ⚠️ Le nucléole <b>N'A PAS DE MEMBRANE</b><br>2. ⚠️ Il se forme sur les <b>NOR des ACROCENTRIQUES 13, 14, 15, 21, 22</b><br>3. ⚠️ Il transcrit les <b>ARNr 28S, 18S, 5.8S</b> avec l'<b>ARN POLYMÉRASE I</b> — mais <b>PAS le 5S</b> (ARN pol III, hors nucléole)<br>4. ⚠️ 3 zones : <b>FC (transcription) → DFC (traitement précoce, fibrillarine) → GC (assemblage, nucléophosmine)</b><br>5. ⚠️ Il <b>DISPARAÎT en prophase</b>, <b>se reforme en télophase</b><br>6. ⚠️ Sa <b>taille est proportionnelle à l'activité protéique</b> → marqueur de malignité<br>7. ⚠️ Il <b>RÉGULE p53</b> via <b>RPL5/RPL11-MDM2</b> (stress nucléolaire)<br>8. ⚠️ Il assemble aussi la <b>SRP</b>, mature les <b>ARNt/snARN</b>, héberge la <b>télomérase</b><br>9. ⚠️ C'est un <b>condensat LLPS</b> — pas un organite membranaire","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q48 — La <b>PROPHASE de la MITOSE</b> : quels événements s'y déroulent ?","a":"<b>📋 LA PROPHASE — PREMIÈRE ÉTAPE DE LA MITOSE :</b><br><br>⚠️ La mitose (phase M) dure <b>~1 h</b> et se divise en : <b>PROPHASE → PROMÉTAPHASE → MÉTAPHASE → ANAPHASE → TELOPHASE → CYTOCINÈSE</b>.<br>⚠️ Certains auteurs comptent <b>4 phases</b> (prophase, métaphase, anaphase, télophase) et rattachent la prométaphase à la prophase.<br><br><b>1. ⭐ CONDENSATION DE LA CHROMATINE EN CHROMOSOMES INDIVIDUALISÉS</b><br>• La chromatine passe de l'état <b>« collier de perles » (10 nm)</b> décondensé à des <b>CHROMOSOMES COMPACTS visibles</b> au microscope optique (compaction <b>×10 000</b>)<br>• ⚠️ Chaque chromosome est déjà <b>DUPLIQUÉ</b> (réplication en phase S) → il est formé de <b>DEUX CHROMATIDES SŒURS IDENTIQUES</b>, unies au <b>CENTROMÈRE</b> par la <b>COHÉSINE</b><br>• <b>Mécanisme de la condensation :</b><br>&nbsp;&nbsp;– ⭐ <b>CONDENSINE I et II</b> : complexes protéiques <b>SMC2-SMC4</b> + sous-unités accessoires (CAP-D2, CAP-G, CAP-H pour la condensine I ; CAP-D3, CAP-G2, CAP-H2 pour la condensine II) → <b>hydrolyse de l'ATP</b> → forment des <b>BOUCLES d'ADN</b> (loop extrusion) et les <b>compactent</b><br>&nbsp;&nbsp;– La <b>CONDENSINE II</b> agit <b>dans le NOYAU dès la prophase</b> ; la <b>CONDENSINE I</b> agit <b>après la désintégration de l'enveloppe</b> (prométaphase)<br>&nbsp;&nbsp;– ⚠️ La <b>TOPOISOMÉRASE IIα</b> résout les <b>enchevêtrements (caténanes)</b> entre chromatides sœurs — <b>INDISPENSABLE</b> à la séparation<br>&nbsp;&nbsp;– ⭐ <b>PHOSPHORYLATION de l'HISTONE H3 sur SER10 par AURORA B</b> → marqueur précoce de la condensation<br>&nbsp;&nbsp;– La <b>transcription s'ARRÊTE quasi complètement</b> (condensation = inaccessibilité) → ⚠️ <b>le nucléole DISPARAÎT</b><br><br><b>2. ⭐ ASSEMBLAGE DU FUSEAU MITOTIQUE (appareil fusorial)</b><br>• ⚠️ <b>Dès l'INTERPHASE (phase G2)</b>, les <b>DEUX CENTROSOMES</b> (dupliqués en phase S) commencent à se séparer<br>• En <b>PROPHASE</b> : les deux centrosomes migrent vers les <b>PÔLES OPPOSÉS</b> de la cellule<br>• Chaque centrosome contient <b>2 CENTRIOLES perpendiculaires</b> entourés de <b>MATÉRIEL PÉRICENTRIOLAIRE (PCM)</b> riche en <b>γ-TUBULINE</b><br>• ⚠️ Le PCM contient les <b>anneaux γ-TuRC (γ-tubulin Ring Complex)</b> = <b>SITE DE NUCLÉATION des MICROTUBULES</b> (l'extrémité <b>MOINS (−)</b> est ancrée au centrosome, l'extrémité <b>PLUS (+)</b> croît vers l'extérieur)<br>• <b>Mécanisme de la séparation des pôles :</b><br>&nbsp;&nbsp;– <b>Protéines moteurs KINÉSINES</b> : <b>Eg5/kinesin-5 (KIF11)</b> — <b>tétramérique</b>, marche vers le <b>(+)</b> des deux microtubules antiparallèles → <b>ÉCARTE les pôles</b> ⚠️ cible des inhibiteurs <b>monastrol, ispinesib</b><br>&nbsp;&nbsp;– <b>DYNÉINE corticale</b> : ancrée au cortex via <b>Numa-LGN-Gαi</b>, tire sur les <b>microtubules astraux</b> vers le <b>(−)</b> → <b>écarte aussi les pôles</b><br>&nbsp;&nbsp;– <b>Kinésine-14 (HSET/KIFC1)</b> : force opposée (vers le −) → équilibre des forces<br>&nbsp;&nbsp;– <b>NEK2A</b> kinase : dissout le lien <b>C-Nap1/rootletine</b> qui retient les centrosomes ensemble<br>• ⚠️ <b>3 TYPES DE MICROTUBULES DU FUSEAU :</b><br>&nbsp;&nbsp;a) <b>MICROTUBULES ASTRaux (asters)</b> : rayonnent depuis chaque centrosome vers le cortex cellulaire → <b>positionnent le fuseau</b><br>&nbsp;&nbsp;b) <b>MICROTUBULES POLAIRES (interpolar/chevauchants)</b> : partent de chaque pôle et <b>se chevauchent au centre</b> (zone d'interdigitation) → <b>structurent et allongent le fuseau</b><br>&nbsp;&nbsp;c) <b>MICROTUBULES KINÉTCHORIENS (K-fibers)</b> : s'attachent aux <b>KINÉTOCHORES</b> des chromosomes → <b>10 à 30 microtubules par kinétochore</b><br>• ⚠️ Les <b>cellules VÉGÉTALES n'ont PAS de centrosomes</b> : elles forment un <b>« phragmoplaste »</b> et des MTOC <b>acentriolaires</b><br><br><b>3. ⭐ PHOSPHORYLATION DE LA LAMINE → DÉBUT DE DÉSASSEMBLAGE DE L'ENVELOPPE NUCLÉAIRE</b><br>• ⚠️ <b>CDK1/CYCLINE B (= MPF, Maturation/Mitosis-Promoting Factor)</b> est <b>ACTIVÉ</b> au passage G2/M (par <b>CAK</b> qui phosphoryle Thr161, puis par <b>CDC25C</b> qui <b>déphosphoryle</b> les sites inhibiteurs <b>Thr14/Tyr15</b> posés par <b>WEE1/MYT1</b>)<br>• <b>CDK1 phosphoryle les LAMINES A, B, C</b> sur des résidus sérine spécifiques → <b>DÉPOLYMÉRISATION de la lamina</b> → fragilisation de l'enveloppe<br>• <b>CDK1 phosphoryle aussi les NUCLÉOPORINES</b> (Nup98, Nup53, Nup358, Nup153) → <b>désassemblage des pores</b><br>• ⚠️ Résultat : l'enveloppe se <b>FRAGMENTE en vésicules</b> qui <b>fusionnent avec le RE</b> → <b>DÉSINTÉGRATION COMPLÈTE À LA FIN DE LA PROPHASE / PROMÉTAPHASE</b><br>• ⚠️ <b>Le nucléole DISPARAÎT</b> (arrêt de la transcription par l'ARN pol I)<br><br><b>4. ⚠️ AUTRES ÉVÉNEMENTS DE LA PROPHASE :</b><br>• <b>ARRÊT TOTAL DE LA TRANSCRIPTION</b> (chromatine condensée) et <b>RÉDUCTION de la traduction</b><br>• <b>DÉPOLYMÉRISATION DE L'ACTINE corticale</b> → la cellule s'<b>ARRONDIT</b> (mitotic rounding) → pression intracellulaire augmentée, nécessaire à un fuseau correct. Contrôlée par <b>RhoA/ROCK</b><br>• ⭐ <b>DÉGRADATION DES ADHÉSIONS CELLULAIRES</b> : les <b>jonctions adhérentes</b> (E-cadhérine) et les <b>hémidesmosomes</b> sont internalisés → la cellule se détache du substrat (⚠️ c'est pourquoi les cellules en mitose sont arrondies et facilement détachables — utilisé pour synchroniser des cultures !)<br>• <b>RÉORGANISATION DU RÉTICULUM ENDOPLASMIQUE et de l'APPAREIL DE GOLGI</b> : le Golgi se <b>FRAGMENTE en vésicules</b> (contrôlé par <b>GRASP65, p115, MEK1</b>) pour assurer une <b>partition équitable</b> entre les cellules filles<br>• <b>ACTIVATION DU POINT DE CONTRÔLE G2/M (checkpoint ADN endommagé)</b> : si l'ADN est lésé, la voie <b>ATM/ATR → CHK1/CHK2 → inhibition de CDC25 → CDK1 reste phosphorylé (Thr14/Tyr15) → BLOCAGE en G2</b> ⚠️ empêche l'entrée en mitose<br>• ⭐ <b>FORMATION DU POINT DE CONTRÔLE DU FUSEAU (SAC — Spindle Assembly Checkpoint)</b> : les kinétochores non attachés recrutent <b>MAD1, MAD2, BUB1, BUBR1, BUB3, MPS1</b> → forment le <b>MCC (Mitotic Checkpoint Complex : MAD2-BUBR1-BUB3-CDC20)</b> qui <b>INHIBE l'APC/C</b><br><br><b>5. ⚠️ LE MOTEUR MOLÉCULAIRE : MPF (CDK1-CYCLINE B)</b><br>• <b>CDK1 (CDC2, p34)</b> + <b>CYCLINE B1/B2</b> = <b>MPF</b><br>• ⚠️ <b>MPF phosphoryle &gt; 100 substrats</b> → coordonne TOUS les événements de la prophase<br>• <b>Activation</b> : déphosphorylation de Thr14/Tyr15 par <b>CDC25C</b> + phosphorylation de Thr161 par <b>CAK (CDK7-cycline H)</b><br>• <b>Inactivation (à l'anaphase)</b> : ⭐ <b>APC/C<sup>CDC20</sup></b> ubiquitine la <b>CYCLINE B</b> → dégradation par le <b>PROTÉASOME 26S</b> → CDK1 inactivé → sortie de mitose. ⚠️ La <b>SÉCURINE</b> est aussi dégradée → libère la <b>SÉPARASE</b> → clive la <b>COHÉSINE</b><br>• ⚠️ <b>Boucle de rétroaction positive</b> : CDK1 actif active CDC25 et inhibe WEE1 → activation explosive et irréversible (« <b>interrupteur bistable</b> »)<br>• ⚠️ <b>Pharmacologie</b> : <b>RO-3306</b> (inhibiteur CDK1), <b>flavopiridol</b>, <b>dinaciclib</b><br><br><b>📋 RAPPEL — LES 5 PHASES DE LA MITOSE :</b><br><b>1. PROPHASE</b> : condensation des chromosomes (2 chromatides sœurs) · duplication/séparation des centrosomes · début d'assemblage du fuseau · phosphorylation des lamines · nucléole disparaît<br><b>2. PROMÉTAPHASE</b> : ⚠️ <b>DÉSINTÉGRATION COMPLÈTE de l'enveloppe nucléaire</b> · les chromosomes sont <b>LIBRES dans le cytoplasme</b> · <b>CAPTURE des kinétochores</b> par les microtubules (recherche-capture) · formation des <b>K-fibers</b> · achèvement de la condensation<br><b>3. MÉTAPHASE</b> : ⚠️ les chromosomes s'alignent sur la <b>PLAQUE ÉQUATORIALE (plaque métaphasique)</b> · tous les kinétochores sont <b>BI-ORIENTÉS (amphitéliques)</b> · tension maximale · <b>SAC ACTIF</b> qui bloque l'APC/C · ⭐ <b>C'EST LE STADE UTILISÉ POUR LE CARYOTYPE</b><br><b>4. ANAPHASE</b> : ⚠️ <b>APC/C<sup>CDC20</sup> ACTIVE</b> → dégradation de la <b>SÉCURINE</b> → libération de la <b>SÉPARASE</b> → clivage de la <b>COHÉSINE (SCC1/RAD21)</b> → les chromatides sœurs SE SÉPARENT<br>&nbsp;&nbsp;– <b>ANAPHASE A</b> : les chromatides <b>MIGRENT vers les pôles</b> (raccourcissement des K-fibers au kinétochore, moteurs <b>CENP-E, dynéine</b>)<br>&nbsp;&nbsp;– <b>ANAPHASE B</b> : les <b>PÔLES S'ÉCARTENT</b> (glissement des microtubules polaires par <b>Eg5/kinesin-5</b>, traction corticale par la <b>dynéine</b>)<br><b>5. TELOPHASE</b> : chromosomes <b>décondensés</b> aux pôles · ⚠️ <b>RÉASSEMBLAGE de l'ENVELOPPE NUCLÉAIRE</b> (déphosphorylation par PP1) · <b>RÉASSEMBLAGE de la LAMINA</b> · <b>RÉASSEMBLAGE des PORES</b> · ⚠️ <b>LE NUCLÉOLE SE REFORME autour des NOR</b> · reprise de la transcription · désassemblage du fuseau · <b>CYTOCINÈSE</b> (anneau contractile <b>actine-myosine II</b> au niveau du <b>corps central/centrale</b>, signalé par <b>RhoA, centralspindline (MKLP1-CYK4), PRC1</b>) → <b>sillon de division</b> → <b>2 CELLULES FILLES IDENTIQUES (2n, 46 chromosomes)</b><br><br><b>📋 DIFFÉRENCE PROPHASE MITOTIQUE vs PROPHASE I DE MÉIOSE ⚠️ :</b><br>• <b>Mitose (prophase)</b> : <b>PAS d'appariement des homologues</b>, <b>PAS de synapse</b>, <b>PAS de crossing-over</b>, dure <b>~30-60 min</b><br>• <b>Méiose I (prophase I)</b> : ⭐ <b>APPAIRIEMENT des HOMOLOGUES + SYNAPE (complexe synaptonémal) + CROSSING-OVER (recombinaison)</b> — dure <b>des jours à des semaines</b> (jusqu'à des décennies chez l'ovocyte humain bloqué en prophase I) · subdivisée en <b>LEPTOTÈNE, ZYGOTÈNE, PACHYTÈNE, DIPLOTÈNE, DIACINÈSE</b><br><br><b>⚠️ PIÈGE CLASSIQUE :</b> en prophase mitotique, il y a <b>46 CHROMOSOMES mais 92 CHROMATIDES</b> (car chaque chromosome est dupliqué). La <b>ploïdie reste 2n</b> mais le contenu en ADN est <b>4C</b>.","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q49 — Le <b>PACHYTÈNE</b> (prophase I de la méiose) : quels événements s'y déroulent ?","a":"<b>📋 LE PACHYTÈNE — LE STADE LE PLUS LONG ET LE PLUS IMPORTANT DE LA PROPHASE I :</b><br><br><b>DÉFINITION :</b> du grec <b>pachys</b> = « épais » → « <b>filaments épais</b> ». C'est le <b>3ᵉ stade de la PROPHASE I de la MÉIOSE</b>, caractérisé par l'<b>APPAIRIEMENT COMPLET des CHROMOSOMES HOMOLOGUES</b> (formation des <b>BIVALENTS / TÉTRADES</b>) et par le <b>CROSSING-OVER (recombinaison homologue)</b>.<br><br><b>1. ⭐ LES 5 STADES DE LA PROPHASE I (À CONNAÎTRE PAR CŒUR) :</b><br><br>• <b>LEPTOTÈNE</b> (« <b>filaments fins</b> », <i>leptos</i> = mince)<br>&nbsp;&nbsp;– Les chromosomes commencent à se <b>condenser</b> et apparaissent comme de <b>fins filaments</b><br>&nbsp;&nbsp;– ⚠️ <b>DOUBLE CASSURE de l'ADN (DSB)</b> programmée, catalysée par <b>SPO11</b> ⭐ (une topoisomérase-like) — <b>~200 à 300 DSB</b> par méiose humaine<br>&nbsp;&nbsp;– Les <b>télomères s'attachent à l'enveloppe nucléaire</b><br>&nbsp;&nbsp;– Chez la femme : ⚠️ c'est le stade où l'<b>OVOCYTE EST BLOQUÉ de la naissance jusqu'à l'ovulation</b> (arrêt en <b>PROPHASE I</b>, plus précisément au stade <b>dictyé</b> du diplonème chez l'adulte)<br><br>• <b>ZYGOTÈNE</b> (« <b>filaments appariés</b> », <i>zygon</i> = joug)<br>&nbsp;&nbsp;– ⚠️ <b>APPAIRIEMENT des CHROMOSOMES HOMOLOGUES (SYNAPSE)</b> — commence au niveau des <b>TÉLOMÈRES</b> puis s'étend en <b>« fermeture éclair (zipper) »</b><br>&nbsp;&nbsp;– ⭐ <b>ASSEMBLAGE du COMPLEXE SYNAPTONÉMAL (SC)</b> : structure protéique en échelle à 3 rails<br>&nbsp;&nbsp;&nbsp;&nbsp;• <b>2 ÉLÉMENTS LATÉRAUX (LE)</b> — les axes des chromosomes homologues, contenant les <b>cohésines méiotiques (REC8, SMC1β, STAG3)</b> et <b>SYCP2/SYCP3</b><br>&nbsp;&nbsp;&nbsp;&nbsp;• <b>1 ÉLÉMENT CENTRAL (CE)</b> — contient <b>SYCP1</b> (protéine majeure, forme les barreaux), <b>SYCE1/2/3, TEX12</b><br>&nbsp;&nbsp;&nbsp;&nbsp;• <b>Espace central</b> de <b>~100 nm</b> · largeur totale <b>~200 nm</b><br>&nbsp;&nbsp;– <b>Les télomères se regroupent d'un même côté du noyau</b> → ⭐ <b>STADE « BOUQUET »</b> — facilite l'appariement<br>&nbsp;&nbsp;– ⚠️ L'appariement se fait <b>PAR HOMOLOGIE DE SÉQUENCE</b> (et non au hasard)<br><br>• <b>⭐ PACHYTÈNE</b> (« <b>filaments épais</b> ») — <b>LE STADE CLÉ</b><br>&nbsp;&nbsp;Voir détails ci-dessous<br><br>• <b>DIPLOTÈNE</b> (« <b>filaments doubles</b> », <i>diploos</i> = double)<br>&nbsp;&nbsp;– ⚠️ <b>DÉSYNAPSE</b> : le <b>complexe synaptonémal SE DÉSASSEMBLE</b><br>&nbsp;&nbsp;– Les homologues commencent à se <b>séparer</b>, mais restent unis aux points de <b>CROSSING-OVER</b> → ces points deviennent <b>VISIBLES</b> : ce sont les ⭐ <b>CHIASMAS (singulier : chiasma)</b><br>&nbsp;&nbsp;– <b>Nombre de chiasmas : 1 à 3 par bivalent</b> (moyenne <b>~50 chiasmas par méiose humaine</b>)<br>&nbsp;&nbsp;– ⚠️ <b>Le chiasma EST LA PREUVE MORPHOLOGIQUE du crossing-over</b><br>&nbsp;&nbsp;– <b>Chez l'OVOCYTE</b> : ⭐ arrêt prolongé au stade <b>DICTYÉ (dictyotène)</b> = un diplonème très condensé, qui peut durer <b>de 12 à 50 ANS</b> ! La reprise se fait sous l'effet du <b>pic de LH</b>, juste avant l'ovulation<br>&nbsp;&nbsp;– Chez le <b>SPERMATOCYTE</b> : le diplonème est bref, sauf pour les spermatogonies qui restent en <b>état quiescent dictyé</b><br><br>• <b>DIACINÈSE</b> (« <b>à travers les cellules</b> », <i>dia</i> + <i>kinesis</i> = mouvement)<br>&nbsp;&nbsp;– <b>CONDENSATION MAXIMALE</b> des chromosomes<br>&nbsp;&nbsp;– ⚠️ <b>Les CHIASMAS TERMINALISENT</b> (migrent vers les extrémités des bras) — c'est eux qui maintiennent les bivalents ensemble jusqu'à l'anaphase I<br>&nbsp;&nbsp;– ⭐ <b>DÉSINTÉGRATION de l'ENVELOPPE NUCLÉAIRE</b> et du <b>NUCLÉOLE</b> (comme en prophase mitotique)<br>&nbsp;&nbsp;– <b>Formation du FUSEAU MÉIOTIQUE</b><br>&nbsp;&nbsp;– Transition vers la <b>MÉTAPHASE I</b><br><br><b>2. ⭐⭐ CE QUI SE PASSE AU PACHYTÈNE :</b><br><br><b>a) APPAIRIEMENT COMPLET DES HOMOLOGUES = BIVALENTS / TÉTRADES</b><br>• ⚠️ Les <b>23 paires de chromosomes homologues</b> sont <b>entièrement appariées</b> le long du <b>complexe synaptonémal</b> (qui est <b>complètement formé</b> à ce stade)<br>• Un <b>BIVALENT</b> = <b>2 chromosomes homologues appariés</b><br>• Une <b>TÉTRADE</b> = <b>4 CHROMATIDES</b> (2 chromatides sœurs × 2 homologues)<br>• ⚠️ On observe donc <b>23 bivalents</b> (ou <b>23 tétrades</b>) et <b>46 chromatides</b> au pachytène chez l'homme<br>• ⚠️ Chez l'homme : <b>22 AUTOSOMES (bivalents autosomiques) + 1 BIVALENT SEXUEL</b>. ⚠️ Le bivalent <b>X-Y</b> ne s'apparie que par leurs <b>régions PSEUDO-AUTOSOMIQUES (PAR1 en Xp/Yp, PAR2 en Xq/Yq)</b> → forme le <b>« CORPS XY » (corps sexuel)</b>, hétérochromatinisé et transcriptionnellement silencieux<br><br><b>b) ⭐⭐ CROSSING-OVER (RECOMBINAISON HOMOLOGUE) — L'ÉVÉNEMENT DÉFINISSANT</b><br>• Définition : <b>ÉCHANGE de segments d'ADN entre DEUX CHROMATIDES NON SŒURS de chromosomes homologues</b><br>• ⚠️ <b>CONSÉQUENCE MAJEURE : CRÉE UNE NOUVELLE COMBINAISON D'ALLÈLES → BRASSAGE GÉNÉTIQUE INTRACHROMOSOMIQUE → DIVERSITÉ de la descendance</b> ⭐<br>• ⚠️ <b>C'est le fondement physique de la LOI D'ASSORTIMENT INDÉPENDANT de MENDEL</b> et de la <b>CARTE GÉNÉTIQUE</b> (1 % de recombinaison = <b>1 centiMorgan (cM)</b>)<br>• ⭐ <b>MÉCANISME MOLÉCULAIRE (modèle de Szostak / DSB repair) :</b><br>&nbsp;&nbsp;1. ⚠️ <b>DOUBLE CASSURE (DSB)</b> créée par <b>SPO11</b> (dès le leptotène) — SPO11 reste <b>covalent lié à l'extrémité 5'</b><br>&nbsp;&nbsp;2. <b>MRN (MRE11-RAD50-NBS1) + COM1/SAE2/CtIP + EXO1</b> font une <b>RÉSECTION 5'→3'</b> → génèrent des <b>EXTRÉMITÉS SIMPLE BRIN 3' (overhangs)</b><br>&nbsp;&nbsp;3. ⚠️ <b>RPA</b> recouvre les extrémités ss, puis est remplacé par les <b>RECOMBINASES DMC1 (spécifique de la méiose ⭐) et RAD51</b> → forment un <b>FILAMENT NUCLÉOPROTÉIQUE</b><br>&nbsp;&nbsp;4. ⭐ <b>INVASION DU BRIN (strand invasion)</b> : le filament 3' envahit la <b>chromatide homologue non sœur</b> et s'apparie → forme une <b>BOUCLE D (D-loop)</b><br>&nbsp;&nbsp;5. <b>ÉLONGATION</b> par l'ADN polymérase δ → extension du 3'<br>&nbsp;&nbsp;6. Deux voies possibles :<br>&nbsp;&nbsp;&nbsp;&nbsp;– ⚠️ <b>VOIE SDSA (Synthesis-Dependent Strand Annealing)</b> → produit des <b>NON-CROSSOVERS (NCO) = CONVERSION GÉNIQUE</b> sans échange de bras (~<b>90 %</b> des événements)<br>&nbsp;&nbsp;&nbsp;&nbsp;– ⚠️ <b>VOIE DOUBLE HOLLIDAY JUNCTION (dHJ)</b> → stabilisée par <b>MSH4-MSH5 (MutSβ)</b>, <b>TEX11, ZIP3</b> → produit des <b>CROSSOVERS (CO)</b> (~<b>10 %</b> des événements) → résolution par <b>MUS81-EME1, GEN1, SLX1-SLX4</b>, ou dissolution par <b>BLM-TOPOIIIα-RMI1/2</b><br>&nbsp;&nbsp;7. <b>LIGATION</b> → le crossing-over est terminé<br>• ⚠️ <b>INTERFÉRENCE DES CROSSING-OVERS</b> : un CO réduit la probabilité d'un second CO à proximité (distance minimale ~<b>10 Mb</b>)<br>• ⚠️ <b>OBLIGATION D'AU MOINS 1 CO PAR BIVALENT</b> (« <b>crossover assurance</b> ») → <b>SANS CO, les homologues ne peuvent pas s'orienter correctement → NON-DISJONCTION → ANEUPLOÏDIE</b> ⭐<br>• ⭐ <b>HOTSPOTS DE RECOMBINAISON</b> : contrôlés par <b>PRDM9</b> (une méthyltransférase H3K4/H3K36 avec des doigts de zinc) qui marque les sites de DSB. ⚠️ <b>Les variations alléliques de PRDM9 expliquent les différences de carte de recombinaison entre individus et espèces</b>. ⚠️ <b>PRDM9 est le seul gène connu dont la variation affecte directement la fertilité humaine</b> (azoospermie chez certains variants)<br>• ⚠️ <b>Différences homme/femme</b> : les femmes ont un <b>taux de recombinaison ~1,6 fois plus élevé</b> que les hommes (<b>~4 200 cM chez la femme vs ~2 600 cM chez l'homme</b>) ; chez l'homme les CO sont concentrés près des <b>télomères</b>, chez la femme près des <b>centromères</b><br><br><b>c) CONTRÔLE QUALITÉ DE LA SYNAPE ⭐</b><br>• Au pachytène, un ⚠️ <b>POINT DE CONTRÔLE (PACHYTENE CHECKPOINT)</b> vérifie :<br>&nbsp;&nbsp;– Que <b>tous les homologues sont correctement appariés</b> (synapse complète)<br>&nbsp;&nbsp;– Que les <b>DSB sont toutes réparées</b><br>&nbsp;&nbsp;– Que le <b>corps XY est correctement formé</b><br>• ⚠️ Si le contrôle échoue → <b>APOPTOSE du gamète</b> (via <b>p53, p63 — surtout TAp63α dans les ovocytes</b>) → <b>INFERTILITÉ / azoospermie</b><br>• ⭐ C'est le mécanisme de l'<b>infertilité masculine par ARRÊT MATURATIF au stade pachytène</b> (maturation arrest) — cause fréquente d'<b>azoospermie non obstructive</b><br>• ⚠️ <b>MSH4/MSH5, TEX11, MEIOB, STAG3, SYCP3</b> mutés → azoospermie/infertilité chez l'homme, insuffisance ovarienne prématurée chez la femme<br><br><b>d) TRANSCRIPTION ET ARN</b><br>• La <b>transcription continue</b> au pachytène (contrairement à la mitose !)<br>• ⚠️ Chez l'<b>ovocyte</b>, c'est la phase de <b>STOCKAGE des ARNm maternels</b> qui seront traduits après la fécondation — les ARNm sont <b>polyadénylés de façon cytoplasmique</b> et stockés sous forme de <b>RNP (granules corticaux, corps de Balbiani)</b><br>• ⚠️ Chez le <b>spermatocyte</b>, transcription massive de gènes méiotiques (ex. <b>SPATA</b>, <b>DAZ</b>, <b>SYCP</b>)<br>• <b>Silencement méiotique des chromosomes non appariés (MSUC / MSCI)</b> : tout chromosome non apparié est <b>silencié</b> (via <b>ATR, BRCA1, γ-H2AX, H3K9me3</b>). ⚠️ C'est le mécanisme du <b>MSCI (Meiotic Sex Chromosome Inactivation)</b> sur le corps XY. ⚠️ <b>Une autosomie non appariée (ex. trisomie) peut déclencher un MSUC global → arrêter la méiose → infertilité</b> → c'est pourquoi les hommes avec une <b>translocation robertsonienne</b> ou un <b>syndrome de Klinefelter (47,XXY)</b> sont souvent <b>azoospermiques</b> ⭐<br><br><b>e) FORMATION DES PROTUBÉRANCES / ÉLÉMENTS DE SURFACE</b><br>• <b>NODULES DE RECOMBINAISON</b> visibles en MET sur le complexe synaptonémal : contiennent <b>RAD51, DMC1, MSH4, MLH1, MLH3</b>. ⚠️ Les <b>nODULES TARDIFS (MLH1-MLH3)</b> marquent les <b>futurs CROSSOVERS</b> → leur nombre prédit le nombre de chiasmas au diplonème<br><br><b>3. ⚠️ PIÈGES ET POINTS CLÉS POUR L'EXAMEN :</b><br>• ⭐ <b>PACHYTÈNE = SYNAPSE COMPLÈTE + CROSSING-OVER</b> — c'est LA réponse<br>• ⚠️ <b>Le CROSSING-OVER commence en fait au ZYGOTÈNE/LEPTOTÈNE (DSB) mais SE COMPLÈTE au PACHYTÈNE</b> — les <b>chiasmas ne deviennent VISIBLES qu'au DIPLOTÈNE</b> (après la désynapse) ⚠️ <b>NE PAS CONFONDRE</b><br>• ⚠️ <b>Le COMPLEXE SYNAPTONÉMAL est COMPLÈTEMENT FORMÉ au PACHYTÈNE</b> et se <b>DÉSASSEMBLE au DIPLOTÈNE</b><br>• ⚠️ <b>L'ENVELOPPE NUCLÉAIRE est ENCORE INTACTE au pachytène</b> — elle ne se désintègre qu'à la <b>DIACINÈSE</b><br>• ⚠️ <b>Le nucléole est encore présent</b> au pachytène<br>• ⚠️ <b>La condensation est MODÉRÉE</b> — les chromosomes sont épais mais pas encore maximaux (max à la diacinèse)<br>• ⚠️ <b>PACHYTÈNE est le STADE LE PLUS LONG</b> de la prophase I (jusqu'à <b>plusieurs jours/semaines</b>)<br>• ⚠️ <b>Contenu en ADN</b> au pachytène : <b>4C</b> (comme après la phase S) · <b>Nombre de chromosomes : 46 (23 bivalents)</b> · <b>Nombre de chromatides : 92</b><br>• ⚠️ <b>MÉIOSE ≠ MITOSE</b> : le crossing-over n'existe <b>PAS</b> en mitose (sauf cas rares de <b>recombinaison mitotique</b> en cellules somatiques, impliquée dans la perte d'hétérozygotie en cancérologie et dans les taches chez les porteurs de NF1)<br><br><b>4. ⭐ CONSÉQUENCES CLINIQUES DU CROSSING-OVER :</b><br>• <b>DIVERSITÉ GÉNÉTIQUE</b> : chaque gamète est unique (2²³ combinaisons par assortiment indépendant × crossing-over → ~<b>8,4 millions</b> de combinaisons rien que par l'assortiment, et <b>des milliards</b> avec la recombinaison)<br>• <b>CARTOGRAPHIE GÉNÉTIQUE</b> : 1 % de recombinaison = <b>1 cM</b> ≈ <b>1 Mb</b> en moyenne<br>• ⚠️ <b>PATHOLOGIES PAR RECOMBINAISON NON ALLÉLIQUE (NAHR)</b> : quand le crossing-over se produit entre des <b>RÉPÉTITIONS SEGMENTAIRES (LCR)</b> au lieu des homologues → <b>syndromes de microdélétion/microduplication récurrents</b> : <b>DiGeorge 22q11.2, Williams 7q11.23, Smith-Magenis/ Potocki-Lupski 17p11.2, Charcot-Marie-Tooth 1A (dup PMP22)/HNPP (del PMP22), Prader-Willi/Angelman 15q11-q13, NF1, α-thalassémie (−−3.7)</b> ⭐<br>• ⚠️ <b>ANEUPLOÏDIES</b> : un crossing-over <b>déficient, mal positionné (trop proche du centromère ou du télomère) ou absent</b> → <b>NON-DISJONCTION</b> → <b>TRISOMIE 21</b> (la plus fréquente, ~<b>1/700 naissances</b>, <b>90 % d'origine MATERNELLE</b>, risque augmenté avec l'<b>âge maternel</b> : 1/1 500 à 25 ans → 1/30 à 45 ans), <b>TRISOMIE 18, 13</b>, <b>45,X (Turner — 75 % d'origine paternelle)</b>, <b>47,XXY (Klinefelter)</b> ⭐<br>• ⚠️ <b>L'ÂGE MATERNEL</b> : les ovocytes restent bloqués en <b>dictyé</b> pendant des décennies → les <b>cohésines (REC8) se dégradent avec le temps</b> → perte de la cohésion des chromatides → non-disjonction. C'est le mécanisme principal du risque accru de trisomie après 35 ans ⭐","t":"biocell-2026 EXAM-2026 M111"},{"q":"Q50 — La <b>MÉIOSE</b> en général : à quoi sert-elle, quelles sont ses caractéristiques ?","a":"<b>📋 LA MÉIOSE — FICHE COMPLÈTE :</b><br><br><b>1. ⭐ BUT ET RÔLE :</b><br>• <b>DIVISION DE RÉDUCTION</b> : transforme une cellule <b>DIPLOÏDE (2n = 46 chromosomes)</b> en <b>QUATRE cellules HAPLOÏDES (n = 23 chromosomes)</b> = les <b>GAMÈTES</b> (spermatozoïdes chez l'homme, ovules chez la femme)<br>• ⚠️ <b>MAINTIENT LE NOMBRE DE CHROMOSOMES CONSTANT D'UNE GÉNÉRATION À L'AUTRE</b> : sans la méiose, la fécondation doublerait le nombre de chromosomes à chaque génération (2n → 4n → 8n...) ⭐<br>• ⭐ <b>CRÉE LA DIVERSITÉ GÉNÉTIQUE</b> par <b>DEUX mécanismes indépendants</b> :<br>&nbsp;&nbsp;a) <b>LE CROSSING-OVER</b> (brassage <b>INTRACHROMOSOMIQUE</b>) — recombinaison entre chromatides non sœurs au pachytène<br>&nbsp;&nbsp;b) <b>L'ASSORTIMENT INDÉPENDANT</b> (brassage <b>INTERCHROMOSOMIQUE</b>) — distribution aléatoire des homologues paternels et maternels en anaphase I → <b>2ⁿ = 2²³ = ~8,4 MILLIONS</b> de combinaisons possibles de gamètes chez l'homme ⭐<br>• ⚠️ <b>LA MÉIOSE N'EXISTE QUE DANS LES CELLULES DE LA LIGNÉE GERMINALE</b> — jamais dans les cellules somatiques<br>• ⚠️ <b>BASE DE L'HÉRÉDITÉ MENDELIENNE</b> : la ségrégation des allèles en anaphase I est le <b>support physique de la 1ʳᵉ loi de Mendel</b> (ségrégation), et l'assortiment indépendant celui de la <b>2ᵉ loi</b> (indépendance)<br><br><b>2. ⭐ LES DEUX DIVISIONS SUCCESSIVES :</b><br><br><b>🔵 MÉIOSE I — « DIVISION RÉDUCTIONNELLE » ⚠️ (hétérotypique)</b><br>• <b>SÉPARE LES CHROMOSOMES HOMOLOGUES</b> (les paires)<br>• ⚠️ <b>Le nombre de chromosomes est DIVISÉ PAR 2</b> : 2n → n<br>• ⚠️ <b>Chaque chromosome reste formé de DEUX CHROMATIDES</b> (les chromatides sœurs ne se séparent PAS) → <b>le contenu en ADN passe de 4C à 2C</b><br>• Phases : <b>PROPHASE I</b> (longue, 5 stades : leptotène, zygotène, pachytène, diplonème, diacinèse — avec <b>synapse + crossing-over</b>) · <b>MÉTAPHASE I</b> (les <b>BIVALENTS</b> s'alignent sur la plaque équatoriale, par paires, orientation aléatoire) · <b>ANAPHASE I</b> (⚠️ les <b>HOMOLOGUES</b> se séparent et migrent chacun vers un pôle — <b>les chromatides sœurs restent unies</b> grâce à la <b>cohésine protégée par la SHUGOSHINE (Sgo1)</b> au centromère) · <b>TELOPHASE I</b> + cytocinèse → <b>2 CELLULES HAPLOÏDES (n) à 2 CHROMATIDES</b><br>• ⚠️ Il peut y avoir ou non une <b>intercinèse</b> (courte, <b>SANS RÉPLICATION DE L'ADN</b> — c'est un point capital !)<br>• ⭐ <b>Différence clé avec la mitose en anaphase I</b> : les kinétochores des <b>2 chromatides sœurs</b> d'un même chromosome fonctionnent <b>COMME UNE SEULE UNITÉ (mono-orientation)</b>, tandis que les homologues sont <b>bi-orientés</b>. Ceci est assuré par la <b>protéine MONOPOLINE</b> et la <b>cohésine méiotique REC8</b><br><br><b>🟢 MÉIOSE II — « DIVISION ÉQUATIONNELLE » ⚠️ (homéotypique)</b><br>• <b>SÉPARE LES CHROMATIDES SŒURS</b> — mécaniquement <b>IDENTIQUE À UNE MITOSE</b>, mais sur des cellules <b>haploïdes</b><br>• ⚠️ <b>Le nombre de chromosomes NE CHANGE PAS</b> : n → n<br>• ⚠️ <b>Le contenu en ADN passe de 2C à 1C</b><br>• Phases : <b>PROPHASE II</b> (brève, pas de synapse, pas de crossing-over) · <b>MÉTAPHASE II</b> (chromosomes à 2 chromatides alignés individuellement sur la plaque) · <b>ANAPHASE II</b> (⚠️ la <b>SHUGOSHINE est dégradée</b> → la <b>cohésine centromérique est clivée par la SÉPARASE</b> → les <b>CHROMATIDES SŒURS SE SÉPARENT</b>) · <b>TELOPHASE II</b> + cytocinèse → <b>4 CELLULES HAPLOÏDES à 1 CHROMATIDE</b><br>• ⚠️ <b>PAS DE RÉPLICATION D'ADN entre la méiose I et la méiose II</b> ⭐<br><br><b>3. ⭐⭐ BILAN FINAL :</b><br>• <b>1 CELLULE DIPLOÏDE (2n, 4C) → 4 CELLULES HAPLOÏDES (n, 1C) GÉNÉTIQUEMENT DIFFÉRENTES</b><br>• Chez l'<b>HOMME (SPERMATOGENÈSE)</b> : <b>4 SPERMATOZOÏDES FONCTIONNELS</b> — cytocinèse <b>SYMÉTRIQUE</b>, tous fonctionnels. Durée totale : <b>~64 à 74 jours</b> (spermatogenèse) + <b>~12 jours</b> dans l'épididyme (maturation)<br>• Chez la <b>FEMME (OVOGENÈSE)</b> : ⚠️ <b>UN SEUL OVULE + 3 GLOBULES POLAIRES (corpuscules polaires) qui DÉGÉNÈRENT</b> — cytocinèse <b>ASYMÉTRIQUE</b> (le cytoplasme et les organites sont conservés pour l'ovule). ⭐ C'est une <b>différence majeure à connaître</b><br>&nbsp;&nbsp;– 1ʳᵉ division : <b>1 ovocyte II + 1 globule polaire I</b><br>&nbsp;&nbsp;– 2ᵉ division : <b>1 ovule + 1 globule polaire II</b> (et le globule polaire I peut se diviser aussi → 3 au total)<br>&nbsp;&nbsp;– ⚠️ Les globules polaires peuvent être utilisés en <b>DPG (diagnostic préimplantatoire) — « polar body biopsy »</b> pour détecter les anomalies maternelles<br><br><b>4. ⭐ LES BLOCS DE LA MÉIOSE CHEZ L'HOMME :</b><br>• <b>FEMME</b> : ⚠️ les <b>OVOCYTES sont BLOQUÉS EN PROPHASE I (stade DICTYÉ du diplonème) DEPUIS LA VIE FŒTALE jusqu'à l'OVULATION</b> — soit <b>12 à 50 ANS d'arrêt</b> ⭐. La reprise est déclenchée par le <b>PIC DE LH pré-ovulatoire</b> (via la reprise de l'activité MPF, dégradation de la protéine <b>Emi2/CSF</b>, activation du <b>complexe APC/C</b>). Le <b>2ᵉ bloc est en MÉTAPHASE II</b> — l'ovocyte II est ovulé en <b>métaphase II</b> et n'achève la méiose II <b>QUE SI IL EST FÉCONDÉ</b> ⚠️ (déclenché par l'<b>oscillation calcique</b> induite par <b>PLCζ</b> du spermatozoïde)<br>• <b>HOMME</b> : la spermatogenèse est <b>CONTINUE et SYNCHRONE</b> à partir de la puberté, sans bloc<br><br><b>5. ⭐ COMPARAISON MITOSE vs MÉIOSE — TABLEAU À APPRENDRE :</b><br>• <b>Nombre de divisions</b> : Mitose = <b>1</b> · Méiose = <b>2</b><br>• <b>Nombre de cellules filles</b> : Mitose = <b>2</b> · Méiose = <b>4</b><br>• <b>Ploïdie</b> : Mitose = <b>2n → 2n (identique)</b> · Méiose = <b>2n → n (réduite)</b><br>• <b>Contenu en ADN</b> : Mitose = <b>4C → 2C</b> · Méiose = <b>4C → 2C → 1C</b><br>• <b>Chromatides par cellule fille</b> : Mitose = <b>1</b> · Méiose I = <b>2</b> · Méiose II = <b>1</b><br>• <b>Appariement des homologues</b> : Mitose = <b>NON</b> · Méiose = <b>OUI (synapse)</b><br>• <b>Complexe synaptonémal</b> : Mitose = <b>absent</b> · Méiose = <b>présent (zygotène-pachytène)</b><br>• <b>CROSSING-OVER</b> : Mitose = <b>NON</b> ⚠️ · Méiose = <b>OUI</b> ⭐<br>• <b>Chiasmas</b> : Mitose = <b>aucun</b> · Méiose = <b>présents (diplonème-diacinèse)</b><br>• <b>Alignement en métaphase</b> : Mitose = <b>chromosomes INDIVIDUELS (à 2 chromatides) en file</b> · Méiose I = <b>BIVALENTS (paires) sur 2 rangées</b> · Méiose II = chromosomes individuels<br>• <b>Séparation en anaphase</b> : Mitose = <b>CHROMATIDES SŒURS</b> · Méiose I = <b>HOMOLOGUES</b> · Méiose II = <b>CHROMATIDES SŒURS</b><br>• <b>Identité génétique</b> : Mitose = <b>CELLULES FILLES IDENTIQUES entre elles et à la mère (clones)</b> · Méiose = <b>CELLULES FILLES TOUTES DIFFÉRENTES</b><br>• <b>Durée</b> : Mitose = <b>~1 heure</b> · Méiose = <b>jours à décennies</b> (prophase I très longue)<br>• <b>Localisation</b> : Mitose = <b>toutes les cellules SOMATIQUES</b> (croissance, réparation, renouvellement) · Méiose = <b>uniquement les CELLULES GERMINALES</b> (gonades : testicule, ovaire)<br>• <b>Rôle</b> : Mitose = <b>CROISSANCE, RÉGÉNÉRATION, REPRODUCTION ASEXUÉE</b> · Méiose = <b>REPRODUCTION SEXUÉE, DIVERSITÉ GÉNÉTIQUE</b><br>• <b>Cohésine</b> : Mitose = <b>SCC1/RAD21</b> · Méiose = ⚠️ <b>REC8</b> (variante méiotique)<br>• <b>Centromère/kinétochore</b> : Mitose = <b>bi-orientation</b> · Méiose I = ⚠️ <b>mono-orientation des chromatides sœurs</b> (protéine monopoline)<br>• <b>Protection de la cohésine centromérique</b> : Méiose I = ⚠️ <b>SHUGOSHINE (Sgo1/2) + PP2A</b> protègent REC8 au centromère<br><br><b>6. ⚠️ ANOMALIES DE LA MÉIOSE → ANEUPLOÏDIES :</b><br>• <b>NON-DISJONCTION</b> en méiose I ou II → gamètes <b>n+1</b> ou <b>n−1</b><br>• Causes : <b>âge maternel avancé</b> (dégradation des cohésines pendant l'arrêt dictyé) · <b>crossing-over absent ou mal positionné</b> · anomalies du fuseau · <b>translocations robertsoniennes</b> · mosaïcisme germinale<br>• <b>Résultats</b> : <b>TRISOMIE 21 (Down, 1/700, 90 % maternelle)</b> · <b>TRISOMIE 18 (Edwards, 1/5 000, létale à 90 % avant 1 an)</b> · <b>TRISOMIE 13 (Patau, 1/15 000)</b> · <b>45,X (Turner, 1/2 500 naissances, ~99 % des conceptions 45,X avortent spontanément)</b> · <b>47,XXY (Klinefelter, 1/600 garçons)</b> · <b>47,XYY (1/1 000 garçons)</b> · <b>47,XXX (1/1 000 filles)</b><br>• ⚠️ <b>Dépistage</b> : <b>marqueurs sériques (PAPP-A, β-hCG libre, AFP, uE3, inhibine A)</b> + <b>échographie (clarté nucale)</b> au 1ᵉʳ trimestre → test combiné · ⭐ <b>DPNI/NIPT (ADN libre fœtal dans le sang maternel, dès 10 SA)</b> — sensibilité &gt; 99 % pour la T21 · ⚠️ <b>Confirmation par CARYOTYPE ou ACPA sur amniocentèse/choriocentèse</b><br><br><b>7. ⭐ MÉIOSE ET CANCER :</b><br>• ⚠️ Les <b>gènes de la méiose sont normalement SILENCIEUX dans les cellules somatiques</b> (car ils sont dans l'hétérochromatine et méthylés)<br>• Dans les cancers, beaucoup sont <b>RÉACTIVÉS</b> → on parle de <b>« CANCER/TESTIS ANTIGENS (CTA) »</b> : <b>MAGE-A, GAGE, XAGE, PRAME, SSX, NY-ESO-1</b>, et aussi <b>SPO11, DMC1, SYCP3, HORMAD1</b><br>• ⚠️ Cela provoque une <b>INSTABILITÉ GÉNOMIQUE</b> et rend les tumeurs immunogènes → ⭐ <b>CIBLES pour l'IMMUNOTHÉRAPIE</b> (vaccins, CAR-T anti-NY-ESO-1)<br><br><b>8. 📋 RÉSUMÉ EN UNE PHRASE :</b><br>⭐ <b>La méiose = 1 réplication + 2 divisions = 4 cellules haploïdes génétiquement uniques</b>, avec <b>crossing-over en prophase I (pachytène)</b> et <b>assortiment indépendant en métaphase I</b> — elle <b>réduit de moitié le nombre de chromosomes</b> pour maintenir la stabilité du génome à travers les générations et <b>génère la diversité</b> nécessaire à l'évolution.","t":"biocell-2026 EXAM-2026 M111"},{"q":"L'<b>ADIPOCYTE BLANC</b> : structure, fonctions et particularités (module M111 / histologie)","a":"<b>📋 L'ADIPOCYTE BLANC (adipocyte uniloculaire) — FICHE COMPLÈTE :</b><br><br><b>1. DÉFINITION :</b> cellule spécialisée du <b>TISSU ADIPEUX BLANC (TAB)</b>, dont le rôle est le <b>STOCKAGE DE L'ÉNERGIE sous forme de TRIGLYCÉRIDES</b> dans <b>UNE SEULE grosse gouttelette lipidique</b>. C'est aussi une <b>CELLULE ENDOCRINE</b> majeure.<br><br><b>2. ⭐ STRUCTURE / MORPHOLOGIE :</b><br>• <b>Forme :</b> ⚠️ <b>SPHÉRIQUE</b> quand il est isolé, mais <b>POLYÉDRIQUE</b> dans le tissu (compression mutuelle)<br>• <b>Taille :</b> ⚠️ <b>TRÈS VARIABLE — de 20 à 200 µm de diamètre</b> selon l'état nutritionnel (un des <b>plus gros</b> types cellulaires de l'organisme). En moyenne <b>~60-100 µm</b><br>• <b>⭐ UNE SEULE GROSSE GOUTTELETTE LIPIDIQUE (UNILOCULAIRE)</b> — c'est le critère qui le distingue de l'adipocyte brun<br>• ⚠️ <b>LE CYTOPLASME EST RÉDUIT À UN MINCE LISERÉ PÉRIPHÉRIQUE</b><br>• ⚠️ <b>LE NOYAU EST REJETÉ À LA PÉRIPHÉRIE, APLATI, EXCENTRÉ</b> — c'est l'image caractéristique en « <b>BAGUE À CHATON</b> » ⭐<br>• <b>Pas de réticulum endoplasmique rugueux abondant</b> (peu de synthèse protéique massive) mais <b>RE lisse développé</b> (synthèse des lipides)<br>• <b>Mitocondries peu nombreuses</b> ⚠️ (contrairement à l'adipocyte brun qui en regorge)<br>• <b>Appareil de Golgi</b> près du noyau<br>• <b>Membrane plasmique</b> avec de <b>nombreuses invaginations (cavéoles)</b> riches en <b>cavéoline-1</b><br>• ⚠️ <b>MEMBRANE BASALE INDIVIDUELLE</b> autour de chaque adipocyte (laminine, collagène IV) + <b>réseau de fibres de RÉTICULINE (collagène III)</b> — chaque adipocyte est <b>isolé</b> mais soutenu<br>• ⚠️ <b>TRÈS VASCULARISÉ</b> : un réseau capillaire dense entoure chaque adipocyte (nécessaire pour la libération des acides gras)<br>• <b>INNERVÉ</b> : innervation <b>sympathique noradrénergique</b> (récepteurs β3-adrénergiques) — ⚠️ moins dense que dans le tissu brun<br><br><b>3. ⭐ COMPOSITION :</b><br>• ⚠️ <b>~90 % du volume cellulaire = LIPIDES</b> (la gouttelette occupe presque tout)<br>• <b>~5 à 10 % d'eau</b> ⚠️ (très peu d'eau — c'est pourquoi le TAB contient peu d'eau)<br>• <b>TRIGLYCÉRIDES (TG) = 90 % des lipides stockés</b> — estérification de <b>3 acides gras</b> sur un <b>glycérol</b><br>• <b>Cholestérol estérifié, phospholipides</b> en faible quantité<br>• ⚠️ <b>La gouttelette lipidique N'EST PAS un simple dépôt inerte</b> : c'est un <b>ORGANITE ACTIF</b>, entouré d'une <b>MONOCOUCHE de phospholipides</b> (et non d'une bicouche !) avec des <b>protéines spécifiques : PÉRILIPINES (PLIN1-5)</b> ⭐, <b>adipophiline (PLIN2)</b>, <b>CGI-58 (ABHD5)</b>, <b>CIDEA/CIDEC (FSP27)</b> (qui favorisent la fusion des gouttelettes → une seule grosse goutte)<br>• ⚠️ <b>La PÉRILIPINE 1</b> recouvre la gouttelette et <b>PROTÈGE les TG de la lipolyse</b> ; quand elle est <b>phosphorylée par la PKA</b>, elle change de conformation et laisse accéder la <b>lipase hormonosensible</b><br><br><b>4. ⭐⭐ FONCTIONS — L'ADIPOCYTE BLANC EST UN ORGANE ENDOCRINE :</b><br><br><b>a) STOCKAGE DE L'ÉNERGIE (LIPOGENÈSE)</b><br>• Après le repas : l'<b>INSULINE</b> stimule la captation du glucose (<b>GLUT4</b>) et des acides gras, la <b>lipogenèse</b> et le <b>stockage en TG</b><br>• Enzymes clés : <b>acétyl-CoA carboxylase, FAS (fatty acid synthase), DGAT1/2, GPAT, lipoprotéine lipase (LPL)</b> ⚠️ (la LPL est sur l'<b>endothélium capillaire</b>, activée par l'<b>apoC-II</b>, hydrolyse les TG des chylomicrons et VLDL)<br><br><b>b) MOBILISATION DE L'ÉNERGIE (LIPOLYSE)</b><br>• À jeun : le <b>GLUCAGON, l'ADRÉNALINE, l'ACTH, la GH, les catécholamines</b> activent la lipolyse via les <b>récepteurs β-adrénergiques → AMPc → PKA</b><br>• ⭐ <b>VOIE EN 3 ÉTAPES :</b><br>&nbsp;&nbsp;1. <b>ATGL (Adipose Triglyceride Lipase)</b> : TG → <b>diacylglycérol (DG)</b> + 1 AG ⚠️ activée par <b>CGI-58</b>, inhibée par <b>G0S2</b>. Mutations de ATGL → <b>myopathie avec surcharge lipidique (NLSDM)</b> ; mutations de CGI-58/ABHD5 → <b>syndrome de CHANARIN-DORFMAN</b> (ichtyose + surcharge lipidique)<br>&nbsp;&nbsp;2. ⭐ <b>HSL (Hormone-Sensitive Lipase / LIPE)</b> : DG → <b>monoacylglycérol (MG)</b> + 1 AG — <b>PHOSPHORYLÉE ET ACTIVÉE PAR LA PKA</b><br>&nbsp;&nbsp;3. <b>MGL (Monoacylglycérol Lipase)</b> : MG → <b>glycérol</b> + 1 AG<br>• ⚠️ Les <b>acides gras libérés</b> vont dans le sang, liés à l'<b>ALBUMINE</b> → utilisés par les muscles, le cœur, le foie (β-oxydation)<br>• ⚠️ Le <b>GLYCÉROL</b> va au foie → <b>néoglucogenèse</b> (l'adipocyte n'a pas de <b>glycérol kinase</b>, il ne peut pas le réutiliser !)<br>• ⚠️ <b>L'INSULINE INHIBE la lipolyse</b> (via la <b>phosphodiestérase PDE3B</b> qui dégrade l'AMPc) — c'est l'hormone <b>antilipolytique</b> majeure<br><br><b>c) ⭐⭐ FONCTION ENDOCRINE — LES ADIPOCYTOKINES (adipokines)</b><br>L'adipocyte blanc sécrète <b>plus de 600 molécules bioactives</b> :<br>• ⭐ <b>LEPTINE (obèse, OB)</b> — <b>proportionnelle à la MASSE GRASSE</b> — agit sur l'<b>hypothalamus (noyau arqué)</b> → <b>COUPE-FAIM (anorexigène)</b>, augmente la dépense énergétique. Gène <b>LEP (7q31)</b>. ⚠️ Mutations → <b>obésité morbide précoce</b> (traitée par leptine recombinante). ⚠️ Chez l'obèse commun, il y a une <b>RÉSISTANCE À LA LEPTINE</b> (taux élevés mais inefficaces). La leptine est aussi nécessaire à la <b>puberté et à la fertilité</b> (aménorrhée des sportives/anorexiques)<br>• ⭐ <b>ADIPONECTINE (Acrp30, adipose most abundant gene transcript 1)</b> — ⚠️ <b>ANTI-inflammatoire, INSULINOSENSIBILISANTE, ANTI-athérogène</b> — augmente l'oxydation des AG (via <b>AMPK</b>) — ⚠️ <b>SON TAUX DIMINUE avec l'OBÉSITÉ</b> (paradoxe !) — formes : trimères, hexamères, multimères de haut poids moléculaire (HMW = les plus actifs). Gène <b>ADIPOQ (3q27)</b><br>• <b>RÉSISTINE</b> — pro-inflammatoire, induit la résistance à l'insuline<br>• ⭐ <b>TNF-α et IL-6</b> — ⚠️ sécrétés surtout par les <b>MACROPHAGES infiltrés</b> dans le TAB de l'obèse → <b>inflammation chronique de bas grade</b> → <b>RÉSISTANCE À L'INSULINE</b> (le TNF-α phosphoryle en <b>SERINE</b> l'<b>IRS-1</b>, ce qui bloque la signalisation insulinique — découverte séminale de <b>Hotamisligil, 1993</b>)<br>• <b>MCP-1 (CCL2)</b> — recrute les macrophages → cercle vicieux inflammatoire<br>• <b>ANGIOTENSINOGÈNE</b> — le TAB est une source majeure → <b>hypertension</b> de l'obèse<br>• ⭐ <b>PAI-1 (Plasminogen Activator Inhibitor-1)</b> — pro-thrombotique → risque cardiovasculaire de l'obésité<br>• ⭐ <b>VISFATINE / NAMPT</b> — sécrétée par la graisse VISCÉRALE, effet insulino-mimétique, précurseur du NAD+<br>• <b>APÉLINE</b> — vasodilatateur, cardioprotecteur<br>• ⭐ <b>FGF21</b> — hormone métabolique, augmente la sensibilité à l'insuline<br>• <b>ASP (acylation stimulating protein)</b> — stimule le stockage des TG<br>• ⭐ <b>ADIPSINE (facteur D du complément)</b> — module la sécrétion d'insuline<br>• <b>IL-1β, IL-8, IL-10, TGF-β, MCP-1</b> — cytokines inflammatoires<br>• ⭐ <b>ESTROGÈNES</b> — le TAB exprime l'<b>AROMATASE</b> → convertit les androgènes en œstrogènes ⚠️ <b>source principale d'œstrogènes après la ménopause</b> → ⚠️ lien entre <b>OBÉSITÉ et CANCER DU SEIN et de l'ENDOMÈTRE</b> ⭐<br>• ⭐ <b>AMYLIN, CHOLESTERYL ESTER TRANSFER PROTEIN (CETP)</b>, <b>LPL</b>, <b>adipocyte fatty acid-binding protein (aP2/FABP4)</b><br>• <b>⚠️ Le TAB EST AUSSI UN ORGANE IMMUNITAIRE</b> : il contient des macrophages (M2 anti-inflammatoires chez le mince → M1 pro-inflammatoires chez l'obèse), des lymphocytes T, des éosinophiles, des ILC2<br><br><b>d) ISOLATION THERMIQUE et PROTECTION MÉCANIQUE</b><br>• Le TAB sous-cutané = <b>isolant thermique</b> (mais bien moins efficace que chez les mammifères marins)<br>• <b>Coussinets adipeux</b> : paumes, plantes, orbite, autour des reins (graisse périrénale), fesses → <b>protection mécanique</b> des organes<br>• ⚠️ La <b>graisse orbitaire</b> maintient le globe oculaire en place ; la <b>boule de Bichat</b> (graisse buccale du nourrisson) facilite la succion ⭐ <b>PERTINENT EN DENTAIRE</b><br><br><b>e) DÉTOXIFICATION et STOCKAGE des VITAMINES LIPOSOLUBLES</b><br>• Stocke les <b>vitamines A, D, E, K</b> ⚠️ (le TAB est la principale réserve de <b>vitamine D</b> — chez l'obèse, la vitamine D est séquestrée → carence fonctionnelle)<br>• Séquestre les <b>polluants lipophiles</b> (pesticides organochlorés, dioxines, PCB) → libérés lors de l'amaigrissement<br><br><b>5. ⭐ HYPERPLASIE vs HYPERTROPHIE :</b><br>• <b>HYPERTROPHIE</b> : <b>AUGMENTATION de la TAILLE</b> des adipocytes existants (jusqu'à 200 µm) — ⚠️ mécanisme dominant chez l'<b>ADULTE obèse</b><br>&nbsp;&nbsp;→ Adipocyte hypertrophié = <b>hypoxique</b> (distance de diffusion de l'O₂ dépassée) → <b>HIF-1α</b> activé → <b>fibrose</b>, <b>nécrose</b>, <b>recrutement de macrophages (couronnes nécrotiques / crown-like structures)</b> → <b>INFLAMMATION</b> → <b>RÉSISTANCE À L'INSULINE</b> ⭐<br>• <b>HYPERPLASIE (adipogenèse)</b> : <b>AUGMENTATION du NOMBRE</b> d'adipocytes par différenciation des <b>PRÉADIPOCYTES</b> à partir des <b>cellules souches mésenchymateuses (ADSC)</b> — ⚠️ dominant pendant l'<b>ENFANCE et l'ADOLESCENCE</b><br>&nbsp;&nbsp;→ ⚠️ <b>Le nombre d'adipocytes est FIXÉ vers l'âge de 20 ans et reste STABLE toute la vie adulte</b> (renouvellement ~<b>10 % par an</b>) — démontré par la méthode du <b>carbone 14 des essais nucléaires</b> (Spalding et al., Nature 2008) ⭐<br>&nbsp;&nbsp;→ C'est pourquoi <b>l'amaigrissement ne réduit PAS le nombre d'adipocytes</b>, seulement leur taille → <b>reprise de poids facile</b><br>• ⭐ <b>FACTEURS DE TRANSCRIPTION DE L'ADIPOGENÈSE :</b> <b>PPARγ</b> (le maître régulateur ⚠️ — cible des <b>glitazones/thiazolidinediones</b> : rosiglitazone, pioglitazone) et <b>C/EBPα</b> — ils s'activent mutuellement en boucle positive. En amont : <b>C/EBPβ, C/EBPδ, KLF15, SREBP1c</b>. Inhibiteurs : <b>PREF-1/DLK1, Wnt/β-caténine, GATA2/3, E2F1</b><br><br><b>6. ⭐ LES DÉPÔTS ADIPEUX — DEUX TYPES TRÈS DIFFÉRENTS :</b><br>• <b>GRAISSE SOUS-CUTANÉE</b> : dépôt <b>relativement SAIN</b>, plus métaboliquement « bénin »<br>• ⚠️ <b>GRAISSE VISCÉRALE (intra-abdominale, mésentérique, omentale)</b> : <b>DANGEREUSE</b> — très <b>lipolytique</b> (forte densité de récepteurs β3, faible sensibilité à l'insuline) → les <b>acides gras vont DIRECTEMENT au FOIE par la VEINE PORTE</b> ⭐ → <b>STÉATOSE HÉPATIQUE, résistance à l'insuline, dyslipidémie athérogène (TG↑, HDL↓, LDL petites et denses), inflammation</b> → <b>SYNDROME MÉTABOLIQUE</b><br>• <b>Mesure</b> : <b>TOUR DE TAILLE</b> — ⚠️ seuils de risque : <b>≥ 94 cm chez l'homme, ≥ 80 cm chez la femme</b> (IDF) ; <b>≥ 102 cm / ≥ 88 cm</b> (NCEP-ATP III) · <b>rapport taille/hanches</b><br>• <b>Obésité ANDROÏDE (pomme)</b> = graisse viscérale → risque cardiovasculaire élevé · <b>Obésité GYNÉCOÏDE (poire)</b> = graisse sous-cutanée fémorale/glutéale → risque moindre<br><br><b>7. ⚠️ COMPARAISON ADIPOCYTE BLANC vs BRUN vs BEIGE :</b><br>• <b>Gouttelette lipidique</b> : Blanc = <b>UNE SEULE grosse (UNILOCULAIRE)</b> · Brun = <b>PLUSIEURS petites (MULTILOCULAIRE)</b> · Beige = variable<br>• <b>Noyau</b> : Blanc = <b>PÉRIPHÉRIQUE, APLATI, EXCENTRÉ</b> ⚠️ (bague à chaton) · Brun = <b>CENTRAL, ROND</b> · Beige = intermédiaire<br>• <b>Mitochondries</b> : Blanc = <b>PEU NOMBREUSES</b> · Brun = <b>TRÈS NOMBREUSES ET VOLUMINEUSES</b> ⚠️ (couleur brune due au <b>cytochrome</b> et à la forte vascularisation) · Beige = nombreuses<br>• <b>Fonction</b> : Blanc = <b>STOCKAGE DE L'ÉNERGIE</b> · Brun = <b>PRODUCTION DE CHALEUR (THERMOGENÈSE)</b> · Beige = <b>thermogénèse induite</b><br>• <b>Protéine clé</b> : Brun/Beige = ⭐ <b>UCP1 (THERMOGÉNINE)</b> — une <b>protéine découplante de la membrane mitochondriale interne</b> qui fait <b>fuir les protons</b> sans passer par l'ATP synthase → l'énergie du gradient est <b>DISSIPÉE EN CHALEUR</b> ⚠️ Absente du TAB<br>• <b>Innervation</b> : Brun = <b>TRÈS DENSE (sympathique, noradrénaline, récepteurs β3)</b> · Blanc = modérée<br>• <b>Localisation du brun</b> : ⚠️ <b>NUQUE, région interscapulaire, médiastin, péri-rénal, péri-aortique, creux sus-claviculaire</b> — abondant chez le <b>NOUVEAU-NÉ</b> (protège de l'hypothermie, car il ne peut pas frissonner) et disparaît presque totalement chez l'adulte (mais reste détectable par <b>TEP-FDG</b> dans les creux sus-claviculaires)<br>• <b>Marqueurs du brun</b> : <b>UCP1, PRDM16, PGC-1α, PPARγ, CIDEC, CIDEA, EVA1, TMEM26, LHX8, ZIC1</b><br>• <b>Marqueurs du blanc</b> : <b>TBX15, SHOX2, HOXC8, HOXC9, WT1</b> (pour le blanc viscéral)<br>• ⭐ <b>L'ADIPOCYTE « BEIGE » ou « BRITE » (brown-in-white)</b> : adipocyte blanc qui <b>ACQUIERT des caractéristiques brunes</b> sous l'effet du <b>FROID</b>, de l'<b>exercice (irisine !)</b>, ou d'agonistes β3 → « <b>BROWNING / BEIGING</b> » → augmente la dépense énergétique → <b>CIBLE THÉRAPEUTIQUE contre l'obésité</b><br><br><b>8. ⚠️ PATHOLOGIES :</b><br>• <b>OBÉSITÉ</b> (IMC ≥ 30 kg/m²) : hypertrophie + inflammation + fibrose du TAB → <b>diabète de type 2, stéatose hépatique (NAFLD/MASH), hypertension, dyslipidémie, apnée du sommeil, arthrose, cancers (sein post-ménopause, endomètre, côlon, rein, œsophage, pancréas)</b><br>• <b>LIPOMES</b> : tumeurs bénignes du TAB — les <b>tumeurs des parties molles les plus fréquentes</b> ⭐. Mous, mobiles, indolores, sous-cutanés. ⚠️ Variants : <b>lipome à cellules fusiformes, lipome pléomorphe, angiolipome (douloureux !), hibernome (graisse brune)</b>. Translocations <b>12q13-15 (HMGA2)</b>, <b>13q, 6p</b><br>• <b>LIPOSARCOMES</b> : tumeurs malignes — <b>well-differentiated/atypical lipomatous tumor</b> (amplification <b>MDM2/CDK4</b> en <b>12q13-15</b>), <b>myxoïde</b> (t(12;16) <b>FUS-DDIT3</b>), <b>pléomorphe</b>, <b>dédifférencié</b><br>• <b>LIPODYSTROPHIES</b> : perte du TAB — <b>congénitales (Berardinelli-Seip, AGPAT2, BSCL2/seipine)</b> ou <b>acquises</b> → diabète sévère, hypertriglycéridémie. Traitement : <b>métréleptine</b> (leptine recombinante)<br>• ⚠️ <b>LIPODYSTROPHIE HIV</b> : chez les patients sous <b>antirétroviraux</b> (ancienne génération : <b>stavudine, zidovudine, inhibiteurs de protéase</b>) → perte de graisse faciale et des membres + accumulation viscérale/dorsocervicale (<b>bosse de bison</b>) → <b>perte de la boule de Bichat → joues creuses → stigmatisation</b> ⭐ <b>PERTINENT EN DENTAIRE/FACIAL</b> — traitement par injections d'acide poly-L-lactique (NewFill/Sculptra)<br>• <b>ANOREXIE MENTALE</b> : <b>atrophie du TAB</b>, perte de leptine → <b>aménorrhée</b>, hypothermie, ostéoporose<br>• <b>LIPEDEME</b> : accumulation pathologique de graisse au niveau des membres inférieurs chez la femme<br>• <b>XANTHOMES</b> : dépôts lipidiques cutanés/tendineux dans les hyperlipidémies (HF homozygote → xanthomes tubéreux dès l'enfance)<br>• <b>SYNDROME MÉTABOLIQUE</b> : critères IDF = <b>obésité abdominale + 2 parmi (TG ≥ 1,50 g/L, HDL bas, PA ≥ 130/85, glycémie ≥ 1,00 g/L)</b><br>• ⚠️ <b>Épiderme/derme</b> : le TAB est aussi impliqué dans la <b>cicatrisation</b> et la <b>défense cutanée</b> (dermal white adipose tissue, sécrétion de cathélicidine)<br><br><b>9. 📋 EN RÉSUMÉ — LES 5 POINTS À RETENIR :</b><br>1. ⭐ <b>UNILOCULAIRE</b> : <b>UNE SEULE</b> grosse gouttelette lipidique (~90 % du volume)<br>2. ⭐ <b>NOYAU PÉRIPHÉRIQUE APLATI</b> → aspect de « <b>BAGUE À CHATON</b> »<br>3. ⭐ <b>Taille 20-200 µm</b>, l'une des plus grosses cellules de l'organisme<br>4. ⭐ <b>ORGANE ENDOCRINE</b> : leptine, adiponectine, TNF-α, IL-6, résistine, PAI-1, œstrogènes (aromatase)<br>5. ⭐ <b>PEU DE MITOCHONDRIES, PAS d'UCP1</b> → pas de thermogenèse (contrairement au brun)","t":"biocell-2026 EXAM-2026 M111 histologie"}]},{"id":"biophysique-M114-S1-2026","nom":"☢️ Biophysique","src":"COURS Pr BOUZOUBAA + EL BOUSSIRI","ordre":7,"module":"M114","desc":"Rayons X · effet photoélectrique · Compton · ultrasons","cards":[{"q":"📘 <b>COURS OFFICIEL — M114 BIOPHYSIQUE &amp; SCIENCES DES MATÉRIAUX</b> (FMDC Casablanca, S1). ⭐ Quel est le barème exact et qui enseigne quoi ?","a":"<b>⭐⭐ HADA L-BARÈME L-OFFICIEL DYAL L-MODULE M114 (6 CRÉDITS)</b><br><br>📖 L-tableau kan f l-cours dyal <b>Pr BOUZOUBAA</b> (<i>Principe physique de l'imagerie en odontologie</i>, page « description du contenu du module ») :<br><br><b>MATIÈRE 1 : BIOPHYSIQUE</b><br>• <b>Interactions électron-matière</b> + <b>Les Ultrasons</b> → <b>15h</b> — <b>Pr Kh. EL BOUSSIRI</b><br>• <b>Interactions des rayonnements ionisants avec la matière</b> + <b>Équilibre acido-basique</b> → <b>10h</b> — <b>Pr Kh. EL GUERMAI</b><br>• <b>Radiobiologie</b> → <b>14h</b> — <b>PR BOUZOUBAA S.M</b><br>• <b>Radioprotection</b> → <b>14h</b> — <b>Pr A. GUENSI</b><br><br>⚠️ <b>TOTAL BIOPHYSIQUE = 53 HEURES</b> ⭐ (15 + 10 + 14 + 14)<br>⚠️ + <b>MATIÈRE 2 : SCIENCES DES MATÉRIAUX</b> (Pr BOUSSIRI + Pr GUERMAI)<br><br><b>🔴 ⭐⭐ CHNO HADA KAY-3NI LIK :</b><br>1. ⚠️ **<b>M114 machi ghir « ultrasons » — hada l-module l-a3la f l-heures f S1 kamal (53h biophysique + matériaux)</b> ⭐⭐<br>2. ⭐ **<b>4 PROFS MKHTALFIN</b> → kol wa7ed 3ando **manière**, **support** w **style dyal QCM**. **Khassk t-chouf l-4.**<br>3. ⭐ **<b>Radiobiologie (14h) + Radioprotection (14h) + Rayonnements ionisants (10h) = 38h</b> ⚠️ **38h ghir 3la les RAYONNEMENTS** — hiyà **l-qsim l-a3la f l-module kamal** ⭐⭐⭐ <b>HADA HOWA L-MOUÇIM DYAL L-EXAMEN</b><br>4. ⚠️ **L-ultrasons = 15h m3a l-interactions électron-matière** — ⭐ **donc machi l-awwawiya, w lakin kayen**<br><br><b>📂 L-DOSSIERS F DRIVE (arborescence l-qi7a) :</b><br>```\nBiophysique et sciences des matériaux/ (1qphThy4Ijo6gRqO3mE1_S55-_FH4W20a)\n├── Biophysique/ (1Z0xJr6BIgtQmNMDe9gWJHjszL8Qadv3s)\n│   ├── Prof Bouzoubaa/Cours/ → ✅ biopc.pdf (1AH0mLhLm0UB1zkc-brafWzA_u-lL3e4Z)\n│   ├── Prof El Boussiri/Cours/ → ✅ Ultrasons CM (1).pdf (1eNxDaeZAscZUHiDRru7sHEFkYCeXSd8e)\n│   ├── Prof El Boussiri/Resume/ → ⏳ (machi m9ri ba3d)\n│   ├── Prof Guensi/ → ⛔ HTTP 500 (rate-limit)\n│   └── Prof Khalil El Guermai/ → Cours · QCMS/EXERCICES · Résumé ⛔ HTTP 500\n├── Sciences Des Matériaux/ (1KySOdFqbkeDCNSEPfaormvH9Bhb1hXEn)\n│   ├── Prof Boussiri/ ⛔ HTTP 500\n│   └── Prof Guermai/ ⛔ HTTP 500\n├── Résumé/ (1j97yQ4hz5oKN54VkikHqpa7ClkxXkjHO)\n│   └── ⏳ BIOPHYSIQUE ET SC DES MATÉRIAUX PR.GUERMAI-BOUSSIRI-BOUZOUBAA.pdf\n│       (1V8Ed6S6SDASU714hUgcUeVnuuY2XL5hP) — 🔥 L-RÉSUMÉ DYAL L-3 PROFS !\n└── Annales/ (13djeO96rZ-9ZuzLyVJjqiOYTGj_TDBSm) ⏳\n```<br><br><b>🔴 L-PROFESSEURS :</b><br>• <b>Pr Sidi Mohammed BOUZOUBAA</b> — Professeur Agrégé en <b>Odontologie chirurgicale</b> · PhD génie génétique et pathologie moléculaire · <b>Enseignant de radiologie dentaire et maxillo-faciale à la FMDC</b> · Médecin spécialiste en chirurgie orale — <b>CHU Ibn Rochd</b> · DU radiologie dentaire et maxillo-faciale · DU implantologie orale · DU urgence médicale et chirurgicale · Certifié pédagogie et E-learning<br>&nbsp;&nbsp;→ ⭐ <b>Hada howa l-prof dyal l-RADIOBIOLOGIE (14h) w l-imagerie</b> ⭐<br>• <b>Pr Khalid EL BOUSSIRI</b> — Professeur de l'enseignement supérieur, <b>Professeur de BIOMATÉRIAUX</b> · Chef d'équipe de recherche : <b>Groupe de biomatériaux métalliques</b> ⭐<br>&nbsp;&nbsp;→ ⭐ <b>Hada howa l-prof dyal l-ULTRASONS (15h) w les MATÉRIAUX</b> ⭐<br>• <b>Pr Khalil EL GUERMAI</b> — <b>Interactions des rayonnements ionisants + équilibre acido-basique (10h)</b> + <b>Matériaux</b><br>• <b>Pr A. GUENSI</b> — <b>Radioprotection (14h)</b> ⭐⭐<br><br><b>📋 ⭐ L-PLAN DYAL L-COURS DYAL Pr BOUZOUBAA (S1 → S8) :</b><br>• <b>S1</b> : 1. Les principes physiques des rayons X · 2. Initiation à la radiologie · 3. <b>Radioprotection</b> ⭐<br>• <b>S3</b> : 4. Incidences standards <b>INTRA-ORALES</b> — <b>cliché rétroalvéolaire, rétro-coronaire, occlusal</b> ⭐<br>• <b>S6</b> : 4. Incidences <b>EXTRA-ORALES</b> — <b>téléradiographie de profil, radiographie de face</b> · 5. Incidence tomographique — <b>panoramique</b> ⭐<br>• <b>S8</b> : 6. Incidence volumétrique 3D — <b>scanner, Cone Beam (CBCT)</b> ⭐⭐ <b>L-AVENIR DYAL L-RADIOLOGIE DENTAIRE</b><br>• 7. Examens complémentaires : <b>IRM, échographie…</b><br><br>⚠️ <b>REMARQUE STRATÉGIQUE :</b> l-plan y-kmel 7tta **<b>S8</b>**. Donc f **<b>S1</b> ghadi y-9arriw ghir **<b>les rayons X + initiation + radioprotection</b>**. ⭐ **Hadou howa li ghadi yjiw f l-examen dyal Janvier** — **machî l-CBCT w l-panoramique** (hadouk S6/S8) ⭐⭐ <b>HADA KAY-WFFER 3LIK DES HEURES</b>","t":"biophysique-2026 M114 COURS-OFFICIEL EXAM-2026"},{"q":"<b>LES RAYONS X — 1-1 &amp; 1-2</b> : ⭐ historique, définition et place dans le spectre électromagnétique (cours Pr BOUZOUBAA)","a":"<b>🔴 1-1 — L'HISTORIQUE ⭐⭐ (question d'examen facile — les chiffres) :</b><br>• ⭐ <b><b>1895</b> : Wilhelm Conrad RÖNTGEN</b> découvre les rayons X ⭐⭐<br>• ⭐ <b>PRIX NOBEL en <b>1901</b></b> ⭐ (⚠️ <b>le 1ᵉʳ prix Nobel de physique de l'histoire</b>)<br>• ⚠️ <b>L'expérience :</b> un <b>tube en absence d'air</b>, avec une <b>anode et une cathode</b> → il remarque qu'un <b>film</b> posé à distance se <b>sensibilise</b> → il découvre le <b>squelette de sa main</b> ⭐<br>• ⚠️ <b>Noms :</b> « <b>Ry X</b> » ou « <b>X rays</b> » ou « <b>الأشعة السينية</b> » (en arabe : achi3a siniyya) ⭐<br><br><b>🔴 1-2 — LA DÉFINITION ⭐ :</b><br>📖 « <b>Le RAYON X est un RAYONNEMENT ÉLECTROMAGNÉTIQUE comme les ondes radio, la lumière visible, ou les infra-rouges.</b> » ⭐<br><br>⚠️ ⭐ <b>LES CARACTÉRISTIQUES CHIFFRÉES (À APPRENDRE PAR CŒUR — TRÈS TOMBABLES) :</b><br>• <b>LONGUEURS D'ONDE : de l'ordre de <b>10⁻⁸ à 10⁻¹² mètre</b></b> ⭐⭐<br>• <b>FRÉQUENCES : <b>10¹⁶ Hz et 10²⁰ Hz</b></b> ⭐⭐<br>• <b>ÉNERGIE DES PHOTONS X : comprise entre <b>40 et 4 × 10⁵ eV</b></b> ⭐⭐<br>• ⚠️ Conséquence : « <b>Rayon X : TRÈS PÉNÉTRANT</b> » ⭐<br><br><b>🔴 ⭐⭐ LE SPECTRE ÉLECTROMAGNÉTIQUE (TABLEAU DU COURS — par LONGUEUR D'ONDE CROISSANTE, en m) :</b><br>• <b>Rayons GAMMA</b> → <b>10⁻¹²</b> ⭐<br>• <b>Rayons X</b> → <b>10⁻⁹</b> ⭐⭐<br>• <b>Ultra-violet (UV)</b> → <b>10⁻⁶</b> ⭐<br>• <b>Infra-rouge (IR)</b> → <b>10⁻³</b> ⭐<br>• <b>Micro-ondes</b> → <b>1</b> ⭐<br>• <b>Ondes radar</b> → <b>1000</b> ⭐<br>• <b>Ondes radio</b> → <b>1000</b> ⭐<br><br>⚠️ <b>MNÉMOTECHNIQUE :</b> « <b>G</b>rand <b>X</b>avier <b>U</b>tilise <b>I</b>nmédiatement <b>M</b>ille <b>R</b>adars <b>R</b>adio » = <b>γ → X → UV → IR → Micro → Radar → Radio</b> ⭐<br>⚠️ ⭐ <b>Ordre de grandeur :</b> ⚠️ <b>λ CROÎT</b> donc <b>ÉNERGIE DÉCROÎT</b> → <b>les γ sont les PLUS ÉNERGÉTIQUES</b>, <b>les ondes radio les MOINS</b> ⭐⭐<br><br><b>🔴 LA LUMIÈRE VISIBLE (tableau du cours, en nm) ⭐ :</b><br><b>400 nm (violet) → 450 → 500 → 550 → 600 → 650 → 700 → 750 → 800 nm (rouge)</b> ⭐<br>• ⚠️ ⭐ <b>LA LUMIÈRE VISIBLE = 400 à 800 nm</b> ⭐ <b>CHIFFRE À RETENIR</b><br>• ⚠️ ⭐ <b>Elle est ENTRE les UV (10⁻⁶ m = 1000 nm) et les IR (10⁻³ m)</b> ⭐<br>• ⚠️ ⭐ <b>ORDRE DE CROISSANCE DES λ :</b> <b>γ (10⁻¹²) &lt; RX (10⁻⁹) &lt; UV (400 nm) &lt; VISIBLE (400-800 nm) &lt; IR (10⁻⁶ m) &lt; micro-ondes (1 m)</b> ⭐⭐<br><br><b>📋 ⭐⭐ LA RELATION FONDAMENTALE (à maîtriser) :</b><br>• ⭐ <b>c = λ × ν</b> où <b>c = 3 × 10⁸ m/s</b> (vitesse de la lumière dans le vide) ⭐⭐<br>• ⭐ <b>E = h × ν = hc / λ</b> où <b>h = 6,63 × 10⁻³⁴ J·s</b> (constante de Planck) ⭐⭐<br>• ⚠️ <b>DONC :</b> ⭐ <b>plus λ est COURTE, plus l'ÉNERGIE est GRANDE</b> ⭐⭐ <b>CONCEPT LE PLUS IMPORTANT</b><br>• ⚠️ <b>Unité pratique en radiologie : l'<b>électron-volt (eV)</b></b> — ⭐ <b>1 eV = 1,6 × 10⁻¹⁹ J</b> ⭐ · ⚠️ <b>1 keV = 1000 eV</b> ⭐<br>• ⚠️ ⭐ <b>En radiologie dentaire :</b> les tensions utilisées sont de <b>60 à 70 kV</b> (donc des photons jusqu'à <b>60-70 keV</b>) ⭐⭐ <b>PERTINENT</b><br><br><b>📋 ⭐⭐ LA TRIADE DE LA RADIOLOGIE (schéma central du cours) :</b><br><b>1. LA SOURCE RX</b> → <b>Production de rayons X</b> → <b>Interactions ÉLECTRONS-matière</b> → <b>Formation de l'IMAGE RADIANTE</b><br><b>2. L'OBJET</b> (le patient / la dent) → <b>Interactions PHOTONS-matière</b> → <b>Formation de l'IMAGE RADIOLOGIQUE</b><br><b>3. LE DÉTECTEUR</b> → <b>Interactions PHOTONS-matière</b> ⭐⭐ <b>À CONNAÎTRE PAR CŒUR — SCHÉMA TOMBABLE</b><br><br><b>📋 ⭐ LES OBJECTIFS DU COURS (énumération exacte) :</b><br>• <b>DÉFINIR le Ry X</b><br>• <b>DÉCRIRE le mécanisme de PRODUCTION de Ry X</b><br>• <b>DÉCRIRE les différents types d'INTERACTION des RX avec la matière</b><br>• <b>DÉCRIRE l'INTERACTION des RX avec le DÉTECTEUR</b> ⭐","t":"biophysique-2026 M114 COURS-OFFICIEL"},{"q":"<b>1-3 — LA PRODUCTION DES RAYONS X</b> : ⭐ le tube de Coolidge, l'anode tournante et le mécanisme","a":"<b>⭐⭐ QUESTION D'EXAMEN CLASSIQUE — SCHÉMA À CONNAÎTRE</b><br><br><b>🔴 LE TUBE (1-3) :</b><br>📖 « <b>Les faisceaux de rayons X utilisés en médecine sont généralement produits par des « TUBES À RAYONS X » ou « TUBE DE COOLIDGE ». Celui-ci est constitué d'un TUBE DE VERRE où règne un VIDE POUSSÉ.</b> » ⭐⭐ <b>LE NOM « TUBE DE COOLIDGE » EST TOMBABLE</b><br><br><b>📋 ⭐⭐ LES COMPOSANTS (liste du schéma du cours) :</b><br>• <b>Tube sous VIDE</b> ⭐<br>• <b>CATHODE</b> = <b>FILAMENT DE TUNGSTÈNE</b> ⭐⭐ (⚠️ pourquoi le tungstène ? <b>Z = 74</b>, point de fusion <b>3 422 °C</b> — le plus élevé des métaux)<br>• <b>ANODE / ANTI-CATHODE</b> = <b>CIBLE MÉTALLIQUE</b> ⭐⭐<br>• <b>HAUTE TENSION (accélératrice)</b> ⭐ — ⚠️ <b>entre la cathode et l'anode</b>, de l'ordre de <b>20 à 150 kV</b> en radiologie<br>• <b>CIRCUIT DE CHAUFFAGE DU FILAMENT</b> (basse tension) ⭐ — ⚠️ produit l'<b>émission thermoïonique</b> ⭐<br>• <b>COUPELLE DE FOCALISATION</b> ⭐ — ⚠️ concentre le faisceau d'électrons sur une petite surface = le <b>FOYER</b> ⭐<br>• <b>FENÊTRE EN BÉRYLLIUM</b> ⭐⭐ ⚠️ <b>QUESTION PIÈGE CLASSIQUE</b> — ⚠️ <b>pourquoi le BÉRYLLIUM ?</b> car <b>Z = 4</b> = <b>très faible numéro atomique</b> → <b>le verre du tube absorberait les RX</b>, alors que le béryllium les <b>laisse passer</b> ⭐⭐<br><br><b>📋 ⭐⭐ LE MÉCANISME (3 temps) :</b><br><b>1.</b> ⭐ « <b>Les ÉLECTRONS sont EXTRAITS d'une CATHODE DE TUNGSTÈNE CHAUFFÉE</b> » ⭐ — ⚠️ c'est l'<b>ÉMISSION THERMOÏONIQUE</b> (découverte par <b>Edison</b>) ⭐<br><b>2.</b> ⭐ « <b>ACCÉLÉRÉS par une TENSION ÉLECTRIQUE dans un TUBE SOUS VIDE</b> » ⭐<br><b>3.</b> ⭐ « <b>Ce faisceau sert à BOMBARDER une CIBLE MÉTALLIQUE (appelée ANODE ou ANTI-CATHODE)</b> » ⭐<br><br><b>🔴 ⭐⭐ LE MOT CLÉ DU COURS :</b><br>📖 « <b>L'ÉMISSION DES RAYONS X est la conséquence des interactions (<b>FREINAGE</b>) qui se produisent entre des ÉLECTRONS RAPIDES et les particules d'une CIBLE MÉTALLIQUE dans lequel ils pénètrent.</b> » ⭐⭐⭐<br><br>⚠️ ⭐⭐ <b>LE TERME ALLEMAND :</b> <b>BREMSSTRAHLUNG</b> = « <b>rayonnement de freinage</b> » ⭐⭐ <b>MOT À CONNAÎTRE ABSOLUMENT</b><br><br><b>📋 ⭐⭐ LES 2 MÉCANISMES DE PRODUCTION (détail) :</b><br><b>1. LE RAYONNEMENT DE FREINAGE (Bremsstrahlung)</b> ⭐⭐<br>• L'électron rapide <b>passe près du noyau</b> de l'atome de la cible → il est <b>dévié et ralenti</b> par le champ électrique du noyau → ⭐ <b>la perte d'énergie cinétique est émise sous forme d'un PHOTON X</b> ⭐⭐<br>• ⚠️ ⭐ <b>Donne un SPECTRE CONTINU</b> (toutes les énergies de 0 jusqu'à <b>E<sub>max</sub> = e·U</b>, où U = la tension en kV) ⭐⭐<br>• ⚠️ <b>C'est le mécanisme LARGEMENT DOMINANT</b> : <b>~80 %</b> des photons ⭐<br><br><b>2. LE RAYONNEMENT CARACTÉRISTIQUE</b> ⭐⭐<br>• L'électron incident <b>éjecte un électron des couches PROFONDES (K, L)</b> de l'atome de la cible → un électron d'une couche plus externe « <b>descend</b> » combler le trou → ⭐ <b>émet un photon X dont l'énergie est CARACTÉRISTIQUE de l'atome de la cible</b> ⭐⭐<br>• ⚠️ ⭐ <b>Donne un SPECTRE DE RAIES (discret)</b> — ⭐ les raies <b>Kα, Kβ, Lα…</b> ⭐<br>• ⚠️ <b>~20 %</b> des photons ⭐<br>• ⚠️ ⭐ <b>Les raies K du TUNGSTÈNE sont à ~59 keV (Kα) et ~67 keV (Kβ)</b> ⭐<br><br><b>🔴 L'ANODE TOURNANTE ⭐⭐ (schéma détaillé dans le cours) :</b><br>• ⚠️ <b>POURQUOI TOURNANTE ?</b> Le bombardement électronique dégage <b>une chaleur énorme</b> — ⭐ <b>99 % de l'énergie des électrons est transformée en CHALEUR</b>, et <b>seulement ~1 % en rayons X</b> ⭐⭐⭐ <b>CHIFFRE TRÈS TOMBABLE</b><br>• ⭐ En faisant <b>TOURNER</b> l'anode, la chaleur se répartit sur toute la <b>PISTE</b> (couronne) au lieu de fondre un seul point ⭐<br>• <b>Composition (schéma du cours) :</b><br>&nbsp;&nbsp;– <b>PISTE EN TUNGSTÈNE</b> ⭐ (la piste de frottement — ⚠️ là où frappent les électrons)<br>&nbsp;&nbsp;– <b>CORPS EN MOLYBDÈNE RHÉNIÉ</b> ou <b>en GRAPHITE</b> ⭐⭐ ⚠️ <b>DÉTAIL TOMBABLE</b> — ⭐ le molybdène et le graphite sont <b>légers</b> et <b>bons conducteurs thermiques</b> → dissipent la chaleur<br>&nbsp;&nbsp;– <b>COURONNE</b> ⭐ · <b>ROTOR</b> ⭐ · <b>QUEUE</b> ⭐<br>&nbsp;&nbsp;– <b>ALIMENTATION ANODE TOURNANTE</b> ⭐ (moteur à induction)<br>• ⚠️ ⭐ « <b>l'orientation de la piste d'anode est OBLIQUE par rapport au faisceau d'électrons</b> » ⭐ — ⚠️ <b>DÉTAIL DU COURS</b> → ⭐ c'est le principe de la <b>LIGNE DE FOYER</b> et de <b>l'ANGLE ANODIQUE</b> (généralement <b>12 à 20°</b>) ⭐<br><br><b>📋 ⭐⭐ RÉSUMÉ — LES 5 POINTS :</b><br>1. ⭐ <b>TUBE DE COOLIDGE</b> = tube de verre sous <b>VIDE POUSSÉ</b><br>2. ⭐ <b>CATHODE = filament de TUNGSTÈNE chauffé</b> → émission thermoïonique<br>3. ⭐ <b>ANODE = cible métallique</b> ; <b>HAUTE TENSION</b> accélère les électrons<br>4. ⭐ <b>MÉCANISME = le FREINAGE (Bremsstrahlung)</b> → <b>99 % chaleur / ~1 % RX</b><br>5. ⭐ <b>FENÊTRE EN BÉRYLLIUM</b> (Z=4, laisse passer les RX) · <b>ANODE TOURNANTE</b> (dissipe la chaleur, piste tungstène + corps molybdène rhénié/graphite)","t":"biophysique-2026 M114 COURS-OFFICIEL"},{"q":"<b>1-4 — L'INTERACTION AVEC LA MATIÈRE</b> : ⭐⭐ <b>EFFET PHOTOÉLECTRIQUE vs EFFET COMPTON</b> (le couple le plus tombable du module)","a":"<b>⭐⭐⭐ HADA HOWA L-CŒUR DYAL L-MODULE — À CONNAÎTRE SUR LE BOUT DES DOIGTS</b><br><br>📖 <b>INTRODUCTION DU COURS :</b><br>« <b>L'interaction entre les rayons X utilisés en RADIODIAGNOSTIC et la matière organique comprend ESSENTIELLEMENT l'<b>EFFET PHOTOÉLECTRIQUE</b> et l'<b>EFFET COMPTON</b>. La compréhension de ces mécanismes atomiques permet d'appréhender les facteurs impliqués dans l'<b>ATTÉNUATION SÉLECTIVE</b> du faisceau de rayons X et donc dans le <b>CONTRASTE</b> de l'image radiographique.</b> » ⭐⭐<br><br><b>🔴 ⭐⭐ EFFET PHOTOÉLECTRIQUE :</b><br>📖 <b>MÉCANISME (texte du cours) :</b><br>« <b>L'effet photoélectrique se produit lorsqu'un <b>RAYON X</b> arrive à proximité d'un <b>ÉLECTRON D'UNE COUCHE PROFONDE</b> avec suffisamment d'énergie pour pouvoir l'<b>ÉJECTER</b>. Le rayon X est <b>ABSORBÉ</b> et le trop plein d'énergie se retrouve dans l'<b>ÉNERGIE CINÉTIQUE du « PHOTOÉLECTRON »</b>. Le <b>« TROU »</b> laissé par l'électron éjecté est <b>REMPLI PAR UN ÉLECTRON D'UNE COUCHE PLUS SUPERFICIELLE</b>, qui laisse échapper <b>UN RAYON X CARACTÉRISTIQUE DE FAIBLE ÉNERGIE</b> lors de sa <b>« DESCENTE »</b>.</b> » ⭐⭐⭐<br><br>⚠️ <b>LES 3 RÉSULTATS (texte du cours) :</b><br>1. ⭐ <b>L'ARRÊT du rayon X</b> — ⚠️ « le rayon X caractéristique est d'énergie trop faible pour avoir un effet significatif » ⭐<br>2. ⭐ <b>La PRODUCTION d'un PHOTOÉLECTRON</b> — ⚠️ « qui pourra avoir des <b>EFFETS BIOLOGIQUES NÉFASTES</b> » ⭐⭐<br>3. ⭐ <b>La PRODUCTION d'un ION POSITIF</b> ⭐<br><br>⚠️ ⭐⭐ <b>LES CONDITIONS (LES 2 CHIFFRES DU COURS) :</b><br>• ⭐ « <b>L'effet photoélectrique est l'effet PRINCIPAL dans les matières ORGANIQUES lorsque les rayons X sont de relativement <b>FAIBLE ÉNERGIE</b>. On considère que l'effet photoélectrique est l'effet MAJEUR pour des TENSIONS <b>INFÉRIEURES À 70 kV</b>.</b> » ⭐⭐⭐<br>• ⭐ <b>IL DÉPEND DU NUMÉRO ATOMIQUE Z</b> — ⚠️ probabilité ∝ <b>Z³ / E³</b> ⭐⭐ <b>FORMULE À CONNAÎTRE</b><br>&nbsp;&nbsp;→ ⚠️ ⭐ <b>CONSEQUENCE CLINIQUE MAJEURE :</b> c'est l'effet photoélectrique qui crée le <b>CONTRASTE</b> entre les tissus ⭐<br>&nbsp;&nbsp;→ ⭐ <b>L'OS</b> contient du <b>CALCIUM (Z = 20)</b> et du <b>PHOSPHORE (Z = 15)</b> → Z élevé → ⭐ <b>forte absorption photoélectrique → l'os apparaît BLANC (radiopaque)</b> ⭐⭐<br>&nbsp;&nbsp;→ ⭐ <b>LES TISSUS MOUS</b> (H, C, O, N → Z faibles : 1, 6, 8, 7) → ⭐ <b>faible absorption → apparaissent GRIS/NOIR (radiolucides)</b> ⭐⭐<br>&nbsp;&nbsp;→ ⭐⭐ <b>EN DENTAIRE :</b> <b>l'ÉMAIL</b> est le tissu le plus minéralisé du corps (<b>96 % de matière minérale</b>, hydroxyapatite) → ⭐ <b>le PLUS RADIOPAQUE → BLANC ÉCLATANT</b> ⭐ · <b>dentine</b> (70 %) moins · <b>cément</b> (45-50 %) encore moins · <b>pulpe</b> = tissu mou = <b>radiolucide</b> ⭐⭐ <b>LA BASE DE TOUTE LA RADIOLOGIE DENTAIRE</b><br>&nbsp;&nbsp;→ ⭐ <b>C'est aussi pour ça qu'on utilise le PLOMB (Z = 82)</b> pour les <b>tabliers</b> et les <b>parois</b> ⭐⭐ <b>LIEN AVEC LA RADIOPROTECTION (Pr GUENSI, 14h)</b><br><br><b>🟠 ⭐⭐ EFFET COMPTON :</b><br>📖 <b>MÉCANISME (texte du cours) :</b><br>« <b>L'effet Compton se produit lorsqu'un RAYON X se trouve à proximité d'un <b>ÉLECTRON PÉRIPHÉRIQUE PEU LIÉ</b> à l'atome (appelé parfois électron « <b>LIBRE</b> »). L'<b>ÉNERGIE</b> du rayon X est transmise <b>EN PARTIE</b> à l'électron qui s'échappe avec une certaine énergie cinétique. <b>LE RESTE DE L'ÉNERGIE</b> se retrouve sous la forme d'un <b>RAYON X DE DIRECTION DIFFÉRENTE ET D'ÉNERGIE INFÉRIEURE</b>.</b> » ⭐⭐⭐<br><br>⚠️ <b>LES 3 RÉSULTATS (texte du cours) :</b><br>1. ⭐ <b>Une DÉVIATION avec une PERTE D'ÉNERGIE</b> du rayon X ⭐<br>2. ⭐ <b>La PRODUCTION d'un ÉLECTRON et d'un ION POSITIF</b> ⭐<br>3. ⭐⭐ « <b>La NOUVELLE DIRECTION du rayon X est <b>ALÉATOIRE</b>, ce qui correspond à une <b>DIFFUSION</b> du faisceau dans <b>TOUTES LES DIRECTIONS, Y COMPRIS DANS LE SENS OPPOSÉ AU FAISCEAU PRIMAIRE</b>.</b> » ⭐⭐⭐ <b>DÉTAIL TOMBABLE</b><br>&nbsp;&nbsp;→ ⚠️ ⭐ <b>CONSEQUENCE :</b> « ce rayonnement est encore suffisamment énergétique pour avoir des <b>EFFETS SIGNIFICATIFS SUR L'IMAGE RADIOGRAPHIQUE</b> et constituer un <b>DANGER dont il faut se PROTÉGER</b> » ⭐⭐ <b>C'EST LE « RAYONNEMENT DIFFUSÉ » = le DANGER N°1 EN RADIOPROTECTION</b> ⭐<br><br>⚠️ ⭐⭐ <b>LES CONDITIONS (LES 2 CHIFFRES DU COURS) :</b><br>• ⭐⭐ « <b>La probabilité d'interaction par un effet Compton <b>NE DÉPEND QUE DE LA DENSITÉ</b> du matériel et <b>NE DÉPEND PAS DU NUMÉRO ATOMIQUE</b> (comme pour l'effet photoélectrique).</b> » ⭐⭐⭐ <b>LA DIFFÉRENCE LA PLUS TOMBABLE</b><br>• ⭐⭐ « <b>L'effet Compton est PRÉPONDÉRANT dans les tissus organiques avec des rayons X de <b>FORTE ÉNERGIE</b> (tension <b>&gt; 100 kV</b>).</b> » ⭐⭐⭐<br><br><b>🔴 ⭐⭐⭐ LE TABLEAU COMPARATIF — À APPRENDRE PAR CŒUR :</b><br>• <b>Électron cible</b> : Photoélectrique = <b>COUCHE PROFONDE</b> (lié) · Compton = <b>PÉRIPHÉRIQUE / « LIBRE »</b> ⭐⭐<br>• <b>Devenir du photon</b> : Photoélectrique = ⭐ <b>ABSORPTION TOTALE</b> (le photon DISPARAÎT) · Compton = ⭐ <b>DIFFUSION</b> (le photon CONTINUE, dévié, avec MOINS d'énergie) ⭐⭐⭐<br>• <b>Dépendance en Z</b> : Photoélectrique = ⭐ <b>OUI — ∝ Z³</b> · Compton = ⭐ <b>NON — dépend seulement de la DENSITÉ électronique</b> ⭐⭐⭐<br>• <b>Dépendance en E</b> : Photoélectrique = ⭐ <b>∝ 1/E³</b> (diminue quand E augmente) · Compton = diminue <b>lentement</b> avec E<br>• <b>Tension</b> : Photoélectrique = ⭐ <b>&lt; 70 kV</b> (effet majeur) · Compton = ⭐ <b>&gt; 100 kV</b> (prépondérant) ⭐⭐⭐<br>• <b>Rôle dans l'image</b> : Photoélectrique = ⭐ <b>CONTRASTE</b> (différencie os/tissus mous) · Compton = ⭐ <b>BRUIT / VOILE</b> (dégrade l'image) ⭐⭐<br>• <b>Radioprotection</b> : Photoélectrique = dose au patient · Compton = ⭐ <b>RAYONNEMENT DIFFUSÉ = danger pour le praticien</b> ⭐⭐<br>• <b>Produits</b> : Photoélectrique = photoélectron + ion + RX caractéristique faible · Compton = électron de recul + ion + photon diffusé ⭐<br><br><b>🔴 ⭐⭐ L'ATTÉNUATION — LA FORMULE DU COURS :</b><br>📖 « <b>Le COEFFICIENT D'ATTÉNUATION µ exprime la PROBABILITÉ pour un photon de subir une INTERACTION.</b> » ⭐<br><br>⭐⭐ <b><b>I = I₀ · exp(−µx)</b></b> ⭐⭐ <b>FORMULE À CONNAÎTRE ABSOLUMENT</b><br>• <b>I₀</b> = intensité incidente · <b>I</b> = intensité transmise · <b>µ</b> = coefficient d'atténuation linéique · <b>x</b> = épaisseur<br>• ⚠️ <b>ATTÉNUATION = EXPONENTIELLE DÉCROISSANTE</b> — ⭐ <b>jamais linéaire</b> ⭐<br>• ⚠️ ⭐ <b>LES 3 FACTEURS (énumérés dans le schéma du cours) :</b> <b>1. L'ÉPAISSEUR du milieu · 2. La NATURE du milieu (Z) · 3. L'ÉNERGIE des photons</b> ⭐⭐<br>• ⚠️ ⭐ <b>µ dépend de :</b> <b>Z du matériau</b>, <b>densité ρ</b>, <b>énergie E des photons</b><br>• ⚠️ <b>Grandeurs dérivées :</b> <b>µ/ρ</b> = coefficient d'atténuation <b>massique</b> ⭐ · <b>CDA = couche de demi-atténuation</b> = épaisseur qui réduit I₀ de moitié : ⭐ <b>CDA = ln2 / µ ≈ 0,693 / µ</b> ⭐⭐ <b>Formule très tombable</b><br>• ⚠️ ⭐ <b>En radiologie dentaire (60-70 kV) :</b> ⭐ <b>l'effet photoélectrique DOMINE</b> ⭐ <b>donc excellent contraste os/dent</b> ⭐⭐<br><br><b>📋 ⭐ LE SCHÉMA-BILAN DU COURS :</b><br><b>RAYONS X → MILIEU →</b> ⭐ <b>TRANSMISSION</b> (sans interaction = le photon traverse) · ⭐ <b>ABSORPTION</b> (effet PHOTOÉLECTRIQUE = absorption totale) · ⭐ <b>DIFFUSION</b> (effet COMPTON = Rx diffusé) · <b>RÉTRODIFFUSION</b> (diffusion vers l'arrière) ⭐","t":"biophysique-2026 M114 COURS-OFFICIEL"},{"q":"<b>LES ULTRASONS</b> (Pr Kh. EL BOUSSIRI) : ⭐⭐ les phénomènes périodiques, l'onde sonore, et les 3 domaines de fréquences","a":"<b>⭐⭐ COURS OFFICIEL — Pr Khalid EL BOUSSIRI, Professeur de BIOMATÉRIAUX, Chef du Groupe de biomatériaux métalliques, FMDC</b><br><br><b>📋 ⭐ LES 7 POINTS ESSENTIELS (annoncés en page 2 du cours) :</b><br>• L'<b>ONDE SONORE</b> · La <b>NATURE</b> de l'onde sonore · La <b>VITESSE DU SON</b> · Le <b>NIVEAU DE PUISSANCE ACOUSTIQUE</b> · Le <b>COEFFICIENT D'ATTÉNUATION</b> · La <b>RÉFLEXION</b> d'une onde sonore · L'<b>ÉCHOGRAPHIE</b> ⭐<br><br><b>🔴 1. LES PHÉNOMÈNES PÉRIODIQUES — LES 6 DÉFINITIONS ⭐ :</b><br>📖 « <b>Un phénomène PÉRIODIQUE est un phénomène qui SE REPRODUIT DANS LE TEMPS EN RESTANT IDENTIQUE À LUI-MÊME.</b> » ⭐<br><br>1. ⭐ <b>LA PÉRIODE T (en s)</b> : « C'est le <b>TEMPS</b> au bout duquel le phénomène se reproduit » ⭐<br>2. ⭐ <b>LA FRÉQUENCE ν</b> : « C'est le <b>NOMBRE DE PÉRIODES T PAR UNITÉ DE TEMPS</b>. On a : <b>ν = 1/T</b>. Unité = <b>HERTZ (Hz) = s⁻¹</b> » ⭐⭐<br>3. ⭐ <b>L'ÉLONGATION u</b> : « Elle correspond au <b>MOUVEMENT u d'une PARTICULE</b> en un point donné <b>x</b> du milieu » ⭐<br>4. ⭐ <b>L'AMPLITUDE A</b> : « C'est la <b>VALEUR MAXIMALE de l'ÉLONGATION</b>. On a : <b>u<sub>(x,t)</sub> = A·f(t)</b> » ⭐<br>5. ⭐ <b>LA VITESSE v ET L'ACCÉLÉRATION γ du MOUVEMENT VIBRATOIRE</b> : « Ce sont la vitesse <b>v</b> et l'accélération <b>γ</b> du DÉPLACEMENT D'UN POINT DU MILIEU lors du mouvement vibratoire. On a : <b>v = du/dt = A·f'(t)</b> et <b>γ = dv/dt = d²u/dt²</b> » ⭐<br>6. ⭐⭐ <b>LA VITESSE DE PROPAGATION ou CÉLÉRITÉ c</b> : « C'est la vitesse de <b>DÉPLACEMENT DE L'ONDE</b> dans le milieu » ⭐⭐ ⚠️ <b>À NE PAS CONFONDRE avec la vitesse v du mouvement vibratoire de la particule !</b> ⭐⭐ <b>PIÈGE CLASSIQUE</b><br><br><b>🔴 2. LES PHÉNOMÈNES SINUSOÏDAUX ⭐ :</b><br>📖 « Ce sont les phénomènes vibratoires <b>LES PLUS SIMPLES ET LES PLUS FRÉQUENTS</b>. Ils répondent à l'équation suivante : <b>u<sub>(x,t)</sub> = A·sin(ωt)</b> » ⭐<br>• ⭐ <b>ω = la PULSATION du mouvement</b>, exprimée en <b>rad·s⁻¹</b> ⭐<br>• ⭐⭐ <b>LA RELATION :</b> la période de la fonction sinus est <b>2π</b>, donc : <b>ωT = 2π</b> → ⭐⭐ <b>ω = 2π/T = 2πν</b> ⭐⭐ <b>FORMULE À CONNAÎTRE PAR CŒUR</b><br><br><b>🔴 ⭐⭐ LA VALEUR MOYENNE DE L'ÉLONGATION (démonstration complète dans le cours) :</b><br>• ⭐ <b>SUR UNE PÉRIODE :</b> ⭐⭐ <b><b>Ū = 0</b></b> ⭐⭐ <b>LE RÉSULTAT LE PLUS TOMBABLE</b><br>• ⭐ <b>SUR UNE DEMI-PÉRIODE :</b> ⭐⭐ <b><b>Ū = 2A/π</b></b> ⭐⭐ <b>À RETENIR AUSSI</b><br><br><b>🔴 3. LA NATURE DE L'ONDE SONORE ⭐⭐ :</b><br>📖 « <b>Les ONDES SONORES sont des ondes <b>MÉCANIQUES LONGITUDINALES</b> caractérisées par des <b>FLUCTUATIONS DE DENSITÉ ET DE PRESSION</b>.</b> » ⭐⭐⭐ <b>DÉFINITION EXACTE — TOMBABLE</b><br>• ⚠️ ⭐ <b>MÉCANIQUE</b> = a besoin d'un <b>MILIEU MATÉRIEL</b> pour se propager → ⭐ <b>ELLE NE SE PROPAGE PAS DANS LE VIDE</b> ⭐⭐ <b>QUESTION CLASSIQUE</b> (contrairement aux rayons X qui sont électromagnétiques !) ⭐⭐ <b>COMPARAISON TOMBABLE</b><br>• ⚠️ ⭐ <b>LONGITUDINALE</b> = les particules du milieu « <b>sont animées d'un MOUVEMENT DE VA-ET-VIENT DANS L'AXE DE DÉPLACEMENT</b> de l'onde ultrasonore » ⭐⭐ — ⚠️ <b>Analogie du cours : un RESSORT</b> ⭐<br>• ⚠️ ⭐ <b>Zones de <b>CONDENSATION</b> (haute pression) et de <b>RARÉFACTION</b> (faible pression)</b> ⭐⭐ <b>VOCABULAIRE ANGLAIS DU COURS : Condensation / Rarefaction</b> ⭐<br><br><b>🔴 4. ⭐⭐⭐ LES 3 DOMAINES DE FRÉQUENCE (TABLEAU DU COURS — À APPRENDRE PAR CŒUR) :</b><br>📖 « L'oreille humaine perçoit les ondes sonores pour les fréquences <b>f</b> comprises entre <b>20 Hz</b> (son GRAVE) et <b>20 000 Hz</b> (son AIGU). » ⭐⭐<br><br>• ⭐ <b>INFRASONS</b> → <b>f &lt; 20 Hz</b> ⭐⭐ ⚠️ « les vibrations <b>SISMIQUES</b>, certaines <b>MACHINES</b>, des <b>HAUT-PARLEURS DE BASSES FRÉQUENCES</b>, émettent des fréquences en dessous de 20 Hz » ⭐<br>• ⭐ <b>SONS AUDIBLES</b> → <b>20 Hz &lt; f &lt; 20 kHz</b> ⭐⭐<br>• ⭐⭐ <b>ULTRASONS</b> → <b>20 kHz &lt; f &lt; 20 MHz</b> ⭐⭐⭐ <b>LE CHIFFRE LE PLUS IMPORTANT</b><br><br>⚠️ ⭐ <b>RAPPEL :</b> <b>1 kHz = 1 000 Hz</b> · <b>1 MHz = 1 000 000 Hz</b> ⭐<br>⚠️ ⭐ <b>EN MÉDECINE :</b> les ultrasons utilisés en échographie vont de <b>2 à 20 MHz</b> ⭐⭐ <b>PERTINENT</b><br><br><b>🔴 5. ⭐⭐ LA VITESSE DE PROPAGATION (TABLEAU DU COURS — les chiffres sont tombables) :</b><br><b>GAZ :</b><br>• <b>Gaz carbonique (CO₂)</b> — 0 °C — <b>259 m/s</b> ⭐<br>• <b>Oxygène (O₂)</b> — 0 °C — <b>316 m/s</b><br>• <b>Air</b> — 0 °C — <b>331 m/s</b> ⭐<br>• <b>Air</b> — 20 °C — <b>343 m/s</b> ⭐⭐ <b>LE CHIFFRE LE PLUS CLASSIQUE</b><br>• <b>Hélium (He)</b> — 0 °C — <b>965 m/s</b> ⭐ ⚠️ <b>le GAZ le plus rapide</b> (car très léger)<br><b>LIQUIDES :</b><br>• <b>Chloroforme</b> — 20 °C — <b>1004 m/s</b><br>• <b>Éthanol</b> — 20 °C — <b>1162 m/s</b><br>• <b>Mercure (Hg)</b> — 20 °C — <b>1450 m/s</b><br>• <b>EAU</b> — 20 °C — <b>1482 m/s</b> ⭐⭐ <b>LE CHIFFRE À RETENIR — référence en échographie</b><br><b>SOLIDES :</b><br>• <b>Plomb</b> — <b>1960 m/s</b> ⭐ ⚠️ <b>le SOLIDE le plus LENT</b> (métal mou et dense)<br>• <b>Cuivre</b> — <b>5010 m/s</b><br>• <b>Verre</b> — <b>5640 m/s</b><br>• <b>ACIER</b> — <b>5980 m/s</b> ⭐⭐ <b>le plus RAPIDE du tableau</b><br><br>⚠️ ⭐⭐ <b>LA LOI GÉNÉRALE (à retenir — plus important que le tableau lui-même) :</b><br>⭐ <b>v<sub>SOLIDE</sub> &gt; v<sub>LIQUIDE</sub> &gt; v<sub>GAZ</sub></b> ⭐⭐ <b>LA RÈGLE LA PLUS TOMBABLE</b><br>• ⚠️ <b>Pourquoi ?</b> Plus le milieu est <b>RIGIDE / INCOMPRESSIBLE</b>, plus la vitesse est <b>ÉLEVÉE</b> ⭐ <b>c = √(E/ρ)</b> où E = module d'élasticité et ρ = masse volumique ⭐<br>• ⚠️ ⭐ <b>Ordre de grandeur :</b> <b>air ~340 m/s</b> · <b>eau ~1500 m/s</b> · <b>os ~3000-4000 m/s</b> · <b>acier ~6000 m/s</b> ⭐<br><br><b>📋 ⭐⭐ COMPARAISON ULTRASONS vs RAYONS X (synthèse des 2 cours) :</b><br>• <b>Nature</b> : Ultrasons = ⭐ <b>onde MÉCANIQUE</b> · RX = ⭐ <b>rayonnement ÉLECTROMAGNÉTIQUE</b> ⭐⭐<br>• <b>Vide</b> : Ultrasons = ⭐ <b>NON</b> (besoin d'un milieu) · RX = ⭐ <b>OUI</b> ⭐⭐ <b>QUESTION CLASSIQUE</b><br>• <b>Direction</b> : Ultrasons = <b>LONGITUDINALE</b> · RX = <b>transverse</b> ⭐<br>• <b>Vitesse</b> : Ultrasons = <b>~1500 m/s dans les tissus</b> · RX = <b>3 × 10⁸ m/s</b> ⭐⭐<br>• <b>Ionisant</b> : Ultrasons = ⭐ <b>NON</b> (sans danger) · RX = ⭐ <b>OUI</b> (dangereux → radioprotection) ⭐⭐⭐ <b>LA DIFFÉRENCE MAJEURE</b><br>• <b>Usage dentaire</b> : Ultrasons = <b>détartrage, nettoyage canalaire, imagerie des tissus mous</b> · RX = <b>imagerie des tissus DURS (os, dents)</b> ⭐⭐ <b>ULTRA PERTINENT</b>","t":"biophysique-2026 M114 COURS-OFFICIEL"}]},{"id":"biochimie-structurale-S1-2026","nom":"🧪 Biochimie structurale","src":"Examen N2026","ordre":8,"module":"M112","desc":"AA · peptides · Hb/Mb · enzymologie","cards":[{"q":"Quels sont les <b>20 acides aminés protéinogènes</b> ? Combien sont essentiels et lesquels ?","a":"Les <b>20 acides aminés</b> qui entrent dans la composition des protéines, tous de configuration <b>L</b> (sauf la glycine qui est achirale).<br><br><b>9 ESSENTIELS</b> (l'organisme ne peut pas les synthétiser → apport alimentaire obligatoire) :<br><b>Leu, Ile, Val, Lys, Met, Phe, Thr, Trp, His</b><br>Moyen mnémotechnique : « <b>Le</b> <b>I</b>ois <b>V</b>ient, <b>L</b>a <b>M</b>ère <b>P</b>ortera <b>T</b>out <b>T</b>on <b>H</b>éritage »<br><br>⚠️ <b>Histidine</b> et <b>arginine</b> sont essentiels surtout chez l'<b>enfant</b> (semi-essentiels chez l'adulte).<br>⚠️ La <b>proline</b> et l'<b>hydroxyproline</b> sont des acides <b>IMINÉS</b> (azote secondaire cyclique), pas des amines vraies.","t":"biochimie-2026 EXAM-2026"},{"q":"Quelle est la structure générale d'un <b>acide α-aminé</b> ? Quel carbone est le Cα ?","a":"<b>H₂N – CH(R) – COOH</b><br><br>Le <b>Cα</b> est le carbone <b>immédiatement voisin du groupe carboxyle</b>. Il porte 4 substituants :<br>• un groupe <b>AMINE (–NH₂)</b><br>• un groupe <b>CARBOXYLE (–COOH)</b><br>• un atome d'<b>HYDROGÈNE</b><br>• une chaîne latérale <b>R</b> (radical, spécifique à chaque acide aminé)<br><br>⚠️ Le Cα est <b>ASYMÉTRIQUE (chiral)</b> pour 19 des 20 acides aminés — <b>SAUF LA GLYCINE</b> dont R = H (donc 2 H identiques → achirale, pas d'isomère D/L, pas d'activité optique).","t":"biochimie-2026 EXAM-2026"},{"q":"<b>PROLINE</b> — pourquoi interrompt-elle une hélice α et un feuillet β ?","a":"Parce que la proline est un acide <b>IMINÉ</b> : son azote est engagé dans un <b>cycle pyrrolidine</b> avec le Cα et la chaîne latérale.<br><br>Conséquences :<br>1. <b>Pas de NH libre</b> dans la liaison peptidique → <b>impossible de donner une liaison hydrogène</b> au squelette peptidique (le NH est le donneur indispensable).<br>2. La liaison peptidique Xaa–Pro est très <b>RIGIDE</b> → pas de rotation libre.<br>3. Enchaînement géométriquement <b>incompatible</b> avec la répétition de l'hélice α (3,6 résidus/tour) et du feuillet β.<br><br>→ La proline est un <b>« casseur » (breaker) de structure secondaire</b>. On la trouve dans les <b>coudes (β-turns)</b> et dans le <b>collagène</b> (triple hélice, où elle est abondante sous forme d'<b>hydroxyproline</b>).","t":"biochimie-2026 EXAM-2026"},{"q":"Qu'est-ce qu'un <b>pont disulfure</b> ? Entre quels acides aminés ? Quel rôle structural ?","a":"Liaison <b>COVALENTE</b> de type <b>–S–S–</b> entre les groupes <b>THIOL (–SH)</b> de <b>DEUX CYSTÉINES</b>.<br><br>• Formation = <b>OXYDATION</b> : 2 Cys–SH → Cys–S–S–Cys + 2H⁺ + 2e⁻<br>• Rupture = <b>RÉDUCTION</b> (par le β-mercaptoéthanol, le DTT, ou le glutathion réduit)<br>• Se forme dans le <b>réticulum endoplasmique</b> (milieu oxydant), catalysée par la <b>PDI (protéine disulfure isomérase)</b><br><br><b>Rôle</b> : <b>stabilise la structure TERTIAIRE</b> (ponts intrachaîne) et la structure <b>QUATERNAIRE</b> (ponts interchaînes).<br><br>Ex. : les <b>immunoglobulines</b> (chaînes H et L reliées par des ponts S–S), l'<b>insuline</b> (3 ponts : 2 interchaînes A-B, 1 intrachaîne A), la <b>kératine</b> (riche en cystéine → rigidité des cheveux ; la permanente = rupture puis reformation des ponts S–S).<br><br>⚠️ La <b>méthionine</b> contient aussi du soufre mais <b>NE forme PAS</b> de pont disulfure (soufre thioéther, non oxydable en –S–S–).","t":"biochimie-2026 EXAM-2026"},{"q":"Quelle amine biogène dérive de l'<b>HISTIDINE</b> ? Par quelle réaction ?","a":"<b>L'HISTAMINE</b>, par <b>DÉCARBOXYLATION</b> (perte du COOH) catalysée par l'<b>histidine décarboxylase</b> (coenzyme : <b>PLP</b> = phosphate de pyridoxal = vitamine B6).<br><br>Histidine → Histamine + CO₂<br><br><b>Rôle de l'histamine</b> :<br>• <b>Vasodilatation</b> + ↑ perméabilité capillaire → œdème, rougeur<br>• <b>Contraction des muscles lisses bronchiques</b> → bronchoconstriction<br>• <b>Stimule la sécrétion gastrique de HCl</b> (récepteurs H2 des cellules pariétales)<br>• Neurotransmetteur / neuromodulateur<br>• Libérée par la <b>dégranulation des mastocytes</b> et des basophiles → <b>RÉACTION ALLERGIQUE / ANAPHYLAXIE</b><br><br>⚠️ Les <b>antihistaminiques H1</b> traitent l'allergie ; les <b>anti-H2</b> (ranitidine, oméprazole en amont) réduisent l'acidité gastrique.","t":"biochimie-2026 EXAM-2026"},{"q":"Donne les autres <b>amines biogènes</b> dérivées d'acides aminés (décarboxylation).","a":"• <b>HISTIDINE → HISTAMINE</b> (allergie, sécrétion gastrique)<br>• <b>ORNITHINE → PUTRESCINE</b> (polyamines)<br>• <b>LYSINE → CADAVERINE</b><br>• <b>TYROSINE → TYRAMINE</b> → puis <b>DOPA → DOPAMINE → NORADRÉNALINE → ADRÉNALINE</b> (catécholamines)<br>• <b>TRYPTOPHANE → TRYPTAMINE / SÉROTONINE (5-HT)</b> → puis <b>MÉLATONINE</b><br>• <b>GLUTAMATE → GABA</b> (acide γ-aminobutyrique), principal neurotransmetteur <b>inhibiteur</b> du SNC<br>• <b>ARGININE → NO (monoxyde d'azote)</b> via la NO-synthase → vasodilatation<br><br>⚠️ Toutes ces réactions sont des <b>DÉCARBOXYLATIONS</b> dépendantes du <b>PLP (vitamine B6)</b>.","t":"biochimie-2026 EXAM-2026"},{"q":"Sur quel(s) groupe(s) fonctionnel(s) d'un acide aminé se fait une <b>PHOSPHORYLATION</b> ?","a":"Sur les groupes <b>HYDROXYLE (–OH)</b> :<br>• <b>SÉRINE</b> (Ser, –CH₂–OH) — la plus fréquente (~86 % des phosphoprotéines)<br>• <b>THRÉONINE</b> (Thr, –CH(CH₃)–OH)<br>• <b>TYROSINE</b> (Tyr, –CH₂–C₆H₄–OH) — plus rare mais cruciale en <b>signalisation cellulaire</b><br><br><b>Réaction</b> : transféré d'un <b>ATP</b> par une <b>KINASE</b> (protéine kinase) :<br>Protéine–OH + ATP → Protéine–O–PO₃²⁻ + ADP<br><b>Réverse</b> par une <b>PHOSPHATASE</b> (hydrolyse).<br><br><b>Effet</b> : ajoute une charge <b>négative ×2</b> → modifie la conformation et l'activité de la protéine (activation ou inhibition).<br><br>⚠️ Piège QCM : <b>–OH n'appartient pas à la fonction amine ni au carboxyle</b> — la phosphorylation se fait sur la <b>chaîne latérale</b>, pas sur le squelette.<br>⚠️ Autres modifications : <b>N-glycosylation</b> sur l'azote de l'<b>asparagine (Asn)</b> ; <b>O-glycosylation</b> sur l'–OH de <b>Ser/Thr</b> ; <b>acétylation</b> sur la <b>lysine</b>.","t":"biochimie-2026 EXAM-2026"},{"q":"Définis la <b>liaison peptidique</b>. Pourquoi est-elle dite <b>PLANE</b> et <b>RIGIDE</b> ?","a":"Liaison <b>COVALENTE AMIDE</b> (–CO–NH–) formée entre le <b>COOH</b> d'un acide aminé et le <b>NH₂</b> du suivant, avec <b>élimination d'une molécule d'EAU</b> (condensation).<br><br><b>POURQUOI PLANE :</b><br>La liaison peptidique présente un caractère de <b>DOUBLE LIAISON PARTIELLE (~40 %)</b> par <b>RÉSONANCE (mésomérie)</b> : le doublet libre de l'<b>azote</b> se délocalise sur le carbonyle.<br><br>Deux formes en équilibre :<br>• <b>–C(=O)–NH–</b> (forme neutre)<br>• <b>–C(–O⁻)=N⁺H–</b> (forme zwittérionique)<br><br>Conséquences :<br>1. <b>Pas de rotation libre</b> autour de la liaison C–N → elle est <b>RIGIDE et PLANAIRE</b> (les 6 atomes Cα–C(=O)–N–H–Cα sont dans un même plan)<br>2. Longueur C–N = <b>1,32 Å</b> (plus courte qu'une C–N simple à 1,49 Å, plus longue qu'une C=N à 1,27 Å)<br>3. Configuration quasi toujours <b>TRANS</b> (les deux Cα de part et d'autre, pour minimiser l'encombrement stérique). ⚠️ Exception : la liaison <b>Xaa–PROLINE</b> peut être <b>cis</b> (~10 % des cas).<br><br><b>La flexibilité du squelette</b> ne vient que des rotations autour des liaisons <b>N–Cα (angle φ, phi)</b> et <b>Cα–C (angle ψ, psi)</b>.","t":"biochimie-2026 EXAM-2026"},{"q":"Quelles sont les <b>4 structures</b> d'une protéine ? Définis chacune.","a":"<b>1. STRUCTURE PRIMAIRE</b> : la <b>SÉQUENCE LINÉAIRE</b> des acides aminés, reliés par les <b>liaisons peptidiques COVALENTES</b>. Sens de lecture : <b>N-terminal → C-terminal</b>. Déterminée <b>génétiquement</b>. Une seule modification peut être pathologique (ex. : drépanocytose).<br><br><b>2. STRUCTURE SECONDAIRE</b> : l'<b>arrangement LOCAL</b> du squelette, stabilisé par des <b>LIAISONS HYDROGÈNE entre les C=O et N–H du squelette peptidique</b> (pas les chaînes latérales !).<br>• <b>Hélice α</b> : droite, 3,6 résidus/tour, pas de 5,4 Å, liaisons H entre le C=O du résidu <b>i</b> et le NH du résidu <b>i+4</b>, chaînes latérales vers l'extérieur<br>• <b>Feuillet β</b> : brins <b>parallèles</b> ou <b>antiparallèles</b>, liaisons H inter-brins, chaînes latérales alternées au-dessus/en-dessous<br>• <b>Coude β (β-turn)</b> : 4 résidus, permet le changement de direction ; riche en <b>proline</b> et <b>glycine</b><br><br><b>3. STRUCTURE TERTIAIRE</b> : le <b>REPLIEMENT TRIDIMENSIONNEL GLOBAL</b> d'une chaîne, stabilisé par des interactions entre les <b>CHAÎNES LATÉRALES (R)</b> : liaisons hydrogène, interactions <b>ioniques</b> (ponts salins), <b>hydrophobes</b> (moteur principal du repliement), <b>Van der Waals</b>, et <b>PONTS DISULFURE covalents</b>. Définit la <b>FONCTION</b>.<br><br><b>4. STRUCTURE QUATERNAIRE</b> : l'<b>ASSEMBLAGE de plusieurs sous-unités (protomères)</b> en un complexe fonctionnel. Interactions <b>NON covalentes</b> (+ parfois ponts S–S). Ex. : hémoglobine = <b>α₂β₂</b>. N'existe que pour les protéines <b>oligomériques</b>.","t":"biochimie-2026 EXAM-2026"},{"q":"Quelles interactions stabilisent la <b>structure TERTIAIRE</b> ? Laquelle est la plus importante ?","a":"• <b>INTERACTIONS HYDROPHOBES</b> — <b>LE MOTEUR PRINCIPAL DU REPLIEMENT</b> ✅<br>&nbsp;&nbsp;Les résidus <b>apolaires</b> (Val, Leu, Ile, Phe, Met, Trp) se regroupent à l'<b>INTÉRIEUR</b> de la protéine pour fuir l'eau ; les résidus <b>polaires/chargés</b> restent en <b>surface</b>. C'est un effet <b>entropique</b> (libération des molécules d'eau ordonnées).<br>• <b>LIAISONS HYDROGÈNE</b> entre chaînes latérales polaires (Ser, Thr, Asn, Gln, Tyr) et avec l'eau de surface<br>• <b>INTERACTIONS IONIQUES (ponts salins)</b> entre groupes chargés de signe opposé : <b>Asp⁻ / Glu⁻</b> avec <b>Lys⁺ / Arg⁺ / His⁺</b><br>• <b>FORCES DE VAN DER WAALS</b> — faibles individuellement mais nombreuses<br>• <b>PONTS DISULFURE (–S–S–)</b> entre cystéines — <b>SEULES LIAISONS COVALENTES</b>, les plus fortes ; formés dans le <b>RE</b><br><br>⚠️ Les liaisons peptidiques sont <b>covalentes</b> mais appartiennent à la structure <b>primaire</b>, elles ne stabilisent pas le repliement tertiaire.","t":"biochimie-2026 EXAM-2026"},{"q":"Qu'est-ce que la <b>DÉNATURATION</b> d'une protéine ? Est-elle réversible ?","a":"<b>DÉNATURATION</b> = perte des structures <b>SECONDAIRE, TERTIAIRE et QUATERNAIRE</b> (dépliement), <b>SANS RUPTURE des liaisons peptidiques</b>.<br><br>⚠️ Point clé des QCM : la <b>STRUCTURE PRIMAIRE EST CONSERVÉE</b>. Il n'y a pas d'<b>hydrolyse</b>.<br><br><b>Conséquence</b> : perte de la <b>FONCTION BIOLOGIQUE</b> (activité enzymatique, reconnaissance) et souvent de la <b>solubilité</b> (précipitation, coagulation — ex. : blanc d'œuf à la cuisson).<br><br><b>AGENTS DÉNATURANTS :</b><br>• <b>CHALEUR</b> (&gt; 60 °C) — agite les molécules, rompt les liaisons faibles<br>• <b>pH extrême</b> — modifie l'ionisation des chaînes latérales, rompt les ponts salins<br>• <b>Solvants organiques, urée 8 M, guanidine 6 M</b> — rompent les liaisons H et les interactions hydrophobes<br>• <b>Détergents (SDS)</b> — rompent les interactions hydrophobes et chargent la protéine négativement<br>• <b>Agents réducteurs (β-mercaptoéthanol, DTT)</b> — rompent les <b>ponts disulfure</b><br>• <b>Sels lourds (Hg²⁺, Pb²⁺, Ag⁺)</b> — précipitent<br><br><b>RÉVERSIBILITÉ</b> : <b>OUI en principe (renaturation)</b> si la protéine est petite et que l'agent est retiré — démonstration célèbre d'<b>ANFINSEN</b> sur la <b>ribonucléase A</b> (urée + β-mercaptoéthanol retirés → activité retrouvée à 100 %).<br>⚠️ En pratique, pour les <b>grosses protéines</b>, la dénaturation est souvent <b>IRRÉVERSIBLE</b> (agrégation) et nécessite des <b>chaperonnes</b> in vivo.<br><br>⚠️ <b>La dénaturation N'EST PAS une précipitation</b> : une protéine peut être dénaturée et rester soluble.","t":"biochimie-2026 EXAM-2026"},{"q":"Combien d'atomes de <b>fer</b> contient l'<b>hémoglobine</b> ? Sous quelle forme d'oxydation ?","a":"<b>QUATRE (4) atomes de fer</b>, un par groupe <b>hème</b> — donc un par sous-unité globinique.<br><br>⚠️ <b>FORME FONCTIONNELLE : Fe²⁺ (FERREUX, fer réduit)</b> ✅<br><br>C'est la seule forme capable de fixer l'<b>O₂</b> de façon <b>réversible</b>.<br><br>Si le fer s'oxyde en <b>Fe³⁺ (ferrique)</b> → <b>MÉTHÉMOGLOBINE</b> → <b>incapable de transporter l'O₂</b> → méthémoglobinémie (cyanose). Le <b>nitrite</b> et certains médicaments oxydent le fer.<br>La <b>méthémoglobine réductase (NADH-cytochrome b5 réductase)</b> maintient normalement le Fe²⁺.<br><br>⚠️ La <b>myoglobine</b> contient <b>UN SEUL</b> atome de fer (1 hème, 1 chaîne).","t":"biochimie-2026 EXAM-2026"},{"q":"Compare l'<b>HÉMOGLOBINE (Hb)</b> et la <b>MYOGLOBINE (Mb)</b> : structure, courbe de saturation, rôle.","a":"<b>MYOGLOBINE (Mb)</b> :<br>• <b>1 seule chaîne polypeptidique</b> + <b>1 hème</b> (PM ≈ 17 kDa)<br>• Structure uniquement <b>tertiaire</b>, <b>PAS de structure quaternaire</b><br>• Localisation : <b>MUSCLE strié squelettique et cardiaque</b><br>• Courbe de saturation : <b>HYPERBOLIQUE</b> (pas de coopérativité)<br>• Affinité pour l'O₂ <b>TRÈS ÉLEVÉE</b> (P₅₀ ≈ 1–3 mmHg)<br>• Rôle : <b>STOCKAGE / RÉSERVE</b> d'O₂ dans le muscle, le libère quand la pO₂ chute à l'effort<br>• N'est <b>PAS</b> sensible au 2,3-DPG<br><br><b>HÉMOGLOBINE (Hb)</b> :<br>• <b>TÉTRAMÈRE α₂β₂</b> (4 chaînes) + <b>4 hèmes</b> (PM ≈ 64,5 kDa)<br>• Structure <b>quaternaire</b> présente<br>• Localisation : <b>ÉRYTHROCYTES (globules rouges)</b><br>• Courbe de saturation : <b>SIGMOÏDE (en S)</b> — à cause de la <b>COOPÉRATIVITÉ</b><br>• Affinité <b>plus faible</b> (P₅₀ ≈ 26–27 mmHg)<br>• Rôle : <b>TRANSPORT</b> de l'O₂ des poumons vers les tissus<br>• Sensible au <b>2,3-DPG</b>, au <b>pH</b> et au <b>CO₂</b> (effet Bohr)<br><br>⚠️ <b>La courbe SIGMOÏDE de l'Hb est la conséquence directe de la coopérativité</b> : la fixation du 1er O₂ sur une sous-unité facilite la fixation des suivants.","t":"biochimie-2026 EXAM-2026"},{"q":"Quelles sont les formes <b>R (relâchée)</b> et <b>T (tendue)</b> de l'hémoglobine ?","a":"<b>FORME T (TENSE / TENDUE)</b> = état <b>DÉSOXYGÉNÉ</b> :<br>• <b>FAIBLE affinité</b> pour l'O₂<br>• Stabilisée par des <b>ponts salins inter-sous-unités</b> et par le <b>2,3-DPG</b> (fixé dans la cavité centrale entre les chaînes β)<br>• Prédomine dans les <b>TISSUS</b> (pO₂ basse, pH acide, CO₂ élevé) → <b>libère l'O₂</b><br><br><b>FORME R (RELAXED / RELÂCHÉE)</b> = état <b>OXYGÉNÉ</b> :<br>• <b>FORTE affinité</b> pour l'O₂<br>• Ponts salins rompus, cavité centrale resserrée → le DPG est expulsé<br>• Prédomine dans les <b>POUMONS</b> (pO₂ élevée, pH alcalin, CO₂ bas) → <b>capte l'O₂</b><br><br><b>MÉCANISME de la transition T → R (modèle MWC, symétrique)</b> :<br>La fixation de l'O₂ sur un hème <b>déplace le fer Fe²⁺ dans le plan de la porphyrine</b> → cela tire sur l'<b>histidine proximale (His F8)</b> → déplacement de l'<b>hélice F</b> → rupture des ponts salins → <b>toute la molécule bascule en forme R</b>.<br><br>⚠️ C'est le <b>modèle ALLOSTÉRIQUE de MONOD-WYMAN-CHANGEUX</b> : la protéine est un <b>tétramère symétrique</b> qui existe en équilibre T ⇌ R, et l'O₂ déplace l'équilibre vers R.","t":"biochimie-2026 EXAM-2026"},{"q":"Qu'est-ce que le <b>2,3-DPG (2,3-diphosphoglycérate)</b> ? Quel est son effet sur l'hémoglobine ?","a":"C'est un petit anion organique, produit par une <b>dérivation de la glycolyse</b> (voie de Rapoport-Luebering) dans l'<b>érythrocyte</b>.<br><br><b>EFFET : il DIMINUE l'affinité de l'Hb pour l'O₂</b> → <b>déplace la courbe de saturation VERS LA DROITE</b> → <b>facilite la LIBÉRATION de l'O₂ dans les tissus</b>.<br><br><b>Mécanisme</b> : le 2,3-DPG, très <b>négatif</b>, se fixe dans la <b>cavité centrale</b> du tétramère, entre les <b>DEUX chaînes β</b>, en formant des <b>ponts salins</b> avec les résidus chargés positivement (Val1, His2, Lys82 des deux β, et His143). Cette cavité n'existe que dans la <b>forme T</b> → le DPG <b>stabilise l'état T (désoxy)</b>.<br><br>⚠️ L'<b>Hb FŒTALE (α₂γ₂)</b> possède des chaînes <b>γ</b> au lieu des β ; l'His143 y est remplacée par une <b>sérine</b> neutre → le DPG se fixe <b>moins bien</b> → <b>l'HbF a une affinité PLUS ÉLEVÉE pour l'O₂</b> → permet les échanges O₂ mère-fœtus à travers le placenta.<br><br><b>Variations physiologiques du DPG :</b><br>• ↑ en <b>ALTITUDE</b> (hypoxie chronique, adaptation en quelques jours)<br>• ↑ dans l'<b>anémie chronique</b><br>• ↓ dans le sang <b>conservé en banque</b> (&lt; 24 h → l'Hb ne libère plus l'O₂, d'où la nécessité de sang « frais » pour les transfusions massives)","t":"biochimie-2026 EXAM-2026"},{"q":"Quels facteurs déplacent la courbe de saturation de l'hémoglobine <b>vers la DROITE</b> ? Vers la <b>GAUCHE</b> ?","a":"<b>VERS LA DROITE</b> = <b>affinité ↓</b> = <b>LIBÉRATION facilitée de l'O₂</b> (conditions des <b>TISSUS actifs</b>) :<br>• <b>pH ↓ (acidose)</b> → <b>EFFET BOHR</b><br>• <b>pCO₂ ↑</b> (le CO₂ se fixe sur les NH₂ terminaux → carbamates → stabilise la forme T)<br>• <b>Température ↑</b><br>• <b>2,3-DPG ↑</b><br>• <b>P₅₀ ↑</b><br><br><b>VERS LA GAUCHE</b> = <b>affinité ↑</b> = <b>CAPTION facilitée de l'O₂</b> (conditions des <b>POUMONS</b>) :<br>• <b>pH ↑ (alcalose)</b><br>• <b>pCO₂ ↓</b><br>• <b>Température ↓</b><br>• <b>2,3-DPG ↓</b><br>• <b>Hb fœtale (α₂γ₂)</b><br>• <b>P₅₀ ↓</b><br>• ⚠️ <b>CO (monoxyde de carbone)</b> : affinité <b>200–250× supérieure</b> à celle de l'O₂ → carboxyhémoglobine → courbe très déplacée à gauche + blocage des sites → hypoxie tissulaire sévère<br><br><b>EFFET BOHR</b> : l'<b>↓ du pH</b> (dû à l'acide lactique et au CO₂/H⁺ des tissus actifs) <b>diminue</b> l'affinité de l'Hb pour l'O₂ → l'O₂ est libéré là où le métabolisme est intense.<br><b>EFFET HALDANE</b> (inverse) : la <b>désoxygénation</b> de l'Hb <b>augmente</b> son affinité pour le CO₂ et les H⁺ → facilite le transport du CO₂ des tissus vers les poumons.<br><br>Moyen mnémotechnique : « <b>la droite, c'est le travail</b> » (chaud, acide, CO₂, DPG → on libère l'O₂).","t":"biochimie-2026 EXAM-2026"},{"q":"Qu'est-ce que la <b>DRÉPANOCYTOSE (anémie falciforme)</b> ? Quelle mutation la provoque ?","a":"<b>MALADIE GÉNÉTIQUE</b> — hémoglobinopathie la plus fréquente dans le monde.<br><br><b>MUTATION :</b> substitution d'<b>UN SEUL acide aminé sur la chaîne BÊTA (β)</b> de l'hémoglobine :<br><b>HbA (normale) : …Glu⁶–Val⁷…</b> → <b>HbS (drépanocytaire) : …Glu⁶–<span style=\"color:#c00\">Val</span>⁷…</b><br><br>Soit : remplacement de l'<b>ACIDE GLUTAMIQUE (Glu, polaire, chargé négativement, hydrophile)</b> en position <b>6</b> de la chaîne <b>β</b> par la <b>VALINE (Val, apolaire, hydrophobe)</b>.<br><br>Au niveau de l'ADN : mutation ponctuelle <b>GAG → GTG</b> sur le codon 6 du gène <b>HBB</b> (chromosome <b>11</b>).<br><br><b>MÉCANISME :</b> la <b>valine hydrophobe</b> crée un <b>site « collant »</b> à la surface de l'HbS <b>désoxygénée</b>. Elle s'insère dans une poche hydrophobe (Phe85, Leu88) d'une autre molécule d'HbS → <b>POLYMÉRISATION</b> en longues fibres rigides → le globule rouge se déforme en <b>FAUCILLE (croissant)</b> → <b>drépanocyte</b>.<br><br><b>CONSÉQUENCES :</b><br>• <b>Hémolyse chronique</b> → anémie (durée de vie du GR : 10–20 jours au lieu de 120)<br>• <b>Obstruction des capillaires</b> → crises vaso-occlusives douloureuses, infarctus (rate, os, poumon, cerveau)<br>• <b>Asplénie fonctionnelle</b> (auto-splenectomie) → risque infectieux<br><br><b>TRANSMISSION AUTOSOMIQUE RÉCESSIVE :</b><br>• <b>AA</b> = sain<br>• <b>AS</b> = <b>porteur / trait drépanocytaire</b> → généralement asymptomatique, <b>protégé contre le paludisme</b> (avantage sélectif en zone d'endémie)<br>• <b>SS</b> = <b>malade</b><br><br>⚠️ Il existe aussi l'<b>HbC</b> (Glu6→<b>Lys</b> sur la chaîne β) et l'<b>HbE</b>. ⚠️ Ce n'est <b>PAS</b> la chaîne α qui est touchée.","t":"biochimie-2026 EXAM-2026"},{"q":"Qu'est-ce que le <b>Km (constante de Michaelis)</b> ? Que mesure-t-il ?","a":"<b>Km = concentration de substrat pour laquelle la vitesse initiale est égale à la MOITIÉ de Vmax</b> (v = Vmax/2).<br><br>Unité : une <b>CONCENTRATION</b> (mol/L ou M).<br><br><b>CE QU'IL MESURE : l'AFFINITÉ de l'enzyme pour son substrat, DE FAÇON INVERSE.</b><br>• <b>Km FAIBLE</b> → <b>affinité ÉLEVÉE</b> (l'enzyme atteint Vmax/2 avec peu de substrat)<br>• <b>Km ÉLEVÉ</b> → <b>affinité FAIBLE</b><br><br><b>PROPRIÉTÉS :</b><br>• Km est une <b>CONSTANTE CARACTÉRISTIQUE</b> du couple enzyme–substrat, dans des conditions données<br>• Km <b>NE DÉPEND PAS</b> de la concentration en enzyme ⚠️ (piège QCM classique)<br>• Km <b>DÉPEND</b> du pH, de la température, de la force ionique et de la présence d'inhibiteurs<br>• Une même enzyme peut avoir des <b>Km différents</b> pour des substrats différents<br><br><b>ÉQUATION DE MICHAELIS-MENTEN :</b><br><b>v₀ = (Vmax × [S]) / (Km + [S])</b><br><br>• Si [S] &lt;&lt; Km → v₀ ≈ (Vmax/Km)[S] : cinétique d'<b>ordre 1</b> (v proportionnelle à [S])<br>• Si [S] = Km → v₀ = Vmax/2<br>• Si [S] &gt;&gt; Km → v₀ ≈ Vmax : <b>ordre 0</b>, l'enzyme est <b>SATURÉE</b><br><br>Avec <b>Vmax = kcat × [E]total</b> et <b>kcat = nombre de renouvellement (turnover)</b> = nombre de molécules de substrat converties par site actif et par seconde.","t":"biochimie-2026 EXAM-2026"},{"q":"Que représente la <b>représentation de LINEWEAVER-BURK</b> (doubles inverses) ? Comment lire Km et Vmax dessus ?","a":"C'est la <b>linéarisation</b> de l'équation de Michaelis-Menten.<br><br><b>Équation :</b><br><b>1/v₀ = (Km/Vmax) × (1/[S]) + 1/Vmax</b><br><br>Forme <b>y = ax + b</b> avec :<br>• <b>y = 1/v₀</b><br>• <b>x = 1/[S]</b><br>• <b>pente a = Km/Vmax</b><br>• <b>ordonnée à l'origine b = 1/Vmax</b><br>• <b>abscisse à l'origine (intersection avec l'axe des x) = −1/Km</b><br><br><b>LECTURE :</b><br>• <b>Vmax = 1 / b</b> (l'inverse de l'ordonnée à l'origine)<br>• <b>Km = −1 / (abscisse à l'origine)</b> = <b>pente × Vmax</b><br><br><b>UTILITÉ :</b> identifier graphiquement le <b>TYPE D'INHIBITION</b> en comparant les droites avec et sans inhibiteur.<br><br>⚠️ <b>Limites</b> : elle <b>amplifie les erreurs expérimentales</b> aux faibles [S] (1/[S] devient très grand). Autres linéarisations : <b>Eadie-Hofstee</b> (v/[S] vs v), <b>Hanes-Woolf</b> ([S]/v vs [S]).","t":"biochimie-2026 EXAM-2026"},{"q":"Quel est l'effet de chaque type d'<b>inhibiteur enzymatique</b> sur Km et Vmax, en Lineweaver-Burk ?","a":"<b>1. INHIBITION COMPÉTITIVE</b><br>• L'inhibiteur ressemble au substrat → il se fixe sur le <b>SITE ACTIF</b><br>• <b>RÉVERSIBLE</b> par ↑ de [S] (compétition)<br>• <b>Km ↑ (apparent)</b> — il faut plus de substrat pour atteindre Vmax/2<br>• <b>Vmax INCHANGÉE</b> ✅<br>• Lineweaver-Burk : droites qui se <b>CROISENT SUR L'AXE DES ORDONNÉES (1/Vmax)</b> — même b, pente différente<br>• Ex. : <b>statines</b> (compétitives de l'HMG-CoA réductase), <b>méthotrexate</b> (compétitif de la dihydrofolate réductase), <b>malonate</b> (compétitif de la succinate déshydrogénase)<br><br><b>2. INHIBITION NON COMPÉTITIVE</b><br>• L'inhibiteur se fixe sur un <b>SITE ALLOSTÉRIQUE</b> différent, sur <b>E</b> et sur <b>ES</b> avec la même affinité<br>• <b>PAS réversible</b> par ↑ de [S]<br>• <b>Km INCHANGÉ</b> ✅ (l'affinité pour S n'est pas modifiée)<br>• <b>Vmax ↓</b><br>• Lineweaver-Burk : droites qui se <b>CROISENT SUR L'AXE DES ABSCISSES (−1/Km)</b><br>• Ex. : ions lourds (Pb²⁺, Hg²⁺)<br><br><b>3. INHIBITION INCOMPÉTITIVE (anti-compétitive)</b><br>• L'inhibiteur ne se fixe que sur le <b>COMPLEXE ES</b> (jamais sur E libre)<br>• <b>Km ↓</b> ET <b>Vmax ↓</b> (les deux diminuent dans le même rapport)<br>• Lineweaver-Burk : droites <b>PARALLÈLES</b> (même pente Km/Vmax)<br>• Typique des réactions à <b>deux substrats</b><br><br><b>4. INHIBITION MIXTE (non compétitive partielle)</b><br>• Fixation sur E et ES avec des affinités <b>différentes</b><br>• Km ↑ ou ↓, Vmax ↓<br>• Droites qui se croisent <b>ni sur l'axe des x ni sur l'axe des y</b> (dans le 2ᵉ quadrant)<br><br><b>5. INHIBITION IRRÉVERSIBLE</b><br>• Liaison <b>COVALENTE</b> avec l'enzyme → inactivation <b>définitive</b><br>• Pas de Km/Vmax au sens classique (la quantité d'enzyme active diminue)<br>• Ex. : <b>ASPIRINE</b>, <b>DFP/DIPE</b> (insecticides organophosphorés, gaz neurotoxiques), <b>pénicilline</b><br><br>Moyen mnémotechnique : « <b>Compétitif → Km seul change · Non compétitif → Vmax seule change · Incompétitif → les deux · Parallèles = incompétitif</b> ».","t":"biochimie-2026 EXAM-2026"},{"q":"Comment agit l'<b>ASPIRINE (acide acétylsalicylique)</b> sur son enzyme cible ? Pourquoi est-ce une inhibition irréversible ?","a":"L'aspirine est un <b>INHIBITEUR IRRÉVERSIBLE (suicide-like) de la CYCLOOXYGÉNASE (COX-1 et COX-2)</b>.<br><br><b>Mécanisme :</b> l'aspirine <b>ACÉTYLE de façon COVALENTE</b> un résidu <b>SÉRINE</b> du site actif de la COX (<b>Ser530</b> pour COX-1, <b>Ser516</b> pour COX-2). Le groupe <b>acétyle (CH₃–CO–)</b> est transféré sur l'<b>–OH</b> de la sérine (réaction d'<b>estérification</b>) avec libération d'acide salicylique.<br><br>→ La sérine acétylée ne peut plus agir → <b>l'enzyme est définitivement inactivée</b>.<br><br>⚠️ <b>Pourquoi « irréversible »</b> : la liaison est <b>COVALENTE</b>, et l'<b>acétylation ne peut pas être annulée</b> par une phosphatase. Il faut <b>synthétiser de nouvelles molécules d'enzyme</b> pour restaurer l'activité.<br><br>⚠️ <b>Conséquence clinique majeure</b> : les <b>PLAQUETTES (thrombocytes) sont ANUCLÉÉES</b> → elles <b>ne peuvent PAS synthétiser de nouvelles protéines</b> → l'inhibition dure <b>toute leur vie (7 à 10 jours)</b>. D'où l'effet <b>ANTIAGRÉGANT PLAQUETTAIRE</b> prolongé de l'aspirine à faible dose (75–100 mg/j) en prévention cardiovasculaire.<br>Les cellules endothéliales, elles, <b>peuvent</b> resynthétiser la COX → la production de <b>prostacycline (PGI₂)</b> est restaurée.<br><br><b>Effets de l'inhibition des COX :</b> ↓ synthèse des <b>PROSTAGLANDINES</b> et du <b>THROMBOXANE A₂</b> →<br>• <b>Antalgique</b> (antidouleur)<br>• <b>Antipyrétique</b> (↓ la fièvre : ↓ PGE₂ dans l'hypothalamus)<br>• <b>Anti-inflammatoire</b> (à dose élevée)<br>• <b>Antiagrégant plaquettaire</b> (↓ TXA₂)<br>• ⚠️ Effet indésirable : ↓ PGE₂ gastroprotectrices → <b>ulcère gastrique</b><br><br>Les <b>AINS classiques</b> (ibuprofène, diclofénac) sont, eux, des inhibiteurs <b>RÉVERSIBLES COMPÉTITIFS</b> de la COX.","t":"biochimie-2026 EXAM-2026"},{"q":"Quel est le rôle du <b>NAD⁺ / NADH</b> et du <b>NADP⁺ / NADPH</b> ? Comment fonctionnent-ils ?","a":"Ce sont des <b>COENZYMES D'OXYDORÉDUCTION</b> dérivés de la <b>vitamine B3 (niacine / acide nicotinique / nicotinamide)</b>.<br><br><b>MÉCANISME :</b> ils transportent des <b>HYDRURES (H⁻ = 2 électrons + 1 proton)</b>. La partie active est le cycle <b>nicotinamide</b> :<br><b>NAD⁺ + 2e⁻ + 2H⁺ → NADH + H⁺</b><br>(ou écrit : <b>NAD⁺ + 2H → NADH + H⁺</b>)<br><br>Le NAD⁺ <b>accepte</b> 2 électrons et 1 proton sur l'azote du cycle (qui devient <b>non aromatique</b>, charge + déplacée) ; le 2ᵉ proton est <b>libéré dans le milieu</b>.<br><br><b>NAD⁺ / NADH — CATABOLISME (oxydations, production d'énergie)</b><br>• <b>NAD⁺ = forme OXYDÉE</b> → utilisée dans les <b>réactions CATABOLIQUES</b> (glycolyse, β-oxydation, cycle de Krebs, chaîne respiratoire)<br>• <b>NADH = forme RÉDUITE</b> → transporte les électrons vers la <b>chaîne respiratoire mitochondriale</b> pour produire de l'<b>ATP</b><br>• Ratio cellulaire : <b>NAD⁺/NADH élevé</b> (~1000 dans le cytosol) → le pool est maintenu <b>oxydé</b> pour favoriser le catabolisme<br>• Enzymes : <b>déshydrogénases</b> (glycéraldéhyde-3-P déshydrogénase, pyruvate DH, isocitrate DH, α-cétoglutarate DH, malate DH, lactate DH)<br><br><b>NADP⁺ / NADPH — ANABOLISME (biosynthèses réductrices, antioxydant)</b><br>• Différence structurale : un <b>groupe PHOSPHATE</b> supplémentaire sur le ribose de l'adénosine (position 2′)<br>• <b>NADPH = forme RÉDUITE</b> → utilisée dans les <b>BIOSYNTHÈSES RÉDUCTRICES</b> : synthèse des <b>acides gras</b>, du <b>cholestérol</b>, des <b>stéroïdes</b>, des <b>nucléotides</b><br>• <b>NADPH = pouvoir réducteur ANTIOXYDANT</b> : régénère le <b>glutathion réduit (GSH)</b> via la glutathion réductase → protège contre les <b>radicaux libres / stress oxydatif</b><br>• Produit surtout par la <b>VOIE DES PENTOSES PHOSPHATES</b> (glucose-6-P déshydrogénase et 6-phosphogluconate déshydrogénase)<br>• Ratio cellulaire : <b>NADPH/NADP⁺ élevé</b> (~100) → le pool est maintenu <b>réduit</b><br>• ⚠️ Enzymes clés : <b>G6PD</b> (son déficit = <b>favisme</b>, anémie hémolytique), <b>cytochrome P450</b> (NADPH-cytochrome P450 réductase), <b>NO-synthase</b>, <b>NADPH oxydase</b> des phagocytes (burst oxydatif)<br><br>Moyen mnémotechnique : <b>NAD = « D » pour Dégradation (catabolisme)</b> ; <b>NADP = « P » pour Production/Photosynthèse (anabolisme)</b>.","t":"biochimie-2026 EXAM-2026"},{"q":"Quel est le rôle du <b>Coenzyme A (CoA-SH)</b> et de l'<b>acétyl-CoA</b> ?","a":"<b>COENZYME A (CoA)</b> : coenzyme de <b>TRANSFERT DE GROUPES ACYLE</b> (à 2 carbones et plus).<br><br><b>Dérivé de la VITAMINE B5 (acide pantothénique)</b>, il contient aussi un <b>ADP</b> et une <b>cystéamine</b>. Sa partie <b>ACTIVE</b> est le groupe <b>THIOL terminal (–SH)</b> de la cystéamine → on écrit <b>CoA-SH</b>.<br><br><b>LIAISON THIOESTER :</b> l'acyle se fixe par une liaison <b>THIOESTER</b> (–CO–S–CoA) sur le soufre.<br><br>⚠️ <b>Pourquoi un thioester plutôt qu'un oxoester :</b> la liaison thioester est <b>RICHE EN ÉNERGIE</b> (ΔG°' d'hydrolyse ≈ <b>−31,5 kJ/mol</b>, proche de celle de l'ATP) car le <b>soufre ne permet pas de résonance stabilisatrice</b> avec le carbonyle (mauvais recouvrement 3p–2p). La liaison est donc <b>activée</b> → le groupe acyle se transfère facilement.<br><br><b>ACÉTYL-CoA (CH₃–CO–S–CoA) — le CARREFOUR MÉTABOLIQUE CENTRAL :</b><br><b>Produit par :</b><br>• <b>Décarboxylation oxydative du PYRUVATE</b> (complexe pyruvate déshydrogénase, dans la matrice mitochondriale) — produit aussi <b>NADH + CO₂</b><br>• <b>β-OXYDATION des acides gras</b> (chaque tour libère 1 acétyl-CoA)<br>• <b>Catabolisme des acides aminés cétogènes</b> (Leu, Lys)<br>• Dégradation de l'alcool (éthanol → acétaldéhyde → acétate → acétyl-CoA)<br><br><b>Utilisé par :</b><br>• <b>CYCLE DE KREBS</b> : acétyl-CoA (2C) + oxaloacétate (4C) → citrate (6C), catalysé par la <b>citrate synthase</b> → production de <b>3 NADH, 1 FADH₂, 1 GTP, 2 CO₂</b> par tour<br>• <b>LIPOGENÈSE</b> (synthèse des acides gras, dans le cytosol)<br>• <b>SYNTHÈSE DU CHOLESTÉROL</b> et des <b>stéroïdes</b><br>• <b>CÉTOGENÈSE</b> (corps cétoniques : acétoacétate, β-hydroxybutyrate, acétone) dans le foie<br>• <b>ACÉTYLATION</b> des protéines (histones) et synthèse de l'<b>acétylcholine</b><br><br>⚠️ L'acétyl-CoA <b>NE PEUT PAS</b> traverser la membrane mitochondriale interne → il sort sous forme de <b>citrate</b> (navette citrate) pour la lipogenèse cytosolique.","t":"biochimie-2026 EXAM-2026"},{"q":"<b>BIOCHIMIE 2026 — CE QUI N'EST PAS TOMBÉ</b> : qu'est-ce qui est absent de l'examen S1 ?","a":"⚠️ <b>VÉRIFIÉ sur le QCM Biochimie structurale N2026 (~24 questions, corrigé à la main)</b> : <b>ZÉRO question</b> nécessitant des <b>prérequis de chimie du bac</b>.<br><br><b>ABSENTS :</b><br>• <b>pH, pKa, équation de Henderson-Hasselbalch, courbes de titrage des acides aminés</b><br>• <b>Point isoélectrique (pI) — calculs</b><br>• <b>Le concept de mole, les calculs de concentrations, les dilutions</b><br>• <b>Équilibres chimiques, constantes d'équilibre</b><br>• <b>Toute la biochimie MÉTABOLIQUE</b> (glycolyse, Krebs, chaîne respiratoire, β-oxydation) → <b>déplacée en S2</b> (module M121 « Biochimie métabolique et clinique », 5 crédits)<br><br><b>CE QUI TOMBE À LA PLACE (100 % mémorisation pure) :</b><br>• <b>Acides aminés</b> : structure, classification, essentiels, particularités (proline, cystéine, histidine, glycine)<br>• <b>Peptides</b> et <b>liaison peptidique</b> (caractère plan et rigide)<br>• <b>Structures des protéines</b> : primaire / secondaire / tertiaire / quaternaire et leurs liaisons<br>• <b>Hémoglobine et myoglobine</b> : Fe²⁺, formes R/T, coopérativité, 2,3-DPG, effet Bohr<br>• <b>Drépanocytose</b> : Glu6→Val sur la chaîne β<br>• <b>Enzymologie descriptive</b> : Km, Vmax, Lineweaver-Burk, types d'inhibition, aspirine, NAD/NADPH, CoA<br>• <b>Modifications post-traductionnelles</b> : phosphorylation sur –OH<br><br><b>CONSÉQUENCE :</b> ce module est <b>100 % mémorisable sans aucune base scientifique préalable</b>. C'est de la <b>fiche pure</b>. Objectif réaliste : <b>15–17/20</b>.","t":"biochimie-2026 EXAM-2026 STRATEGIE"},{"q":"<b>BIOCHIMIE 2026</b> — Quels sont les vitamines/coenzymes à associer (questions récurrentes) ?","a":"• <b>Vitamine B1 (thiamine)</b> → <b>TPP</b> : pyruvate déshydrogénase, α-cétoglutarate DH, transkétolase<br>• <b>Vitamine B2 (riboflavine)</b> → <b>FAD / FMN</b> : oxydoréductions (succinate DH, complexe I de la chaîne respiratoire)<br>• <b>Vitamine B3 (niacine)</b> → <b>NAD⁺ / NADP⁺</b> : oxydoréductions<br>• <b>Vitamine B5 (acide pantothénique)</b> → <b>COENZYME A</b> : transfert d'acyles<br>• <b>Vitamine B6 (pyridoxine)</b> → <b>PLP (phosphate de pyridoxal)</b> : <b>transaminations</b>, <b>décarboxylations</b> des acides aminés<br>• <b>Vitamine B8 / H (biotine)</b> → <b>carboxylations</b> (pyruvate carboxylase, acétyl-CoA carboxylase)<br>• <b>Vitamine B9 (folate)</b> → <b>THF (tétrahydrofolate)</b> : transferts de <b>mono-carbonés</b> (méthyl, formyl)<br>• <b>Vitamine B12 (cobalamine)</b> → <b>méthylmalonyl-CoA mutase, méthionine synthase</b> — nécessite le <b>facteur intrinsèque</b><br>• <b>Vitamine C (acide ascorbique)</b> → <b>hydroxylation de la proline et de la lysine du COLLAGÈNE</b> (prolyl-hydroxylase) — carence = <b>SCORBUT</b><br>• <b>Vitamine K</b> → <b>γ-carboxylation des facteurs de coagulation II, VII, IX, X</b><br>• <b>Vitamine A (rétinol)</b> → <b>rhodopsine</b> (vision), différenciation épithéliale<br>• <b>Vitamine D</b> → <b>métabolisme du calcium</b><br>• <b>Vitamine E (tocophérol)</b> → <b>antioxydant</b> membranaire","t":"biochimie-2026 EXAM-2026"}]},{"id":"anatomie-S1-2026","nom":"🦴 Anatomie","src":"Examen N2026","ordre":9,"module":"M113","desc":"Rédaction · plans · dimensions","cards":[{"q":"<b>ANATOMIE — LE PLAN UNIVERSEL</b> : quels sont les 8 points à traiter pour TOUTE question de description d'un organe ?","a":"⚠️ <b>CE PLAN EST LA CLÉ DE LA NOTE.</b> L'anatomie à la FMDC est un <b>ÉCRIT de rédaction</b>, pas un QCM. Le correcteur <b>cherche des points</b>, pas de la prose.<br><br><b>1. DÉFINITION</b> — une phrase : nature, système d'appartenance, fonction.<br><b>2. SITUATION / LOCALISATION</b> — région, loge, étage, rapports squelettiques (vertèbres, côtes).<br><b>3. FORME</b> — comparaison classique (« en grain de café », « piriforme », « en J »).<br><b>4. DIMENSIONS CHIFFRÉES</b> — longueur, largeur, épaisseur, <b>POIDS</b>. ⚠️ <b>Ce sont les chiffres qui rapportent le plus de points.</b><br><b>5. ORIENTATION / DIRECTIONS</b> — axe, faces, bords, extrémités.<br><b>6. CONFIGURATION EXTERNE et INTERNE</b> — surfaces, hile, segments, subdivisions.<br><b>7. RAPPORTS</b> — antérieurs, postérieurs, latéraux, médiaux, vasculo-nerveux.<br><b>8. VASCULARISATION + INNERVATION + LYMPHATIQUES</b> — artère (origine), veine (drainage), nerf (racine).<br><br><b>+ SCHÉMA LÉGENDÉ</b> (même simple) — rapporte des points et montre que tu as compris.<br><br>⚠️ <b>RÈGLE D'OR :</b> écris en <b>puces courtes</b>, pas en paragraphes. Un correcteur qui lit 400 copies en 3 jours <b>compte les items</b>.","t":"anato-2026 EXAM-2026 STRATEGIE"},{"q":"<b>ANATOMIE — LES 3 PROFESSEURS</b> : quels sont les 3 domaines récurrents et qui pose quoi ?","a":"⚠️ <b>VÉRIFIÉ sur les examens 2023 ET 2026</b> — l'épreuve d'anatomie est divisée entre <b>3 professeurs</b>, chacun avec des <b>copies de couleur différente</b>, et chacun pose <b>toujours le même domaine</b>.<br><br><b>1. Pr DEBBAGH → APPAREIL URINAIRE</b><br>• Le <b>REIN</b> (description complète)<br>• L'<b>URETÈRE</b><br>• La <b>VESSIE</b>, l'<b>urètre</b><br><br><b>2. Pr ERGUIBI → ABDOMEN / APPAREIL DIGESTIF</b><br>• Les <b>QUADRANTS / régions de l'abdomen</b><br>• La <b>RATE</b><br>• Le <b>DUODÉNUM</b><br>• Le <b>PANCRÉAS</b><br>• L'<b>ŒSOPHAGE</b><br>• L'<b>ESTOMAC</b>, le <b>FOIE</b><br><br><b>3. Pr ID EL HAJ → THORAX</b><br>• Le <b>STERNUM</b><br>• La <b>PAROI THORACIQUE</b><br>• La <b>PLÈVRE</b><br>• Le <b>MÉDIASTIN</b><br>• Les <b>POUMONS</b><br><br><b>VERBES TYPES DES ÉNONCÉS :</b><br><b>« Décrire »</b> · <b>« Citer »</b> · <b>« Énumérer »</b> · <b>« Légender »</b> · <b>« Donner les limites »</b> · <b>« Donner les rapports »</b><br><br>⚠️ <b>STRATÉGIE :</b> il n'y a que <b>≈ 12 structures</b> à connaître parfaitement, pas tout le corps humain. <b>Priorise les 3 premières de chaque prof</b> : rein, rate, duodénum, sternum, plèvre.","t":"anato-2026 EXAM-2026 STRATEGIE"},{"q":"Quel est la différence de réponse entre « <b>CITER</b> » et « <b>DÉCRIRE</b> » dans un énoncé d'anatomie ?","a":"<b>« CITER » / « ÉNUMÉRER »</b> = <b>UNE SIMPLE LISTE</b>, sans développement.<br>• Réponds en <b>puces numérotées</b>, <b>1 ligne par item</b><br>• Ne perds <b>pas de temps</b> à expliquer<br>• ⚠️ Mais cite le <b>nombre exact</b> attendu et <b>TOUS</b> les items (chaque item manquant = points perdus)<br>Ex. : « Citer les régions de l'abdomen » → les <b>9 régions</b> en liste, c'est tout.<br><br><b>« DÉCRIRE »</b> = <b>LE PLAN COMPLET EN 8 POINTS</b> (définition, situation, forme, dimensions, orientation, configuration, rapports, vascularisation) + schéma.<br>• C'est la question qui rapporte le <b>plus de points</b><br>• <b>Toujours</b> donner les <b>DIMENSIONS CHIFFRÉES</b> et le <b>POIDS</b><br><br><b>« LÉGENDER »</b> = un schéma est fourni, tu écris les <b>numéros</b> avec les noms.<br>• ⚠️ Utilise le <b>vocabulaire exact</b> (Terminologia Anatomica), pas de synonymes familiers.<br><br><b>« DONNER LES LIMITES »</b> = énumère les <b>frontières anatomiques précises</b> d'un espace ou d'une région (haut, bas, avant, arrière, dedans, dehors).<br>• Réponds en <b>6 puces</b> : supérieure, inférieure, antérieure, postérieure, latérale, médiale.","t":"anato-2026 EXAM-2026 STRATEGIE"},{"q":"Décris le <b>REIN</b> (plan complet, façon examen).","a":"<b>DÉFINITION :</b> organe <b>PAIR</b>, <b>rétropéritonéal</b>, de l'<b>appareil urinaire</b>, chargé de la <b>filtration du sang</b> et de la formation de l'<b>urine</b>. Glande <b>uro-poïétique</b>.<br><br><b>SITUATION :</b> dans la <b>loge rénale</b> de la <b>fosse lombaire</b>, de part et d'autre de la colonne vertébrale, <b>RÉTROPÉRITONÉAL</b> (en arrière du péritoine pariétal postérieur).<br>⚠️ <b>Asymétrie :</b> le rein <b>DROIT est PLUS BAS</b> que le gauche (à cause du foie).<br>• Rein droit : de <b>L1 (ou T12) à L3</b> (pôle supérieur ~ 2 cm plus bas)<br>• Rein gauche : de <b>T12 à L3</b><br>• Le <b>hile rénal</b> se projette sur <b>L1</b> (plan transpylorique de Addison).<br><br><b>FORME :</b> <b>haricot</b> (fève) — deux faces, deux bords, deux pôles.<br><br><b>DIMENSIONS :</b><br>• Longueur : <b>11 à 12 cm</b> (≈ la hauteur d'une vertèbre et demie)<br>• Largeur : <b>6 cm</b><br>• Épaisseur : <b>3 cm</b><br>• Poids : <b>125 à 150 g</b> chez l'homme, <b>115 à 140 g</b> chez la femme<br>Moyen mnémotechnique : <b>12 × 6 × 3</b> et <b>150 g</b>.<br><br><b>ORIENTATION :</b> grand axe <b>oblique en bas, en dehors et en arrière</b>. Les pôles supérieurs sont <b>plus rapprochés</b> que les inférieurs (convergence vers le haut).<br><br><b>CONFIGURATION EXTERNE :</b><br>• <b>2 faces</b> : antérieure (convexe) et postérieure (plane)<br>• <b>2 bords</b> : <b>latéral (convexe)</b> et <b>médial (concave)</b><br>• <b>2 pôles (extrémités)</b> : supérieur et inférieur<br>• Le bord médial présente le <b>HILE RÉNAL</b> (fissure verticale) — entrée/sortie des éléments du <b>pédicule rénal</b><br>• Le rein est enveloppé de 3 couches : <b>capsule fibreuse</b> (adhérente, se décortique), <b>capsule adipeuse</b> (graisse périrénale), <b>fascia rénal (de Gerota)</b><br><br><b>CONFIGURATION INTERNE (coupe frontale) :</b><br>• <b>SINUS RÉNAL</b> : cavité centrale contenant le <b>hile</b>, les calices, la graisse, les vaisseaux<br>• <b>PARENCHYME</b> en 2 zones :<br>&nbsp;&nbsp;– <b>CORTICALE</b> (périphérique, granuleuse, claire) — contient les <b>corpuscules rénaux (de Malpighi)</b> et les <b>tubes contournés</b> ; elle s'invagine entre les pyramides sous forme de <b>COLONNES RÉNALES (de Bertin)</b><br>&nbsp;&nbsp;– <b>MÉDULLAIRE</b> (centrale, striée, foncée) — <b>8 à 18 PYRAMIDES RÉNALES (de Malpighi)</b>, dont la base regarde le cortex et le <b>SOMMET (papille rénale)</b> se projette dans un calice mineur. Les <b>tubes collecteurs (de Bellini)</b> s'ouvrent à la papille par les <b>orifices papillaires (crible rénal)</b><br>• <b>VOIES EXCRÉTRICES intra-rénales</b> : papille → <b>calice mineur</b> → <b>calice majeur</b> (2–3) → <b>bassinet (pelvis rénal)</b> → <b>uretère</b><br><br><b>RAPPORTS :</b><br>• <b>EN AVANT (rein droit)</b> : foie (face viscérale), angle colique droit (flexure hépatique), duodénum (2ᵉ portion), glande surrénale<br>• <b>EN AVANT (rein gauche)</b> : rate, estomac (grande courbure, par l'intermédiaire de l'épiploon gastro-splénique), queue du pancréas, angle colique gauche, jéjunum, glande surrénale<br>• <b>EN ARRIÈRE (les deux)</b> : <b>diaphragme</b> (en haut, avec le cul-de-sac pleural), puis <b>carré des lombes</b> et <b>psoas</b> ; nerfs <b>subcostal (T12), ilio-hypogastrique (L1) et ilio-inguinal (L1)</b> ; 12ᵉ côte (rein gauche) et 11ᵉ–12ᵉ côtes (rein droit)<br>• <b>EN DEDANS</b> : pédicule rénal, piliers du diaphragme, corps vertébraux lombaires<br>• ⚠️ Le <b>rein droit</b> est en rapport avec le <b>cul-de-sac pleural</b> → risque de <b>plaie pleurale</b> lors d'une chirurgie lombaire<br><br><b>PÉDICULE RÉNAL (de AVANT en ARRIÈRE) :</b><br><b>VEINE — ARTÈRE — BASSINET</b> (moyen mnémotechnique : <b>V-A-B</b>, ou « <b>V</b>eine en <b>V</b>itesse devant »)<br>De <b>HAUT en BAS</b> : <b>ARTÈRE — VEINE — BASSINET</b> (A-V-B)<br>⚠️ Ne pas confondre les deux ordres !<br><br><b>VASCULARISATION :</b><br>• <b>ARTÈRE</b> : <b>artère rénale</b>, branche de l'<b>aorte abdominale</b>, naît en <b>L1–L2</b>, courte, <b>TERMINALE (artère de type terminal — pas d'anastomose)</b> ⚠️ → toute ligature = infarctus du territoire. Elle se divise en <b>5 artères segmentaires</b> (apicale, antéro-supérieure, antéro-inférieure, inférieure, postérieure).<br>• <b>VEINE</b> : <b>veine rénale</b> → se jette dans la <b>veine cave inférieure</b>. La <b>veine rénale GAUCHE est PLUS LONGUE</b> (elle croise l'aorte en avant, entre l'aorte et l'artère mésentérique supérieure = <b>« pince aorto-mésentérique »</b> — peut causer le <b>syndrome de la casse-noisette / nutcracker</b>) et reçoit la <b>veine gonadique gauche</b> et la <b>veine surrénale gauche</b>.<br>• <b>Débit sanguin rénal ≈ 1,2 L/min</b> = <b>20–25 % du débit cardiaque</b><br>• <b>LYMPHATIQUES</b> : nœuds <b>lombariques (aortiques et caves)</b><br><br><b>INNERVATION :</b> <b>plexus rénal</b>, sympathique (<b>T10–L1</b>, nerfs splanchniques) et parasympathique (<b>nerf vague X</b>). La douleur rénale est projetée sur la <b>fosse lombaire</b> et se propage vers l'<b>aine</b> (colique néphrétique).<br><br><b>UNITÉ FONCTIONNELLE : le NÉPHRON</b> — <b>1 à 1,3 million par rein</b>. = corpuscule rénal (glomérule + capsule de Bowman) + tubule contourné proximal + anse de Henlé + tubule contourné distal + tube collecteur.","t":"anato-2026 EXAM-2026"},{"q":"Décris l'<b>URETÈRE</b> (plan complet).","a":"<b>DÉFINITION :</b> conduit <b>PAIR</b>, <b>MUSCULO-MEMBRANEUX</b>, qui transporte l'<b>urine du bassinet rénal vers la vessie</b>. Voie excrétrice urinaire haute.<br><br><b>SITUATION :</b> <b>RÉTROPÉRITONÉAL</b>, dans la <b>fosse lombaire</b> puis la <b>cavité pelvienne</b>.<br><br><b>DIMENSIONS :</b><br>• Longueur : <b>25 à 30 cm</b> (27 cm en moyenne)<br>• Diamètre : <b>3 à 5 mm</b> — mais <b>variable</b> (présence de <b>rétrécissements</b>)<br>• Paroi : <b>3 tuniques</b> — muqueuse (épithélium <b>de transition / urothélium</b>), musculeuse (<b>3 couches</b> : longitudinale interne, circulaire moyenne, longitudinale externe ⚠️ inversé par rapport au tube digestif), adventice conjonctive<br><br><b>TRAJET — 3 PORTIONS :</b><br>1. <b>LOMBAIRE (abdominale)</b> : du bassinet au détroit supérieur, descend verticalement sur le <b>psoas</b><br>2. <b>PELVIENNE (iliaque)</b> : du détroit supérieur à la paroi vésicale<br>3. <b>INTRAMURALE (vésicale / pariétale)</b> : traverse obliquement la paroi de la vessie sur <b>1,5 à 2 cm</b> → s'abouche par l'<b>orifice urétéral</b> (méat) au sommet du <b>triangle de Lieutaud</b><br>⚠️ Le trajet oblique intramural forme une <b>VALVE PHYSIOLOGIQUE</b> anti-reflux (le reflux vésico-urétéral est empêché par la contraction vésicale qui comprime l'uretère).<br><br><b>LES 3 (ou 4) RÉTRÉCISSEMENTS DE L'URETÈRE ⚠️ QUESTION TRÈS FRÉQUENTE :</b><br>1. <b>JONCTION PYÉLO-URÉTÉRALE (JPU)</b> — à la sortie du bassinet (dès l'origine), diamètre ≈ 2–3 mm<br>2. <b>CROISEMENT DES VAISSEAUX ILIAQUES</b> — au détroit supérieur (croise l'<b>artère iliaque commune</b> à droite, l'<b>artère iliaque externe</b> à gauche)<br>3. <b>JONCTION URÉTÉRO-VÉSICALE (JUV)</b> — entrée dans la vessie, <b>le plus étroit</b> (2–3 mm)<br>(Parfois cité : le rétrécissement <b>pelvien/lombaire</b>)<br>→ Ce sont les <b>3 SITES D'ENCLAVEMENT DES CALCULS (lithiase urétérale)</b> et de la <b>colique néphrétique</b>.<br><br><b>RAPPORTS :</b><br>• <b>EN AVANT (droit)</b> : duodénum (2ᵉ portion), vaisseaux <b>coliques droits</b>, vaisseaux <b>gonadiques droits</b>, racine du mésentère de l'iléon terminal<br>• <b>EN AVANT (gauche)</b> : vaisseaux <b>coliques gauches</b>, vaisseaux <b>gonadiques gauches</b>, côlon sigmoïde<br>• <b>EN ARRIÈRE (les deux)</b> : <b>muscle psoas</b>, apophyses transverses lombaires, nerf <b>génito-fémoral</b><br>• <b>EN DEDANS</b> : colonne vertébrale lombaire, aorte (à gauche) / veine cave inférieure (à droite)<br>• ⚠️ <b>EN CHIRURGIE GYNÉCOLOGIQUE</b> : l'uretère est <b>TOUT PRÈS de l'artère utérine</b> (« l'eau passe sous le pont ») — sous le ligament large → <b>RISQUE DE PLAIE per-opératoire</b> lors d'une hystérectomie<br><br><b>VASCULARISATION ⚠️ SEGMENTAIRE ET MULTIPLE (pas une seule artère) :</b><br>• <b>1/3 supérieur</b> : branches de l'<b>artère rénale</b> et de l'<b>artère gonadique</b><br>• <b>1/3 moyen</b> : <b>artère iliaque commune / aorte abdominale</b><br>• <b>1/3 inférieur (pelvien)</b> : <b>artère vésicale inférieure</b>, <b>artère utérine</b> (chez la femme), <b>artère rectale moyenne</b><br>• ⚠️ Les artères arrivent <b>par le bord MÉDIAL</b> et forment un <b>plexus longitudinal</b> — il ne faut pas disséquer l'uretère sur toute sa circonférence (risque d'ischémie)<br>• <b>VEINES</b> : suivent les artères → veine rénale, gonadique, iliaques → cave<br>• <b>LYMPHATIQUES</b> : lombaires (sup.), iliaques (inf.)<br><br><b>INNERVATION :</b> <b>plexus urétéral</b> — sympathique <b>T11–L2</b> (douleur → colique néphrétique, projetée sur le flanc, l'aine et les organes génitaux externes, dermatomes T11–L1) ; parasympathique <b>vague (X)</b> en haut et <b>S2–S4</b> en bas.<br><br><b>PHYSIOLOGIE :</b> l'urine progresse par <b>PÉRISTALTISME</b> (ondes de 1 à 5/min), pas par gravité.","t":"anato-2026 EXAM-2026"},{"q":"Énumère les <b>9 RÉGIONS DE L'ABDOMEN</b> et les <b>4 QUADRANTS</b>.","a":"<b>LES 9 RÉGIONS (division classique en 3 étages × 3 colonnes) :</b><br><br>Délimitées par <b>2 plans horizontaux</b> et <b>2 plans verticaux</b> :<br>• <b>Plan horizontal supérieur</b> = <b>PLAN SUBCOSTAL</b> (reliant les 10ᵉ cartilages costaux, passe par <b>L3</b>) — ou plan <b>transpylorique</b> (Addison, passant par L1, reliant les 9ᵉ cartilages costaux et le bord inférieur de L1)<br>• <b>Plan horizontal inférieur</b> = <b>PLAN INTERTUBERCULAIRE</b> (reliant les tubercules des crêtes iliaques, passe par <b>L5</b>)<br>• <b>2 plans verticaux</b> = <b>lignes médio-claviculaires</b> (ou lignes verticales passant par le milieu des clavicules, à ≈ 8–10 cm de la ligne médiane)<br><br><b>ÉTAGE SUPÉRIEUR (hypochondres + épigastre) :</b><br>1. <b>HYPOCHONDRE DROIT</b> — foie (lobe droit), vésicule biliaire, angle colique droit, rein droit (pôle sup.), surrénale droite<br>2. <b>ÉPIGASTRE</b> — estomac (antre/pylore), duodénum (1ʳᵉ et 2ᵉ portions), pancréas, foie (lobe gauche), aorte, veine cave inférieure, plexus cœliaque<br>3. <b>HYPOCHONDRE GAUCHE</b> — rate, estomac (fundus), queue du pancréas, angle colique gauche, rein gauche (pôle sup.), surrénale gauche<br><br><b>ÉTAGE MOYEN (flancs + ombilic) :</b><br>4. <b>FLANC DROIT (région lombaire droite)</b> — côlon ascendant, rein droit (partie moyenne), duodénum (3ᵉ portion)<br>5. <b>OMBILIC (région ombilicale)</b> — duodénum (3ᵉ–4ᵉ portions), jéjunum, iléon, aorte, veine cave inférieure, uretères, tête du pancréas<br>6. <b>FLANC GAUCHE (région lombaire gauche)</b> — côlon descendant, rein gauche, jéjunum<br><br><b>ÉTAGE INFÉRIEUR (fosses iliaques + hypogastre) :</b><br>7. <b>FOSSE ILIAQUE DROITE (région inguinale droite)</b> — <b>CÆCUM + APPENDICE</b> ⚠️, iléon terminal, ovaire/trompe droits, cordon spermatique droit<br>8. <b>HYPOGASTRE (région pubienne)</b> — vessie, utérus, anses grêles, côlon sigmoïde (partie), prostate<br>9. <b>FOSSE ILIAQUE GAUCHE (région inguinale gauche)</b> — <b>CÔLON SIGMOÏDE</b>, ovaire/trompe gauches, cordon spermatique gauche<br><br>Moyen mnémotechnique des 9 régions : <b>« HÉH / FOF / FHF »</b> (Hypochondre-Épigastre-Hypochondre / Flanc-Ombilic-Flanc / Fosse iliaque-Hypogastre-Fosse iliaque), toujours <b>DROITE → GAUCHE</b>.<br><br><b>LES 4 QUADRANTS</b> (division simple en croix, par la <b>ligne médiane</b> et le <b>plan transombilical</b> passant par <b>L3/L4</b> et l'ombilic) :<br>• <b>QSD</b> (quadrant supéro-droit) : foie, vésicule, duodénum, tête du pancréas, rein droit, angle colique droit<br>• <b>QSG</b> (quadrant supéro-gauche) : rate, estomac, queue du pancréas, rein gauche, angle colique gauche<br>• <b>QID</b> (quadrant inféro-droit) : <b>appendice</b>, cæcum, ovaire droite<br>• <b>QIG</b> (quadrant inféro-gauche) : <b>sigmoïde</b>, ovaire gauche<br><br>⚠️ <b>POINTS DE REPÈRE CLINIQUES :</b><br>• <b>Point de McBurney</b> : jonction du <b>1/3 externe et des 2/3 internes</b> de la ligne reliant l'<b>ombilic</b> à l'<b>épine iliaque antéro-supérieure droite</b> → douleur de l'<b>APPENDICITE</b><br>• <b>Signe de Murphy</b> : douleur à l'inspiration profonde lors de la palpation de l'hypochondre droit → <b>CHOLÉCYSTITE</b><br>• <b>Signe de Giordano</b> : percussion de la fosse lombaire → <b>PYÉLONÉPHRITE</b>","t":"anato-2026 EXAM-2026"},{"q":"Décris la <b>RATE</b> (plan complet).","a":"<b>DÉFINITION :</b> le <b>plus gros organe LYMPHOÏDE</b> de l'organisme. Organe <b>IMPAIR</b>, <b>intrapéritonéal</b>, très <b>vascularisé</b> et <b>fragile</b>. Située dans l'<b>hypochondre gauche</b>.<br><br><b>RÔLES :</b><br>• <b>Immunitaire</b> : production de <b>lymphocytes</b>, d'<b>anticorps</b>, filtration des antigènes sanguins<br>• <b>Hématologique</b> : <b>destruction des hématies vieillies</b> (cimetière des globules rouges) — <b>hématose/érythrocytorhexie</b><br>• <b>Réserve sanguine</b> (~200–300 mL de sang, surtout de plaquettes : <b>⅓ du pool plaquettaire</b>)<br>• Chez le <b>fœtus</b> : <b>hématopoïèse</b> (reprise chez l'adulte en cas de pathologie médullaire)<br><br><b>SITUATION :</b> hypochondre gauche, <b>intrapéritonéale</b> (reliée à l'estomac par le <b>ligament gastro-splénique</b> et au rein par le <b>ligament spléno-rénal</b>), sous la <b>coupole diaphragmatique gauche</b>.<br><br><b>PROJECTION PARIÉTALE ⚠️ QUESTION FRÉQUENTE :</b><br>La rate se projette entre la <b>9ᵉ et la 11ᵉ CÔTE</b>, le long de l'axe de la <b>10ᵉ côte</b>.<br>Elle est <b>NON PALPABLE</b> chez le sujet normal (elle devient palpable seulement si elle a <b>doublé ou triplé de volume</b> → splénomégalie).<br><br><b>FORME :</b> <b>ovoïde</b>, « grain de café » — aplatie, avec une <b>incisure (échancrure)</b> sur le bord antéro-supérieur.<br><br><b>DIMENSIONS :</b><br>• Longueur : <b>12 à 13 cm</b><br>• Largeur : <b>7 à 8 cm</b><br>• Épaisseur : <b>3 à 4 cm</b><br>• Poids : <b>150 à 200 g</b><br>• ⚠️ <b>Ne dépasse PAS 350–400 g</b> en cas de pathologie<br>Moyen mnémotechnique : <b>1 × 3 × 8 × 11</b> (1 pouce d'épaisseur, 3–4 oz, 8 cm de large, 11ᵉ côte) — en français retiens <b>12–13 cm / 150–200 g</b>.<br><br><b>ORIENTATION :</b> grand axe <b>oblique en bas, en avant et en dehors</b>, parallèle à la <b>10ᵉ côte</b>.<br><br><b>CONFIGURATION :</b><br>• <b>2 faces</b> : <b>diaphragmatique</b> (latérale, convexe, lisse, contre le diaphragme) et <b>viscérale</b> (médiale, concave, irrégulière)<br>• <b>2 bords</b> : <b>antérieur</b> (mince, dentelé, avec l'<b>incisure</b> — repère palpatoire) et <b>postérieur</b> (épais, arrondi)<br>• <b>2 extrémités (pôles)</b> : supérieure et inférieure<br>• La face viscérale présente le <b>HILE SPLENIQUE (hile de la rate)</b> — face médiale, où pénètrent l'<b>artère splénique</b> et la <b>veine splénique</b> et d'où partent les lymphatiques<br>• La face viscérale montre des <b>impressions</b> : gastrique (estomac), rénale (rein gauche), colique (angle colique gauche)<br>• <b>STRUCTURE</b> : capsule fibreuse + péritoine ; parenchyme = <b>PULPE</b> en 2 types :<br>&nbsp;&nbsp;– <b>PULPE ROUGE</b> : filtration du sang, destruction des GR vieillies (cordons de Billroth + sinus)<br>&nbsp;&nbsp;– <b>PULPE BLANCHE</b> : lymphoïde — <b>corpuscules de Malpighi</b> (gaines lymphoïdes péri-artérielles, PALS, autour de l'artère centrale)<br><br><b>RAPPORTS :</b><br>• <b>EN DEHORS / EN HAUT</b> : <b>DIAPHRAGME</b>, puis la paroi thoracique (côtes 9–11), le <b>cul-de-sac pleural gauche</b> ⚠️ → une fracture des côtes 9–11 peut léser la rate ET la plèvre<br>• <b>EN DEDANS / EN AVANT</b> : <b>ESTOMAC</b> (grande courbure/fundus) — par le <b>ligament gastro-splénique</b> contenant les <b>vaisseaux gastriques courts (vasa brevia)</b> et la <b>gastro-épiploïque gauche</b><br>• <b>EN ARRIÈRE / EN DEDANS</b> : <b>REIN GAUCHE</b> et <b>glande surrénale gauche</b> — par le <b>ligament spléno-rénal</b> contenant les <b>vaisseaux spléniques</b> et la <b>queue du pancréas</b> ⚠️ (risque de fistule pancréatique en splénectomie)<br>• <b>EN BAS</b> : <b>ANGLE COLIQUE GAUCHE (flexure splénique)</b>, retenu par le <b>ligament phréno-colique</b><br>• <b>EN BAS / EN ARRIÈRE</b> : l'<b>espace sous-phrénique gauche</b> et la <b>bourse omentale (arrière-cavité des épiploons)</b><br><br><b>VASCULARISATION :</b><br>• <b>ARTÈRE</b> : <b>ARTÈRE SPLÉNIQUE</b> — la <b>plus grosse branche du TRONC CŒLIAQUE</b>. Trajet <b>TORTUEUX</b> le long du bord supérieur du pancréas, puis dans le ligament spléno-rénal. Se divise au hile en <b>2 branches terminales</b> (supérieure et inférieure) → <b>5 à 6 artères segmentaires</b> ⚠️ artères <b>TERMINALES</b> (peu d'anastomoses) → les infarctus spléniques sont fréquents<br>• <b>VEINE</b> : <b>VEINE SPLÉNIQUE</b> — rejoint la <b>veine mésentérique supérieure</b> en arrière du col du pancréas pour former la <b>VEINE PORTE</b> ⚠️ → une <b>hypertension portale</b> (cirrhose) se traduit par une <b>SPLENO-MÉGALIE</b><br>• <b>LYMPHATIQUES</b> : nœuds <b>pancréatico-spléniques</b> (au hile) → nœuds <b>cœliaques</b> → conduit thoracique<br><br><b>INNERVATION :</b> plexus splénique, sympathique (<b>T6–T10</b> via le plexus cœliaque) + parasympathique (<b>vague X</b>).<br><br>⚠️ <b>CLINIQUE :</b> la <b>RATE EST L'ORGANE ABDOMINAL LE PLUS SOUVENT LÉSÉ dans les TRAUMATISMES FERMÉS de l'abdomen</b> (accident de la voie publique, chute) → <b>hémorragie interne grave</b> (rate très vascularisée, capsule fine). La <b>SPLENECTOMIE</b> est possible (la survie est normale) mais expose au risque d'<b>OPSI</b> (infections fulminantes post-splénectomie à germes encapsulés : pneumocoque, méningocoque, Haemophilus) → <b>vaccination obligatoire</b>.","t":"anato-2026 EXAM-2026"},{"q":"Décris le <b>DUODÉNUM</b> (plan complet).","a":"<b>DÉFINITION :</b> <b>PREMIER SEGMENT DE L'INTESTIN GRÊLE</b>, faisant suite au <b>pylore</b> et se continuant par le <b>jéjunum</b>. Seul segment <b>FIXE</b> (rétropéritonéal en grande partie) et le plus <b>large</b> de l'intestin grêle. C'est le <b>carrefour bilio-pancréatique</b>.<br><br><b>DIMENSIONS :</b><br>• Longueur : <b>25 cm</b> environ — soit <b>12 travers de doigt</b> ⚠️ (d'où son nom : « <b>duodenum</b> » = « douze »)<br>• Diamètre : <b>4 à 5 cm</b> (le plus large de l'intestin grêle)<br>• Il s'étend de <b>L1 à L4</b><br><br><b>FORME :</b> <b>anneau incomplet, en « C » ou en fer à cheval</b>, <b>ouvert en arrière et à gauche</b>, <b>embrassant la TÊTE DU PANCRÉAS</b>.<br><br><b>SITUATION :</b> <b>RÉTROPÉRITONÉAL</b> (sauf le <b>1ᵉʳ cm</b> = bulbe, qui est <b>intrapéritonéal</b> et mobile). Situé dans l'<b>étage sus-mésocolique</b>, en regard de <b>L1 à L4</b>.<br><br><b>LES 4 PORTIONS ⚠️ QUESTION TRÈS FRÉQUENTE :</b><br>1. <b>D1 — PORTION SUPÉRIEURE (premier duodénum / BULBE DUODÉNAL)</b> : <b>horizontale</b>, de <b>L1</b>, <b>intrapéritonéale</b>, mobile, ascendante et postéro-supérieure. Sa première partie, lisse et sans plis, forme l'<b>ampoule duodénale</b> — ⚠️ <b>SIÈGE DE 75–80 % DES ULCÈRES DUODÉNAUX</b>. Elle est en rapport en avant avec la <b>vésicule biliaire</b> et le <b>foie</b>.<br>2. <b>D2 — PORTION DESCENDANTE</b> : <b>verticale</b>, de <b>L1 à L3</b>, descend en avant du <b>hile du rein droit</b>. Contient les <b>PAPILLES (CARONCULES) DUODÉNALES</b> :<br>&nbsp;&nbsp;• <b>Grande papille (papille majeure, ampoule de Vater)</b> : abouchement du <b>canal cholédoque + canal de Wirsung (pancréatique principal)</b>, après leur union dans l'<b>ampoule hépato-pancréatique de Vater</b>, contrôlée par le <b>SPHINCTER D'ODDI</b>. Elle est située à <b>8–10 cm du pylore</b>, sur la face <b>médiale</b> de D2.<br>&nbsp;&nbsp;• <b>Petite papille (papille accessoire, de Santorini)</b> : abouchement du <b>canal de Santorini (pancréatique accessoire)</b>, à <b>2 cm au-dessus</b> de la grande papille.<br>&nbsp;&nbsp;⚠️ C'est la <b>frontière embryologique entre l'intestin antérieur (foregut) et l'intestin moyen (midgut)</b>.<br>3. <b>D3 — PORTION HORIZONTALE (INFÉRIEURE / TRANSVERSE)</b> : <b>horizontale</b>, traverse la ligne médiane en <b>L3</b>, passe <b>EN AVANT de l'aorte et de la veine cave inférieure</b> et <b>EN ARRIÈRE des vaisseaux mésentériques supérieurs</b> ⚠️ → peut être comprimé entre l'aorte et l'artère mésentérique supérieure = <b>SYNDROME DE WILKIE (pince aorto-mésentérique)</b> → occlusion duodénale. Le <b>crochet du pancréas</b> s'insinue en arrière.<br>4. <b>D4 — PORTION ASCENDANTE</b> : courte, <b>oblique en haut et à gauche</b>, remonte jusqu'en <b>L2</b> au niveau du <b>bord inférieur du corps du pancréas</b>, puis se courbe en avant pour former l'<b>ANGLE DUODÉNO-JÉJUNAL (angle de Treitz)</b>, maintenu par le <b>MUSCLE DE TREITZ</b> (ligament suspenseur du duodénum, muscle lisse + squelettique issu du pilier droit du diaphragme). Cet angle marque la <b>jonction duodéno-jéjunale</b>.<br><br><b>CONFIGURATION INTERNE :</b><br>• <b>PLIS CIRCULAIRES (valvules conniventes, plis de Kerckring)</b> — permanents, perpendiculaires à l'axe, augmentent la surface d'absorption (absents dans le bulbe)<br>• <b>VILLOSITÉS INTESTINALES</b> (~1/mm²) — recouvertes d'<b>entérocytes</b> à <b>microvillosités</b> (bordure en brosse)<br>• <b>CRYPTES DE LIEBERKÜHN</b> (glandes intestinales)<br>• ⚠️ Cellules spécifiques du duodénum : <b>GLANDES DE BRUNNER</b> (glandes duodénales, dans la <b>sous-muqueuse</b> — unique au duodénum) → sécrètent un <b>mucus ALCALIN (riche en bicarbonates)</b> qui <b>neutralise le chyme acide</b> et protège la muqueuse. Aussi : cellules <b>S</b> (sécrétine), cellules <b>I</b> (CCK), cellules <b>K</b> (GIP), cellules de <b>Paneth</b>.<br><br><b>RAPPORTS :</b><br>• <b>EN ARRIÈRE</b> : <b>TÊTE DU PANCRÉAS</b> (le duodénum est « soudé » à elle, vascularisation commune ⚠️ → on ne peut pas retirer l'un sans l'autre = <b>duodéno-pancréatectomie céphalique, DPCE</b>), veine cave inférieure, pédicule rénal droit, aorte (D3)<br>• <b>EN AVANT</b> : foie (lobe carré), vésicule biliaire, côlon transverse (racine du mésocôlon transverse), anses jéjunales<br>• <b>EN HAUT</b> : <b>foramen omental (hiatus de Winslow)</b>, bord libre du petit omentum contenant le <b>pédicule hépatique</b> (artère hépatique propre, veine porte, canal cholédoque)<br>• <b>EN BAS</b> : anses jéjunales<br>• <b>À DROITE</b> : côlon ascendant, flexure colique droite, rein droit<br>• <b>À GAUCHE</b> : tête du pancréas, vaisseaux mésentériques supérieurs<br><br><b>VASCULARISATION ⚠️ DOUBLE, avec une ANASTOMOSE en arcade :</b><br>• <b>MOITIÉ SUPÉRIEURE (D1 + partie de D2)</b> : <b>ARTÈRES PANCRÉATICO-DUODÉNALES SUPÉRIEURES (antérieure et postérieure)</b>, branches de l'<b>ARTÈRE GASTRO-DUODÉNALE</b> (elle-même branche de l'<b>artère hépatique commune</b>, issue du <b>tronc cœliaque</b>)<br>• <b>MOITIÉ INFÉRIEURE (partie de D2, D3, D4)</b> : <b>ARTÈRES PANCRÉATICO-DUODÉNALES INFÉRIEURES</b>, premières branches de l'<b>ARTÈRE MÉSSENTÉRIQUE SUPÉRIEURE</b><br>• ⚠️ Les deux systèmes s'<b>ANASTOMOSENT</b> en formant les <b>ARCADES PANCRÉATICO-DUODÉNALES</b> (antérieure et postérieure) le long du sillon entre le pancréas et le duodénum → c'est une <b>voie de dérivation (collatérale)</b> en cas d'obstruction du tronc cœliaque ou de l'AMS. C'est aussi la <b>frontière entre le tronc cœliaque et l'AMS</b>.<br>• <b>VEINES</b> : <b>veines pancréatico-duodénales supérieures</b> → <b>veine gastro-duodénale</b> → <b>veine PORTE</b> ; <b>veines pancréatico-duodénales inférieures</b> → <b>1ʳᵉ veine jéjunale</b> → <b>veine mésentérique supérieure</b> → veine porte<br>• <b>LYMPHATIQUES</b> : nœuds <b>pancréatico-duodénaux</b> (supérieurs et inférieurs) → nœuds <b>mésentériques supérieurs</b> et <b>cœliaques</b> → conduit thoracique. ⚠️ C'est le <b>chemin de diffusion des cancers de la tête du pancréas</b><br><br><b>INNERVATION :</b> <b>sympathique</b> (T5–T9 via les <b>nerfs grands splanchniques</b> → plexus cœliaque et mésentérique supérieur) et <b>parasympathique</b> (<b>nerf VAGUE X</b>) → plexus d'<b>Auerbach</b> (myentérique) et de <b>Meissner</b> (sous-muqueux).<br><br><b>PHYSIOLOGIE :</b> le duodénum est le <b>SIÈGE PRINCIPAL DE LA DIGESTION CHIMIQUE et de l'ABSORPTION</b> :<br>• Il reçoit la <b>bile</b> (émulsification des lipides) et le <b>suc pancréatique</b> (amylase, lipase, trypsine, chymotrypsine, bicarbonates)<br>• <b>Absorption du FER (Fe²⁺) et du CALCIUM</b> — principalement dans le duodénum ⚠️ (d'où l'anémie ferriprive après bypass gastrique)<br>• <b>C'est le siège de l'ulcère duodénal</b> (Helicobacter pylori, AINS)","t":"anato-2026 EXAM-2026"},{"q":"Décris le <b>STERNUM</b> (plan complet).","a":"<b>DÉFINITION :</b> os <b>IMPAIR, SYMÉTRIQUE, PLAT</b>, situé à la partie <b>ANTÉRIEURE ET MÉDIANE</b> du <b>thorax</b>. Il forme, avec les <b>12 paires de côtes</b> et les <b>12 vertèbres thoraciques</b>, la <b>CAGE THORACIQUE</b>. C'est un os <b>superficiel</b> (palpable sous la peau).<br><br><b>RÔLES :</b><br>• <b>Protection</b> du cœur, des poumons et des gros vaisseaux<br>• <b>Insertion</b> des muscles pectoraux, du diaphragme, des muscles sous-hyoïdiens (sterno-hyoïdien, sterno-thyroïdien)<br>• <b>POINT DE PONCTION DE LA MOELLE OSSEUSE</b> ⚠️ (sternum = site classique de la <b>ponction sternale</b> chez l'adulte, au niveau du corps, à cause de sa richesse en moelle rouge et de son accessibilité)<br>• <b>MASSAGE CARDIAQUE EXTERNE</b> (compression sur la moitié inférieure du corps)<br><br><b>DIMENSIONS :</b><br>• Longueur : <b>15 à 20 cm</b> (≈ 17 cm)<br>• Largeur : <b>5 à 6 cm</b> au niveau du corps ; plus large en haut<br>• Épaisseur : <b>1 à 2 cm</b><br>• Poids : <b>≈ 60 g</b><br><br><b>LES 3 PARTIES ⚠️ QUESTION DE BASE :</b><br>1. <b>MANUBRIUM (poignée)</b> — partie <b>SUPÉRIEURE</b>, <b>quadrangulaire</b>, la plus <b>épaisse</b> et la plus <b>large</b>. De <b>T3 à T4</b>.<br>&nbsp;&nbsp;• <b>Incisure (échancrure) jugulaire / sus-sternale</b> : encoche médiane sur le bord supérieur, palpable<br>&nbsp;&nbsp;• <b>Incisures claviculaires</b> : de part et d'autre de l'incisure jugulaire → s'articulent avec les <b>clavicules</b> (<b>articulation sterno-costo-claviculaire</b> = seule articulation entre le squelette axial et le membre supérieur)<br>&nbsp;&nbsp;• Face antérieure : insertion du <b>sterno-cléido-mastoïdien</b> (en haut), du <b>grand pectoral</b><br>&nbsp;&nbsp;• Bords latéraux : facettes pour le <b>1ᵉʳ cartilage costal</b> (synchondrose, immobile) et l'encoche pour le <b>2ᵉ cartilage costal</b><br>2. <b>CORPS (corpus sterni)</b> — partie <b>MOYENNE</b>, la plus <b>LONGUE</b>, <b>aplatie</b>, <b>allongée</b>. De <b>T5 à T9</b>.<br>&nbsp;&nbsp;• Formé de <b>4 sternèbres (segmentes)</b> soudées — la fusion est complète vers <b>25–40 ans</b><br>&nbsp;&nbsp;• Face antérieure : <b>3 crêtes transversales</b> (vestiges des soudures) ; insertion du <b>grand pectoral</b> (latéralement)<br>&nbsp;&nbsp;• Bords latéraux : <b>7 incisures costales</b> pour les cartilages des côtes <b>2 à 7</b> (la 2ᵉ à la jonction manubrio-corporale, la 7ᵉ à la jonction corpéo-xiphoïdienne)<br>&nbsp;&nbsp;• ⚠️ <b>ANGLE DE LOUIS (angle sternal, angle de Ludovic)</b> : la <b>saillie transversale à la jonction MANUBRIUM / CORPS</b> — palpable cliniquement ⚠️. C'est un <b>REPERE FONDAMENTAL</b> : il correspond au disque <b>T4–T5</b> et permet de compter les côtes (le 2ᵉ cartilage costal s'y articule) et les espaces intercostaux.<br>3. <b>PROCESSUS XIPHOÏDE (appendice xiphoïde)</b> — partie <b>INFÉRIEURE</b>, la plus <b>PETITE</b>, <b>mince</b>, de forme <b>variable</b> (pointue, triangulaire, bifide, parfois perforée). En regard de <b>T10</b>.<br>&nbsp;&nbsp;• <b>CARTILAGINEUSE chez l'enfant</b>, s'<b>ossifie vers 40 ans</b> et se <b>soude au corps vers 60 ans</b> (synostose xipho-sternale)<br>&nbsp;&nbsp;• Insertion : <b>diaphragme</b> (faisceaux xiphoïdiens), <b>muscle droit de l'abdomen</b> (ligne blanche), <b>muscles petits pectoraux / transversus thoracis</b><br>&nbsp;&nbsp;• ⚠️ <b>FRAGILE</b> — risque de fracture lors du <b>massage cardiaque</b> → peut léser le <b>foie</b><br><br><b>LES 2 ARTICULATIONS STERNALES :</b><br>• <b>SYNCHONDROSE MANUBRIO-STERNALE</b> (articulation de Louis) : entre manubrium et corps, <b>amphiarthrose</b> (semi-mobile), formant l'<b>angle de Louis</b> (≈ 160°, ouvert en arrière)<br>• <b>SYNCHONDROSE XIPHO-STERNALE</b> : entre corps et xiphoïde, <b>se soude avec l'âge</b><br><br><b>STRUCTURE :</b> os <b>PLAT</b> — 2 lames d'<b>os compact (cortical)</b> minces, renfermant une <b>spongiose épaisse, très riche en MOELLE OSSEUSE ROUGE (hématopoïétique)</b> chez l'adulte ⚠️ — d'où son utilisation pour la <b>ponction-biopsie</b>.<br><br><b>VASCULARISATION :</b><br>• <b>ARTÈRES</b> : <b>artère thoracique interne ( mammaire interne)</b>, branche de l'<b>artère subclavière</b> — descend verticalement à <b>1 cm du bord latéral du sternum</b>, en arrière des 6 premiers cartilages costaux, et donne des <b>branches sternales</b> ; + <b>artères intercostales postérieures</b> (branches de l'aorte thoracique) ; + <b>artère péricardio-phrénique</b>. L'artère thoracique interne se termine en <b>artère musculo-phrénique</b> et <b>artère épigastrique supérieure</b>.<br>• <b>VEINES</b> : <b>veines thoraciques internes</b> → veines brachio-céphaliques → veine cave supérieure ; réseau veineux <b>pré- et rétro-sternal</b><br>• <b>LYMPHATIQUES</b> : nœuds <b>parasternaux (thoraciques internes)</b> → troncs broncho-médiastinaux → canal thoracique (à gauche) ou grande veine lymphatique (à droite). ⚠️ Voie de drainage du <b>cancer du sein</b> (quadrant médial)<br><br><b>INNERVATION :</b> <b>nerfs intercostaux</b> (rameaux des <b>T1 à T6/T7</b>), branches des nerfs spinaux thoraciques, et rameaux du <b>plexus cervical superficiel</b> (pour le manubrium).<br><br><b>RAPPORTS :</b><br>• <b>EN AVANT</b> : peau, tissu cellulaire sous-cutané, fascia pectoral, <b>muscles grands pectoraux</b>, périoste<br>• <b>EN ARRIÈRE</b> : <b>médiastin antérieur</b> — thymus (chez l'enfant), <b>cœur et péricarde</b>, <b>gros vaisseaux</b> (aorte, veine cave supérieure, tronc pulmonaire), <b>muscle transversus thoracis (sterno-costal)</b>, plèvre et poumons (bords antérieurs), artères thoraciques internes<br>• ⚠️ Derrière le manubrium : l'<b>arc aortique</b> et le <b>tronc brachio-céphalique</b> ; derrière l'angle de Louis : la <b>bifurcation trachéale (carène)</b><br><br>⚠️ <b>ANOMALIES CONGÉNITALES :</b><br>• <b>PECTUS EXCAVATUM</b> : sternum <b>enfoncé</b> (dépression), l'anomalie la plus fréquente<br>• <b>PECTUS CARINATUM</b> : sternum <b>proéminent</b> (« poitrine de pigeon »)<br>• <b>STERNUM BIFIDE</b> : défaut de fusion des deux bourgeons sternaux","t":"anato-2026 EXAM-2026"},{"q":"Décris la <b>PLÈVRE</b> et les <b>culs-de-sac pleuraux</b> (plan complet).","a":"<b>DÉFINITION :</b> <b>membrane SÉREUSE</b> qui enveloppe les <b>poumons</b> et tapisse la <b>cavité thoracique</b>. Elle délimite un espace <b>VIRTUEL</b> (la cavité pleurale) contenant une mince pellicule de <b>liquide pleural</b>.<br><br><b>LES 2 FEUILLETS ⚠️ QUESTION DE BASE :</b><br>1. <b>PLÈVRE VISCÉRALE (pulmonaire)</b> : adhère <b>INTIMEMENT</b> à la surface du poumon, s'invagine dans les <b>fissures</b> interlobaires. Elle se réfléchit au niveau du <b>HILE</b> pour devenir la plèvre pariétale (formant le <b>ligament pulmonaire</b>, triangulaire, en bas du hile). ⚠️ <b>NON INNERVÉE par des fibres sensitives somatiques</b> → elle est <b>INDOLORE</b> ; elle reçoit son innervation du <b>système nerveux autonome</b>. Elle est <b>ADHÉRENTE</b> et ne peut pas être disséquée facilement.<br>2. <b>PLÈVRE PARIÉTALE</b> : tapisse la <b>paroi thoracique</b>, le <b>médiastin</b> et le <b>diaphragme</b>. Elle est <b>DÉCOLLABLE</b>. ⚠️ Elle est <b>RICHEMENT INNERVÉE EN FIBRES SENSITIVES SOMATIQUES</b> → elle est <b>TRÈS DOULOUREUSE</b> (douleur de la pleurésie, douleur latérale thoracique).<br><br><b>LES 4 PORTIONS DE LA PLÈVRE PARIÉTALE :</b><br>• <b>PLÈVRE COSTALE</b> : tapisse la face interne des côtes, des cartilages costaux et des espaces intercostaux (en dedans du fascia endothoracique)<br>• <b>PLÈVRE DIAPHRAGMATIQUE</b> : recouvre la face supérieure du diaphragme<br>• <b>PLÈVRE MÉDIASTINALE</b> : tapisse les faces latérales du médiastin ; elle se réfléchit autour du hile<br>• <b>PLÈVRE CERVICALE (DÔME / COUPOLE PLEURALE)</b> : dépasse l'orifice supérieur du thorax, remonte <b>2 à 3 cm au-dessus de la clavicule</b> (à hauteur du col de la 1ʳᵉ côte), recouverte par le <b>fascia suprapleural (de Sibson)</b> et par le <b>muscle scalène minimum</b> ⚠️ → <b>RISQUE DE PNEUMOTHORAX</b> lors d'un traumatisme du cou ou d'une ponction sous-clavière<br><br><b>CAVITÉ PLEURALE (espace pleural) :</b><br>• Espace <b>VIRTUEL</b> entre les deux feuillets<br>• Contient <b>≈ 10 à 20 mL de LIQUIDE PLEURAL</b> — un <b>film séreux</b> produit par la plèvre pariétale et résorbé par les lymphatiques<br>• <b>PRESSION NÉGATIVE (subatmosphérique)</b> : <b>−4 à −8 cmH₂O</b> au repos, descendant jusqu'à <b>−20 à −40 cmH₂O</b> lors d'une inspiration forcée ⚠️<br>• Cette <b>dépression</b> est ce qui <b>MAINTIENT LE POUMON EXPANSÉ</b> contre la paroi (le poumon a une tendance naturelle à la rétraction élastique)<br>• Rôle du liquide : <b>lubrification</b> (permet le glissement des feuillets) et <b>adhérence</b> par tension superficielle<br>• ⚠️ Si de l'<b>AIR</b> entre → <b>PNEUMOTHORAX</b> → la pression devient atmosphérique → le poumon <b>se rétracte (collapsus/atélectasie)</b><br>• Si du <b>LIQUIDE</b> s'accumule → <b>ÉPANCHEMENT PLEURAL (pleurésie)</b> : transsudat (insuffisance cardiaque) ou exsudat (infection, cancer)<br><br><b>LES CULS-DE-SAC (récessus / sinus) PLEURAUX ⚠️ QUESTION TRÈS FRÉQUENTE :</b><br>Ce sont des <b>espaces où la plèvre pariétale se réfléchit</b>, et où le poumon <b>ne pénètre PAS</b> au repos (il n'y pénètre qu'à l'inspiration profonde). Ce sont donc des <b>zones où le liquide s'accumule en premier</b>.<br><br>1. <b>CUL-DE-SAC COSTO-DIAPHRAGMATIQUE</b> — <b>LE PLUS IMPORTANT ET LE PLUS BAS</b> ✅<br>&nbsp;&nbsp;• Entre la plèvre <b>costale</b> et la plèvre <b>diaphragmatique</b><br>&nbsp;&nbsp;• Situé à la partie <b>inféro-latérale</b> de la cavité pleurale<br>&nbsp;&nbsp;• S'étend jusqu'à la <b>8ᵉ côte sur la ligne médio-claviculaire</b>, la <b>10ᵉ côte sur la ligne axillaire moyenne</b>, la <b>12ᵉ côte en arrière (paravertébrale)</b><br>&nbsp;&nbsp;• ⚠️ C'est <b>là que le liquide s'accumule en position debout</b> (gravité) → c'est le site de la <b>ponction pleurale</b> et le premier lieu où disparaît le murmure vésiculaire<br>2. <b>CUL-DE-SAC COSTO-MÉDIASTINAL (antérieur)</b><br>&nbsp;&nbsp;• Entre la plèvre <b>costale</b> et la plèvre <b>médiastinale</b>, en avant, de part et d'autre du sternum<br>&nbsp;&nbsp;• Le poumon y pénètre à l'inspiration<br>&nbsp;&nbsp;• ⚠️ Au niveau de ce recessus, les deux plèvres médiastinales se rapprochent en haut et s'écartent en bas à <b>gauche</b> — délimitant l'<b>INCISURE CARDIAQUE</b> et la zone du <b>triangle de percussion de la matité cardiaque</b><br>3. <b>CUL-DE-SAC DIAPHRAGMATICO-MÉDIASTINAL</b> — entre la plèvre diaphragmatique et médiastinale (petit)<br>4. <b>CUL-DE-SAC VERTEBRO-COSTAL (postérieur)</b> — entre la plèvre costale et la plèvre vertébrale/médiastinale postérieure<br><br><b>LIMITES DE LA PLÈVRE PARIÉTALE (projection sur la paroi) ⚠️ :</b><br>• <b>Sommet (dôme)</b> : <b>3 cm au-dessus de la clavicule</b>, niveau du col de la 1ʳᵉ côte (T1)<br>• <b>En avant</b> : ligne médiane, derrière le sternum, descend jusqu'à la <b>6ᵉ côte</b> (articulation sterno-costale)<br>• <b>Sur la ligne médio-claviculaire</b> : <b>8ᵉ côte</b><br>• <b>Sur la ligne axillaire moyenne</b> : <b>10ᵉ côte</b><br>• <b>Sur la ligne scapulaire / paravertébrale</b> : <b>12ᵉ côte</b> (apophyse transverse de T12)<br><br>⚠️ <b>RÈGLE DES « 2, 4, 6, 8, 10, 12 » :</b> le <b>POUMON</b> se termine en avant à la <b>6ᵉ côte</b>, sur la ligne médio-claviculaire à la <b>6ᵉ–8ᵉ</b>, sur la ligne axillaire à la <b>8ᵉ–10ᵉ</b>, en arrière à la <b>10ᵉ</b> (épine de T10) ; la <b>PLÈVRE</b> descend toujours <b>2 côtes plus bas</b> (8 / 10 / 12). Ce <b>décalage de 2 côtes</b> = l'espace des <b>culs-de-sac</b>.<br><br><b>VASCULARISATION :</b><br>• <b>PLÈVRE VISCÉRALE</b> : <b>circulation PULMONAIRE</b> — artères <b>bronchiques</b> (branches de l'aorte thoracique) et capillaires pulmonaires ; veines → <b>veines pulmonaires</b> (sang oxygéné)<br>• <b>PLÈVRE PARIÉTALE</b> : <b>circulation SYSTÉMIQUE</b> — artères <b>intercostales postérieures</b> (aorte), <b>thoracique interne</b> (subclavière), <b>péricardio-phrénique</b>, <b>musculo-phrénique</b>, <b>phrénique supérieure/inférieure</b> ; veines → veines intercostales → veine cave supérieure<br>• <b>LYMPHATIQUES</b> : ⚠️ la plèvre <b>pariétale</b> possède des <b>stomates</b> qui drainent vers les nœuds <b>parasternaux, intercostaux, phréniques et médiastinaux</b> ; c'est la <b>voie principale de résorption du liquide pleural</b><br><br><b>INNERVATION ⚠️ DIFFÉRENCE FONDAMENTALE :</b><br>• <b>PLÈVRE PARIÉTALE COSTALE et PÉRIPHÉRIQUE du diaphragme</b> : <b>NERFS INTERCOSTAUX (T1–T11)</b> → douleur <b>LOCALISÉE, LATÉRALE, à type de POINT DE CÔTÉ</b>, augmentée à l'inspiration et à la toux<br>• <b>PLÈVRE PARIÉTALE CENTRALE du diaphragme et MÉDIASTINALE</b> : <b>NERF PHRÉNIQUE (C3–C4–C5)</b> ⚠️ → douleur <b>PROJETÉE vers l'ÉPAULE</b> (dermatomes C3–C5) et le cou<br>• <b>PLÈVRE VISCÉRALE</b> : <b>INNERVATION AUTONOME (sympathique et vague)</b>, <b>PAS de fibres nociceptives somatiques</b> → <b>INDOLORE</b> ⚠️<br><br><b>EMBRYOLOGIE :</b> dérivée du <b>mésoderme extra-embryonnaire / somatopleure et splanchnopleure</b> (mésenchyme des cavités cœlomiques).<br><br><b>STRUCTURE HISTOLOGIQUE :</b> <b>mésothélium</b> (épithélium pavimenteux simple) + tissu conjonctif lâche sous-mésothélial (riche en fibres élastiques, vaisseaux, lymphatiques).<br><br>⚠️ <b>CLINIQUE :</b><br>• <b>MÉSOTHÉLIOME PLEURAL MALIN</b> : tumeur liée à l'<b>AMIANTE (asbeste)</b>, pronostic très sombre, latence de 20–40 ans<br>• <b>PONCTION PLEURALE</b> : on pique dans le <b>7ᵉ ou 8ᵉ espace intercostal, sur la ligne axillaire moyenne ou postérieure</b>, en longeant le <b>BORD SUPÉRIEUR de la côte inférieure</b> ⚠️ — car le <b>paquet vasculo-nerveux intercostal (veine, artère, nerf — VAN, de haut en bas)</b> chemine dans le <b>sillon costal, au BORD INFÉRIEUR de la côte supérieure</b><br>• <b>SYMPHYSE PLEURALE (pleurodèse)</b> : adhérence des deux feuillets après inflammation — abolit la cavité pleurale<br>• <b>FROTTEMENT PLEURAL</b> : signe auscultatoire de la pleurésie fibrineuse","t":"anato-2026 EXAM-2026"},{"q":"<b>THORAX</b> — Quelles sont les limites et la subdivision du <b>MÉDIASTIN</b> ?","a":"<b>DÉFINITION :</b> espace <b>MÉDIAN</b> de la cavité thoracique, situé <b>ENTRE LES DEUX CAVITÉS PLEURALES</b> (les deux poumons), contenant <b>tous les viscères et structures du thorax SAUF LES POUMONS</b>.<br><br><b>LIMITES ⚠️ QUESTION FRÉQUENTE :</b><br>• <b>EN AVANT</b> : face postérieure du <b>STERNUM</b> et des cartilages costaux (de la 1ʳᵉ à la 7ᵉ)<br>• <b>EN ARRIÈRE</b> : face antérieure des <b>CORPS VERTÉBRAUX THORACIQUES (T1 à T12)</b> et des disques intervertébraux (avec les gouttières costo-vertébrales)<br>• <b>SUR LES CÔTÉS (LATÉRALEMENT)</b> : les <b>PLÈVRES MÉDIASTINALES</b> (médias pleuraux)<br>• <b>EN HAUT</b> : l'<b>ORIFICE SUPÉRIEUR DU THORAX (détroit thoracique supérieur)</b> — plan oblique passant par le disque <b>T4/T5</b>, la <b>1ʳᵉ paire de côtes</b> et le <b>bord supérieur du manubrium sternal</b>. Il communique avec le cou<br>• <b>EN BAS</b> : le <b>DIAPHRAGME</b> (coupole, en regard de T12)<br><br><b>SUBDIVISION CLASSIQUE ⚠️ : on divise d'abord par un PLAN HORIZONTAL passant par l'ANGLE DE LOUIS (T4–T5) :</b><br><br><b>I. MÉDIASTIN SUPÉRIEUR</b> — au-dessus du plan T4–T5 (entre le détroit supérieur et l'angle de Louis)<br>Contient :<br>• <b>THYMUS</b> (chez l'enfant) / reliquats graisseux (adulte)<br>• <b>ARC AORTIQUE (crosse de l'aorte)</b> et ses 3 branches : <b>tronc brachio-céphalique, artère carotide commune gauche, artère subclavière gauche</b><br>• <b>VEINE CAVE SUPÉRIEURE</b> (partie supérieure) et les <b>2 VEINES BRACHIO-CÉPHALIQUES</b><br>• <b>TRACHÉE</b> et sa <b>BIFURCATION (CARÈNE)</b> à T4–T5 ⚠️<br>• <b>ŒSOPHAGE</b> (partie supérieure) et le <b>canal thoracique</b><br>• <b>NERFS VAGUES (X)</b> et <b>NERFS PHRÉNIQUES (C3-C4-C5)</b>, nerfs laryngés récurrents<br>• <b>Tronc sympathique</b>, nœuds lymphatiques médiastinaux<br><br><b>II. MÉDIASTIN INFÉRIEUR</b> — au-dessous du plan T4–T5, jusqu'au diaphragme. Lui-même divisé en <b>3 compartiments</b> par rapport au <b>PÉRICARDE</b> :<br><br>&nbsp;&nbsp;<b>1. MÉDIASTIN INFÉRIEUR ANTÉRIEUR (pré-péricardique)</b> — entre le sternum et le péricarde<br>&nbsp;&nbsp;• <b>Très mince</b>, contient : graisse, <b>reliquats thymiques</b>, <b>nœuds lymphatiques parasternaux (thoraciques internes)</b>, <b>artères thoraciques internes</b>, portion inférieure de la veine cave supérieure<br>&nbsp;&nbsp;• ⚠️ C'est là que se situent les <b>TÉRATOMES</b> et les <b>LYMPHOMES</b> (avec le thymus = médiastin antéro-supérieur)<br><br>&nbsp;&nbsp;<b>2. MÉDIASTIN INFÉRIEUR MOYEN (viscéral / péricardique)</b> — le <b>plus grand</b>, occupé par le <b>PÉRICARDE</b> et son contenu<br>&nbsp;&nbsp;• <b>CŒUR</b> et <b>PÉRICARDE</b><br>• <b>RACINES DES GROS VAISSEAUX</b> : aorte ascendante, tronc pulmonaire et ses 2 branches, veines caves supérieure et inférieure, les <b>4 veines pulmonaires</b><br>• <b>BIFURCATION TRACHÉALE</b> et les <b>2 BRONCHES SOUCHES (principales)</b><br>• <b>Nerfs phréniques</b> (passent en avant des racines pulmonaires, entre le péricarde et la plèvre médiastinale) ⚠️<br>• <b>Nœuds lymphatiques trachéo-bronchiques</b><br><br>&nbsp;&nbsp;<b>3. MÉDIASTIN INFÉRIEUR POSTÉRIEUR (rétro-péricardique)</b> — entre le péricarde en avant et les vertèbres thoraciques en arrière<br>&nbsp;&nbsp;• <b>ŒSOPHAGE</b> (portion thoracique descendante) + plexus œsophagien<br>• <b>AORTE THORACIQUE DESCENDANTE</b> ⚠️ (elle se situe à <b>GAUCHE</b> puis devient médiane en passant dans l'orifice aortique du diaphragme à T12)<br>• <b>CANAL THORACIQUE (de Pecquet)</b> — le plus gros vaisseau lymphatique, monte entre l'aorte et la veine azygos, traverse le diaphragme par l'<b>orifice aortique</b><br>• <b>SYSTÈME AZYGOS</b> : <b>veine azygos</b> (à droite), <b>hémiazygos</b> et <b>hémiazygos accessoire</b> (à gauche)<br>• <b>NERFS VAGUES (X)</b> — ⚠️ ils passent <b>EN ARRIÈRE des racines pulmonaires</b> (contrairement aux phréniques qui passent en avant)<br>• <b>TRONCS SYMPATHIQUES THORACIQUES</b> + <b>nerfs splanchniques (grand, petit, inférieur)</b><br>• <b>Nœuds lymphatiques médiastinaux postérieurs</b><br><br>⚠️ <b>NOUVELLE CLASSIFICATION (imagerie / ITMIG) :</b> la tomodensitométrie moderne utilise une division en <b>3 compartiments</b> seulement :<br>• <b>MÉDIASTIN ANTÉRIEUR (pré-vasculaire)</b> — devant les gros vaisseaux : thymus, graisse, nœuds → <b>tumeurs : thymome, tératome, thyroïde plongeante, lymphome (« les 4 T »)</b><br>• <b>MÉDIASTIN MOYEN (viscéral)</b> — cœur, trachée, œsophage, gros vaisseaux<br>• <b>MÉDIASTIN POSTÉRIEUR (para-vertébral)</b> — gouttières costo-vertébrales → <b>tumeurs neurogènes (schwannome, neurofibrome, ganglioneurome)</b><br><br><b>RÈGLE DES TUMEURS DU MÉDIASTIN SELON L'ÂGE ⚠️ :</b><br>• <b>ENFANT</b> : médiastin postérieur = <b>tumeurs neurogènes</b> ; médiastin antérieur = <b>lymphome, tératome</b><br>• <b>ADULTE</b> : médiastin antérieur = <b>thymome, lymphome, goitre plongeant, tératome</b> (« <b>4 T</b> ») ; médiastin moyen = <b>kystes bronchogéniques</b> ; médiastin postérieur = <b>tumeurs neurogènes</b><br><br><b>MÉDIASTIN — SIGNES CLINIQUES :</b> compression de la veine cave supérieure → <b>SYNDROME CAVAL SUPÉRIEUR</b> (œdème en pèlerine, cyanose, circulation collatérale) ; compression du nerf laryngé récurrent → <b>DISPHONIE (voix rauque)</b> ; compression de l'œsophage → <b>DYSPHAGIE</b> ; compression trachéale → <b>DYSPNÉE, CORNAGE, TIRAGE</b>.","t":"anato-2026 EXAM-2026"},{"q":"<b>ANATOMIE — LES DIMENSIONS CHIFFRÉES</b> à retenir par cœur (rapportent le plus de points).","a":"⚠️ <b>Le correcteur compte les chiffres.</b> Voici la liste minimale à connaître par cœur :<br><br><b>REIN</b> : <b>12 × 6 × 3 cm</b>, <b>150 g</b>, <b>L1–L3</b>, <b>1 à 1,3 million de néphrons</b>, débit sanguin <b>1,2 L/min (20–25 % du DC)</b>, <b>8 à 18 pyramides</b><br><b>URETÈRE</b> : <b>25–30 cm</b>, <b>3–5 mm</b> de diamètre, <b>3 portions</b>, <b>3 rétrécissements</b>, paroi <b>3 tuniques</b><br><b>VESSIE</b> : capacité <b>300–500 mL</b> (jusqu'à 800 mL), envie d'uriner dès <b>250 mL</b><br><b>RATE</b> : <b>12–13 × 7–8 × 3–4 cm</b>, <b>150–200 g</b>, projetée entre la <b>9ᵉ et la 11ᵉ côte</b> (axe de la 10ᵉ)<br><b>DUODÉNUM</b> : <b>25 cm</b> (= <b>12 travers de doigt</b>), <b>4–5 cm</b> de diamètre, <b>4 portions</b>, grande papille à <b>8–10 cm du pylore</b>, petite papille <b>2 cm au-dessus</b><br><b>ŒSOPHAGE</b> : <b>25 cm</b> (du cartilage cricoïde C6 à la cardias T11), <b>3 rétrécissements</b> (cricopharyngien à <b>15 cm</b>, broncho-aortique à <b>25 cm</b>, diaphragmatique à <b>40 cm</b>)<br><b>ESTOMAC</b> : capacité <b>1,5 L</b> (jusqu'à 4 L), de <b>T10 à L1/L2</b><br><b>FOIE</b> : <b>1,5 kg</b> (la <b>plus grosse glande</b> de l'organisme), <b>28 × 16 × 8 cm</b>, reçoit <b>25 % du débit cardiaque</b> (75 % par la veine porte, 25 % par l'artère hépatique), <b>2 lobes</b> (droit/gauche) anatomiques et <b>4 secteurs</b> fonctionnels, <b>8 segments de Couinaud</b><br><b>PANCRÉAS</b> : <b>15 cm</b> de long, <b>60–100 g</b>, de <b>L1 à L2</b>, <b>glande mixte (endocrine + exocrine)</b>, <b>1 à 2 L de suc/jour</b><br><b>INTESTIN GRÊLE</b> : <b>6 à 7 m</b> in vivo (4 m post-mortem), surface d'absorption <b>≈ 200–300 m²</b><br><b>GROS INTESTIN</b> : <b>1,5 m</b>, diamètre <b>6–8 cm</b><br><b>STERNUM</b> : <b>15–20 cm</b> de long, <b>3 parties</b>, <b>≈ 60 g</b>, corps formé de <b>4 sternèbres</b><br><b>CÔTES</b> : <b>12 paires</b> — <b>7 vraies</b> (sternales), <b>3 fausses</b> (costales 8-9-10, unies au 7ᵉ cartilage), <b>2 flottantes</b> (11 et 12)<br><b>CAGE THORACIQUE</b> : <b>12 vertèbres thoraciques</b>, <b>12 paires de côtes</b>, <b>1 sternum</b><br><b>POUMON</b> : <b>600 g (D)</b> et <b>500 g (G)</b>, poumon droit <b>3 lobes / 2 fissures / 10 segments</b>, gauche <b>2 lobes / 1 fissure / 8–9 segments</b>, capacité pulmonaire totale <b>6 L</b>, volume courant <b>500 mL</b><br><b>CŒUR</b> : <b>250–350 g</b>, <b>12 × 8 × 6 cm</b> (volume d'un poing), débit cardiaque <b>5 L/min</b>, <b>4 cavités</b>, <b>4 valves</b><br><b>PLÈVRE</b> : <b>10–20 mL de liquide</b>, pression <b>−4 à −8 cmH₂O</b><br><b>DIAPHRAGME</b> : <b>3 orifices</b> — <b>caval (T8)</b>, <b>œsophagien (T10)</b>, <b>aortique (T12)</b> ⚠️ règle mnémotechnique : « <b>T8 la veine cave (8 lettres : VEINE CAVE = 8)</b>, <b>T10 œsophage (10 lettres : OESOPHAGE = 9… retenir 8-10-12)</b>, <b>T12 aorte</b> » — mieux : « <b>Je bois à 8, je mange à 10, je digère à 12</b> »<br><br>⚠️ <b>MÉTHODE :</b> ne tente <b>PAS</b> d'apprendre tout ça d'un coup. Fais <b>une fiche Anki par organe</b> avec ses 4–6 chiffres, et révise <b>5 min par jour</b>.","t":"anato-2026 EXAM-2026 STRATEGIE"},{"q":"<b>ANATOMIE — VASCULARISATION</b> : rappelle les branches du <b>TRONC CŒLIAQUE</b> et de l'<b>ARTÈRE MÉSSENTÉRIQUE SUPÉRIEURE</b>.","a":"<b>TRONC CŒLIAQUE (artère cœliaque, de Haller)</b> — première branche <b>impaire et viscérale</b> de l'<b>aorte abdominale</b>, naît en <b>T12–L1</b>, juste sous l'orifice aortique du diaphragme, courte (<b>1 à 2 cm</b>) et épaisse. Il vascularise l'<b>INTESTIN ANTÉRIEUR (foregut)</b>.<br><br>⚠️ <b>IL SE DIVISE EN 3 BRANCHES (la « triade de Haller ») :</b><br>1. <b>ARTÈRE GASTRIQUE GAUCHE (coronaire stomachique)</b> — la <b>plus petite</b>, monte vers la cardias puis descend le long de la <b>petite courbure</b> de l'estomac, s'anastomosant avec l'<b>artère gastrique droite</b>. Elle donne des <b>branches œsophagiennes</b>. ⚠️ Elle est la <b>1ʳᵉ branche</b> et peut naître directement de l'aorte.<br>2. <b>ARTÈRE SPLÉNIQUE</b> — la <b>plus grosse</b> des 3, trajet <b>TORTUEUX (flexueuse)</b> le long du <b>bord supérieur du pancréas</b>, dans le ligament spléno-rénal, jusqu'au <b>hile de la rate</b>. Elle donne :<br>&nbsp;&nbsp;• <b>Branches pancréatiques</b> : artère <b>dorsale du pancréas</b>, <b>grande pancréatique</b>, artère de la <b>queue du pancréas</b><br>&nbsp;&nbsp;• <b>Artère gastro-épiploïque (gastro-omentale) GAUCHE</b> — longe la <b>grande courbure</b><br>&nbsp;&nbsp;• <b>Artères gastriques courtes (vasa brevia)</b> — 5 à 7 branches pour le <b>fundus</b> de l'estomac<br>&nbsp;&nbsp;• <b>Artère polaire supérieure</b> de la rate (inconstante)<br>3. <b>ARTÈRE HÉPATIQUE COMMUNE</b> — se dirige à droite, donne l'<b>artère gastro-duodénale</b>, puis devient l'<b>ARTÈRE HÉPATIQUE PROPRE</b> qui monte dans le <b>ligament hépato-duodénal (bord libre du petit omentum)</b> — ⚠️ dans le <b>TRIANGLE DE CALOT</b> / pédicule hépatique, avec la <b>veine porte en arrière</b> et le <b>canal cholédoque à droite</b>. Elle donne :<br>&nbsp;&nbsp;• <b>ARTÈRE GASTRO-DUODÉNALE</b> → descend derrière le <b>1ᵉʳ duodénum</b> ⚠️ (un ulcère duodénal postérieur peut l'éroder → <b>hémorragie digestive massive</b>) → se divise en <b>artère gastro-épiploïque DROITE</b> (le long de la grande courbure) et en <b>artères pancréatico-duodénales SUPÉRIEURES (antérieure + postérieure)</b><br>&nbsp;&nbsp;• <b>ARTÈRE GASTRIQUE DROITE (pylorique)</b> — petite, longe la petite courbure<br>&nbsp;&nbsp;• <b>ARTÈRE CYSTIQUE</b> — vascularise la <b>vésicule biliaire</b>, naît habituellement de la branche <b>droite</b> de l'artère hépatique propre, dans le <b>triangle de Calot</b> (limites : canal cystique en bas, canal hépatique commun à gauche, bord inférieur du foie en haut) ⚠️ repère chirurgical de la <b>cholécystectomie<br>&nbsp;&nbsp;• Branches <b>droite</b> et <b>gauche</b> pour le foie<br><br><b>ARTÈRE MÉSSENTÉRIQUE SUPÉRIEURE (AMS)</b> — naît de l'<b>aorte abdominale en L1</b>, <b>1 cm sous le tronc cœliaque</b>. Elle vascularise l'<b>INTESTIN MOYEN (midgut)</b> : du <b>duodénum (2ᵉ portion)</b> jusqu'aux <b>2/3 proximaux du côlon transverse</b>. Elle passe <b>EN ARRIÈRE du col du pancréas</b>, puis <b>EN AVANT du 3ᵉ duodénum (D3)</b> ⚠️ (la <b>pince aorto-mésentérique</b> → syndrome de Wilkie), et chemine dans la racine du <b>mésentère</b> (oblique en bas et à droite).<br><br><b>SES BRANCHES :</b><br>• <b>ARTÈRES PANCRÉATICO-DUODÉNALES INFÉRIEURES (antérieure + postérieure)</b> — les <b>premières branches</b>, vascularisent D2-D3-D4 et la tête du pancréas, <b>s'anastomosent avec les supérieures</b> (arcades pancréatico-duodénales)<br>• <b>ARTÈRES JÉJUNALES ET ILÉALES (artères intestinales)</b> — <b>15 à 18 branches</b> gauches, formant des <b>ARCADES ANASTOMOTIQUES</b> (1ʳᵉ, 2ᵉ, 3ᵉ rangée) puis des <b>VAISSEAUX DROITS (vasa recta)</b> qui gagnent l'intestin ⚠️ Le nombre d'arcades <b>augmente</b> et la longueur des vasa recta <b>augmente</b> du jéjunum vers l'iléon (critère de distinction)<br>• <b>ARTÈRE COLIQUE MOYENNE</b> — vascularise les <b>2/3 proximaux du côlon transverse</b><br>• <b>ARTÈRE COLIQUE DROITE</b> — vascularise le <b>côlon ascendant</b> (inconstante, naît parfois de l'iléo-colique)<br>• <b>ARTÈRE ILÉO-COLO-CÆCO-APPENDICULAIRE (iléo-colique)</b> — la <b>branche terminale droite</b>, vascularise l'<b>iléon terminal, le cæcum, l'appendice, le côlon ascendant</b>. Elle donne :<br>&nbsp;&nbsp;• <b>Artère appendiculaire (appendiculaire de Quénu)</b> ⚠️ — artère <b>TERMINALE</b>, chemine dans le <b>méso-appendice</b> → son occlusion (appendicite) entraîne une <b>nécrose de l'appendice</b> (risque de perforation/péritonite)<br>&nbsp;&nbsp;• Artères cæcales antérieure et postérieure, colique ascendante, iléale<br><br>⚠️ <b>RÈGLE GÉNÉRALE DE L'AORTE ABDOMINALE (branches IMPAIRES et viscérales) :</b><br>• <b>T12</b> — <b>TRONC CŒLIAQUE</b> (foregut)<br>• <b>L1</b> — <b>ARTÈRE MÉSSENTÉRIQUE SUPÉRIEURE</b> (midgut)<br>• <b>L3</b> — <b>ARTÈRE MÉSSENTÉRIQUE INFÉRIEURE</b> (hindgut : du 1/3 distal du côlon transverse jusqu'au rectum supérieur) — donne les artères <b>colique gauche</b>, <b>sigmoïdiennes</b> et <b>rectale supérieure (hémorroïdaire supérieure)</b><br><br>⚠️ <b>ANASTOMOSE CRUCIALE — L'ARCADE DE RIOLAN (artère mésentérique sinueuse) et l'ARTÈRE MARGINALE DE DRUMMOND</b> : elles relient l'<b>AMS</b> (colique moyenne) à l'<b>AMI</b> (colique gauche) au niveau de l'<b>angle colique gauche (flexure splénique, angle de Griffith)</b> → voie de suppléance en cas d'occlusion. ⚠️ Cette zone est un <b>point faible</b> : c'est le siège classique de l'<b>ISCÉMIE MÉSSENTÉRIQUE</b> et des <b>colites ischémiques</b>.","t":"anato-2026 EXAM-2026"},{"q":"<b>ANATOMIE — MÉTHODE</b> : comment gérer l'épreuve le jour J (3 profs, copies de couleurs différentes) ?","a":"⚠️ <b>CE QUI A ÉTÉ VÉRIFIÉ :</b> l'épreuve d'anatomie est distribuée en <b>3 parties</b>, une par professeur, avec des <b>copies de couleurs différentes</b>. Chaque prof pose sur <b>SON domaine</b>, et ces domaines <b>se répètent d'année en année</b>.<br><br><b>1. AVANT L'EXAMEN — LA PRIORISATION :</b><br>Il y a seulement <b>≈ 12 structures récurrentes</b>. Apprends-les <b>DANS L'ORDRE</b> :<br>• <b>Niveau 1 (obligatoire, rapporte le plus)</b> : <b>REIN · RATE · DUODÉNUM · STERNUM · PLÈVRE</b><br>• <b>Niveau 2</b> : <b>URETÈRE · PANCRÉAS · ŒSOPHAGE · MÉDIASTIN</b><br>• <b>Niveau 3</b> : <b>VESSIE · PAROI THORACIQUE · QUADRANTS</b><br><br><b>2. POUR CHAQUE STRUCTURE, FICHE 5 ÉLÉMENTS :</b><br>a) <b>3 à 5 dimensions chiffrées</b> (longueur × largeur × épaisseur + poids)<br>b) <b>Le niveau vertébral</b> exact (T…, L…)<br>c) <b>Les 3 ou 4 subdivisions</b> (parties, portions, faces)<br>d) <b>Les 3 rapports essentiels</b> (avant, arrière, dedans/dehors)<br>e) <b>L'artère + la veine + le nerf</b> (origine précise)<br>→ Ça tient sur <b>UNE PAGE A4 par organe</b>.<br><br><b>3. LE JOUR DE L'EXAMEN :</b><br>• <b>Lis TOUS les énoncés des 3 feuilles d'abord</b> (5 min) — repère les verbes (« citer » vs « décrire ») et alloue le temps.<br>• <b>Réponds TOUJOURS en STRUCTURE</b> : écris les <b>titres du plan</b> (DÉFINITION / SITUATION / FORME / DIMENSIONS / RAPPORTS / VASCULARISATION) <b>avant de remplir</b>. Un correcteur voit tout de suite ce qui manque et donne les points partiels.<br>• <b>Mets les CHIFFRES EN PREMIER</b> et <b>souligne-les</b>.<br>• <b>Fais un SCHÉMA</b> même médiocre — <b>légendé</b>. Un schéma correct peut valoir 30–40 % de la note.<br>• <b>Ne laisse JAMAIS une question vide</b>. Écris au minimum la <b>définition</b> et la <b>situation</b> — ça vaut 1 à 2 points.<br>• ⚠️ <b>Respecte la couleur de copie</b> : ne mélange pas les réponses d'un prof sur la feuille d'un autre.<br>• <b>Utilise le vocabulaire EXACT</b> (Terminologia Anatomica) — « artère splénique » et non « artère de la rate », « hile » et non « porte ».<br><br><b>4. OBJECTIF RÉALISTE :</b> l'anatomie est un module à <b>rédaction</b> — <b>difficile d'avoir 18/20</b>, mais <b>très facile d'avoir 13–15/20</b> en maîtrisant 8 structures avec le plan et les chiffres. C'est <b>≈ 4 crédits</b>, donc ça compte, mais <b>ne lui consacre pas plus de 20 % de ton temps</b>.","t":"anato-2026 EXAM-2026 STRATEGIE"}]},{"id":"vocab-fr","nom":"📖 Vocabulaire français","src":"TON PROBLÈME N°1","ordre":10,"module":"—","desc":"91 mots savants expliqués en darija","cards":[{"q":"<b>Unité</b>","a":"<b>Grandeur mesurée</b> exprimée par une quantité de référence.<br>Ex. : le <b>mètre</b> (longueur), le <b>litre</b> (volume), la <b>mole</b> (quantité de matière).<br>⚠️ En sciences, une valeur <b>sans unité</b> = réponse fausse.","t":"fr-base"},{"q":"<b>Conversion</b>","a":"<b>Changer d'unité</b> sans changer la grandeur.<br>kilo (k) = ×1000 · centi (c) = ÷100 · milli (m) = ÷1000 · micro (μ) = ÷1 000 000<br><b>1 L = 1000 mL = 1 dm³</b> · <b>1 mL = 1 cm³ = 1000 μL</b>","t":"fr-base"},{"q":"<b>Notation scientifique</b>","a":"Écrire un nombre sous la forme <b>a × 10ⁿ</b> avec 1 ≤ a &lt; 10.<br>0,00034 = <b>3,4 × 10⁻⁴</b> · 45 000 = <b>4,5 × 10⁴</b><br>→ Indispensable pour les concentrations, les pH, la radioactivité.","t":"fr-base"},{"q":"<b>Chiffres significatifs</b>","a":"Chiffres <b>fiables</b> d'une mesure (tous les chiffres certains + 1 estimé).<br>0,00340 → <b>3 chiffres significatifs</b> (3, 4, 0 final)<br>→ Le résultat ne peut pas être plus précis que la mesure la moins précise.","t":"fr-base"},{"q":"<b>Puissance</b>","a":"<b>aⁿ</b> = a multiplié par lui-même n fois.<br>Règles : aⁿ × aᵐ = <b>aⁿ⁺ᵐ</b> · aⁿ ÷ aᵐ = <b>aⁿ⁻ᵐ</b> · a⁻ⁿ = <b>1/aⁿ</b> · a⁰ = <b>1</b>","t":"fr-base"},{"q":"<b>Racine carrée</b>","a":"√a = nombre qui, élevé au carré, donne a.<br>√9 = 3 · √(a×b) = √a × √b · √(10⁻⁶) = <b>10⁻³</b>","t":"fr-base"},{"q":"<b>Fraction</b>","a":"<b>a/b</b> = a divisé par b.<br>1/4 = 0,25 = <b>25 %</b><br>Même dénominateur pour additionner : a/c + b/c = (a+b)/c","t":"fr-base"},{"q":"<b>Pourcentage</b>","a":"<b>Partie pour 100</b>.<br>20 % de 150 = 0,20 × 150 = <b>30</b><br>Passer de % à fraction : 20 % = 20/100 = 0,2","t":"fr-base"},{"q":"<b>Proportionnalité</b>","a":"Deux grandeurs sont proportionnelles si leur <b>rapport est constant</b> (coefficient de proportionnalité k).<br>y = k·x → la représentation graphique est une <b>droite passant par l'origine</b>.","t":"fr-base"},{"q":"<b>Règle de trois</b>","a":"Méthode de calcul par proportionnalité.<br>Si 5 mL contiennent 10 mg → 100 mL contiennent x<br>x = (10 × 100) / 5 = <b>200 mg</b><br>→ Sert pour toutes les <b>dilutions</b>.","t":"fr-base"},{"q":"<b>Équation</b>","a":"<b>Égalité avec une inconnue</b>. On cherche la valeur qui rend l'égalité vraie.<br>2x + 6 = 14 → 2x = 8 → <b>x = 4</b><br>Règle : ce qu'on fait d'un côté, on le fait de l'autre.","t":"fr-base"},{"q":"<b>Système d'équations</b>","a":"Plusieurs équations avec plusieurs inconnues, à résoudre <b>simultanément</b>.<br>Méthodes : <b>substitution</b>, <b>combinaison</b> (addition).","t":"fr-base"},{"q":"<b>Logarithme décimal</b> (log₁₀)","a":"<b>log₁₀(x) = n</b> signifie <b>10ⁿ = x</b>.<br>log(100) = 2 · log(1000) = 3 · log(0,01) = −2 · log(1) = <b>0</b><br>Règles : log(a×b) = <b>log a + log b</b> · log(a/b) = <b>log a − log b</b> · log(aⁿ) = <b>n·log a</b>","t":"fr-maths"},{"q":"<b>Logarithme népérien</b> (ln)","a":"Logarithme de base <b>e ≈ 2,718</b>.<br>ln(e) = 1 · ln(1) = 0<br>→ Sert en <b>cinétique</b>, en <b>radioactivité</b> (décroissance exponentielle) et en <b>pharmacocinétique</b>.","t":"fr-maths"},{"q":"Pourquoi le <b>log</b> est-il essentiel en médecine dentaire ?","a":"Parce que <b>pH = −log₁₀[H⁺]</b>.<br>• [H⁺] = 10⁻⁷ → pH = <b>7</b> (neutre)<br>• [H⁺] = 10⁻⁵ → pH = <b>5</b> (acide)<br>⚠️ Chaque unité de pH = <b>×10</b> en concentration. pH 5 est <b>100 fois</b> plus acide que pH 7.","t":"fr-maths"},{"q":"<b>Exponentielle</b>","a":"Fonction <b>eˣ</b> ou <b>aˣ</b>. Croissance (ou décroissance) très rapide.<br>Propriété clé : <b>e^(ln x) = x</b> et <b>ln(eˣ) = x</b><br>→ <b>Décroissance radioactive</b> : N(t) = N₀ · e^(−λt)","t":"fr-maths"},{"q":"<b>Dérivée</b>","a":"Mesure la <b>vitesse de variation</b> d'une fonction.<br>f(x) = xⁿ → f'(x) = <b>n·xⁿ⁻¹</b><br>Graphiquement = la <b>pente</b> de la tangente.<br>→ Sert pour les <b>vitesses de réaction</b> et les <b>clearances</b>.","t":"fr-maths"},{"q":"<b>Pente</b> (coefficient directeur)","a":"Inclinaison d'une droite : <b>a = Δy / Δx</b> = (y₂−y₁)/(x₂−x₁).<br>Dans y = ax + b : <b>a</b> = pente, <b>b</b> = ordonnée à l'origine.<br>→ En <b>cinétique</b>, la pente donne la <b>vitesse</b>.","t":"fr-maths"},{"q":"<b>Moyenne</b>","a":"<b>Somme des valeurs ÷ nombre de valeurs</b>.<br>x̄ = Σxᵢ / n<br>⚠️ Sensible aux <b>valeurs extrêmes</b>.","t":"fr-stats"},{"q":"<b>Médiane</b>","a":"Valeur qui <b>coupe la série en deux moitiés égales</b> (50 % au-dessus, 50 % au-dessous).<br>⚠️ <b>Robuste</b> aux valeurs extrêmes — préférable à la moyenne en cas de distribution asymétrique.","t":"fr-stats"},{"q":"<b>Écart-type</b> (σ)","a":"Mesure la <b>dispersion</b> des valeurs autour de la moyenne.<br>σ petit = valeurs groupées · σ grand = valeurs étalées.<br>→ Dans une distribution normale : <b>68 %</b> des valeurs sont à ±1σ, <b>95 %</b> à ±2σ.","t":"fr-stats"},{"q":"<b>Prévalence</b>","a":"<b>Nombre total de cas</b> d'une maladie dans une population à un moment donné.<br>Prévalence = (cas existants / population) × 100<br>→ Répond à : « <b>combien de personnes sont malades ?</b> »","t":"fr-sante"},{"q":"<b>Incidence</b>","a":"<b>Nombre de NOUVEAUX cas</b> sur une période donnée.<br>Incidence = (nouveaux cas / population à risque) × 100<br>→ Répond à : « <b>quelle est la vitesse d'apparition ?</b> »<br>⚠️ Ne pas confondre avec la prévalence.","t":"fr-sante"},{"q":"<b>Facteur de risque</b>","a":"Caractéristique qui <b>augmente la probabilité</b> de développer une maladie.<br>Ex. pour la carie : <b>fréquence des sucres</b>, <b>hygiène insuffisante</b>, <b>absence de fluor</b>, <b>hyposialie</b>.<br>⚠️ Ce n'est pas une <b>cause</b> directe, c'est une <b>association</b>.","t":"fr-sante"},{"q":"<b>Épidémiologie</b>","a":"Étude de la <b>répartition</b> et des <b>déterminants</b> des maladies dans les populations.<br>→ C'est la base de la <b>santé publique</b> (PSP1).","t":"fr-sante"},{"q":"<b>Solution</b>","a":"Mélange <b>homogène</b> d'un <b>soluté</b> (dissous) dans un <b>solvant</b> (dissolvant).<br>Ex. : sel (soluté) dans l'eau (solvant) → <b>solution aqueuse</b>.","t":"fr-chimie"},{"q":"<b>Solvant</b>","a":"<b>Liquide qui dissout</b>. En biologie et en chimie, c'est presque toujours l'<b>eau</b> → on parle de <b>solution aqueuse</b>.","t":"fr-chimie"},{"q":"<b>Soluté</b>","a":"<b>Substance dissoute</b> dans le solvant.","t":"fr-chimie"},{"q":"<b>Concentration</b>","a":"Quantité de soluté par unité de volume de solution.<br>• <b>C = n / V</b> (mol/L) — concentration <b>molaire</b> (molarité)<br>• <b>Cm = m / V</b> (g/L) — concentration <b>massique</b>","t":"fr-chimie"},{"q":"<b>Dilution</b>","a":"Ajouter du solvant pour <b>diminuer la concentration</b>.<br>Formule clé : <b>C₁ × V₁ = C₂ × V₂</b><br>⚠️ La <b>quantité de matière ne change pas</b>, seul le volume augmente.","t":"fr-chimie"},{"q":"<b>Mole</b>","a":"<b>Unité de quantité de matière</b>.<br>1 mole = <b>6,022 × 10²³</b> particules (<b>nombre d'Avogadro</b>, Nₐ).<br>→ Comme « une douzaine » = 12, « une mole » = 6,022 × 10²³.","t":"fr-chimie"},{"q":"<b>Masse molaire</b> (M)","a":"Masse d'<b>une mole</b> d'une substance, en <b>g/mol</b>.<br>H₂O : M = (2×1) + 16 = <b>18 g/mol</b><br>NaCl : M = 23 + 35,5 = <b>58,5 g/mol</b><br>→ <b>n = m / M</b> (nombre de moles = masse ÷ masse molaire)","t":"fr-chimie"},{"q":"<b>Acide</b>","a":"Espèce capable de <b>céder un proton H⁺</b> (définition de Brønsted).<br>En solution : <b>fait baisser le pH</b>.<br>Ex. : HCl, acide acétique CH₃COOH, <b>acide lactique</b> (produit par les bactéries de la plaque).","t":"fr-chimie"},{"q":"<b>Base</b>","a":"Espèce capable de <b>capter un proton H⁺</b>.<br>En solution : <b>fait monter le pH</b>.<br>Ex. : NaOH, ammoniac NH₃, bicarbonate HCO₃⁻ (<b>tampon de la salive</b>).","t":"fr-chimie"},{"q":"<b>pH</b>","a":"<b>pH = −log₁₀[H⁺]</b> — mesure l'<b>acidité</b>.<br>• pH &lt; 7 → <b>acide</b> · pH = 7 → <b>neutre</b> · pH &gt; 7 → <b>basique/alcalin</b><br>⚠️ <b>pH critique de l'émail = 5,5</b> (en dessous → déminéralisation → carie).","t":"fr-chimie"},{"q":"<b>Neutralisation</b>","a":"<b>Acide + Base → Sel + Eau</b>.<br>HCl + NaOH → NaCl + H₂O<br>→ Le pH tend vers 7.","t":"fr-chimie"},{"q":"<b>Solution tampon</b>","a":"Solution qui <b>résiste aux variations de pH</b> lors de l'ajout d'un acide ou d'une base.<br>Composée d'un <b>acide faible + sa base conjuguée</b>.<br>Ex. : <b>bicarbonate</b> dans la salive, <b>phosphate</b> dans le sang.<br>→ Équation de <b>Henderson-Hasselbalch</b> : pH = pKa + log([base]/[acide])","t":"fr-chimie"},{"q":"<b>Titrage</b> (dosage)","a":"Déterminer une <b>concentration inconnue</b> en ajoutant progressivement une solution de concentration connue.<br>Au <b>point d'équivalence</b> : n(acide) = n(base).<br>→ <b>C₁V₁ = C₂V₂</b>","t":"fr-chimie"},{"q":"<b>Réaction chimique</b>","a":"Transformation d'<b>espèces chimiques</b> (réactifs) en d'autres (produits).<br><b>Réactifs → Produits</b><br>⚠️ Il faut <b>équilibrer</b> : même nombre d'atomes de chaque élément des deux côtés.<br>2H₂ + O₂ → 2H₂O","t":"fr-chimie"},{"q":"<b>Équilibrer une équation</b>","a":"Ajuster les <b>coefficients</b> (jamais les indices !) pour respecter la <b>conservation des atomes</b>.<br>__ H₂ + __ O₂ → __ H₂O devient <b>2</b> H₂ + <b>1</b> O₂ → <b>2</b> H₂O","t":"fr-chimie"},{"q":"<b>Ion</b>","a":"Atome ou molécule qui a <b>gagné ou perdu des électrons</b>.<br>• <b>Cation</b> = charge <b>positive</b> (Ca²⁺, Na⁺, K⁺)<br>• <b>Anion</b> = charge <b>négative</b> (Cl⁻, HCO₃⁻, PO₄³⁻)","t":"fr-chimie"},{"q":"<b>Oxydation</b>","a":"<b>Perte d'électrons</b>. (Moyen mnémotechnique : <b>OIL RIG</b> — Oxidation Is Loss, Reduction Is Gain)<br>→ L'espèce oxydée <b>cède</b> des électrons à l'espèce réduite.","t":"fr-chimie"},{"q":"<b>Réduction</b>","a":"<b>Gain d'électrons</b>.<br>Dans une réaction <b>redox</b>, il y a toujours <b>un oxydé et un réduit</b> en même temps.","t":"fr-chimie"},{"q":"<b>Pression</b>","a":"<b>P = F / S</b> — force par unité de surface.<br>Unité : <b>Pascal (Pa)</b> = N/m² · aussi : <b>bar</b>, <b>atm</b>, <b>mmHg</b><br>→ 1 atm = 101 325 Pa ≈ 760 mmHg","t":"fr-physique"},{"q":"<b>Force</b>","a":"<b>F = m × a</b> (2ᵉ loi de Newton) — masse × accélération.<br>Unité : <b>Newton (N)</b> = kg·m/s²","t":"fr-physique"},{"q":"<b>Débit</b>","a":"<b>Q = V / t</b> — volume par unité de temps.<br>Unités : <b>L/min</b>, <b>mL/s</b>, <b>m³/s</b><br>⚠️ Aussi : <b>Q = v × S</b> (vitesse × section)","t":"fr-physique"},{"q":"<b>Vitesse</b>","a":"<b>v = d / t</b> — distance par unité de temps.<br>Unités : m/s, km/h, <b>cm/s</b>","t":"fr-physique"},{"q":"<b>Énergie</b>","a":"<b>Capacité à produire un travail</b>.<br>Unité : <b>Joule (J)</b>. Aussi : <b>calorie (cal)</b> — 1 cal = 4,18 J<br>Formes : cinétique, potentielle, thermique, chimique.","t":"fr-physique"},{"q":"<b>Puissance</b>","a":"<b>P = E / t</b> — énergie par unité de temps.<br>Unité : <b>Watt (W)</b> = J/s<br>⚠️ Ne pas confondre avec la <b>pression</b> !","t":"fr-physique"},{"q":"<b>Température</b>","a":"Mesure l'<b>agitation des molécules</b>.<br>Unités : <b>°C</b> (Celsius) et <b>K</b> (Kelvin).<br><b>T(K) = T(°C) + 273,15</b><br>⚠️ 0 K = zéro absolu (−273,15 °C)","t":"fr-physique"},{"q":"<b>Courant électrique</b>","a":"<b>Déplacement de charges</b>. Unité : <b>Ampère (A)</b>.<br><b>I = Q / t</b> (charge par unité de temps)<br>⚠️ Par convention, le courant va du <b>+</b> vers le <b>−</b> (les électrons vont dans l'autre sens).","t":"fr-physique"},{"q":"<b>Tension</b> (voltage)","a":"<b>Différence de potentiel</b> entre 2 points. Unité : <b>Volt (V)</b>.<br>→ C'est la « pression » qui pousse les électrons.","t":"fr-physique"},{"q":"<b>Résistance</b>","a":"Capacité d'un matériau à <b>s'opposer au passage du courant</b>. Unité : <b>Ohm (Ω)</b>.<br><b>Loi d'Ohm : U = R × I</b>","t":"fr-physique"},{"q":"<b>Cellule</b>","a":"<b>Unité structurale et fonctionnelle</b> du vivant.<br>• <b>Procaryote</b> : pas de noyau (bactéries)<br>• <b>Eucaryote</b> : noyau délimité par une membrane (cellules humaines)","t":"fr-bio"},{"q":"<b>Membrane plasmique</b>","a":"<b>Enveloppe</b> de la cellule : <b>bicouche de phospholipides</b> + protéines + cholestérol.<br>• <b>Semi-perméable</b> (laisse passer certaines substances)<br>• Rôles : <b>protection</b>, <b>échanges</b>, <b>reconnaissance</b>, <b>communication</b>","t":"fr-bio"},{"q":"<b>Organite</b>","a":"<b>Structure spécialisée</b> à l'intérieur de la cellule, ayant une fonction propre.<br>Ex. : mitochondrie, noyau, ribosome, appareil de Golgi, lysosome, REG.","t":"fr-bio"},{"q":"<b>Métabolisme</b>","a":"Ensemble des <b>réactions chimiques</b> d'un organisme.<br>• <b>Anabolisme</b> = synthèse (consomme de l'énergie)<br>• <b>Catabolisme</b> = dégradation (libère de l'énergie)","t":"fr-bio"},{"q":"<b>ATP</b>","a":"<b>Adénosine TriPhosphate</b> — la « <b>monnaie énergétique</b> » de la cellule.<br>Produit par : <b>glycolyse</b> (2 ATP) → <b>cycle de Krebs</b> → <b>chaîne respiratoire</b> (~36 ATP).<br>Total : ~<b>38 ATP</b> par glucose.","t":"fr-bio"},{"q":"<b>Enzyme</b>","a":"<b>Protéine catalyseur</b> : accélère une réaction chimique <b>sans être consommée</b>.<br>• Très <b>spécifique</b> (modèle clé-serrure)<br>• Sensible à la <b>température</b> et au <b>pH</b><br>→ Paramètres : <b>Km</b> (affinité) et <b>Vmax</b> (vitesse maximale)","t":"fr-bio"},{"q":"<b>Protéine</b>","a":"<b>Macromolécule</b> faite d'une chaîne d'<b>acides aminés</b> liés par des <b>liaisons peptidiques</b>.<br>4 niveaux de structure : <b>primaire</b> (séquence) → <b>secondaire</b> (α-hélice, feuillet β) → <b>tertiaire</b> (repliement 3D) → <b>quaternaire</b> (plusieurs chaînes).","t":"fr-bio"},{"q":"<b>ADN</b>","a":"<b>Acide DésoxyriboNucléique</b> — support de l'<b>information génétique</b>.<br>Double hélice, 4 bases : <b>A-T</b> et <b>G-C</b> (appariements complémentaires).<br>Localisation : <b>noyau</b> (et mitochondries).","t":"fr-bio"},{"q":"<b>ARN</b>","a":"<b>Acide RiboNucléique</b> — copie simple brin de l'ADN.<br>Bases : <b>A-U</b> (uracile remplace la thymine) et G-C.<br>3 types : <b>ARNm</b> (messager), <b>ARNt</b> (transfert), <b>ARNr</b> (ribosomal).","t":"fr-bio"},{"q":"<b>Transcription</b>","a":"<b>ADN → ARN</b>. Copie d'un gène en ARN messager, dans le <b>noyau</b>.<br>Enzyme clé : <b>ARN polymérase</b>.","t":"fr-bio"},{"q":"<b>Traduction</b>","a":"<b>ARN → protéine</b>. Lecture du code génétique par le <b>ribosome</b>, dans le <b>cytoplasme</b>.<br>• <b>Codon</b> = 3 bases = 1 acide aminé<br>• Code génétique : <b>universel</b>, <b>redondant</b>, <b>non ambigu</b>","t":"fr-bio"},{"q":"<b>Réplication</b>","a":"<b>Copie de l'ADN</b> avant la division cellulaire.<br>• <b>Semi-conservative</b> (chaque nouvelle molécule garde 1 brin d'origine)<br>• Enzyme clé : <b>ADN polymérase</b>","t":"fr-bio"},{"q":"<b>Mitose</b>","a":"<b>Division cellulaire</b> d'une cellule somatique → <b>2 cellules identiques</b> (2n → 2n).<br>4 phases : <b>Prophase · Métaphase · Anaphase · Télophase</b> (+ interphase avant).","t":"fr-bio"},{"q":"<b>Méiose</b>","a":"Division qui produit les <b>gamètes</b> → <b>4 cellules à n chromosomes</b> (2n → n), <b>génétiquement différentes</b>.<br>→ Base de la <b>variabilité génétique</b>.","t":"fr-bio"},{"q":"<b>Homéostasie</b>","a":"<b>Maintien de l'équilibre interne</b> de l'organisme malgré les variations externes.<br>Ex. : température (37 °C), pH sanguin (7,4), glycémie (~1 g/L).<br>Mécanisme : <b>rétrocontrôle (feedback)</b> négatif.","t":"fr-bio"},{"q":"<b>Physiologie</b>","a":"Étude du <b>fonctionnement</b> des êtres vivants (organes, cellules, molécules).<br>⚠️ À distinguer de l'<b>anatomie</b> (= étude de la <b>structure</b>).","t":"fr-bio"},{"q":"<b>Anatomie</b>","a":"Étude de la <b>structure</b> et de la <b>forme</b> des organes.<br>• <b>Macroscopique</b> (à l'œil nu)<br>• <b>Microscopique</b> = <b>histologie</b> (au microscope)","t":"fr-bio"},{"q":"<b>Histologie</b>","a":"Étude <b>microscopique des tissus</b>.<br>4 tissus fondamentaux : <b>épithélial</b>, <b>conjonctif</b>, <b>musculaire</b>, <b>nerveux</b>.","t":"fr-bio"},{"q":"<b>Embryologie</b>","a":"Étude du <b>développement</b> de l'embryon, de la fécondation à la naissance.","t":"fr-bio"},{"q":"<b>Tissu épithélial</b>","a":"Tissu de <b>revêtement</b> et de <b>sécrétion</b>. Cellules <b>juxtaposées</b>, pas de vaisseaux (avascularisé), reposant sur une <b>membrane basale</b>.<br>Ex. : épiderme, muqueuse buccale, <b>émail</b> (épithélium améloblastique).","t":"fr-bio"},{"q":"<b>Tissu conjonctif</b>","a":"Tissu de <b>soutien et de liaison</b>. Cellules <b>dispersées</b> dans une <b>matrice extracellulaire</b> abondante (fibres + substance fondamentale).<br>Ex. : os, cartilage, sang, <b>pulpe dentaire</b>, <b>ligament parodontal</b>.","t":"fr-bio"},{"q":"<b>Pathologie</b>","a":"Étude des <b>maladies</b> : causes (<b>étiologie</b>), mécanismes (<b>pathogenèse</b>), lésions, évolution.","t":"fr-med"},{"q":"<b>Étiologie</b>","a":"<b>Cause</b> d'une maladie.<br>Ex. étiologie de la carie : biofilm bactérien + sucres + temps + hôte sensible.","t":"fr-med"},{"q":"<b>Pathogenèse</b>","a":"<b>Mécanisme</b> par lequel la maladie se développe (la « chaîne » des événements).","t":"fr-med"},{"q":"<b>Symptôme</b>","a":"<b>Ressenti par le patient</b>, subjectif.<br>Ex. : douleur, soif, fatigue.<br>⚠️ À distinguer du <b>signe</b>.","t":"fr-med"},{"q":"<b>Signe</b>","a":"<b>Constaté par le clinicien</b>, objectif.<br>Ex. : fièvre mesurée, gonflement, saignement au sondage.","t":"fr-med"},{"q":"<b>Syndrome</b>","a":"Ensemble de <b>signes et symptômes</b> qui surviennent ensemble et caractérisent une situation clinique.","t":"fr-med"},{"q":"<b>Diagnostic</b>","a":"<b>Identification de la maladie</b>.<br>Étapes : <b>interrogatoire</b> (anamnèse) → <b>examen clinique</b> → <b>examens complémentaires</b> (radio, bio) → <b>diagnostic différentiel</b>.","t":"fr-med"},{"q":"<b>Anamnèse</b>","a":"<b>Interrogatoire</b> du patient : motifs de consultation, antécédents, traitements, allergies, habitudes.","t":"fr-med"},{"q":"<b>Pronostic</b>","a":"<b>Prévision de l'évolution</b> de la maladie.<br>• <b>Bon</b> : guérison attendue<br>• <b>Réservé</b> : incertain<br>• <b>Défavorable</b> : évolution défavorable attendue","t":"fr-med"},{"q":"<b>Aigu</b> vs <b>chronique</b>","a":"<b>Aigu</b> : apparition <b>rapide</b>, durée <b>courte</b>, souvent intense.<br>Ex. : abcès dentaire aigu.<br><b>Chronique</b> : évolution <b>lente</b> et <b>prolongée</b>, souvent peu symptomatique.<br>Ex. : <b>la carie</b>, la parodontite.","t":"fr-med"},{"q":"<b>Inflammation</b>","a":"Réaction de défense de l'organisme à une agression.<br><b>5 signes cardinaux</b> (Celse) : <b>rougeur</b> (rubor), <b>chaleur</b> (calor), <b>gonflement</b> (tumor), <b>douleur</b> (dolor), <b>perte de fonction</b> (functio laesa).","t":"fr-med"},{"q":"<b>Infection</b>","a":"<b>Envahissement</b> de l'organisme par des <b>micro-organismes pathogènes</b> qui s'y multiplient.<br>⚠️ ≠ inflammation (qui peut être non infectieuse).","t":"fr-med"},{"q":"<b>Asepsie</b> vs <b>Antisepsie</b>","a":"<b>Asepsie</b> : <b>prévenir</b> l'apport de microbes (stérilisation, gants, champ opératoire).<br><b>Antisepsie</b> : <b>détruire</b> les microbes déjà présents sur un tissu vivant (bétadine, chlorhexidine).","t":"fr-med"},{"q":"<b>Stérilisation</b>","a":"Destruction de <b>tous</b> les micro-organismes, y compris les <b>spores</b>.<br>Méthode de référence en cabinet dentaire : <b>autoclave</b> (vapeur sous pression, 134 °C, 18 min).","t":"fr-med"},{"q":"<b>Désinfection</b>","a":"Élimination de la <b>plupart</b> des micro-organismes pathogènes sur une <b>surface inerte</b> (mais pas nécessairement les spores).","t":"fr-med"},{"q":"<b>Anesthésie locale</b>","a":"<b>Suppression réversible de la sensibilité</b> dans une zone limitée.<br>Produits : <b>lidocaïne</b>, <b>articaïne</b>, <b>mépivacaïne</b> + vasoconstricteur (<b>adrénaline</b>).<br>Techniques : <b>para-apicale</b> (infiltration), <b>tronculaire</b> (nerf dentaire inférieur).","t":"fr-med"},{"q":"<b>Tronculaire</b>","a":"Qui concerne un <b>tronc nerveux</b>.<br>En odontologie : anesthésie <b>tronculaire du nerf dentaire inférieur</b> (au <b>canal mandibulaire</b>, repère = <b>épine de Spix</b>) → anesthésie de toute une <b>demi-mandibule</b>.","t":"fr-med"}]},{"id":"organe-dentaire","nom":"🦷 Organe dentaire","src":"Cours M115","ordre":11,"module":"M115","desc":"Anatomie dentaire · parodonte · occlusion","cards":[{"q":"La dent est un organe.","a":"La dent est un <b>organe</b> — pas un simple tissu. Elle est constituée de <b>3 tissus durs</b> (émail, dentine, cément) et d'<b>1 tissu mou</b> (pulpe).","t":"organe-dentaire"},{"q":"Combien de dents chez l'adulte (denture permanente) ?","a":"<b>32 dents</b> (16 par arcade) — dont 4 dents de sagesse.<br>Sans les dents de sagesse : <b>28</b>.","t":"organe-dentaire"},{"q":"Combien de dents chez l'enfant (denture temporaire / dents de lait) ?","a":"<b>20 dents</b> (10 par arcade).<br>Pas de prémolaires, pas de 3ᵉ molaire.","t":"organe-dentaire"},{"q":"Nomme les 5 groupes de dents (par arcade).","a":"1. <b>Incisives</b> (2) — couper<br>2. <b>Canines</b> (1) — déchirer<br>3. <b>Prémolaires</b> (2) — broyer<br>4. <b>Molaires</b> (2 ou 3) — broyer<br>→ Total : 8 par demi-arcade × 2 = 16 (dents de sagesse comprises)","t":"organe-dentaire"},{"q":"Quelles dents sont absentes de la denture temporaire ?","a":"Les <b>prémolaires</b> et les <b>3ᵉ molaires</b> (dents de sagesse).","t":"organe-dentaire"},{"q":"Les 4 parties anatomiques d'une dent.","a":"1. <b>Couronne</b> — partie visible, recouverte d'émail<br>2. <b>Collet</b> (ligne cervicale) — jonction couronne/racine<br>3. <b>Racine</b> — partie dans l'os, recouverte de cément<br>4. <b>Apex</b> — extrémité de la racine (foramen apical)","t":"organe-dentaire"},{"q":"Combien de racines : incisive · canine · prémolaire · molaire maxillaire · molaire mandibulaire ?","a":"<b>Incisive</b> : 1<br><b>Canine</b> : 1<br><b>Prémolaire</b> : 1 ou 2<br><b>Molaire maxillaire</b> : <b>3</b><br><b>Molaire mandibulaire</b> : <b>2</b>","t":"organe-dentaire"},{"q":"Qu'est-ce que l'<b>émail</b> ? (3 caractéristiques)","a":"Tissu <b>le plus dur</b> du corps humain.<br>• <b>Acellulaire</b> (pas de cellules vivantes) → <b>ne se répare pas</b><br>• Composé à <b>96–97 % de minéral</b> (hydroxyapatite)<br>• Recouvre la <b>couronne</b> seulement","t":"organe-dentaire"},{"q":"Quel est le minéral principal de l'émail, de la dentine et du cément ?","a":"<b>Hydroxyapatite</b> : Ca₁₀(PO₄)₆(OH)₂<br>= phosphate de calcium cristallin.","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>dentine</b> ?","a":"Tissu dur <b>sous l'émail</b>, qui forme le <b>corps de la dent</b>.<br>• 70 % minéral (moins que l'émail)<br>• Traversée par des <b>tubules dentinaires</b> → contient des prolongements des <b>odontoblastes</b><br>• <b>Vivante</b> → peut se réparer (dentine réactionnelle/réparatrice)<br>• Transmet la <b>douleur</b>","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>cément</b> ?","a":"Tissu dur qui <b>recouvre la racine</b>.<br>• Moins minéralisé que la dentine<br>• Sert d'<b>ancrage</b> aux fibres du ligament parodontal<br>• Se dépose toute la vie (cément secondaire)","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>pulpe dentaire</b> ?","a":"<b>Tissu conjonctif mou</b> au centre de la dent, dans la <b>chambre pulpaire</b> (couronne) et les <b>canaux radiculaires</b> (racine).<br>Contient : <b>nerfs</b>, <b>vaisseaux sanguins</b>, lymphatiques, <b>odontoblastes</b>, tissu conjonctif.<br>Rôles : formation de la dentine, nutrition, sensibilité, défense.","t":"organe-dentaire"},{"q":"Qui fabrique l'émail ? Qui fabrique la dentine ?","a":"<b>Améloblastes</b> → émail (disparaissent après l'éruption → l'émail ne se régénère plus)<br><b>Odontoblastes</b> → dentine (restent toute la vie à la périphérie de la pulpe)","t":"organe-dentaire"},{"q":"Que sont les <b>tubules dentinaires</b> (canaux de Tomes) ?","a":"Micro-canaux qui traversent toute la dentine, du <b>cément/émail</b> vers la <b>pulpe</b>.<br>Contiennent le <b>prolongement de l'odontoblaste</b> (fibre de Tomes).<br>→ <b>C'est la voie de la sensibilité et de la douleur dentaire.</b>","t":"organe-dentaire"},{"q":"Définis : <b>chambre pulpaire</b> vs <b>canal radiculaire</b>.","a":"<b>Chambre pulpaire</b> : cavité dans la <b>couronne</b>.<br><b>Canal radiculaire</b> : prolongement de la pulpe dans la <b>racine</b>, qui s'ouvre au <b>foramen apical</b>.","t":"organe-dentaire"},{"q":"Définis : <b>corne pulpaire</b>.","a":"Prolongement de la chambre pulpaire sous chaque <b>cuspide</b>.<br>⚠️ Très proche de la surface chez l'enfant → risque de <b>perforation</b> lors d'une cavité.","t":"organe-dentaire"},{"q":"Nomme les faces d'une dent. (5)","a":"1. <b>Vestibulaire</b> — vers les lèvres/joues<br>2. <b>Palatine</b> (maxillaire) / <b>linguale</b> (mandibulaire) — vers le palais/la langue<br>3. <b>Mésiale</b> — vers la ligne médiane<br>4. <b>Distale</b> — loin de la ligne médiane<br>5. <b>Occlusale</b> (postérieures) / <b>Incisive</b> (antérieures) — face de mastication","t":"organe-dentaire"},{"q":"Que sont une <b>cuspide</b> et une <b>crête marginale</b> ?","a":"<b>Cuspide</b> : pointe/relief pyramidal sur la face occlusale (canine = 1, prémolaire = 2, molaire = 4–5).<br><b>Crête marginale</b> : relief linéaire en bordure de la face occlusale/palatine.","t":"organe-dentaire"},{"q":"Nomme les 4 types de <b>sillons et fosses</b> occlusaux.","a":"• <b>Fosse centrale</b><br>• <b>Sillon principal</b> (mésio-distal)<br>• <b>Fossettes</b> (mésiale, distale)<br>• <b>Cryptes / puits</b> (points de départ fréquents de la <b>carie</b>)","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>jonction émail-dentine</b> (JED) ? Pourquoi est-elle importante ?","a":"Ligne de rencontre entre <b>émail</b> et <b>dentine</b>, au niveau du collet et sous la couronne.<br>• <b>Zone de fragilité mécanique</b> (carie s'y propage latéralement)<br>• <b>Très sensible</b> (proximité des tubules) → douleur au froid/au sucré","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>ligne cervicale</b> (collet) ?","a":"Jonction <b>couronne / racine</b> = jonction <b>émail / cément</b>.<br>3 types de relation possible : bout à bout, émail recouvre le cément (60 %), cément recouvre l'émail, ou <b>hiatus</b> (dentine exposée → sensibilité).","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>foramen apical</b> ?","a":"Orifice à l'<b>extrémité de la racine</b> par lequel passent le <b>nerf</b> et les <b>vaisseaux</b> pulaires.<br>→ C'est la porte d'entrée de la pulpe (et la voie de sortie de l'infection : <b>abcès péri-apical</b>).","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>déciduation</b> ?","a":"Processus de <b>perte des dents temporaires</b> (dents de lait), par <b>résorption des racines</b> sous la poussée de la dent permanente.<br>Débute vers <b>6 ans</b>, se termine vers <b>12 ans</b>.","t":"organe-dentaire"},{"q":"Donne les âges d'éruption des dents permanentes (ordre).","a":"<b>6 ans</b> : 1ʳᵉ molaire (« dent de 6 ans ») + incisives centrales<br><b>7–8 ans</b> : incisives latérales<br><b>9–12 ans</b> : canines + prémolaires<br><b>12 ans</b> : 2ᵉ molaire (« dent de 12 ans »)<br><b>17–25 ans</b> : 3ᵉ molaire (dent de sagesse)","t":"organe-dentaire"},{"q":"Quelle est la <b>première</b> dent permanente à apparaître ? Pourquoi est-elle capitale ?","a":"La <b>1ʳᵉ molaire</b> (« dent de 6 ans »).<br>• Elle <b>ne remplace aucune dent de lait</b> → les parents croient que c'est une dent temporaire et ne la soignent pas<br>• C'est la <b>clé de l'occlusion</b> → la perdre jeune = effondrement de toute l'articulé dentaire","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>dent de 6 ans</b> et la <b>dent de 12 ans</b> ?","a":"<b>Dent de 6 ans</b> = 1ʳᵉ molaire permanente<br><b>Dent de 12 ans</b> = 2ᵉ molaire permanente<br>(Les 3ᵉ molaires = « dents de sagesse », 17–25 ans)","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>formule dentaire</b> ? Donne celle de l'adulte.","a":"Notation du nombre de dents par demi-arcade :<br><b>I 2/2 · C 1/1 · PM 2/2 · M 3/3</b> = 32<br>Enfant : <b>i 2/2 · c 1/1 · m 2/2</b> = 20 (m = molaires de lait, pas de prémolaires)","t":"organe-dentaire"},{"q":"Qu'est-ce que la numérotation <b>FDI</b> (Fédération Dentaire Internationale) ?","a":"2 chiffres : <b>quadrant</b> + <b>position</b>.<br>Quadrants : <b>1</b> = haut droit · <b>2</b> = haut gauche · <b>3</b> = bas gauche · <b>4</b> = bas droit<br>(sens des aiguilles d'une montre, vu du praticien)<br>Dents de lait : quadrants <b>5, 6, 7, 8</b>.","t":"organe-dentaire"},{"q":"Donne le code FDI de : incisive centrale supérieure droite · canine inférieure gauche · 1ʳᵉ molaire supérieure gauche.","a":"Incisive centrale sup. droite = <b>11</b><br>Canine inf. gauche = <b>33</b><br>1ʳᵉ molaire sup. gauche = <b>26</b>","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>parodonte</b> ? Nomme ses 4 constituants.","a":"Ensemble des tissus de <b>soutien de la dent</b> :<br>1. <b>Gencive</b><br>2. <b>Ligament parodontal</b> (desmodonte)<br>3. <b>Cément</b><br>4. <b>Os alvéolaire</b>;<br>→ Le parodonte <b>attache</b> la dent à l'os et <b>amortit</b> les forces de mastication.","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>ligament parodontal</b> (desmodonte) ?","a":"Tissu conjonctif fibreux entre le <b>cément</b> et l'<b>os alvéolaire</b>.<br>Fibres principales : <b>alvéolo-dentaires</b>, <b>cémento-périostées</b>.<br>Rôles : <b>attache</b>, <b>amortisseur</b>, <b>nutrition</b>, <b>innervation proprioceptive</b> (sensibilité à la pression), remodelage.","t":"organe-dentaire"},{"q":"Nomme les 2 types de <b>gencive</b> et leurs caractéristiques.","a":"<b>Gencive attachée</b> (libre + adhérente) : rose pâle, ferme, <b>stipulée</b> (aspect peau d'orange), kératinisée.<br><b>Gencive marginale</b> (libre) : forme le <b>sulcus</b>, non attachée.<br><b>Muqueuse alvéolaire</b> : rouge, mobile, <b>non kératinisée</b> — ce n'est PAS de la gencive.","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>sillon gingival libre</b> et le <b>sulcus</b> ?","a":"<b>Sulcus</b> (sillon gingivo-dentaire) : espace entre la <b>gencive marginale</b> et la <b>dent</b>.<br>• Profondeur physiologique : <b>0,5 à 3 mm</b><br>• Au-delà = <b>poche parodontale</b> = signe de <b>parodontite</b>","t":"organe-dentaire"},{"q":"Qu'est-ce que l'<b>attache épithéliale</b> ? Pourquoi est-elle cruciale ?","a":"Bande d'épithélium qui <b>scelle la gencive à la dent</b> (au niveau du cément/émail).<br>• C'est la <b>barrière</b> entre la cavité buccale (infectée) et le parodonte (stérile)<br>• Sa <b>migration apicale</b> = signe de <b>parodontite</b> (perte d'attache = critère diagnostique principal)","t":"organe-dentaire"},{"q":"Qu'est-ce que l'<b>os alvéolaire</b> ? Distingue ses 2 parties.","a":"Os qui <b>porte les dents</b>.<br>• <b>Os de soutien</b> (basal) : cortical + spongieux<br>• <b>Os alvéolaire propre</b> (lamina dura en radio) : os qui tapisse l'alvéole, où s'insèrent les fibres du ligament<br>→ La <b>lamina dura</b> disparaît en cas de parodontite.","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>tissu péri-apical</b> ?","a":"Tissu situé à l'<b>apex</b> de la racine, autour du foramen apical : ligament, os, vaisseaux, nerfs.<br>→ Siège de l'<b>abcès péri-apical</b>, du <b>kyste radiculeux</b>, du <b>granulome apical</b>.","t":"organe-dentaire"},{"q":"Définis : <b>maxillaire</b> vs <b>mandibule</b>.","a":"<b>Maxillaire</b> : os de l'arcade <b>supérieure</b>, <b>fixe</b>, creusé du <b>sinus maxillaire</b>.<br><b>Mandibule</b> : os de l'arcade <b>inférieure</b>, <b>seul os mobile du crâne</b>, porte le <b>condyle</b>.","t":"organe-dentaire"},{"q":"Qu'est-ce que l'<b>articulation temporo-mandibulaire</b> (ATM) ? Ses 3 éléments.","a":"Articulation entre le <b>condyle mandibulaire</b> et la <b>fosse mandibulaire du temporal</b>.<br>1. <b>Condyle</b><br>2. <b>Fosse glénoïde / cavité glénoïde</b><br>3. <b>Disque articulaire</b> (ménisque) + capsule + ligaments<br>→ Mouvements : <b>rotation</b> (ouverture initiale) puis <b>translation</b>.","t":"organe-dentaire"},{"q":"Nomme les 4 <b>muscles masticateurs</b>.","a":"1. <b>Masséter</b> — élévation (fermeture)<br>2. <b>Temporal</b> — élévation + rétropulsion<br>3. <b>Pterygoïdien médial</b> (interne) — élévation<br>4. <b>Pterygoïdien latéral</b> (externe) — <b>abaissement / propulsion</b> (seul muscle qui ouvre activement)","t":"organe-dentaire"},{"q":"Quel nerf innerve les dents et la mandibule ? Quel nerf le maxillaire ?","a":"<b>Nerf mandibulaire (V3)</b> — branche du <b>trijumeau (V)</b> : nerf dentaire inférieur → dents mandibulaires.<br><b>Nerf maxillaire (V2)</b> : nerfs dentaires supérieurs → dents maxillaires.<br>⚠️ Le <b>trijumeau (V)</b> est le nerf clé en odontologie (anesthésie locale).","t":"organe-dentaire"},{"q":"Quelles sont les <b>3 grandes glandes salivaires</b> et leurs canaux ?","a":"1. <b>Parotide</b> → canal de <b>Sténon</b> (en regard de la 2ᵉ molaire supérieure)<br>2. <b>Sous-maxillaire</b> (submandibulaire) → canal de <b>Wharton</b><br>3. <b>Sublinguale</b> → canaux de <b>Rivinus</b> / canal de <b>Bartholin</b><br>+ glandes salivaires <b>accessoires</b> (labiales, palatines, linguales).","t":"organe-dentaire"},{"q":"Quel type de sécrétion pour chaque grande glande salivaire ?","a":"<b>Parotide</b> : <b>séreuse</b> (fluide, riche en amylase)<br><b>Sous-maxillaire</b> : <b>mixte</b> (séro-muqueuse) — produit le plus de volume au repos<br><b>Sublinguale</b> : <b>muqueuse</b> (visqueuse)","t":"organe-dentaire"},{"q":"Quel est le <b>pH normal de la salive</b> ? Le <b>débit</b> quotidien ?","a":"<b>pH : 6,7 – 7,4</b> (moyenne ≈ 7)<br>⚠️ En dessous de <b>5,5</b> → <b>déminéralisation</b> de l'émail (début de la carie)<br><b>Débit : 1 à 1,5 L / jour</b> (0,3 mL/min au repos · 1–3 mL/min stimulée)","t":"organe-dentaire"},{"q":"Nomme 6 <b>fonctions de la salive</b>.","a":"1. <b>Protection</b> (tampon du pH, clairance des sucres)<br>2. <b>Reminéralisation</b> (Ca²⁺, PO₄³⁻, fluor)<br>3. <b>Antibactérienne</b> (lysozyme, lactoperoxydase, IgA, lactoferrine)<br>4. <b>Digestive</b> (amylase salivaire / ptyaline)<br>5. <b>Lubrification</b> (mucines → phonation, déglutition)<br>6. <b>Gustative</b> (dissout les molécules sapides)<br>+ <b>pellicule acquise</b> sur la dent.","t":"organe-dentaire"},{"q":"Quels sont les 4 <b>systèmes tampons</b> de la salive ?","a":"1. <b>Bicarbonate</b> (HCO₃⁻) — le plus important, stimulé<br>2. <b>Phosphate</b> — dominant au repos<br>3. <b>Protéines</b> (acides aminés)<br>4. <b>Urée</b> (→ ammoniac)<br>→ Rôle : <b>neutraliser les acides</b> produits par les bactéries après un repas.","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>pellicule acquise</b> ?","a":"Film <b>organique acellulaire</b> (glycoprotéines salivaires) qui se dépose sur l'émail en <b>quelques minutes</b> après brossage.<br>→ Sert de <b>support d'adhésion</b> aux bactéries → devient la <b>plaque dentaire</b>.","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>biofilm dentaire</b> (plaque dentaire) ?","a":"Communauté structurée de <b>bactéries</b> adhérant à la pellicule acquise.<br>• <b>Primaire</b> : cocci Gram+ aérobies (<i>Streptococcus</i>)<br>• <b>Mature</b> (48 h+) : Gram− anaérobies (<i>Porphyromonas</i>, <i>Treponema</i>) → <b>parodontopathogène</b><br>→ Ne s'élimine que <b>mécaniquement</b> (brossage).","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>tartre</b> (calcul dentaire) ?","a":"<b>Plaque dentaire minéralisée</b> par les sels salivaires (Ca, PO₄).<br>• <b>Blanc jaunâtre</b>, dur, adhérent<br>• Ne s'enlève <b>pas au brossage</b> → nécessite un <b>détartrage</b> professionnel<br>• Rétention de plaque → gingivite → parodontite","t":"organe-dentaire"},{"q":"Nomme les 3 types de <b>muqueuse buccale</b>.","a":"1. <b>Muqueuse masticatoire</b> : gencive, palais dur — <b>kératinisée</b>, résistante<br>2. <b>Muqueuse de revêtement</b> : joues, lèvres, plancher, ventre de la langue — <b>non kératinisée</b>, souple<br>3. <b>Muqueuse spécialisée</b> : dos de la langue — papilles + goût","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>vestibule buccal</b> ?","a":"Espace en <b>fer à cheval</b> entre les <b>lèvres/joues</b> en dehors et les <b>arcades dentaires</b> en dedans.<br>→ C'est là qu'on fait les <b>injections anesthésiques vestibulaires</b>.","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>cavité buccale proprement dite</b> ? Ses limites.","a":"Espace <b>en dedans des arcades dentaires</b>.<br>• <b>Haut</b> : palais (dur + mou)<br>• <b>Bas</b> : plancher buccal + langue<br>• <b>En arrière</b> : se prolonge par l'<b>oropharynx</b> via l'<b>isthme du gosier</b> (entre les piliers antérieurs)","t":"organe-dentaire"},{"q":"Distingue le <b>palais dur</b> du <b>palais mou</b>.","a":"<b>Palais dur</b> (antérieur, 2/3) : os recouvert de muqueuse kératinisée, <b>rigide</b> → mastication. Présente les <b>rides palatines</b>.<br><b>Palais mou</b> (postérieur, 1/3) : musculaire, <b>mobile</b>, se termine par la <b>luette (uvula)</b> → ferme le rhinopharynx lors de la déglutition.","t":"organe-dentaire"},{"q":"Nomme les 4 types de <b>papilles linguales</b>.","a":"1. <b>Caliciformes</b> (circumvallées) — 8 à 12, en <b>V lingual</b>, les plus grosses, goût<br>2. <b>Fongiformes</b> — pointe/bords, goût<br>3. <b>Foliées</b> — bords postérieurs, goût<br>4. <b>Filiformes</b> — les plus nombreuses, <b>pas de bourgeons gustatifs</b>, rôle mécanique (abrasion)","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>V lingual</b> ?","a":"<b>V</b> formé par les <b>papilles caliciformes</b> à la partie postérieure du dos de la langue.<br>Sommet = <b>foramen cæcum</b> (vestige du canal thyréoglosse).<br>→ Sépare le <b>dos de la langue</b> (2/3 antérieurs) de la <b>base de langue</b> (1/3 postérieur).","t":"organe-dentaire"},{"q":"Quels nerfs pour : sensibilité des 2/3 antérieurs de la langue · goût des 2/3 antérieurs · sensibilité du 1/3 postérieur ?","a":"<b>Sensibilité 2/3 ant.</b> : nerf <b>lingual</b> (V3, trijumeau)<br><b>Goût 2/3 ant.</b> : <b>corde du tympan</b> (VII, facial)<br><b>Sensibilité + goût 1/3 post.</b> : nerf <b>glosso-pharyngien</b> (IX)<br><b>Motricité</b> : nerf <b>grand hypoglosse</b> (XII)","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>frein labial</b> ? Signe clinique ?","a":"Repli de muqueuse qui attache la <b>lèvre</b> à la gencive (médian, supérieur et inférieur).<br>⚠️ Un frein <b>haut inséré</b> peut causer un <b>diastème</b> (espace entre incisives centrales) ou une <b>récidive orthodontique</b>.","t":"organe-dentaire"},{"q":"Qu'est-ce qu'un <b>diastème</b> ?","a":"<b>Espace anormal</b> entre deux dents adjacentes (souvent incisives centrales supérieures).<br>Causes : frein haut inséré, dent surnuméraire (mésiodens), macroglossie, discrepancy de taille dent/os.","t":"organe-dentaire"},{"q":"Qu'est-ce que l'<b>occlusion dentaire</b> ?","a":"<b>Contact</b> entre les dents maxillaires et mandibulaires lors de la fermeture.<br>• <b>OCIM</b> / OIM : <b>occlusion d'intercuspidie maximale</b> = position de référence<br>• <b>Relation centrée</b> : position condylienne la plus antéro-supérieure<br>• <b>Classe I d'Angle</b> = occlusion normale","t":"organe-dentaire"},{"q":"Quelles sont les <b>3 classes d'Angle</b> ?","a":"<b>Classe I</b> (normale) : cuspide mésio-vestibulaire de la 1ʳᵉ molaire sup. s'articule dans le <b>sillon mésio-vestibulaire</b> de la 1ʳᵉ molaire inf.<br><b>Classe II</b> : mandibule en <b>arrière</b> (rétrognathie) → « dents en avant »<br><b>Classe III</b> : mandibule en <b>avant</b> (prognathie) → prognathisme mandibulaire","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>surplomb</b> et la <b>supraclusion</b> (overjet / overbite) ?","a":"<b>Surplomb (overjet)</b> : distance <b>horizontale</b> entre le bord des incisives sup. et inf. → normal <b>2–3 mm</b><br><b>Supraclusion (overbite)</b> : recouvrement <b>vertical</b> → normal <b>2–3 mm</b> (1/3 de la couronne)<br>Au-delà : <b>supraclusion excessive</b> ; en dessous : <b>béance</b>.","t":"organe-dentaire"},{"q":"Qu'est-ce que l'<b>articulé croisé</b> (occlusion inversée) ?","a":"Inversion du rapport normal : la dent <b>mandibulaire passe en vestibulaire</b> de la dent maxillaire.<br>Peut être <b>antérieur</b> ou <b>postérieur</b>, <b>unilatéral</b> ou <b>bilatéral</b>.","t":"organe-dentaire"},{"q":"Définis : <b>mésial</b>, <b>distal</b>, <b>vestibulaire</b>, <b>palatin</b>, <b>lingual</b>, <b>occlusal</b>, <b>cervical</b>, <b>apical</b>.","a":"<b>Mésial</b> : vers la ligne médiane<br><b>Distal</b> : loin de la ligne médiane<br><b>Vestibulaire</b> : vers lèvres/joues<br><b>Palatin</b> : vers le palais (haut)<br><b>Langual</b> : vers la langue (bas)<br><b>Occlusal</b> : face de mastication<br><b>Cervical</b> : vers le collet<br><b>Apical</b> : vers l'apex de la racine","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>dentine réactionnelle</b> vs la <b>dentine réparatrice</b> (tertiaire) ?","a":"<b>Réactionnelle</b> : déposée par les odontoblastes <b>existants</b> en réponse à une agression lente (usure, carie débutante).<br><b>Réparatrice / tertiaire</b> : déposée par de <b>nouveaux odontoblastes</b> après mort des anciens (agression sévère).<br>→ Mécanisme de <b>défense pulpaire</b>.","t":"organe-dentaire"},{"q":"Qu'est-ce que l'<b>éruption</b> et l'<b>rhizagenèse</b> ?","a":"<b>Éruption</b> : migration de la dent de son germe osseux vers la cavité buccale.<br><b>Rhizagenèse</b> : formation de la <b>racine</b> (après la couronne).<br>⚠️ À l'éruption, l'<b>apex est encore ouvert</b> → se ferme ~2–3 ans après (important pour l'endodontie de l'enfant).","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>dent incluse</b> vs <b>enclavée</b> vs <b>impaction</b> ?","a":"<b>Incluse</b> : dent qui n'a pas fait éruption, restée dans l'os (fréquent : <b>dents de sagesse</b>, canines sup.).<br><b>Enclavée</b> : dent dont l'éruption est <b>bloquée</b> par un obstacle (dent voisine, os, kyste).<br><b>Impaction</b> : dent incluse en <b>conflit</b> avec la racine de la dent voisine (risque de résorption).","t":"organe-dentaire"},{"q":"Qu'est-ce que la <b>péricoronarite</b> ?","a":"Inflammation/infection de la <b>gencive qui recouvre partiellement une dent en cours d'éruption</b> (capuchon muqueux), typiquement la <b>dent de sagesse inférieure</b>.<br>Signes : douleur, trismus, dysphagie, haleine fétide.<br>→ Urgence odontologique fréquente.","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>trismus</b> ?","a":"<b>Limitation de l'ouverture buccale</b> par contracture des muscles masticateurs.<br>Causes : péricoronarite, abcès, infection de l'espace massétérique, traumatisme de l'ATM.<br>Mesure normale : <b>40–50 mm</b> entre les bords incisifs.","t":"organe-dentaire"},{"q":"Qu'est-ce que le <b>sillon naso-labial</b>, le <b>philtrum</b>, le <b>tubercule</b> ?","a":"<b>Philtrum</b> : gouttière médiane de la lèvre supérieure.<br><b>Tubercule</b> : relief médian du bord libre de la lèvre supérieure.<br><b>Sillon naso-labial</b> : pli entre l'aile du nez et le coin de la bouche.","t":"cavite-buccale"},{"q":"Qu'est-ce que le <b>commissure labiale</b> ? Pathologie fréquente ?","a":"Angle de réunion des lèvres (coin de la bouche).<br>Pathologie fréquente : <b>perlèche</b> (chéilite angulaire) — fissuration, souvent candidosique, favorisée par l'<b>effondrement de la dimension verticale</b> (édenté).","t":"cavite-buccale"},{"q":"Qu'est-ce que la <b>dimension verticale d'occlusion</b> (DVO) ?","a":"Distance entre 2 points (ex. <b>base du nez</b> et <b>menton</b>) lorsque les dents sont en <b>occlusion</b>.<br>→ En prothèse complète, il faut la <b>reconstruire</b>. Sa perte = vieillisement du visage, perlèche, douleur ATM.","t":"prothese"},{"q":"Qu'est-ce que l'<b>espace inter-arcades</b> (freeway space) ?","a":"Espace entre les arcades en <b>position de repos mandibulaire</b> (dents sans contact).<br>Normal : <b>2–4 mm</b>.<br>DVO = dimension verticale de repos − espace inter-arcades.","t":"prothese"},{"q":"Nomme les 6 étapes de la <b>formation de la dent</b> (odontogenèse).","a":"1. <b>Initiation</b> (bourgeon épithélial)<br>2. <b>Prolifération</b> (stade du bonnet)<br>3. <b>Histo-différenciation</b> (stade de la cloche)<br>4. <b>Morpho-différenciation</b> (empreinte de la future couronne)<br>5. <b>Apposition</b> (dépôt de matrice : émail + dentine)<br>6. <b>Calcification / minéralisation</b><br>+ <b>Éruption</b> et <b>rhizagenèse</b>","t":"embryologie"},{"q":"Distingue : <b>organe de l'émail</b> · <b>papille dentaire</b> · <b>sac dentaire</b> (germe dentaire).","a":"<b>Organe de l'émail</b> (ectoderme) → <b>émail</b> (améloblastes)<br><b>Papille dentaire</b> (ectomésenchyme) → <b>pulpe + dentine</b> (odontoblastes)<br><b>Sac dentaire</b> (ectomésenchyme) → <b>cément + ligament parodontal + os alvéolaire</b><br>→ Ensemble = <b>germe dentaire</b>.","t":"embryologie"},{"q":"Quelle est l'origine embryologique de l'émail vs la dentine ? Pourquoi est-ce capital ?","a":"<b>Émail</b> : <b>ectoderme</b> (épithélium buccal primitif)<br><b>Dentine, pulpe, cément, parodonte</b> : <b>ectomésenchyme</b> (crêtes neurales)<br>⚠️ Conséquence clinique : l'émail est <b>acellulaire</b> et ne se régénère <b>pas</b> (les améloblastes disparaissent à l'éruption), alors que la dentine <b>se répare toute la vie</b>.","t":"embryologie"},{"q":"Qu'est-ce que la <b>minéralisation</b> de l'émail ? Étapes.","a":"1. Dépôt de <b>matrice organique</b> (amélogénines, énamélines) par les améloblastes<br>2. <b>Calcification initiale</b> (~30 % de minéral)<br>3. <b>Maturation</b> : perte d'eau et de protéines, dépôt massif d'<b>hydroxyapatite</b> → 96 %<br>⚠️ Tout ce qui perturbe cette phase = <b>hypominéralisation</b> (MIH, fluorose, hypoplasie).","t":"embryologie"},{"q":"Qu'est-ce qu'une <b>hypoplasie de l'émail</b> ? Donne 3 causes.","a":"<b>Défaut quantitatif</b> de formation de l'émail → émail mince, puits, sillons.<br>Causes :<br>• <b>Maladie fébrile</b> de l'enfance, prématurité<br>• <b>Carence</b> (vitamine D, calcium, vit A/C)<br>• <b>Fluorose</b> (excès de fluor)<br>• Traumatisme/infection d'une dent temporaire → <b>tache de Turner</b>","t":"pathologie"},{"q":"Qu'est-ce que la <b>MIH</b> (Molar-Incisor Hypomineralisation) ?","a":"<b>Hypominéralisation</b> affectant <b>1 à 4 molaires permanentes</b> ± incisives.<br>Émail <b>blanc crémeux à brun jaunâtre</b>, poreux, qui <b>s'effrite</b>.<br>Hypersensibilité marquée → anesthésie difficile.<br>Prévalence ~15 % ; étiologie multifactorielle (prématurité, antibio précoce, fièvre).","t":"pathologie"},{"q":"Qu'est-ce qu'une <b>dents de Turner</b> (tache de Turner) ?","a":"<b>Hypoplasie d'une dent permanente isolée</b> causée par une <b>infection ou un traumatisme de la dent temporaire</b> qui la précédait.<br>Touche surtout les <b>prémolaires</b> (après infection d'une molaire de lait) et les <b>incisives</b> (après traumatisme).","t":"pathologie"},{"q":"Qu'est-ce que l'<b>odontalgie</b> ? Distingue les 3 grands types de douleur.","a":"<b>Odontalgie</b> = douleur dentaire.<br>1. <b>Dentine/pulpe réversible</b> : douleur au <b>froid/sucré</b>, <b>brève</b>, cède à l'éviction du stimulus → pulpite réversible<br>2. <b>Pulpe irréversible</b> : douleur <b>spontanée</b>, <b>pulsatile</b>, <b>nocturne</b>, prolongée, non localisée → pulpite irréversible<br>3. <b>Péri-apicale</b> : douleur à la <b>pression/mastication</b>, dent bien <b>localisée</b>, « dent longue » → desmodontite/abcès","t":"semio"},{"q":"Définis : <b>pulpite réversible</b> vs <b>pulpite irréversible</b>.","a":"<b>Réversible</b> : inflammation légère, douleur provoquée et brève, la pulpe peut <b>guérir</b> → traitement = <b>soin conservateur</b> (obturation).<br><b>Irréversible</b> : inflammation sévère, douleur <b>spontanée/pulsatile/nocturne</b>, la pulpe <b>ne peut pas guérir</b> → traitement = <b>traitement endodontique</b> (dévitalisation) ou extraction.","t":"endodontie"},{"q":"Qu'est-ce que la <b>nécrose pulpaire</b> ?","a":"<b>Mort de la pulpe</b>. Dent <b>non douloureuse au froid</b> (test de vitalité négatif), peut devenir douloureuse à la percussion si infection péri-apicale.<br>→ Évolution : <b>gangrène pulpaire</b>, <b>granulome apical</b>, <b>kyste radiculeux</b>, <b>abcès</b>, <b>cellulite</b>.","t":"endodontie"},{"q":"Qu'est-ce qu'un <b>abcès péri-apical</b> vs une <b>cellulite</b> ?","a":"<b>Abcès péri-apical</b> : collection purulente <b>localisée</b> à l'apex, dans l'os.<br><b>Cellulite</b> : diffusion de l'infection dans les <b>espaces cellulaires</b> des tissus mous de la face (jugale, sous-mandibulaire, plancher → <b>angine de Ludwig</b>).<br>⚠️ La cellulite = <b>urgence vitale</b> (détresse respiratoire possible).","t":"chirurgie"},{"q":"Qu'est-ce que l'<b>angine de Ludwig</b> ?","a":"Cellulite <b>bilatérale des espaces sous-mandibulaire, sublingual et submental</b>, d'origine dentaire (souvent 2ᵉ/3ᵉ molaire inférieure).<br>Signes : <b>langue refoulée vers le haut</b>, dysphagie, trismus, dyspnée, fièvre.<br>→ <b>URGENCE VITALE</b> : obstruction des voies aériennes.","t":"urgence"},{"q":"Qu'est-ce qu'une <b>fistule</b> dentaire ?","a":"<b>Trajet anormal</b> qui draine le pus d'un foyer infectieux vers la surface (muqueuse ou peau).<br>Se présente comme une <b>papule</b> (« bouton ») sur la gencive, en regard de l'apex de la dent causale.<br>→ Signe de <b>suppuration chronique</b>; le patient peut être <b>peu douloureux</b> (la pression est drainée).","t":"semio"},{"q":"Qu'est-ce qu'un <b>kyste radiculeux</b> (péri-apical) ?","a":"Kyste <b>inflammatoire</b> à l'apex d'une dent à pulpe nécrosée, formé à partir des <b>restes épithéliaux de Malassez</b> du ligament.<br>Radiographie : <b>image radio-claire ronde, bien limitée, cortiquée</b>.<br>Traitement : endodontie + chirurgie (kystectomie/apicectomie) si grande taille.","t":"pathologie"},{"q":"Qu'est-ce que les <b>restes épithéliaux de Malassez</b> ?","a":"Îlots épithéliaux résiduels de la <b>gaine de Hertwig</b> dans le ligament parodontal.<br>→ Peuvent proliférer sous stimulation inflammatoire → <b>kyste radiculeux</b>.<br>→ Peuvent aussi donner des <b>tumeurs odontogènes</b>.","t":"embryologie"},{"q":"Définis : <b>gingivite</b> vs <b>parodontite</b>.","a":"<b>Gingivite</b> : inflammation <b>limitée à la gencive</b>. Rouge, œdémateuse, <b>saigne au sondage</b>. <b>RÉVERSIBLE</b> (détartrage + hygiène). Pas de perte d'attache, pas de perte osseuse.<br><b>Parodontite</b> : destruction du <b>parodonte profond</b> → <b>perte d'attache</b>, <b>poche parodontale</b>, <b>résorption osseuse</b>, mobilité dentaire. <b>IRRÉVERSIBLE</b> (on stabilise, on ne régénère pas).","t":"parodontologie"},{"q":"Quels sont les <b>4 signes cardinaux de la gingivite</b> ?","a":"1. <b>Rougeur</b> (érythème) — la gencive saine est rose pâle<br>2. <b>Œdème</b> — perte du stipulé (aspect peau d'orange)<br>3. <b>Saignement</b> au sondage (⚠️ signe le plus précoce et le plus fiable)<br>4. <b>Augmentation du volume</b> / bourrelet gingival<br>⚠️ La gingivite est <b>indolore</b> → souvent ignorée.","t":"parodontologie"},{"q":"Qu'est-ce que la <b>poche parodontale</b> ?","a":"<b>Sulcus approfondi pathologiquement</b> (> 3 mm) par la <b>migration apicale de l'attache épithéliale</b> + la destruction du ligament et de l'os.<br>→ Se mesure avec la <b>sonde parodontale</b> (sondage).<br>→ Réservoir de bactéries anaérobies, inaccessible au brossage.","t":"parodontologie"},{"q":"Qu'est-ce que le <b>sondage parodontal</b> ? Que mesure-t-on ?","a":"Examen à la <b>sonde parodontale graduée</b> (ex. sonde OMS / CPITN).<br>On mesure sur <b>6 faces par dent</b> :<br>• <b>Profondeur de poche</b> (PP) : bord gingival → fond du sulcus<br>• <b>Perte d'attache</b> (PA / CAL) : JED → fond du sulcus<br>• <b>Saignement au sondage</b><br>• <b>Atteinte des furcations</b>, mobilité","t":"parodontologie"},{"q":"Quelle est la différence entre <b>profondeur de poche</b> et <b>perte d'attache clinique</b> (CAL) ? Pourquoi la CAL est-elle meilleure ?","a":"<b>PP</b> = bord gingival libre → fond du sulcus.<br><b>CAL</b> = jonction émail-dentine → fond du sulcus.<br>⚠️ La <b>CAL</b> est indépendante de la position de la gencive : elle mesure la <b>destruction réelle</b>.<br>(En cas de récession, PP peut être normale alors que CAL est élevée.)","t":"parodontologie"},{"q":"Quelles sont les <b>bactéries clés</b> de la parodontite ? (« complexe rouge » de Socransky)","a":"<b>Complexe rouge</b> (Socransky) — anaérobies Gram négatifs, associés à la parodontite sévère :<br>• <i><b>Porphyromonas gingivalis</b></i><br>• <i><b>Tannerella forsythia</b></i> (Bacteroides forsythus)<br>• <i><b>Treponema denticola</b></i><br>+ <i>Aggregatibacter actinomycetemcomitans</i> → parodontite <b>agressive</b>","t":"microbiologie"},{"q":"Qu'est-ce que la <b>mobilité dentaire</b> ? Grades.","a":"Déplacement pathologique de la dent dans son alvéole.<br><b>Grade 0</b> : physiologique (< 0,2 mm horizontal)<br><b>Grade I</b> : mobilité horizontale <b>&lt; 1 mm</b><br><b>Grade II</b> : mobilité horizontale <b>&gt; 1 mm</b><br><b>Grade III</b> : mobilité horizontale + <b>verticale</b> (signe de pronostic très réservé → extraction)","t":"parodontologie"},{"q":"Qu'est-ce que la <b>récession gingivale</b> ?","a":"<b>Déplacement apical du bord gingival</b> → exposition du <b>cément/racine</b>.<br>Causes : brossage traumatique, parodontite, frein haut inséré, malposition dentaire, orthodontie.<br>Conséquences : <b>hypersensibilité dentinaire</b>, carie radiculaire, préjudice esthétique.","t":"parodontologie"},{"q":"Qu'est-ce que l'<b>hypersensibilité dentinaire</b> ? Mécanisme ?","a":"Douleur <b>brève, vive</b>, déclenchée par le <b>froid, le sucré, le tactile</b>, sur une <b>racine exposée</b>.<br>Mécanisme : <b>théorie hydrodynamique de Brännström</b> — déplacement du liquide dans les <b>tubules dentinaires</b> → stimulation des terminaisons nerveuses pulaires.","t":"semio"},{"q":"Qu'est-ce que le <b>bruxisme</b> ? Conséquences ?","a":"<b>Parafonction</b> : serrement/grincement des dents, souvent <b>nocturne</b> et <b>inconscient</b>.<br>Conséquences : <b>usure (attrition)</b> des faces occlusales, <b>facettes d'usure</b>, fractures d'émail, <b>myalgies</b> masticatrices, douleur ATM, mobilité, <b>hypertrophie du masséter</b>.<br>Traitement : <b>gouttière occlusale</b>, gestion du stress.","t":"occlusodontie"},{"q":"Distingue : <b>attrition</b> · <b>abrasion</b> · <b>érosion</b> · <b>abfraction</b>.","a":"<b>Attrition</b> : usure par <b>contact dent contre dent</b> (bruxisme, mastication) — facettes brillantes<br><b>Abrasion</b> : usure par un <b>corps étranger</b> (brossage trop fort, pipe, ongles) — encoche cervicale en V<br><b>Érosion</b> : perte de substance par <b>acides non bactériens</b> (reflux, vomissements, boissons acides) — lisse, concave<br><b>Abfraction</b> : encoche cervicale par <b>flexion de la dent</b> sous charge occlusale","t":"pathologie"},{"q":"Qu'est-ce que l'<b>émail perlé</b>, le <b>tubercule de Carabelli</b>, la <b>dentine en fuseau</b> ?","a":"Anomalies anatomiques normales :<br><b>Tubercule de Carabelli</b> : cuspide surnuméraire sur la face <b>palatine</b> de la 1ʳᵉ molaire supérieure (5ᵉ cuspide)<br><b>Émail perlé</b> : goutte d'émail sur la <b>racine</b> (souvent au niveau des furcations)<br><b>Furcation</b> : zone de division des racines — site difficile à nettoyer","t":"anatomie"},{"q":"Qu'est-ce qu'une <b>furcation</b> ? Classification de Glickman.","a":"Zone de <b>division des racines</b> d'une dent pluriradiculée.<br><b>Classe I</b> : atteinte initiale, sonde pénètre &lt; 3 mm<br><b>Classe II</b> : atteinte partielle, sonde pénètre mais <b>pas de part en part</b><br><b>Classe III</b> : atteinte <b>de part en part</b>, mais recouverte par la gencive<br><b>Classe IV</b> : atteinte de part en part <b>visible</b> (récession)<br>→ Pronostic de plus en plus réservé.","t":"parodontologie"}]},{"id":"carie","nom":"🕳️ La carie","src":"Cours M115","ordre":12,"module":"M115","desc":"Keyes · bactéries · pH critique · ICDAS","cards":[{"q":"Définis la <b>carie dentaire</b>.","a":"Maladie <b>infectieuse</b>, <b>transmissible</b>, <b>multifactorielle</b> et <b>chronique</b> des tissus durs de la dent.<br>Elle provoque une <b>déminéralisation</b> des tissus (émail, dentine, cément) par les <b>acides</b> produits par les bactéries de la plaque à partir des <b>glucides fermentescibles</b>.<br>→ Destruction progressive, <b>irréversible</b>, qui ne guérit pas spontanément (sauf au stade de lésion initiale).","t":"carie"},{"q":"Pourquoi la carie est-elle dite <b>maladie biofilm-dépendante</b> ?","a":"Parce que la bactérie doit être <b>organisée en biofilm adhérent</b> (plaque dentaire) pour produire un acide <b>concentré et maintenu au contact de l'émail</b>.<br>Des bactéries libres dans la salive ne causent pas de carie.<br>→ Conséquence : le traitement de base est <b>mécanique</b> (brossage), pas antibiotique.","t":"carie"},{"q":"Quelles sont les <b>4 facteurs</b> du schéma de <b>Keyes</b> (1960) ? Le <b>5ᵉ</b> ajouté par Newbrun ?","a":"<b>Keyes (4 facteurs, tous nécessaires)</b> :<br>1. <b>Hôte / terrain</b> (dent, salive)<br>2. <b>Flore bactérienne</b> (biofilm)<br>3. <b>Substrat</b> (glucides fermentescibles)<br>4. <b>Temps</b><br><b>Newbrun ajoute un 5ᵉ</b> : <b>la salive</b> (facteur protecteur majeur).<br>→ Enlever UN seul facteur = <b>pas de carie</b>. C'est la base de la prévention.","t":"carie"},{"q":"Quelles sont les <b>2 bactéries</b> principales de la carie et leurs rôles respectifs ?","a":"<b>1. <i>Streptococcus mutans</i></b> — <b>initiateur</b><br>&nbsp;&nbsp;• Adhère à la pellicule (glucanes via <b>glucosyltransférases</b>)<br>&nbsp;&nbsp;• Produit de l'<b>acide lactique</b> (acidogène)<br>&nbsp;&nbsp;• Survit en milieu acide (acidurique)<br><b>2. <i>Lactobacillus</i></b> — <b>propagateur</b><br>&nbsp;&nbsp;• Intervient <b>tardivement</b>, dans la dentine<br>&nbsp;&nbsp;• Très acidurique, marqueur de <b>risque carieux élevé</b><br>+ <i>Actinomyces</i> → carie <b>radiculaire</b> et lésions initiales","t":"carie"},{"q":"Quels sont les <b>3 sucres</b> les plus cariogènes ? Par ordre décroissant.","a":"<b>1. Saccharose</b> (sucre de table) — <b>le plus cariogène</b>, car sert aussi à fabriquer les <b>glucanes</b> (adhésion de la plaque)<br><b>2. Glucose / fructose</b> (sucres libres, sirops, miel)<br><b>3. Maltose</b><br>⚠️ Moins cariogènes : <b>lactose</b> (lait), <b>xylitol</b> et <b>sorbitol</b> (non cariogènes, voire <b>cariostatiques</b>).","t":"carie"},{"q":"Quel est le <b>pH critique</b> de l'émail ? De la dentine ? Pourquoi ?","a":"<b>Émail : pH 5,5</b><br><b>Dentine / cément : pH 6,0 – 6,2</b> (plus soluble car moins minéralisés)<br>En dessous de ce pH → <b>déminéralisation</b> (dissolution des cristaux d'hydroxyapatite).<br>⚠️ La <b>racine exposée</b> se carie donc <b>plus vite</b> que la couronne.","t":"carie"},{"q":"Qu'est-ce que la <b>courbe de Stephan</b> ?","a":"<b>Chute du pH</b> de la plaque après un apport de sucre :<br>• pH chute en <b>2–5 min</b> jusqu'à <b>4,5</b> (sous le pH critique)<br>• Remonte en <b>20–60 min</b> grâce aux <b>tampons salivaires</b><br>→ Chaque prise alimentaire = un <b>pic acide</b>.<br>⚠️ Ce qui compte, ce n'est pas la <b>quantité</b> de sucre, mais la <b>FRÉQUENCE</b> des prises.","t":"carie"},{"q":"Explique la balance <b>déminéralisation / reminéralisation</b>.","a":"<b>Déminéralisation</b> : pH &lt; 5,5 → sortie de <b>Ca²⁺</b> et <b>PO₄³⁻</b> de l'émail<br><b>Reminéralisation</b> : pH remonte → la salive (saturée en Ca²⁺, PO₄³⁻, <b>F⁻</b>) <b>redépose</b> les minéraux<br>→ La carie apparaît quand les <b>épisodes de déminéralisation</b> l'emportent en <b>fréquence</b> et en <b>durée</b>.<br>→ C'est pourquoi la carie est <b>réversible au stade de lésion initiale</b>.","t":"carie"},{"q":"Qu'est-ce qu'une <b>tache blanche</b> (white spot lesion / lésion carieuse initiale) ?","a":"<b>Premier signe clinique visible</b> de la carie : perte de translucidité de l'émail, aspect <b>blanc crayeux, mat</b>, après séchage à l'air.<br>• Surface <b>intacte</b> (pas de cavitation)<br>• <b>RÉVERSIBLE</b> par reminéralisation (fluor + hygiène + contrôle du sucre)<br>⚠️ Ne <b>pas</b> obturer. Traiter par fluor topique / vernis.","t":"carie"},{"q":"Quels sont les <b>5 stades</b> de progression de la carie (classification anatomique) ?","a":"1. <b>C0 — Lésion initiale</b> : tache blanche, émail seulement, surface intacte → <b>réversible</b><br>2. <b>C1 — Carie de l'émail</b> : cavitation dans l'émail<br>3. <b>C2 — Carie de la dentine</b> : atteint la JED → progression rapide (dentine moins minéralisée)<br>4. <b>C3 — Carie pénétrante</b> : atteint la <b>pulpe</b> → pulpite<br>5. <b>C4 — Carie compliquée</b> : nécrose pulpaire, atteinte <b>péri-apicale</b> (abcès, kyste)","t":"carie"},{"q":"Qu'est-ce que la <b>carie rampante du biberon</b> (syndrome du biberon) ?","a":"Carie <b>aiguë, fulgurante</b> du jeune enfant, causée par l'<b>endormissement au biberon</b> (lait sucré, jus, sirop).<br>Atteinte typique : <b>incisives maxillaires</b> (faces vestibulaires et proximales) — les incisives mandibulaires sont <b>épargnées</b> (protégées par la langue et la salive sublinguale).<br>→ Prévention : pas de biberon au lit, eau seule.","t":"pedodontie"},{"q":"Pourquoi les incisives mandibulaires sont-elles épargnées dans la carie du biberon ?","a":"Parce que pendant la tétée, la <b>langue</b> recouvre les incisives inférieures et la <b>glande sublinguale/submandibulaire</b> y déverse sa salive en continu → effet de <b>lavage et de tamponnement</b>.","t":"pedodontie"},{"q":"Qu'est-ce que la <b>carie radiculaire</b> ? Qui est à risque ?","a":"Carie du <b>cément et de la dentine radiculaire</b>, sur une <b>racine exposée</b> (récession gingivale).<br>• pH critique plus élevé : <b>6,0–6,2</b> → progression <b>plus rapide</b><br>• Aspect : lésion <b>jaunâtre, molle, étalée</b>, peu douloureuse<br>• Population : <b>sujets âgés</b>, parodontites, xérostomie<br>• Bactéries : <i>Actinomyces</i>, <i>Lactobacillus</i>","t":"carie"},{"q":"Quelles sont les <b>4 localisations</b> préférentielles de la carie ? (sites à risque)","a":"1. <b>Fosses et sillons occlusaux</b> (molaires, prémolaires) — 40–50 % des caries, rétention mécanique de la plaque<br>2. <b>Faces proximales</b> (points de contact) — invisibles sans radiographie<br>3. <b>Collet</b> (cervical) — surtout en cas de récession<br>4. <b>Bord des restaurations</b> (carie secondaire / récidivante)","t":"carie"},{"q":"Qu'est-ce que la <b>carie secondaire</b> (récidivante) ?","a":"Nouvelle carie qui se développe <b>au bord d'une restauration existante</b> (obturation, couronne).<br>Causes : <b>margination défectueuse</b>, fente, débord, hygiène insuffisante.<br>→ 1ʳᵉ cause d'<b>échec</b> et de <b>remplacement</b> des obturations.","t":"carie"},{"q":"Quels sont les <b>4 modes de diagnostic</b> de la carie ?","a":"1. <b>Examen visuel</b> (dent sèche + éclairage) — le principal<br>2. <b>Sondage</b> à la sonde — ⚠️ avec prudence sur une lésion initiale (risque de <b>caviter</b> une lésion réversible)<br>3. <b>Radiographie</b> (rétro-alvéolaire / bite-wing) — indispensable pour les faces <b>proximales</b><br>4. <b>Transillumination</b> (fibro-optique) + méthodes modernes (fluorescence, DIAGNOdent, OCT)","t":"diagnostic"},{"q":"Quels sont les <b>4 aspects radiologiques</b> de la carie ?","a":"<b>1. Émail</b> : image radio-claire <b>triangulaire</b>, sommet vers la JED<br><b>2. Dentine</b> : image radio-claire <b>triangulaire inversée</b>, base à la JED, sommet vers la pulpe<br><b>3. Face proximale</b> : <b>bite-wing</b> (rétro-coronaire) = examen de choix<br><b>4. Cément/racine</b> : radio-clair, mal limité<br>⚠️ La carie n'est visible en radio que si la perte minérale dépasse <b>30–40 %</b>.","t":"diagnostic"},{"q":"Qu'est-ce que la classification <b>ICDAS</b> ?","a":"<b>International Caries Detection and Assessment System</b> — classification visuelle standardisée :<br><b>0</b> : sain · <b>1</b> : changement de translucidité <b>visible au séchage</b> seulement · <b>2</b> : changement visible <b>dent humide</b> · <b>3</b> : perte de substance <b>sans atteinte dentinaire visible</b> · <b>4</b> : ombre dentinaire sous-jacente · <b>5</b> : <b>dentine visible</b> · <b>6</b> : dentine <b>franchement exposée</b>","t":"diagnostic"},{"q":"Qu'est-ce que la classification de <b>Black</b> ? (5 classes)","a":"<b>Classe I</b> : fosses et <b>sillons</b> (occlusal des molaires/prémolaires, faces vestib/palat des antérieures)<br><b>Classe II</b> : faces <b>proximales</b> des <b>prémolaires et molaires</br><b>Classe III</b> : faces <b>proximales</b> des <b>incisives/canines</b>, <b>sans</b> atteinte de l'angle incisal<br><b>Classe IV</b> : proximales des incisives/canines <b>avec</b> atteinte de l'angle incisal<br><b>Classe V</b> : <b>collet</b> (1/3 cervical) de toutes les dents<br>(+ Classe VI de Howard : cuspides/bords incisals)","t":"classification"},{"q":"Quels sont les <b>3 grands facteurs de risque</b> carieux modifiables ?","a":"1. <b>Alimentation</b> : fréquence des prises de sucre, grignotage, boissons sucrées/acides<br>2. <b>Hygiène bucco-dentaire</b> : brossage absent/inefficace, plaque non éliminée<br>3. <b>Fluor</b> : exposition insuffisante<br>+ facteurs non modifiables : <b>salive</b> (hyposialie), <b>terrain génétique</b>, maladies générales, médicaments (anticholinergiques).","t":"prevention"},{"q":"Qu'est-ce que l'<b>xérostomie</b> (hyposialie) ? Risque dentaire ?","a":"<b>Sécheresse buccale</b> par diminution du débit salivaire (&lt; 0,1 mL/min au repos).<br>Causes : médicaments (antidépresseurs, antihistaminiques, anticholinergiques), <b>radiothérapie cervico-faciale</b>, <b>syndrome de Gougerot-Sjögren</b>, diabète, âge.<br>⚠️ Conséquence : perte du pouvoir <b>tampon et de reminéralisation</b> → <b>caries cervicales fulgurantes</b> (carie du « irradié »).","t":"pathologie"},{"q":"Quels sont les <b>4 moyens de prévention</b> de la carie ?","a":"1. <b>Contrôle mécanique du biofilm</b> : brossage 2×/jour (Brossette + technique de Bass), fil/ brossettes interdentaires<br>2. <b>Fluor</b> : dentifrice fluoré (1000–1450 ppm), vernis fluoré professionnel, eau fluorée<br>3. <b>Contrôle alimentaire</b> : réduire la <b>fréquence</b> des sucres, pas de grignotage<br>4. <b>Scellement des sillons</b> (molaires permanentes de l'enfant) + détartrage régulier","t":"prevention"},{"q":"Quel est le <b>mécanisme d'action du fluor</b> ? (3 effets)","a":"1. <b>Reminéralisation</b> : le fluor se fixe sur l'hydroxyapatite → <b>fluoroapatite</b>, plus <b>stable</b> et plus résistante aux acides (pH critique abaissé à <b>4,5</b>)<br>2. <b>Action antibactérienne</b> : inhibe l'<b>énolase</b> des bactéries → moins d'acide produit<br>3. <b>Action sur la salive</b> : favorise le dépôt de Ca²⁺ et PO₄³⁻<br>⚠️ Effet principalement <b>topique</b> (post-éruptif), pas systémique.","t":"prevention"},{"q":"Quelles sont les concentrations de fluor recommandées selon l'âge ?","a":"<b>0 – 3 ans</b> : <b>1000 ppm</b>, quantité = <b>grain de riz</b><br><b>3 – 6 ans</b> : <b>1000 ppm</b>, quantité = <b>petit pois</b><br><b>&gt; 6 ans et adultes</b> : <b>1450 ppm</b>, quantité = longueur de la brosse<br>⚠️ Le <b>dentifrice fluoré</b> est le moyen le plus efficace ayant fait baisser la prévalence de la carie dans le monde.","t":"prevention"},{"q":"Qu'est-ce que la <b>fluorose dentaire</b> ?","a":"<b>Intoxication chronique au fluor</b> pendant la <b>formation de l'émail</b> (avant 6 ans).<br>Aspect : <b>taches blanches opaques</b> → stries → coloration <b>brune</b> → dans les formes sévères, <b>hypoplasie</b> et émail friable.<br>Indice : <b>indice TF</b> (Thylstrup-Fejerskov) ou <b>indice de Dean</b>.<br>⚠️ Cause = <b>ingestion</b> (dentifrice avalé, suppléments cumulés, eau fluorée).","t":"prevention"},{"q":"Qu'est-ce que le <b>scellement des sillons</b> ? Indications.","a":"Application d'une <b>résine fluide</b> (ou ionomère de verre) dans les <b>fosses et sillons</b> des dents permanentes pour <b>oblitérer</b> les zones de rétention de plaque.<br><b>Indications</b> : enfant à risque carieux, molaires permanentes récemment éruptées (dans les <b>2 ans</b> suivant l'éruption), sillons profonds et étroits.<br>⚠️ Ne remplace <b>pas</b> le brossage ni le contrôle alimentaire.","t":"pedodontie"},{"q":"Qu'est-ce que la technique de brossage de <b>Bass</b> modifiée ?","a":"Brosse inclinée à <b>45°</b>, poils dirigés vers le <b>sulcus gingival</b>.<br>• Petits mouvements <b>vibratoires</b> sur place (10 fois) puis mouvement de <b>rouleau</b> vers la face occlusale<br>• Brosser <b>par secteur</b>, toutes les faces : vestibulaire, linguale, occlusale<br>• Durée : <b>2 minutes</b>, <b>2 fois par jour</b><br>• Brosse <b>souple</b> pour éviter l'abrasion cervicale","t":"prevention"},{"q":"Qu'est-ce que l'<b>indice CAO</b> (DMFT) ?","a":"<b>Indice épidémiologique</b> de l'OMS pour la carie sur dents permanentes :<br><b>C</b> = Caries (dent cariée non soignée)<br><b>A</b> = Absentes (dent extraite pour cause de carie)<br><b>O</b> = Obturées (dent soignée)<br>→ Somme moyenne par individu. Sur dents temporaires : <b>cao</b> (minuscules).<br>⚠️ Utilisé en <b>santé publique</b> (PSP1) et dans les <b>enquêtes nationales</b>.","t":"sante-publique"},{"q":"Quels sont les <b>3 niveaux de prévention</b> appliqués à la carie ?","a":"<b>Primaire</b> : empêcher la maladie → hygiène, fluor, éducation alimentaire, scellement<br><b>Secondaire</b> : diagnostiquer et traiter tôt → dépistage, obturation, arrêt de la progression<br><b>Tertiaire</b> : réhabiliter → endodontie, prothèse, réhabilitation occlusale","t":"sante-publique"},{"q":"Qu'est-ce que l'<b>effet de plaque</b> / la <b>transmissibilité</b> de la carie ?","a":"La carie est <b>transmissible</b> : <i>S. mutans</i> se transmet par la <b>salive</b> (baiser, partage de cuillère, biberon goûté par la mère, tétine).<br>→ Fenêtre d'infection : entre <b>19 et 31 mois</b> (éruption des molaires de lait).<br>⚠️ Prévention : traiter les caries de la <b>mère</b> avant/pendant la grossesse et la petite enfance.","t":"pedodontie"},{"q":"Qu'est-ce qu'un <b>test de risque carieux</b> ? Que mesure-t-on ?","a":"Évaluation de la probabilité de développer de nouvelles caries.<br>On mesure :<br>• <b>Compte bactérien</b> salivaire en <i>S. mutans</i> et <i>Lactobacillus</i><br>• <b>Débit et pH salivaires</b>, pouvoir tampon<br>• <b>Historique</b> de caries (le meilleur prédicteur)<br>• <b>Hygiène</b> (indice de plaque)<br>• <b>Alimentation</b> (questionnaire de fréquence)<br>→ Détermine l'intensité de la prévention à mettre en place.","t":"diagnostic"},{"q":"Qu'est-ce que la <b>détection précoce</b> de la carie change au traitement ?","a":"Au stade <b>tache blanche</b> : traitement <b>non invasif</b> = reminéralisation (fluor, hygiène, alimentation) → <b>pas de fraise, pas d'obturation</b>.<br>Après <b>cavitation</b> : la lésion est <b>irréversible</b> → traitement <b>opératoire</b> obligatoire.<br>→ C'est le concept de <b>CAMBRA</b> et de la <b>dentisterie minimalement invasive</b>.","t":"carie"},{"q":"Qu'est-ce que le <b>principe de l'extension pour prévention</b> de Black ? Pourquoi est-il abandonné ?","a":"<b>Black (XIXᵉ s.)</b> : élargir la cavité jusqu'aux <b>zones auto-nettoyantes</b> pour prévenir la récidive.<br>⚠️ <b>Abandonné</b> car il sacrifiait trop de tissu dentaire sain.<br>→ Aujourd'hui : <b>dentisterie minimalement invasive</b> — on retire uniquement le tissu <b>infecté</b> (cimentaire/dentinaire ramolli), on préserve le tissu <b>affecté</b> (reminéralisable), on <b>scelle</b> les sillons à risque.","t":"odontologie-conservatrice"},{"q":"Distingue la dentine <b>affectée</b> de la dentine <b>infectée</b>.","a":"<b>Dentine infectée</b> : envahie par les bactéries, <b>ramollie</b>, structure détruite, <b>non reminéralisable</b> → <b>à éliminer</b>.<br><b>Dentine affectée</b> : déminéralisée mais <b>stérile</b>, structure de collagène <b>intacte</b>, peut se <b>reminéraliser</b> → <b>à préserver</b>.<br>→ Test clinique : la dentine infectée se laisse <b>creuser à l'excavateur</b> sans résistance.","t":"odontologie-conservatrice"},{"q":"Qu'est-ce que la <b>pulpite</b> carieuse ? Évolution si non traitée.","a":"Inflammation de la pulpe secondaire à la pénétration bactérienne.<br><b>Réversible</b> → douleur provoquée brève → <b>obturation</b><br><b>Irréversible</b> → douleur spontanée, pulsatile, nocturne → <b>traitement endodontique</b><br>→ Non traitée : <b>nécrose pulpaire</b> → <b>desmodontite</b> → <b>abcès péri-apical</b> → <b>cellulite</b> → <b>septicémie</b> (rare).","t":"endodontie"}]}];
